pub const AppliedMetadataCheckpoint = apply_contract.AppliedMetadataCheckpoint;
/// Cleanup may outlive the apply lock after successful commit. Release this
/// registration before unlock so deferred cleanup cannot clear a later owner.
const ApplyOutcomeGuard = struct {
    slot: *?*CommittedApplyOutcome,
    outcome: *CommittedApplyOutcome,
    owned: bool = true,
    fn init(slot: *?*CommittedApplyOutcome, outcome: *CommittedApplyOutcome) ApplyOutcomeGuard {
        std.debug.assert(slot.* == null);
        slot.* = outcome;
        return .{ .slot = slot, .outcome = outcome };
    }
    fn release(self: *@This()) void {
        std.debug.assert(self.owned and self.slot.* == self.outcome);
        self.slot.* = null;
        self.owned = false;
    }
    fn deinit(self: *@This()) void {
        if (self.owned) self.release();
    }
};

test "system catalog relation namespace transaction outcome cleanup cannot clear the next apply owner" {
    var first: CommittedApplyOutcome = .{ .alloc = std.testing.allocator };
    defer first.deinit();
    var next: CommittedApplyOutcome = .{ .alloc = std.testing.allocator };
    defer next.deinit();
    var slot: ?*CommittedApplyOutcome = null;
    var completed = ApplyOutcomeGuard.init(&slot, &first);
    completed.release(); // successful commit, before unlocking
    var subsequent = ApplyOutcomeGuard.init(&slot, &next); // next lock owner
    completed.deinit(); // old frame's deferred cleanup, after unlocking
    try std.testing.expectEqual(&next, slot.?);
    subsequent.deinit(); // failure/early-return path, still owning the lock
    try std.testing.expect(slot == null);
}

test "system catalog relation namespace transaction classifies only canonical affected table keys" {
    const prefix = "\x00\x00__metadata__:system_catalog:41:record:table:";
    for ([_][]const u8{ "", "0", "01", "+1", "-1", "1:extra", "18446744073709551616" }) |suffix| {
        const key = try std.fmt.allocPrint(std.testing.allocator, "{s}{s}", .{ prefix, suffix });
        defer std.testing.allocator.free(key);
        try std.testing.expectError(error.InvalidCatalogRecord, system_catalog_storage.tableIdFromRecordKey(key, 41));
    }
    try std.testing.expectEqual(@as(?u64, 7), try RaftApplyStore.capturedRelationTableId(prefix ++ "7", 41));
    try std.testing.expectEqual(@as(?u64, 7), try RaftApplyStore.capturedRelationTableId("\x00\x00__metadata__:metadata_table:41:7", 41));
    try std.testing.expectEqual(@as(?u64, null), try RaftApplyStore.capturedRelationTableId(prefix ++ "7", 42));
    try std.testing.expectEqual(@as(?u64, null), try RaftApplyStore.capturedRelationTableId("\x00\x00__metadata__:system_catalog:41:record:namespace:7", 41));
    try std.testing.expectEqual(@as(?u64, std.math.maxInt(u64)), try system_catalog_storage.tableIdFromRecordKey(prefix ++ "18446744073709551615", 41));
}

/// Fixtures explicitly model the already capability-fenced bootstrap. This is
/// not an automatic migration or a production writer-adoption entry point.
fn adoptRelationWriterForTest(store: *RaftApplyStore, a: std.mem.Allocator, group: u64) !void {
    var txn = try store.store.beginWriteTxn();
    errdefer txn.abort();
    var cursor = try txn.openCursor();
    var cursor_open = true;
    defer if (cursor_open) cursor.close();
    var buf: [160]u8 = undefined;
    const prefix = try tablePrefixForGroup(&buf, group);
    var table_ids: std.ArrayList(u64) = .empty;
    defer table_ids.deinit(a);
    var row = try cursor.seekAtOrAfter(prefix);
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, prefix)) break;
        const id = (try RaftApplyStore.capturedRelationTableId(item.key, group)).?;
        try table_ids.append(a, id);
    }
    // Registry writes can replace the transaction's memtable sources. Finish
    // traversal before mutating them, retaining only owned table identifiers.
    cursor.close();
    cursor_open = false;
    for (table_ids.items) |id| {
        var cut = try RaftApplyStore.relationWriterSnapshot(a, &txn, group, id, true);
        defer cut.deinit();
        var plan = try relation_names.Plan.init(a, &.{}, cut.claims());
        defer plan.deinit();
        var registry: relation_names.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .alloc = a, .group_id = group };
        try plan.apply(&registry);
    }
    try txn.put(try RaftApplyStore.relationWriterKeyForGroup(&buf, group), "AFRW01");
    try verifyRelationCheckpointTxn(a, &txn);
    try txn.commit();
}

fn verifyRelationRecoveryForTest(store: *RaftApplyStore, a: std.mem.Allocator, group: u64) !void {
    const snapshot = try store.snapshotBuilder().buildSnapshot(a, group);
    defer a.free(snapshot);
    const rows = try decodeMetadataSnapshotAlloc(a, snapshot);
    defer freeMetadataSnapshotRows(a, rows);
    try validateMetadataSnapshotRows(a, group, rows);
    var read = try store.store.beginReadTxn();
    defer read.abort();
    try verifyRelationCheckpointTxn(a, &read);
}

/// Test bootstrap supplies the capability/lifecycle barrier externally, but
/// obtains the actual native source/candidate proof before installing a root.
fn adoptLiveRelationWriterForTest(store: *RaftApplyStore, a: std.mem.Allocator, group: u64) !relation_reconciliation.State {
    try adoptRelationWriterForTest(store, a, group);
    return publishLiveRelationRootForTest(store, a, group);
}

fn publishLiveRelationRootForTest(store: *RaftApplyStore, a: std.mem.Allocator, group: u64) !relation_reconciliation.State {
    return publishLiveRelationRootWithCoverageForTest(store, a, group, .relations);
}
fn publishLiveRelationRootWithCoverageForTest(store: *RaftApplyStore, a: std.mem.Allocator, group: u64, coverage: relation_reconciliation.Coverage) !relation_reconciliation.State {
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        if (!try RaftApplyStore.relationWriterEnabledTxn(&txn, group)) return error.InvalidCatalogRecord;
        if (try relation_reconciliation.readSourceRevision(&txn, group) == 0) try relation_reconciliation.advanceSource(&txn, group);
        try txn.commit();
    }
    const epoch = blk: {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        break :blk try RaftApplyStore.relationSourceEpochTxn(&read, group);
    };
    const initial = try relation_reconciliation.State.initWithCoverage(group, try relation_reconciliation.nextJobId(null), epoch, coverage);
    const ready = try reconcileRestoreNamesForTest(store, a, initial);
    const proof = try store.prepareRelationPublicationProof(a, ready);
    var txn = try store.store.beginWriteTxn();
    errdefer txn.abort();
    try std.testing.expect(try proof.matchesTxn(&txn));
    _ = try relation_reconciliation.publishVerifiedRoot(&txn, ready, epoch, null);
    try verifyRelationCheckpointTxn(a, &txn);
    try txn.commit();
    return ready;
}

test "system catalog relation namespace transaction occupancy adoption rejects lower durable capability without effects" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/occupancy-adoption", .{tmp.sub_path});
    defer a.free(path);
    var store = try RaftApplyStore.init(a, .{ .root_dir = path });
    defer store.deinit();
    const identity = "11111111111111111111111111111111".*;
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = identity });
    var proof: topology_protocol.Activation = .{ .version = topology_protocol.relation_mutation_version, .incarnation = identity, .member_count = 3, .membership_fingerprint = @splat(7) };
    const activated = try std.json.Stringify.valueAlloc(a, proof, .{});
    defer a.free(activated);
    try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activated });
    proof.version = topology_protocol.constraint_occupancy_version;
    const adopt = try (relation_control.Command{ .adopt = proof }).encodeAlloc(a);
    defer a.free(adopt);
    const revision = try store.standaloneRevision();
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(group, .{ .apply_relation_reconciliation = adopt }));
    try std.testing.expectEqual(revision, try store.standaloneRevision());
    {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        try std.testing.expectEqual(@as(u64, 0), try relation_reconciliation.readSourceRevision(&read, group));
    }
    proof.version = topology_protocol.relation_reconciliation_version;
    const legacy = try (relation_control.Command{ .adopt = proof }).encodeAlloc(a);
    defer a.free(legacy);
    try store.applyStandaloneCommand(group, .{ .apply_relation_reconciliation = legacy });
    const observed = try store.relationReconciliationWork(group);
    try std.testing.expectEqual(@as(u64, 1), observed.epoch.?.revision);
    const next = try relation_reconciliation.State.initWithCoverage(group, try relation_reconciliation.nextJobId(null), observed.epoch.?, .constraint_names);
    const start = try (relation_control.Command{ .start = .{ .next = next } }).encodeAlloc(a);
    defer a.free(start);
    const prior_revision = try store.standaloneRevision();
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(group, .{ .apply_relation_reconciliation = start }));
    try std.testing.expectEqual(prior_revision, try store.standaloneRevision());
    try std.testing.expect(std.meta.eql(observed, try store.relationReconciliationWork(group)));
    const meta = try store.systemCatalogMeta(a, group);
    const named: SystemCatalogCommand = .{
        .version = 2,
        .expected_revision = meta.revision,
        .mutation = .{ .action = .create, .kind = .table, .name = "t", .table_id = 7, .storage_name = "table:7" },
        .topology = .{ .create = .{ .expected_transition_generation = 0, .table = .{ .table_id = 7, .name = "table:7", .schema_json = "{}" }, .ranges = &.{} } },
        .constraint_name_admission = .{ .namespace_id = system_catalog.default_namespace_id, .names = &.{.{ .name = "t_pkey", .kind = .primary }} },
    };
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.prepareSystemCatalogResult(a, group, named));
    const named_bytes = try std.json.Stringify.valueAlloc(a, named, .{});
    defer a.free(named_bytes);
    try store.applyStandaloneCommand(group, .{ .apply_system_catalog = named_bytes });
    try std.testing.expect(std.meta.eql(meta, try store.systemCatalogMeta(a, group)));
    try std.testing.expect(std.meta.eql(observed, try store.relationReconciliationWork(group)));
}

test "system catalog relation namespace transaction legacy request and command wire omit future naming fields" {
    const a = std.testing.allocator;
    const request: system_catalog.Request = .{ .mutation = .{ .action = .create, .kind = .database, .name = "legacy" } };
    const actual_request = try std.json.Stringify.valueAlloc(a, request, .{});
    defer a.free(actual_request);
    const old_request = try std.json.Stringify.valueAlloc(a, .{ .mutation = request.mutation, .create_table_json = request.create_table_json, .physical_name = request.physical_name }, .{});
    defer a.free(old_request);
    try std.testing.expectEqualStrings(old_request, actual_request);
    const command: SystemCatalogCommand = .{ .expected_revision = 0, .mutation = request.mutation };
    const actual_command = try std.json.Stringify.valueAlloc(a, command, .{});
    defer a.free(actual_command);
    const old_command = try std.json.Stringify.valueAlloc(a, .{ .version = command.version, .expected_revision = command.expected_revision, .mutation = command.mutation, .topology = command.topology, .placement_update = command.placement_update }, .{});
    defer a.free(old_command);
    try std.testing.expectEqualStrings(old_command, actual_command);
}

test "system catalog relation namespace transaction occupancy follows native writes checkpoint and restart" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    const T = struct {
        fn verify(store: *RaftApplyStore) !void {
            try verifyRelationRecoveryForTest(store, std.testing.allocator, 41);
            var read = try store.store.beginReadTxn();
            defer read.abort();
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, 41)).?;
            try std.testing.expectEqual(relation_reconciliation.Coverage.constraint_names, live.root.coverage);
            try std.testing.expectEqual(@as(u64, 5), live.root.claims);
            const ns = system_catalog.default_namespace_id;
            try std.testing.expect((try live.getEntry(.{ .namespace_id = ns, .name = "shared", .membership_table_id = 7 })) == null);
            try std.testing.expectEqual(@as(u32, 2), (try live.getClaim(.{ .namespace_id = ns, .name = "new_check", .membership_table_id = 7 })).?.schema_version);
            try std.testing.expectEqual(@as(u32, 1), (try live.getClaim(.{ .namespace_id = ns, .name = "shared", .membership_table_id = 8 })).?.schema_version);
            try std.testing.expectEqual(@as(u64, 9), (try live.getClaim(.{ .namespace_id = ns, .name = "shared" })).?.table_id);
        }
    };
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/constraint-occupancy", .{tmp.sub_path});
    defer a.free(path);
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
        const schema = "{\"version\":1,\"checks\":[{\"name\":\"shared\"}]}";
        try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "items", .schema_json = schema } });
        try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "other", .schema_json = schema } });
        try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 9, .name = "shared", .schema_json = "{\"version\":1}" } });
        // This lower-level fixture supplies adoption barriers externally;
        // production advertising remains disabled until all-voter activation.
        try adoptRelationWriterForTest(&store, a, group);
        _ = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
        try verifyRelationRecoveryForTest(&store, a, group);
        try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "items", .schema_json = "{\"version\":2,\"checks\":[{\"name\":\"new_check\"}]}" } });
        try T.verify(&store);
    }
    {
        var reopened = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer reopened.deinit();
        try T.verify(&reopened);
    }
}

test "system catalog relation namespace transaction prepared names pin native coverage and observe later conflicts" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/prepared-names", .{tmp.sub_path});
    defer a.free(path);
    var store = try RaftApplyStore.init(a, .{ .root_dir = path });
    defer store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    const schema = "{\"checks\":[{\"name\":\"anonymous\",\"expression\":{\"op\":\"column\",\"column\":\"id\"}}]}";
    const initial_meta = try store.systemCatalogMeta(a, group);
    try std.testing.expectError(error.CatalogOccupancyNotReady, store.prepareGeneratedConstraintNames(a, group, initial_meta.revision, system_catalog.default_namespace_id, "t", schema, &.{"anonymous"}, .{}));
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "t_id_check", .schema_json = "{\"version\":1}" } });
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "holder", .schema_json = "{\"version\":1}" } });
    try adoptRelationWriterForTest(&store, a, group);
    _ = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
    const meta = try store.systemCatalogMeta(a, group);
    var selected = try store.prepareGeneratedConstraintNames(a, group, meta.revision, system_catalog.default_namespace_id, "t", schema, &.{"anonymous"}, .{});
    defer selected.deinit();
    try std.testing.expectEqualStrings("t_id_check", selected.admission.names[0].name);
    try selected.admission.validateSchema(a, selected.schema_json);
    const explicit_collision = "{\"checks\":[{\"name\":\"anonymous\",\"expression\":{\"op\":\"column\",\"column\":\"email\"}}],\"unique_constraints\":[{\"name\":\"t_id_check\",\"columns\":[\"id\"]}]}";
    try std.testing.expectError(error.SqlIndexAlreadyExists, store.prepareGeneratedConstraintNames(a, group, meta.revision, system_catalog.default_namespace_id, "t", explicit_collision, &.{"anonymous"}, .{}));
    try std.testing.expectError(error.CatalogGenerationChanged, store.prepareGeneratedConstraintNames(a, group, meta.revision + 1, system_catalog.default_namespace_id, "t", schema, &.{"anonymous"}, .{}));
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "holder", .schema_json = "{\"version\":2,\"checks\":[{\"name\":\"t_id_check\"},{\"name\":\"only_member\"}]}" } });
    // Schema-only changes need not advance the ordinary catalog revision.
    // A selected-name predicate must use the current native root at commit.
    try std.testing.expectEqual(meta.revision, (try store.systemCatalogMeta(a, group)).revision);
    var read = try store.store.beginReadTxn();
    defer read.abort();
    var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
    try std.testing.expect(try live.nameOccupied(system_catalog.default_namespace_id, selected.admission.names[0].name, false));
    var retried = try store.prepareGeneratedConstraintNames(a, group, meta.revision, system_catalog.default_namespace_id, "t", schema, &.{"anonymous"}, .{});
    defer retried.deinit();
    try std.testing.expectEqualStrings("t_id_check1", retried.admission.names[0].name);
    const allowed_explicit = "{\"checks\":[{\"name\":\"anonymous\",\"expression\":{\"op\":\"column\",\"column\":\"email\"}}],\"unique_constraints\":[{\"name\":\"only_member\",\"columns\":[\"id\"]}]}";
    var explicit = try store.prepareGeneratedConstraintNames(a, group, meta.revision, system_catalog.default_namespace_id, "t", allowed_explicit, &.{"anonymous"}, .{});
    defer explicit.deinit();
}

test "system catalog relation namespace transaction ALTER naming pins exact table owner and current occupancy" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/prepared-alter", .{tmp.sub_path});
    defer a.free(path);
    var store = try RaftApplyStore.init(a, .{ .root_dir = path });
    defer store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    const base = "{\"version\":1,\"checks\":[{\"name\":\"items_id_check\"}],\"relational_indexes\":[{\"name\":\"own_idx\"}]}";
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "items", .schema_json = base } });
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "holder", .schema_json = "{\"version\":1,\"checks\":[{\"name\":\"items_id_check1\"}]}" } });
    try adoptRelationWriterForTest(&store, a, group);
    _ = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
    var guard: system_catalog.RelationMutationGuard = undefined;
    {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
        guard = .{ .target = .{ .name = "items" }, .logical_table = "items", .owner = (try live.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "items" })).?, .incarnation = live.root.epoch.incarnation };
    }
    const fragment = "{\"checks\":[{\"name\":\"anonymous\",\"expression\":{\"op\":\"column\",\"column\":\"id\"}}]}";
    var plan = try store.prepareGeneratedConstraintAddition(a, group, guard, fragment, &.{"anonymous"}, .{});
    defer plan.deinit();
    try std.testing.expectEqualStrings("items_id_check2", plan.admission.names[0].name);
    try plan.admission.validateSchema(a, plan.schema_json);
    var named_guard = guard;
    named_guard.constraint_name_admission = plan.admission;
    const expected: metadata.TableRecord = .{ .table_id = 7, .name = "items", .schema_json = base };
    var replacement = expected;
    replacement.schema_json = plan.schema_json;
    const command: TransitionCommand = .{ .compare_and_replace_table = .{ .expected = expected, .replacement = replacement, .relation_guard = named_guard } };
    const encoded = try encodeTransitionCommand(a, command);
    defer a.free(encoded);
    var decoded = (try decodeTransitionCommand(a, encoded)).?;
    defer decoded.deinit(a);
    try std.testing.expectEqualStrings("items_id_check2", decoded.compare_and_replace_table.relation_guard.?.constraint_name_admission.?.names[0].name);
    const canonical = try encodeTransitionCommand(a, decoded);
    defer a.free(canonical);
    try std.testing.expectEqualSlices(u8, encoded, canonical);
    const before = try store.standaloneRevision();
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(group, decoded));
    try std.testing.expectEqual(before, try store.standaloneRevision());
    var wrong_kind = guard;
    wrong_kind.owner.kind = .index;
    try std.testing.expectError(error.SqlWrongObjectType, store.prepareGeneratedConstraintAddition(a, group, wrong_kind, fragment, &.{"anonymous"}, .{}));
    var wrong_incarnation = guard;
    wrong_incarnation.incarnation[0] ^= 1;
    try std.testing.expectError(error.CatalogGenerationChanged, store.prepareGeneratedConstraintAddition(a, group, wrong_incarnation, fragment, &.{"anonymous"}, .{}));
    // Unrelated owners may change: use their current occupancy, without a
    // global captured-source-epoch CAS that would spuriously reject ALTER.
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "holder", .schema_json = "{\"version\":2,\"checks\":[{\"name\":\"items_id_check2\"}]}" } });
    var refreshed = try store.prepareGeneratedConstraintAddition(a, group, guard, fragment, &.{"anonymous"}, .{});
    defer refreshed.deinit();
    try std.testing.expectEqualStrings("items_id_check1", refreshed.admission.names[0].name);
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "items", .schema_json = "{\"version\":2,\"checks\":[{\"name\":\"items_id_check9\"}]}" } });
    try std.testing.expectError(error.CatalogGenerationChanged, store.prepareGeneratedConstraintAddition(a, group, guard, fragment, &.{"anonymous"}, .{}));
    var latest = guard;
    {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
        latest.owner = (try live.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "items" })).?;
    }
    // Physical substitution bypasses the tracked writer deliberately. A
    // syntactically valid row must not become a baseline for the pinned owner.
    const corrupt = try encodeTableRecord(a, .{ .table_id = 7, .name = "items", .schema_json = "{\"version\":2,\"checks\":[{\"name\":\"substituted\"}]}" });
    defer a.free(corrupt);
    {
        var write = try store.store.beginWriteTxn();
        errdefer write.abort();
        var key_buf: [160]u8 = undefined;
        try write.put(try tableKeyForGroup(&key_buf, group, 7), corrupt);
        try write.commit();
    }
    try std.testing.expectError(error.InvalidCatalogRecord, store.prepareGeneratedConstraintAddition(a, group, latest, fragment, &.{"anonymous"}, .{}));
}

test "system catalog relation namespace transaction generated addition races publish and recover under activated occupancy" {
    const T = struct {
        fn successorSchema(alloc: std.mem.Allocator, bytes: []const u8) ![]u8 {
            var parsed = try std.json.parseFromSlice(std.json.Value, alloc, bytes, .{});
            defer parsed.deinit();
            parsed.value.object.getPtr("version").?.* = .{ .integer = 2 };
            return std.json.Stringify.valueAlloc(alloc, parsed.value, .{});
        }
    };
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/activated-names", .{tmp.sub_path});
    defer a.free(path);
    const identity = "01010101010101010101010101010101".*;
    const base =
        \\{"version":1,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"x":{"type":"integer","nullable":false}},"required":["x"],"additionalProperties":false}}}}
    ;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "items", .schema_json = base };
    var committed: ?[]u8 = null;
    defer if (committed) |bytes| a.free(bytes);
    var delayed: ?[]u8 = null;
    defer if (delayed) |bytes| a.free(bytes);
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = identity });
        try store.applyStandaloneCommand(group, .{ .upsert_table = table });
        const activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{ .version = topology_protocol.constraint_occupancy_version, .incarnation = identity, .member_count = 3, .membership_fingerprint = @splat(7) }, .{});
        defer a.free(activation);
        try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
        try std.testing.expectEqual(topology_protocol.constraint_occupancy_version, (try store.topologyActivation(group)).?.version);
        try adoptRelationWriterForTest(&store, a, group);
        const published = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
        var guard: system_catalog.RelationMutationGuard = undefined;
        {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
            guard = .{ .target = .{ .name = table.name }, .logical_table = table.name, .owner = (try live.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = table.name })).?, .incarnation = published.epoch.incarnation };
        }
        const fragment = "{\"unique_constraints\":[{\"name\":\"anonymous\",\"columns\":[\"x\"]}]}";
        var first = try store.prepareGeneratedConstraintAddition(a, group, guard, fragment, &.{"anonymous"}, .{});
        defer first.deinit();
        try std.testing.expectEqualStrings("items_x_key", first.admission.names[0].name);
        var named_guard = guard;
        named_guard.constraint_name_admission = first.admission;
        var replacement = table;
        const first_schema = try T.successorSchema(a, first.schema_json);
        defer a.free(first_schema);
        replacement.schema_json = first_schema;
        // An unrelated owner claims the prepared name after preparation.
        // Exact predecessor identity still matches; only occupancy defeats it.
        try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "items_x_key", .schema_json = "{\"version\":1}" } });
        const observed = try store.relationReconciliationWork(group);
        try std.testing.expectError(error.CatalogGenerationChanged, store.checkConstraintNamesWithContext(a, group, .{ .guard = named_guard, .schema_json = replacement.schema_json }, .{}));
        const rejected = try encodeTransitionCommand(a, .{ .compare_and_replace_table = .{ .expected = table, .replacement = replacement, .relation_guard = named_guard } });
        defer a.free(rejected);
        delayed = try a.dupe(u8, rejected);
        var replay = try MetadataReplayTest.apply(&store, group, &.{.{ .term = 1, .index = 1, .data = rejected }});
        defer replay.deinit();
        try std.testing.expect(std.meta.eql(observed, try store.relationReconciliationWork(group)));
        const unchanged = (try store.getTable(a, group, 7)).?;
        defer metadata_table_manager.freeTable(a, unchanged);
        try std.testing.expectEqualDeep(table, unchanged);
        // Explicit re-preparation, not transparent replay, chooses a suffix.
        var next = try store.prepareGeneratedConstraintAddition(a, group, guard, fragment, &.{"anonymous"}, .{});
        defer next.deinit();
        try std.testing.expectEqualStrings("items_x_key1", next.admission.names[0].name);
        named_guard.constraint_name_admission = next.admission;
        const next_schema = try T.successorSchema(a, next.schema_json);
        defer a.free(next_schema);
        replacement.schema_json = next_schema;
        try store.checkConstraintNamesWithContext(a, group, .{ .guard = named_guard, .schema_json = replacement.schema_json }, .{});
        try store.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = table, .replacement = replacement, .relation_guard = named_guard } });
        const actual = (try store.getTable(a, group, 7)).?;
        defer metadata_table_manager.freeTable(a, actual);
        try std.testing.expectEqualStrings(next_schema, actual.schema_json);
        committed = try a.dupe(u8, actual.schema_json);
        try verifyRelationRecoveryForTest(&store, a, group);
    }
    {
        var reopened = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer reopened.deinit();
        try verifyRelationRecoveryForTest(&reopened, a, group);
        const before = try reopened.relationReconciliationWork(group);
        var replay = try MetadataReplayTest.apply(&reopened, group, &.{.{ .term = 2, .index = 2, .data = delayed.? }});
        defer replay.deinit();
        try std.testing.expect(std.meta.eql(before, try reopened.relationReconciliationWork(group)));
        try std.testing.expectEqual(@as(u64, 2), try reopened.durableAppliedIndex(group));
        const actual = (try reopened.getTable(a, group, 7)).?;
        defer metadata_table_manager.freeTable(a, actual);
        try std.testing.expectEqualStrings(committed.?, actual.schema_json);
        try std.testing.expectEqual(topology_protocol.constraint_occupancy_version, (try reopened.topologyActivation(group)).?.version);
    }
}

test "system catalog relation namespace transaction hidden FK legacy plan digests retain their wire shape" {
    const a = std.testing.allocator;
    const plan: fk_generation_publication.InitialCreatePlan = .{
        .id = @splat(1),
        .retirement_scope = .local_owner,
        .catalog_id = 3,
        .expected_catalog_revision = 0,
        .child = .{ .table_id = 7, .name = "table:3", .schema_json = "{}" },
        .child_ranges = &.{},
        .parents = &.{},
        .logical_name = "t",
        .namespace_id = system_catalog.default_namespace_id,
    };
    const legacy = .{
        .id = plan.id,
        .retirement_scope = plan.retirement_scope,
        .catalog_id = plan.catalog_id,
        .expected_catalog_revision = plan.expected_catalog_revision,
        .tablespace_id = plan.tablespace_id,
        .min_ranges_explicit = plan.min_ranges_explicit,
        .child = plan.child,
        .child_ranges = plan.child_ranges,
        .parents = plan.parents,
        .support_pending = plan.support_pending,
        .self_transitions = plan.self_transitions,
        .logical_name = plan.logical_name,
        .namespace_id = plan.namespace_id,
    };
    const old_bytes = try std.json.Stringify.valueAlloc(a, legacy, .{});
    defer a.free(old_bytes);
    const new_bytes = try std.json.Stringify.valueAlloc(a, plan, .{});
    defer a.free(new_bytes);
    try std.testing.expectEqualStrings(old_bytes, new_bytes);
    var named = plan;
    named.constraint_name_admission = .{ .namespace_id = plan.namespace_id, .names = &.{.{ .name = "t_id_fkey", .kind = .foreign_key }} };
    const named_bytes = try std.json.Stringify.valueAlloc(a, named, .{});
    defer a.free(named_bytes);
    try std.testing.expect(std.mem.indexOf(u8, named_bytes, "constraint_name_admission") != null);
    var decoded = try std.json.parseFromSlice(fk_generation_publication.InitialCreatePlan, a, named_bytes, .{});
    defer decoded.deinit();
    try std.testing.expectEqualStrings("t_id_fkey", decoded.value.constraint_name_admission.?.names[0].name);
}

test "system catalog relation namespace transaction hidden FK prepares names before fingerprinting" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/prepared-fk-names", .{tmp.sub_path});
    defer a.free(path);
    var store = try RaftApplyStore.init(a, .{ .root_dir = path });
    defer store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    const request: fk_generation_publication.InitialCreatePrepareRequest = .{
        .namespace_id = system_catalog.default_namespace_id,
        .logical_name = "t",
        .candidate = .{ .table_id = 0, .name = "", .schema_json = "{\"checks\":[{\"name\":\"anonymous_check\",\"expression\":{\"op\":\"column\",\"column\":\"id\"}}],\"foreign_keys\":[{\"name\":\"anonymous_fk\",\"child_columns\":[\"id\"],\"parent_table\":\"parent\",\"parent_columns\":[\"id\"]}]}" },
        .generated_constraint_names = &.{ "anonymous_check", "anonymous_fk" },
    };
    try std.testing.expectError(error.CatalogOccupancyNotReady, store.fkInitialCreatePrepareJson(a, group, request));
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "t_id_check", .schema_json = "{\"version\":1}" } });
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "holder", .schema_json = "{\"version\":1,\"checks\":[{\"name\":\"t_id_fkey\"}]}" } });
    try adoptRelationWriterForTest(&store, a, group);
    _ = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
    const before = try store.systemCatalogMeta(a, group);
    const bytes = try store.fkInitialCreatePrepareJson(a, group, request);
    defer a.free(bytes);
    var prepared = try std.json.parseFromSlice(fk_generation_publication.InitialCreatePrepare, a, bytes, .{});
    defer prepared.deinit();
    const admission = prepared.value.constraint_name_admission.?;
    try std.testing.expectEqualStrings("t_id_check", admission.names[0].name);
    try std.testing.expectEqualStrings("t_id_fkey1", admission.names[1].name);
    try admission.validateSchema(a, prepared.value.child.schema_json);
    try std.testing.expectEqual(before.revision, prepared.value.expected_catalog_revision);
    try std.testing.expectEqual(before.revision, (try store.systemCatalogMeta(a, group)).revision);
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        try store.validateConstraintNameOccupancyTxn(a, &txn, group, admission, request.namespace_id, prepared.value.child.schema_json);
        try std.testing.expectError(error.InvalidCatalogRecord, store.validateConstraintNameOccupancyTxn(a, &txn, group, admission, request.namespace_id + 1, prepared.value.child.schema_json));
    }
    // A schema-only competing writer can claim the chosen name without
    // changing catalog revision. The frozen predicate must still lose.
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "holder", .schema_json = "{\"version\":2,\"checks\":[{\"name\":\"t_id_fkey\"},{\"name\":\"t_id_fkey1\"}]}" } });
    try std.testing.expectEqual(before.revision, (try store.systemCatalogMeta(a, group)).revision);
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    try std.testing.expectError(error.CatalogGenerationChanged, store.validateConstraintNameOccupancyTxn(a, &txn, group, admission, request.namespace_id, prepared.value.child.schema_json));
}

test "system catalog relation namespace transaction bulk resolution requires a live root and follows schema ownership" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/relation-resolution", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();

    const description: [256 * 1024]u8 = @splat('x');
    var table: metadata.TableRecord = .{ .table_id = 7, .name = "items", .description = &description, .schema_json = "{\"version\":1,\"relational_indexes\":[{\"name\":\"old_idx\"}],\"checks\":[{\"name\":\"new_idx\"}]}" };
    // Hosted name allocation requires a durable Raft cursor for its source
    // cut. Exercise production apply rather than a standalone-only fixture.
    const initialize = try encodeTransitionCommand(a, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    defer a.free(initialize);
    const upsert = try encodeTransitionCommand(a, .{ .upsert_table = table });
    defer a.free(upsert);
    const entries = try raft_state_machine.encodeCommittedEntries(a, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = initialize },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = upsert },
    });
    defer a.free(entries);
    try store.snapshotBuilder().applyBatch(.{ .group_id = group, .commit_index = 2, .entries_bytes = entries });
    const targets = [_]system_catalog.RelationTarget{ .{ .name = "items" }, .{ .name = "old_idx" }, .{ .name = "new_idx" }, .{ .namespace = "missing", .name = "old_idx" } };
    try std.testing.expectError(error.CatalogPublicationProofPending, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets }));
    var allocation_epoch: relation_reconciliation.Epoch = undefined;
    {
        const allocation: system_catalog.ResolveMany = .{ .relations = &targets, .name_allocation = true };
        const names = try store.resolveSystemCatalogIdentities(a, group, allocation);
        defer names.deinit(a);
        try names.validateRelations(allocation);
        allocation_epoch = names.relation_epoch.?;
        try std.testing.expectError(error.DeadlineExceeded, store.resolveSystemCatalogIdentitiesWithContext(a, group, allocation, .{ .deadline_ns = platform_time.monotonicNs() -| 1 }));
        try std.testing.expect(names.relation_names_only);
        try std.testing.expectEqual(relation_names.Kind.table, names.relations[0].?.owner.kind);
        try std.testing.expectEqual(relation_names.Kind.index, names.relations[1].?.owner.kind);
        // CHECK names are table-qualified memberships, not occupants of the
        // shared table/index namespace used by generated relation names.
        try std.testing.expect(names.relations[2] == null and names.relations[3] == null);
        try std.testing.expectError(error.CatalogPublicationProofPending, names.validateRelations(.{ .relations = &targets }));
        try std.testing.expectError(error.InvalidCatalogMutation, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .name_allocation = true, .include_query_definitions = true }));
        var stale = names.relation_epoch.?;
        stale.revision += 1;
        try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .name_allocation = true, .expected_relation_epoch = stale }));
    }
    {
        const Apply = struct {
            fn command(s: *RaftApplyStore, allocator: std.mem.Allocator, g: u64, index: u64, value: restore_staging.Command) !void {
                const json = try std.json.Stringify.valueAlloc(allocator, value, .{});
                defer allocator.free(json);
                const wire = try encodeTransitionCommand(allocator, .{ .apply_restore_staging = json });
                defer allocator.free(wire);
                const batch = try raft_state_machine.encodeCommittedEntries(allocator, &.{.{ .term = 1, .index = index, .entry_type = .normal, .data = wire }});
                defer allocator.free(batch);
                try s.snapshotBuilder().applyBatch(.{ .group_id = g, .commit_index = index, .entries_bytes = batch });
            }
        };
        const plan: restore_staging.Plan = .{
            .id = @splat(8),
            .cohort_digest = @splat(9),
            .targets = &.{.{
                .source_table_id = 1,
                .table = .{ .table_id = 11, .name = "hidden_restore", .schema_json = "{}" },
                .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }},
            }},
        };
        try plan.validate(a);
        const catalog_before = (try store.captureCatalogCursor(group)).revision;
        try Apply.command(&store, a, group, 3, .{ .id = plan.id, .action = .reserve, .plan = plan });
        var staged = (try store.loadRestoreStaging(a, group, plan.id)) orelse return error.MissingRestoreReservation;
        defer staged.deinit();
        try std.testing.expectEqual(catalog_before, (try store.captureCatalogCursor(group)).revision);
        // Even a lookup for unrelated names must reject the old source cut.
        try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .name_allocation = true, .expected_relation_epoch = allocation_epoch }));
        const reserved = try store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .name_allocation = true });
        defer reserved.deinit(a);
        try std.testing.expectEqualSlices(u8, &allocation_epoch.incarnation, &reserved.relation_epoch.?.incarnation);
        try std.testing.expect(reserved.relation_epoch.?.revision > allocation_epoch.revision);
        for ([_][]const u8{"hidden_restore"}) |name| {
            try std.testing.expectError(error.CatalogPublicationProofPending, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &.{.{ .name = name }}, .name_allocation = true }));
        }
        try Apply.command(&store, a, group, 4, .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 1 });
        try Apply.command(&store, a, group, 5, .{ .id = plan.id, .action = .canceled, .expected_revision = 2, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = try plan.digest(a), .completion_digest = @splat(3) } });
        try Apply.command(&store, a, group, 6, .{ .id = plan.id, .action = .finish_cancel, .expected_revision = 2 });
        try std.testing.expectEqual(catalog_before, (try store.captureCatalogCursor(group)).revision);
        try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .name_allocation = true, .expected_relation_epoch = reserved.relation_epoch }));
        const released = try store.resolveSystemCatalogIdentities(a, group, .{ .relations = &.{.{ .name = "hidden_restore" }}, .name_allocation = true });
        defer released.deinit(a);
        try std.testing.expect(released.relation_epoch.?.revision > reserved.relation_epoch.?.revision);
        try std.testing.expectEqualSlices(u8, &allocation_epoch.incarnation, &released.relation_epoch.?.incarnation);
        try std.testing.expect(released.relations[0] == null);
    }
    _ = try adoptLiveRelationWriterForTest(&store, a, group);
    try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .name_allocation = true, .expected_relation_epoch = allocation_epoch }));
    var epoch: relation_reconciliation.Epoch = undefined;
    {
        const resolved = try store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .include_query_definitions = true });
        defer resolved.deinit(a);
        epoch = resolved.relation_epoch.?;
        try resolved.validateRelations(.{ .relations = &targets, .include_query_definitions = true });
        try std.testing.expectEqual(@as(usize, 0), resolved.tables.len);
        try std.testing.expectEqual(relation_names.Kind.table, resolved.relations[0].?.owner.kind);
        try std.testing.expectEqual(relation_names.Kind.index, resolved.relations[1].?.owner.kind);
        try std.testing.expectEqualStrings(table.name, resolved.relations[1].?.table.name);
        try std.testing.expectEqualStrings(table.name, resolved.relations[1].?.logical_table);
        try std.testing.expectEqualStrings(table.schema_json, resolved.relations[1].?.table.query_definition.?.schema_json);
        try std.testing.expect(resolved.relations[2] == null);
        try std.testing.expect(resolved.relations[3] == null);
        const encoded = try std.json.Stringify.valueAlloc(a, resolved, .{});
        defer a.free(encoded);
        var wire = try std.json.parseFromSlice(system_catalog.ResolvedMany, a, encoded, .{});
        defer wire.deinit();
        try wire.value.validateRelations(.{ .relations = &targets, .include_query_definitions = true, .expected_relation_epoch = epoch });
        try std.testing.expect(wire.value.relations[1].?.owner.eql(resolved.relations[1].?.owner));
    }
    {
        // Identity lookup must not allocate the table's large administrative
        // description or decode a schema DOM for each requested index.
        var buffer: [16 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const resolved = try store.resolveSystemCatalogIdentities(bounded.allocator(), group, .{ .relations = &targets, .expected_relation_epoch = epoch });
        defer resolved.deinit(bounded.allocator());
        try std.testing.expectEqual(@as(u64, 7), resolved.relations[1].?.owner.table_id);
    }
    var foreign_epoch = epoch;
    foreign_epoch.incarnation[0] ^= 1;
    try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .expected_relation_epoch = foreign_epoch }));
    table.schema_json = "{\"version\":2,\"relational_indexes\":[{\"name\":\"new_idx\"}]}";
    try store.applyStandaloneCommand(group, .{ .upsert_table = table });
    {
        const resolved = try store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets });
        defer resolved.deinit(a);
        try std.testing.expect(resolved.relation_epoch.?.revision > epoch.revision);
        // The obsolete derived registry still contains old_idx, but cannot
        // turn the published root's authoritative miss into a hit.
        try std.testing.expect(resolved.relations[1] == null);
        try std.testing.expectEqual(@as(u32, 2), resolved.relations[2].?.owner.schema_version);
        try std.testing.expect(resolved.relations[2].?.table.query_definition == null);
        try resolved.validateRelations(.{ .relations = &targets });
        try std.testing.expectError(error.InvalidCatalogRecord, resolved.validateRelations(.{ .relations = &targets, .include_query_definitions = true }));
        var invalid = resolved.relations[2].?;
        invalid.owner.phase = .reserved;
        invalid.owner.publication_id = @splat(1);
        const reserved: system_catalog.ResolvedMany = .{ .revision = resolved.revision, .tables = &.{}, .relation_epoch = resolved.relation_epoch, .relations = &.{invalid} };
        try std.testing.expectError(error.InvalidCatalogRecord, reserved.validateRelations(.{ .relations = &.{targets[2]} }));
    }
    try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &targets, .expected_relation_epoch = epoch }));
    const too_many: [257]system_catalog.RelationTarget = @splat(.{ .name = "items" });
    try std.testing.expectError(error.CatalogCommandTooLarge, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &too_many }));
    try std.testing.expectError(error.InvalidCatalogName, store.resolveSystemCatalogIdentities(a, group, .{ .relations = &.{.{ .name = "" }} }));
    // Older peers omit the attestation field. Their default response must not
    // be treated as a successful relation lookup with no matches.
    var old = try std.json.parseFromSlice(system_catalog.ResolvedMany, a, "{\"revision\":1,\"tables\":[]}", .{});
    defer old.deinit();
    try std.testing.expect(old.value.relation_epoch == null);
    try std.testing.expectError(error.TableTopologyUpgradeRequired, old.value.validateRelations(.{ .relations = &targets }));
    const legacy_wire = struct {
        targets: []const system_catalog.Target,
        storage_names: []const []const u8,
        include_query_definitions: bool,
        expected_revision: ?u64,
    };
    const request_bytes = try std.json.Stringify.valueAlloc(a, system_catalog.ResolveMany{}, .{});
    defer a.free(request_bytes);
    var legacy_request = try std.json.parseFromSlice(legacy_wire, a, request_bytes, .{});
    defer legacy_request.deinit();
    const legacy_result = struct { revision: u64, tables: []const ?system_catalog.ResolvedTable, logical_names: []const ?[]const u8 };
    const result_bytes = try std.json.Stringify.valueAlloc(a, old.value, .{});
    defer a.free(result_bytes);
    var legacy_response = try std.json.parseFromSlice(legacy_result, a, result_bytes, .{});
    defer legacy_response.deinit();
}

test "system catalog relation namespace transaction guarded replacements fence owners not unrelated DDL" {
    const a = std.testing.allocator;
    const group: u64 = 21;
    const identity = "01010101010101010101010101010101".*;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/guarded-replacement", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = identity });
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "physical", .schema_json = "{\"version\":1,\"relational_indexes\":[{\"name\":\"owned_idx\"}]}" };
    try store.applyStandaloneCommand(group, .{ .upsert_table = table });
    _ = try adoptLiveRelationWriterForTest(&store, a, group);
    const target: system_catalog.RelationTarget = .{ .name = "owned_idx" };
    const resolved = try store.resolveSystemCatalogIdentities(a, group, .{ .relations = &.{target} });
    defer resolved.deinit(a);
    const guard: system_catalog.RelationMutationGuard = .{ .target = target, .logical_table = resolved.relations[0].?.logical_table, .owner = resolved.relations[0].?.owner, .incarnation = resolved.relation_epoch.?.incarnation };
    var replacement = table;
    replacement.description = "guarded";
    var command: TransitionCommand = .{ .compare_and_replace_table = .{ .expected = table, .replacement = replacement, .relation_guard = guard } };
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(group, command));
    inline for (.{ topology_protocol.relation_publication_version, topology_protocol.relation_mutation_version }) |version| {
        const activation: topology_protocol.Activation = .{ .version = version, .incarnation = identity, .member_count = 3, .membership_fingerprint = @splat(7) };
        const bytes = try std.json.Stringify.valueAlloc(a, activation, .{});
        defer a.free(bytes);
        try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = bytes });
        if (version < topology_protocol.relation_mutation_version) try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(group, command));
    }
    // A delayed publication-floor proof cannot downgrade an activated writer.
    const delayed_activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{ .version = topology_protocol.relation_publication_version, .incarnation = identity, .member_count = 3, .membership_fingerprint = @splat(7) }, .{});
    defer a.free(delayed_activation);
    try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = delayed_activation });
    try std.testing.expectEqual(topology_protocol.relation_mutation_version, (try store.topologyActivation(group)).?.version);
    const encoded = try encodeTransitionCommand(a, command);
    defer a.free(encoded);
    try std.testing.expectEqual(@backingInt(TransitionTag.compare_and_replace_relation_table), encoded[transition_magic.len]);
    var decoded = (try decodeTransitionCommand(a, encoded)).?;
    defer decoded.deinit(a);
    try std.testing.expect(decoded.compare_and_replace_table.relation_guard.?.owner.eql(guard.owner));
    const canonical = try encodeTransitionCommand(a, decoded);
    defer a.free(canonical);
    try std.testing.expectEqualSlices(u8, encoded, canonical);
    const unguarded = try encodeTransitionCommand(a, .{ .compare_and_replace_table = .{ .expected = table, .replacement = replacement } });
    defer a.free(unguarded);
    try std.testing.expectEqual(@backingInt(TransitionTag.compare_and_replace_table), unguarded[transition_magic.len]);
    var invalid = guard;
    invalid.incarnation[0] ^= 1;
    command.compare_and_replace_table.relation_guard = invalid;
    const before = try store.standaloneRevision();
    try std.testing.expectError(error.CatalogGenerationChanged, store.applyStandaloneCommand(group, command));
    try std.testing.expectEqual(before, try store.standaloneRevision());
    invalid = guard;
    invalid.owner.kind = .constraint_index;
    command.compare_and_replace_table.relation_guard = invalid;
    try std.testing.expectError(error.CatalogGenerationChanged, store.applyStandaloneCommand(group, command));
    invalid = guard;
    invalid.logical_table = "not_authorized";
    command.compare_and_replace_table.relation_guard = invalid;
    try std.testing.expectError(error.CatalogGenerationChanged, store.applyStandaloneCommand(group, command));
    command.compare_and_replace_table.relation_guard = guard;
    // A new source revision on a different table must not serialize this DDL.
    try store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "unrelated" } });
    // Ownership can change after name admission without changing the schema
    // digest. Both standalone and replicated apply must retain owned state.
    try store.applyStandaloneCommand(group, .{ .upsert_extension_member = .{ .extension_name = "owner", .scope = .{ .kind = .table, .table_name = table.name }, .object_kind = .table_schema, .object_name = "row", .table_name = table.name } });
    const owned_revision = try store.standaloneRevision();
    try std.testing.expectError(error.ExtensionOwnedObject, store.applyStandaloneCommand(group, command));
    try std.testing.expectEqual(owned_revision, try store.standaloneRevision());
    {
        var rejected = try MetadataReplayTest.apply(&store, group, &.{.{ .term = 1, .index = 1, .data = encoded }});
        defer rejected.deinit();
        const retained = (try store.getTable(a, group, table.table_id)).?;
        defer metadata_table_manager.freeTable(a, retained);
        try std.testing.expectEqualStrings("", retained.description);
        try std.testing.expectEqual(@as(u64, 1), try store.durableAppliedIndex(group));
    }
    try store.applyStandaloneCommand(group, .{ .remove_extension_member = .{ .extension_name = "owner", .object_kind = .table_schema, .object_name = "row" } });
    try store.applyStandaloneCommand(group, command);
    {
        const actual = (try store.getTable(a, group, table.table_id)).?;
        defer metadata_table_manager.freeTable(a, actual);
        try std.testing.expectEqualStrings("guarded", actual.description);
    }
    // Rename changes no schema version and leaves the index owner identical.
    // Only the in-transaction logical binding fence detects this race.
    try applySystemCatalogTestCommand(&store, 2, .{ .expected_revision = 0, .mutation = .{ .action = .rename, .kind = .table, .name = "physical", .new_name = "logical" } });
    command.compare_and_replace_table.expected = replacement;
    command.compare_and_replace_table.replacement.description = "must_not_apply";
    try std.testing.expectError(error.CatalogGenerationChanged, store.applyStandaloneCommand(group, command));
    const stale = try encodeTransitionCommand(a, command);
    defer a.free(stale);
    var outcome = try MetadataReplayTest.apply(&store, group, &.{.{ .term = 1, .index = 3, .data = stale }});
    defer outcome.deinit();
    try std.testing.expectEqual(@as(u64, 3), try store.durableAppliedIndex(group));
    const actual = (try store.getTable(a, group, table.table_id)).?;
    defer metadata_table_manager.freeTable(a, actual);
    try std.testing.expectEqualStrings("guarded", actual.description);
}

test "system catalog relation namespace transaction guarded codec rejects truncation and allocation faults" {
    const Fixture = struct {
        const table: metadata.TableRecord = .{ .table_id = 7, .name = "physical" };
        const command: TransitionCommand = .{ .compare_and_replace_table = .{ .expected = table, .replacement = table, .relation_guard = .{ .target = .{ .name = "idx" }, .logical_table = "logical", .owner = .{ .table_id = 7, .schema_version = 1, .schema_digest = @splat(1), .kind = .index }, .incarnation = @splat(1) } } };
        fn run(a: std.mem.Allocator) !void {
            const bytes = try encodeTransitionCommand(a, command);
            defer a.free(bytes);
            var decoded = (try decodeTransitionCommand(a, bytes)).?;
            defer decoded.deinit(a);
            try std.testing.expectEqualStrings("logical", decoded.compare_and_replace_table.relation_guard.?.logical_table);
        }
    };
    const bytes = try encodeTransitionCommand(std.testing.allocator, Fixture.command);
    defer std.testing.allocator.free(bytes);
    for (transition_magic.len + 1..bytes.len) |len| try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTransitionCommand(std.testing.allocator, bytes[0..len]));
    const trailing = try std.mem.concat(std.testing.allocator, u8, &.{ bytes, "x" });
    defer std.testing.allocator.free(trailing);
    try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTransitionCommand(std.testing.allocator, trailing));
    try std.testing.checkAllAllocationFailures(std.testing.allocator, Fixture.run, .{});
}

test "system catalog relation namespace transaction live writers pin roots recover and ignore obsolete registry bytes" {
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/live-writer", .{tmp.sub_path});
    defer a.free(root);
    const restored_root = try std.fmt.allocPrint(a, "{s}-restored", .{root});
    defer a.free(restored_root);
    const checkpoint_path = try std.fmt.allocPrint(a, "{s}.checkpoint", .{root});
    defer a.free(checkpoint_path);
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "before", .schema_json = "{\"version\":1,\"relational_indexes\":[{\"name\":\"old_idx\"}]}" };
    var artifact: RaftApplyStore.metadata_hot_standby.CheckpointArtifact = undefined;
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = root });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
        try store.applyStandaloneCommand(group, .{ .upsert_table = table });
        const ready = try adoptLiveRelationWriterForTest(&store, a, group);
        var pinned = try store.store.beginReadTxn();
        defer pinned.abort();
        var before = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(a, &pinned, group);
        try std.testing.expect(before.live != null);
        const initial = before.live.?.root;
        var changed = table;
        changed.name = "after";
        changed.schema_json = "{\"version\":2,\"relational_indexes\":[{\"name\":\"new_idx\"}]}";
        try store.applyStandaloneCommand(group, .{ .upsert_table = changed });
        try std.testing.expect((try before.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = table.name })) != null);
        try std.testing.expect((try before.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = changed.name })) == null);
        {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            var after = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(a, &read, group);
            try std.testing.expectEqual(initial.sequence + 1, after.live.?.root.sequence);
            try std.testing.expectEqual(@as(u64, 2), after.live.?.root.claims);
            try std.testing.expect((try after.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "old_idx" })) == null);
            try std.testing.expectEqual(@as(u32, 2), (try after.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "new_idx" })).?.schema_version);
            // No bulk migration/copy or cleanup is needed for root publication.
            var obsolete: relation_names.Store(docstore.DocStore.Txn) = .{ .txn = &read, .alloc = a, .group_id = group };
            try std.testing.expect((try obsolete.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = table.name })) != null);
            var buf: [128]u8 = undefined;
            try std.testing.expectEqualSlices(u8, &(try ready.encode()), try read.get(try relation_reconciliation.jobKey(&buf, group)));
        }
        try verifyRelationRecoveryForTest(&store, a, group);
        const revision = try store.standaloneRevision();
        try std.testing.expectError(error.CatalogAlreadyExists, store.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 8, .name = "other", .schema_json = "{\"version\":1,\"relational_indexes\":[{\"name\":\"new_idx\"}]}" } }));
        try std.testing.expectEqual(revision, try store.standaloneRevision());
        try verifyRelationRecoveryForTest(&store, a, group);
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group)).?;
            const key: relation_names.Key = .{ .namespace_id = system_catalog.default_namespace_id, .name = "new_idx" };
            const prior = (try live.getEntry(key)).?;
            var forged = prior;
            forged.active.?.schema_digest[0] ^= 1;
            var plan = try relation_names.Plan.init(a, &.{try relation_names.Claim.fromEntry(key, prior)}, &.{try relation_names.Claim.fromEntry(key, forged)});
            defer plan.deinit();
            try relation_reconciliation.advanceSource(&txn, group);
            try live.apply(&plan, try RaftApplyStore.relationSourceEpochTxn(&txn, group));
            // The attacker supplied a self-consistent count/hash and source
            // clock. Native recovery must still authenticate the owner schema.
            try verifyReconciliationGroupTxn(&txn, group);
            try std.testing.expectError(error.InvalidMetadataHACheckpoint, verifyRelationCheckpointTxn(a, &txn));
            try std.testing.expectError(error.InvalidMetadataSnapshot, store.buildMetadataSnapshotTxn(a, &txn, group, null));
        }
        artifact = try store.exportHotStandbyCheckpoint(store.io_impl.io(), checkpoint_path);
    }
    {
        var restored = try RaftApplyStore.init(a, .{ .root_dir = restored_root });
        defer restored.deinit();
        try restored.importHotStandbyCheckpoint(restored.io_impl.io(), checkpoint_path, artifact.size_bytes);
        try verifyRelationRecoveryForTest(&restored, a, group);
        try restored.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "recovered", .schema_json = "{}" } });
        try verifyRelationRecoveryForTest(&restored, a, group);
    }
    var reopened = try RaftApplyStore.init(a, .{ .root_dir = restored_root });
    defer reopened.deinit();
    try verifyRelationRecoveryForTest(&reopened, a, group);
    var read = try reopened.store.beginReadTxn();
    defer read.abort();
    var registry = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(a, &read, group);
    try std.testing.expect((try registry.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "recovered" })) != null);
    try std.testing.expect((try registry.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "before" })) == null);
}

test "system catalog relation namespace transaction live replay authenticates producer cuts and aborts incomplete effects" {
    const a = std.testing.allocator;
    const group = group_ids.main_metadata_group_id;
    const T = struct {
        const Variant = enum { valid, missing_owner, missing_delete, missing_manifest, forged, extra, obsolete, disable, swap };
        fn effect(store: *RaftApplyStore, variant: Variant) ![]u8 {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            var capture = @import("antfly_local_sources").storage_txn_mutation_capture.Capture.init(a);
            defer capture.deinit();
            txn.mutation_capture = &capture;
            var outcome: CommittedApplyOutcome = .{ .alloc = a };
            defer outcome.deinit();
            store.active_outcome = &outcome;
            defer store.active_outcome = null;
            if (variant == .swap) {
                var buf: [128]u8 = undefined;
                const ready = try relation_reconciliation.State.decode(try txn.get(try relation_reconciliation.jobKey(&buf, group)));
                // Exclusive test fixture: obtain independent authority to
                // demonstrate that receiver activation requires its own
                // membership capability, not just a valid candidate seal.
                const proof = try RaftApplyStore.prepareRelationPublicationProofTxn(a, &txn, ready);
                try std.testing.expect(try proof.matchesTxn(&txn));
                const prior = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group)).?;
                _ = try relation_reconciliation.publishVerifiedRoot(&txn, ready, ready.epoch, prior.root);
                return RaftApplyStore.metadata_hot_standby.encode(a, &capture, &txn, .{ .source = @splat(1), .sequence = 1, .group_id = group, .count = 0 });
            }
            try store.applyTransitionCommandTxn(&txn, group, .{ .upsert_table = .{ .table_id = 7, .name = "after", .schema_json = "{}" } });
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group)).?;
            const key: relation_names.Key = .{ .namespace_id = system_catalog.default_namespace_id, .name = "after" };
            var buf: [relation_reconciliation.max_cursor_bytes]u8 = undefined;
            switch (variant) {
                .valid => {},
                .missing_owner => try std.testing.expect(capture.keys.remove(try relation_reconciliation.candidateGenerationKey(&buf, live.root.generation, key))),
                .missing_delete => try std.testing.expect(capture.keys.remove(try relation_reconciliation.candidateGenerationKey(&buf, live.root.generation, .{ .namespace_id = key.namespace_id, .name = "before" }))),
                .missing_manifest => try std.testing.expect(capture.keys.remove(try relation_reconciliation.liveKey(&buf, group))),
                .forged => {
                    var entry = (try live.getEntry(key)).?;
                    entry.active.?.schema_digest[0] ^= 1;
                    try txn.put(try relation_reconciliation.candidateGenerationKey(&buf, live.root.generation, key), &(try entry.encode()));
                },
                .extra => try txn.put(try relation_reconciliation.candidateGenerationKey(&buf, live.root.generation, .{ .namespace_id = key.namespace_id, .name = "injected" }), &(try (try live.getEntry(key)).?.encode())),
                .obsolete => {
                    var obsolete: relation_names.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .alloc = a, .group_id = group };
                    try obsolete.putEntry(.{ .namespace_id = key.namespace_id, .name = "injected" }, (try live.getEntry(key)).?);
                },
                .disable => try txn.delete(try RaftApplyStore.relationWriterKeyForGroup(&buf, group)),
                .swap => unreachable,
            }
            return RaftApplyStore.metadata_hot_standby.encode(a, &capture, &txn, .{ .source = @splat(1), .sequence = 1, .group_id = group, .count = 0 });
        }
        fn replay(store: *RaftApplyStore, bytes: []const u8) !void {
            const descriptor = try RaftApplyStore.metadata_chunks.Descriptor.fromEffect(bytes);
            try std.testing.expectEqual(@as(u32, 1), descriptor.chunk_count);
            const frame = try RaftApplyStore.metadata_chunks.encodeFrame(a, descriptor, 0, bytes);
            defer a.free(frame);
            try store.applyHotStandbyRecord(.{ .kind = .metadata_mutation, .payload_codec = .binary, .cluster_id = 7, .timeline_id = 1, .epoch = 1, .lsn = 1, .previous_lsn = 0, .payload = frame });
        }
    };
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/live-replay-source", .{tmp.sub_path});
    defer a.free(root);
    var source = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer source.deinit();
    try source.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    try source.applyStandaloneCommand(group, .{ .upsert_table = .{ .table_id = 7, .name = "before", .schema_json = "{}" } });
    const original = try adoptLiveRelationWriterForTest(&source, a, group);
    const replacement = try relation_reconciliation.State.init(group, try relation_reconciliation.nextJobId(&original), original.epoch);
    {
        var txn = try source.store.beginWriteTxn();
        errdefer txn.abort();
        try relation_reconciliation.start(&txn, &replacement, original.epoch, &(try original.encode()));
        try txn.commit();
    }
    _ = try reconcileRestoreNamesForTest(&source, a, replacement);
    const snapshot = try source.snapshotBuilder().buildSnapshot(a, group);
    defer a.free(snapshot);
    const valid = try T.effect(&source, .valid);
    defer a.free(valid);
    for ([_]T.Variant{ .missing_owner, .missing_delete, .missing_manifest, .forged, .extra, .obsolete, .disable, .swap }) |variant| {
        const target_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/live-replay-{s}", .{ tmp.sub_path, @tagName(variant) });
        defer a.free(target_root);
        const invalid = try T.effect(&source, variant);
        defer a.free(invalid);
        {
            var receiver = try RaftApplyStore.init(a, .{ .root_dir = target_root });
            defer receiver.deinit();
            try RaftApplyStore.installSnapshotFromRaft(&receiver, a, group, 10, snapshot);
            var signals: MetadataReplayTest.Capture = .{};
            try signals.register(&receiver);
            const expected = switch (variant) {
                .missing_owner, .missing_delete, .forged => error.CatalogGenerationChanged,
                .swap => error.TableTopologyProtocolUpgradeRequired,
                else => error.InvalidCatalogRecord,
            };
            try std.testing.expectError(expected, T.replay(&receiver, invalid));
            try std.testing.expectEqual(@as(usize, 0), signals.projections);
            try std.testing.expectEqual(@as(usize, 0), signals.keys);
            {
                var read = try receiver.store.beginReadTxn();
                defer read.abort();
                var registry = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(a, &read, group);
                try std.testing.expectEqual(@as(u64, 1), registry.live.?.root.sequence);
                try std.testing.expect((try registry.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "before" })) != null);
                try std.testing.expect((try registry.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "after" })) == null);
                try std.testing.expectError(error.NotFound, read.get(RaftApplyStore.metadata_hot_standby.sequence_key));
                try std.testing.expectError(error.NotFound, read.get(RaftApplyStore.metadata_hot_standby.replay_key));
                try verifyRelationCheckpointTxn(a, &read);
            }
            try T.replay(&receiver, valid);
            try verifyRelationRecoveryForTest(&receiver, a, group);
        }
        var recovered = try RaftApplyStore.init(a, .{ .root_dir = target_root });
        defer recovered.deinit();
        try T.replay(&recovered, valid); // Receipt-fenced idempotence after restart.
        try verifyRelationRecoveryForTest(&recovered, a, group);
        var read = try recovered.store.beginReadTxn();
        defer read.abort();
        var registry = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(a, &read, group);
        try std.testing.expectEqual(@as(u64, 2), registry.live.?.root.sequence);
        try std.testing.expect((try registry.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "after" })) != null);
        try std.testing.expect((try registry.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = "injected" })) == null);
    }
}

test "SQL view catalog publishes attributes and reverse edges atomically and verifies native snapshots and cold reopen" {
    try testViewCatalogSnapshot(false);
}

test "SQL view catalog temporal snapshots preserve kinds and reject downgraded readers" {
    try testViewCatalogSnapshot(true);
}

fn testViewCatalogSnapshot(temporal: bool) !void {
    const a = std.testing.allocator;
    const group: u64 = 41;
    const schema =
        \\{"version":1,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"},"status":{"type":"keyword"}},"additionalProperties":false}}}}
    ;
    const schema_added =
        \\{"version":2,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"},"status":{"type":"keyword"},"note":{"type":"keyword"}},"additionalProperties":false}}}}
    ;
    const schema_dropped =
        \\{"version":3,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"status":{"type":"keyword"},"note":{"type":"keyword"}},"additionalProperties":false}}}}
    ;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/view-catalog", .{tmp.sub_path});
    defer a.free(root);
    const copy_root = try std.fmt.allocPrint(a, "{s}-snapshot", .{root});
    defer a.free(copy_root);
    var identity: RaftApplyStore.SqlViewIdentity = undefined;
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = root });
        defer store.deinit();
        const incarnation = "01010101010101010101010101010101".*;
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = incarnation });
        const table: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .schema_json = schema };
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .tables = &.{table}, .auxiliary_json = "{}" });
        const source_bytes = try RaftApplyStore.columnIdentityValue(a, table, null, &.{});
        defer a.free(source_bytes);
        var attributes = try column_identities.State.decode(a, source_bytes);
        defer attributes.deinit();
        const id = for (attributes.value.columns) |column| {
            if (std.mem.eql(u8, column.name, "id")) break column;
        } else return error.TestMissingColumnIdentity;
        var source: @import("antfly_local_sources").sql_view_definition.Source = .{
            .reference = .{ .table = "rows" },
            .database = "default",
            .namespace = "public",
            .name = "rows",
            .physical_name = "rows",
            .table_id = 7,
            .schema_version = attributes.value.epoch.version,
            .schema_digest = attributes.value.epoch.digest,
            .columns = &.{.{ .name = "id", .signature = id.signature, .ordinal = 0, .virtual = false }},
        };
        var definition: @import("antfly_local_sources").sql_view_definition.Definition = .{
            .format = if (temporal) 2 else 1,
            .query = if (temporal) "SELECT DATE '2000-01-01' AS id FROM rows WHERE id>0" else "SELECT id FROM rows",
            .owner = .auth_disabled,
            .security = .invoker,
            .security_barrier = true,
            .catalog_revision = null,
            .setting_epoch = null,
            .columns = if (temporal) &.{.{ .name = "id", .type = .datetime, .temporal_kind = .date }} else &.{.{ .name = "id", .type = .integer, .element_type = .int64 }},
            .sources = &.{source},
        };
        const before = try store.systemCatalogMeta(a, group);
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.publishSqlViewTxn(&txn, group, .{
                .expected_revision = before.revision,
                .target = .{ .table = "stored" },
                .definition = definition,
            }));
            const registry: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .group_id = group };
            try std.testing.expect((try registry.load(a, 7)) == null);
        }
        const activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{
            .version = topology_protocol.current_version,
            .incarnation = incarnation,
            .member_count = 1,
            .membership_fingerprint = @splat(7),
        }, .{});
        defer a.free(activation);
        try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
        try adoptRelationWriterForTest(&store, a, group);
        _ = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
        // A retained replacement owns the source identity. A view may not
        // sneak a new reverse dependency behind its admitted retirement cut.
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            var key_buf: [256]u8 = undefined;
            const lock = try restore_staging.identityKey(&key_buf, group, .old_table, table.table_id);
            try txn.put(lock, &@as([16]u8, @splat(1)));
            try std.testing.expectError(error.CatalogGenerationChanged, store.publishSqlViewTxn(&txn, group, .{
                .expected_revision = before.revision,
                .target = .{ .table = "during_replacement" },
                .definition = definition,
            }));
            const registry: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .group_id = group };
            try std.testing.expect((try registry.load(a, table.table_id)) == null);
        }
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            const epoch = try RaftApplyStore.relationSourceEpochTxn(&txn, group);
            identity = try store.publishSqlViewTxn(&txn, group, .{
                .expected_revision = before.revision,
                .target = .{ .table = "stored" },
                .definition = definition,
            });
            try std.testing.expect(epoch.eql(try RaftApplyStore.relationSourceEpochTxn(&txn, group)));
            try verifySqlViewCheckpointTxn(a, &txn);
            try txn.commit();
        }
        const after = try store.systemCatalogMeta(a, group);
        try std.testing.expectEqual(before.revision + 1, after.revision);
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            try std.testing.expectError(error.CatalogGenerationChanged, store.publishSqlViewTxn(&txn, group, .{
                .expected_revision = before.revision,
                .target = .{ .table = "other" },
                .definition = definition,
            }));
            try std.testing.expectError(error.CatalogAlreadyExists, store.publishSqlViewTxn(&txn, group, .{
                .expected_revision = after.revision,
                .target = .{ .table = "stored" },
                .definition = definition,
            }));
            try std.testing.expect(try store.relationalDropBlockedTxn(&txn, group, table));
            try std.testing.expectEqual(@as(?u64, identity.id), try sql_views.firstDependent(&txn, group, .table, 7, id.id));
            // Replacing an owner cannot silently strand a catalog-bound view.
            // Reject before any reservation, not late in committed publish.
            const replacement: restore_staging.Plan = .{
                .id = @splat(2),
                .cohort_digest = @splat(3),
                .targets = &.{.{
                    .source_table_id = table.table_id,
                    .table = .{ .table_id = 8, .name = table.name, .schema_json = schema_added },
                    .ranges = &.{},
                    .replace = .{ .table = table, .ranges = &.{}, .fences = &.{} },
                }},
            };
            try std.testing.expectError(error.InvalidRestoreStaging, RaftApplyStore.restoreCatalogDeltaTxn(a, &txn, group, replacement));
        }
        var added = table;
        added.schema_json = schema_added;
        try store.applyStandaloneCommand(group, .{ .upsert_table = added });
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            var removed = added;
            removed.schema_json = schema_dropped;
            var buffer: [160]u8 = undefined;
            try std.testing.expect(!try store.tryPutTableRecordTxnMode(&txn, group, try tableKeyForGroup(&buffer, group, 7), removed, false));
            const registry: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .group_id = group };
            var state = (try registry.load(a, 7)).?;
            defer state.deinit();
            source.schema_version = state.value.epoch.version;
            source.schema_digest = state.value.epoch.digest;
        }
        definition.sources = &.{source};
        definition.query = if (temporal) "SELECT DATE '2000-01-01' AS id, 'note' AS note FROM rows WHERE id>0" else "SELECT id, 'note' AS note FROM rows";
        definition.columns = if (temporal) &.{
            .{ .name = "id", .type = .datetime, .temporal_kind = .date },
            .{ .name = "note", .type = .string },
        } else &.{
            .{ .name = "id", .type = .integer, .element_type = .int64 },
            .{ .name = "note", .type = .string },
        };
        definition.security = .owner;
        definition.security_barrier = false;
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            identity = try store.publishSqlViewTxn(&txn, group, .{
                .expected_revision = after.revision,
                .target = .{ .table = "stored" },
                .definition = definition,
                .replace = true,
                .expected = identity,
            });
            try std.testing.expectEqual(@as(u32, 2), identity.generation);
            try verifySqlViewCheckpointTxn(a, &txn);
            try txn.commit();
        }
        const snapshot = try store.snapshotBuilder().buildSnapshot(a, group);
        defer a.free(snapshot);
        const rows = try decodeMetadataSnapshotAlloc(a, snapshot);
        defer freeMetadataSnapshotRows(a, rows);
        try validateMetadataSnapshotRows(a, group, rows);
        // Snapshot admission must honor the descriptor's capability floor,
        // independently of canonical encoding and dependency fingerprints.
        {
            const downgraded = try a.dupe(docstore.OwnedKVPair, rows);
            defer a.free(downgraded);
            var buffer: [160]u8 = undefined;
            const key = try RaftApplyStore.topologyActivationKeyForGroup(&buffer, group);
            var found = false;
            for (downgraded) |*row| if (std.mem.eql(u8, row.key, key)) {
                var parsed = try std.json.parseFromSlice(topology_protocol.Activation, a, row.value, .{});
                defer parsed.deinit();
                parsed.value.version = topology_protocol.sql_view_domains_version - 1;
                const encoded = try std.json.Stringify.valueAlloc(a, parsed.value, .{});
                defer a.free(encoded);
                row.value = encoded;
                found = true;
                if (temporal) {
                    try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, group, downgraded));
                } else {
                    try validateMetadataSnapshotRows(a, group, downgraded);
                }
                break;
            };
            try std.testing.expect(found);
        }
        {
            var missing: std.ArrayList(docstore.OwnedKVPair) = .empty;
            defer missing.deinit(a);
            for (rows) |row| {
                if (try sql_views.dependencyFromKey(row.key, group)) |edge| if (edge.dependency.column == id.id) continue;
                try missing.append(a, row);
            }
            try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, group, missing.items));
            var buffer: [160]u8 = undefined;
            const orphan = try sql_views.dependencyKey(&buffer, group, .{ .kind = .table, .id = 7, .column = 999 }, identity.id);
            var extra: std.ArrayList(docstore.OwnedKVPair) = .empty;
            defer extra.deinit(a);
            try extra.appendSlice(a, rows);
            try extra.append(a, .{ .key = @constCast(orphan), .value = @constCast(&[_]u8{1}) });
            try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, group, extra.items));
        }
        var copy = try RaftApplyStore.init(a, .{ .root_dir = copy_root });
        defer copy.deinit();
        try std.testing.expect(try copy.snapshotBuilder().installSnapshot(a, group, 10, snapshot));
        try verifyRelationRecoveryForTest(&copy, a, group);
    }
    for ([_][]const u8{ root, copy_root }) |path| {
        var reopened = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer reopened.deinit();
        try verifyRelationRecoveryForTest(&reopened, a, group);
        var txn = try reopened.store.beginReadTxn();
        defer txn.abort();
        var resource = (try system_catalog_storage.getById(a, &txn, group, .view, identity.id)).?;
        defer resource.deinit();
        var record = try sql_views.Record.decode(a, resource.value.source_json);
        defer record.deinit();
        try std.testing.expectEqual(@as(u32, 2), record.value.generation);
        try std.testing.expectEqual(@as(u8, if (temporal) 2 else 1), record.value.definition.format);
        try std.testing.expectEqual(if (temporal) @as(?@import("antfly_local_sources").sql_temporal_value.Kind, .date) else null, record.value.definition.columns[0].temporal_kind);
        try std.testing.expectEqual(@as(u64, 3), record.value.attributes.next_id);
        try std.testing.expectEqual(@as(u64, 1), record.value.attributes.columns[0].id);
        try std.testing.expectEqual(@as(u64, 2), record.value.attributes.columns[1].id);
        try std.testing.expectEqual(@as(?u64, identity.id), try sql_views.firstDependent(&txn, group, .table, 7, null));
    }
}

test "SQL view catalog physical source normalization retains nondefault namespace guards" {
    const a = std.testing.allocator;
    const key = try system_catalog_storage.recordKeyAlloc(a, 41, .namespace, system_catalog.default_namespace_id);
    defer a.free(key);
    const canonical = try std.json.Stringify.valueAlloc(a, system_catalog.default_namespace, .{});
    defer a.free(canonical);
    var implicit: RaftApplyStore.RelationSourceCut = .{ .revision = 1 };
    const empty = implicit;
    try implicit.feed(a, 41, key, canonical);
    try std.testing.expect(implicit.eql(empty));
    var changed = system_catalog.default_namespace;
    changed.placement_policy.desired_replica_count = 3;
    const encoded = try std.json.Stringify.valueAlloc(a, changed, .{});
    defer a.free(encoded);
    try implicit.feed(a, 41, key, encoded);
    try std.testing.expect(!implicit.eql(empty));
}

test "SQL view catalog committed log delivery survives lost replies duplicate intents restart and lagging snapshot catchup" {
    const T = struct {
        fn deliver(store: *RaftApplyStore, group: u64, index: u64, term: u64, bytes: []const u8) !void {
            const wire = try encodeTransitionCommand(store.alloc, .{ .apply_system_catalog = bytes });
            defer store.alloc.free(wire);
            const entries = try raft_state_machine.encodeCommittedEntries(store.alloc, &.{.{ .term = term, .index = index, .entry_type = .normal, .data = wire }});
            defer store.alloc.free(entries);
            try store.snapshotBuilder().applyBatch(.{ .group_id = group, .commit_index = index, .entries_bytes = entries });
        }
    };
    const a = std.testing.allocator;
    const group: u64 = 41;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var paths: [3][]const u8 = undefined;
    var stores: [3]RaftApplyStore = undefined;
    var initialized: usize = 0;
    var live: [3]bool = @splat(false);
    defer for (stores[0..initialized], paths[0..initialized], live[0..initialized]) |*store, path, active| {
        if (active) store.deinit();
        a.free(path);
    };
    for (&stores, &paths, 0..) |*store, *path, i| {
        path.* = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/view-replica-{d}", .{ tmp.sub_path, i });
        errdefer a.free(path.*);
        store.* = try RaftApplyStore.init(a, .{ .root_dir = path.* });
        live[i] = true;
        initialized += 1;
    }
    const incarnation = "01010101010101010101010101010101".*;
    try stores[0].applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = incarnation });
    const activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{
        .version = topology_protocol.current_version,
        .incarnation = incarnation,
        .member_count = 3,
        .membership_fingerprint = @splat(7),
    }, .{});
    defer a.free(activation);
    try stores[0].applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
    try adoptRelationWriterForTest(&stores[0], a, group);
    _ = try publishLiveRelationRootWithCoverageForTest(&stores[0], a, group, .constraint_names);
    const initial = try stores[0].snapshotBuilder().buildSnapshot(a, group);
    defer a.free(initial);
    for (stores[1..]) |*store| try std.testing.expect(try store.snapshotBuilder().installSnapshot(a, group, 10, initial));
    const revision = (try stores[0].systemCatalogMeta(a, group)).revision;
    const request: sql_views.Request = .{ .expected_revision = revision, .mutation = .{
        .target = .{ .table = "published" },
        .operation = .{ .publish = .{ .definition = .{
            .format = 1,
            .query = "SELECT 1::BIGINT AS id",
            .owner = .auth_disabled,
            .security = .invoker,
            .security_barrier = true,
            .catalog_revision = null,
            .setting_epoch = null,
            .columns = &.{.{ .name = "id", .type = .integer, .element_type = .int64 }},
            .sources = &.{},
        } } },
    } };
    const command = sql_views.command(request);
    const prepared = try stores[0].prepareSystemCatalogResult(a, group, command);
    defer a.free(prepared);
    var receipt = try std.json.parseFromSlice(sql_views.MutationResult, a, prepared, .{});
    defer receipt.deinit();
    const create = try std.json.Stringify.valueAlloc(a, command, .{});
    defer a.free(create);
    for (stores[0..2]) |*store| try T.deliver(store, group, 11, 2, create);
    // Lose the caller's receipt, then commit the same stale intent again.
    // CAS replay cannot allocate another view or consume another catalog ID.
    const committed = try stores[0].systemCatalogMeta(a, group);
    for (stores[0..2]) |*store| try T.deliver(store, group, 12, 2, create);
    try std.testing.expectEqualDeep(committed, try stores[0].systemCatalogMeta(a, group));
    const checkpoint = try stores[1].snapshotBuilder().buildSnapshot(a, group);
    defer a.free(checkpoint);
    // One follower missed both log entries; it catches up from a verified cut.
    try std.testing.expect(try stores[2].snapshotBuilder().installSnapshot(a, group, 12, checkpoint));
    stores[0].deinit();
    live[0] = false;
    stores[0] = try RaftApplyStore.init(a, .{ .root_dir = paths[0] });
    live[0] = true;
    const rename = try std.json.Stringify.valueAlloc(a, sql_views.command(.{ .expected_revision = committed.revision, .mutation = .{
        .target = .{ .table = "published" },
        .operation = .{ .rename = .{ .expected = receipt.value.identity.?, .name = "renamed" } },
    } }), .{});
    defer a.free(rename);
    // A successor term uses the same identity, including on the restarted
    // former leader. This tests state-machine delivery, not a fake election.
    for (&stores) |*store| try T.deliver(store, group, 13, 3, rename);
    for (&stores) |*store| {
        const result = try store.resolveSystemCatalogIdentities(a, group, .{ .sql_sources = &.{ .{ .name = .{ .table = "published" } }, .{ .view_id = receipt.value.identity.?.id } } });
        defer result.deinit(a);
        try std.testing.expect(result.sql_sources[0] == null);
        try std.testing.expectEqualStrings("renamed", result.sql_sources[1].?.target.table);
        try std.testing.expectEqualDeep(try stores[1].systemCatalogMeta(a, group), try store.systemCatalogMeta(a, group));
    }
}

test "sequence catalog portable export retains standalone revision and extension authority" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/standalone-export-authority", .{tmp.sub_path});
    defer a.free(root);
    const auxiliary = "{\"extension_packages\":[{\"name\":\"portable_fixture\",\"version\":\"1.0.0\",\"digest\":\"fixture\",\"install\":{\"scopes_supported\":[\"cluster\"]}}]}";
    const group = group_ids.main_metadata_group_id;
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = root });
        defer store.deinit();
        try store.updateStandaloneCatalog(group, 0, .{ .auxiliary_json = auxiliary });
        // Auxiliary-only edits advance the standalone authority without
        // changing distributed physical table-catalog revision counters.
        try store.updateStandaloneCatalog(group, 1, .{ .auxiliary_json = auxiliary });
    }
    var reopened = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer reopened.deinit();
    const bytes = try reopened.exportSystemCatalog(a, group);
    defer a.free(bytes);
    var exported = try std.json.parseFromSlice(@import("../../system_catalog/projection.zig").Export, a, bytes, .{});
    defer exported.deinit();
    try std.testing.expectEqual(try reopened.standaloneRevision(), exported.value.epoch);
    try std.testing.expectEqual(@as(usize, 1), exported.value.extension_packages.len);
    try std.testing.expectEqualStrings("portable_fixture", exported.value.extension_packages[0].name);
    try exported.value.extension_packages[0].validate();
}

test "sequence catalog native declarations share atomic metadata standalone raft cold and snapshot owners" {
    const T = struct {
        fn checkpointWithout(store: *RaftApplyStore, path: []const u8, omitted: ?[]const u8) !RaftApplyStore.metadata_hot_standby.CheckpointArtifact {
            const codec = RaftApplyStore.metadata_hot_standby;
            const io = store.io_impl.io();
            var txn = try store.store.beginReadTxn();
            defer txn.abort();
            var file = try std.Io.Dir.cwd().createFile(io, path, .{ .exclusive = true });
            defer file.close(io);
            var writer: codec.CheckpointWriter = .{ .file = file, .io = io };
            try writer.write("AFMCHK01");
            var cursor = try txn.openCursor();
            defer cursor.close();
            var removed: usize = 0;
            var row = try cursor.first();
            while (row) |item| : (row = try cursor.next()) {
                if (omitted) |prefix| if (std.mem.startsWith(u8, item.key, prefix)) {
                    removed += 1;
                    continue;
                };
                try writer.write(&try codec.checkpointHeader(item.key.len, item.value.len));
                try writer.write(item.key);
                try writer.write(item.value);
            }
            if (omitted != null) try std.testing.expect(removed != 0);
            return writer.finish();
        }
        fn expectLogicalMeta(expected: system_catalog.Meta, actual: system_catalog.Meta) !void {
            var logical = actual;
            logical.sequence_outcome_head = expected.sequence_outcome_head;
            try std.testing.expectEqualDeep(expected, logical);
        }
        fn deliver(store: *RaftApplyStore, group: u64, index: u64, request: sql_sequences.Mutation, replicated: bool) !void {
            const json = try std.json.Stringify.valueAlloc(store.alloc, sql_sequences.command(request), .{});
            defer store.alloc.free(json);
            return transition(store, group, index, .{ .apply_system_catalog = json }, replicated);
        }
        fn transition(store: *RaftApplyStore, group: u64, index: u64, command: TransitionCommand, replicated: bool) !void {
            if (!replicated) return store.applyStandaloneCommand(group, command);
            const wire = try encodeTransitionCommand(store.alloc, command);
            defer store.alloc.free(wire);
            const entries = try raft_state_machine.encodeCommittedEntries(store.alloc, &.{.{ .term = 1, .index = index, .entry_type = .normal, .data = wire }});
            defer store.alloc.free(entries);
            try store.snapshotBuilder().applyBatch(.{ .group_id = group, .commit_index = index, .entries_bytes = entries });
        }
        fn state(store: *RaftApplyStore, group: u64, name: []const u8, wanted: i64, generation: u64) !sql_sequences.Identity {
            // Snapshot installation intentionally excludes derived indexes;
            // use the production query gate which rebuilds/verifies them.
            var txn = try store.beginQueryCatalogReadTxn(group);
            defer txn.abort();
