    try std.testing.expect(!std.mem.eql(u8, &expected, &try RaftApplyStore.relationFkSourceDigest(projection, 7)));
    projection.plan.child_after.schema_json = "{\"version\":2}";
    const payload = try a.alloc(u8, 128 * 1024);
