    const json = try std.json.Stringify.valueAlloc(a, .{ .plan = projection.plan, .phase = projection.phase, .revision = 1024, .child_fenced = &.{.{ .unused = payload }} }, .{});
    defer a.free(json);
    var storage: [32 * 1024]u8 = undefined;
