const checkpoint_magic = "AMCKPT\x00\x00";
const checkpoint_encoded_len = 26;
// Replica-local installation receipt, not replicated catalog state. Retain
// only the latest snapshot, independently of later committed-entry watermarks.
const MetadataSnapshotInstallCut = struct {
    const magic = "AMSI01";
    const encoded_len = magic.len + 8 + 8 + 32;
    index: u64,
    bytes: u64,
    digest: [32]u8,

    fn of(index: u64, encoded: []const u8) !@This() {
        if (index == 0 or encoded.len == 0) return error.InvalidMetadataSnapshot;
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(encoded, &digest, .{});
        return .{ .index = index, .bytes = encoded.len, .digest = digest };
    }
    fn encode(self: @This()) [encoded_len]u8 {
        var out: [encoded_len]u8 = undefined;
        @memcpy(out[0..magic.len], magic);
        std.mem.writeInt(u64, out[magic.len..][0..8], self.index, .big);
        std.mem.writeInt(u64, out[magic.len + 8 ..][0..8], self.bytes, .big);
        @memcpy(out[magic.len + 16 ..], &self.digest);
        return out;
    }
    fn decode(encoded: []const u8) !@This() {
        if (encoded.len != encoded_len or !std.mem.eql(u8, encoded[0..magic.len], magic)) return error.InvalidMetadataSnapshot;
        const value: @This() = .{
            .index = std.mem.readInt(u64, encoded[magic.len..][0..8], .big),
            .bytes = std.mem.readInt(u64, encoded[magic.len + 8 ..][0..8], .big),
            .digest = encoded[magic.len + 16 ..][0..32].*,
        };
        if (value.index == 0 or value.bytes == 0) return error.InvalidMetadataSnapshot;
        return value;
    }
};
fn encodeMetadataCheckpoint(value: AppliedMetadataCheckpoint) [checkpoint_encoded_len]u8 {
    var bytes: [checkpoint_encoded_len]u8 = undefined;
    std.mem.writeInt(u64, bytes[0..8], value.commit_index, .little);
    @memcpy(bytes[8..16], checkpoint_magic);
    bytes[16] = 1;
    bytes[17] = @backingInt(value.input_kind);
    std.mem.writeInt(u64, bytes[18..26], value.input_bytes, .little);
    return bytes;
}

test "initial child root receipt requires enrollment current reporter and exact live placement" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/root-receipt", .{tmp.sub_path});
    defer alloc.free(path);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = path });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const incarnation = "11111111111111111111111111111111".*;
    try store.applyStandaloneCommand(group_id, .{ .initialize_metadata_incarnation = incarnation });
    const seed: [32]u8 = @splat(9);
    const pair = try std.crypto.sign.Ed25519.KeyPair.generateDeterministic(seed);
    const root: @import("antfly_local_sources").storage_db_root_signing_identity.State = .{ .seed = seed, .root_incarnation = 7, .public_key = pair.public_key.toBytes() };
    var current: metadata.StoreRecord = .{ .store_id = 3, .node_id = 2, .reporter_incarnation = 4, .replica_root_incarnation = 7, .replica_root_public_key = root.public_key, .role = "data", .live = true };
    try store.applyStandaloneCommand(group_id, .{ .register_store = current });
    const replica: fk_initial_retirement.Replica = .{ .plan_id = @splat(1), .plan_digest = @splat(2), .child_table_id = 10, .group_id = 11, .range_id = 12, .node_id = 2, .store_id = 3, .store_incarnation = 4, .store_root_incarnation = 7, .replica_id = 5, .root_generation = 6 };
    var key_buf: [256]u8 = undefined;
    const live_key = try fk_initial_retirement.liveKey(&key_buf, group_id, replica.group_id, replica.node_id);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try txn.put(live_key, &try replica.encode());
        try txn.commit();
    }
    var receipt: @import("../../api/relational_fk_generation_publication.zig").InitialChildReceipt = .{ .plan_id = replica.plan_id, .child_table_id = 10, .child_group_id = 11, .action = .provision, .namespace = .{ .table_id = 10, .shard_id = 11, .range_id = 12 }, .plan_digest = replica.plan_digest, .schema_version = 1, .schema_digest = @splat(3), .public_schema_json_digest = @splat(4), .catalog_digest = @splat(5), .row_count = 0, .applied_term = 2, .applied_index = 9 };
    {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
    }
    const identity: store_root_enrollment.Identity = .{ .metadata_incarnation = incarnation, .node_id = 2, .store_id = 3, .root_incarnation = 7, .public_key = root.public_key };
    receipt.root_attestation = try (@import("../initial_child_root_attestation.zig").Attestation{ .identity = identity, .reporter_incarnation = 4, .replica_id = 5, .root_generation = 6, .signature = undefined }).sign(root, receipt.digest());
    {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
    }
    const enrollment = try store_root_enrollment.Request.sign(identity, seed);
    const encoded = try std.json.Stringify.valueAlloc(alloc, enrollment, .{});
    defer alloc.free(encoded);
    try store.applyStandaloneCommand(group_id, .{ .apply_store_root_enrollment = encoded });
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        try store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt);
        var forged = receipt;
        forged.applied_index += 1;
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, forged));
        var changed = replica;
        changed.root_generation += 1;
        try txn.put(live_key, &try changed.encode());
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
        changed = replica;
        changed.group_id += 1;
        try txn.put(live_key, &try changed.encode());
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
        try txn.delete(live_key);
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
    }
    current.reporter_incarnation += 1;
    try store.applyStandaloneCommand(group_id, .{ .register_store = current });
    {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
        receipt.root_attestation.?.reporter_incarnation = current.reporter_incarnation;
        receipt.root_attestation = try receipt.root_attestation.?.sign(root, receipt.digest());
        try store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt);
    }
    // Reporter restart is allowed for the same enrolled physical root, but a
    // replacement root cannot inherit its receipt or admitted generation.
    current.replica_root_incarnation += 1;
    try store.applyStandaloneCommand(group_id, .{ .register_store = current });
    {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        try std.testing.expectError(error.InitialChildRootReceiptChanged, store.requireInitialChildRootReceiptTxn(&txn, group_id, receipt));
    }
}

test "relational index publication reverse cohort verification uses three fixed reads and consumes borrowed buffers" {
    const Reader = struct {
        head: [index_progress.Head.encoded_len]u8,
        owner: [index_progress.OwnerState.encoded_len]u8,
        scratch: [index_progress.OwnerState.encoded_len]u8 = undefined,
        calls: usize = 0,
        fail: bool = false,
        pub fn get(self: *@This(), key: []const u8) anyerror![]const u8 {
            self.calls += 1;
            if (self.fail) return error.StorageReadFailed;
            var buf: [160]u8 = undefined;
            const bytes: []const u8 = switch (self.calls) {
                1 => blk: {
                    try std.testing.expectEqualStrings(try index_publication.headKey(&buf, 13, 101), key);
                    break :blk &self.head;
                },
                2 => blk: {
                    try std.testing.expectEqualStrings(try index_publication.ownerGroupKey(&buf, 13, 101, 301), key);
                    break :blk &.{ 0, 0 };
                },
                3 => blk: {
                    try std.testing.expectEqualStrings(try index_publication.ownerKey(&buf, 13, 101, 0), key);
                    break :blk &self.owner;
                },
                else => return error.UnexpectedRead,
            };
            @memcpy(self.scratch[0..bytes.len], bytes);
            return self.scratch[0..bytes.len];
        }
    };
    var head: index_progress.Head = .{ .plan_id = @splat(1), .plan_digest = @splat(2), .candidate_digest = @splat(3), .reservation_digest = @splat(4), .table_id = 101, .owner_count = 1 };
    const owner: index_progress.OwnerState = .{ .owner = .{ .plan_id = head.plan_id, .plan_digest = head.plan_digest, .ordinal = 0, .group_id = 301, .namespace = .{ .table_id = 101, .shard_id = 301, .range_id = 301 }, .authority = .raft, .fence_digest = @splat(5) } };
    var reader: Reader = .{ .head = try head.encode(), .owner = try owner.encode() };
    var value: [16]u8 = undefined;
    std.mem.writeInt(u64, value[0..8], 301, .little);
    std.mem.writeInt(u64, value[8..16], 101, .little);
    var buf: [160]u8 = undefined;
    try IndexPublicationVerification.verifyRange(&reader, 13, try rangeKeyForGroup(&buf, 13, 301), &value);
    try std.testing.expectEqual(@as(usize, 3), reader.calls);
    reader.calls = 0;
    try std.testing.expectError(error.InvalidCatalogRecord, IndexPublicationVerification.verifyRange(&reader, 13, try rangeKeyForGroup(&buf, 13, 302), &value));
    try std.testing.expectEqual(@as(usize, 1), reader.calls);
    reader.calls = 0;
    reader.fail = true;
    try std.testing.expectError(error.StorageReadFailed, IndexPublicationVerification.verifyRange(&reader, 13, try rangeKeyForGroup(&buf, 13, 301), &value));
    reader.fail = false;
    reader.calls = 0;
    head.phase = .published;
    head.counts = .{ 1, 1, 1, 1, 1, 0, 0 };
    reader.head = try head.encode();
    try IndexPublicationVerification.verifyRange(&reader, 13, try rangeKeyForGroup(&buf, 13, 302), &value);
    try std.testing.expectEqual(@as(usize, 1), reader.calls);
}

test "relational index publication range enumeration stops before excess allocation or unbounded scanning" {
    const Cursor = struct {
        visits: usize = 0,
        fail: bool = false,
        const Row = struct { key: []const u8, value: []const u8 };
        fn seekAtOrAfter(self: *@This(), _: []const u8) !?Row {
            if (self.fail) return error.StorageReadFailed;
            self.visits = 1;
            return .{ .key = "range:1", .value = &.{ 7, 0, 0, 0, 0, 0, 0, 0 } };
        }
        fn next(self: *@This()) !?Row {
            self.visits += 1;
            return if (self.visits == 2) .{ .key = "range:2", .value = &.{ 8, 0, 0, 0, 0, 0, 0, 0 } } else null;
        }
    };
    var cursor: Cursor = .{};
    try std.testing.expectError(error.GenerationPublicationChanged, readTableRangeIdsBounded(std.testing.failing_allocator, &cursor, "range:", 0));
    try std.testing.expectEqual(@as(usize, 1), cursor.visits);
    cursor = .{};
    try std.testing.expectError(error.GenerationPublicationChanged, readTableRangeIdsBounded(std.testing.allocator, &cursor, "range:", 1));
    try std.testing.expectEqual(@as(usize, 2), cursor.visits);
    cursor = .{};
    const ids = try readTableRangeIdsBounded(std.testing.allocator, &cursor, "range:", 2);
    defer std.testing.allocator.free(ids);
    try std.testing.expectEqualSlices(u64, &.{ 7, 8 }, ids);
    cursor = .{ .fail = true };
    try std.testing.expectError(error.StorageReadFailed, readTableRangeIdsBounded(std.testing.failing_allocator, &cursor, "range:", 0));
}

