            defer metadata_table_manager.freeTable(a, current);
            try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(current, plan.before));
        }
        const Fault = enum { head_missing, reader_requirements_changed, owner_missing, active_missing, active_substituted, extra_owner, lock_missing, wrong_counter, orphan_group, owner_substituted, plan_substituted, orphan_index_lock, orphan_lock_group, table_substituted, range_substituted, directory_missing, directory_substituted, extra_directory, extra_range, aliased_range, stale_plan_incarnation, foreign_plan_namespace, rebound_table, rebound_namespace, rebound_database, inputs_missing, inputs_corrupt, dispatch_missing, dispatch_corrupt, extra_inputs, extra_dispatch };
        inline for (std.meta.tags(Fault)) |fault| {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            var buf: [160]u8 = undefined;
            switch (fault) {
                .inputs_missing => try txn.delete(try index_publication.inputsKey(&buf, group, plan.before.table_id)),
                .inputs_corrupt => try txn.put(try index_publication.inputsKey(&buf, group, plan.before.table_id), "corrupt"),
                .dispatch_missing => try txn.delete(try index_publication.dispatchKey(&buf, group, plan.before.table_id, 0)),
                .dispatch_corrupt => try txn.put(try index_publication.dispatchKey(&buf, group, plan.before.table_id, 0), "corrupt"),
                .extra_inputs => try txn.put(try index_publication.inputsKey(&buf, group, 999), "orphan"),
                .extra_dispatch => try txn.put(try index_publication.dispatchKey(&buf, group, plan.before.table_id, 1), "orphan"),
                .head_missing => try txn.delete(try index_publication.headKey(&buf, group, plan.before.table_id)),
                .reader_requirements_changed => {
                    const key = try index_publication.headKey(&buf, group, plan.before.table_id);
                    var head = try index_progress.Head.decode(try txn.get(key));
                    // Valid pair and checksum, but not the admitted plan's pair.
                    head.reader_requirements = .{ .semantic_version = 11, .encoding_version = 17 };
                    try txn.put(key, &try head.encode());
                },
                .owner_missing => try txn.delete(try index_publication.ownerKey(&buf, group, plan.before.table_id, 0)),
                .active_missing => try txn.delete(try index_publication.activeKey(&buf, group, plan.before.table_id)),
                .active_substituted => try txn.put(try index_publication.activeKey(&buf, group, plan.before.table_id), &@as([16]u8, @splat(9))),
                .extra_owner => try txn.put(try index_publication.ownerKey(&buf, group, plan.before.table_id, 1), "orphan"),
                .lock_missing => try txn.delete(try fk_generation_publication.tableLockKey(&buf, group, plan.before.table_id)),
                .wrong_counter => {
                    const key = try index_publication.headKey(&buf, group, plan.before.table_id);
                    var head = try index_progress.Head.decode(try txn.get(key));
                    head.counts[0] = 1;
                    try txn.put(key, &try head.encode());
                },
                .orphan_group => try txn.put(try index_publication.activeKey(&buf, group + 1, plan.before.table_id), &plan.id),
                .owner_substituted => {
                    const key = try index_publication.ownerKey(&buf, group, plan.before.table_id, 0);
                    var owner = try index_progress.OwnerState.decode(try txn.get(key));
                    owner.owner.group_id += 1;
                    try txn.put(key, &try owner.encode());
                },
                .plan_substituted => {
                    var substitute = plan;
                    substitute.id = @splat(9);
                    var prepared = try substitute.prepare(a);
                    defer prepared.deinit();
                    try txn.put(try index_publication.planKey(&buf, group, plan.before.table_id), prepared.frame);
                },
                .orphan_index_lock, .orphan_lock_group => {
                    const lock_group = if (fault == .orphan_lock_group) group + 1 else group;
                    try txn.put(try fk_generation_publication.tableLockKey(&buf, lock_group, 999), &RaftApplyStore.fkTableLockValue(.index_build, plan.id));
                },
                .table_substituted => {
                    var changed = plan.before;
                    changed.description = "changed while lifecycle-locked";
                    const encoded = try encodeTableRecord(a, changed);
                    defer a.free(encoded);
                    try txn.put(try tableKeyForGroup(&buf, group, changed.table_id), encoded);
                },
                .range_substituted => {
                    var changed = plan.owners[0].range;
                    changed.doc_identity_range_id += 1;
                    const encoded = try encodeRangeRecord(a, changed);
                    defer a.free(encoded);
                    try txn.put(try rangeKeyForGroup(&buf, group, changed.group_id), encoded);
                },
                .directory_missing => try txn.delete(try index_publication.ownerGroupKey(&buf, group, plan.before.table_id, plan.owners[0].range.group_id)),
                .directory_substituted => try txn.put(try index_publication.ownerGroupKey(&buf, group, plan.before.table_id, plan.owners[0].range.group_id), &.{ 0, 1 }),
                .extra_directory => try txn.put(try index_publication.ownerGroupKey(&buf, group, plan.before.table_id, 999), &.{ 0, 0 }),
                .extra_range, .aliased_range => {
                    var changed = plan.owners[0].range;
                    if (fault == .extra_range) changed.group_id += 1;
                    const encoded = try encodeRangeRecord(a, changed);
                    defer a.free(encoded);
                    try txn.put(try rangeKeyForGroup(&buf, group, plan.owners[0].range.group_id + 1), encoded);
                },
                .stale_plan_incarnation, .foreign_plan_namespace => {
                    var changed = plan;
                    if (fault == .stale_plan_incarnation) changed.table_guard.incarnation[0] ^= 1 else changed.namespace_id += 1;
                    var prepared = try changed.prepare(a);
                    defer prepared.deinit();
                    // Keep the immutable frame, head and owners self-consistent:
                    // this is stale authority, not a checksum-substitution test.
                    try txn.put(try index_publication.planKey(&buf, group, plan.before.table_id), prepared.frame);
                    try txn.put(try index_publication.inputsKey(&buf, group, plan.before.table_id), prepared.inputs);
                    try txn.put(try index_publication.headKey(&buf, group, plan.before.table_id), &try prepared.head.encode());
                    for (prepared.owners, 0..) |owner, i| {
                        try txn.put(try index_publication.ownerKey(&buf, group, plan.before.table_id, @intCast(i)), &try owner.encode());
                        try txn.put(try index_publication.dispatchKey(&buf, group, plan.before.table_id, @intCast(i)), prepared.dispatch[i]);
                    }
                },
                .rebound_table, .rebound_namespace, .rebound_database => {
                    const resource: system_catalog.Resource = switch (fault) {
                        .rebound_table => .{ .kind = .table, .id = plan.before.table_id, .parent_id = plan.namespace_id + 1, .name = plan.table_guard.logical_table, .storage_name = plan.before.name },
                        .rebound_namespace => .{ .kind = .namespace, .id = plan.namespace_id, .parent_id = system_catalog.default_database_id, .name = "different_namespace" },
                        .rebound_database => .{ .kind = .database, .id = system_catalog.default_database_id, .name = "different_database" },
                        else => unreachable,
                    };
                    const key = try std.fmt.bufPrint(&buf, "\x00\x00__metadata__:system_catalog:{d}:record:{s}:{d}", .{ group, @tagName(resource.kind), resource.id });
                    const encoded = try std.json.Stringify.valueAlloc(a, resource, .{});
                    defer a.free(encoded);
                    try txn.put(key, encoded);
                },
            }
            switch (fault) {
                .stale_plan_incarnation, .foreign_plan_namespace, .rebound_table, .rebound_namespace, .rebound_database => try std.testing.expectError(error.InvalidCatalogRecord, IndexPublicationVerification.verifyTableCut(a, &txn, group, plan.before.table_id)),
                else => {},
            }
            try std.testing.expectError(error.InvalidMetadataHACheckpoint, verifyRelationCheckpointTxn(a, &txn));
            if (fault != .orphan_group and fault != .orphan_lock_group) {
                // Incoming snapshots validate the same new record/cohort
                // invariants before any staging database is published.
                const rows = try store.collectMetadataSnapshotRowsTxn(a, &txn, group, null, false);
                defer freeMetadataSnapshotRows(a, rows);
                try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, group, rows));
            }
        }
        {
            // Isolate stable-ID authority for nondefault catalog bindings.
            // The enclosing campaign verifies full registry recovery separately;
            // this deliberately unpublished transaction cannot alter its root.
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            var bound = plan;
            bound.namespace_id = 1002;
            bound.table_guard.target = .{ .database = "tenant", .namespace = "sales", .name = "visible_items" };
            bound.table_guard.logical_table = "visible_items";
            var prepared = try bound.prepare(a);
            defer prepared.deinit();
            var buf: [192]u8 = undefined;
            for ([_]system_catalog.Resource{
                .{ .kind = .database, .id = 1001, .name = "tenant" },
                .{ .kind = .namespace, .id = 1002, .parent_id = 1001, .name = "sales" },
                .{ .kind = .table, .id = plan.before.table_id, .parent_id = 1002, .name = "visible_items", .storage_name = plan.before.name },
            }) |resource| {
                const key = try std.fmt.bufPrint(&buf, "\x00\x00__metadata__:system_catalog:{d}:record:{s}:{d}", .{ group, @tagName(resource.kind), resource.id });
                const encoded = try std.json.Stringify.valueAlloc(a, resource, .{});
                defer a.free(encoded);
                try txn.put(key, encoded);
            }
            try txn.put(try index_publication.planKey(&buf, group, plan.before.table_id), prepared.frame);
            try txn.put(try index_publication.inputsKey(&buf, group, plan.before.table_id), prepared.inputs);
            try txn.put(try index_publication.headKey(&buf, group, plan.before.table_id), &try prepared.head.encode());
            for (prepared.owners, 0..) |owner, i| {
                try txn.put(try index_publication.ownerKey(&buf, group, plan.before.table_id, @intCast(i)), &try owner.encode());
                try txn.put(try index_publication.dispatchKey(&buf, group, plan.before.table_id, @intCast(i)), prepared.dispatch[i]);
            }
            _ = try IndexPublicationVerification.verifyTableCut(a, &txn, group, plan.before.table_id);
        }
        try verifyRelationRecoveryForTest(&store, a, group);
    }
}

test "relational index publication terminal replacement bounds owner retention and CASes the exact predecessor" {
    // Storage-component qualification only: synthetic kernel cleanup receipts
    // below are not authentication or evidence of native owner cancellation.
    // Never commit this deliberately unadopted fixture to a serving catalog.
    const a = std.testing.allocator;
    const group = group_ids.main_metadata_group_id;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/index-retention", .{tmp.sub_path});
    defer a.free(path);
    var store = try RaftApplyStore.init(a, .{ .root_dir = path });
    defer store.deinit();
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const single = try index_publication.testing.plan(arena.allocator());
    var multiple = single;
    const owners = try arena.allocator().alloc(index_publication.Owner, 2);
    owners[0] = single.owners[0];
    owners[0].range.end_key = "m";
    owners[1] = single.owners[0];
    owners[1].range.start_key = "m";
    owners[1].range.group_id = 302;
    owners[1].range.range_id = 302;
    owners[1].range.doc_identity_shard_id = 302;
    owners[1].range.doc_identity_range_id = 302;
    owners[1].namespace.shard_id = 302;
    owners[1].namespace.range_id = 302;
    multiple.owners = owners;
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    var expected: ?[index_progress.Head.encoded_len]u8 = null;
    var buf: [160]u8 = undefined;
    for (1..33) |attempt| {
        var plan = if (attempt % 2 == 0) single else multiple;
        plan.id = @splat(0);
        std.mem.writeInt(u64, plan.id[0..8], attempt, .little);
        // Both halves become exact transition/attempt identities. Retain all
        // 32 distinct retries and the alternating full owner cohorts.
        std.mem.writeInt(u64, plan.id[8..16], attempt, .little);
        var prepared = try plan.prepare(a);
        defer prepared.deinit();
        if (expected) |old| {
            var stale = old;
            stale[0] ^= 1;
            try std.testing.expectError(error.GenerationPublicationChanged, prepared.stageBegin(&txn, group, stale));
        }
        try prepared.stageBegin(&txn, group, expected);
        _ = try index_publication.verifyJob(a, &txn, group, plan.before.table_id);
        inline for (.{ index_publication.ownersPrefix, index_publication.ownerGroupsPrefix, index_publication.dispatchPrefix }) |prefix_fn| {
            var cursor = try txn.openCursor();
            defer cursor.close();
            const prefix = try prefix_fn(&buf, group);
            var row = try cursor.seekAtOrAfter(prefix);
            var count: usize = 0;
            while (row) |item| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, item.key, prefix)) break;
                count += 1;
            }
            try std.testing.expectEqual(plan.owners.len, count);
        }
        const head_key = try index_publication.headKey(&buf, group, plan.before.table_id);
        var head = try index_progress.Head.decode(try txn.get(head_key));
        head = try head.cancel(head.revision, .requested);
        try txn.put(head_key, &try head.encode());
        for ([_]index_progress.Action{ .canceled, .cancel_released }) |action| {
            for (0..plan.owners.len) |i| {
                var head_buf: [160]u8 = undefined;
                var owner_buf: [160]u8 = undefined;
                const hk = try index_publication.headKey(&head_buf, group, plan.before.table_id);
                const ok = try index_publication.ownerKey(&owner_buf, group, plan.before.table_id, @intCast(i));
                head = try index_progress.Head.decode(try txn.get(hk));
                const owner = try index_progress.OwnerState.decode(try txn.get(ok));
                var receipt: index_progress.Receipt = .{
                    .owner = owner.owner,
                    .action = action,
                    .position = .{ .raft = .{ .term = 1, .index = head.revision + 100 } },
                    .candidate_digest = head.candidate_digest,
                    .reservation_digest = head.reservation_digest,
                    .evidence_digest = @splat(7),
                };
                var cancellation_witness: ?index_publication.CancellationWitness = null;
                if (action == .canceled) {
                    var dispatch = try index_publication.readDispatch(a, &txn, group, owner.owner);
                    defer dispatch.deinit();
                    const d = dispatch.value;
                    const permission: index_publication.OwnerDecision = .{ .metadata_group_id = group, .metadata_incarnation = std.fmt.bytesToHex(plan.table_guard.incarnation, .lower), .head = head, .owner = owner, .disposition = .execute, .dispatch = d };
                    const intent = try permission.raftCancellationIntent();
                    const record: @import("antfly_local_sources").storage_db_relational_index_owner_job.Canceled = .{
                        .binding = .{ .id = intent.id, .plan_digest = intent.plan_digest, .owner_digest = intent.owner_digest, .ordinal = intent.ordinal, .authority = .raft, .phase = .reserved, .fence = intent.fence, .integrity_before = intent.fence.catalog_digest, .integrity_reserved = intent.reservation_digest, .integrity_candidate = intent.candidate_digest, .schema_before = d.native_schema_digest, .inputs_digest = d.native_inputs_digest, .physical_before = null, .physical_reserved = .{ .revision = 2, .schema_version = 1, .blob_digest = @splat(4) }, .physical_candidate = .{ .revision = 2, .schema_version = 2, .blob_digest = @splat(5) }, .index = .{ .generation = 2, .slot = 0 } },
                        .intent_position = .{ .raft = .{ .term = 1, .index = 1 } },
                        .cleanup = .{ .intent = intent, .claim_allocation = d.native_claim_allocation, .position = .{ .raft = .{ .term = 1, .index = 2 } } },
                        .position = receipt.position,
                    };
                    cancellation_witness = .{ .record = record };
                    receipt = try record.receipt();
                } else {
                    const accepted = try index_publication.storedProof(a, try txn.get(try index_publication.proofKey(&buf, group, plan.before.table_id, @intCast(i), .canceled)), head, owner, .canceled);
                    const grant: index_publication.CancellationReleaseGrant = .{ .canceled = accepted.cancellation.?.record, .cleanup_proof = accepted.signed.proof, .decision_digest = try index_publication.cancellationReleaseDecisionDigest(group, accepted.signed.proof.identity.metadata_incarnation, head) };
                    receipt = try grant.intent().receiptAt(receipt.position);
                }
                const signed = try index_publication.testing.signedHistoricalReceipt(receipt, plan.table_guard.incarnation);
                const enrollment_key = try store_root_enrollment.key(&buf, group, signed.proof.identity.store_id, signed.proof.identity.root_incarnation);
                if ((try RaftApplyStore.stagingGet(&txn, enrollment_key)) == null) {
                    const enrollment_bytes = try std.json.Stringify.valueAlloc(a, signed.proof.identity, .{});
                    defer a.free(enrollment_bytes);
                    try txn.put(enrollment_key, enrollment_bytes);
                }
                var ack = try index_progress.PreparedAck.prepare(&try head.encode(), &try owner.encode(), head.revision, receipt);
                var next_owner = try index_progress.OwnerState.decode(&ack.next_owner);
                next_owner.attestations[@backingInt(action)] = try signed.commitment();
                ack.next_owner = try next_owner.encode();
                try ack.stage(&txn, hk, ok);
                const proof_bytes = try index_publication.StoredProof.encode(signed, null, null, cancellation_witness, null);
                try txn.put(try index_publication.proofKey(&buf, group, plan.before.table_id, @intCast(i), action), proof_bytes.slice());
            }
        }
        try txn.delete(try index_publication.activeKey(&buf, group, plan.before.table_id));
        try @import("../table_lifecycle_lock.zig").release(&txn, group, plan.before.table_id, .{ .kind = .index_build, .id = plan.id });
        head = try index_publication.verifyJob(a, &txn, group, plan.before.table_id);
        try std.testing.expectEqual(index_progress.Phase.canceled, head.phase);
        expected = try head.encode();
        try std.testing.expectError(error.GenerationPublicationChanged, prepared.stageBegin(&txn, group, expected));
    }
    // Completed history must not freeze a later legitimate table definition or
    // require its historical ranges to remain in the current topology.
    var later_table = single.before;
    later_table.description = "updated after terminal completion";
    const later_encoded = try encodeTableRecord(a, later_table);
    defer a.free(later_encoded);
    try txn.put(try tableKeyForGroup(&buf, group, later_table.table_id), later_encoded);
    const retained = try IndexPublicationVerification.verifyTableCut(a, &txn, group, later_table.table_id);
    try std.testing.expectEqual(index_progress.Phase.canceled, retained.phase);
    try std.testing.expect(try index_publication.deleteTerminal(&txn, group, single.before.table_id));
    try std.testing.expect(!try index_publication.deleteTerminal(&txn, group, single.before.table_id));
    inline for (.{ index_publication.planPrefix, index_publication.headPrefix, index_publication.activePrefix, index_publication.ownersPrefix, index_publication.ownerGroupsPrefix, index_publication.inputsPrefix, index_publication.dispatchPrefix }) |prefix_fn| {
        try std.testing.expect(!try txn.hasPrefix(try prefix_fn(&buf, group)));
    }
}

test "system catalog relation namespace transaction activated generated FK begin reserves both owners and recovers its name guard" {
    const a = std.testing.allocator;
    const group = group_ids.main_metadata_group_id;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/named-fk", .{tmp.sub_path});
    defer a.free(path);
    const identity = "11111111111111111111111111111111".*;
    const before_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const parent_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"parent_id_key","columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const child: metadata.TableRecord = .{ .table_id = 101, .name = "child", .schema_json = before_json };
    const parent: metadata.TableRecord = .{ .table_id = 201, .name = "parent", .schema_json = parent_json };
    const child_range: metadata.RangeRecord = .{ .table_id = 101, .group_id = 301, .range_id = 301, .doc_identity_shard_id = 301, .doc_identity_range_id = 301, .start_key = "" };
    const parent_range: metadata.RangeRecord = .{ .table_id = 201, .group_id = 401, .range_id = 401, .doc_identity_shard_id = 401, .doc_identity_range_id = 401, .start_key = "" };
    var id: fk_generation_publication.Id = @splat(0);
    std.mem.writeInt(u64, id[0..8], 7, .little);
    std.mem.writeInt(u64, id[8..16], 1, .little);
    const topology = @import("antfly_local_sources").storage_db_relational_integrity_topology_contract;
    const child_fence: topology.Fence = .{ .transition_id = 7, .attempt = 1, .peer_group_id = 301, .owner_group_id = 301, .role = .child_generation_source, .namespace = .{ .table_id = 101, .shard_id = 301, .range_id = 301 }, .catalog_digest = @splat(1) };
    const parent_fence: topology.Fence = .{ .transition_id = 7, .attempt = 1, .peer_group_id = 401, .owner_group_id = 401, .role = .child_generation_parent, .namespace = .{ .table_id = 201, .shard_id = 401, .range_id = 401 }, .catalog_digest = @splat(2) };
    var expected_digest: [32]u8 = undefined;
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = identity });
        try store.applyStandaloneCommand(group, .{ .upsert_table = parent });
        try store.applyStandaloneCommand(group, .{ .upsert_table = child });
        try store.applyStandaloneCommand(group, .{ .upsert_range = parent_range });
        try store.applyStandaloneCommand(group, .{ .upsert_range = child_range });
        const activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{ .version = topology_protocol.constraint_occupancy_version, .incarnation = identity, .member_count = 3, .membership_fingerprint = @splat(7) }, .{});
        defer a.free(activation);
        try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
        try adoptRelationWriterForTest(&store, a, group);
        _ = try publishLiveRelationRootWithCoverageForTest(&store, a, group, .constraint_names);
        var guard: system_catalog.RelationMutationGuard = undefined;
        {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
            guard = .{ .target = .{ .name = child.name }, .logical_table = child.name, .owner = (try live.getClaim(.{ .namespace_id = system_catalog.default_namespace_id, .name = child.name })).?, .incarnation = live.root.epoch.incarnation };
        }
        const fragment = "{\"foreign_keys\":[{\"name\":\"anonymous\",\"child_columns\":[\"id\"],\"parent_table\":\"parent\",\"parent_columns\":[\"id\"]}]}";
        var names = try store.prepareGeneratedConstraintAddition(a, group, guard, fragment, &.{"anonymous"}, .{});
        defer names.deinit();
        try std.testing.expectEqualStrings("child_id_fkey", names.admission.names[0].name);
        guard.constraint_name_admission = names.admission;
        var after = try std.json.parseFromSlice(std.json.Value, a, names.schema_json, .{});
        defer after.deinit();
        after.value.object.getPtr("version").?.* = .{ .integer = 2 };
        const after_json = try std.json.Stringify.valueAlloc(a, after.value, .{});
        defer a.free(after_json);
        var parsed = try @import("antfly_local_sources").schema_mod.parseValidatedTableSchema(a, before_json);
        defer parsed.deinit(a);
        var catalog = try fk_generation_publication.compileCatalog(a, parsed, child.table_id, null);
        defer catalog.deinit();
        const before_b64 = try a.alloc(u8, std.base64.standard.Encoder.calcSize(catalog.value.len));
        defer a.free(before_b64);
        _ = std.base64.standard.Encoder.encode(before_b64, catalog.value);
        const transitions = try fk_generation_publication.deriveTransitions(a, child.table_id, child.name, before_json, after_json, before_b64);
        defer fk_generation_publication.freeDerivedTransitions(a, transitions);
        try std.testing.expectEqual(@as(usize, 1), transitions.len);
        var child_after = child;
        child_after.schema_json = after_json;
        const plan: fk_generation_publication.Plan = .{ .id = id, .child_before = child, .child_after = child_after, .child_catalog_before_b64 = before_b64, .child_ranges = &.{child_range}, .child_fences = &.{child_fence}, .parents = &.{.{ .table = parent, .ranges = &.{parent_range}, .fences = &.{parent_fence}, .transitions = &.{transitions[0].transition} }}, .constraint_name_guard = guard };
        try plan.validate(a);
        expected_digest = try plan.digest(a);
        try store.preflightFkGenerationNameAdmission(group, plan);
        const begin = try std.json.Stringify.valueAlloc(a, fk_generation_publication.Command{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 0, .action = .begin, .plan = plan }, .{});
        defer a.free(begin);
        try store.applyStandaloneCommand(group, .{ .apply_fk_generation_publication = begin });
        try verifyRelationRecoveryForTest(&store, a, group);
    }
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer store.deinit();
        try verifyRelationRecoveryForTest(&store, a, group);
        const bytes = try store.fkGenerationPublicationStatusJson(a, group, child.table_id);
        defer a.free(bytes);
        var recovered = try std.json.parseFromSlice(fk_generation_publication.Publication, a, bytes, .{});
        defer recovered.deinit();
        try recovered.value.validate(a);
        try std.testing.expectEqual(.fencing_child, recovered.value.phase);
        try std.testing.expectEqualDeep(expected_digest, recovered.value.plan_digest);
        try std.testing.expectEqualStrings("child_id_fkey", recovered.value.plan.constraint_name_guard.?.constraint_name_admission.?.names[0].name);
        {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            for ([_]u64{ child.table_id, parent.table_id }) |table_id| try std.testing.expectEqual(RaftApplyStore.FkTableLockKind.generation, (try store.fkTableLockKindTxn(&read, group, table_id)).?);
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
            try std.testing.expect(try live.nameOccupied(system_catalog.default_namespace_id, "child_id_fkey", false));
        }
        // Cancellation is not completion. No invented owner receipt may
        // release the name or either generation lock ahead of real owners.
        const cancel = try std.json.Stringify.valueAlloc(a, fk_generation_publication.Command{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 1, .action = .cancel }, .{});
        defer a.free(cancel);
        try store.applyStandaloneCommand(group, .{ .apply_fk_generation_publication = cancel });
    }
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer store.deinit();
        try verifyRelationRecoveryForTest(&store, a, group);
        const bytes = try store.fkGenerationPublicationStatusJson(a, group, child.table_id);
        defer a.free(bytes);
        var recovered = try std.json.parseFromSlice(fk_generation_publication.Publication, a, bytes, .{});
        defer recovered.deinit();
        try recovered.value.validate(a);
        try std.testing.expectEqual(.canceling, recovered.value.phase);
        try std.testing.expectEqual(@as(u64, 2), recovered.value.revision);
        try std.testing.expectEqualDeep(expected_digest, recovered.value.plan_digest);
        var read = try store.store.beginReadTxn();
        defer read.abort();
        for ([_]u64{ child.table_id, parent.table_id }) |table_id| try std.testing.expectEqual(RaftApplyStore.FkTableLockKind.generation, (try store.fkTableLockKindTxn(&read, group, table_id)).?);
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
        try std.testing.expect(try live.nameOccupied(system_catalog.default_namespace_id, "child_id_fkey", false));
    }
}

test "system catalog relation namespace transaction FK generation publication begins durably and rejects stale CAS and topology drift" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/fk-generation-publication", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    try store.applyStandaloneCommand(group_id, .{ .initialize_metadata_incarnation = "11111111111111111111111111111111".* });
    const old_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"fk","child_columns":["id"],"parent_table":"parent","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const new_json =
        \\{"version":2,"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"fk","child_columns":["id"],"parent_table":"parent","parent_columns":["id"],"on_delete":"cascade"}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const parent: metadata.TableRecord = .{ .table_id = 201, .name = "parent" };
    const child: metadata.TableRecord = .{ .table_id = 101, .name = "child", .schema_json = old_json };
    const child_after: metadata.TableRecord = .{ .table_id = 101, .name = "child", .schema_json = new_json };
    const child_range: metadata.RangeRecord = .{ .table_id = 101, .group_id = 301, .range_id = 301, .doc_identity_shard_id = 301, .doc_identity_range_id = 301, .start_key = "" };
    const parent_range: metadata.RangeRecord = .{ .table_id = 201, .group_id = 401, .range_id = 401, .doc_identity_shard_id = 401, .doc_identity_range_id = 401, .start_key = "" };
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = parent });
    try store.applyStandaloneCommand(group_id, .{ .upsert_range = parent_range });
    // The public physical-create Raft action must never install an FK-bearing
    // child without accepted parent generations.
    {
        var attempted_create = try store.store.beginWriteTxn();
        defer attempted_create.abort();
        try store.applyTableTopologyMutationTxn(&attempted_create, group_id, .{ .create = .{
            .table = child,
            .expected_transition_generation = 0,
            .ranges = &.{child_range},
        } });
        var absent_buf: [160]u8 = undefined;
        try std.testing.expectError(error.NotFound, attempted_create.get(try tableKeyForGroup(&absent_buf, group_id, child.table_id)));
    }
    // Seed an already accepted FK-bearing catalog directly; public create has
    // a distinct topology action with a fail-closed initial-generation guard.
    {
        var seed = try store.store.beginWriteTxn();
        errdefer seed.abort();
        var child_key_buf: [160]u8 = undefined;
        try store.putTableRecordTxn(&seed, group_id, try tableKeyForGroup(&child_key_buf, group_id, child.table_id), child);
        try seed.commit();
    }
    try store.applyStandaloneCommand(group_id, .{ .upsert_range = child_range });
    try adoptRelationWriterForTest(&store, alloc, group_id);
    // Adopt source tracking before the first pending generation. These writes
    // model the already capability-fenced adoption command, not writer serving.
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try relation_reconciliation.advanceSource(&txn, group_id);
        try txn.commit();
    }
    var parsed_schema = try @import("antfly_local_sources").schema_mod.parseValidatedTableSchema(alloc, old_json);
    defer parsed_schema.deinit(alloc);
    var old_catalog = try fk_generation_publication.compileCatalog(alloc, parsed_schema, child.table_id, null);
    defer old_catalog.deinit();
    const old_b64 = try alloc.alloc(u8, std.base64.standard.Encoder.calcSize(old_catalog.value.len));
    defer alloc.free(old_b64);
    _ = std.base64.standard.Encoder.encode(old_b64, old_catalog.value);
    const derived = try fk_generation_publication.deriveTransitions(alloc, child.table_id, child.name, old_json, new_json, old_b64);
    defer fk_generation_publication.freeDerivedTransitions(alloc, derived);
    try std.testing.expectEqual(@as(usize, 1), derived.len);
    var id: fk_generation_publication.Id = @splat(0);
    std.mem.writeInt(u64, id[0..8], 7, .little);
    std.mem.writeInt(u64, id[8..16], 1, .little);
    const child_fence: @import("antfly_local_sources").storage_db_relational_integrity_topology_contract.Fence = .{ .transition_id = 7, .attempt = 1, .peer_group_id = 301, .owner_group_id = 301, .role = .child_generation_source, .namespace = .{ .table_id = 101, .shard_id = 301, .range_id = 301 }, .catalog_digest = @splat(1) };
    const parent_fence: @import("antfly_local_sources").storage_db_relational_integrity_topology_contract.Fence = .{ .transition_id = 7, .attempt = 1, .peer_group_id = 401, .owner_group_id = 401, .role = .child_generation_parent, .namespace = .{ .table_id = 201, .shard_id = 401, .range_id = 401 }, .catalog_digest = @splat(2) };
    const plan: fk_generation_publication.Plan = .{
        .id = id,
        .child_before = child,
        .child_after = child_after,
        .child_catalog_before_b64 = old_b64,
        .child_ranges = &.{child_range},
        .child_fences = &.{child_fence},
        .parents = &.{.{ .table = parent, .ranges = &.{parent_range}, .fences = &.{parent_fence}, .transitions = &.{derived[0].transition} }},
    };
    var altered_index_plan = plan;
    altered_index_plan.child_after.indexes_json = "{\"unexpected\":{}}";
    try std.testing.expectError(error.InvalidGenerationPublication, altered_index_plan.validate(alloc));
    var named_plan = plan;
    var before_digest: [32]u8 = undefined;
    std.crypto.hash.Blake3.hash(old_json, &before_digest, .{});
    named_plan.constraint_name_guard = .{
        .target = .{ .name = "child" },
        .logical_table = "child",
        .owner = .{ .table_id = child.table_id, .schema_version = 1, .schema_digest = before_digest, .kind = .table },
        .incarnation = (try store.relationReconciliationWork(group_id)).epoch.?.incarnation,
        .constraint_name_admission = .{ .namespace_id = system_catalog.default_namespace_id, .names = &.{.{ .name = "fk", .kind = .foreign_key }} },
    };
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.preflightFkGenerationNameAdmission(group_id, named_plan));
    const named_begin = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.Command{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 0, .action = .begin, .plan = named_plan }, .{});
    defer alloc.free(named_begin);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_generation_publication = named_begin });
    // A committed lower-capability begin cannot reserve any owner or publish
    // a plan. The following legacy admission still succeeds independently.
    {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        var key_buf: [160]u8 = undefined;
        try std.testing.expectError(error.NotFound, read.get(try fk_generation_publication.key(&key_buf, group_id, child.table_id)));
        for ([_]u64{ child.table_id, parent.table_id }) |table_id| {
            try std.testing.expectError(error.NotFound, read.get(try fk_generation_publication.tableLockKey(&key_buf, group_id, table_id)));
        }
    }
    const begin = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.Command{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 0, .action = .begin, .plan = plan }, .{});
    defer alloc.free(begin);
    try store.preflightFkGenerationNameAdmission(group_id, plan);
    {
        // Corrupt lock ownership is not a defeated optimistic predicate.
        var key_buf: [160]u8 = undefined;
        const key = try fk_generation_publication.tableLockKey(&key_buf, group_id, parent.table_id);
        const bad_lock = RaftApplyStore.fkTableLockValue(.generation, @splat(0));
        var write = try store.store.beginWriteTxn();
        errdefer write.abort();
        try write.put(key, &bad_lock);
        try write.commit();
        try std.testing.expectError(error.InvalidGenerationPublication, store.preflightFkGenerationNameAdmission(group_id, plan));
        var cleanup = try store.store.beginWriteTxn();
        errdefer cleanup.abort();
        try cleanup.delete(key);
        try cleanup.commit();
    }
    // The child is unprotected, but an active policy on an external parent
    // still forbids an uncoupled generation plan. Reject before publishing a
    // 202/pending plan that its parent owner would be unable to install.
    const policy_owner: sql_policies.Publication.OwnerIdentity = .{ .group_id = parent_range.group_id, .descriptor_digest = @splat(3) };
    const policy_ack: sql_policies.Publication.OwnerAck = .{ .owner = policy_owner, .catalog_epoch = 2, .phase = .pending_install, .applied_term = 1, .applied_index = 1, .bundle_digest = @splat(4) };
    var serving_ack = policy_ack;
    serving_ack.phase = .serving_install;
    serving_ack.applied_index = 2;
    const parent_policy: sql_policies.Publication = .{
        .table_id = parent.table_id,
        .schema_version = 1,
        .schema_digest = @splat(5),
        .generation = 1,
        .catalog_epoch = 2,
        .phase = .active,
        .required_owners = &.{policy_owner},
        .acknowledged_owners = &.{policy_ack},
        .serving_acknowledged_owners = &.{serving_ack},
    };
    try parent_policy.validateShape();
    const policy_key = try std.fmt.allocPrint(alloc, "\x00\x00__metadata__:system_catalog:{d}:policy-publication:{d}", .{ group_id, parent.table_id });
    defer alloc.free(policy_key);
    const policy_bytes = try std.json.Stringify.valueAlloc(alloc, parent_policy, .{});
    defer alloc.free(policy_bytes);
    {
        var policy_txn = try store.store.beginWriteTxn();
        errdefer policy_txn.abort();
        try policy_txn.put(policy_key, policy_bytes);
        try policy_txn.commit();
    }
    try std.testing.expectError(error.RowPolicyUnsupported, store.applyStandaloneCommand(group_id, .{ .apply_fk_generation_publication = begin }));
    {
        var policy_txn = try store.store.beginWriteTxn();
        errdefer policy_txn.abort();
        try policy_txn.delete(policy_key);
        try policy_txn.commit();
    }
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_generation_publication = begin });
    try verifyRelationRecoveryForTest(&store, alloc, group_id);
    const reserved_epoch = blk: {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        const epoch = try RaftApplyStore.relationSourceEpochTxn(&txn, group_id);
        try std.testing.expectEqual(@as(u64, 2), epoch.revision);
        var cut = try RaftApplyStore.relationReconciliationSnapshot(alloc, &txn, group_id, child.table_id);
        defer cut.deinit();
        const entry = try cut.claims()[0].entry();
        try std.testing.expectEqual(@as(u32, 1), entry.active.?.schema_version);
        try std.testing.expectEqual(@as(u32, 2), entry.pending.?.schema_version);
        try std.testing.expectEqualSlices(u8, &id, &entry.pending.?.publication_id);
        var registry: relation_names.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .alloc = alloc, .group_id = group_id };
        try std.testing.expect((try registry.getEntry(cut.claims()[0].key)).?.eql(entry));
        break :blk epoch;
    };
    const reserved_source_cut = blk: {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        break :blk try RaftApplyStore.relationSourceCutTxn(alloc, &txn, group_id, reserved_epoch.revision);
    };
    // Actual page preparation and replica-side authority verification use the
    // same durable plan cut. Neither accepts a self-consistent forged owner.
    const relation_state = try relation_reconciliation.State.init(group_id, try relation_reconciliation.nextJobId(null), reserved_epoch);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try relation_reconciliation.start(&txn, &relation_state, reserved_epoch, null);
        try txn.commit();
    }
    var relation_page = try store.prepareRelationReconciliationPage(alloc, relation_state);
    defer relation_page.deinit();
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var journal = command_journal.Journal.initVerification(alloc, &txn, group_id, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        try relation_page.apply(&txn, reserved_epoch);
        try store.verifyReconciliationSourceOwnersTxn(&txn, group_id, &journal);
        const pending = for (relation_page.claims) |claim| {
            if (claim.pending != null) break claim;
        } else return error.TestExpectedPendingClaim;
        var forged = try pending.entry();
        forged.pending.?.schema_digest[0] ^= 1;
        var buf: [relation_reconciliation.max_cursor_bytes]u8 = undefined;
        try txn.put(try relation_reconciliation.candidateKey(&buf, &relation_state, pending.key), &(try forged.encode()));
        try std.testing.expectError(error.InvalidCatalogRecord, store.verifyReconciliationSourceOwnersTxn(&txn, group_id, &journal));
    }
    // A second source may reserve a name that an earlier page already added.
    // Such updates need the same durable-plan authority as fresh candidates.
    {
        const pending = for (relation_page.claims) |claim| {
            if (claim.pending != null) break claim;
        } else return error.TestExpectedPendingClaim;
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var buf: [relation_reconciliation.max_cursor_bytes]u8 = undefined;
        const key = try relation_reconciliation.candidateKey(&buf, &relation_state, pending.key);
        const before: relation_names.Entry = .{ .active = pending.owner };
        try txn.put(key, &(try before.encode()));
        var journal = command_journal.Journal.initVerification(alloc, &txn, group_id, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        const authentic = try pending.entry();
        try txn.put(key, &(try authentic.encode()));
        try std.testing.expect(journal.originals.get(key).? != null);
        try store.verifyReconciliationSourceOwnersTxn(&txn, group_id, &journal);
        var forged = authentic;
        forged.pending.?.schema_digest[0] ^= 1;
        try txn.put(key, &(try forged.encode()));
        try std.testing.expectError(error.InvalidCatalogRecord, store.verifyReconciliationSourceOwnersTxn(&txn, group_id, &journal));
        forged = authentic;
        forged.pending.?.publication_id[0] ^= 1;
        try txn.put(key, &(try forged.encode()));
        try std.testing.expectError(error.InvalidCatalogRecord, store.verifyReconciliationSourceOwnersTxn(&txn, group_id, &journal));
    }
    const status = try store.fkGenerationPublicationStatusJson(alloc, group_id, child.table_id);
    defer alloc.free(status);
    var publication = try std.json.parseFromSlice(fk_generation_publication.Publication, alloc, status, .{});
    defer publication.deinit();
    try std.testing.expectEqual(fk_generation_publication.Phase.fencing_child, publication.value.phase);
    try std.testing.expectEqual(@as(u64, 1), publication.value.revision);
    // A transient owner failure happens after the supervisor has advanced its
    // in-memory cursor, but before a durable child receipt is recorded. The
    // same unfinished publication must be returned on the next pass.
    const retry_work = try store.fkGenerationPublicationWorkJson(alloc, group_id, child.table_id);
    defer alloc.free(retry_work);
    var retry = try std.json.parseFromSlice(fk_generation_publication.Publication, alloc, retry_work, .{});
    defer retry.deinit();
    try std.testing.expectEqual(child.table_id, retry.value.plan.child_before.table_id);
    try std.testing.expectEqual(fk_generation_publication.Phase.fencing_child, retry.value.phase);
    const source_receipt: @import("../../api/relational_fk_generation_publication.zig").SourceReceipt = .{
        .plan_id = id,
        .child_table_id = child.table_id,
        .child_group_id = child_range.group_id,
        .action = .fence,
        .plan_digest = publication.value.plan_digest,
        .fence_digest = try @import("antfly_local_sources").storage_db_relational_integrity_generation_admission.sourceFenceDigest(child_fence),
        .before_schema_version = publication.value.child_identity.before_schema_version,
        .before_schema_digest = publication.value.child_identity.before_schema_digest,
        .before_catalog_digest = publication.value.child_identity.before_catalog_digest,
        .after_schema_version = publication.value.child_identity.after_schema_version,
        .after_schema_digest = publication.value.child_identity.after_schema_digest,
        .after_catalog_digest = publication.value.child_identity.after_catalog_digest,
        .applied_term = 1,
        .applied_index = 3,
    };
    const fenced_command = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.Command{
        .plan_id = id,
        .child_table_id = child.table_id,
        .expected_revision = 1,
        .action = .child_fenced,
        .source_receipt = source_receipt,
    }, .{});
    defer alloc.free(fenced_command);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_generation_publication = fenced_command });
    {
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        try std.testing.expect(reserved_epoch.eql(try RaftApplyStore.relationSourceEpochTxn(&txn, group_id)));
        try std.testing.expect(reserved_source_cut.eql(try RaftApplyStore.relationSourceCutTxn(alloc, &txn, group_id, reserved_epoch.revision)));
    }
    const advanced_json = try store.fkGenerationPublicationStatusJson(alloc, group_id, child.table_id);
    defer alloc.free(advanced_json);
    var advanced = try std.json.parseFromSlice(fk_generation_publication.Publication, alloc, advanced_json, .{});
    defer advanced.deinit();
    try std.testing.expectEqual(fk_generation_publication.Phase.staging_parents, advanced.value.phase);
    try std.testing.expectEqual(@as(usize, 1), advanced.value.child_fenced.len);
    try std.testing.expectEqualStrings(child.name, advanced.value.plan.child_before.name);
    {
        // Authenticated delta replay cannot substitute an immutable plan at
        // the same source epoch, even though receipt-only rewrites are valid.
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var journal = command_journal.Journal.initVerification(alloc, &txn, group_id, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        var key_buf: [160]u8 = undefined;
        const key = try fk_generation_publication.key(&key_buf, group_id, child.table_id);
        var receipt_only = advanced.value;
        receipt_only.revision += 1;
        const receipt_bytes = try std.json.Stringify.valueAlloc(alloc, receipt_only, .{});
        defer alloc.free(receipt_bytes);
        try txn.put(key, receipt_bytes);
        {
            var no_allocations = std.testing.FailingAllocator.init(alloc, .{ .fail_index = 0 });
            const saved_alloc = store.alloc;
            store.alloc = no_allocations.allocator();
            defer store.alloc = saved_alloc;
            var unchanged_plan = try store.capturedRelationsPlanTxn(&txn, group_id, &journal, false);
            defer unchanged_plan.deinit();
            try std.testing.expectEqual(@as(usize, 0), unchanged_plan.before.len);
            try std.testing.expectEqual(@as(usize, 0), unchanged_plan.after.len);
            try std.testing.expectEqual(@as(usize, 0), no_allocations.alloc_index);
        }
        try RaftApplyStore.verifyRelationSourceDeltaTxn(alloc, &txn, group_id, &journal);
        receipt_only.plan.id[0] ^= 1;
        const forged_bytes = try std.json.Stringify.valueAlloc(alloc, receipt_only, .{});
        defer alloc.free(forged_bytes);
        try txn.put(key, forged_bytes);
        try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.verifyRelationSourceDeltaTxn(alloc, &txn, group_id, &journal));
    }
    const stale = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.Command{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 9, .action = .cancel }, .{});
    defer alloc.free(stale);
    try std.testing.expectError(error.GenerationPublicationChanged, store.applyStandaloneCommand(group_id, .{ .apply_fk_generation_publication = stale }));
    var changed_parent = parent;
    changed_parent.description = "changed after plan begin";
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = changed_parent });
    var table_key_buf: [160]u8 = undefined;
    const parent_key = try tableKeyForGroup(&table_key_buf, group_id, parent.table_id);
    const still_locked = try store.store.get(alloc, parent_key);
    defer alloc.free(still_locked);
    const unchanged = try decodeTableRecord(alloc, still_locked);
    defer metadata_table_manager.freeTable(alloc, unchanged);
    try std.testing.expectEqualStrings(parent.description, unchanged.description);
    // Simulate a stale/corrupt projection slipping past an older writer: the
    // read-index owner decision still refuses to authorize an old descriptor.
    var injected = try store.store.beginWriteTxn();
    const forged_bytes = try encodeTableRecord(alloc, changed_parent);
    defer alloc.free(forged_bytes);
    try injected.put(parent_key, forged_bytes);
    try injected.commit();
    try std.testing.expectError(error.GenerationPublicationChanged, store.fkGenerationPublicationSourceDecisionJson(alloc, group_id, .{ .plan_id = id, .child_table_id = child.table_id, .child_table_name = child.name, .child_group_id = child_range.group_id, .action = .fence }));
    // Terminal transitions retire their work key atomically with the record.
    // Model both projections directly so the selector's read-side behavior
    // stays independent of the command path tested above.
    var terminal = publication.value;
    terminal.phase = .canceled;
    const terminal_bytes = try std.json.Stringify.valueAlloc(alloc, terminal, .{});
    defer alloc.free(terminal_bytes);
    var terminal_txn = try store.store.beginWriteTxn();
    errdefer terminal_txn.abort();
    var publication_key_buf: [160]u8 = undefined;
    try terminal_txn.put(try fk_generation_publication.key(&publication_key_buf, group_id, child.table_id), terminal_bytes);
    var work_key_buf: [160]u8 = undefined;
    try terminal_txn.delete(try fk_generation_publication.workKey(&work_key_buf, group_id, child.table_id));
    try terminal_txn.commit();
    const no_work = try store.fkGenerationPublicationWorkJson(alloc, group_id, child.table_id);
    defer alloc.free(no_work);
    try std.testing.expectEqualStrings("null", no_work);
    // An index entry without its matching nonterminal publication must fail
    // closed rather than silently losing supervisor work after a snapshot.
    var orphan_txn = try store.store.beginWriteTxn();
    errdefer orphan_txn.abort();
    try orphan_txn.put(try fk_generation_publication.workKey(&work_key_buf, group_id, child.table_id), &id);
    try orphan_txn.commit();
    try std.testing.expectError(error.InvalidGenerationPublication, store.fkGenerationPublicationWorkJson(alloc, group_id, child.table_id));
}

test "initial self FK reserves one hidden child owner and no duplicate parent route" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/initial-self-fk", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    try store.applyStandaloneCommand(group_id, .{ .initialize_metadata_incarnation = "11111111111111111111111111111111".* });
    const logical_schema =
        \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["id"]}],"foreign_keys":[{"name":"self_fk","child_columns":["parent_id"],"parent_table":"nodes","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"},"parent_id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const prepared_json = try store.fkInitialCreatePrepareJson(alloc, group_id, .{
        .namespace_id = system_catalog.default_namespace_id,
        .logical_name = "nodes",
        .candidate = .{ .table_id = 0, .name = "", .schema_json = logical_schema },
    });
    defer alloc.free(prepared_json);
    var prepared = try std.json.parseFromSlice(fk_generation_publication.InitialCreatePrepare, alloc, prepared_json, .{});
    defer prepared.deinit();
    const child = prepared.value.child;
    const replacement = try std.fmt.allocPrint(alloc, "\"parent_table\":\"{s}\"", .{child.name});
    defer alloc.free(replacement);
    const bound_schema = try std.mem.replaceOwned(u8, alloc, logical_schema, "\"parent_table\":\"nodes\"", replacement);
    defer alloc.free(bound_schema);
    var bound_child = child;
    bound_child.schema_json = bound_schema;
    const derived = try fk_generation_publication.deriveInitialTransitions(alloc, child.table_id, child.name, bound_schema);
    defer fk_generation_publication.freeDerivedTransitions(alloc, derived);
    try std.testing.expectEqual(@as(usize, 1), derived.len);
    var id: fk_generation_publication.Id = @splat(0);
    std.mem.writeInt(u64, id[0..8], 91, .little);
    std.mem.writeInt(u64, id[8..16], 2, .little);
    const plan: fk_generation_publication.InitialCreatePlan = .{
        .id = id,
        .retirement_scope = .local_owner,
        .catalog_id = prepared.value.catalog_id,
        .expected_catalog_revision = prepared.value.expected_catalog_revision,
        .child = bound_child,
        .child_ranges = prepared.value.child_ranges,
        .parents = &.{},
        .self_transitions = &.{derived[0].transition},
        .logical_name = "nodes",
        .namespace_id = system_catalog.default_namespace_id,
    };
    try plan.validate(alloc);
    const begin = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 0, .action = .begin, .plan = plan }, .{});
    defer alloc.free(begin);
    // A prepared predicate is not permission to use a new wire/occupancy
    // capability. Both preflight and committed apply must reject before any
    // hidden identity is reserved; the legacy begin below must still succeed.
    var named_plan = plan;
    named_plan.constraint_name_admission = .{ .namespace_id = plan.namespace_id, .names = &.{.{ .name = "self_fk", .kind = .foreign_key }} };
    const named_begin = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 0, .action = .begin, .plan = named_plan }, .{});
    defer alloc.free(named_begin);
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.preflightFkInitialCreateCommand(group_id, named_begin));
    const before_named = try store.systemCatalogMeta(alloc, group_id);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = named_begin });
    try std.testing.expectEqual(before_named.revision, (try store.systemCatalogMeta(alloc, group_id)).revision);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = begin });
    const hidden_group_id = prepared.value.child_ranges[0].group_id;
    try store.applyStandaloneCommand(group_id, .{ .register_node = .{ .node_id = 7, .role = "data", .lifecycle = metadata_table_manager.node_lifecycle_active } });
    try store.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
        .expected_metadata_version = null,
        .expected_version_fence = 0,
        .expected_target_drain_requested = false,
        .replacement = .{ .record = .{ .group_id = hidden_group_id, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
    } });
    const hidden_placements = try store.listPlacementIntents(alloc, group_id);
    defer store.freePlacementIntents(alloc, hidden_placements);
    try std.testing.expectEqual(@as(usize, 1), hidden_placements.len);
    try std.testing.expectEqual(hidden_group_id, hidden_placements[0].record.group_id);
    const decision_json = try store.fkInitialChildDecisionJson(alloc, group_id, .{ .plan_id = id, .child_table_id = child.table_id, .child_group_id = prepared.value.child_ranges[0].group_id, .action = .provision });
    defer alloc.free(decision_json);
    var decision = try std.json.parseFromSlice(fk_generation_publication.InitialChildDecision, alloc, decision_json, .{});
    defer decision.deinit();
    try std.testing.expectEqualStrings(bound_schema, decision.value.child.schema_json);
    const candidate = try plan.candidateIdentity(alloc);
    const namespace: @import("antfly_local_sources").storage_db_doc_identity_namespace.Namespace = .{
        .table_id = child.table_id,
        .shard_id = metadata_table_manager.rangeDocIdentityShardId(prepared.value.child_ranges[0]),
        .range_id = metadata_table_manager.rangeDocIdentityRangeId(prepared.value.child_ranges[0]),
    };
    const db_path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/initial-self-owner", .{tmp.sub_path});
    defer alloc.free(db_path);
    const bootstrap: @import("antfly_local_sources").storage_db_relational_initial_child_publication.Bootstrap = .{
        .plan_id = id,
        .plan_digest = try plan.digest(alloc),
        .namespace = namespace,
        .schema_version = candidate.schema_version,
        .schema_digest = candidate.schema_digest,
        .public_schema_json_digest = candidate.public_schema_json_digest,
        .catalog_digest = candidate.catalog_digest,
    };
    const db_options: @import("antfly_source_root").antfly_sources.physical_db.OpenOptions = .{ .identity_namespace = namespace, .initial_child_bootstrap = bootstrap, .start_optional_runtimes = false, .start_index_workers = false };
    const child_fence: @import("antfly_local_sources").storage_db_relational_integrity_topology_contract.Fence = .{
        .role = .child_generation_source,
        .transition_id = child.table_id,
        .attempt = 1,
        .admission_epoch = 1,
        .peer_group_id = prepared.value.child_ranges[0].group_id,
        .owner_group_id = prepared.value.child_ranges[0].group_id,
        .namespace = namespace,
        .catalog_digest = candidate.catalog_digest,
    };
    {
        var db = try @import("antfly_source_root").antfly_sources.physical_db.DB.open(alloc, db_path, db_options);
        defer db.close();
        try std.testing.expectError(error.InitialChildNotPublished, db.lookup(alloc, "unpublished", .{}));
        try @import("../../storage/server_db_adapter.zig").applyOrdered(&db, .{ .relational_topology = .{ .action = .provision_initial_child, .fence = child_fence, .initial_child_provision = .{
            .schema_json = bound_schema,
            .child_table_name = child.name,
            .plan_id = id,
            .plan_digest = bootstrap.plan_digest,
            .schema_digest = candidate.schema_digest,
            .public_schema_json_digest = candidate.public_schema_json_digest,
            .catalog_digest = candidate.catalog_digest,
        } } }, .{ .term = 2, .index = 1 });
        try std.testing.expectError(error.InitialChildNotPublished, db.lookup(alloc, "unpublished", .{}));
    }
    const receipt: @import("../../api/relational_fk_generation_publication.zig").InitialChildReceipt = .{
        .plan_id = id,
        .child_table_id = child.table_id,
        .child_group_id = prepared.value.child_ranges[0].group_id,
        .action = .provision,
        .namespace = namespace,
        .plan_digest = try plan.digest(alloc),
        .schema_version = candidate.schema_version,
        .schema_digest = candidate.schema_digest,
        .public_schema_json_digest = candidate.public_schema_json_digest,
        .catalog_digest = candidate.catalog_digest,
        .row_count = 0,
        .applied_term = 2,
        .applied_index = 1,
    };
    const provisioned = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 1, .action = .child_provisioned, .child_receipt = receipt }, .{});
    defer alloc.free(provisioned);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = provisioned });
    const work_json = try store.fkInitialCreateWorkJson(alloc, group_id, 0);
    defer alloc.free(work_json);
    var work = try std.json.parseFromSlice(?fk_generation_publication.InitialWork, alloc, work_json, .{});
    defer work.deinit();
    try std.testing.expectEqual(fk_generation_publication.InitialPhase.published_hidden, work.value.?.phase);
    try std.testing.expectEqual(@import("../../api/relational_fk_generation_publication.zig").InitialChildAction.release, work.value.?.target.child.action);
    const public_tables = try store.listTables(alloc, group_id);
    defer store.freeTables(alloc, public_tables);
    try std.testing.expectEqual(@as(usize, 0), public_tables.len);
    {
        var db = try @import("antfly_source_root").antfly_sources.physical_db.DB.open(alloc, db_path, db_options);
        defer db.close();
        try std.testing.expectError(error.InitialChildNotPublished, db.lookup(alloc, "unpublished", .{}));
        try @import("../../storage/server_db_adapter.zig").applyOrdered(&db, .{ .relational_topology = .{ .action = .release_initial_child, .fence = child_fence, .initial_child_control = .{
            .plan_id = id,
            .plan_digest = bootstrap.plan_digest,
            .schema_version = candidate.schema_version,
            .schema_digest = candidate.schema_digest,
            .public_schema_json_digest = candidate.public_schema_json_digest,
            .catalog_digest = candidate.catalog_digest,
        } } }, .{ .term = 2, .index = 2 });
        try std.testing.expect((try db.lookup(alloc, "unpublished", .{})) == null);
    }
    var released_receipt = receipt;
    released_receipt.action = .release;
    released_receipt.applied_index = 2;
    const released = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 2, .action = .child_released, .child_receipt = released_receipt }, .{});
    defer alloc.free(released);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = released });
    const published = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 3, .action = .publish_child }, .{});
    defer alloc.free(published);
    const PublicationSignals = struct {
        child_id: u64,
        table: usize = 0,
        ranges: usize = 0,

        fn onProjection(ptr: *anyopaque, signal: ProjectionSignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (signal.table_id != self.child_id) return;
            switch (signal.kind) {
                .table => self.table += 1,
                .range => self.ranges += 1,
                else => {},
            }
        }
    };
    var signals = PublicationSignals{ .child_id = child.table_id };
    try store.addProjectionListener(.{ .ptr = &signals, .vtable = &.{ .on_projection_signal = PublicationSignals.onProjection } });
    try store.preflightFkInitialCreateCommand(group_id, published);
    try std.testing.expectEqual(@as(usize, 0), signals.table);
    try std.testing.expectEqual(@as(usize, 0), signals.ranges);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = published });
    try std.testing.expectEqual(@as(usize, 1), signals.table);
    try std.testing.expectEqual(plan.child_ranges.len, signals.ranges);
    const resolved = (try store.resolveSystemCatalogIdentity(alloc, group_id, .{ .table = "nodes" })).?;
    defer alloc.free(resolved.name);
    try std.testing.expectEqual(child.table_id, resolved.table_id);
    try std.testing.expectEqualStrings(child.name, resolved.name);
    const visible = try store.listTables(alloc, group_id);
    defer store.freeTables(alloc, visible);
    try std.testing.expectEqual(@as(usize, 1), visible.len);
    try std.testing.expectEqualStrings(bound_schema, visible[0].schema_json);
    const listed = try store.listSystemCatalogTables(alloc, group_id, .{});
    defer alloc.free(listed);
    var listing = try std.json.parseFromSlice(@import("../../system_catalog/projection.zig").TableListing, alloc, listed, .{});
    defer listing.deinit();
    try std.testing.expectEqual(@as(usize, 1), listing.value.entries.len);
    try std.testing.expectEqualStrings("nodes", listing.value.entries[0].name);
    var listing_txn = try store.store.beginReadTxn();
    defer listing_txn.abort();
    const prefix = try RaftApplyStore.legacyListingPrefix(alloc, group_id);
    defer alloc.free(prefix);
    const stale = try docstore.DocStore.scanPrefixTxn(alloc, &listing_txn, prefix);
    defer RaftApplyStore.freeKvs(alloc, stale);
    try std.testing.expectEqual(@as(usize, 0), stale.len);
    const published_placements = try store.listPlacementIntents(alloc, group_id);
    defer store.freePlacementIntents(alloc, published_placements);
    try std.testing.expectEqual(@as(usize, 1), published_placements.len);
    try std.testing.expectEqual(hidden_placements[0].record.metadata_version, published_placements[0].record.metadata_version);
}

test "initial self FK resumes the second hidden range after a durable owner receipt" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/initial-self-multi", .{tmp.sub_path});
    defer alloc.free(root);
    const group_id = group_ids.main_metadata_group_id;
    const logical_schema =
        \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["id"]}],"foreign_keys":[{"name":"self_fk","child_columns":["parent_id"],"parent_table":"nodes","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"},"parent_id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    var store_open = true;
    defer if (store_open) store.deinit();
    try store.applyStandaloneCommand(group_id, .{ .initialize_metadata_incarnation = "22222222222222222222222222222222".* });
    const prepared_json = try store.fkInitialCreatePrepareJson(alloc, group_id, .{
        .namespace_id = system_catalog.default_namespace_id,
        .logical_name = "nodes",
        .min_ranges_explicit = true,
        .candidate = .{ .table_id = 0, .name = "", .schema_json = logical_schema, .min_ranges = 2 },
    });
    defer alloc.free(prepared_json);
    var prepared = try std.json.parseFromSlice(fk_generation_publication.InitialCreatePrepare, alloc, prepared_json, .{});
    defer prepared.deinit();
    try std.testing.expectEqual(@as(usize, 2), prepared.value.child_ranges.len);
    const child = prepared.value.child;
    const replacement = try std.fmt.allocPrint(alloc, "\"parent_table\":\"{s}\"", .{child.name});
    defer alloc.free(replacement);
    const bound_schema = try std.mem.replaceOwned(u8, alloc, logical_schema, "\"parent_table\":\"nodes\"", replacement);
    defer alloc.free(bound_schema);
    var bound_child = child;
    bound_child.schema_json = bound_schema;
    const derived = try fk_generation_publication.deriveInitialTransitions(alloc, child.table_id, child.name, bound_schema);
    defer fk_generation_publication.freeDerivedTransitions(alloc, derived);
    var id: fk_generation_publication.Id = @splat(0);
    std.mem.writeInt(u64, id[0..8], 92, .little);
    std.mem.writeInt(u64, id[8..16], 2, .little);
    const plan: fk_generation_publication.InitialCreatePlan = .{
        .id = id,
        .retirement_scope = .local_owner,
        .catalog_id = prepared.value.catalog_id,
        .expected_catalog_revision = prepared.value.expected_catalog_revision,
        .min_ranges_explicit = true,
        .child = bound_child,
        .child_ranges = prepared.value.child_ranges,
        .parents = &.{},
        .self_transitions = &.{derived[0].transition},
        .logical_name = "nodes",
        .namespace_id = system_catalog.default_namespace_id,
    };
    try plan.validate(alloc);
    const begin = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 0, .action = .begin, .plan = plan }, .{});
    defer alloc.free(begin);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = begin });
    const first_work_json = try store.fkInitialCreateWorkJson(alloc, group_id, 0);
    defer alloc.free(first_work_json);
    var first_work = try std.json.parseFromSlice(?fk_generation_publication.InitialWork, alloc, first_work_json, .{});
    defer first_work.deinit();
    const first_group = first_work.value.?.target.child.group_id;
    const first_range = for (plan.child_ranges) |range| {
        if (range.group_id == first_group) break range;
    } else return error.InvalidGenerationPublication;
    const candidate = try plan.candidateIdentity(alloc);
    const first_receipt: @import("../../api/relational_fk_generation_publication.zig").InitialChildReceipt = .{
        .plan_id = id,
        .child_table_id = child.table_id,
        .child_group_id = first_group,
        .action = .provision,
        .namespace = .{ .table_id = child.table_id, .shard_id = metadata_table_manager.rangeDocIdentityShardId(first_range), .range_id = metadata_table_manager.rangeDocIdentityRangeId(first_range) },
        .plan_digest = try plan.digest(alloc),
        .schema_version = candidate.schema_version,
        .schema_digest = candidate.schema_digest,
        .public_schema_json_digest = candidate.public_schema_json_digest,
        .catalog_digest = candidate.catalog_digest,
        .row_count = 0,
        .applied_term = 1,
        .applied_index = 1,
    };
    const first_command = try std.json.Stringify.valueAlloc(alloc, fk_generation_publication.InitialCommand{ .plan_id = id, .child_table_id = child.table_id, .expected_revision = 1, .action = .child_provisioned, .child_receipt = first_receipt }, .{});
    defer alloc.free(first_command);
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = first_command });
    try std.testing.expectError(error.GenerationPublicationChanged, store.preflightFkInitialCreateCommand(group_id, first_command));
    try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = first_command });
    // Two supervisors may submit this same revision before either receives
    // the first commit. The losing committed entry must advance as a no-op.
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        try store.applyCommittedFkInitialCreateTxn(&txn, group_id, first_command);
    }
    store.deinit();
    store_open = false;
    var recovered = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer recovered.deinit();
    const next_work_json = try recovered.fkInitialCreateWorkJson(alloc, group_id, 0);
    defer alloc.free(next_work_json);
    var next_work = try std.json.parseFromSlice(?fk_generation_publication.InitialWork, alloc, next_work_json, .{});
    defer next_work.deinit();
    try std.testing.expectEqual(fk_generation_publication.InitialPhase.provisioning_child, next_work.value.?.phase);
    try std.testing.expectEqual(@as(u64, 2), next_work.value.?.revision);
    try std.testing.expect(next_work.value.?.target.child.group_id != first_group);
}

