        try std.testing.expectEqual(fk_initial_retirement_ack.Disposition.already_acked, try recovered.ackInitialFkRetirementTxn(&txn, group_id, signed));
        try txn.commit();
    }
    const acked_page_json = try recovered.fkInitialRetirementTicketPageJson(alloc, group_id, .{ .store_id = 30, .limit = 1 });
    defer alloc.free(acked_page_json);
    var acked_page = try std.json.parseFromSlice(fk_initial_retirement_wire.PageResponse, alloc, acked_page_json, .{});
    defer acked_page.deinit();
    try std.testing.expectEqual(@as(usize, 0), acked_page.value.items.len);
}

test "generation lock freezes the table cut while initial support permits exact schema retirement" {
    try exerciseTableCutLifecycleLock(.generation);
}

test "index build lock freezes the table cut while initial support permits exact schema retirement" {
    try exerciseTableCutLifecycleLock(.index_build);
}

test "schema validation publication shared lock freezes the table cut and schema retirement" {
    try exerciseTableCutLifecycleLock(.schema_validation);
}

fn exerciseTableCutLifecycleLock(kind: @import("../table_lifecycle_lock.zig").Kind) !void {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/fk-read-schema-lock", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const current: metadata.TableRecord = .{
        .table_id = 201,
        .name = "parent",
        .schema_json = "{\"version\":2}",
        .read_schema_json = "{\"version\":1}",
    };
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = current });
    try store.applyStandaloneCommand(group_id, .{ .upsert_range = .{
        .table_id = 201,
        .group_id = 401,
        .range_id = 401,
        .doc_identity_shard_id = 401,
        .doc_identity_range_id = 401,
        .start_key = "",
    } });
    try store.applyStandaloneCommand(group_id, .{ .register_node = .{ .node_id = 7, .role = "data", .lifecycle = metadata_table_manager.node_lifecycle_active } });
    try store.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
        .expected_metadata_version = null,
        .expected_version_fence = 0,
        .expected_target_drain_requested = false,
        .replacement = .{ .record = .{ .group_id = 401, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
    } });
    var lock_key_buf: [160]u8 = undefined;
    const lock_key = try fk_generation_publication.tableLockKey(&lock_key_buf, group_id, current.table_id);
    var plan_id: fk_generation_publication.Id = @splat(0);
    plan_id[0] = 1;
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        const generation_lock = RaftApplyStore.fkTableLockValue(kind, plan_id);
        try txn.put(lock_key, &generation_lock);
        try txn.commit();
    }
    var finalized = current;
    finalized.read_schema_json = "";
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = finalized });
    var tables = try store.listTables(alloc, group_id);
    try std.testing.expectEqualStrings(current.read_schema_json, tables[0].read_schema_json);
    store.freeTables(alloc, tables);
    try store.applyStandaloneCommand(group_id, .{ .compare_and_replace_table = .{ .expected = current, .replacement = finalized } });
    tables = try store.listTables(alloc, group_id);
    try std.testing.expectEqualStrings(current.read_schema_json, tables[0].read_schema_json);
    store.freeTables(alloc, tables);
    try store.applyStandaloneCommand(group_id, .{ .upsert_schema_progress = .{ .table_id = 201, .node_id = 7, .schema_version = 2 } });
    {
        var progress_txn = try store.store.beginReadTxn();
        defer progress_txn.abort();
        const indexed_ranges = try store.indexedTableRangeIdsTxn(alloc, &progress_txn, group_id, 201);
        defer alloc.free(indexed_ranges);
        try std.testing.expectEqual(@as(usize, 1), indexed_ranges.len);
        const placed = try store.listPlacementIntents(alloc, group_id);
        defer store.freePlacementIntents(alloc, placed);
        try std.testing.expectEqual(@as(usize, 1), placed.len);
        try std.testing.expect(try store.schemaMigrationReadyTxn(&progress_txn, group_id, 201, 2));
    }
    // A generation ADD/DROP already captured the old read layout and index
    // catalog. Even after migration progress arrives, finalization must wait
    // for that publication to release its lock.
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = finalized });
    tables = try store.listTables(alloc, group_id);
    try std.testing.expectEqualStrings(current.read_schema_json, tables[0].read_schema_json);
    store.freeTables(alloc, tables);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        const initial_support_lock = RaftApplyStore.fkTableLockValue(.initial_support, plan_id);
        try txn.put(lock_key, &initial_support_lock);
        try txn.commit();
    }
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = finalized });
    tables = try store.listTables(alloc, group_id);
    try std.testing.expectEqual(@as(usize, 1), tables.len);
    try std.testing.expectEqualStrings("", tables[0].read_schema_json);
    store.freeTables(alloc, tables);
    var unrelated = finalized;
    unrelated.description = "unrelated DDL";
    try store.applyStandaloneCommand(group_id, .{ .upsert_table = unrelated });
    tables = try store.listTables(alloc, group_id);
    try std.testing.expectEqualStrings("", tables[0].description);
    store.freeTables(alloc, tables);
    try store.applyStandaloneCommand(group_id, .{ .compare_and_replace_table = .{ .expected = finalized, .replacement = unrelated } });
    tables = try store.listTables(alloc, group_id);
    try std.testing.expectEqualStrings("", tables[0].description);
    store.freeTables(alloc, tables);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try txn.delete(lock_key);
        try txn.commit();
    }
    try store.applyStandaloneCommand(group_id, .{ .compare_and_replace_table = .{ .expected = finalized, .replacement = unrelated } });
    tables = try store.listTables(alloc, group_id);
    defer store.freeTables(alloc, tables);
    try std.testing.expectEqualStrings("unrelated DDL", tables[0].description);
}

test "relational index publication native reporter retirement bounds every commit and resumes partial inventories through snapshot and cold reopen" {
    const a = std.testing.allocator;
    var directory = std.testing.tmpDir(.{});
    defer directory.cleanup();
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const scratch = arena.allocator();
    const path = try std.fmt.allocPrint(scratch, ".zig-cache/tmp/{s}/native-restart", .{directory.sub_path});
    const copied_path = try std.fmt.allocPrint(scratch, ".zig-cache/tmp/{s}/native-restart-copy", .{directory.sub_path});
    const root_path = try std.fmt.allocPrint(scratch, ".zig-cache/tmp/{s}/native-root", .{directory.sub_path});
    const root = try @import("antfly_local_sources").storage_db_root_signing_identity.loadOrCreate(a, std.testing.io, root_path);
    const group = group_ids.main_metadata_group_id;
    const request = try (standalone_native_owner.Registration{
        .identity = .{ .metadata_incarnation = @splat('1'), .node_id = 2, .store_id = 3, .root_incarnation = root.root_incarnation, .public_key = root.public_key },
        .reporter_incarnation = 5,
        .expected_reporter_incarnation = 4,
        .signature = undefined,
        .schema_reader = metadata_table_manager.SchemaReaderCapabilities.current,
        .artifact_sources_protocol_version = metadata_table_manager.artifact_sources_protocol_version,
        .native_generation_restore_version = metadata_table_manager.native_generation_restore_protocol_version,
        .dense_native_storage_protocol_version = metadata_table_manager.dense_native_storage_protocol_version,
        .relational_topology_protocol_version = metadata_table_manager.relational_topology_protocol_version,
    }).sign(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = path });
    var store_open = true;
    defer if (store_open) store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = request.identity.metadata_incarnation });
    try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .auxiliary_json = "{}" });
    const activation = try std.json.Stringify.valueAlloc(scratch, topology_protocol.Activation{ .version = topology_protocol.native_reporter_restart_version, .incarnation = request.identity.metadata_incarnation, .member_count = 1, .membership_fingerprint = @splat(7) }, .{});
    try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
    try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_owner = request.binding() });
    var old: metadata.StoreRecord = .{ .store_id = 3, .node_id = 2, .reporter_incarnation = 4, .replica_root_incarnation = root.root_incarnation, .replica_root_public_key = root.public_key };
    try store.applyStandaloneCommand(group, .{ .register_store = old });
    const reports = try scratch.alloc(metadata.GroupStatusReport, 256);
    for (reports, 0..) |*item, i| item.* = .{ .group_id = i + 1000, .doc_count = 1, .empty = false };
    old.group_statuses = reports;
    const baseline: RaftApplyStore.BaselineState = .{
        .active = .{ .incarnation = 4, .sequence = 2 },
        .garbage = .{ .incarnation = 4, .sequence = 1 },
        .gc_fragment_end = 1,
        .upload = .{ .cursor = .{ .reporter_incarnation = 4, .sequence = 3, .digest = @splat(7) }, .chunk_count = 3, .next_chunk = 1, .total_bytes = 100000, .received_bytes = 4096, .fragment_count = 1, .fragment_received = 8, .fragment_total = 16, .fragment_group_id = 2000, .fragment_digest = @splat(8), .expected_header = @splat(1), .admission_cursor = null, .report_header_digest = @splat(2) },
    };
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        for (1..4) |sequence| {
            const generation: store_report_baseline.Generation = .{ .incarnation = 4, .sequence = sequence };
            _ = try store.writeStoreGenerationTxn(&txn, group, 3, old, false, null, null, generation);
            if (sequence != 2) try txn.put(try (RaftApplyStore.ReportAddress{ .store_id = 3, .generation = generation }).key(scratch, group, "fragment", 0), "partial-fragment");
        }
        try txn.put(try RaftApplyStore.baselineKey(scratch, group, 3), try std.json.Stringify.valueAlloc(scratch, baseline, .{}));
        try txn.commit();
    }
    const observed = try store.observeStandaloneNativeReporter(group, request);
    try store.updateStandaloneCatalog(group, observed.revision, .{ .native_restart = .{ .request = request, .expected = observed } });
    {
        const current = (try store.readStore(a, group, 3, true)).?;
        defer metadata_table_manager.freeStore(a, current);
        try std.testing.expect(!current.live and current.group_statuses.len == 0);
        var signing_read = try store.store.beginReadTxn();
        defer signing_read.abort();
        try std.testing.expect((try store.nativeIndexSigningViewTxn(&signing_read, group, request.identity.metadata_incarnation)) == null);
    }
    var snapshotted = false;
    var steps: usize = 0;
    var current_path = path;
    var last: ?standalone_native_owner.RestartProgress = null;
    while (try store.nativeReporterRestartProgress(group, 3)) |progress| {
        if (steps > 64) return error.TestUnexpectedUnboundedRetirement;
        var key_buf: [256]u8 = undefined;
        const record = read_record: {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            break :read_record try RaftApplyStore.decodeNativeRestart(scratch, try read.get(try standalone_native_owner.restartKey(&key_buf, group, 3)));
        };
        if (!snapshotted and record.phase == .active and record.page == 1) {
            const bytes = snapshot: {
                var snapshot_txn = try store.store.beginReadTxn();
                defer snapshot_txn.abort();
                break :snapshot try store.buildMetadataSnapshotTxn(scratch, &snapshot_txn, group, null);
            };
            var copied = try RaftApplyStore.init(a, .{ .root_dir = copied_path });
            errdefer copied.deinit();
            // A valid outer snapshot checksum cannot authorize an altered
            // implementation profile under the predecessor's signature.
            const altered = try decodeMetadataSnapshotAlloc(a, bytes);
            defer freeMetadataSnapshotRows(a, altered);
            for (altered) |*row| if (std.mem.eql(u8, row.key, try standalone_native_owner.restartKey(&key_buf, group, 3))) {
                var forged = try RaftApplyStore.decodeNativeRestart(scratch, row.value);
                forged.request.schema_reader.semantic_ceiling -= 1;
                const changed = try std.json.Stringify.valueAlloc(a, forged, .{});
                a.free(row.value);
                row.value = changed;
            };
            const forged_snapshot = try encodeMetadataSnapshot(a, altered);
            defer a.free(forged_snapshot);
            try std.testing.expectError(error.InvalidMetadataSnapshot, RaftApplyStore.installSnapshotFromRaft(&copied, a, group, 1, forged_snapshot));
            try std.testing.expect((try copied.standaloneNativeOwnerBinding(group)) == null);
            try RaftApplyStore.installSnapshotFromRaft(&copied, a, group, 1, bytes);
            try std.testing.expectEqualDeep(progress, (try copied.nativeReporterRestartProgress(group, 3)).?);
            // Group snapshots intentionally exclude the process-global
            // standalone envelope. Its paired source checkpoint must be
            // bootstrapped before standalone-only mutations may resume.
            try std.testing.expectError(error.InvalidStandaloneCatalog, copied.updateStandaloneCatalog(group, try copied.standaloneRevision(), .{ .native_restart = .{ .request = request, .progress = progress.digest } }));
            const paired_catalog = paired: {
                var source_read = try store.store.beginReadTxn();
                defer source_read.abort();
                break :paired try scratch.dupe(u8, try source_read.get(RaftApplyStore.standalone_catalog_key));
            };
            try copied.updateStandaloneCatalog(group, try copied.standaloneRevision(), .{ .auxiliary_json = paired_catalog });
            store.deinit();
            store = copied;
            current_path = copied_path;
            snapshotted = true;
        }
        if (last) |stale| {
            try std.testing.expectError(error.GenerationPublicationChanged, store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_restart = .{ .request = request, .progress = stale.digest } }));
            try std.testing.expectEqualDeep(progress, (try store.nativeReporterRestartProgress(group, 3)).?);
        }
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_restart = .{ .request = request, .progress = progress.digest } });
        last = progress;
        steps += 1;
        store.deinit();
        store_open = false;
        store = try RaftApplyStore.init(a, .{ .root_dir = current_path });
        store_open = true;
    }
    // Three 256-group inventories, one 64-reference page per commit, two
    // incomplete fragments and one final install require at least 15 turns.
    const minimum_turns = 3 * ((reports.len + 63) / 64) + 2 + 1;
    try std.testing.expect(snapshotted and steps >= minimum_turns);
    const installed = (try store.readStore(a, group, 3, true)).?;
    defer metadata_table_manager.freeStore(a, installed);
    try std.testing.expect(installed.live and installed.reporter_incarnation == request.reporter_incarnation);
    try std.testing.expectEqualDeep(request.schema_reader, installed.schema_reader);
    {
        var signing_read = try store.store.beginReadTxn();
        defer signing_read.abort();
        try std.testing.expect((try store.nativeIndexSigningViewTxn(&signing_read, group, request.identity.metadata_incarnation)) == null);
    } // Enrollment remains separate.
    try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_restart = .{ .request = request, .progress = last.?.digest } });
}

test "relational index publication native reporter CAS is durable atomic and cannot enroll its key" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/native-reporter", .{tmp.sub_path});
    defer alloc.free(path);
    const group = group_ids.main_metadata_group_id;
    const seed: [32]u8 = @splat(9);
    const pair = try std.crypto.sign.Ed25519.KeyPair.generateDeterministic(seed);
    const root: @import("antfly_local_sources").storage_db_root_signing_identity.State = .{ .seed = seed, .root_incarnation = 7, .public_key = pair.public_key.toBytes() };
    const first = try (standalone_native_owner.Registration{ .identity = .{ .metadata_incarnation = @splat('1'), .node_id = 2, .store_id = 3, .root_incarnation = 7, .public_key = root.public_key }, .reporter_incarnation = 4, .expected_reporter_incarnation = null, .signature = undefined }).sign(root);
    var next = first;
    next.reporter_incarnation = 5;
    next.expected_reporter_incarnation = 4;
    next = try next.sign(root);
    var final_revision: RaftApplyStore.StandaloneRevisionState = undefined;
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = path });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = first.identity.metadata_incarnation });
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .auxiliary_json = "{}" });
        try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_registration = first }));
        const activation = try std.json.Stringify.valueAlloc(alloc, topology_protocol.Activation{ .version = topology_protocol.store_root_enrollment_version, .incarnation = first.identity.metadata_incarnation, .member_count = 1, .membership_fingerprint = @splat(7) }, .{});
        defer alloc.free(activation);
        try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
        try std.testing.expectError(error.StoreRootEnrollmentChanged, store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_registration = first }));
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_owner = first.binding() });
        const before = try store.standaloneRevisionState();
        try store.updateStandaloneCatalog(group, before.revision, .{ .native_registration = first });
        const after = try store.standaloneRevisionState();
        try std.testing.expectEqual(before.revision + 1, after.revision);
        try std.testing.expectEqual(before.projection_revision, after.projection_revision);
        {
            var registered = (try store.readStore(alloc, group, 3, false)).?;
            defer metadata_table_manager.freeStore(alloc, registered);
            try std.testing.expectEqual(@as(u64, 4), registered.reporter_incarnation);
            try std.testing.expectEqual(@as(u128, 7), registered.replica_root_incarnation);
            try std.testing.expectEqualSlices(u8, &root.public_key, &registered.replica_root_public_key);
            try std.testing.expectEqual(@as(u64, 0), registered.status_generation);
            registered.status_generation = 17;
            try store.applyStandaloneCommand(group, .{ .upsert_store = registered });
        }
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_registration = first });
        {
            const duplicate = (try store.readStore(alloc, group, 3, false)).?;
            defer metadata_table_manager.freeStore(alloc, duplicate);
            try std.testing.expectEqual(@as(u64, 17), duplicate.status_generation);
        }
        const stable = try store.standaloneRevisionState();
        const mixed: metadata.TableRecord = .{ .table_id = 99, .name = "must_not_appear" };
        try std.testing.expectError(error.InvalidStandaloneCatalog, store.updateStandaloneCatalog(group, stable.revision, .{ .native_registration = next, .tables = &.{mixed} }));
        try std.testing.expectEqualDeep(stable, try store.standaloneRevisionState());
        var unknown = next;
        unknown.expected_reporter_incarnation = null;
        unknown = try unknown.sign(root);
        try std.testing.expectError(error.GenerationPublicationChanged, store.updateStandaloneCatalog(group, stable.revision, .{ .native_registration = unknown }));
        var changed_root = root;
        changed_root.root_incarnation += 1;
        var changed = next;
        changed.identity.root_incarnation += 1;
        changed = try changed.sign(changed_root);
        try std.testing.expectError(error.StoreRootEnrollmentChanged, store.updateStandaloneCatalog(group, stable.revision, .{ .native_registration = changed }));
        const other_seed: [32]u8 = @splat(8);
        const other_pair = try std.crypto.sign.Ed25519.KeyPair.generateDeterministic(other_seed);
        const other_root: @import("antfly_local_sources").storage_db_root_signing_identity.State = .{ .seed = other_seed, .root_incarnation = 7, .public_key = other_pair.public_key.toBytes() };
        changed = next;
        changed.identity.public_key = other_root.public_key;
        changed = try changed.sign(other_root);
        try std.testing.expectError(error.StoreRootEnrollmentChanged, store.updateStandaloneCatalog(group, stable.revision, .{ .native_registration = changed }));
        changed = next;
        changed.identity.metadata_incarnation = @splat('2');
        changed = try changed.sign(root);
        try std.testing.expectError(error.StoreRootEnrollmentChanged, store.updateStandaloneCatalog(group, stable.revision, .{ .native_registration = changed }));
        try std.testing.expectEqualDeep(stable, try store.standaloneRevisionState());
        try store.updateStandaloneCatalog(group, stable.revision, .{ .native_registration = next });
        // Lost reply: exact signed registration can be observed again without
        // resetting the reporter's status generation or report baselines.
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_registration = next });
        final_revision = try store.standaloneRevisionState();
        try std.testing.expectError(error.GenerationPublicationChanged, store.updateStandaloneCatalog(group, final_revision.revision, .{ .native_registration = first }));
        var read = try store.store.beginReadTxn();
        defer read.abort();
        try std.testing.expect(try store.nativeIndexSigningViewTxn(&read, group, first.identity.metadata_incarnation) == null);
    }
    var reopened = try RaftApplyStore.init(alloc, .{ .root_dir = path });
    defer reopened.deinit();
    try std.testing.expectEqualDeep(final_revision, try reopened.standaloneRevisionState());
    const registered = (try reopened.readStore(alloc, group, 3, false)).?;
    defer metadata_table_manager.freeStore(alloc, registered);
    try std.testing.expectEqual(@as(u64, 5), registered.reporter_incarnation);
    try std.testing.expectEqualSlices(u8, &root.public_key, &registered.replica_root_public_key);
    try std.testing.expectError(error.GenerationPublicationChanged, reopened.updateStandaloneCatalog(group, final_revision.revision, .{ .native_registration = first }));
    const tables = try reopened.listTables(alloc, group);
    defer reopened.freeTables(alloc, tables);
    try std.testing.expectEqual(@as(usize, 0), tables.len);
}

test "relational index publication native restart observation is read only and isolates report namespaces" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/native-restart-observation", .{tmp.sub_path});
    defer a.free(path);
    const group = group_ids.main_metadata_group_id;
    const signing = @import("antfly_local_sources").storage_db_root_signing_identity;
    const physical_path = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/physical-owner", .{tmp.sub_path});
    defer a.free(physical_path);
    const root = try signing.loadOrCreate(a, std.testing.io, physical_path);
    const request = try (standalone_native_owner.Registration{ .identity = .{ .metadata_incarnation = @splat('1'), .node_id = 2, .store_id = 3, .root_incarnation = root.root_incarnation, .public_key = root.public_key }, .reporter_incarnation = 5, .expected_reporter_incarnation = 4, .signature = undefined }).sign(root);
    const state: RaftApplyStore.BaselineState = .{
        .active = .{ .incarnation = 4, .sequence = 2 },
        .garbage = .{ .incarnation = 4, .sequence = 1 },
        .gc_page = 1,
        .gc_fragment = 1,
        .gc_fragment_end = 2,
        .upload = .{
            .cursor = .{ .reporter_incarnation = 4, .sequence = 3, .digest = @splat(7) },
            .chunk_count = 2,
            .total_bytes = 64,
            .fragment_count = 1,
            .fragment_received = 8,
            .fragment_total = 16,
            .fragment_group_id = 888,
            .fragment_digest = @splat(8),
            .expected_header = @splat(1),
            .admission_cursor = null,
            .report_header_digest = @splat(2),
        },
    };
    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    const scratch = arena.allocator();
    const baseline_key = try RaftApplyStore.baselineKey(scratch, group, 3);
    const state_bytes = try std.json.Stringify.valueAlloc(scratch, state, .{});
    const active: RaftApplyStore.ReportAddress = .{ .store_id = 3, .generation = state.active };
    const pending: RaftApplyStore.ReportAddress = .{ .store_id = 3, .generation = .{ .incarnation = 4, .sequence = 3 } };
    const membership_key = try RaftApplyStore.reportMembershipKey(scratch, group, active);
    const fragment_key = try pending.key(scratch, group, "fragment", 0);
    var observed: standalone_native_owner.RestartObservation = undefined;
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = path });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = request.identity.metadata_incarnation });
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .auxiliary_json = "{}" });
        try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.observeStandaloneNativeReporter(group, request));
        const activation = try std.json.Stringify.valueAlloc(scratch, topology_protocol.Activation{ .version = topology_protocol.store_root_enrollment_version, .incarnation = request.identity.metadata_incarnation, .member_count = 1, .membership_fingerprint = @splat(7) }, .{});
        try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
        try std.testing.expectError(error.StoreRootEnrollmentChanged, store.observeStandaloneNativeReporter(group, request));
        try store.updateStandaloneCatalog(group, try store.standaloneRevision(), .{ .native_owner = request.binding() });
        var first = request;
        first.expected_reporter_incarnation = null;
        first = try first.sign(root);
        const empty = try store.observeStandaloneNativeReporter(group, first);
        try std.testing.expect(empty.header_digest == null and !empty.root_enrolled and !empty.reporter_matches);
        try std.testing.expect((try store.readStore(a, group, 3, false)) == null);
        try store.applyStandaloneCommand(group, .{ .register_store = .{ .store_id = 3, .node_id = 2, .reporter_incarnation = 4, .replica_root_incarnation = root.root_incarnation, .replica_root_public_key = root.public_key } });
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try txn.put(baseline_key, state_bytes);
            // A read-only restart cut must not expand either report inventory
            // or a partial upload. Poison values make accidental decoding fail.
            try txn.put(membership_key, "not-a-report-directory");
            try txn.put(fragment_key, "preserve-incomplete-upload");
            try txn.put("unrelated:user:row", "preserve-user-data");
            try txn.commit();
        }
        const revision = try store.standaloneRevisionState();
        observed = try store.observeStandaloneNativeReporter(group, request);
        try std.testing.expectEqual(revision.revision, observed.revision);
        try std.testing.expect(!observed.reporter_matches);
        try std.testing.expect(!observed.root_enrolled and !observed.replication_pending);
        try std.testing.expectEqualDeep(state.active, observed.active);
        try std.testing.expectEqualDeep(state.upload.?.cursor, observed.pending.?);
        try std.testing.expectEqualDeep(state.garbage, observed.retired);
        try std.testing.expectEqual(@as(usize, 1), observed.gc_page);
        try std.testing.expectEqualSlices(u8, &try request.message(), &observed.request_digest);
        var wrong = request;
        wrong.expected_reporter_incarnation = 6;
        wrong = try wrong.sign(root);
        try std.testing.expectError(error.GenerationPublicationChanged, store.observeStandaloneNativeReporter(group, wrong));
        wrong = request;
        wrong.identity.metadata_incarnation = @splat('2');
        wrong = try wrong.sign(root);
        try std.testing.expectError(error.StoreRootEnrollmentChanged, store.observeStandaloneNativeReporter(group, wrong));
        for (0..7) |fault| {
            var invalid = state;
            switch (fault) {
                0 => invalid.garbage = invalid.active,
                1 => invalid.upload.?.cursor.sequence = invalid.active.sequence,
                2 => invalid.upload.?.cursor.sequence = invalid.garbage.?.sequence,
                3 => invalid.active.sequence = 0,
                4 => invalid.gc_fragment = invalid.gc_fragment_end + 1,
                5 => invalid.garbage = null,
                6 => invalid.upload.?.next_chunk = invalid.upload.?.chunk_count + 1,
                else => unreachable,
            }
            try std.testing.expectError(error.InvalidCatalogRecord, invalid.validateRestartObservation());
            const invalid_bytes = try std.json.Stringify.valueAlloc(scratch, invalid, .{});
            {
                var txn = try store.store.beginWriteTxn();
                errdefer txn.abort();
                try txn.put(baseline_key, invalid_bytes);
                try txn.commit();
            }
            try std.testing.expectError(error.InvalidCatalogRecord, store.observeStandaloneNativeReporter(group, request));
            var read = try store.store.beginReadTxn();
            defer read.abort();
            try std.testing.expectEqualStrings(invalid_bytes, try read.get(baseline_key));
            try std.testing.expectEqualStrings("preserve-incomplete-upload", try read.get(fragment_key));
        }
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try txn.put(baseline_key, state_bytes);
            try txn.commit();
        }
        try std.testing.expectEqualDeep(revision, try store.standaloneRevisionState());
    }
    var reopened = try RaftApplyStore.init(a, .{ .root_dir = path });
    defer reopened.deinit();
    try std.testing.expectEqualDeep(root, try signing.load(a, std.testing.io, physical_path));
    try std.testing.expectEqualDeep(observed, try reopened.observeStandaloneNativeReporter(group, request));
    var read = try reopened.store.beginReadTxn();
    defer read.abort();
    try std.testing.expectEqualStrings(state_bytes, try read.get(baseline_key));
    try std.testing.expectEqualStrings("not-a-report-directory", try read.get(membership_key));
    try std.testing.expectEqualStrings("preserve-incomplete-upload", try read.get(fragment_key));
    try std.testing.expectEqualStrings("preserve-user-data", try read.get("unrelated:user:row"));
    try std.testing.expect(try reopened.nativeIndexSigningViewTxn(&read, group, request.identity.metadata_incarnation) == null);
}

test "native initial support finalization requires current bound root and durable owner progress" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/native-owner-schema", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group = group_ids.main_metadata_group_id;
    const incarnation: metadata_incarnation.MetadataClusterIncarnation = "0123456789abcdef0123456789abcdef".*;
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = incarnation });
    try store.updateStandaloneCatalog(group, 1, .{ .auxiliary_json = "{}" });
    const owner: standalone_native_owner.Binding = .{
        .metadata_incarnation = incarnation,
        .node_id = 7,
        .store_id = 9,
        .root_incarnation = 11,
    };
    try store.updateStandaloneCatalog(group, 2, .{ .native_owner = owner });
    var replacement = owner;
    replacement.root_incarnation = 12;
    try std.testing.expectError(error.StoreRootEnrollmentChanged, store.updateStandaloneCatalog(group, 3, .{ .native_owner = replacement }));
    const current: metadata.TableRecord = .{
        .table_id = 201,
        .name = "parent",
        .schema_json = "{\"version\":2}",
        // The old serving layout owns a coordinated declaration absent from
        // the already-published new schema. Generic retention must reject its
        // removal; only exact owner-ready finalization may retire it.
        .read_schema_json = "{\"version\":1,\"unique_constraints\":[{\"name\":\"old_key\",\"columns\":[\"id\"]}]}",
        .indexes_json = "{}",
    };
    const range: metadata.RangeRecord = .{
        .table_id = 201,
        .group_id = 401,
        .range_id = 401,
        .doc_identity_shard_id = 401,
        .doc_identity_range_id = 401,
        .start_key = "",
    };
    try store.updateStandaloneCatalog(group, 3, .{ .tables = &.{current}, .ranges = &.{range} });
    var lock_key_buf: [160]u8 = undefined;
    const lock_key = try fk_generation_publication.tableLockKey(&lock_key_buf, group, current.table_id);
    var plan_id: fk_generation_publication.Id = @splat(0);
    plan_id[0] = 1;
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        const value = RaftApplyStore.fkTableLockValue(.initial_support, plan_id);
        try txn.put(lock_key, &value);
        try txn.commit();
    }
    var finalized = current;
    finalized.read_schema_json = "";
    try std.testing.expectError(error.TableLifecycleConflict, store.updateStandaloneCatalog(group, 4, .{ .tables = &.{finalized} }));
    try std.testing.expectError(error.TableLifecycleConflict, store.updateStandaloneCatalog(group, 4, .{ .tables = &.{finalized}, .native_owner = owner }));
    try store.applyStandaloneCommand(group, .{ .upsert_schema_progress = .{ .table_id = current.table_id, .node_id = owner.node_id, .schema_version = 1 } });
    try std.testing.expectError(error.TableLifecycleConflict, store.updateStandaloneCatalog(group, 5, .{ .tables = &.{finalized}, .native_owner = owner }));
    try store.applyStandaloneCommand(group, .{ .upsert_schema_progress = .{ .table_id = current.table_id, .node_id = owner.node_id, .schema_version = 2 } });
    try store.updateStandaloneCatalog(group, 6, .{ .tables = &.{finalized}, .native_owner = owner });
    const rows = try store.listTables(alloc, group);
    defer store.freeTables(alloc, rows);
    try std.testing.expectEqual(@as(usize, 1), rows.len);
    try std.testing.expectEqualStrings("", rows[0].read_schema_json);
}

test "initial partial support begin survives restart and cancellation before child provision" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/fk-pending-support", .{tmp.sub_path});
    const group_id = group_ids.main_metadata_group_id;
    const child_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"fk","child_columns":["a","b"],"parent_table":"parent","parent_columns":["a","b"],"match":"partial"}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"a":{"type":"integer","nullable":true},"b":{"type":"integer","nullable":true}},"additionalProperties":false}}}}
    ;
    const parent_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["a","b"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"a":{"type":"integer","nullable":true},"b":{"type":"integer","nullable":true}},"additionalProperties":false}}}}
    ;
    const parent_before: metadata.TableRecord = .{
        .table_id = 201,
        .name = "parent",
        .schema_json = parent_json,
        .indexes_json = "{\"full_text_index_v1\":{\"type\":\"full_text\",\"_index_incarnation\":11}}",
    };
    const parent_range: metadata.RangeRecord = .{ .table_id = 201, .group_id = 401, .range_id = 401, .doc_identity_shard_id = 401, .doc_identity_range_id = 401, .start_key = "" };
    const support_json = (try @import("antfly_local_sources").schema_relational_witness_indexes.ensureCoverage(a, parent_json, &.{ "a", "b" })).?;
    const parent_after = try @import("../../api/tables.zig").applySchemaUpdateRecord(a, &parent_before, support_json);
    {
        var parsed = try std.json.parseFromSlice(std.json.Value, a, parent_after.indexes_json, .{});
        defer parsed.deinit();
        const next = parsed.value.object.get("full_text_index_v2") orelse return error.TestUnexpectedResult;
        const incarnation = @import("antfly_local_sources").api_coverage_policy.incarnation(next) orelse return error.TestUnexpectedResult;
        try std.testing.expect(incarnation != 11);
    }
    var plan: fk_generation_publication.InitialCreatePlan = undefined;
    {
        var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
        defer store.deinit();
        try store.applyStandaloneCommand(group_id, .{ .initialize_metadata_incarnation = "11111111111111111111111111111111".* });
        try store.applyStandaloneCommand(group_id, .{ .upsert_table = parent_before });
        try store.applyStandaloneCommand(group_id, .{ .upsert_range = parent_range });
        const prepared_json = try store.fkInitialCreatePrepareJson(a, group_id, .{
            .namespace_id = system_catalog.default_namespace_id,
            .logical_name = "child",
            .candidate = .{ .table_id = 0, .name = "", .schema_json = child_json },
        });
        const prepared = try std.json.parseFromSliceLeaky(fk_generation_publication.InitialCreatePrepare, a, prepared_json, .{});
        const derived = try fk_generation_publication.deriveInitialTransitions(a, prepared.child.table_id, prepared.child.name, child_json);
        var id: fk_generation_publication.Id = @splat(0);
        id[0] = 1;
        id[8] = 1;
        plan = .{
            .id = id,
            .retirement_scope = .local_owner,
            .catalog_id = prepared.catalog_id,
            .expected_catalog_revision = prepared.expected_catalog_revision,
            .tablespace_id = prepared.tablespace_id,
            .child = prepared.child,
            .child_ranges = prepared.child_ranges,
            .logical_name = "child",
            .namespace_id = system_catalog.default_namespace_id,
            .support_pending = true,
            .parents = &.{.{
                .table = parent_before,
                .ranges = &.{parent_range},
                .fences = &.{},
                .transitions = &.{derived[0].transition},
                .support_before = parent_before,
                .support_after = parent_after,
            }},
        };
        try plan.validate(a);
        var forged = plan;
        var forged_parent = plan.parents[0];
        var forged_after = parent_after;
        forged_after.description = "smuggled DDL";
        forged_parent.support_after = forged_after;
        forged.parents = &.{forged_parent};
        const forged_begin = try std.json.Stringify.valueAlloc(a, fk_generation_publication.InitialCommand{
            .plan_id = id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 0,
            .action = .begin,
            .plan = forged,
        }, .{});
        const before = try store.systemCatalogMeta(a, group_id);
        try std.testing.expectError(error.InvalidGenerationPublication, store.preflightFkInitialCreateCommand(group_id, forged_begin));
        var reused = try std.json.parseFromSlice(std.json.Value, a, parent_after.indexes_json, .{});
        defer reused.deinit();
        const next = reused.value.object.getPtr("full_text_index_v2") orelse return error.TestUnexpectedResult;
        try next.object.put(a, "_index_incarnation", .{ .integer = 11 });
        var reused_after = parent_after;
        reused_after.indexes_json = try std.json.Stringify.valueAlloc(a, reused.value, .{});
        var reused_parent = plan.parents[0];
        reused_parent.support_after = reused_after;
        var reused_plan = plan;
        reused_plan.parents = &.{reused_parent};
        const reused_begin = try std.json.Stringify.valueAlloc(a, fk_generation_publication.InitialCommand{
            .plan_id = id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 0,
            .action = .begin,
            .plan = reused_plan,
        }, .{});
        try std.testing.expectError(error.InvalidGenerationPublication, store.preflightFkInitialCreateCommand(group_id, reused_begin));
        const after = try store.systemCatalogMeta(a, group_id);
        try std.testing.expectEqual(before.revision, after.revision);
        try std.testing.expectEqual(before.next_id, after.next_id);
        const begin = try std.json.Stringify.valueAlloc(a, fk_generation_publication.InitialCommand{
            .plan_id = id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 0,
            .action = .begin,
            .plan = plan,
        }, .{});
        try store.preflightFkInitialCreateCommand(group_id, begin);
        try store.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = begin });
        const tables = try store.listTables(a, group_id);
        try std.testing.expectEqual(@as(usize, 1), tables.len);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(parent_after, tables[0]));
        const work_json = try store.fkInitialCreateWorkJson(a, group_id, 0);
        const work = try std.json.parseFromSliceLeaky(?fk_generation_publication.InitialWork, a, work_json, .{});
        try std.testing.expectEqual(fk_generation_publication.InitialPhase.preparing_support, work.?.phase);
        try std.testing.expect(work.?.target == .seal_support);
        var preseal_provisioning = try store.captureProvisioningCatalog(a, group_id);
        defer preseal_provisioning.deinit(a);
        try std.testing.expectEqual(@as(usize, 0), preseal_provisioning.initial_fk_owners.len);
        try std.testing.expectEqualStrings("true", try store.fkGenerationTableLockedJson(a, group_id, parent_before.table_id));
        // A placement for a hidden group must be bound to this exact durable
        // reservation. A forged plan ID cannot create a routable owner.
        const child_group_id = plan.child_ranges[0].group_id;
        var reservation_key_buf: [160]u8 = undefined;
        const reservation_key = try fk_generation_publication.initialGroupKey(&reservation_key_buf, group_id, child_group_id);
        const legitimate = (fk_generation_publication.InitialGroupReservation{
            .plan_id = plan.id,
            .child_table_id = plan.child.table_id,
            .range_id = plan.child_ranges[0].range_id,
            .plan_digest = try plan.digest(a),
            .retirement_scope = plan.retirement_scope,
        }).encode();
        var forged_reservation = legitimate;
        forged_reservation[0] ^= 0xff;
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try txn.put(reservation_key, &forged_reservation);
            try txn.commit();
        }
        try store.applyStandaloneCommand(group_id, .{ .register_node = .{ .node_id = 7, .role = "data", .lifecycle = metadata_table_manager.node_lifecycle_active } });
        try std.testing.expectError(error.InvalidGenerationPublication, store.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
            .expected_metadata_version = null,
            .expected_version_fence = 0,
            .expected_target_drain_requested = false,
            .replacement = .{ .record = .{ .group_id = child_group_id, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
        } }));
        const rejected_placements = try store.listPlacementIntents(a, group_id);
        try std.testing.expectEqual(@as(usize, 0), rejected_placements.len);
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try txn.put(reservation_key, &legitimate);
            try txn.commit();
        }
        try store.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
            .expected_metadata_version = null,
            .expected_version_fence = 0,
            .expected_target_drain_requested = false,
            .replacement = .{ .record = .{ .group_id = child_group_id, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
        } });
        const hidden_placements = try store.listPlacementIntents(a, group_id);
        // A support-pending plan has not sealed its final digest. Even an
        // otherwise valid reservation cannot create a stale-digest owner.
        try std.testing.expectEqual(@as(usize, 0), hidden_placements.len);
        {
            var txn = try store.store.beginReadTxn();
            defer txn.abort();
            try std.testing.expect(try store.fkGenerationTableLockedTxn(&txn, group_id, parent_before.table_id));
        }
        // The support lock must not starve the exact reconciler finalization
        // after owner progress, but neither may a forged caller retire the
        // read layout early or smuggle unrelated index changes.
        var finalized = try metadata_table_manager.cloneTable(a, parent_after);
        try @import("../schema_migration_finalization.zig").apply(a, &finalized);
        try store.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
            .expected_metadata_version = null,
            .expected_version_fence = 0,
            .expected_target_drain_requested = false,
            .replacement = .{ .record = .{ .group_id = 401, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
        } });
        try store.applyStandaloneCommand(group_id, .{ .upsert_table = finalized });
        var unsettled = try store.listTables(a, group_id);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(parent_after, unsettled[0]));
        store.freeTables(a, unsettled);
        try store.applyStandaloneCommand(group_id, .{ .upsert_schema_progress = .{ .table_id = 201, .node_id = 7, .schema_version = 2 } });
        {
            var progress_txn = try store.store.beginReadTxn();
            defer progress_txn.abort();
            const indexed_ranges = try store.indexedTableRangeIdsTxn(a, &progress_txn, group_id, 201);
            try std.testing.expectEqual(@as(usize, 1), indexed_ranges.len);
            const placed = try store.listPlacementIntents(a, group_id);
            try std.testing.expectEqual(@as(usize, 1), placed.len);
            try std.testing.expect(try store.schemaMigrationReadyTxn(&progress_txn, group_id, 201, 2));
        }
        var forged_finalized = finalized;
        forged_finalized.indexes_json = "{\"unrelated\":{\"type\":\"full_text\"}}";
        try store.applyStandaloneCommand(group_id, .{ .upsert_table = forged_finalized });
        unsettled = try store.listTables(a, group_id);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(parent_after, unsettled[0]));
        store.freeTables(a, unsettled);
        try store.applyStandaloneCommand(group_id, .{ .upsert_table = finalized });
        const settled = try store.listTables(a, group_id);
        try std.testing.expectEqual(@as(usize, 1), settled.len);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(finalized, settled[0]));
        const fence: @import("antfly_local_sources").storage_db_relational_integrity_topology_contract.Fence = .{
            .transition_id = 1,
            .attempt = 1,
            .peer_group_id = parent_range.group_id,
            .owner_group_id = parent_range.group_id,
            .role = .child_generation_parent,
            .namespace = .{ .table_id = parent_before.table_id, .shard_id = 401, .range_id = 401 },
            .catalog_digest = @splat(2),
        };
        var sealed = plan;
        var sealed_parent = plan.parents[0];
        sealed_parent.table = finalized;
        sealed_parent.fences = &.{fence};
        sealed.parents = &.{sealed_parent};
        sealed.support_pending = false;
        try sealed.validate(a);
        const pending: fk_generation_publication.InitialPublication = .{
            .plan = plan,
            .plan_digest = try plan.digest(a),
            .candidate = try plan.candidateIdentity(a),
            .revision = 1,
            .phase = .preparing_support,
        };
        var forged_seal = sealed;
        var forged_child = sealed.child;
        forged_child.description = "unreserved child setting";
        forged_seal.child = forged_child;
        try std.testing.expectError(error.GenerationPublicationChanged, pending.apply(a, .{
            .plan_id = plan.id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 1,
            .action = .seal_support,
            .plan = forged_seal,
        }));
        forged_seal = sealed;
        forged_seal.tablespace_id +%= 1;
        try std.testing.expectError(error.GenerationPublicationChanged, pending.apply(a, .{
            .plan_id = plan.id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 1,
            .action = .seal_support,
            .plan = forged_seal,
        }));
        forged_seal = sealed;
        forged_seal.retirement_scope = .hosted_store;
        try std.testing.expectError(error.GenerationPublicationChanged, pending.apply(a, .{
            .plan_id = plan.id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 1,
            .action = .seal_support,
            .plan = forged_seal,
        }));
        const accepted = try pending.apply(a, .{
            .plan_id = plan.id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 1,
            .action = .seal_support,
            .plan = sealed,
        });
        try std.testing.expectEqual(fk_generation_publication.InitialPhase.provisioning_child, accepted.phase);
    }
    {
        var recovered = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
        defer recovered.deinit();
        const work_json = try recovered.fkInitialCreateWorkJson(a, group_id, 0);
        const work = try std.json.parseFromSliceLeaky(?fk_generation_publication.InitialWork, a, work_json, .{});
        try std.testing.expectEqual(fk_generation_publication.InitialPhase.preparing_support, work.?.phase);
        const cancel = try std.json.Stringify.valueAlloc(a, fk_generation_publication.InitialCommand{
            .plan_id = plan.id,
            .child_table_id = plan.child.table_id,
            .expected_revision = 1,
            .action = .cancel,
        }, .{});
        try recovered.applyStandaloneCommand(group_id, .{ .apply_fk_initial_create = cancel });
        const status_json = try recovered.fkInitialCreateStatusJson(a, group_id, plan.child.table_id);
        const status = try std.json.parseFromSliceLeaky(fk_generation_publication.InitialPublication, a, status_json, .{});
        try std.testing.expectEqual(fk_generation_publication.InitialPhase.canceled, status.phase);
        var terminal_key_buf: [160]u8 = undefined;
        var terminal_txn = try recovered.store.beginReadTxn();
        const terminal_bytes = try terminal_txn.get(try fk_generation_publication.initialGroupKey(&terminal_key_buf, group_id, plan.child_ranges[0].group_id));
        const terminal_proof = try fk_generation_publication.InitialGroupReservation.decode(terminal_bytes);
        terminal_txn.abort();
        try std.testing.expect(terminal_proof.canceled);
        try std.testing.expectEqual(plan.child_ranges[0].range_id, terminal_proof.range_id);
        try std.testing.expectEqual(plan.child.table_id, terminal_proof.child_table_id);
        try std.testing.expectEqualSlices(u8, &status.plan_digest, &terminal_proof.plan_digest);
        try std.testing.expectEqualSlices(u8, &plan.id, &terminal_proof.plan_id);
        // The canceled reservation survives restart as a compact tombstone.
        // No late placement proposal may recreate this unpublished owner.
        try recovered.applyStandaloneCommand(group_id, .{ .register_node = .{ .node_id = 8, .role = "data", .lifecycle = metadata_table_manager.node_lifecycle_active } });
        try recovered.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
            .expected_metadata_version = null,
            .expected_version_fence = 0,
            .expected_target_drain_requested = false,
            .replacement = .{ .record = .{ .group_id = plan.child_ranges[0].group_id, .replica_id = 2, .local_node_id = 8 }, .store_id = 0, .peer_node_ids = &.{8} },
        } });
        const after_cancel_placements = try recovered.listPlacementIntents(a, group_id);
        for (after_cancel_placements) |placement| {
            try std.testing.expect(placement.record.group_id != plan.child_ranges[0].group_id or placement.record.local_node_id != 8);
        }
        try std.testing.expectEqualStrings("false", try recovered.fkGenerationTableLockedJson(a, group_id, parent_before.table_id));
        var txn = try recovered.store.beginReadTxn();
        defer txn.abort();
        try std.testing.expect(!try recovered.fkGenerationTableLockedTxn(&txn, group_id, parent_before.table_id));
        try std.testing.expect(!try recovered.fkGenerationTableLockedTxn(&txn, group_id, plan.child.table_id));
        const tables = try recovered.listTables(a, group_id);
        try std.testing.expectEqual(@as(usize, 1), tables.len);
        try std.testing.expect((try @import("../../api/relational_witness_ddl.zig").cleanup(a, tables, tables[0])) != null);
        const no_work = try recovered.fkInitialCreateWorkJson(a, group_id, 0);
        try std.testing.expectEqualStrings("null", no_work);
    }
}
fn decodeMetadataCheckpoint(bytes: []const u8) !AppliedMetadataCheckpoint {
    if (bytes.len < 8) return error.InvalidMetadataApplyBatch;
    const index = std.mem.readInt(u64, bytes[0..8], .little);
    // Legacy rows held the full encoded batch after the applied index. Read
    // them without retaining that allocation; the next commit replaces them.
    if (!std.mem.startsWith(u8, bytes[8..], checkpoint_magic)) return AppliedMetadataCheckpoint.fromInput(index, .committed_entries, bytes[8..]);
    if (bytes.len != checkpoint_encoded_len or bytes[16] != 1) return error.InvalidMetadataApplyBatch;
    return .{ .commit_index = index, .input_kind = switch (bytes[17]) {
        0 => .committed_entries,
        1 => .snapshot,
        else => return error.InvalidMetadataApplyBatch,
    }, .input_bytes = std.mem.readInt(u64, bytes[18..26], .little) };
}

pub const CatalogProjectionSnapshot = apply_contract.CatalogProjectionSnapshot;
pub const CatalogCursor = apply_contract.CatalogCursor;

fn catalogProjectionDeadline(deadline_ns: ?u64, deadline_io: ?@import("antfly_runtime_abi").io_abi.Borrow) !void {
    if (deadline_ns) |deadline| {
        const now_ns: u64 = if (deadline_io) |borrow| blk: {
            var receiver = try borrow.receive();
            break :blk @intCast(@max(0, std.Io.Clock.awake.now(receiver.io()).nanoseconds));
        } else platform_time.monotonicNs();
        if (now_ns >= deadline) return error.CatalogRoutingSnapshotTimeout;
    }
}

