    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();

    const metadata_group_id: u64 = 21;
    const table = metadata.TableRecord{ .table_id = 7, .name = "docs", .min_ranges = 1 };
    const range = metadata.RangeRecord{
        .group_id = 301,
        .range_id = 301,
        .table_id = table.table_id,
        .start_key = "",
    };
    const table_upsert = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_table = table });
    defer std.testing.allocator.free(table_upsert);
    const range_upsert = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_range = range });
    defer std.testing.allocator.free(range_upsert);
    const seed_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = table_upsert },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = range_upsert },
    });
    defer std.testing.allocator.free(seed_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 2,
        .entries_bytes = seed_entries,
    });

    const legacy_fence = try store.getTableTransitionFence(metadata_group_id, table.table_id);
    try store.ensureDerivedCatalogIndexes(metadata_group_id);
    const legacy_admission = try store.captureTableRestoreAdmission(
        std.testing.allocator,
        metadata_group_id,
        table,
    );
    try std.testing.expectEqual(legacy_fence.generation, legacy_admission.expected_transition_generation);
    try std.testing.expect(legacy_admission.already_applied);
    const legacy_remove = try encodeTransitionCommand(std.testing.allocator, .{ .remove_table = .{
        .table_id = table.table_id,
        .expected_transition_generation = legacy_fence.generation,
    } });
    defer std.testing.allocator.free(legacy_remove);
    const remove_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 3, .entry_type = .normal, .data = legacy_remove },
    });
    defer std.testing.allocator.free(remove_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 3,
        .entries_bytes = remove_entries,
    });
    try store.ensureDerivedCatalogIndexes(metadata_group_id);
    try std.testing.expectError(
        error.TableTransitionActive,
        store.captureTableCreateGeneration(std.testing.allocator, metadata_group_id, table.table_id),
    );

    const unsafe_recreate = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .create = .{
            .expected_transition_generation = legacy_fence.generation,
            .table = table,
            .ranges = &.{range},
        } },
    });
    defer std.testing.allocator.free(unsafe_recreate);
    const recreate_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 4, .entry_type = .normal, .data = unsafe_recreate },
    });
    defer std.testing.allocator.free(recreate_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 4,
        .entries_bytes = recreate_entries,
    });
    try std.testing.expect((try store.getTable(std.testing.allocator, metadata_group_id, table.table_id)) == null);
    const retained = (try store.getRange(std.testing.allocator, metadata_group_id, range.group_id)).?;
    defer metadata_table_manager.freeRange(std.testing.allocator, retained);
    try std.testing.expect(metadata_table_manager.rangeRecordsEqual(retained, range));
}

test "table topology mutation atomically creates and drops catalog ranges" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(
        std.testing.allocator,
        ".zig-cache/tmp/{s}/metadata-table-topology-mutation",
        .{tmp.sub_path},
    );
    defer std.testing.allocator.free(root);
    const restored_root = try std.fmt.allocPrint(
        std.testing.allocator,
        ".zig-cache/tmp/{s}/metadata-table-topology-mutation-restored",
        .{tmp.sub_path},
    );
    defer std.testing.allocator.free(restored_root);

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();
    const metadata_group_id: u64 = 21;
    const table = metadata.TableRecord{ .table_id = 7, .name = "docs", .min_ranges = 2 };
    const ranges = [_]metadata.RangeRecord{
        .{
            .group_id = 301,
            .range_id = 301,
            .table_id = 7,
            .start_key = "",
            .end_key = "doc:m",
            .restore_backup_id = "backup-1",
            .restore_artifact_backup_id = "artifacts-1",
            .restore_location = "file:///backup",
            .restore_snapshot_path = "backup-1/groups/301",
        },
        .{ .group_id = 302, .range_id = 302, .table_id = 7, .start_key = "doc:m", .end_key = null },
    };
    const create = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .create = .{
            .expected_transition_generation = 0,
            .table = table,
            .ranges = &ranges,
        } },
    });
    defer std.testing.allocator.free(create);
    var decoded_create = (try decodeTransitionCommand(std.testing.allocator, create)).?;
    defer decoded_create.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), decoded_create.apply_table_topology.create.ranges.len);

    const create_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = create },
    });
    defer std.testing.allocator.free(create_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 1,
        .entries_bytes = create_entries,
    });
    {
        const projected_tables = try store.listTables(std.testing.allocator, metadata_group_id);
        defer store.freeTables(std.testing.allocator, projected_tables);
        const projected_ranges = try store.listRanges(std.testing.allocator, metadata_group_id);
        defer store.freeRanges(std.testing.allocator, projected_ranges);
        try std.testing.expectEqual(@as(usize, 1), projected_tables.len);
        try std.testing.expectEqual(@as(usize, 2), projected_ranges.len);
        const active_restores = try store.listActiveRestoreRanges(std.testing.allocator, metadata_group_id);
        defer store.freeRanges(std.testing.allocator, active_restores);
        try std.testing.expectEqual(@as(usize, 1), active_restores.len);
        try std.testing.expectEqual(@as(u64, 301), active_restores[0].group_id);
    }

    const create_fence = try store.getTableTransitionFence(metadata_group_id, table.table_id);
    try std.testing.expectEqual(@as(u64, 1), create_fence.generation);
    try store.ensureDerivedCatalogIndexes(metadata_group_id);
    const restore_admission = try store.captureTableRestoreAdmission(
        std.testing.allocator,
        metadata_group_id,
        table,
    );
    try std.testing.expectEqual(create_fence.generation, restore_admission.expected_transition_generation);
    try std.testing.expectEqual(@as(u64, 0), restore_admission.incarnation_generation);
    try std.testing.expect(restore_admission.already_applied);
    try store.verifyTableCreateProjectionExact(
        std.testing.allocator,
        metadata_group_id,
        table,
        &ranges,
    );
    try std.testing.expectError(
        error.TableAlreadyExists,
        store.verifyTableCreateProjectionExact(
            std.testing.allocator,
            metadata_group_id,
            table,
            ranges[0..1],
        ),
    );
    var create_projection = (try store.captureTableDropProjection(
        std.testing.allocator,
        metadata_group_id,
        table.name,
    )).?;
    defer create_projection.deinit(std.testing.allocator);
    try std.testing.expect(!create_projection.extension_owned);
    try std.testing.expect(create_projection.fence.membership(table.table_id).eql(
        create_fence.membership(table.table_id),
    ));
    // A current version marker must not suppress repair after an indexed read
    // proves that an individual derived row is missing.
    {
        var txn = try store.store.beginWriteTxn();
        var name_key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        try txn.delete(try tableNameIndexKey(&name_key_buf, metadata_group_id, table.name));
        try txn.commit();
    }
    try std.testing.expectError(
        error.InvalidDerivedCatalogIndex,
        store.captureTableDropProjection(std.testing.allocator, metadata_group_id, table.name),
    );
    // Marker-based ensure is intentionally cheap and cannot diagnose row
    // corruption; the explicit rebuild path must restore it.
    try store.ensureDerivedCatalogIndexes(metadata_group_id);
    try std.testing.expectError(
        error.InvalidDerivedCatalogIndex,
        store.captureTableDropProjection(std.testing.allocator, metadata_group_id, table.name),
    );
    try store.rebuildDerivedCatalogIndexes(metadata_group_id);
    var repaired_projection = (try store.captureTableDropProjection(
        std.testing.allocator,
        metadata_group_id,
        table.name,
    )).?;
    repaired_projection.deinit(std.testing.allocator);

    // A range admitted after the caller's snapshot advances the table fence.
    // The stale drop must therefore no-op without scanning unrelated ranges.
    const concurrent_range = metadata.RangeRecord{
        .group_id = 303,
        .range_id = 303,
        .table_id = table.table_id,
        .start_key = "doc:z",
        .end_key = null,
    };
    const concurrent_upsert = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_range = concurrent_range });
    defer std.testing.allocator.free(concurrent_upsert);
    const concurrent_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = concurrent_upsert },
    });
    defer std.testing.allocator.free(concurrent_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 2,
        .entries_bytes = concurrent_entries,
    });
    const incomplete_drop = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .drop = .{
            .table_id = table.table_id,
            .expected_name = table.name,
            .expected_transition_generation = create_fence.generation,
            .range_contract = .{ .legacy_group_ids = &.{301} },
        } },
    });
    defer std.testing.allocator.free(incomplete_drop);
    const incomplete_drop_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 3, .entry_type = .normal, .data = incomplete_drop },
    });
    defer std.testing.allocator.free(incomplete_drop_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 3,
        .entries_bytes = incomplete_drop_entries,
    });
    {
        const retained_tables = try store.listTables(std.testing.allocator, metadata_group_id);
        defer store.freeTables(std.testing.allocator, retained_tables);
        const retained_ranges = try store.listRanges(std.testing.allocator, metadata_group_id);
        defer store.freeRanges(std.testing.allocator, retained_ranges);
        try std.testing.expectEqual(@as(usize, 1), retained_tables.len);
        try std.testing.expectEqual(@as(usize, 3), retained_ranges.len);
    }

    const current_fence = try store.getTableTransitionFence(metadata_group_id, table.table_id);
    try std.testing.expectEqual(@as(u64, 2), current_fence.generation);

    // Even a legacy command with the current generation must contain the
    // exact range set; otherwise it could delete the table and orphan ranges.
    const incomplete_current_drop = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .drop = .{
            .table_id = table.table_id,
            .expected_name = table.name,
            .expected_transition_generation = current_fence.generation,
            .range_contract = .{ .legacy_group_ids = &.{ 301, 302 } },
        } },
    });
    defer std.testing.allocator.free(incomplete_current_drop);
    const incomplete_current_drop_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 4, .entry_type = .normal, .data = incomplete_current_drop },
    });
    defer std.testing.allocator.free(incomplete_current_drop_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 4,
        .entries_bytes = incomplete_current_drop_entries,
    });
    {
        const retained_tables = try store.listTables(std.testing.allocator, metadata_group_id);
        defer store.freeTables(std.testing.allocator, retained_tables);
        const retained_ranges = try store.listRanges(std.testing.allocator, metadata_group_id);
        defer store.freeRanges(std.testing.allocator, retained_ranges);
        try std.testing.expectEqual(@as(usize, 1), retained_tables.len);
        try std.testing.expectEqual(@as(usize, 3), retained_ranges.len);
    }

    const owned_member = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_extension_member = .{
            .extension_name = "memoryaf",
            .scope = .{ .kind = .table, .table_name = table.name },
            .object_kind = .index,
            .object_name = "memory_text",
            .table_name = table.name,
        },
    });
    defer std.testing.allocator.free(owned_member);
    const owned_member_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 5, .entry_type = .normal, .data = owned_member },
    });
    defer std.testing.allocator.free(owned_member_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 5,
        .entries_bytes = owned_member_entries,
    });
    var owned_projection = (try store.captureTableDropProjection(
        std.testing.allocator,
        metadata_group_id,
        table.name,
    )).?;
    defer owned_projection.deinit(std.testing.allocator);
    try std.testing.expect(owned_projection.extension_owned);

    // Derived indexes do not inflate Raft snapshots. Snapshot installation
    // discards any local copies and rebuilds them from authoritative rows.
    const snapshot = try store.snapshotBuilder().buildSnapshot(std.testing.allocator, metadata_group_id);
    defer std.testing.allocator.free(snapshot);
    {
        var restored = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = restored_root });
        defer restored.deinit();
        try std.testing.expect(try restored.snapshotBuilder().installSnapshot(
            std.testing.allocator,
            metadata_group_id,
            5,
            snapshot,
        ));
        try restored.ensureDerivedCatalogIndexes(metadata_group_id);
        var restored_projection = (try restored.captureTableDropProjection(
            std.testing.allocator,
            metadata_group_id,
            table.name,
        )).?;
        defer restored_projection.deinit(std.testing.allocator);
        try std.testing.expect(restored_projection.extension_owned);
        try std.testing.expect(restored_projection.fence.membership(table.table_id).eql(
            current_fence.membership(table.table_id),
        ));
        const restored_active = try restored.listActiveRestoreRanges(std.testing.allocator, metadata_group_id);
        defer restored.freeRanges(std.testing.allocator, restored_active);
        try std.testing.expectEqual(@as(usize, 1), restored_active.len);
    }

    const drop = try encodeTransitionCommand(std.testing.allocator, .{
        .apply_table_topology = .{ .drop = .{
            .table_id = table.table_id,
            .expected_name = table.name,
            .expected_transition_generation = current_fence.generation,
            .range_contract = .{ .membership = current_fence.membership(table.table_id) },
        } },
    });
    defer std.testing.allocator.free(drop);
    var decoded_drop = (try decodeTransitionCommand(std.testing.allocator, drop)).?;
    defer decoded_drop.deinit(std.testing.allocator);
    try std.testing.expect(decoded_drop.apply_table_topology.drop.range_contract == .membership);
    try std.testing.expect(decoded_drop.apply_table_topology.drop.range_contract.membership.eql(
        current_fence.membership(table.table_id),
    ));
    const drop_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 6, .entry_type = .normal, .data = drop },
    });
    defer std.testing.allocator.free(drop_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 6,
        .entries_bytes = drop_entries,
    });
    {
        const retained_tables = try store.listTables(std.testing.allocator, metadata_group_id);
        defer store.freeTables(std.testing.allocator, retained_tables);
        try std.testing.expectEqual(@as(usize, 1), retained_tables.len);
    }

    const remove_owned_member = try encodeTransitionCommand(std.testing.allocator, .{
        .remove_extension_member = .{
            .extension_name = "memoryaf",
            .object_kind = .index,
            .object_name = "memory_text",
        },
    });
    defer std.testing.allocator.free(remove_owned_member);
    const remove_owned_member_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 7, .entry_type = .normal, .data = remove_owned_member },
    });
    defer std.testing.allocator.free(remove_owned_member_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 7,
        .entries_bytes = remove_owned_member_entries,
    });
    const final_drop_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 8, .entry_type = .normal, .data = drop },
    });
    defer std.testing.allocator.free(final_drop_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 8,
        .entries_bytes = final_drop_entries,
    });
    const projected_tables = try store.listTables(std.testing.allocator, metadata_group_id);
    defer store.freeTables(std.testing.allocator, projected_tables);
    const projected_ranges = try store.listRanges(std.testing.allocator, metadata_group_id);
    defer store.freeRanges(std.testing.allocator, projected_ranges);
    try std.testing.expectEqual(@as(usize, 0), projected_tables.len);
    try std.testing.expectEqual(@as(usize, 0), projected_ranges.len);
    const active_after_drop = try store.listActiveRestoreRanges(std.testing.allocator, metadata_group_id);
    defer store.freeRanges(std.testing.allocator, active_after_drop);
    try std.testing.expectEqual(@as(usize, 0), active_after_drop.len);

    const delayed_upsert = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_range = ranges[0],
    });
    defer std.testing.allocator.free(delayed_upsert);
    const delayed_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 9, .entry_type = .normal, .data = delayed_upsert },
    });
    defer std.testing.allocator.free(delayed_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = metadata_group_id,
        .commit_index = 9,
        .entries_bytes = delayed_entries,
    });
    const ranges_after_delayed_upsert = try store.listRanges(std.testing.allocator, metadata_group_id);
    defer store.freeRanges(std.testing.allocator, ranges_after_delayed_upsert);
    try std.testing.expectEqual(@as(usize, 0), ranges_after_delayed_upsert.len);
}

test "metadata backup cohort atomically admits immutable plans and releases exact table locks" {
    const alloc = std.testing.allocator;
    const cohort = @import("antfly_local_sources").metadata_backup_cohort;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/backup-cohort", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const table: metadata.TableRecord = .{ .table_id = 9, .name = "rows", .schema_json = "{}" };
    const range: metadata.RangeRecord = .{ .table_id = 9, .group_id = 301, .start_key = "" };
    const owner: cohort.Owner = .{
        .table_name = table.name,
        .range_start = "",
        .range_end = "",
        .artifact_id = "cohort-700-owner-301",
        .fence = .{ .transition_id = 700, .attempt = 1, .admission_epoch = 1, .owner_group_id = 301, .peer_group_id = 301, .role = .backup_snapshot, .namespace = .{ .table_id = 9, .shard_id = 301, .range_id = 301 }, .catalog_digest = @splat(3) },
    };
    var job: cohort.Job = .{ .id = 700, .revision = 1, .backup_id = "backup", .location = "file:///backup", .connection = "backups", .tables = &.{.{ .table_id = 9, .name = "rows", .definition = metadata_table_manager.tableDefinitionFingerprint(table) }}, .state = .{ .metadata_digest = @splat(4), .owners = &.{owner} } };
    const table_bytes = try encodeTableRecord(alloc, table);
    defer alloc.free(table_bytes);
    const range_bytes = try encodeRangeRecord(alloc, range);
    defer alloc.free(range_bytes);
    var txn = try store.store.beginWriteTxn();
    var txn_open = true;
    defer if (txn_open) txn.abort();
    var buf: [192]u8 = undefined;
    try txn.put(try tableKeyForGroup(&buf, group_id, table.table_id), table_bytes);
    try txn.put(try rangeKeyForGroup(&buf, group_id, range.group_id), range_bytes);
    // Invalid or late private requests are deterministic no-ops, not apply
    // errors that could prevent an otherwise healthy Raft log from advancing.
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 0, .value = "{" });
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 1, .value = "{}" });
    try std.testing.expect(!try backupCohortLocksTableTxn(&txn, group_id, table.table_id));
    const first = try std.json.Stringify.valueAlloc(alloc, job, .{});
    defer alloc.free(first);
    const encoded = try encodeTransitionCommand(alloc, .{ .compare_and_set_backup_cohort = .{ .job_id = job.id, .expected_revision = 0, .value = first } });
    defer alloc.free(encoded);
    var decoded = (try decodeTransitionCommand(alloc, encoded)).?;
    defer decoded.deinit(alloc);
    try store.applyBackupCohortTxn(&txn, group_id, decoded.compare_and_set_backup_cohort);
    try std.testing.expect(try backupCohortLocksTableTxn(&txn, group_id, table.table_id));
    var active_key_buf: [192]u8 = undefined;
    _ = try txn.get(try backupCohortActiveKey(&active_key_buf, group_id, job.id));
    // A competing job cannot replace the lock, even with a valid source proof.
    var competitor = job;
    competitor.id = 701;
    var competing_owner = owner;
    competing_owner.fence.transition_id = 701;
    competitor.state.owners = &.{competing_owner};
    const competing = try std.json.Stringify.valueAlloc(alloc, competitor, .{});
    defer alloc.free(competing);
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = competitor.id, .expected_revision = 0, .value = competing });
    try std.testing.expectError(error.NotFound, txn.get(try backupCohortKeyForGroup(&buf, group_id, competitor.id)));
    inline for (.{ cohort.Phase.draining, cohort.Phase.capturing }) |phase| {
        const expected_revision = job.revision;
        job.revision += 1;
        job.state.phase = phase;
        const progress = try std.json.Stringify.valueAlloc(alloc, try cohort.Progress.fromJob(job, alloc), .{});
        defer alloc.free(progress);
        try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = expected_revision, .value = progress });
    }
    job.revision = 4;
    job.state.phase = .releasing;
    const sealed_progress = try std.json.Stringify.valueAlloc(alloc, try cohort.Progress.fromJob(job, alloc), .{});
    defer alloc.free(sealed_progress);
    // Release admission and the exact immutable source handle are one durable
    // checkpoint. Neither a missing receipt nor a different replica can pass.
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 3, .value = sealed_progress });
    var seal: cohort.SealReceipt = .{ .handle = .{ .fence = owner.fence, .digest = @splat(11) }, .source_node_id = 999 };
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 3, .value = sealed_progress, .seal = seal });
    var seal_key_buf: [192]u8 = undefined;
    try std.testing.expectError(error.NotFound, txn.get(try backupCohortOwnerKey(&seal_key_buf, group_id, job.id, "seal", 0)));
    seal.source_node_id = owner.capture_node_id;
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 3, .value = sealed_progress, .seal = seal });
    _ = try txn.get(try backupCohortOwnerKey(&seal_key_buf, group_id, job.id, "seal", 0));
    job.revision = 5;
    job.state.phase = .cancelling;
    const cancel_bytes = try std.json.Stringify.valueAlloc(alloc, try cohort.Progress.fromJob(job, alloc), .{});
    defer alloc.free(cancel_bytes);
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 4, .value = cancel_bytes });
    try std.testing.expect(try backupCohortLocksTableTxn(&txn, group_id, table.table_id));
    job.revision = 6;
    job.state.phase = .cancel_reclaiming;
    const released = try std.json.Stringify.valueAlloc(alloc, try cohort.Progress.fromJob(job, alloc), .{});
    defer alloc.free(released);
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 5, .value = released });
    try std.testing.expect(!try backupCohortLocksTableTxn(&txn, group_id, table.table_id));
    _ = try txn.get(try backupCohortActiveKey(&active_key_buf, group_id, job.id));
    job.revision = 7;
    job.state.phase = .cancelled;
    const complete = try std.json.Stringify.valueAlloc(alloc, try cohort.Progress.fromJob(job, alloc), .{});
    defer alloc.free(complete);
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 6, .value = complete });
    try std.testing.expect(!try backupCohortLocksTableTxn(&txn, group_id, table.table_id));
    try std.testing.expectError(error.NotFound, txn.get(try backupCohortActiveKey(&active_key_buf, group_id, job.id)));
    try std.testing.expectEqualStrings(first, try txn.get(try backupCohortKeyForGroup(&buf, group_id, job.id)));
    // Delayed admission cannot resurrect a terminal job or source lock.
    try store.applyBackupCohortTxn(&txn, group_id, .{ .job_id = job.id, .expected_revision = 0, .value = first });
    try std.testing.expect(!try backupCohortLocksTableTxn(&txn, group_id, table.table_id));
    try txn.commit();
    txn_open = false;
    const recovered_bytes = (try store.getBackupCohort(alloc, group_id, job.id)).?;
    defer alloc.free(recovered_bytes);
    var recovered = try std.json.parseFromSlice(cohort.Job, alloc, recovered_bytes, .{});
    defer recovered.deinit();
    try recovered.value.validate();
    try std.testing.expectEqual(cohort.Phase.cancelled, recovered.value.state.phase);
    try std.testing.expectEqual(@as(u64, 7), recovered.value.revision);
    try std.testing.expectEqual(@as(usize, 1), recovered.value.seals.len);
    try std.testing.expectEqualSlices(u8, &seal.handle.digest, &recovered.value.seals[0].handle.digest);
    const page = try store.listBackupCohorts(alloc, group_id, null, 1);
    defer docstore.DocStore.freeResults(alloc, page);
    try std.testing.expectEqual(@as(usize, 0), page.len);
}

test "system catalog active restore cursor resumes bounded target pages without terminal history" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/restore-name-cursor", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    const group = group_ids.main_metadata_group_id;
    const id: [16]u8 = @splat(9);
    var names: [70][32]u8 = undefined;
    var targets: [70]RaftApplyStore.RelationRestoreProjection.Target = undefined;
    for (&targets, &names, 0..) |*target, *name, index| target.* = .{ .table = .{ .table_id = 100 + index, .name = try std.fmt.bufPrint(name, "t{d:0>4}", .{100 + index}), .schema_json = "{}" } };
    const job: RaftApplyStore.RelationRestoreProjection = .{ .plan = .{ .id = id, .targets = &targets } };
    const json = try std.json.Stringify.valueAlloc(a, job, .{});
    defer a.free(json);
    const later_id: [16]u8 = @splat(10);
    const later: RaftApplyStore.RelationRestoreProjection = .{ .plan = .{ .id = later_id, .targets = &.{.{ .table = .{ .table_id = 200, .name = "later", .schema_json = "{}" } }} } };
    const later_json = try std.json.Stringify.valueAlloc(a, later, .{});
    defer a.free(later_json);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        var buf: [512]u8 = undefined;
        try txn.put(try restore_staging.jobKey(&buf, group, id), json);
        try txn.put(try restore_staging.activeKey(&buf, group, id), &id);
        try txn.put(try restore_staging.progressKey(&buf, group, id), "{}");
        for (targets) |target| {
            try txn.put(try restore_staging.nameKey(&buf, group, target.table.name), &id);
            try txn.put(try restore_staging.identityKey(&buf, group, .table, target.table.table_id), &id);
        }
        try txn.put(try restore_staging.jobKey(&buf, group, later_id), later_json);
        try txn.put(try restore_staging.activeKey(&buf, group, later_id), &later_id);
        try txn.put(try restore_staging.progressKey(&buf, group, later_id), "{}");
        try txn.put(try restore_staging.nameKey(&buf, group, "later"), &later_id);
        try txn.put(try restore_staging.identityKey(&buf, group, .table, 200), &later_id);
        for (0..1000) |index| {
            var terminal: [16]u8 = @splat(0);
            std.mem.writeInt(u64, terminal[8..16], index + 1, .big);
            try txn.put(try restore_staging.jobKey(&buf, group, terminal), "not-a-live-plan");
        }
        try txn.commit();
    }
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var buf: [512]u8 = undefined;
        try txn.put(try restore_staging.identityKey(&buf, group, .table, 100), &@as([16]u8, @splat(8)));
        var prefix_buf: [160]u8 = undefined;
        var source: RaftApplyStore.RelationRestoreSource = .{ .a = a, .txn = &txn, .group_id = group, .raw = .{ .cursor = try txn.openCursor(), .prefix = try restore_staging.activePrefix(&prefix_buf, group) } };
        defer source.deinit();
        try std.testing.expectError(error.InvalidCatalogRecord, source.nextAfter(""));
    }
    var read = try store.store.beginReadTxn();
    var read_open = true;
    defer if (read_open) read.abort();
    var prefix_buf: [160]u8 = undefined;
    var source: RaftApplyStore.RelationRestoreSource = .{ .a = a, .txn = &read, .group_id = group, .raw = .{ .cursor = try read.openCursor(), .prefix = try restore_staging.activePrefix(&prefix_buf, group) } };
    var source_open = true;
    defer if (source_open) source.deinit();
    const epoch: relation_reconciliation.Epoch = .{ .incarnation = @splat(1), .revision = 1 };
    const state = try relation_reconciliation.State.init(group, try relation_reconciliation.nextJobId(null), epoch);
    var first = try relation_reconciliation.Page.prepareSource(a, state, epoch, &source);
    defer first.deinit();
    try std.testing.expectEqual(@as(u64, 64), first.after.pass.rows);
    try std.testing.expectEqual(relation_reconciliation.Phase.building, first.after.phase);
    const lookahead = (try source.nextAfter(first.after.cursor())).?;
    try std.testing.expectEqual(@as(u64, 164), lookahead.table_id);
    try std.testing.expectEqual(@as(usize, 1), source.loaded_jobs);
    var boundary_buf: [512]u8 = undefined;
    var base_buf: [256]u8 = undefined;
    const boundary = try std.fmt.bufPrint(&boundary_buf, "{s}:{x:0>4}", .{ try restore_staging.activeKey(&base_buf, group, id), @as(usize, 69) });
    try std.testing.expectEqual(@as(u64, 200), (try source.nextAfter(boundary)).?.table_id);
    // Rewind from an unadmitted lookahead in another job to the last committed
    // target in the first job. Neither the six remaining rows nor job two may
    // disappear when the raw active-index cursor has already moved forward.
    var second = try relation_reconciliation.Page.prepareSource(a, first.after, epoch, &source);
    defer second.deinit();
    try std.testing.expectEqual(@as(u64, 71), second.after.expected.rows);
    try std.testing.expectEqual(relation_reconciliation.Phase.verifying_source, second.after.phase);
    try std.testing.expectEqual(@as(usize, 4), source.loaded_jobs);
    var replay = try relation_reconciliation.Page.prepareSource(a, second.after, epoch, &source);
    defer replay.deinit();
    try std.testing.expectEqual(@as(u64, 64), replay.after.pass.rows);
    try std.testing.expectEqual(@as(usize, 5), source.loaded_jobs);
    source.deinit();
    source_open = false;
    read.abort();
    read_open = false;
    try std.testing.expectEqualStrings("t0100", first.claims[0].key.name);
    try std.testing.expect(first.claims[0].reservation);
    try std.testing.expect((try first.claims[0].entry()).active == null);
}

fn reconcileRestoreNamesForTest(store: *RaftApplyStore, a: std.mem.Allocator, initial: relation_reconciliation.State) !relation_reconciliation.State {
    const r = relation_reconciliation;
    const group = initial.group_id;
    const prior_root = blk: {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        var buf: [128]u8 = undefined;
        break :blk if (try RaftApplyStore.stagingGet(&read, try r.rootKey(&buf, group))) |bytes| try r.Generation.decode(bytes) else null;
    };
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        var buf: [128]u8 = undefined;
        if (try RaftApplyStore.stagingGet(&txn, try r.jobKey(&buf, group))) |bytes| {
            const prior = try r.State.decode(bytes);
            if (!std.meta.eql(initial, prior)) {
                try std.testing.expectEqual(r.Phase.ready, prior.phase);
                // A fixture with an activated root already has a completed
                // generation. Use the real CAS/retirement transition rather
                // than resetting its job or reusing the sealed generation.
                try r.start(&txn, &initial, initial.epoch, bytes);
            }
        } else {
            try r.start(&txn, &initial, initial.epoch, null);
        }
        try txn.commit();
    }
    var state = initial;
    var pages: usize = 0;
    while (state.phase != .ready) {
        pages += 1;
        if (pages > 32) return error.TestExpectedBoundedProgress;
        var page = try store.prepareRelationReconciliationPage(a, state);
        defer page.deinit();
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        var journal = command_journal.Journal.initVerification(a, &txn, group, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        try page.apply(&txn, initial.epoch);
        try store.verifyReconciliationSourceOwnersTxn(&txn, group, &journal);
        var before = journal.beforeReader();
        var replay = try r.ReplayVerifier(command_journal.Journal.BeforeReader, docstore.DocStore.Txn).init(a, &before, &txn, group);
        defer replay.deinit();
        var keys = journal.originals.keyIterator();
        while (keys.next()) |key| try replay.feed(key.*);
        try replay.finish();
        try RaftApplyStore.verifyReconciliationEpochTxn(&txn, group, &journal);
        try RaftApplyStore.verifyRelationSourceDeltaTxn(a, &txn, group, &journal);
        try verifyReconciliationGroupTxn(&txn, group);
        try journal.accept();
        try txn.commit();
        state = page.after;
    }
    var read = try store.store.beginReadTxn();
    defer read.abort();
    var buf: [128]u8 = undefined;
    const observed_root = if (try RaftApplyStore.stagingGet(&read, try r.rootKey(&buf, group))) |bytes| try r.Generation.decode(bytes) else null;
    try std.testing.expect(std.meta.eql(prior_root, observed_root));
    return state;
}

test "system catalog restore reconciliation authenticates source phases and canonical physical aliases" {
    try exerciseRestoreReconciliationCoverage(.relations);
}

test "system catalog relation namespace transaction occupancy restore authenticates typed memberships across native fault paths" {
    try exerciseRestoreReconciliationCoverage(.constraint_names);
}

fn exerciseRestoreReconciliationCoverage(coverage: relation_reconciliation.Coverage) !void {
    const a = std.testing.allocator;
    const r = relation_reconciliation;
    const group = group_ids.main_metadata_group_id;
    const id: [16]u8 = @splat(9);
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/restore-name-apply", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    var names: [70][32]u8 = undefined;
    var schemas: [70][256]u8 = undefined;
    var targets: [70]RaftApplyStore.RelationRestoreProjection.Target = undefined;
    for (&targets, &names, &schemas, 0..) |*target, *name, *schema, index| {
        const table_name = try std.fmt.bufPrint(name, "t{d:0>4}", .{100 + index});
        target.* = .{
            .table = .{ .table_id = 100 + index, .name = table_name, .schema_json = try std.fmt.bufPrint(schema, "{{\"version\":2,\"relational_indexes\":[{{\"name\":\"new_idx_{d:0>4}\"}}],\"checks\":[{{\"name\":\"shared\"}},{{\"name\":\"new_check\"}}]}}", .{index}) },
            .replace = .{ .table = .{ .table_id = 1000 + index, .name = table_name, .schema_json = "{\"version\":1,\"checks\":[{\"name\":\"shared\"},{\"name\":\"old_check\"}]}" } },
        };
    }
    const job: RaftApplyStore.RelationRestoreProjection = .{ .plan = .{ .id = id, .targets = &targets } };
    const json = try std.json.Stringify.valueAlloc(a, job, .{});
    defer a.free(json);
    const epoch: r.Epoch = .{ .incarnation = @splat(1), .revision = 1 };
    const initial = try r.State.initWithCoverage(group, try r.nextJobId(null), epoch, coverage);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try r.advanceSource(&txn, group);
        var buf: [512]u8 = undefined;
        try txn.put(try restore_staging.jobKey(&buf, group, id), json);
        try txn.put(try restore_staging.activeKey(&buf, group, id), &id);
        try txn.put(try restore_staging.progressKey(&buf, group, id), "{}");
        for (targets) |target| {
            const old = target.replace.?.table;
            const encoded = try encodeTableRecord(a, .{ .table_id = old.table_id, .name = old.name, .schema_json = old.schema_json });
            defer a.free(encoded);
            try txn.put(try tableKeyForGroup(&buf, group, old.table_id), encoded);
            try txn.put(try restore_staging.nameKey(&buf, group, target.table.name), &id);
            try txn.put(try restore_staging.identityKey(&buf, group, .table, target.table.table_id), &id);
            try txn.put(try restore_staging.identityKey(&buf, group, .old_table, old.table_id), &id);
        }
        try r.start(&txn, &initial, epoch, null);
        try txn.commit();
    }
    // Authentic pending bytes are still premature before their source bookmark.
    // Test native authority independently of the structural fingerprint fence.
    {
        var page = try store.prepareRelationReconciliationPage(a, initial);
        defer page.deinit();
        try std.testing.expectEqual(@as(u64, 64), page.after.pass.rows);
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var journal = command_journal.Journal.initVerification(a, &txn, group, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        try page.apply(&txn, epoch);
        try store.verifyReconciliationSourceOwnersTxn(&txn, group, &journal);
        var reserved = try RaftApplyStore.relationRestoreTargetSnapshotWithCoverage(a, &txn, group, id, targets[0], false, coverage);
        defer reserved.deinit();
        var buf: [512]u8 = undefined;
        const claim = reserved.claims()[0];
        try txn.put(try r.candidateKey(&buf, &initial, claim.key), &(try (try claim.entry()).encode()));
        try std.testing.expectError(error.InvalidCatalogRecord, store.verifyReconciliationSourceOwnersTxn(&txn, group, &journal));
    }
    const ready = try reconcileRestoreNamesForTest(&store, a, initial);
    try std.testing.expectEqual(@as(u64, 140), ready.expected.rows);
    try std.testing.expectEqual(@as(u64, if (coverage == .relations) 210 else 490), ready.expected.claims);
    const proof = try store.prepareRelationPublicationProof(a, ready);
    {
        // The replica pool owns the actual native snapshots, not a second
        // leader-only copy. Each call advances at most one page.
        const lifetime = relation_worker.publication_snapshot_lifetime_ns;
        try std.testing.expectError(error.CatalogPublicationProofPending, store.requireRelationPublicationProof(ready, 0));
        try std.testing.expect(store.snapshotBuilder().isApplyRetryable(group, error.CatalogPublicationProofPending));
        try std.testing.expect(!store.snapshotBuilder().isApplyRetryable(group, error.ResourceTemporarilyUnavailable));
        try std.testing.expect(!store.snapshotBuilder().isApplyRetryable(group, error.InvalidCatalogRecord));
        try std.testing.expect(!store.snapshotBuilder().isApplyRetryable(group, error.OutOfMemory));
        var slot_index: usize = 0;
        while (store.relation_publication_pool.slots[slot_index] == null or store.relation_publication_pool.slots[slot_index].?.group != group) : (slot_index += 1) {}
        const preparation = &store.relation_publication_pool.slots[slot_index].?.preparation;
        try std.testing.expectEqual(@as(u64, 64), preparation.scan.?.verifier.state.pass.rows);
        try std.testing.expect((try store.stepRelationPublicationProof(ready, lifetime - 1)) == null);
        const before_renewal = preparation.scan.?.verifier.state;
        try store.expireRelationPublicationProofs(lifetime);
        try std.testing.expect(std.meta.eql(before_renewal, preparation.scan.?.verifier.state));
        var now: u64 = lifetime;
        var steps: usize = 2;
        while (true) {
            now += 1;
            steps += 1;
            if (try store.stepRelationPublicationProof(ready, now)) |finished| {
                try std.testing.expect(std.meta.eql(proof, finished));
                break;
            }
        }
        try std.testing.expect(steps >= 4);
        try std.testing.expect(preparation.scan == null);
        try std.testing.expect(std.meta.eql(proof, (try store.stepRelationPublicationProof(ready, now + 1)).?));
        try store.cancelRelationPublicationProof(group);
        try std.testing.expect((try store.stepRelationPublicationProof(ready, now + 2)) == null);
        try store.expireRelationPublicationProofs(now + 2 + lifetime);
        for (store.relation_publication_pool.slots) |slot| if (slot) |value| {
            try std.testing.expect(value.group != group);
        };
    }
    {
        const scan = try store.beginRelationPublicationScan(a, ready);
        defer scan.deinit();
        try std.testing.expect((try scan.step(null)) == null);
        try std.testing.expectEqual(@as(u64, 64), scan.verifier.state.pass.rows);
        try std.testing.expect(scan.open);
        var steps: usize = 1;
        while (true) {
            const prior = scan.verifier.state;
            try scan.renew();
            try std.testing.expect(std.meta.eql(prior, scan.verifier.state));
            steps += 1;
            if (try scan.step(null)) |finished| {
                try std.testing.expect(std.meta.eql(proof, finished));
                break;
            }
        }
        try std.testing.expect(steps >= 4);
        try std.testing.expect(!scan.open);
        try scan.renew(); // Completed evidence never reopens a snapshot.
        try std.testing.expect(std.meta.eql(proof, (try scan.step(null)).?));
    }
    // Both source and candidate phases release every cursor/owned plan on
    // cancellation. No partial source seal can be returned as a proof.
    for ([_]bool{ false, true }) |candidate_phase| {
        const scan = try store.beginRelationPublicationScan(a, ready);
        defer scan.deinit();
        if (candidate_phase) while (scan.verifier.state.phase == .verifying_source) {
            try std.testing.expect((try scan.step(null)) == null);
        };
        var cancelled = std.atomic.Value(bool).init(true);
        try std.testing.expectError(error.CatalogPublicationScanCancelled, scan.step(&cancelled));
        try std.testing.expect(!scan.open);
        try std.testing.expectError(error.CatalogPublicationScanClosed, scan.step(null));
        scan.cancel();
    }
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        try std.testing.expect(try proof.matchesTxn(&txn));
        var buf: [128]u8 = undefined;
        try txn.put(try r.rootKey(&buf, group), &(try r.Generation.of(&ready).encode()));
        try std.testing.expect(!try proof.matchesTxn(&txn));
        var wrong_group = r.Generation.of(&ready);
        wrong_group.group_id += 1;
        try txn.put(try r.rootKey(&buf, group), &(try wrong_group.encode()));
        try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.prepareRelationPublicationProofTxn(a, &txn, ready));
    }
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        try r.advanceSource(&txn, group);
        try std.testing.expect(!try proof.matchesTxn(&txn));
        try std.testing.expectError(error.CatalogGenerationChanged, RaftApplyStore.prepareRelationPublicationProofTxn(a, &txn, ready));
    }
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var buf: [128]u8 = undefined;
        var advanced: [8]u8 = undefined;
        std.mem.writeInt(u64, &advanced, proof.applied_index + 1, .little);
        try txn.put(try RaftApplyStore.keyForGroup(&buf, group), &advanced);
        try std.testing.expect(!try proof.matchesTxn(&txn));
    }
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var forged = ready;
        forged.expected.source_hash[0] ^= 1;
        var buf: [128]u8 = undefined;
        try txn.put(try r.jobKey(&buf, group), &(try forged.encode()));
        // Structural consistency alone cannot authenticate a ready source
        // seal. The complete native source pass must independently reject it.
        try verifyReconciliationGroupTxn(&txn, group);
        try std.testing.expect(!try proof.matchesTxn(&txn));
        try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.prepareRelationPublicationProofTxn(a, &txn, forged));
    }
    {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var journal = command_journal.Journal.initVerification(a, &txn, group, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        var buf: [512]u8 = undefined;
        const key = try r.candidateKey(&buf, &ready, .{ .namespace_id = system_catalog.default_namespace_id, .name = "t0100" });
        var forged = try relation_names.Entry.decode(try txn.get(key));
        try std.testing.expectEqual(@as(u64, 1000), forged.active.?.table_id);
        try std.testing.expectEqual(@as(u64, 100), forged.pending.?.table_id);
        forged.pending.?.publication_id[0] ^= 1;
        try txn.put(key, &(try forged.encode()));
        try std.testing.expectError(error.InvalidCatalogRecord, store.verifyReconciliationSourceOwnersTxn(&txn, group, &journal));
        try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.prepareRelationPublicationProofTxn(a, &txn, ready));
    }
    if (coverage == .constraint_names) for (0..4) |fault| {
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var journal = command_journal.Journal.initVerification(a, &txn, group, RaftApplyStore.relationSourceReplayBeforeKey);
        defer journal.deinit();
        try journal.attach();
        var buf: [512]u8 = undefined;
        const key = try r.candidateKey(&buf, &ready, .{ .namespace_id = system_catalog.default_namespace_id, .name = "new_check", .membership_table_id = 100 });
        var forged = try relation_names.Entry.decode(try txn.get(key));
        try std.testing.expect(forged.active == null);
        try std.testing.expectEqual(relation_names.Kind.constraint_name, forged.pending.?.kind);
        switch (fault) {
            0 => try txn.delete(key),
            1 => {
                forged.pending.?.publication_id[0] ^= 1;
                try txn.put(key, &(try forged.encode()));
            },
            2 => {
                forged.pending.?.table_id += 1;
                try txn.put(key, &(try forged.encode()));
            },
            else => {
                forged.pending.?.kind = .table;
                try txn.put(key, &(try forged.encode()));
            },
        }
        if (fault != 0) try std.testing.expectError(error.InvalidCatalogRecord, store.verifyReconciliationSourceOwnersTxn(&txn, group, &journal));
        try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.prepareRelationPublicationProofTxn(a, &txn, ready));
        try std.testing.expect(try proof.matchesTxn(&txn)); // Scalar fences alone are insufficient.
    };
    {
        const Heartbeat = struct {
            fn apply(owner: *RaftApplyStore, alloc: std.mem.Allocator, metadata_group: u64, index: u64) !void {
                const wire = try encodeTransitionCommand(alloc, .{ .upsert_store_heartbeat = .{
                    .store_id = 20,
                    .node_id = 30,
                    .reporter_incarnation = 77,
                    .status_generation = 1,
                    .available_bytes = index,
                } });
                defer alloc.free(wire);
                const entries = try raft_state_machine.encodeCommittedEntries(alloc, &.{.{ .term = 1, .index = index, .entry_type = .normal, .data = wire }});
                defer alloc.free(entries);
                var outcome = try owner.applyCommittedBatch(metadata_group, index, entries);
                defer outcome.deinit();
            }
        };
        try store.applyStandaloneCommand(group, .{ .register_store = .{ .store_id = 20, .node_id = 30, .reporter_incarnation = 77, .status_generation = 1 } });
        var index = try store.durableAppliedIndex(group) + 1;
        try Heartbeat.apply(&store, a, group, index);
        try store.cancelRelationPublicationProof(group);
        try std.testing.expect((try store.stepRelationPublicationProof(ready, index)) == null);
        index += 1;
        try Heartbeat.apply(&store, a, group, index);
        try std.testing.expect((try store.stepRelationPublicationProof(ready, index)) == null);
        for (store.relation_publication_pool.slots) |slot| if (slot) |value| if (value.group == group) {
            const progress = value.preparation.scan.?.verifier.state;
            try std.testing.expect(progress.phase != .verifying_source or progress.pass.rows > 64);
        };
        var finished: ?RaftApplyStore.RelationPublicationProof = null;
        for (0..32) |_| {
            index += 1;
            try Heartbeat.apply(&store, a, group, index);
            if (try store.stepRelationPublicationProof(ready, index)) |complete| {
                finished = complete;
                break;
            }
        }
        const complete = finished orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(index, complete.applied_index);
        {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            try std.testing.expect(try complete.matchesTxn(&read));
        }
        // A non-Raft writer breaks adoption even without a changed applied
        // watermark or semantic source epoch. No native activation is added.
        try store.applyStandaloneCommand(group, .{ .upsert_store = .{ .store_id = 20, .node_id = 30, .reporter_incarnation = 77, .status_generation = 1 } });
        try std.testing.expect(!store.relationProofTracking(group).canAdopt(complete.fence.?, index, index));
        try std.testing.expect((try store.stepRelationPublicationProof(ready, index + 1)) == null);
        var standalone_finished = false;
        for (0..32) |round| {
            try store.applyStandaloneCommand(group, .{ .upsert_store_heartbeat = .{ .store_id = 20, .node_id = 30, .reporter_incarnation = 77, .status_generation = 1, .available_bytes = round } });
            if (try store.stepRelationPublicationProof(ready, index + 2 + round)) |standalone_proof| {
                try std.testing.expectEqual(index, standalone_proof.applied_index);
                standalone_finished = true;
                break;
            }
        }
        try std.testing.expect(standalone_finished);
    }
    for ([_]bool{ false, true }) |epoch_change| {
        const baseline = try store.prepareRelationPublicationProof(a, ready);
        var pool_time: u64 = 0;
        while ((try store.stepRelationPublicationProof(ready, pool_time)) == null) : (pool_time += 1) {}
        const scan = try store.beginRelationPublicationScan(a, ready);
        defer scan.deinit();
        try std.testing.expect((try scan.step(null)) == null);
        const invalidated = try store.beginRelationPublicationScan(a, ready);
        defer invalidated.deinit();
        try std.testing.expect((try invalidated.step(null)) == null);
        // New commits must not splice a later source page into this scan.
        // Its final scalar proof remains fenced by the original epoch/index.
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        if (epoch_change) {
            try r.advanceSource(&txn, group);
        } else {
            var buf: [128]u8 = undefined;
            var advanced: [8]u8 = undefined;
            std.mem.writeInt(u64, &advanced, baseline.applied_index + 1, .little);
            try txn.put(try RaftApplyStore.keyForGroup(&buf, group), &advanced);
        }
        try txn.commit();
        pool_time += 1;
        if (epoch_change) {
            try std.testing.expectError(error.CatalogGenerationChanged, store.stepRelationPublicationProof(ready, pool_time));
            for (store.relation_publication_pool.slots) |slot| if (slot) |value| {
                try std.testing.expect(value.group != group);
            };
        } else {
            // Even an index-only commit invalidates completed evidence. A
            // fresh proof needs independent bounded source/candidate passes.
            try std.testing.expect((try store.stepRelationPublicationProof(ready, pool_time)) == null);
            while (true) {
                pool_time += 1;
                if (try store.stepRelationPublicationProof(ready, pool_time)) |fresh| {
                    try std.testing.expectEqual(baseline.applied_index + 1, fresh.applied_index);
                    try std.testing.expect(std.meta.eql(baseline.state, fresh.state));
                    break;
                }
            }
        }
        try std.testing.expectError(error.CatalogGenerationChanged, invalidated.renew());
        try std.testing.expect(!invalidated.open);
        try std.testing.expectError(error.CatalogPublicationScanClosed, invalidated.step(null));
        while (true) if (try scan.step(null)) |finished| {
            try std.testing.expect(std.meta.eql(baseline, finished));
            var current = try store.store.beginReadTxn();
            defer current.abort();
            try std.testing.expect(!try finished.matchesTxn(&current));
            break;
        };
    }
}

test "system catalog restore namespace projections bind names and skip artifact payloads" {
    const a = std.testing.allocator;
    const group = group_ids.main_metadata_group_id;
    const id: [16]u8 = @splat(9);
    var targets = [_]RaftApplyStore.RelationRestoreProjection.Target{.{
        .table = .{ .table_id = 8, .name = "physical_new", .schema_json = "{\"version\":2}" },
        .catalog_binding = .{ .kind = .table, .parent_id = 5, .name = "orders" },
        .replace = .{ .table = .{ .table_id = 7, .name = "physical_old", .schema_json = "{\"version\":1}" } },
    }};
    const projection: RaftApplyStore.RelationRestoreProjection = .{ .plan = .{ .id = id, .targets = &targets } };
    const expected = try RaftApplyStore.relationRestoreSourceDigest(projection.plan);
    const json = try std.json.Stringify.valueAlloc(a, projection, .{});
    defer a.free(json);
    const plan_json = try std.json.Stringify.valueAlloc(a, projection.plan, .{});
    defer a.free(plan_json);
    const noise = try a.alloc(u8, 512 * 1024);
    defer a.free(noise);
    @memset(noise, 'x');
    const oversized_dom = try std.mem.concat(a, u8, &.{ "{\"ignored_artifacts\":\"", noise, "\",\"revision\":999,\"state\":\"published\",\"plan\":", plan_json, "}" });
    defer a.free(oversized_dom);
    var scratch: [32 * 1024]u8 = undefined;
    var bounded = std.heap.FixedBufferAllocator.init(&scratch);
    try std.testing.expectEqualSlices(u8, &expected, &try RaftApplyStore.relationRestoreSourceValueDigest(bounded.allocator(), oversized_dom, id));
    var buf: [256]u8 = undefined;
    try std.testing.expectEqualSlices(u8, &expected, &try RaftApplyStore.relationSourceValueDigest(a, group, try restore_staging.jobKey(&buf, group, id), json));
    try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.relationRestoreSourceValueDigest(a, json, @splat(8)));
    const Probe = struct {
        fn prepare(alloc: std.mem.Allocator, input: []const u8, plan_id: [16]u8) !void {
            _ = try RaftApplyStore.relationRestoreSourceValueDigest(alloc, input, plan_id);
        }
    };
    try std.testing.checkAllAllocationFailures(a, Probe.prepare, .{ json, id });
    targets[0].table.schema_json = "{\"version\":3}";
    try std.testing.expect(!std.mem.eql(u8, &expected, &try RaftApplyStore.relationRestoreSourceDigest(projection.plan)));
    targets[0].table.schema_json = "{\"version\":2}";
    targets[0].catalog_binding.?.parent_id = 6;
    try std.testing.expect(!std.mem.eql(u8, &expected, &try RaftApplyStore.relationRestoreSourceDigest(projection.plan)));
    targets[0].catalog_binding.?.parent_id = 5;
    targets[0].replace.?.table.schema_json = "{\"version\":0}";
    try std.testing.expect(!std.mem.eql(u8, &expected, &try RaftApplyStore.relationRestoreSourceDigest(projection.plan)));
    try std.testing.expect(try RaftApplyStore.relationSourceKey(group, try restore_staging.activeKey(&buf, group, id)));
    try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.relationSourceValueDigest(a, group, try restore_staging.activeKey(&buf, group, id), &@as([16]u8, @splat(8))));
    try std.testing.expect(!try RaftApplyStore.relationSourceKey(group, try restore_staging.progressKey(&buf, group, id)));
    try std.testing.expect(!try RaftApplyStore.relationSourceKey(group, try restore_staging.receiptKey(&buf, group, id, .validating, 8)));
    try std.testing.expect(!try RaftApplyStore.relationSourceKey(group, try restore_staging.identityKey(&buf, group, .group, 8)));
    try std.testing.expect(try RaftApplyStore.relationSourceKey(group, try restore_staging.identityKey(&buf, group, .old_table, 7)));
    var prefix_buf: [160]u8 = undefined;
    const prefix = try restore_staging.prefix(&prefix_buf, group);
    try std.testing.expectError(error.InvalidCatalogRecord, RaftApplyStore.relationRestoreSourceKey(try std.fmt.bufPrint(&buf, "{s}table:07", .{prefix}), group));
}

fn applyRestoreTransitionForTest(store: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, command: TransitionCommand) !void {
    // Direct transaction fixtures still require the production command's
    // buffered outcome boundary so journal rollback restores both effects.
    var outcome: CommittedApplyOutcome = .{ .alloc = std.testing.allocator, .collect_transition_deltas = false };
    defer outcome.deinit();
    const previous = store.active_outcome;
    if (previous == null) store.active_outcome = &outcome;
    defer store.active_outcome = previous;
    try store.applyTransitionCommandTxn(txn, group_id, command);
}

fn applyRestoreStagingForTest(store: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, command: restore_staging.Command) !void {
    const bytes = try std.json.Stringify.valueAlloc(std.testing.allocator, command, .{});
    defer std.testing.allocator.free(bytes);
    const wire = try encodeTransitionCommand(std.testing.allocator, .{ .apply_restore_staging = bytes });
    defer std.testing.allocator.free(wire);
    var decoded = (try decodeTransitionCommand(std.testing.allocator, wire)).?;
    defer decoded.deinit(std.testing.allocator);
    try applyRestoreTransitionForTest(store, txn, group_id, decoded);
}

test "relational integrity restore staging rewrite draft survives restart and freezes only exact pre-pin intent" {
    try testRewriteDraft(false, false);
}

test "relational integrity restore staging rewrite pre-pin cancellation requires only source tombstones and fences delayed freeze" {
    try testRewriteDraft(true, false);
}

test "metadata raft apply store compound rewrite admission atomically reserves exact sources and preserves first job" {
    try testRewriteDraft(false, true);
}

fn testRewriteDraft(cancel: bool, compound: bool) !void {
    return testRewriteDraftWithNames(cancel, compound, false);
}

test "metadata raft apply store generated primary rewrite cannot reserve names or jobs below capability" {
    try testRewriteDraftWithNames(false, true, true);
}

fn testRewriteDraftWithNames(cancel: bool, compound: bool, named: bool) !void {
    return testRewriteDraftWithActivation(cancel, compound, named, false);
}

test "metadata raft apply store activated primary rewrite retains its name guard across freeze and restart" {
    try testRewriteDraftWithActivation(false, true, true, true);
}

test "metadata raft apply store activated primary rewrite cancellation retires the guarded reservation" {
    try testRewriteDraftWithActivation(true, false, true, true);
}

fn testRewriteDraftWithActivation(cancel: bool, compound: bool, named: bool, activated: bool) !void {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/rewrite-draft", .{tmp.sub_path});
    defer alloc.free(root);
    const group = group_ids.main_metadata_group_id;
    const id = try restore_staging.idForAttempt(7, 1);
    const schema_json = if (named)
        \\{"version":1,"storage_mode":"relational","default_type":"row","document_schemas":{"row":{"schema":{"type":"object","properties":{"x":{"type":"integer"}},"additionalProperties":false}}}}
    else
        "{\"version\":1,\"storage_mode\":\"document\"}";
    const target_schema = if (named)
        \\{"version":2,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"rows_pkey","columns":["x"],"primary":true,"timing":"immediate"}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"x":{"type":"integer","nullable":false}},"required":["x"],"additionalProperties":false}}}}
    else
        schema_json;
    const source: @import("antfly_local_sources").storage_db_online_source_contract.Scope = .{
        .fence = .{ .role = .rewrite_source, .transition_id = 7, .attempt = 1, .owner_group_id = 301, .peer_group_id = 401, .namespace = .{ .table_id = 9, .shard_id = 301, .range_id = 301 }, .catalog_digest = @splat(4) },
        .receiver_namespace = .{ .table_id = 10, .shard_id = 401, .range_id = 401 },
        .consumer_epoch = 1,
        .copy_attempt = .{ .donor_term = 1, .sequence = 1 },
    };
    const original: metadata.TableRecord = .{ .table_id = 9, .name = "rows", .schema_json = schema_json };
    const original_range: metadata.RangeRecord = .{ .table_id = 9, .group_id = 301, .range_id = 301, .start_key = "" };
    var targets = [_]restore_staging.Target{.{
        .source_table_id = 9,
        .table = .{ .table_id = 10, .name = "rows", .schema_json = target_schema },
        .ranges = &.{.{ .table_id = 10, .group_id = 401, .range_id = 401, .doc_identity_shard_id = 401, .doc_identity_range_id = 401, .start_key = "" }},
        .replace = .{ .table = original, .ranges = &.{original_range}, .fences = &.{source.fence} },
        .rewrite_sources = &.{source},
        .rewrite = .{ .preserve_document = !named, .source_schemas = &.{schema_json}, .target_schema = target_schema, .program_digest = @splat(6) },
        .generation_handoffs = &.{.{ .source_group_id = 301, .target_group_id = 401, .source_namespace = source.fence.namespace, .admissions = &.{}, .admissions_digest = try @import("antfly_local_sources").storage_portable_backup.sourceGenerationAdmissionSummaryDigest(source.fence.namespace, &.{}), .retired_digest = @splat(8), .retired_count = 0 }},
    }};
    var draft: restore_staging.Plan = .{ .id = id, .cohort_digest = @splat(7), .targets = &targets, .preparing_sources = true };
    try draft.validate(alloc);
    const handoffs = targets[0].generation_handoffs;
    targets[0].generation_handoffs = &.{};
    try std.testing.expectError(error.RestoreSourceProofMissing, draft.validate(alloc));
    targets[0].generation_handoffs = handoffs;
    var draft_digest = try draft.digest(alloc);
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .upsert_table = original });
        try store.applyStandaloneCommand(group, .{ .upsert_range = original_range });
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
        try adoptRelationWriterForTest(&store, alloc, group);
        {
            var tracked = try store.store.beginWriteTxn();
            errdefer tracked.abort();
            try relation_reconciliation.advanceSource(&tracked, group);
            try tracked.commit();
        }
        const user_key = restore_job_logical_prefix ++ "0000000000000007";
        const user_value = "{\"job_id\":7,\"attempt_id\":1,\"staging_attempt_id\":1,\"source_kind\":\"schema_rewrite\",\"phase\":\"queued\"}";
        if (named) {
            if (activated) {
                const proof = try std.json.Stringify.valueAlloc(alloc, topology_protocol.Activation{ .version = topology_protocol.constraint_occupancy_version, .incarnation = "01010101010101010101010101010101".*, .member_count = 3, .membership_fingerprint = @splat(7) }, .{});
                defer alloc.free(proof);
                try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = proof });
                _ = try publishLiveRelationRootWithCoverageForTest(&store, alloc, group, .constraint_names);
            }
            const work = try store.relationReconciliationWork(group);
            var schema_digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(schema_json, &schema_digest, .{});
            draft.constraint_name_guard = .{
                .target = .{ .name = "rows" },
                .logical_table = "rows",
                .owner = .{ .table_id = 9, .schema_version = 1, .schema_digest = schema_digest, .kind = .table },
                .incarnation = work.epoch.?.incarnation,
                .constraint_name_admission = .{ .namespace_id = system_catalog.default_namespace_id, .names = &.{.{ .name = "rows_pkey", .kind = .primary }} },
            };
            try draft.validate(alloc);
            draft_digest = try draft.digest(alloc);
            if (activated) {
                try store.checkConstraintNamesWithContext(alloc, group, .{ .guard = draft.constraint_name_guard.?, .schema_json = target_schema }, .{});
            } else {
                try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.checkConstraintNamesWithContext(alloc, group, .{ .guard = draft.constraint_name_guard.?, .schema_json = target_schema }, .{}));
                const plan_json = try std.json.Stringify.valueAlloc(alloc, draft, .{});
                defer alloc.free(plan_json);
                const reserve_json = try std.json.Stringify.valueAlloc(alloc, restore_staging.Command{ .id = id, .action = .reserve, .plan = draft }, .{});
                defer alloc.free(reserve_json);
                try store.applyStandaloneCommand(group, .{ .apply_restore_staging = reserve_json });
                try store.applyStandaloneCommand(group, .{ .create_restore_job_with_staging = .{ .key = user_key, .value = user_value, .plan_json = plan_json } });
                try std.testing.expect(std.meta.eql(work, try store.relationReconciliationWork(group)));
                {
                    var read = try store.store.beginReadTxn();
                    defer read.abort();
                    var key_buf: [256]u8 = undefined;
                    try std.testing.expectError(error.NotFound, read.get(try restore_staging.jobKey(&key_buf, group, id)));
                    try std.testing.expectError(error.NotFound, read.get(try restoreJobKeyForGroup(&key_buf, group, user_key)));
                    try std.testing.expectError(error.NotFound, read.get(try tableKeyForGroup(&key_buf, group, 10)));
                    const unchanged = try decodeTableRecord(alloc, try read.get(try tableKeyForGroup(&key_buf, group, 9)));
                    defer metadata_table_manager.freeTable(alloc, unchanged);
                    try std.testing.expectEqualDeep(original, unchanged);
                    var cursor = try read.openCursor();
                    defer cursor.close();
                    const prefix = try restore_staging.activePrefix(&key_buf, group);
                    if (try cursor.seekAtOrAfter(prefix)) |row| try std.testing.expect(!std.mem.startsWith(u8, row.key, prefix));
                }
                // The exact same topology and schema can be admitted without the
                // new predicate. This proves the negative result above was not
                // caused by an invalid rewrite fixture or missing source facts.
                draft.constraint_name_guard = null;
                const legacy_json = try std.json.Stringify.valueAlloc(alloc, draft, .{});
                defer alloc.free(legacy_json);
                try store.applyStandaloneCommand(group, .{ .create_restore_job_with_staging = .{ .key = user_key, .value = user_value, .plan_json = legacy_json } });
                var accepted = try store.store.beginReadTxn();
                defer accepted.abort();
                var key_buf: [256]u8 = undefined;
                _ = try accepted.get(try restore_staging.jobKey(&key_buf, group, id));
                try std.testing.expectEqualStrings(user_value, try accepted.get(try restoreJobKeyForGroup(&key_buf, group, user_key)));
                return;
            }
        }
        if (compound) {
            const plan_json = try std.json.Stringify.valueAlloc(alloc, draft, .{});
            defer alloc.free(plan_json);
            const command: TransitionCommand = .{ .create_restore_job_with_staging = .{ .key = user_key, .value = user_value, .plan_json = plan_json } };
            const wire = try encodeTransitionCommand(alloc, command);
            defer alloc.free(wire);
            try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTransitionCommand(alloc, wire[0 .. wire.len - 1]));
            const trailing = try std.mem.concat(alloc, u8, &.{ wire, "x" });
            defer alloc.free(trailing);
            try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTransitionCommand(alloc, trailing));
            var decoded = (try decodeTransitionCommand(alloc, wire)).?;
            defer decoded.deinit(alloc);
            try std.testing.expectEqualDeep(command, decoded);
            {
                var cancelled_txn = try store.store.beginWriteTxn();
                defer cancelled_txn.abort();
                var key_buf: [256]u8 = undefined;
                const key = try restoreJobKeyForGroup(&key_buf, group, user_key);
                try cancelled_txn.put(key, "already canceled");
                try applyRestoreTransitionForTest(&store, &cancelled_txn, group, decoded);
                var plan_key_buf: [256]u8 = undefined;
                try std.testing.expectError(error.NotFound, cancelled_txn.get(try restore_staging.jobKey(&plan_key_buf, group, id)));
                try std.testing.expectEqualStrings("already canceled", try cancelled_txn.get(key));
            }
            {
                var failed_txn = try store.store.beginWriteTxn();
                defer failed_txn.abort();
                targets[0].replace.?.table.description = "stale expected definition";
                const stale_json = try std.json.Stringify.valueAlloc(alloc, draft, .{});
                defer alloc.free(stale_json);
                try applyRestoreTransitionForTest(&store, &failed_txn, group, .{ .create_restore_job_with_staging = .{ .key = user_key, .value = user_value, .plan_json = stale_json } });
                targets[0].replace.?.table.description = "";
                var key_buf: [256]u8 = undefined;
                try std.testing.expectError(error.NotFound, failed_txn.get(try restoreJobKeyForGroup(&key_buf, group, user_key)));
                try std.testing.expectError(error.NotFound, failed_txn.get(try restore_staging.jobKey(&key_buf, group, id)));
                // A rejected/cancelled reservation cannot leave a user-visible
                // accepted job with no recoverable source plan.
                try applyRestoreStagingForTest(&store, &failed_txn, group, .{ .id = id, .action = .cancel_reservation });
                try applyRestoreTransitionForTest(&store, &failed_txn, group, decoded);
                try std.testing.expectError(error.NotFound, failed_txn.get(try restoreJobKeyForGroup(&key_buf, group, user_key)));
            }
            // Aborting a fully successful mutation rolls both sides back.
            {
                var rolled_back = try store.store.beginWriteTxn();
                defer rolled_back.abort();
                try applyRestoreTransitionForTest(&store, &rolled_back, group, decoded);
                var key_buf: [256]u8 = undefined;
                _ = try rolled_back.get(try restoreJobKeyForGroup(&key_buf, group, user_key));
                _ = try rolled_back.get(try restore_staging.jobKey(&key_buf, group, id));
            }
        }
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        if (compound) {
            const plan_json = try std.json.Stringify.valueAlloc(alloc, draft, .{});
            defer alloc.free(plan_json);
            const command: TransitionCommand = .{ .create_restore_job_with_staging = .{ .key = user_key, .value = user_value, .plan_json = plan_json } };
            try applyRestoreTransitionForTest(&store, &txn, group, command);
            var replay = command;
            replay.create_restore_job_with_staging.value = "rejected late replacement";
            try applyRestoreTransitionForTest(&store, &txn, group, replay);
            var key_buf: [256]u8 = undefined;
            try std.testing.expectEqualStrings(user_value, try txn.get(try restoreJobKeyForGroup(&key_buf, group, user_key)));
        } else try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .reserve, .plan = draft });
        try std.testing.expect(try restoreStagingLocksTableTxn(&txn, group, original.table_id));
        try std.testing.expectEqual(@as(u64, 2), try relation_reconciliation.readSourceRevision(&txn, group));
        try txn.commit();
        var projection = try store.captureProvisioningCatalog(alloc, group);
        defer projection.deinit(alloc);
        try std.testing.expectEqual(@as(usize, 1), projection.tables.len);
        try std.testing.expectEqual(@as(usize, 0), projection.jobs_json.len);
    }
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    if (compound) {
        const row = (try store.getRestoreJobValue(alloc, group, restore_job_logical_prefix ++ "0000000000000007")).?;
        defer alloc.free(row);
        try std.testing.expect(std.mem.indexOf(u8, row, "schema_rewrite") != null);
    }
    try std.testing.expectEqual(.preparing_sources, (try store.loadRestoreStagingProgress(alloc, group, id)).?.state);
    try verifyRelationRecoveryForTest(&store, alloc, group);
    const prior_work = try store.relationReconciliationWork(group);
    const next_job = try relation_reconciliation.nextJobId(if (prior_work.current) |*prior| prior else null);
    const namespace_ready = try reconcileRestoreNamesForTest(&store, alloc, try relation_reconciliation.State.initWithCoverage(group, next_job, .{ .incarnation = @splat(1), .revision = 2 }, if (activated) .constraint_names else .relations));
    const namespace_source_cut = blk: {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        const Probe = struct {
            fn scan(a: std.mem.Allocator, owner: *RaftApplyStore, state: relation_reconciliation.State) !void {
                const verification = try owner.beginRelationPublicationScan(a, state);
                defer verification.deinit();
                try verification.renew();
                while (true) if (try verification.step(null)) |proof| {
                    var txn = try owner.store.beginReadTxn();
                    defer txn.abort();
                    try std.testing.expect(try proof.matchesTxn(&txn));
                    break;
                } else try verification.renew();
            }
            fn publication(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, state: relation_reconciliation.State) !void {
                const proof = try RaftApplyStore.prepareRelationPublicationProofTxn(a, txn, state);
                try std.testing.expect(try proof.matchesTxn(txn));
            }
            fn prepare(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, metadata_group: u64) !void {
                var prefix_buf: [160]u8 = undefined;
                var names_source: RaftApplyStore.RelationRestoreSource = .{ .a = a, .txn = txn, .group_id = metadata_group, .raw = .{ .cursor = try txn.openCursor(), .prefix = try restore_staging.activePrefix(&prefix_buf, metadata_group) } };
                defer names_source.deinit();
                const row = (try names_source.nextAfter("")).?;
                const entry = try row.claims[0].entry();
                try std.testing.expectEqual(@as(u64, 9), entry.active.?.table_id);
                try std.testing.expectEqual(@as(u64, 10), entry.pending.?.table_id);
                try std.testing.expect(row.claims[0].reservation);
            }
        };
        try Probe.prepare(alloc, &read, group);
        // Arena resize success depends on backing addresses between runs.
        // Force its allocation fallback so every injected point is repeatable.
        var no_resize = std.testing.FailingAllocator.init(alloc, .{ .resize_fail_index = 0 });
        try std.testing.checkAllAllocationFailures(no_resize.allocator(), Probe.prepare, .{ &read, group });
        try Probe.publication(alloc, &read, namespace_ready);
        if (cancel and !compound) {
            try std.testing.checkAllAllocationFailures(no_resize.allocator(), Probe.publication, .{ &read, namespace_ready });
            try std.testing.checkAllAllocationFailures(no_resize.allocator(), Probe.scan, .{ &store, namespace_ready });
        }
        break :blk try RaftApplyStore.relationSourceCutTxn(alloc, &read, group, 2);
    };
    const artifacts = [_]restore_staging.SourceArtifact{.{ .target_group_id = 401, .source_namespace = source.fence.namespace, .format = .portable, .snapshot_path = "cut/source.afb2", .artifact_size_bytes = 100, .artifact_sha256 = @splat(7), .rewrite = .{ .program_digest = @splat(6), .retained_pin = source.pin(), .snapshot_certificate = @splat(7), .retained_epoch = 1, .retained_start = 8, .source_applied_index = 20, .source_scope = source } }};
    targets[0].source_artifacts = &artifacts;
    draft.preparing_sources = false;
    draft.cohort_digest = @splat(8);
    try draft.validate(alloc);
    try std.testing.expectError(error.InvalidRestoreStaging, (restore_staging.Command{ .id = id, .action = .reserve, .plan = draft }).validate(alloc));
    if (activated) {
        var read = try store.store.beginReadTxn();
        defer read.abort();
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
        try std.testing.expect(try live.nameOccupied(system_catalog.default_namespace_id, "rows_pkey", true));
    }
    if (cancel) {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .begin_cancel, .expected_revision = 1 });
        try std.testing.expectEqual(@as(u64, 2), try relation_reconciliation.readSourceRevision(&txn, group));
        try std.testing.expect(namespace_source_cut.eql(try RaftApplyStore.relationSourceCutTxn(alloc, &txn, group, 2)));
        // No target generation was ever provisioned. Its invented receipt
        // cannot satisfy cancellation of an actual admitted source pin.
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .canceled, .expected_revision = 2, .receipt = .{ .group_id = 401, .range_id = 401, .plan_digest = draft_digest, .completion_digest = @splat(1) } });
        var buf: [256]u8 = undefined;
        const pending = try std.json.parseFromSlice(restore_staging.Progress, alloc, try txn.get(try restore_staging.progressKey(&buf, group, id)), .{});
        defer pending.deinit();
        try std.testing.expectEqual(@as(u32, 0), pending.value.completed_owners);
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .canceled, .expected_revision = 2, .receipt = .{ .group_id = 301, .range_id = 301, .plan_digest = draft_digest, .completion_digest = @splat(2) } });
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .finish_cancel, .expected_revision = 2 });
        try std.testing.expectEqual(@as(u64, 3), try relation_reconciliation.readSourceRevision(&txn, group));
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .freeze_rewrite, .expected_revision = 1, .plan = draft });
        try std.testing.expect(!try restoreStagingLocksTableTxn(&txn, group, original.table_id));
        _ = try txn.get(try tableKeyForGroup(&buf, group, original.table_id));
        try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group, targets[0].table.table_id)));
        try txn.commit();
        try std.testing.expectEqual(.canceled, (try store.loadRestoreStagingProgress(alloc, group, id)).?.state);
        try verifyRelationRecoveryForTest(&store, alloc, group);
        if (activated) {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&read, group)).?;
            try std.testing.expect(!try live.nameOccupied(system_catalog.default_namespace_id, "rows_pkey", true));
        }
        return;
    }
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        // A fabricated frozen plan is not enough: every published source cut
        // has its own durable bounded receipt before metadata freezes it.
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .freeze_rewrite, .expected_revision = 1, .plan = draft });
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .rewrite_source_ready, .expected_revision = 1, .source_artifact = artifacts[0] });
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .rewrite_source_ready, .expected_revision = 1, .source_artifact = artifacts[0] });
        try std.testing.expectEqual(@as(u64, 2), try relation_reconciliation.readSourceRevision(&txn, group));
        try txn.commit();
    }
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    {
        var pending = (try store.loadRestoreStaging(alloc, group, id)).?;
        defer pending.deinit();
        try std.testing.expectEqual(.preparing_sources, pending.value.state);
        try std.testing.expectEqual(@as(u64, 2), pending.value.revision);
        try std.testing.expectEqual(@as(u32, 1), pending.value.completed_owners);
        try std.testing.expectEqualDeep(artifacts[0], pending.value.plan.targets[0].source_artifacts[0]);
    }
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        // A valid plan with altered immutable target configuration is not a
        // continuation of the reserved rewrite, even under the same ID.
        targets[0].table.description = "changed after pin";
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .freeze_rewrite, .expected_revision = 2, .plan = draft });
        targets[0].table.description = "";
        if (activated) {
            // The admitted predicate is part of the immutable pre-pin intent,
            // not an optional field that source preparation may replace.
            draft.constraint_name_guard.?.incarnation[0] ^= 1;
            try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .freeze_rewrite, .expected_revision = 2, .plan = draft });
            draft.constraint_name_guard.?.incarnation[0] ^= 1;
        }
        var buf: [256]u8 = undefined;
        const progress = try std.json.parseFromSlice(restore_staging.Progress, alloc, try txn.get(try restore_staging.progressKey(&buf, group, id)), .{});
        defer progress.deinit();
        try std.testing.expectEqual(.preparing_sources, progress.value.state);
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .freeze_rewrite, .expected_revision = 2, .plan = draft });
        try applyRestoreStagingForTest(&store, &txn, group, .{ .id = id, .action = .freeze_rewrite, .expected_revision = 2, .plan = draft });
        try std.testing.expectEqual(@as(u64, 2), try relation_reconciliation.readSourceRevision(&txn, group));
        try std.testing.expect(namespace_source_cut.eql(try RaftApplyStore.relationSourceCutTxn(alloc, &txn, group, 2)));
        try txn.commit();
    }
    const progress = (try store.loadRestoreStagingProgress(alloc, group, id)).?;
    try std.testing.expectEqual(.importing, progress.state);
    try std.testing.expectEqual(@as(u64, 3), progress.revision);
    try verifyRelationRecoveryForTest(&store, alloc, group);
    var recovered = (try store.loadRestoreStaging(alloc, group, id)).?;
    defer recovered.deinit();
    try std.testing.expectEqualDeep(artifacts[0], recovered.value.plan.targets[0].source_artifacts[0]);
    try std.testing.expectEqualSlices(u8, &try draft.digest(alloc), &recovered.value.plan_digest);
}

test "relational integrity restore staging authority survives retirement and snapshot with point reads" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/authority", .{tmp.sub_path});
    defer alloc.free(root);
    const restored_root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/authority-restored", .{tmp.sub_path});
    defer alloc.free(restored_root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const target: restore_staging.Target = .{ .source_table_id = 1, .table = .{ .table_id = 11, .name = "private", .schema_json = "{}" }, .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }} };
    const plan: restore_staging.Plan = .{ .id = @splat(8), .cohort_digest = @splat(9), .targets = &.{target} };
    const reserve = try std.json.Stringify.valueAlloc(alloc, restore_staging.Command{ .id = plan.id, .action = .reserve, .plan = plan }, .{});
    defer alloc.free(reserve);
    try store.applyStandaloneCommand(group_id, .{ .apply_restore_staging = reserve });
    try store.applyStandaloneCommand(group_id, .{ .register_node = .{ .node_id = 7, .role = "data", .lifecycle = metadata_table_manager.node_lifecycle_active } });
    // Prime cached snapshot projections before placement adds its authority
    // row: the placement command must dirty the staging projection as well.
    const before_placement_snapshot = try store.snapshotBuilder().buildSnapshot(alloc, group_id);
    defer alloc.free(before_placement_snapshot);
    const placement: TransitionCommand = .{ .upsert_replica_intent = .{
        .expected_metadata_version = null,
        .expected_version_fence = 0,
        .expected_target_drain_requested = false,
        .replacement = .{ .record = .{ .group_id = 701, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
    } };
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, null));
    try store.applyStandaloneCommand(group_id, placement);
    try std.testing.expect(try store.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, null));
    try std.testing.expect(try store.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, 701));
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 8, null));
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, @splat(7), 7, null));
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id + 1, plan.id, 7, null));
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, 702));
    try store.applyStandaloneCommand(group_id, .{ .remove_replica_intent = .{ .group_id = 701, .local_node_id = 7, .expected_metadata_version = 1 } });
    const placements = try store.listPlacementIntents(alloc, group_id);
    defer store.freePlacementIntents(alloc, placements);
    try std.testing.expectEqual(@as(usize, 0), placements.len);
    try std.testing.expect(try store.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, 701));
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 1 });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .canceled, .expected_revision = 2, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = try plan.digest(alloc), .completion_digest = @splat(3) } });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .finish_cancel, .expected_revision = 2 });
        try txn.commit();
    }
    try std.testing.expectEqual(restore_staging.State.canceled, (try store.loadRestoreStagingProgress(alloc, group_id, plan.id)).?.state);
    const snapshot = try store.snapshotBuilder().buildSnapshot(alloc, group_id);
    defer alloc.free(snapshot);
    var restored = try RaftApplyStore.init(alloc, .{ .root_dir = restored_root });
    defer restored.deinit();
    try std.testing.expect(try restored.snapshotBuilder().installSnapshot(alloc, group_id, 1, snapshot));
    try std.testing.expect(try restored.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, 701));
    // Corrupting the large immutable job cannot affect this compact authority
    // check: it performs only fixed-key reads and never parses the plan.
    var key_buf: [256]u8 = undefined;
    try restored.store.put(try restore_staging.jobKey(&key_buf, group_id, plan.id), "not a JSON plan");
    var no_alloc = std.testing.FailingAllocator.init(alloc, .{ .fail_index = 0 });
    for (0..128) |_| try std.testing.expect(try restored.restoreStagingAuthorityAllowed(no_alloc.allocator(), group_id, plan.id, 7, 701));
    try restored.store.put(try restore_staging.identityKey(&key_buf, group_id, .group, 701), &@as([16]u8, @splat(5)));
    try std.testing.expect(!try restored.restoreStagingAuthorityAllowed(alloc, group_id, plan.id, 7, 701));
}

test "relational integrity restore staging cancellation tombstone defeats delayed reserve" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/cancel-before-reserve", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const plan: restore_staging.Plan = .{
        .id = @splat(17),
        .cohort_digest = @splat(9),
        .targets = &.{.{ .source_table_id = 1, .table = .{ .table_id = 11, .name = "never_admitted", .schema_json = "{}" }, .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }} }},
    };
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .cancel_reservation });
        try txn.commit();
    }
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .cancel_reservation });
        try txn.commit();
    }
    try std.testing.expect((try store.loadRestoreStaging(alloc, group_id, plan.id)) == null);
    const progress = (try store.loadRestoreStagingProgress(alloc, group_id, plan.id)).?;
    try std.testing.expectEqual(restore_staging.State.canceled, progress.state);
    var txn = try store.store.beginReadTxn();
    defer txn.abort();
    var key_buf: [256]u8 = undefined;
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.nameKey(&key_buf, group_id, "never_admitted")));
}

test "relational integrity restore staging publishes all targets only after exact owner validation" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/staging", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    try store.applyStandaloneCommand(group_id, .{ .initialize_metadata_incarnation = "01010101010101010101010101010101".* });
    _ = try adoptLiveRelationWriterForTest(&store, alloc, group_id);
    var targets = [_]restore_staging.Target{
        .{ .source_table_id = 1, .table = .{ .table_id = 11, .name = "new_parent", .schema_json = "{}" }, .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }} },
        .{ .source_table_id = 2, .table = .{ .table_id = 12, .name = "new_child", .schema_json = "{}" }, .ranges = &.{.{ .table_id = 12, .group_id = 702, .range_id = 702, .doc_identity_shard_id = 702, .doc_identity_range_id = 702, .start_key = "" }} },
    };
    for (&targets, [_][]const u8{ "parents", "children" }) |*target, name| target.catalog_binding = .{
        .kind = .table,
        .id = target.table.table_id,
        .parent_id = system_catalog.default_namespace_id,
        .name = name,
        .storage_name = target.table.name,
    };
    targets[0].table.schema_reader_requirements = .{ .semantic_version = 11, .encoding_version = 31 };
    const plan: restore_staging.Plan = .{ .id = @splat(7), .cohort_digest = @splat(9), .targets = &targets };
    const digest = try plan.digest(alloc);
    var txn = try store.store.beginWriteTxn();
    var txn_open = true;
    defer if (txn_open) txn.abort();
    var decoder = topology_protocol.Activation{ .version = topology_protocol.schema_reader_floor_version, .incarnation = "01010101010101010101010101010101".*, .member_count = 3, .membership_fingerprint = @splat(7) };
    const old_decoder = try std.json.Stringify.valueAlloc(alloc, decoder, .{});
    defer alloc.free(old_decoder);
    var decoder_buf: [160]u8 = undefined;
    const decoder_key = try RaftApplyStore.topologyActivationKeyForGroup(&decoder_buf, group_id);
    try txn.put(decoder_key, old_decoder);
    // Prove that the real command decoder retains the reader marker before
    // testing admission: malformed commands intentionally apply as no-ops.
    const reserve_command: restore_staging.Command = .{ .id = plan.id, .action = .reserve, .plan = plan };
    const reserve_bytes = try std.json.Stringify.valueAlloc(alloc, reserve_command, .{});
    defer alloc.free(reserve_bytes);
    var reserve_parsed = try restore_staging.parseCommand(alloc, reserve_bytes);
    defer reserve_parsed.deinit();
    try std.testing.expect(reserve_parsed.value.plan.?.readerPublicationRequired());
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan }));
    var rejected_job_buf: [256]u8 = undefined;
    try std.testing.expect((try RaftApplyStore.stagingGet(&txn, try restore_staging.jobKey(&rejected_job_buf, group_id, plan.id))) == null);
    var rejected_name_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    for (targets) |target| try std.testing.expect((try RaftApplyStore.stagingGet(&txn, try restore_staging.nameKey(&rejected_name_buf, group_id, target.table.name))) == null);
    decoder.version = topology_protocol.schema_reader_publication_version;
    const current_decoder = try std.json.Stringify.valueAlloc(alloc, decoder, .{});
    defer alloc.free(current_decoder);
    try txn.put(decoder_key, current_decoder);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    const reservation = try txn.get(try restore_staging.nameKey(&key_buf, group_id, targets[0].table.name));
    try std.testing.expectEqualSlices(u8, &plan.id, reservation);
    var registry = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(alloc, &txn, group_id);
    try std.testing.expect(registry.live != null);
    for (targets) |target| {
        const key: relation_names.Key = .{ .namespace_id = target.catalog_binding.?.parent_id, .name = target.catalog_binding.?.name };
        const entry = (try registry.getEntry(key)).?;
        try std.testing.expect(entry.active == null);
        try std.testing.expectEqual(target.table.table_id, entry.pending.?.table_id);
        try std.testing.expectEqualSlices(u8, &plan.id, &entry.pending.?.publication_id);
        try std.testing.expect((try registry.getClaim(key)) == null);
    }
    try verifyRelationCheckpointTxn(alloc, &txn);
    for (targets) |target| try std.testing.expect(!try store.relationalParentsExistTxn(&txn, group_id, target.table));
    const hidden = try store.listTablesTxn(alloc, &txn, group_id);
    defer store.freeTables(alloc, hidden);
    try std.testing.expectEqual(@as(usize, 0), hidden.len);
    try std.testing.expectEqual(@as(u64, 0), (try system_catalog_storage.readMeta(alloc, &txn, group_id)).revision);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 1 });
    for (targets) |target| {
        const command: restore_staging.Command = .{ .id = plan.id, .action = .imported, .expected_revision = 1, .receipt = .{
            .group_id = target.ranges[0].group_id,
            .range_id = target.ranges[0].range_id,
            .plan_digest = digest,
            .completion_digest = @splat(3),
        } };
        try applyRestoreStagingForTest(&store, &txn, group_id, command);
        try applyRestoreStagingForTest(&store, &txn, group_id, command);
    }
    // Import completion is not constraint coverage. A wrong-owner proof and
    // early publication remain hidden, even with the current revision.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .validated, .expected_revision = 2, .receipt = .{
        .group_id = 701,
        .range_id = 999,
        .plan_digest = digest,
        .completion_digest = @splat(4),
    } });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 2 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
    for (targets) |target| try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .validated, .expected_revision = 2, .receipt = .{
        .group_id = target.ranges[0].group_id,
        .range_id = target.ranges[0].range_id,
        .plan_digest = digest,
        .completion_digest = @splat(4),
    } });
    // Losing either private identity reservation cannot partially publish
    // an otherwise fully validated target set, even with its name lock intact.
    for ([_]struct { kind: enum { table, group }, id: u64 }{ .{ .kind = .table, .id = 12 }, .{ .kind = .group, .id = 702 } }) |identity| {
        const reserved_key = if (identity.kind == .table)
            try restore_staging.identityKey(&key_buf, group_id, .table, identity.id)
        else
            try restore_staging.identityKey(&key_buf, group_id, .group, identity.id);
        try txn.put(reserved_key, &@as([16]u8, @splat(8)));
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 2 });
        const still_hidden = try store.listTablesTxn(alloc, &txn, group_id);
        defer store.freeTables(alloc, still_hidden);
        try std.testing.expectEqual(@as(usize, 0), still_hidden.len);
        try txn.put(reserved_key, &plan.id);
    }
    // A late common-writer veto on the second target must precede the logical
    // catalog delta, the first physical target and every restored range.
    var lock_buf: [160]u8 = undefined;
    const lock_key = try fk_generation_publication.tableLockKey(&lock_buf, group_id, targets[1].table.table_id);
    const lock_value = RaftApplyStore.fkTableLockValue(.generation, @splat(5));
    try txn.put(lock_key, &lock_value);
    const source_before = try relation_reconciliation.readSourceRevision(&txn, group_id);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 2 });
    try std.testing.expectEqual(@as(u64, 0), (try system_catalog_storage.readMeta(alloc, &txn, group_id)).revision);
    try std.testing.expectEqual(source_before, try relation_reconciliation.readSourceRevision(&txn, group_id));
    for (targets) |target| {
        try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, target.table.table_id)));
        try std.testing.expectError(error.NotFound, txn.get(try rangeKeyForGroup(&key_buf, group_id, target.ranges[0].group_id)));
    }
    try txn.delete(lock_key);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 2 });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 2 });
    const published = try store.listTablesTxn(alloc, &txn, group_id);
    defer store.freeTables(alloc, published);
    try std.testing.expectEqual(@as(usize, 2), published.len);
    try std.testing.expectEqual(@as(u64, 1), (try system_catalog_storage.readMeta(alloc, &txn, group_id)).revision);
    for (targets) |target| {
        var binding = (try system_catalog_storage.find(alloc, &txn, group_id, .table, system_catalog.default_namespace_id, target.catalog_binding.?.name)).?;
        defer binding.deinit();
        try std.testing.expectEqual(target.table.table_id, binding.value.id);
        try std.testing.expectEqualStrings(target.table.name, binding.value.storage_name);
        const entry = (try registry.getEntry(.{ .namespace_id = binding.value.parent_id, .name = binding.value.name })).?;
        try std.testing.expectEqual(target.table.table_id, entry.active.?.table_id);
        try std.testing.expect(entry.pending == null);
        _ = try txn.get(try rangeKeyForGroup(&key_buf, group_id, target.ranges[0].group_id));
        try std.testing.expectError(error.NotFound, txn.get(try restore_staging.nameKey(&key_buf, group_id, target.table.name)));
    }
    // A delayed cancel cannot unpublish a completed target set.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 3 });
    try txn.commit();
    txn_open = false;
    try verifyRelationRecoveryForTest(&store, alloc, group_id);
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    var loaded = (try store.loadRestoreStaging(alloc, group_id, plan.id)).?;
    defer loaded.deinit();
    try std.testing.expectEqual(restore_staging.State.published, loaded.value.state);
    try verifyRelationRecoveryForTest(&store, alloc, group_id);
}

test "relational integrity restore staging portable FK cannot publish before exact mapped parent admission receipt" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/portable-fk-admission", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const id = try restore_staging.idForAttempt(7, 1);
    const parent_schema =
        \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const child_schema =
        \\{"version":1,"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"fk","child_columns":["id"],"parent_table":"parents","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    const parent_artifact: restore_staging.SourceArtifact = .{ .target_group_id = 701, .source_namespace = .{ .table_id = 1, .shard_id = 101, .range_id = 101 }, .format = .portable, .snapshot_path = "parent.afb", .artifact_size_bytes = 1, .artifact_sha256 = @splat(2) };
    const parent_artifact_second: restore_staging.SourceArtifact = .{ .target_group_id = 703, .source_namespace = .{ .table_id = 1, .shard_id = 103, .range_id = 103 }, .format = .portable, .snapshot_path = "parent-second.afb", .artifact_size_bytes = 1, .artifact_sha256 = @splat(8) };
    const child_artifact: restore_staging.SourceArtifact = .{ .target_group_id = 702, .source_namespace = .{ .table_id = 2, .shard_id = 102, .range_id = 102 }, .format = .portable, .snapshot_path = "child.afb", .artifact_size_bytes = 1, .artifact_sha256 = @splat(3) };
    const child: restore_staging.Target = .{ .source_table_id = 2, .source_table_name = "children", .table = .{ .table_id = 12, .name = "children", .schema_json = child_schema }, .ranges = &.{.{ .table_id = 12, .group_id = 702, .range_id = 702, .doc_identity_shard_id = 702, .doc_identity_range_id = 702, .start_key = "" }}, .source_artifacts = &.{child_artifact}, .source_generation_admissions = &.{.{ .target_group_id = 702, .source_namespace = child_artifact.source_namespace, .entries = &.{}, .digest = try @import("antfly_local_sources").storage_portable_backup.sourceGenerationAdmissionSummaryDigest(child_artifact.source_namespace, &.{}) }} };
    var source_child = child;
    source_child.table.table_id = 2;
    const source_generation = try restore_staging.plannedForeignGeneration(alloc, source_child, "fk");
    const summaries = [_]@import("antfly_local_sources").storage_portable_backup.SourceGenerationAdmissionSummaryEntry{.{ .child_table_id = 2, .child_table_name = "children", .constraint_name = "fk", .active_generation = source_generation, .source_scope_digest = @splat(4) }};
    const summaries_second = [_]@import("antfly_local_sources").storage_portable_backup.SourceGenerationAdmissionSummaryEntry{.{ .child_table_id = 2, .child_table_name = "children", .constraint_name = "fk", .active_generation = source_generation, .source_scope_digest = @splat(9) }};
    const parent: restore_staging.Target = .{ .source_table_id = 1, .source_table_name = "parents", .table = .{ .table_id = 11, .name = "parents", .schema_json = parent_schema, .min_ranges = 2 }, .ranges = &.{
        .{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "", .end_key = "m" },
        .{ .table_id = 11, .group_id = 703, .range_id = 703, .doc_identity_shard_id = 703, .doc_identity_range_id = 703, .start_key = "m" },
    }, .source_artifacts = &.{ parent_artifact, parent_artifact_second }, .source_generation_admissions = &.{
        .{ .target_group_id = 701, .source_namespace = parent_artifact.source_namespace, .entries = &summaries, .digest = try @import("antfly_local_sources").storage_portable_backup.sourceGenerationAdmissionSummaryDigest(parent_artifact.source_namespace, &summaries) },
        .{ .target_group_id = 703, .source_namespace = parent_artifact_second.source_namespace, .entries = &summaries_second, .digest = try @import("antfly_local_sources").storage_portable_backup.sourceGenerationAdmissionSummaryDigest(parent_artifact_second.source_namespace, &summaries_second) },
    } };
    var projection_arena = std.heap.ArenaAllocator.init(alloc);
    defer projection_arena.deinit();
    var targets = [_]restore_staging.Target{ parent, child };
    try restore_staging.prepareTargetProjectionsAlloc(projection_arena.allocator(), &targets);
    const plan: restore_staging.Plan = .{ .id = id, .cohort_digest = @splat(9), .targets = &targets };
    try plan.validate(alloc);
    const digest = try plan.digest(alloc);
    var mapped = (try restore_staging.mappedGenerationAdmissionsForGroupAlloc(alloc, plan, digest, 701)).?;
    defer mapped.deinit(alloc);
    var mapped_second = (try restore_staging.mappedGenerationAdmissionsForGroupAlloc(alloc, plan, digest, 703)).?;
    defer mapped_second.deinit(alloc);
    try std.testing.expect(!std.mem.eql(u8, &mapped.command.source_summary_digest, &mapped_second.command.source_summary_digest));
    var txn = try store.store.beginWriteTxn();
    var txn_open = true;
    defer if (txn_open) txn.abort();
    var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .reserve, .plan = plan });
    for (plan.targets) |target| for (target.ranges) |range| {
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .imported, .expected_revision = 1, .receipt = .{ .group_id = range.group_id, .range_id = range.range_id, .plan_digest = digest, .completion_digest = @splat(5) } });
    };
    for (plan.targets) |target| for (target.ranges) |range| {
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .validated, .expected_revision = 2, .receipt = .{ .group_id = range.group_id, .range_id = range.range_id, .plan_digest = digest, .completion_digest = @splat(6) } });
    };
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 2 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_activation, .expected_revision = 2 });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_cancel, .expected_revision = 3 });
    const forged: restore_staging.OwnerReceipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = @splat(7) };
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .target_admissions_activated, .expected_revision = 3, .receipt = forged });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 3 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
    var exact = forged;
    exact.completion_digest = mapped.expected_receipt_digest;
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .target_admissions_activated, .expected_revision = 3, .receipt = exact });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .target_admissions_activated, .expected_revision = 3, .receipt = exact });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 3 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
    try txn.commit();
    txn_open = false;
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    txn = try store.store.beginWriteTxn();
    txn_open = true;
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .target_admissions_activated, .expected_revision = 2, .receipt = exact });
    var exact_second = exact;
    exact_second.group_id = 703;
    exact_second.range_id = 703;
    exact_second.completion_digest = mapped_second.expected_receipt_digest;
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .target_admissions_activated, .expected_revision = 3, .receipt = exact_second });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 3 });
    _ = try txn.get(try tableKeyForGroup(&key_buf, group_id, 11));
    _ = try txn.get(try tableKeyForGroup(&key_buf, group_id, 12));
    txn.abort();
    txn_open = false;
}

test "relational integrity restore staging cancellation survives snapshots without reopening identities" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/cancel", .{tmp.sub_path});
    defer alloc.free(root);
    const restored_root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/cancel-restored", .{tmp.sub_path});
    defer alloc.free(restored_root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const target: restore_staging.Target = .{ .source_table_id = 1, .table = .{ .table_id = 11, .name = "canceled_target", .schema_json = "{}" }, .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }} };
    const plan: restore_staging.Plan = .{ .id = @splat(8), .cohort_digest = @splat(9), .targets = &.{target} };
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 1 });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .finish_cancel, .expected_revision = 2 });
        var buf: [256]u8 = undefined;
        _ = try txn.get(try restore_staging.nameKey(&buf, group_id, target.table.name));
        try txn.commit();
    }
    var provisioning = try store.captureProvisioningCatalog(alloc, group_id);
    defer provisioning.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), provisioning.jobs_json.len);
    var projected_job = try std.json.parseFromSlice(restore_staging.Job, alloc, provisioning.jobs_json[0], .{});
    defer projected_job.deinit();
    try std.testing.expectEqual(restore_staging.State.canceling, projected_job.value.state);
    try std.testing.expectEqual(@as(u64, 2), projected_job.value.revision);
    try std.testing.expectEqual(@as(u32, 0), projected_job.value.completed_owners);
    try std.testing.expectEqualSlices(u8, &(try plan.digest(alloc)), &projected_job.value.plan_digest);
    {
        var key_buf: [256]u8 = undefined;
        const immutable = try store.store.get(alloc, try restore_staging.jobKey(&key_buf, group_id, plan.id));
        defer alloc.free(immutable);
        var original = try std.json.parseFromSlice(restore_staging.Job, alloc, immutable, .{});
        defer original.deinit();
        try std.testing.expectEqual(restore_staging.State.importing, original.value.state);
        try std.testing.expectEqual(@as(u64, 1), original.value.revision);
    }
    const snapshot = try store.snapshotBuilder().buildSnapshot(alloc, group_id);
    defer alloc.free(snapshot);
    var restored = try RaftApplyStore.init(alloc, .{ .root_dir = restored_root });
    defer restored.deinit();
    try std.testing.expect(try restored.snapshotBuilder().installSnapshot(alloc, group_id, 1, snapshot));
    var loaded = (try restored.loadRestoreStaging(alloc, group_id, plan.id)).?;
    defer loaded.deinit();
    try std.testing.expectEqual(restore_staging.State.canceling, loaded.value.state);
    var restored_provisioning = try restored.captureProvisioningCatalog(alloc, group_id);
    defer restored_provisioning.deinit(alloc);
    try std.testing.expectEqualStrings(provisioning.jobs_json[0], restored_provisioning.jobs_json[0]);
    var txn = try restored.store.beginWriteTxn();
    defer txn.abort();
    try applyRestoreStagingForTest(&restored, &txn, group_id, .{ .id = plan.id, .action = .canceled, .expected_revision = 2, .receipt = .{
        .group_id = 701,
        .range_id = 701,
        .plan_digest = try plan.digest(alloc),
        .completion_digest = @splat(5),
    } });
    try applyRestoreStagingForTest(&restored, &txn, group_id, .{ .id = plan.id, .action = .finish_cancel, .expected_revision = 2 });
    var buf: [256]u8 = undefined;
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.nameKey(&buf, group_id, target.table.name)));
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, target.table.table_id)));
    // Replaying admission cannot revive the job, nor may another job reuse
    // any canceled table/group ID and inherit a delayed import command.
    try applyRestoreStagingForTest(&restored, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    var replacement = plan;
    replacement.id = @splat(7);
    try applyRestoreStagingForTest(&restored, &txn, group_id, .{ .id = replacement.id, .action = .reserve, .plan = replacement });
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.jobKey(&buf, group_id, replacement.id)));
    _ = try txn.get(try restore_staging.identityKey(&buf, group_id, .group, 701));
}

test "relational integrity restore staging overwrite keeps old generation until fenced atomic cutover" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/overwrite", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const old_table: metadata.TableRecord = .{ .table_id = 1, .name = "documents", .schema_json = "{}" };
    const old_range: metadata.RangeRecord = .{ .table_id = 1, .group_id = 601, .range_id = 601, .start_key = "" };
    const target: restore_staging.Target = .{
        .source_table_id = 1,
        .table = .{ .table_id = 11, .name = "documents", .schema_json = "{}" },
        .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }},
        .replace = .{ .table = old_table, .ranges = &.{old_range} },
    };
    const plan: restore_staging.Plan = .{ .id = @splat(4), .cohort_digest = @splat(9), .targets = &.{target} };
    const digest = try plan.digest(alloc);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old_table });
        try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
        var buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        _ = try txn.get(try restore_staging.jobKey(&buf, group_id, plan.id));
        try std.testing.expect(try store.relationalDropBlockedTxn(&txn, group_id, old_table));
        try std.testing.expect(!try store.relationalParentsExistTxn(&txn, group_id, old_table));
        try txn.commit();
    }
    // The placement controller sees both generations, but normal routing only
    // sees the old one. Restored owners are provisioned EMPTY, never raw-imported.
    var provisioning = try store.captureProvisioningCatalog(alloc, group_id);
    defer provisioning.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), provisioning.tables.len);
    try std.testing.expectEqual(@as(usize, 2), provisioning.ranges.len);
    for (provisioning.tables) |table| try std.testing.expectEqualStrings("", table.restore_backup_id);
    // Both generations share a name until atomic cutover. Placement and its
    // desired-state seed must retain them by ID, without publishing an alias.
    var placement = metadata_table_manager.TableManager.initProvisioning(alloc);
    defer placement.deinit();
    _ = try placement.replaceProjectedTopology(provisioning.tables, provisioning.ranges);
    try std.testing.expectEqual(@as(u32, 2), placement.tables.count());
    try std.testing.expect(placement.findTableByName("documents") == null);
    var desired = metadata_table_manager.TableManager.initProvisioning(alloc);
    defer desired.deinit();
    try desired.replaceTopology(provisioning.tables, provisioning.ranges);
    try std.testing.expectEqual(@as(u32, 2), desired.tables.count());
    var txn = try store.store.beginWriteTxn();
    var txn_open = true;
    defer if (txn_open) txn.abort();
    var buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    const visible = try store.listTablesTxn(alloc, &txn, group_id);
    defer store.freeTables(alloc, visible);
    try std.testing.expectEqual(@as(usize, 1), visible.len);
    try std.testing.expectEqual(@as(u64, 1), visible[0].table_id);
    for ([_]restore_staging.Command{
        .{ .id = plan.id, .action = .imported, .expected_revision = 1, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = @splat(1) } },
        .{ .id = plan.id, .action = .validated, .expected_revision = 2, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = @splat(2) } },
        .{ .id = plan.id, .action = .publish, .expected_revision = 2 },
        .{ .id = plan.id, .action = .begin_cutover, .expected_revision = 2 },
        .{ .id = plan.id, .action = .publish, .expected_revision = 3 },
    }) |command| try applyRestoreStagingForTest(&store, &txn, group_id, command);
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, 1));
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, 11)));
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .old_fenced, .expected_revision = 3, .receipt = .{ .group_id = 601, .range_id = 601, .plan_digest = digest, .completion_digest = @splat(3) } });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 3 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, 1)));
    try std.testing.expectError(error.NotFound, txn.get(try rangeKeyForGroup(&buf, group_id, 601)));
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, 11));
    _ = try txn.get(try rangeKeyForGroup(&buf, group_id, 701));
    try std.testing.expect(try restoreStagingLocksTableTxn(&txn, group_id, 1));
    // Delayed old metadata cannot resurrect the retired physical generation.
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old_table });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, 1)));
    try std.testing.expectError(error.NotFound, txn.get(try rangeKeyForGroup(&buf, group_id, 601)));
    const published_fence = try store.loadTableTransitionFenceTxn(&txn, group_id, 11);
    try store.applyTableTopologyMutationTxn(&txn, group_id, .{ .drop = .{
        .table_id = 11,
        .expected_name = "documents",
        .expected_transition_generation = published_fence.generation,
        .range_contract = .{ .membership = published_fence.membership(11) },
    } });
    const recreate_fence = try store.loadTableTransitionFenceTxn(&txn, group_id, 11);
    var recreated_range = target.ranges[0];
    recreated_range.group_id = 801;
    recreated_range.range_id = 801;
    recreated_range.doc_identity_shard_id = 801;
    recreated_range.doc_identity_range_id = 801;
    try store.applyTableTopologyMutationTxn(&txn, group_id, .{ .create = .{
        .table = target.table,
        .expected_transition_generation = recreate_fence.generation,
        .ranges = &.{recreated_range},
    } });
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, 11));
    _ = try txn.get(try rangeKeyForGroup(&buf, group_id, 801));
    try std.testing.expectError(error.NotFound, txn.get(try rangeKeyForGroup(&buf, group_id, 701)));
    try txn.commit();
    txn_open = false;
    try std.testing.expectEqual(@as(u64, 11), try store.resolveTableCreateIdentity(group_id, 1));
}

test "relational integrity restore staging graph empty-generation cutover replays old tombstone and fresh owner atomically" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/graph-empty-cutover", .{tmp.sub_path});
    defer alloc.free(root);
    const group_id = group_ids.main_metadata_group_id;
    const indexes = "{\"links\":{\"type\":\"graph\"}}";
    const old: metadata.TableRecord = .{ .table_id = 1, .name = "documents", .schema_json = "{}", .indexes_json = indexes };
    const old_range: metadata.RangeRecord = .{ .table_id = 1, .group_id = 601, .range_id = 601, .start_key = "" };
    const fence: @import("antfly_local_sources").storage_db_relational_integrity_topology_contract.Fence = .{ .role = .rewrite_source, .transition_id = 7, .attempt = 1, .owner_group_id = 601, .peer_group_id = 701, .namespace = .{ .table_id = 1, .shard_id = 601, .range_id = 601 }, .catalog_digest = @splat(4) };
    const handoff: restore_staging.GenerationHandoffRange = .{ .source_group_id = 601, .target_group_id = 701, .source_namespace = fence.namespace, .admissions = &.{}, .admissions_digest = try @import("antfly_local_sources").storage_portable_backup.sourceGenerationAdmissionSummaryDigest(fence.namespace, &.{}), .retired_digest = @splat(8), .retired_count = 0 };
    var replacement = old;
    replacement.table_id = 11;
    const target: restore_staging.Target = .{
        .source_table_id = 1,
        .empty_generation = true,
        .graph_retirement_digest = try restore_staging.graphRetirementDigest(alloc, 1, 11, indexes),
        .generation_handoffs = &.{handoff},
        .table = replacement,
        .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }},
        .replace = .{ .table = old, .ranges = &.{old_range}, .fences = &.{fence} },
    };
    const plan: restore_staging.Plan = .{ .id = try restore_staging.idForAttempt(7, 1), .cohort_digest = @splat(9), .targets = &.{target} };
    try plan.validate(alloc);
    const digest = try plan.digest(alloc);
    const graph_scope = (try restore_staging.graphSealScopeForOldRange(alloc, plan, digest, target, old_range)).?;
    const graph_seal = try graph_scope.sealDigest();
    const preflight = try restore_staging.generationHandoffPreflightDigest(fence, digest, handoff);
    const handoff_seal = try restore_staging.generationHandoffSealDigest(fence, digest, handoff);
    const combined_seal = try restore_staging.generationHandoffOldFenceDigest(fence, handoff_seal, graph_seal);
    const target_install = (try restore_staging.mappedEmptyGenerationHandoffForGroup(alloc, plan, digest, 701)).?;
    {
        const cancel_root = try std.fmt.allocPrint(alloc, "{s}-before-cutover", .{root});
        defer alloc.free(cancel_root);
        var cancel_store = try RaftApplyStore.init(alloc, .{ .root_dir = cancel_root });
        defer cancel_store.deinit();
        var txn = try cancel_store.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        try cancel_store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old });
        try cancel_store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
        try applyRestoreStagingForTest(&cancel_store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
        try applyRestoreStagingForTest(&cancel_store, &txn, group_id, .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 1 });
        try txn.commit();
        txn_open = false;
        try std.testing.expectEqual(restore_staging.State.canceling, (try cancel_store.loadRestoreStagingProgress(alloc, group_id, plan.id)).?.state);
    }
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        var txn = try store.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old });
        try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
        try txn.commit();
        txn_open = false;
    }
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        var txn = try store.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        _ = try txn.get(try tableKeyForGroup(&key_buf, group_id, 1));
        try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
        for ([_]restore_staging.Command{
            .{ .id = plan.id, .action = .imported, .expected_revision = 1, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = @splat(1) } },
            .{ .id = plan.id, .action = .validated, .expected_revision = 2, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = @splat(2) } },
            .{ .id = plan.id, .action = .begin_cutover, .expected_revision = 2 },
            .{ .id = plan.id, .action = .source_handoff_checked, .expected_revision = 2, .receipt = .{ .group_id = 601, .range_id = 601, .plan_digest = digest, .completion_digest = @splat(3) } },
            .{ .id = plan.id, .action = .source_handoff_checked, .expected_revision = 2, .receipt = .{ .group_id = 601, .range_id = 601, .plan_digest = digest, .completion_digest = preflight } },
            .{ .id = plan.id, .action = .begin_cutover, .expected_revision = 3 },
            .{ .id = plan.id, .action = .old_fenced, .expected_revision = 4, .receipt = .{ .group_id = 601, .range_id = 601, .plan_digest = digest, .completion_digest = @splat(3) } },
            .{ .id = plan.id, .action = .old_fenced, .expected_revision = 4, .receipt = .{ .group_id = 601, .range_id = 602, .plan_digest = digest, .completion_digest = combined_seal } },
            .{ .id = plan.id, .action = .old_fenced, .expected_revision = 4, .receipt = .{ .group_id = 601, .range_id = 601, .plan_digest = digest, .completion_digest = graph_seal } },
            .{ .id = plan.id, .action = .old_fenced, .expected_revision = 4, .receipt = .{ .group_id = 601, .range_id = 601, .plan_digest = digest, .completion_digest = combined_seal } },
            // Graph begin_cutover is irreversible: a late cancellation may
            // not move metadata to canceling after the owner sealed its gate.
            .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 4 },
            .{ .id = plan.id, .action = .publish, .expected_revision = 4 },
            .{ .id = plan.id, .action = .begin_activation, .expected_revision = 4 },
            .{ .id = plan.id, .action = .target_admissions_activated, .expected_revision = 5, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = @splat(3) } },
            .{ .id = plan.id, .action = .target_admissions_activated, .expected_revision = 5, .receipt = .{ .group_id = 701, .range_id = 701, .plan_digest = digest, .completion_digest = target_install.expected_receipt_digest } },
            .{ .id = plan.id, .action = .publish, .expected_revision = 5 },
        }) |command| try applyRestoreStagingForTest(&store, &txn, group_id, command);
        try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 1)));
        _ = try txn.get(try tableKeyForGroup(&key_buf, group_id, 11));
        try txn.commit();
        txn_open = false;
    }
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        var txn = try store.store.beginWriteTxn();
        defer txn.abort();
        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 1)));
        _ = try txn.get(try tableKeyForGroup(&key_buf, group_id, 11));
        try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old });
        try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 1)));
    }
}

test "relational integrity restore staging cancellation drains both old and new owners" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/overwrite-cancel", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const old_table: metadata.TableRecord = .{ .table_id = 1, .name = "documents", .schema_json = "{}" };
    const old_range: metadata.RangeRecord = .{ .table_id = 1, .group_id = 601, .range_id = 601, .start_key = "" };
    const target: restore_staging.Target = .{
        .source_table_id = 1,
        .table = .{ .table_id = 11, .name = "documents", .schema_json = "{}" },
        .ranges = &.{.{ .table_id = 11, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }},
        .replace = .{ .table = old_table, .ranges = &.{old_range} },
    };
    const plan: restore_staging.Plan = .{ .id = @splat(4), .cohort_digest = @splat(9), .targets = &.{target} };
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old_table });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .begin_cancel, .expected_revision = 1 });
    var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    for ([_]u64{ 701, 601 }, 0..) |owner, index| {
        const command: restore_staging.Command = .{ .id = plan.id, .action = .canceled, .expected_revision = 2, .receipt = .{
            .group_id = owner,
            .range_id = owner,
            .plan_digest = try plan.digest(alloc),
            .completion_digest = @splat(1),
        } };
        try applyRestoreStagingForTest(&store, &txn, group_id, command);
        try applyRestoreStagingForTest(&store, &txn, group_id, command);
        try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .finish_cancel, .expected_revision = 2 });
        if (index == 0) {
            _ = try txn.get(try restore_staging.nameKey(&key_buf, group_id, "documents"));
            try std.testing.expect(try restoreStagingLocksTableTxn(&txn, group_id, 1));
        }
    }
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.nameKey(&key_buf, group_id, "documents")));
    try std.testing.expect(!try restoreStagingLocksTableTxn(&txn, group_id, 1));
    _ = try txn.get(try tableKeyForGroup(&key_buf, group_id, 1));
    _ = try txn.get(try rangeKeyForGroup(&key_buf, group_id, 601));
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
    try std.testing.expect(try store.relationalParentsExistTxn(&txn, group_id, old_table));
    // Delayed cutover and publication cannot resurrect a canceled attempt.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .begin_cutover, .expected_revision = 3 });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .publish, .expected_revision = 3 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&key_buf, group_id, 11)));
}

test "relational integrity restore staging fences incoming dependency admission" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/restore-dependencies", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group_id = group_ids.main_metadata_group_id;
    const parent: metadata.TableRecord = .{
        .table_id = 7,
        .name = "parents",
        .schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
        ,
    };
    const child: metadata.TableRecord = .{
        .table_id = 8,
        .name = "children",
        .schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"parent_fk","child_columns":["id"],"parent_table":"parents","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
        ,
    };
    const old_range: metadata.RangeRecord = .{ .table_id = 7, .group_id = 601, .range_id = 601, .start_key = "" };
    var replacement = parent;
    replacement.table_id = 17;
    const plan: restore_staging.Plan = .{ .id = @splat(7), .cohort_digest = @splat(9), .targets = &.{.{
        .source_table_id = 7,
        .table = replacement,
        .ranges = &.{.{ .table_id = 17, .group_id = 701, .range_id = 701, .doc_identity_shard_id = 701, .doc_identity_range_id = 701, .start_key = "" }},
        .replace = .{ .table = parent, .ranges = &.{old_range} },
    }} };
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = parent });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = child });
    var buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, 8));
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.jobKey(&buf, group_id, plan.id)));
    // Remove the test declaration to model a completed child retirement/drop.
    try txn.delete(try tableKeyForGroup(&buf, group_id, 8));
    try store.deleteTableNameIndexTxn(&txn, group_id, child.name);
    const dependencies = @import("../schema_validation_dependencies.zig");
    const lease_head: @import("../schema_validation_publication.zig").Head = .{ .metadata_group_id = group_id, .metadata_incarnation = "0123456789abcdef0123456789abcdef".*, .table_id = child.table_id, .id = @splat(91), .plan_digest = @splat(92), .owner_count = 1 };
    // Fixture lease only: the real FK ledger campaign independently qualifies
    // its admission/ACK authority. This verifies restore's exclusion boundary.
    const lease_source: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.ForeignKeySource = .{ .table_name = child.name, .parents = &.{.{ .constraint_name = "parent_fk", .declared_parent = parent.name, .parent_table = parent.name, .parent_table_id = parent.table_id, .parent_schema_version = 1, .parent_schema = @splat(1), .parent_public = @splat(2), .parent_catalog = @splat(3), .parent_unique = "pk", .parent_generation = @splat(4), .parent_definition = @splat(5) }} };
    try dependencies.acquire(alloc, &txn, lease_head, lease_source);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.jobKey(&buf, group_id, plan.id)));
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.nameKey(&buf, group_id, replacement.name)));
    try dependencies.releaseJob(&txn, lease_head, 1);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = plan.id, .action = .reserve, .plan = plan });
    _ = try txn.get(try restore_staging.jobKey(&buf, group_id, plan.id));
    // A late incoming FK is rejected by the authoritative apply transaction,
    // not merely by a stale coordinator admission snapshot.
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = child });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, 8)));
}

