    const next_generation = try restore_staging.plannedForeignGeneration(alloc, target, "fk");
    const parent: restore_staging.ExternalFkParent = .{ .table = parent_table, .ranges = &.{parent_range}, .fences = &.{parent_fence}, .foreign_keys = &.{.{ .child_table_id = 9, .child_table_name = "children", .constraint_name = "fk", .generation = @splat(5), .next_generation = next_generation }} };
    const plan: restore_staging.Plan = .{ .id = id, .cohort_digest = @splat(3), .targets = &.{target}, .external_fk_parents = &.{parent} };
    var txn = try store.store.beginWriteTxn();
    var txn_open = true;
    defer if (txn_open) txn.abort();
    var buf: [catalog_name_key_buffer_bytes]u8 = undefined;
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = parent_table });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = parent_range });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_table = old });
    try store.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = old_range });
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, old.table_id));
    try std.testing.expect(try store.restoreReplacementMatchesTxn(&txn, group_id, target));
    try std.testing.expect(try store.restoreExternalParentMatchesTxn(&txn, group_id, parent));
    try std.testing.expect(try store.restoreIncomingDependenciesClosedTxn(&txn, group_id, plan));
    const locks = @import("../table_lifecycle_lock.zig");
    for ([_]u64{ old.table_id, parent_table.table_id }) |locked_table| {
        for ([_]locks.Kind{ .generation, .initial_support, .index_build, .schema_validation }) |kind| {
            const lock: locks.Lock = .{ .kind = kind, .id = @splat(91) };
            try locks.acquire(&txn, group_id, locked_table, lock);
            try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .reserve, .plan = plan });
            try std.testing.expectError(error.NotFound, txn.get(try restore_staging.jobKey(&buf, group_id, id)));
            try std.testing.expectError(error.NotFound, txn.get(try restore_staging.nameKey(&buf, group_id, target.table.name)));
            try locks.release(&txn, group_id, locked_table, lock);
        }
    }
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .reserve, .plan = plan });
    _ = try txn.get(try restore_staging.jobKey(&buf, group_id, id));
    try std.testing.expect(try restoreStagingLocksTableTxn(&txn, group_id, parent_table.table_id));
    _ = try txn.get(try restore_staging.identityKey(&buf, group_id, .parent_group, parent_range.group_id));
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.identityKey(&buf, group_id, .group, parent_range.group_id)));
    try txn.commit();
    txn_open = false;
    // A coordinator restart after durable reservation must retain the parent
    // identity lock and exact parent-group authority, not silently reopen a
    // concurrent schema or topology transition.
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, id, 7, 501));
    try store.applyStandaloneCommand(group_id, .{ .register_node = .{ .node_id = 7, .role = "data", .lifecycle = metadata_table_manager.node_lifecycle_active } });
    try store.applyStandaloneCommand(group_id, .{ .upsert_replica_intent = .{
        .expected_metadata_version = null,
        .expected_version_fence = 0,
        .expected_target_drain_requested = false,
        .replacement = .{ .record = .{ .group_id = 501, .replica_id = 1, .local_node_id = 7 }, .store_id = 0, .peer_node_ids = &.{7} },
    } });
    try std.testing.expect(try store.restoreStagingAuthorityAllowed(alloc, group_id, id, 7, 501));
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, id, 7, null));
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, id, 7, 301));
    txn = try store.store.beginWriteTxn();
    txn_open = true;
    try std.testing.expect(try restoreStagingLocksTableTxn(&txn, group_id, parent_table.table_id));
    const digest = try plan.digest(alloc);
    const preflight = try restore_staging.generationHandoffPreflightDigest(old_fence, digest, handoff);
    const handoff_seal = try restore_staging.generationHandoffSealDigest(old_fence, digest, handoff);
    const old_completion = try restore_staging.generationHandoffOldFenceDigest(old_fence, handoff_seal, null);
    const target_install = (try restore_staging.mappedEmptyGenerationHandoffForGroup(alloc, plan, digest, 401)).?;
    const new_receipt: restore_staging.OwnerReceipt = .{ .group_id = 401, .range_id = 401, .plan_digest = digest, .completion_digest = @splat(1) };
    const parent_receipt: restore_staging.OwnerReceipt = .{ .group_id = 501, .range_id = 501, .plan_digest = digest, .completion_digest = @splat(2) };
    const old_receipt: restore_staging.OwnerReceipt = .{ .group_id = 301, .range_id = 301, .plan_digest = digest, .completion_digest = old_completion };
    // A parent acknowledgement cannot arrive before cutover.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .parent_fenced, .expected_revision = 1, .receipt = parent_receipt });
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.receiptKey(&buf, group_id, id, .cutover, 501)));
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .imported, .expected_revision = 1, .receipt = new_receipt });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .validated, .expected_revision = 2, .receipt = new_receipt });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_cutover, .expected_revision = 2 });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .source_handoff_checked, .expected_revision = 2, .receipt = .{ .group_id = 301, .range_id = 301, .plan_digest = digest, .completion_digest = preflight } });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_cutover, .expected_revision = 3 });
    // Old-child cutover cannot outrun the parent pending record.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .old_fenced, .expected_revision = 4, .receipt = old_receipt });
    try std.testing.expectError(error.NotFound, txn.get(try restore_staging.receiptKey(&buf, group_id, id, .cutover, 301)));
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .parent_fenced, .expected_revision = 4, .receipt = parent_receipt });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .parent_fenced, .expected_revision = 4, .receipt = parent_receipt });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .old_fenced, .expected_revision = 4, .receipt = old_receipt });
    try txn.commit();
    txn_open = false;
    // Crash between parent/old-child cutover receipts and the irreversible
    // activation decision: replayed metadata must still require the exact
    // owner activation receipt before any target becomes visible.
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    txn = try store.store.beginWriteTxn();
    txn_open = true;
    // The metadata decision is irreversible: once a parent may have made old
    // inverse references invisible, cancellation cannot revive the child.
    // A fabricated receipt is rejected; an exact owner publication receipt
    // permits the all-table metadata switch only after the decision.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_activation, .expected_revision = 4 });
    const activating_bytes = try txn.get(try restore_staging.progressKey(&buf, group_id, id));
    var activating = try std.json.parseFromSlice(restore_staging.Progress, alloc, activating_bytes, .{});
    defer activating.deinit();
    try std.testing.expectEqual(restore_staging.State.activating, activating.value.state);
    try std.testing.expectEqual(@as(u64, 5), activating.value.revision);
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_cancel, .expected_revision = 5 });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .parent_activated, .expected_revision = 5, .receipt = parent_receipt });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 5 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, target.table.table_id)));
    const verified_digest = try @import("antfly_local_sources").storage_db_relational_integrity_generation_retirement.activationReceipt(parent_fence, digest, @import("antfly_local_sources").storage_db_relational_integrity_generation_retirement.publicationDigest(id, digest));
    var verified_receipt = parent_receipt;
    verified_receipt.completion_digest = verified_digest;
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .parent_activated, .expected_revision = 5, .receipt = verified_receipt });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 5 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, target.table.table_id)));
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .target_admissions_activated, .expected_revision = 5, .receipt = .{ .group_id = 401, .range_id = 401, .plan_digest = digest, .completion_digest = target_install.expected_receipt_digest } });
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 5 });
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, target.table.table_id));
    txn.abort();
    txn_open = false;
    try store.applyStandaloneCommand(group_id, .{ .remove_replica_intent = .{ .group_id = 501, .local_node_id = 7, .expected_metadata_version = 1 } });
    try std.testing.expect(!try store.restoreStagingAuthorityAllowed(alloc, group_id, id, 7, 501));
    txn = try store.store.beginWriteTxn();
    txn_open = true;
    // Publication is still impossible without activation proof.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .publish, .expected_revision = 4 });
    try std.testing.expectError(error.NotFound, txn.get(try tableKeyForGroup(&buf, group_id, target.table.table_id)));
    // Cutover is irreversible once source handoff can be sealed. Removing a
    // replica does not turn this into a cancellable job or release the parent
    // lock; a new leader must finish the exact activation receipts.
    try applyRestoreStagingForTest(&store, &txn, group_id, .{ .id = id, .action = .begin_cancel, .expected_revision = 4 });
    try std.testing.expect(try restoreStagingLocksTableTxn(&txn, group_id, parent_table.table_id));
    _ = try txn.get(try tableKeyForGroup(&buf, group_id, parent_table.table_id));
    _ = try txn.get(try rangeKeyForGroup(&buf, group_id, parent_range.group_id));
}

test "metadata raft apply store restore job transition encoding is append-only compatible" {
    const encoded = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_restore_job = .{
            .key = "\x00\x00__api_restore_jobs__:000000000000002a",
            .value = "{\"job_id\":42}",
        },
    });
    defer std.testing.allocator.free(encoded);
    var decoded = (try decodeTransitionCommand(std.testing.allocator, encoded)).?;
    defer decoded.deinit(std.testing.allocator);
    try std.testing.expect(decoded == .upsert_restore_job);
    try std.testing.expectEqualStrings("\x00\x00__api_restore_jobs__:000000000000002a", decoded.upsert_restore_job.key);
    try std.testing.expectEqualStrings("{\"job_id\":42}", decoded.upsert_restore_job.value);

    const keys = [_][]const u8{
        "\x00\x00__api_restore_jobs__:000000000000002a",
        "\x00\x00__api_restore_jobs__:000000000000002b",
    };
    const batch_encoded = try encodeTransitionCommand(std.testing.allocator, .{
        .remove_restore_jobs = .{ .keys = &keys },
    });
    defer std.testing.allocator.free(batch_encoded);
    var batch_decoded = (try decodeTransitionCommand(std.testing.allocator, batch_encoded)).?;
    defer batch_decoded.deinit(std.testing.allocator);
    try std.testing.expect(batch_decoded == .remove_restore_jobs);
    try std.testing.expectEqual(@as(usize, 2), batch_decoded.remove_restore_jobs.keys.len);
    try std.testing.expectEqualStrings(keys[0], batch_decoded.remove_restore_jobs.keys[0]);
    try std.testing.expectEqualStrings(keys[1], batch_decoded.remove_restore_jobs.keys[1]);
}

test "metadata transition decoders reject unknown enum values" {
    const unknown_transition = transition_magic ++ [_]u8{0xff};
    try std.testing.expectError(
        error.InvalidMetadataTransitionEncoding,
        decodeTransitionCommand(std.testing.allocator, unknown_transition),
    );

    const bootstrap_mode_offset = @sizeOf(u64) * 4;
    var placement = try encodePlacementIntent(std.testing.allocator, .{
        .record = .{
            .group_id = 7001,
            .replica_id = 1,
            .local_node_id = 2,
        },
    });
    defer std.testing.allocator.free(placement);
    const original_bootstrap_mode = placement[bootstrap_mode_offset];
    placement[bootstrap_mode_offset] = 0xff;
    try std.testing.expectError(
        error.InvalidMetadataTransitionEncoding,
        decodePlacementIntent(std.testing.allocator, placement),
    );
    placement[bootstrap_mode_offset] = original_bootstrap_mode;

    const serving_state_offset = bootstrap_mode_offset + 1 + @sizeOf(u32) + @sizeOf(u64) + 1;
    placement[serving_state_offset] = 0xff;
    try std.testing.expectError(
        error.InvalidMetadataTransitionEncoding,
        decodePlacementIntent(std.testing.allocator, placement),
    );

    var merge = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_merge_transition = .{
            .transition_id = 1,
            .donor_group_id = 7001,
            .receiver_group_id = 7002,
            .table_contract = test_transition_table_contract,
        },
    });
    defer std.testing.allocator.free(merge);
    const merge_phase_offset = transition_magic.len + 1 + @sizeOf(u64) * 3;
    const original_merge_phase = merge[merge_phase_offset];
    merge[merge_phase_offset] = 0xff;
    try std.testing.expectError(
        error.InvalidMetadataTransitionEncoding,
        decodeTransitionCommand(std.testing.allocator, merge),
    );
    merge[merge_phase_offset] = original_merge_phase;

    const merge_reassignment_offset = merge_phase_offset + 2;
    merge[merge_reassignment_offset] = 2;
    try std.testing.expectError(
        error.InvalidMetadataTransitionEncoding,
        decodeTransitionCommand(std.testing.allocator, merge),
    );
}

test "metadata raft apply store replicates restore job records" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-restore-job-store", .{tmp.sub_path});
    defer std.testing.allocator.free(root);
    const group_id = group_ids.main_metadata_group_id;
    const logical_key = "\x00\x00__api_restore_jobs__:000000000000002a";
    const value = "{\"job_id\":42,\"phase\":\"queued\"}";

    const upsert = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_restore_job = .{ .key = logical_key, .value = value },
    });
    defer std.testing.allocator.free(upsert);
    const upsert_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = upsert },
    });
    defer std.testing.allocator.free(upsert_entries);

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();
    try store.snapshotBuilder().applyBatch(.{
        .group_id = group_id,
        .commit_index = 1,
        .entries_bytes = upsert_entries,
    });
    const loaded = (try store.getRestoreJobValue(std.testing.allocator, group_id, logical_key)).?;
    defer std.testing.allocator.free(loaded);
    try std.testing.expectEqualStrings(value, loaded);
    const rows = try store.listRestoreJobRows(std.testing.allocator, group_id);
    defer store.freeRestoreJobRows(std.testing.allocator, rows);
    try std.testing.expectEqual(@as(usize, 1), rows.len);
    try std.testing.expectEqualStrings(logical_key, rows[0].key);

    const remove = try encodeTransitionCommand(std.testing.allocator, .{
        .remove_restore_job = .{ .key = logical_key },
    });
    defer std.testing.allocator.free(remove);
    const remove_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = remove },
    });
    defer std.testing.allocator.free(remove_entries);
    try store.snapshotBuilder().applyBatch(.{
        .group_id = group_id,
        .commit_index = 2,
        .entries_bytes = remove_entries,
    });
    try std.testing.expect((try store.getRestoreJobValue(std.testing.allocator, group_id, logical_key)) == null);
}

test "metadata raft apply store initializes one durable snapshotted cluster incarnation" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const source_root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-incarnation-source", .{tmp.sub_path});
    defer std.testing.allocator.free(source_root);
    const target_root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-incarnation-target", .{tmp.sub_path});
    defer std.testing.allocator.free(target_root);
    const group_id = group_ids.main_metadata_group_id;
    const first: metadata_incarnation.MetadataClusterIncarnation = "11111111111111111111111111111111".*;
    const competing: metadata_incarnation.MetadataClusterIncarnation = "22222222222222222222222222222222".*;
    const Capture = struct {
        incarnation_signals: usize = 0,

        fn onProjection(ptr: *anyopaque, signal: ProjectionSignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (signal.kind == .metadata_incarnation) self.incarnation_signals += 1;
        }
    };

    const initialize = try encodeTransitionCommand(std.testing.allocator, .{ .initialize_metadata_incarnation = first });
    defer std.testing.allocator.free(initialize);
    const compete = try encodeTransitionCommand(std.testing.allocator, .{ .initialize_metadata_incarnation = competing });
    defer std.testing.allocator.free(compete);
    const entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = initialize },
        .{ .term = 2, .index = 2, .entry_type = .normal, .data = compete },
    });
    defer std.testing.allocator.free(entries);

    var source = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = source_root });
    var capture = Capture{};
    try source.addProjectionListener(.{ .ptr = &capture, .vtable = &.{ .on_projection_signal = Capture.onProjection } });
    try source.snapshotBuilder().applyBatch(.{ .group_id = group_id, .commit_index = 2, .entries_bytes = entries });
    try std.testing.expectEqual(first, (try source.getMetadataIncarnation(group_id)).?);
    try std.testing.expectEqual(@as(usize, 1), capture.incarnation_signals);
    try std.testing.expectEqual(@as(u64, 2), (try source.captureCatalogCursor(group_id)).revision);
    try std.testing.expectEqual(@as(u16, 0), try source.getRuntimeStatusProtocolActivationVersion(group_id));

    var repair_indexes = [_]metadata.RuntimeIndexStatusReport{.{
        .name = "visual_idx",
        .kind = "dense_vector",
        .lifecycle_work_class = .repair,
        .repair_status = .rebuilding,
        .repair_active_generation_serviceable = true,
    }};
    var runtime_statuses = [_]metadata.RuntimeGroupStatusReport{.{
        .table_id = 11,
        .table_name = "products",
        .group_id = 12,
        .store_id = 13,
        .node_id = 1,
        .indexes = repair_indexes[0..],
    }};
    const activate = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_store = .{
        .store_id = 13,
        .node_id = 1,
        .runtime_statuses = runtime_statuses[0..],
    } });
    defer std.testing.allocator.free(activate);
    const activate_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 2, .index = 3, .entry_type = .normal, .data = activate },
    });
    defer std.testing.allocator.free(activate_entries);
    try source.snapshotBuilder().applyBatch(.{ .group_id = group_id, .commit_index = 3, .entries_bytes = activate_entries });
    try std.testing.expectEqual(@as(u64, 2), (try source.captureCatalogCursor(group_id)).revision);
    try std.testing.expectEqual(
        runtime_status_protocol.repair_status_record_version,
        try source.getRuntimeStatusProtocolActivationVersion(group_id),
    );
    const activate_reporter_fence = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_store = .{
        .store_id = 13,
        .node_id = 1,
        .reporter_incarnation = 0x1234,
        .dense_native_storage_protocol_version = metadata_table_manager.dense_native_storage_protocol_version,
    } });
    defer std.testing.allocator.free(activate_reporter_fence);
    const reporter_fence_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 2, .index = 4, .entry_type = .normal, .data = activate_reporter_fence },
    });
    defer std.testing.allocator.free(reporter_fence_entries);
    try source.snapshotBuilder().applyBatch(.{
        .group_id = group_id,
        .commit_index = 4,
        .entries_bytes = reporter_fence_entries,
    });
    try std.testing.expectEqual(@as(u64, 4), (try source.captureCatalogCursor(group_id)).revision);
    try std.testing.expectEqual(
        runtime_status_protocol.framed_index_record_version,
        try source.getRuntimeStatusProtocolActivationVersion(group_id),
    );
    try std.testing.expectEqual(
        metadata_table_manager.dense_native_storage_protocol_version,
        try source.getDenseNativeStorageProtocolActivationVersion(group_id),
    );
    const stale_legacy_store = try encodeTransitionCommand(std.testing.allocator, .{ .register_store = .{
        .store_id = 14,
        .node_id = 2,
    } });
    defer std.testing.allocator.free(stale_legacy_store);
    const stale_legacy_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 2, .index = 5, .entry_type = .normal, .data = stale_legacy_store },
    });
    defer std.testing.allocator.free(stale_legacy_entries);
    try source.snapshotBuilder().applyBatch(.{
        .group_id = group_id,
        .commit_index = 5,
        .entries_bytes = stale_legacy_entries,
    });
    const activated_stores = try source.listStores(std.testing.allocator, group_id);
    defer source.freeStores(std.testing.allocator, activated_stores);
    try std.testing.expectEqual(@as(usize, 1), activated_stores.len);
    try std.testing.expectEqual(@as(u64, 13), activated_stores[0].store_id);
    const snapshot = try source.snapshotBuilder().buildSnapshot(std.testing.allocator, group_id);
    defer std.testing.allocator.free(snapshot);
    source.deinit();

    var reopened = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = source_root });
    defer reopened.deinit();
    try std.testing.expectEqual(first, (try reopened.getMetadataIncarnation(group_id)).?);
    const reopened_cursor = try reopened.captureCatalogCursor(group_id);
    try std.testing.expectEqual(first, reopened_cursor.metadata_incarnation.?);
    try std.testing.expectEqual(@as(u64, 4), reopened_cursor.revision);
    try std.testing.expectEqual(
        runtime_status_protocol.framed_index_record_version,
        try reopened.getRuntimeStatusProtocolActivationVersion(group_id),
    );
    try std.testing.expectEqual(
        metadata_table_manager.dense_native_storage_protocol_version,
        try reopened.getDenseNativeStorageProtocolActivationVersion(group_id),
    );

    var target = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = target_root });
    defer target.deinit();
    try std.testing.expect(try target.snapshotBuilder().installSnapshot(std.testing.allocator, group_id, 5, snapshot));
    try std.testing.expectEqual(first, (try target.getMetadataIncarnation(group_id)).?);
    const installed_cursor = try target.captureCatalogCursor(group_id);
    try std.testing.expectEqual(first, installed_cursor.metadata_incarnation.?);
    try std.testing.expectEqual(@as(u64, 4), installed_cursor.revision);
    try std.testing.expectEqual(
        runtime_status_protocol.framed_index_record_version,
        try target.getRuntimeStatusProtocolActivationVersion(group_id),
    );
    try std.testing.expectEqual(
        metadata_table_manager.dense_native_storage_protocol_version,
        try target.getDenseNativeStorageProtocolActivationVersion(group_id),
    );
}

test "metadata raft apply store snapshots and promotes the latest pending reallocation" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const source_root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-reallocation-source", .{tmp.sub_path});
    defer std.testing.allocator.free(source_root);
    const target_root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-reallocation-target", .{tmp.sub_path});
    defer std.testing.allocator.free(target_root);
    const group_id = group_ids.main_metadata_group_id;
    const incarnation: metadata_incarnation.MetadataClusterIncarnation = "0123456789abcdef0123456789abcdef".*;
    const fingerprint = metadata.reallocation_request.membershipFingerprint(&.{1});
    const active: metadata.ReallocationRequestRecord = .{
        .request_id = 17,
        .requested_at_ms = 17_000,
        .barrier_protocol_version = metadata.reallocation_request.barrier_protocol_version,
        .metadata_incarnation = incarnation,
        .protected_metadata_member_count = 1,
        .protected_metadata_membership_fingerprint = fingerprint,
    };
    const superseded_pending: metadata.ReallocationRequestRecord = .{
        .request_id = 18,
        .requested_at_ms = 18_000,
        .barrier_protocol_version = metadata.reallocation_request.barrier_protocol_version,
        .metadata_incarnation = incarnation,
        .protected_metadata_member_count = 1,
        .protected_metadata_membership_fingerprint = fingerprint,
    };
    const latest_pending: metadata.ReallocationRequestRecord = .{
        .request_id = 19,
        .requested_at_ms = 19_000,
        .barrier_protocol_version = metadata.reallocation_request.barrier_protocol_version,
        .metadata_incarnation = incarnation,
        .protected_metadata_member_count = 1,
        .protected_metadata_membership_fingerprint = fingerprint,
    };

    const active_command = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_reallocation_request = active });
    defer std.testing.allocator.free(active_command);
    const superseded_pending_command = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_reallocation_request = superseded_pending });
    defer std.testing.allocator.free(superseded_pending_command);
    const latest_pending_command = try encodeTransitionCommand(std.testing.allocator, .{ .upsert_reallocation_request = latest_pending });
    defer std.testing.allocator.free(latest_pending_command);
    const entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = active_command },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = superseded_pending_command },
        .{ .term = 1, .index = 3, .entry_type = .normal, .data = latest_pending_command },
    });
    defer std.testing.allocator.free(entries);

    var source = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = source_root });
    defer source.deinit();
    try source.snapshotBuilder().applyBatch(.{ .group_id = group_id, .commit_index = 3, .entries_bytes = entries });
    try std.testing.expectEqual(active, (try source.getReallocationRequest(group_id)).?);
    const snapshot = try source.snapshotBuilder().buildSnapshot(std.testing.allocator, group_id);
    defer std.testing.allocator.free(snapshot);

    var target = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = target_root });
    defer target.deinit();
    try std.testing.expect(try target.snapshotBuilder().installSnapshot(std.testing.allocator, group_id, 3, snapshot));
    try std.testing.expectEqual(active, (try target.getReallocationRequest(group_id)).?);

    const clear_active = try encodeTransitionCommand(std.testing.allocator, .{
        .remove_reallocation_request = .{ .expected_request_id = active.request_id },
    });
    defer std.testing.allocator.free(clear_active);
    const clear_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 4, .entry_type = .normal, .data = clear_active },
    });
    defer std.testing.allocator.free(clear_entries);
    try target.snapshotBuilder().applyBatch(.{ .group_id = group_id, .commit_index = 4, .entries_bytes = clear_entries });
    try std.testing.expectEqual(latest_pending, (try target.getReallocationRequest(group_id)).?);

    const clear_promoted = try encodeTransitionCommand(std.testing.allocator, .{
        .remove_reallocation_request = .{ .expected_request_id = latest_pending.request_id },
    });
    defer std.testing.allocator.free(clear_promoted);
    const final_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 5, .entry_type = .normal, .data = clear_promoted },
    });
    defer std.testing.allocator.free(final_entries);
    try target.snapshotBuilder().applyBatch(.{ .group_id = group_id, .commit_index = 5, .entries_bytes = final_entries });
    try std.testing.expect((try target.getReallocationRequest(group_id)) == null);
}

test "metadata raft apply store snapshot replaces one complete projection and preserves other groups" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const source_root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-snapshot-source", .{tmp.sub_path});
    defer std.testing.allocator.free(source_root);
    const target_root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-snapshot-target", .{tmp.sub_path});
    defer std.testing.allocator.free(target_root);
    const group_id = group_ids.main_metadata_group_id;
    const other_group_id = group_id + 1;
    const retained_key = "\x00\x00__api_restore_jobs__:0000000000000001";
    const stale_key = "\x00\x00__api_restore_jobs__:0000000000000002";
    const other_group_key = "\x00\x00__api_restore_jobs__:0000000000000003";

    const retained_command = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_restore_job = .{ .key = retained_key, .value = "retained" },
    });
    defer std.testing.allocator.free(retained_command);
    const table_command = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_table = testTransitionTableRecord(),
    });
    defer std.testing.allocator.free(table_command);
    const source_range_command = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_range = testTransitionRangeRecord(
            101,
            test_transition_table_contract.source_identity,
            "a",
            "z",
        ),
    });
    defer std.testing.allocator.free(source_range_command);
    const split_command = try encodeTransitionCommand(std.testing.allocator, .{
        .admit_split_transition = .{
            .expected_source_epoch = 0,
            .record = .{
                .transition_id = 71,
                .attempt_epoch = 1,
                .source_group_id = 101,
                .destination_group_id = 102,
                .phase = .prepare,
                .split_key = "m",
                .source_range_end = "z",
                .table_contract = test_transition_table_contract,
            },
        },
    });
    defer std.testing.allocator.free(split_command);
    const source_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = retained_command },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = table_command },
        .{ .term = 1, .index = 3, .entry_type = .normal, .data = source_range_command },
        .{ .term = 1, .index = 4, .entry_type = .normal, .data = split_command },
    });
    defer std.testing.allocator.free(source_entries);

    var source = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = source_root });
    defer source.deinit();
    try source.snapshotBuilder().applyBatch(.{
        .group_id = group_id,
        .commit_index = 4,
        .entries_bytes = source_entries,
    });
    var prepared = (try source.snapshotBuilder().prepareSnapshot(group_id, 4)) orelse return error.MissingMetadataSnapshotSource;
    defer prepared.deinit();
    var materialized = try prepared.materialize(std.testing.allocator);
    defer materialized.deinit(std.testing.allocator);
    const snapshot = switch (materialized) {
        .bytes => |bytes| bytes,
        .artifact => return error.UnexpectedMetadataSnapshotArtifact,
    };
    const rebuilt_snapshot = try source.snapshotBuilder().buildSnapshot(std.testing.allocator, group_id);
    defer std.testing.allocator.free(rebuilt_snapshot);
    try std.testing.expectEqualSlices(u8, rebuilt_snapshot, snapshot);

    var target = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = target_root });
    defer target.deinit();
    const stale_command = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_restore_job = .{ .key = stale_key, .value = "stale" },
    });
    defer std.testing.allocator.free(stale_command);
    const stale_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = stale_command },
    });
    defer std.testing.allocator.free(stale_entries);
    try target.snapshotBuilder().applyBatch(.{ .group_id = group_id, .commit_index = 1, .entries_bytes = stale_entries });

    const other_group_command = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_restore_job = .{ .key = other_group_key, .value = "other-group" },
    });
    defer std.testing.allocator.free(other_group_command);
    const other_group_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = other_group_command },
    });
    defer std.testing.allocator.free(other_group_entries);
    try target.snapshotBuilder().applyBatch(.{ .group_id = other_group_id, .commit_index = 1, .entries_bytes = other_group_entries });

    try std.testing.expect(try target.snapshotBuilder().installSnapshot(std.testing.allocator, group_id, 4, snapshot));
    const retained = (try target.getRestoreJobValue(std.testing.allocator, group_id, retained_key)).?;
    defer std.testing.allocator.free(retained);
    try std.testing.expectEqualStrings("retained", retained);
    try std.testing.expect((try target.getRestoreJobValue(std.testing.allocator, group_id, stale_key)) == null);
    const other = (try target.getRestoreJobValue(std.testing.allocator, other_group_id, other_group_key)).?;
    defer std.testing.allocator.free(other);
    try std.testing.expectEqualStrings("other-group", other);
    const splits = try target.listSplitTransitions(std.testing.allocator, group_id);
    defer target.freeSplitTransitions(std.testing.allocator, splits);
    try std.testing.expectEqual(@as(usize, 1), splits.len);
    try std.testing.expectEqual(@as(u64, 71), splits[0].transition_id);
    const batch = (try target.latestCheckpoint(group_id)).?;
    try std.testing.expectEqualDeep(AppliedMetadataCheckpoint.fromInput(4, .snapshot, snapshot), batch);
    const installed_snapshot = try target.snapshotBuilder().buildSnapshot(std.testing.allocator, group_id);
    defer std.testing.allocator.free(installed_snapshot);
    try std.testing.expectEqualSlices(u8, snapshot, installed_snapshot);
}

pub const RaftApplyStoreConfig = struct {
    /// Borrowed durable system keyspace; must outlive this authority.
    borrowed_store: ?*@import("antfly_local_sources").storage_backend_erased.Store = null,
    root_dir: []const u8,
    map_size: usize = 16 * 1024 * 1024,
    no_sync: bool = false,
    read_only: bool = false,
    // Metadata apply traffic is many tiny durable WAL-backed writes. Flushing
    // every commit amplifies manifest churn and makes simulation/runtime costs
    // pathological without improving durability.
    flush_threshold: usize = 64,
    /// Retained immutable metadata blocks/indexes. Zero disables caching;
    /// active snapshot leases can temporarily exceed the retention budget.
    block_cache_bytes: usize = 64 * 1024 * 1024,
};

pub const ProjectionSignalKind = apply_contract.ProjectionSignalKind;
pub const ProjectionSignal = apply_contract.ProjectionSignal;
pub const ProjectionListener = apply_contract.ProjectionListener;
pub const CommittedKeySignal = apply_contract.CommittedKeySignal;
pub const CommittedKeyListener = apply_contract.CommittedKeyListener;

/// Stable ownership token for one atomically registered projection/key
/// listener pair. The token is process-local and deliberately opaque to
/// callers; teardown uses it to detach exactly the pair it owns while the
/// apply store is still alive.
pub const LifecycleListenerRegistration = @import("raft_apply_contract.zig").LifecycleListenerRegistration;

const RegisteredProjectionListener = struct {
    registration_id: ?u64 = null,
    listener: ProjectionListener,
};

const RegisteredCommittedKeyListener = struct {
    registration_id: ?u64 = null,
    listener: CommittedKeyListener,
};

const TestLifecycleDetachLockBarrier = struct {
    entered: *std.Io.Event,
    resume_event: *std.Io.Event,
    contended: *std.atomic.Value(bool),
};

var test_lifecycle_detach_lock_barrier: ?TestLifecycleDetachLockBarrier = null;

fn lockLifecycleDetachApplyMutex(mutex: *std.Io.Mutex, io: std.Io) void {
    if (comptime builtin.is_test) {
        if (test_lifecycle_detach_lock_barrier) |barrier| {
            const acquired = mutex.tryLock();
            barrier.contended.store(!acquired, .release);
            barrier.entered.set(std.Options.debug_io);
            barrier.resume_event.waitUncancelable(std.Options.debug_io);
            if (acquired) return;
        }
    }
    mutex.lockUncancelable(io);
}

pub const CommittedTransitionDelta = union(enum) {
    upsert_split: metadata.SplitTransitionRecord,
    remove_split: u64,
    upsert_merge: metadata.MergeTransitionRecord,
    remove_merge: u64,
};

const OwnedProjectionSignal = struct {
    signal: ProjectionSignal,
    table_name: ?[]u8 = null,
    store_group_ids: ?[]u64 = null,

    pub fn deinit(self: *OwnedProjectionSignal, alloc: std.mem.Allocator) void {
        if (self.table_name) |name| alloc.free(name);
        if (self.store_group_ids) |ids| alloc.free(ids);
        self.* = undefined;
    }
};

const OwnedCommittedKeySignal = struct {
    metadata_group_id: u64,
    key: []u8,

    pub fn deinit(self: *OwnedCommittedKeySignal, alloc: std.mem.Allocator) void {
        alloc.free(self.key);
        self.* = undefined;
    }
};

pub const CommittedApplyOutcome = struct {
    alloc: std.mem.Allocator,
    native_owner_proof: ?standalone_native_owner.Binding = null,
    collect_transition_deltas: bool = true,
    projection_signals: std.ArrayListUnmanaged(OwnedProjectionSignal) = .empty,
    projection_kinds: std.EnumSet(ProjectionSignalKind) = std.EnumSet(ProjectionSignalKind).empty,
    committed_keys: std.ArrayListUnmanaged(OwnedCommittedKeySignal) = .empty,
    transition_deltas: std.ArrayListUnmanaged(CommittedTransitionDelta) = .empty,
    failure: ?anyerror = null,

    const CommandCheckpoint = struct {
        projections: usize,
        keys: usize,
        transitions: usize,
        kinds: std.EnumSet(ProjectionSignalKind),
        failure: ?anyerror,
    };
    fn checkpointCommand(self: *const CommittedApplyOutcome) CommandCheckpoint {
        return .{ .projections = self.projection_signals.items.len, .keys = self.committed_keys.items.len, .transitions = self.transition_deltas.items.len, .kinds = self.projection_kinds, .failure = self.failure };
    }
    /// Pair with storage-command rollback before committing the enclosing
    /// Raft batch. Rejected commands must not notify readers or advance live
    /// topology projections merely because earlier commands are committed.
    fn rollbackCommand(self: *CommittedApplyOutcome, checkpoint: CommandCheckpoint) void {
        std.debug.assert(checkpoint.projections <= self.projection_signals.items.len and checkpoint.keys <= self.committed_keys.items.len and checkpoint.transitions <= self.transition_deltas.items.len);
        for (self.projection_signals.items[checkpoint.projections..]) |*signal| signal.deinit(self.alloc);
        self.projection_signals.shrinkRetainingCapacity(checkpoint.projections);
        for (self.committed_keys.items[checkpoint.keys..]) |*signal| signal.deinit(self.alloc);
        self.committed_keys.shrinkRetainingCapacity(checkpoint.keys);
        for (self.transition_deltas.items[checkpoint.transitions..]) |*delta| deinitCommittedTransitionDelta(self.alloc, delta);
        self.transition_deltas.shrinkRetainingCapacity(checkpoint.transitions);
        self.projection_kinds = checkpoint.kinds;
        self.failure = checkpoint.failure;
    }

    pub fn deinit(self: *CommittedApplyOutcome) void {
        for (self.projection_signals.items) |*signal| signal.deinit(self.alloc);
        self.projection_signals.deinit(self.alloc);
        for (self.committed_keys.items) |*signal| signal.deinit(self.alloc);
        self.committed_keys.deinit(self.alloc);
        for (self.transition_deltas.items) |*delta| deinitCommittedTransitionDelta(self.alloc, delta);
        self.transition_deltas.deinit(self.alloc);
        self.* = undefined;
    }

    fn appendProjection(self: *CommittedApplyOutcome, signal: ProjectionSignal) !void {
        const table_name = if (signal.table_name) |name| try self.alloc.dupe(u8, name) else null;
        errdefer if (table_name) |name| self.alloc.free(name);
        const ids = if (signal.store_group_ids) |groups| try self.alloc.dupe(u64, groups) else null;
        errdefer if (ids) |groups| self.alloc.free(groups);
        var owned_signal = signal;
        owned_signal.table_name = table_name;
        owned_signal.store_group_ids = ids;
        try self.projection_signals.append(self.alloc, .{
            .signal = owned_signal,
            .table_name = table_name,
            .store_group_ids = ids,
        });
        self.projection_kinds.insert(signal.kind);
    }

    fn appendCommittedKey(self: *CommittedApplyOutcome, signal: CommittedKeySignal) !void {
        const key = try self.alloc.dupe(u8, signal.key);
        errdefer self.alloc.free(key);
        try self.committed_keys.append(self.alloc, .{
            .metadata_group_id = signal.metadata_group_id,
            .key = key,
        });
    }

    fn appendTransition(self: *CommittedApplyOutcome, delta: CommittedTransitionDelta) !void {
        const owned = try cloneCommittedTransitionDelta(self.alloc, delta);
        errdefer {
            var doomed = owned;
            deinitCommittedTransitionDelta(self.alloc, &doomed);
        }
        try self.transition_deltas.append(self.alloc, owned);
    }

    fn recordFailure(self: *CommittedApplyOutcome, err: anyerror) void {
        if (self.failure == null) self.failure = err;
    }
};

fn cloneCommittedTransitionDelta(alloc: std.mem.Allocator, delta: CommittedTransitionDelta) !CommittedTransitionDelta {
    return switch (delta) {
        .upsert_split => |record| .{ .upsert_split = try cloneCommittedSplitTransition(alloc, record) },
        .remove_split => |transition_id| .{ .remove_split = transition_id },
        .upsert_merge => |record| .{ .upsert_merge = try cloneCommittedMergeTransition(alloc, record) },
        .remove_merge => |transition_id| .{ .remove_merge = transition_id },
    };
}

fn cloneCommittedSplitTransition(alloc: std.mem.Allocator, record: metadata.SplitTransitionRecord) !metadata.SplitTransitionRecord {
    const table_contract = try record.table_contract.clone(alloc);
    var owned = record;
    owned.split_key = null;
    owned.source_range_end = null;
    owned.rollback_reason = null;
    owned.table_contract = table_contract;
    errdefer metadata_table_manager.freeSplitTransitionRecord(alloc, owned);
    if (record.split_key) |value| owned.split_key = try alloc.dupe(u8, value);
    if (record.source_range_end) |value| owned.source_range_end = try alloc.dupe(u8, value);
    if (record.rollback_reason) |value| owned.rollback_reason = try alloc.dupe(u8, value);
    return owned;
}

fn cloneCommittedMergeTransition(alloc: std.mem.Allocator, record: metadata.MergeTransitionRecord) !metadata.MergeTransitionRecord {
    const table_contract = try record.table_contract.clone(alloc);
    var owned = record;
    owned.rollback_reason = null;
    owned.table_contract = table_contract;
    errdefer metadata_table_manager.freeMergeTransitionRecord(alloc, owned);
    if (record.rollback_reason) |value| owned.rollback_reason = try alloc.dupe(u8, value);
    return owned;
}

fn deinitCommittedTransitionDelta(alloc: std.mem.Allocator, delta: *CommittedTransitionDelta) void {
    switch (delta.*) {
        .upsert_split => |record| metadata_table_manager.freeSplitTransitionRecord(alloc, record),
        .upsert_merge => |record| metadata_table_manager.freeMergeTransitionRecord(alloc, record),
        .remove_split, .remove_merge => {},
    }
    delta.* = undefined;
}

test "standalone metadata released JSON replay is atomic exact and checkpoint durable" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    const root = try std.fmt.allocPrint(scratch, ".zig-cache/tmp/{s}/legacy-replay", .{tmp.sub_path});
    const restored_root = try std.fmt.allocPrint(scratch, "{s}-restored", .{root});
    const checkpoint = try std.fmt.allocPrint(scratch, "{s}.checkpoint", .{root});
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "legacy", .storage = .{ .dense_embeddings = .vector_store }, .storage_migration = .{ .request = .{ .job_id = "vectors", .mode = .online } } };
    const ranges = [_]metadata.RangeRecord{.{ .table_id = 7, .group_id = 17, .range_id = 19, .start_key = "" }};
    const payload = try std.json.Stringify.valueAlloc(scratch, RaftApplyStore.LegacyCatalogCreate{ .table = table, .ranges = &ranges }, .{});
    var record: @import("antfly_local_sources").storage_db_replication_record.Record = .{ .kind = .metadata_mutation, .payload_codec = .json, .cluster_id = 7, .timeline_id = 1, .epoch = 1, .lsn = 5, .previous_lsn = 4, .payload = payload };
    const group = group_ids.main_metadata_group_id;
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        try store.applyHotStandbyRecord(record);
        const revision = try store.standaloneRevision();
        try std.testing.expectEqual(@as(u64, 1), revision);
        try store.applyHotStandbyRecord(record);
        try std.testing.expectEqual(revision, try store.standaloneRevision());
        const tables = try store.listTables(alloc, group);
        defer store.freeTables(alloc, tables);
        try std.testing.expectEqual(@as(usize, 1), tables.len);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, tables[0]));
        const owned_ranges = try store.listRanges(alloc, group);
        defer store.freeRanges(alloc, owned_ranges);
        try std.testing.expectEqual(@as(usize, 1), owned_ranges.len);
        try std.testing.expect(metadata_table_manager.rangeRecordsEqual(ranges[0], owned_ranges[0]));
        const auxiliary = (try store.loadStandaloneCatalog(alloc)).?;
        defer alloc.free(auxiliary);
        try std.testing.expectEqualStrings("{\"epoch\":1,\"tables\":[],\"ranges\":[]}", auxiliary);
        var altered_table = table;
        altered_table.description = "conflicting";
        record.payload = try std.json.Stringify.valueAlloc(scratch, RaftApplyStore.LegacyCatalogCreate{ .table = altered_table, .ranges = &ranges }, .{});
        try std.testing.expectError(error.MetadataHASourceChanged, store.applyHotStandbyRecord(record));
        record.lsn = 9;
        record.previous_lsn = 8;
        try std.testing.expectError(error.TableLifecycleConflict, store.applyHotStandbyRecord(record));
        try std.testing.expectEqual(revision, try store.standaloneRevision());
        record.payload = payload;
        record.cluster_id = 8;
        try std.testing.expectError(error.MetadataHASourceChanged, store.applyHotStandbyRecord(record));
        record.cluster_id = 7;
        record.timeline_id = 2;
        try std.testing.expectError(error.MetadataHASourceChanged, store.applyHotStandbyRecord(record));
        record.timeline_id = 1;
        // Metadata effects may have document WAL entries between them.
        try store.applyHotStandbyRecord(record);
        try std.testing.expectEqual(revision + 1, try store.standaloneRevision());
    }
    var reopened = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer reopened.deinit();
    const artifact = try reopened.exportHotStandbyCheckpoint(std.testing.io, checkpoint);
    var restored = try RaftApplyStore.init(alloc, .{ .root_dir = restored_root });
    defer restored.deinit();
    try restored.importHotStandbyCheckpoint(std.testing.io, checkpoint, artifact.size_bytes);
    try restored.applyHotStandbyRecord(record);
    try std.testing.expectEqual(@as(u64, 2), try restored.standaloneRevision());
    const receipt = try restored.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key);
    defer alloc.free(receipt);
    try std.testing.expectEqual(@as(u64, 9), std.mem.readInt(u64, receipt[24..32], .little));
    const tables = try restored.listTables(alloc, group);
    defer restored.freeTables(alloc, tables);
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, tables[0]));
}

test "standalone metadata released JSON replay verifies imported ranges and preserves auxiliary state" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/legacy-import", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group = group_ids.main_metadata_group_id;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "legacy" };
    const ranges = [_]metadata.RangeRecord{.{ .table_id = 7, .group_id = 17, .range_id = 19, .start_key = "" }};
    const auxiliary = "{\"epoch\":42,\"extension_packages\":[{\"name\":\"preserved\"}]}";
    try store.replaceStandaloneCatalog(group, 0, &.{table}, &ranges, auxiliary);
    var wrong_ranges = ranges;
    wrong_ranges[0].range_id += 1;
    const invalid_payload = try std.json.Stringify.valueAlloc(alloc, RaftApplyStore.LegacyCatalogCreate{ .table = table, .ranges = &wrong_ranges }, .{});
    defer alloc.free(invalid_payload);
    var record: @import("antfly_local_sources").storage_db_replication_record.Record = .{ .kind = .metadata_mutation, .payload_codec = .json, .cluster_id = 7, .timeline_id = 1, .epoch = 1, .lsn = 1, .previous_lsn = 0, .payload = invalid_payload };
    try std.testing.expectError(error.TableLifecycleConflict, store.applyHotStandbyRecord(record));
    try std.testing.expectError(error.NotFound, store.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key));
    try std.testing.expectEqual(@as(u64, 1), try store.standaloneRevision());
    const payload = try std.json.Stringify.valueAlloc(alloc, RaftApplyStore.LegacyCatalogCreate{ .table = table, .ranges = &ranges }, .{});
    defer alloc.free(payload);
    record.payload = payload;
    try store.applyHotStandbyRecord(record);
    const loaded = (try store.loadStandaloneCatalog(alloc)).?;
    defer alloc.free(loaded);
    try std.testing.expectEqualStrings(auxiliary, loaded);
    try std.testing.expectEqual(@as(u64, 2), try store.standaloneRevision());
    // A binary producer identity forbids later legacy effects. Covered JSON
    // records remain harmless even when the table has since changed.
    var txn = try store.store.beginWriteTxn();
    try txn.put(RaftApplyStore.metadata_hot_standby.source_key, &(@as([16]u8, @splat(1))));
    try txn.commit();
    try store.applyHotStandbyRecord(record);
    record.lsn = 2;
    record.previous_lsn = 1;
    try std.testing.expectError(error.MetadataHASourceChanged, store.applyHotStandbyRecord(record));
    try std.testing.expectEqual(@as(u64, 2), try store.standaloneRevision());
}

test "system catalog standalone rejected constraint drop preserves bindings ranges and revisions" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/guarded-drop", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const group = group_ids.main_metadata_group_id;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "table:parent", .schema_json =
        \\{"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
    };
    const range: metadata.RangeRecord = .{ .table_id = 7, .group_id = 17, .range_id = 17, .start_key = "" };
    const binding: system_catalog.Resource = .{ .kind = .table, .id = 7, .parent_id = system_catalog.default_namespace_id, .name = "parent", .storage_name = table.name };
    try store.updateStandaloneCatalog(group, 0, .{
        .tables = &.{table},
        .ranges = &.{range},
        .auxiliary_json = "{}",
        .import_catalog = .{ .revision = 1, .next_id = 8, .resources = &.{binding} },
    });
    const revision = try store.standaloneRevision();
    const before = (try store.loadStandaloneCatalogSnapshot(alloc)).?;
    defer alloc.free(before);
    // Logical unbind and range removals are staged first, but a rejected drop
    // must abort all of them, leave revisions untouched, and retain its cause.
    try std.testing.expectError(error.ConstraintRetirementRequired, store.updateStandaloneCatalog(group, revision, .{
        .remove_tables = &.{table.table_id},
        .remove_ranges = &.{range.group_id},
        .logical = .{ .previous_revision = 1, .delta = .{ .removes = @constCast(&[_]system_catalog.Resource{binding}), .upserts = &.{}, .next_id = 8 } },
    }));
    try std.testing.expectEqual(revision, try store.standaloneRevision());
    const after = (try store.loadStandaloneCatalogSnapshot(alloc)).?;
    defer alloc.free(after);
    try std.testing.expectEqualStrings(before, after);
    try std.testing.expectError(error.ConstraintRetirementRequired, store.replaceStandaloneCatalog(group, revision, &.{}, &.{}, "{}"));
    try std.testing.expectEqual(revision, try store.standaloneRevision());
    // Raft's rejected command is a committed no-op, not a partial unbind.
    try store.applyStandaloneCommand(group, .{ .remove_table = .{ .table_id = table.table_id, .expected_transition_generation = 0 } });
    var catalog = try store.systemCatalogSnapshot(alloc, group);
    defer catalog.deinit();
    try std.testing.expectEqual(@as(u64, 1), catalog.value.revision);
    try std.testing.expectEqualStrings(table.name, catalog.value.byId(.table, table.table_id).?.storage_name);
    const tables = try store.listTables(alloc, group);
    defer store.freeTables(alloc, tables);
    try std.testing.expectEqual(@as(usize, 1), tables.len);
}

test "standalone metadata migration and listeners are failure atomic" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/metadata-atomic", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const Observer = struct {
        store: *RaftApplyStore,
        calls: usize = 0,
        saw_uncommitted: bool = false,
        fn matches(_: *anyopaque, _: CommittedKeySignal) bool {
            return true;
        }
        fn notify(ptr: *anyopaque, signal: CommittedKeySignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const value = self.store.store.get(std.testing.allocator, signal.key) catch {
                self.saw_uncommitted = true;
                return;
            };
            std.testing.allocator.free(value);
            self.calls += 1;
        }
    };
    var observer = Observer{ .store = &store };
    try store.addCommittedKeyListener(.{ .ptr = &observer, .vtable = &.{ .matches_key = Observer.matches, .on_committed_key = Observer.notify } });
    const group = group_ids.main_metadata_group_id;
    const key = "\x00\x00__api_restore_jobs__:0000000000000001";
    try store.applyStandaloneCommand(group, .{ .upsert_restore_job = .{ .key = key, .value = "queued" } });
    try std.testing.expectEqual(@as(usize, 1), observer.calls);
    try std.testing.expect(!observer.saw_uncommitted);
    const other = "\x00\x00__api_restore_jobs__:0000000000000002";
    try std.testing.expectError(error.RestoreJobMigrationConflict, store.migrateStandaloneRestoreJobs(&.{
        .{ .key = @constCast(other), .value = @constCast("new") },
        .{ .key = @constCast(key), .value = @constCast("different") },
    }));
    try std.testing.expectEqual(@as(usize, 1), observer.calls);
    try std.testing.expect((try store.getRestoreJobValue(alloc, group, other)) == null);
    try store.migrateStandaloneRestoreJobs(&.{.{ .key = @constCast(other), .value = @constCast("new") }});
    try std.testing.expectEqual(@as(usize, 2), observer.calls);
    try std.testing.expect(!observer.saw_uncommitted);
}

test "standalone metadata HA preserves incremental jobs outbox recovery and full checkpoint authority" {
    const alloc = std.testing.allocator;
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    const root = try std.fmt.allocPrint(scratch, ".zig-cache/tmp/{s}/metadata-ha", .{tmp.sub_path});
    try fs_paths.createDirPathPortable(io, root);
    const source_root = try std.fs.path.join(scratch, &.{ root, "source" });
    const target_root = try std.fs.path.join(scratch, &.{ root, "target" });
    const restored_root = try std.fs.path.join(scratch, &.{ root, "restored" });
    const checkpoint = try std.fs.path.join(scratch, &.{ root, "checkpoint.bin" });
    const log_path = try std.fmt.allocPrintSentinel(scratch, "{s}/ha.log", .{root}, 0);
    const slots_path = try std.fmt.allocPrintSentinel(scratch, "{s}/slots", .{root}, 0);
    const primary_mod = @import("../../storage/hot_standby/primary.zig");
    var primary = try primary_mod.Primary.open(alloc, log_path.ptr, slots_path.ptr, .{ .cluster_id = 7, .shard_id = 0, .table_id = 0, .timeline_id = 1, .epoch = 1 }, .{});
    defer primary.close();
    var target = try RaftApplyStore.init(alloc, .{ .root_dir = target_root });
    defer target.deinit();
    const logical_key = "\x00\x00__api_restore_jobs__:000000000000002a";
    const queued = "{\"job_id\":42,\"phase\":\"queued\"}";
    const importing = "{\"job_id\":42,\"phase\":\"importing\"}";
    const complete = "{\"job_id\":42,\"phase\":\"complete\"}";
    const group = group_ids.main_metadata_group_id;
    {
        var source = try RaftApplyStore.init(alloc, .{ .root_dir = source_root });
        defer source.deinit();
        try source.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&primary) }, hot_standby_publisher_adapter.bindMirror(&primary, .{}));
        try source.applyStandaloneCommand(group, .{ .upsert_restore_job = .{ .key = logical_key, .value = queued } });
        var first = (try primary.log.entryAt(alloc, 1)).?;
        defer first.deinit(alloc);
        try std.testing.expect(first.record.payload.len < 4096);
        try target.applyHotStandbyRecord(first.record);
        try target.applyHotStandbyRecord(first.record);
        const actual = (try target.getRestoreJobValue(alloc, group, logical_key)).?;
        defer alloc.free(actual);
        try std.testing.expectEqualStrings(queued, actual);
        const Failure = struct {
            fn wait(_: *anyopaque, _: *anyopaque, _: u64, _: primary_mod.SyncPolicy) !void {
                return error.InjectedAfterMetadataHAAppend;
            }
        };
        var context: u8 = 0;
        try source.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&primary) }, hot_standby_publisher_adapter.bindMirror(&primary, .{ .sync_policy = .{ .mode = .remote_apply }, .sync_wait_ctx = &context, .sync_wait_fn = Failure.wait }));
        try std.testing.expectError(error.InjectedAfterMetadataHAAppend, source.applyStandaloneCommand(group, .{ .upsert_restore_job = .{ .key = logical_key, .value = importing } }));
        try std.testing.expectEqual(@as(u64, 2), primary.lastLsn());
        try std.testing.expectError(error.MetadataHAOutboxPending, source.exportHotStandbyCheckpoint(io, checkpoint));
    }
    {
        var source = try RaftApplyStore.init(alloc, .{ .root_dir = source_root });
        defer source.deinit();
        try source.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&primary) }, hot_standby_publisher_adapter.bindMirror(&primary, .{}));
        try source.flushHotStandbyOutbox();
        try std.testing.expectEqual(@as(u64, 2), primary.lastLsn());
        try source.store.put("\x00\x00__metadata__:private_fixture", "private-reservation-proof");
        const artifact = try source.exportHotStandbyCheckpoint(io, checkpoint);
        var restored = try RaftApplyStore.init(alloc, .{ .root_dir = restored_root });
        defer restored.deinit();
        try restored.importHotStandbyCheckpoint(io, checkpoint, artifact.size_bytes);
        const private = try restored.store.get(alloc, "\x00\x00__metadata__:private_fixture");
        defer alloc.free(private);
        try std.testing.expectEqualStrings("private-reservation-proof", private);
        const actual = (try restored.getRestoreJobValue(alloc, group, logical_key)).?;
        defer alloc.free(actual);
        try std.testing.expectEqualStrings(importing, actual);
        var second = (try primary.log.entryAt(alloc, 2)).?;
        defer second.deinit(alloc);
        try restored.applyHotStandbyRecord(second.record);
        try std.testing.expectError(error.MetadataHACheckpointTargetNotEmpty, restored.importHotStandbyCheckpoint(io, checkpoint, artifact.size_bytes));
        try source.applyStandaloneCommand(group, .{ .upsert_restore_job = .{ .key = logical_key, .value = complete } });
        var third = (try primary.log.entryAt(alloc, 3)).?;
        defer third.deinit(alloc);
        try std.testing.expectError(error.MetadataHASequenceGap, target.applyHotStandbyRecord(third.record));
        try restored.applyHotStandbyRecord(third.record);
        try restored.applyHotStandbyRecord(second.record);
        const receipt = try restored.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key);
        defer alloc.free(receipt);
        try std.testing.expectEqual(third.record.lsn, std.mem.readInt(u64, receipt[24..32], .little));
        const done = (try restored.getRestoreJobValue(alloc, group, logical_key)).?;
        defer alloc.free(done);
        try std.testing.expectEqualStrings(complete, done);
        var corrupted = third.record;
        const bad = try scratch.dupe(u8, third.record.payload);
        bad[bad.len - 1] ^= 1;
        corrupted.payload = bad;
        try std.testing.expectError(error.InvalidMetadataHAEffectChunk, restored.applyHotStandbyRecord(corrupted));
    }
}

test "standalone metadata chunked HA resumes large effects through checkpoint without partial visibility" {
    const alloc = std.testing.allocator;
    const io = std.testing.io;
    const chunks = @import("../../storage/hot_standby/metadata_effect_chunks.zig");
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    const root = try std.fmt.allocPrint(scratch, ".zig-cache/tmp/{s}/metadata-chunks", .{tmp.sub_path});
    try fs_paths.createDirPathPortable(io, root);
    const source_root = try std.fs.path.join(scratch, &.{ root, "source" });
    const target_root = try std.fs.path.join(scratch, &.{ root, "target" });
    const restored_root = try std.fs.path.join(scratch, &.{ root, "restored" });
    const corrupt_root = try std.fs.path.join(scratch, &.{ root, "corrupt" });
    const checkpoint = try std.fs.path.join(scratch, &.{ root, "checkpoint.bin" });
    const log_path = try std.fmt.allocPrintSentinel(scratch, "{s}/ha.log", .{root}, 0);
    const slots_path = try std.fmt.allocPrintSentinel(scratch, "{s}/slots", .{root}, 0);
    const primary_mod = @import("../../storage/hot_standby/primary.zig");
    var primary = try primary_mod.Primary.open(alloc, log_path.ptr, slots_path.ptr, .{ .cluster_id = 7, .shard_id = 0, .table_id = 0, .timeline_id = 1, .epoch = 1 }, .{});
    defer primary.close();
    const key = "\x00\x00__api_restore_jobs__:0000000000000009";
    const value = try alloc.alloc(u8, 9 * 1024 * 1024);
    defer alloc.free(value);
    @memset(value, 'q');
    @memcpy(value[0..12], "{\"padding\":\"");
    @memcpy(value[value.len - 2 ..], "\"}");
    const group = group_ids.main_metadata_group_id;
    {
        var source = try RaftApplyStore.init(alloc, .{ .root_dir = source_root });
        defer source.deinit();
        const Failure = struct {
            fn wait(_: *anyopaque, _: *anyopaque, _: u64, _: primary_mod.SyncPolicy) !void {
                return error.InjectedAfterMetadataHAAppend;
            }
        };
        var context: u8 = 0;
        try source.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&primary) }, hot_standby_publisher_adapter.bindMirror(&primary, .{ .sync_policy = .{ .mode = .remote_apply }, .sync_wait_ctx = &context, .sync_wait_fn = Failure.wait }));
        try std.testing.expectError(error.MetadataReplicationPending, source.replaceStandaloneCatalog(group, 0, &.{}, &.{}, value));
    }
    const final_lsn = primary.lastLsn();
    try std.testing.expect(final_lsn > 8);
    {
        var source = try RaftApplyStore.init(alloc, .{ .root_dir = source_root });
        defer source.deinit();
        try source.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&primary) }, hot_standby_publisher_adapter.bindMirror(&primary, .{}));
        try source.flushHotStandbyOutbox();
        try std.testing.expectEqual(final_lsn, primary.lastLsn());
    }
    var checkpoint_size: u64 = 0;
    {
        var target = try RaftApplyStore.init(alloc, .{ .root_dir = target_root });
        defer target.deinit();
        var lsn: u64 = 1;
        while (lsn <= 3) : (lsn += 1) {
            var entry = (try primary.log.entryAt(alloc, lsn)).?;
            defer entry.deinit(alloc);
            try std.testing.expect(entry.record.payload.len + @import("antfly_local_sources").storage_db_replication_record.header_size <= 1024 * 1024);
            try target.applyHotStandbyRecord(entry.record);
            try target.applyHotStandbyRecord(entry.record);
            try std.testing.expect((try target.loadStandaloneCatalog(alloc)) == null);
            try std.testing.expectError(error.NotFound, target.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key));
        }
        var skipped = (try primary.log.entryAt(alloc, 5)).?;
        defer skipped.deinit(alloc);
        try std.testing.expectError(error.MetadataHAChunkSequenceGap, target.applyHotStandbyRecord(skipped.record));
        var first = (try primary.log.entryAt(alloc, 1)).?;
        defer first.deinit(alloc);
        const decoded = try chunks.decodeFrame(first.record.payload);
        var foreign = decoded.descriptor;
        foreign.source[0] ^= 1;
        const forged = try chunks.encodeFrame(alloc, foreign, 0, decoded.payload);
        defer alloc.free(forged);
        var foreign_record = first.record;
        foreign_record.payload = forged;
        try std.testing.expectError(error.MetadataHASourceChanged, target.applyHotStandbyRecord(foreign_record));
        const artifact = try target.exportHotStandbyCheckpoint(io, checkpoint);
        checkpoint_size = artifact.size_bytes;
    }
    {
        var target = try RaftApplyStore.init(alloc, .{ .root_dir = corrupt_root });
        defer target.deinit();
        try target.importHotStandbyCheckpoint(io, checkpoint, checkpoint_size);
        var fourth = (try primary.log.entryAt(alloc, 4)).?;
        defer fourth.deinit(alloc);
        const decoded = try chunks.decodeFrame(fourth.record.payload);
        const bad_payload = try alloc.dupe(u8, decoded.payload);
        defer alloc.free(bad_payload);
        bad_payload[100] ^= 1;
        const forged = try chunks.encodeFrame(alloc, decoded.descriptor, decoded.index, bad_payload);
        defer alloc.free(forged);
        var bad_record = fourth.record;
        bad_record.payload = forged;
        var resumed = false;
        var deferred: u32 = 0;
        for (0..16) |_| {
            target.applyHotStandbyRecord(bad_record) catch |err| {
                if (err != error.CatalogPublicationProofPending) return err;
                deferred += 1;
                // Reconstruct exactly one immutable prefix frame per retry.
                // Preparation neither extends staging nor exposes any row.
                try std.testing.expectEqual(deferred, target.standby_probe.?.next_frame);
                const raw = try target.store.get(alloc, RaftApplyStore.metadata_pending_key);
                defer alloc.free(raw);
                try std.testing.expectEqual(@as(u32, 3), (try RaftApplyStore.MetadataPending.decode(raw)).next);
                try std.testing.expect((try target.loadStandaloneCatalog(alloc)) == null);
                try std.testing.expectError(error.NotFound, target.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key));
                continue;
            };
            resumed = true;
            break;
        }
        try std.testing.expect(resumed);
        try std.testing.expectEqual(@as(u32, 3), deferred);
        var lsn: u64 = 5;
        while (lsn <= final_lsn) : (lsn += 1) {
            var entry = (try primary.log.entryAt(alloc, lsn)).?;
            defer entry.deinit(alloc);
            if (lsn == final_lsn) try std.testing.expectError(error.InvalidMetadataHAEffect, target.applyHotStandbyRecord(entry.record)) else try target.applyHotStandbyRecord(entry.record);
        }
        try std.testing.expect((try target.loadStandaloneCatalog(alloc)) == null);
        try std.testing.expectError(error.NotFound, target.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key));
    }
    {
        var target = try RaftApplyStore.init(alloc, .{ .root_dir = restored_root });
        defer target.deinit();
        try target.importHotStandbyCheckpoint(io, checkpoint, checkpoint_size);
    }
    {
        var target = try RaftApplyStore.init(alloc, .{ .root_dir = restored_root });
        defer target.deinit();
        var lsn: u64 = 1;
        while (lsn <= final_lsn) : (lsn += 1) {
            var entry = (try primary.log.entryAt(alloc, lsn)).?;
            defer entry.deinit(alloc);
            try target.applyHotStandbyRecord(entry.record);
            if (lsn < final_lsn) try std.testing.expect((try target.loadStandaloneCatalog(alloc)) == null);
        }
        const actual = (try target.loadStandaloneCatalog(alloc)).?;
        defer alloc.free(actual);
        try std.testing.expectEqualSlices(u8, value, actual);
        try std.testing.expectError(error.NotFound, target.store.get(alloc, RaftApplyStore.metadata_pending_key));
        const receipt = try target.store.get(alloc, RaftApplyStore.metadata_hot_standby.replay_key);
        defer alloc.free(receipt);
        try std.testing.expectEqual(final_lsn, std.mem.readInt(u64, receipt[24..32], .little));
    }
    // A promoted primary may discard only an UNCOMMITTED incoming prefix.
    // Its new epoch preserves source identity but supersedes that sequence's
    // effect digest; another partial standby can follow the same decision.
    const promoted_root = try std.fs.path.join(scratch, &.{ root, "promoted" });
    const follower_root = try std.fs.path.join(scratch, &.{ root, "new-follower" });
    const promoted_log = try std.fmt.allocPrintSentinel(scratch, "{s}/promoted.log", .{root}, 0);
    const promoted_slots = try std.fmt.allocPrintSentinel(scratch, "{s}/promoted-slots", .{root}, 0);
    var new_primary = try primary_mod.Primary.open(alloc, promoted_log.ptr, promoted_slots.ptr, .{ .cluster_id = 7, .shard_id = 0, .table_id = 0, .timeline_id = 2, .epoch = 2 }, .{});
    defer new_primary.close();
    var promoted = try RaftApplyStore.init(alloc, .{ .root_dir = promoted_root });
    defer promoted.deinit();
    try promoted.importHotStandbyCheckpoint(io, checkpoint, checkpoint_size);
    try promoted.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&primary) }, hot_standby_publisher_adapter.bindMirror(&primary, .{}));
    try std.testing.expectError(error.MetadataHAIncompleteEffect, promoted.applyStandaloneCommand(group, .{ .upsert_restore_job = .{ .key = key, .value = "promoted" } }));
    try promoted.bindHotStandby(.{ .borrowed = hot_standby_write_gate_adapter.bindPrimary(&new_primary) }, hot_standby_publisher_adapter.bindMirror(&new_primary, .{}));
    try promoted.applyStandaloneCommand(group, .{ .upsert_restore_job = .{ .key = key, .value = "promoted" } });
    var follower = try RaftApplyStore.init(alloc, .{ .root_dir = follower_root });
    defer follower.deinit();
    try follower.importHotStandbyCheckpoint(io, checkpoint, checkpoint_size);
    var replacement = (try new_primary.log.entryAt(alloc, 1)).?;
    defer replacement.deinit(alloc);
    try follower.applyHotStandbyRecord(replacement.record);
    const replaced = (try follower.getRestoreJobValue(alloc, group, key)).?;
    defer alloc.free(replaced);
    try std.testing.expectEqualStrings("promoted", replaced);
    var late = (try primary.log.entryAt(alloc, final_lsn)).?;
    defer late.deinit(alloc);
    try std.testing.expectError(error.MetadataHASourceChanged, follower.applyHotStandbyRecord(late.record));
}

fn policyHasUnsupportedArtifactIndexes(alloc: std.mem.Allocator, indexes_json: []const u8) !bool {
    const parsed = std.json.parseFromSliceLeaky(std.json.Value, alloc, indexes_json, .{}) catch return error.InvalidCatalogRecord;
    if (parsed != .object) return error.InvalidCatalogRecord;
    var indexes = parsed.object.iterator();
    while (indexes.next()) |index| {
        const config = index.value_ptr.*;
        if (config != .object) return error.InvalidCatalogRecord;
        const kind = config.object.get("type") orelse return error.InvalidCatalogRecord;
        if (kind != .string) return error.InvalidCatalogRecord;
        // Relational secondary indexes recheck primary typed rows before
        // projection. Search modalities need owner-side candidate filtering.
        if (!std.mem.eql(u8, kind.string, "relational")) return true;
    }
    return false;
}

pub const RaftApplyStore = struct {
    // Counts visited index rows, including rows not ultimately deleted, so
    // regressions can assert that completion work is bounded by one range.
    restore_cleanup_rows_visited: if (builtin.is_test) usize else void = if (builtin.is_test) 0 else {},
    policy_full_owner_cut_validations: if (builtin.is_test) usize else void = if (builtin.is_test) 0 else {},
    alloc: std.mem.Allocator,
    io_impl: std.Io.Threaded,
    root_dir: []u8,
    path: []u8,
    backend: ?lsm_backend.BackendHandle,
    block_cache: ?*lsm_backend.Cache = null,
    resolver_projection_mutex: std.Io.Mutex = .init,
    resolver_projection_payloads: std.StringHashMapUnmanaged([]const u8) = .empty,
    resolver_projection_bytes: usize = 0,
    resolver_projection_exports: if (builtin.is_test) usize else void = if (builtin.is_test) 0 else {},
    store: docstore.DocStore,
    checkpoints: std.AutoHashMapUnmanaged(u64, AppliedMetadataCheckpoint) = .empty,
    projected_placement_intents: std.ArrayListUnmanaged(ProjectedPlacementIntent) = .empty,
    loaded_placement_groups: std.AutoHashMapUnmanaged(u64, void) = .empty,
    projection_listeners: std.ArrayListUnmanaged(RegisteredProjectionListener) = .empty,
    committed_key_listeners: std.ArrayListUnmanaged(RegisteredCommittedKeyListener) = .empty,
    next_lifecycle_listener_registration_id: u64 = 1,
    apply_mutex: std.Io.Mutex = .init,
    relation_publication_pool: RelationPublicationPool = .{},
    relation_tracking_mutex: std.Io.Mutex = .init,
    relation_tracking: std.AutoHashMapUnmanaged(u64, publication_fence.State) = .empty,
    relation_tracking_generation: u64 = 1,
    relation_tracking_enabled: bool = true,
    standby_probe_mutex: std.Io.Mutex = .init,
    standby_probe: ?StandbyRelationProbe = null,
    active_outcome: ?*CommittedApplyOutcome = null,
    // Protected by apply_mutex, like active_outcome. Standalone commands have
    // no Raft position; replicated rejection receipts bind the exact entry.
    active_resolver_apply_position: struct { term: u64 = 0, index: u64 = 0 } = .{},
    active_relation_page: ?*const relation_reconciliation.Page = null,
    active_relation_failure: ?*const relation_reconciliation.FailurePlan = null,
    active_relation_garbage: ?*const relation_reconciliation.GarbagePage = null,
    active_relation_publication: ?*const RelationPublicationProof = null,
    active_relation_initial_index: ?u64 = null,
    verified_catalog_groups: std.AutoHashMapUnmanaged(u64, void) = .empty,
    read_only: bool = false,
    hot_standby_gate: ?@import("antfly_local_sources").storage_db_replication_contract.WriteGate = null,
    hot_standby_mirror: ?@import("antfly_local_sources").storage_db_replication_contract.AsyncEffectMirror = null,
    hot_standby_port: ?@import("../../storage/metadata_hot_standby_port.zig").Port = null,

    const ProjectedPlacementIntent = struct {
        metadata_group_id: u64,
        intent: raft_reconciler.PlacementIntent,
    };

    pub fn init(alloc: std.mem.Allocator, cfg: RaftApplyStoreConfig) !RaftApplyStore {
        var io_impl = threaded_io_limits.initService(alloc);
        errdefer io_impl.deinit();

        const root_dir = try alloc.dupe(u8, cfg.root_dir);
        errdefer alloc.free(root_dir);
        if (!cfg.read_only and cfg.borrowed_store == null) try fs_paths.createDirPathPortable(io_impl.io(), root_dir);

        const path = try std.fmt.allocPrint(alloc, "{s}/metadata-apply-store", .{root_dir});
        errdefer alloc.free(path);
        if (!cfg.read_only and cfg.borrowed_store == null) try fs_paths.createDirPathPortable(io_impl.io(), path);

        const block_cache = if (cfg.block_cache_bytes == 0 or cfg.borrowed_store != null) null else blk: {
            const cache = try alloc.create(lsm_backend.Cache);
            cache.* = lsm_backend.Cache.init(alloc, cfg.block_cache_bytes);
            break :blk cache;
        };
        errdefer if (block_cache) |cache| {
            cache.deinit();
            alloc.destroy(cache);
        };
        var backend: ?lsm_backend.BackendHandle = if (cfg.borrowed_store == null) try lsm_backend.BackendHandle.open(alloc, path, .{
            .backend = .{
                .durability = if (cfg.no_sync) .none else .full,
                .read_only = cfg.read_only,
                .create_if_missing = !cfg.read_only,
            },
            .flush_threshold = cfg.flush_threshold,
            .cache = block_cache,
        }) else null;
        errdefer if (backend) |*owned| owned.close();
        var store = if (cfg.borrowed_store) |borrowed|
            try docstore.DocStore.openRuntime(alloc, borrowed)
        else blk: {
            var runtime_store = try backend.?.backend.runtimeStore(alloc, .{ .name = "metadata-apply" });
            errdefer runtime_store.deinit();
            break :blk try docstore.DocStore.openRuntime(alloc, runtime_store);
        };
        errdefer store.close();

        return .{
            .alloc = alloc,
            .io_impl = io_impl,
            .root_dir = root_dir,
            .read_only = cfg.read_only,
            .path = path,
            .backend = backend,
            .block_cache = block_cache,
            .store = store,
        };
    }

    pub fn deinit(self: *RaftApplyStore) void {
        self.relation_publication_pool.deinit(self.io_impl.io());
        self.relation_tracking.deinit(self.alloc);
        var projections = self.resolver_projection_payloads.iterator();
        while (projections.next()) |entry| {
            self.alloc.free(entry.key_ptr.*);
            self.alloc.free(entry.value_ptr.*);
        }
        self.resolver_projection_payloads.deinit(self.alloc);
        self.checkpoints.deinit(self.alloc);
        self.verified_catalog_groups.deinit(self.alloc);
        for (self.projected_placement_intents.items) |*entry| freePlacementIntent(self.alloc, entry.intent);
        self.projected_placement_intents.deinit(self.alloc);
        self.loaded_placement_groups.deinit(self.alloc);
        self.projection_listeners.deinit(self.alloc);
        self.committed_key_listeners.deinit(self.alloc);
        self.store.close();
        if (self.backend) |*backend| backend.close();
        if (self.block_cache) |cache| {
            cache.deinit();
            self.alloc.destroy(cache);
        }
        self.alloc.free(self.path);
        self.alloc.free(self.root_dir);
        self.io_impl.deinit();
        self.* = undefined;
    }

    const standalone_catalog_key = "\x00\x00__metadata__:standalone_catalog";
    const StandaloneCatalogAuxiliary = struct {
        extension_packages: []extension_domain.PackageManifest = &.{},
        installed_extensions: []extension_domain.InstalledExtension = &.{},
        extension_members: []extension_domain.ExtensionMember = &.{},
        extension_dependencies: []extension_domain.ExtensionDependency = &.{},
    };
    const standalone_revision_key = "\x00\x00__metadata__:standalone_revision";
    const standalone_projection_revision_key = "\x00\x00__metadata__:standalone_projection_revision";
    const metadata_hot_standby = @import("../../storage/hot_standby/metadata_effects.zig");
    const metadata_chunks = @import("../../storage/hot_standby/metadata_effect_chunks.zig");
    const StandbyRelationProbe = @import("../../storage/hot_standby/metadata_effect_probe.zig").PointProbe(2, 160, 2048);
    const StandbyRelationPublication = struct {
        proof: RelationPublicationProof,
        activation: topology_protocol.Activation,
    };
    const metadata_pending_key = metadata_hot_standby.prefix ++ "pending";
    const metadata_chunk_prefix = metadata_hot_standby.prefix ++ "chunk:";
    const legacy_catalog_digest_key = metadata_hot_standby.prefix ++ "legacy_catalog_digest";

    const MetadataPending = struct {
        descriptor: metadata_chunks.Descriptor,
        next: u32,
        cluster_id: u64,
        timeline_id: u64,
        epoch: u64,
        last_lsn: u64,

        fn encode(self: @This()) [144]u8 {
            var bytes: [144]u8 = undefined;
            @memcpy(bytes[0..16], &self.descriptor.source);
            std.mem.writeInt(u64, bytes[16..24], self.descriptor.sequence, .little);
            std.mem.writeInt(u64, bytes[24..32], self.descriptor.group_id, .little);
            std.mem.writeInt(u64, bytes[32..40], self.descriptor.total_bytes, .little);
            @memcpy(bytes[40..72], &self.descriptor.digest);
            std.mem.writeInt(u32, bytes[72..76], self.descriptor.chunk_count, .little);
            std.mem.writeInt(u32, bytes[76..80], self.next, .little);
            inline for (.{ "cluster_id", "timeline_id", "epoch", "last_lsn" }, 0..) |field, index| std.mem.writeInt(u64, bytes[80 + index * 8 ..][0..8], @field(self, field), .little);
            std.crypto.hash.Blake3.hash(bytes[0..112], bytes[112..144], .{});
            return bytes;
        }

        fn decode(bytes: []const u8) !@This() {
            if (bytes.len != 144) return error.InvalidMetadataHAEffect;
            var digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(bytes[0..112], &digest, .{});
            if (!std.mem.eql(u8, bytes[112..], &digest)) return error.InvalidMetadataHAEffect;
            const result: @This() = .{
                .descriptor = .{ .source = bytes[0..16].*, .sequence = std.mem.readInt(u64, bytes[16..24], .little), .group_id = std.mem.readInt(u64, bytes[24..32], .little), .total_bytes = std.mem.readInt(u64, bytes[32..40], .little), .digest = bytes[40..72].*, .chunk_count = std.mem.readInt(u32, bytes[72..76], .little) },
                .next = std.mem.readInt(u32, bytes[76..80], .little),
                .cluster_id = std.mem.readInt(u64, bytes[80..88], .little),
                .timeline_id = std.mem.readInt(u64, bytes[88..96], .little),
                .epoch = std.mem.readInt(u64, bytes[96..104], .little),
                .last_lsn = std.mem.readInt(u64, bytes[104..112], .little),
            };
            try result.descriptor.validate();
            if (result.next == 0 or result.next > result.descriptor.chunk_count) return error.InvalidMetadataHAEffect;
            return result;
        }
    };

    fn metadataChunkKey(index: u32) [metadata_chunk_prefix.len + 4]u8 {
        var key: [metadata_chunk_prefix.len + 4]u8 = undefined;
        @memcpy(key[0..metadata_chunk_prefix.len], metadata_chunk_prefix);
        std.mem.writeInt(u32, key[metadata_chunk_prefix.len..], index, .big);
        return key;
    }

    /// The embedding owns the shared HA mutation lease BEFORE its catalog
    /// mutex. Do not recursively acquire the writer-preferring seed barrier.
    pub fn bindHotStandby(self: *RaftApplyStore, gate: ?@import("antfly_local_sources").storage_db_replication_contract.WriteGate, mirror: ?@import("antfly_local_sources").storage_db_replication_contract.AsyncEffectMirror) !void {
        if (!self.apply_mutex.tryLock()) return error.MetadataHABindingBusy;
        defer self.apply_mutex.unlock(self.io_impl.io());
        self.hot_standby_gate = gate;
        self.hot_standby_mirror = mirror;
        self.hot_standby_port = null;
    }

    pub fn bindHotStandbyPort(self: *RaftApplyStore, port: ?@import("../../storage/metadata_hot_standby_port.zig").Port) !void {
        if (!self.apply_mutex.tryLock()) return error.MetadataHABindingBusy;
        defer self.apply_mutex.unlock(self.io_impl.io());
        self.hot_standby_port = port;
        self.hot_standby_gate = null;
        self.hot_standby_mirror = null;
    }

    fn hasHotStandbyMirror(self: *const RaftApplyStore) bool {
        return self.hot_standby_mirror != null or (if (self.hot_standby_port) |port| port.has_mirror else false);
    }

    fn lockHotStandbyTransition(self: *RaftApplyStore) !void {
        if (self.hot_standby_port) |port| return port.lock();
        if (self.hot_standby_mirror) |mirror| if (mirror.transition_mutex) |mutex| {
            @import("antfly_platform").sync.lockYieldingIo(mutex, self.io_impl.io());
        };
    }
    fn unlockHotStandbyTransition(self: *RaftApplyStore) void {
        if (self.hot_standby_port) |port| return port.unlock();
        if (self.hot_standby_mirror) |mirror| if (mirror.transition_mutex) |mutex| mutex.unlock();
    }
    fn checkHotStandby(self: *RaftApplyStore) !void {
        if (self.hot_standby_port) |port| return port.check();
        if (self.hot_standby_gate) |gate| try gate.check();
    }

    fn stageStandaloneHotStandby(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, capture: *@import("antfly_local_sources").storage_txn_mutation_capture.Capture, group_id: u64) !void {
        txn.mutation_capture = null;
        if (!self.hasHotStandbyMirror()) return;
        const identity: @import("../../storage/metadata_hot_standby_port.zig").Identity = if (self.hot_standby_port) |port| try port.identity() else .{
            .next_lsn = self.hot_standby_mirror.?.publisher.nextLsn(),
            .timeline_id = self.hot_standby_mirror.?.publisher.identity().timeline_id,
            .epoch = self.hot_standby_mirror.?.publisher.identity().epoch,
        };
        var source: [16]u8 = undefined;
        const pending = if (try stagingGet(txn, metadata_pending_key)) |bytes| try MetadataPending.decode(bytes) else null;
        if (pending) |value| if (identity.epoch <= value.epoch) return error.MetadataHAIncompleteEffect;
        if (try stagingGet(txn, metadata_hot_standby.source_key)) |bytes| {
            if (bytes.len != 16) return error.InvalidMetadataHAEffect;
            source = bytes[0..16].*;
        } else if (pending) |value| {
            source = value.descriptor.source;
        } else {
            try self.io_impl.io().randomSecure(&source);
            if (std.mem.allEqual(u8, &source, 0)) return error.InvalidMetadataHAEffect;
        }
        const raw_sequence = try stagingGet(txn, metadata_hot_standby.sequence_key);
        if (raw_sequence != null and raw_sequence.?.len != 8) return error.InvalidMetadataHAEffect;
        const sequence = std.math.add(u64, if (raw_sequence) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else 0, 1) catch return error.InvalidMetadataHAEffect;
        const payload = try metadata_hot_standby.encode(self.alloc, capture, txn, .{ .source = source, .sequence = sequence, .group_id = group_id, .count = 0 });
        defer self.alloc.free(payload);
        // A promoted authority starts from its last fully applied metadata
        // epoch, not an interrupted incoming effect. No staged prefix is
        // externally visible or included in the outgoing mutation capture.
        if (pending) |value| try clearMetadataPending(txn, value);
        const outbox = try self.alloc.alloc(u8, payload.len + 24);
        defer self.alloc.free(outbox);
        std.mem.writeInt(u64, outbox[0..8], identity.next_lsn, .little);
        std.mem.writeInt(u64, outbox[8..16], identity.timeline_id, .little);
        std.mem.writeInt(u64, outbox[16..24], identity.epoch, .little);
        @memcpy(outbox[24..], payload);
        var sequence_bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &sequence_bytes, sequence, .little);
        try txn.put(metadata_hot_standby.source_key, &source);
        try txn.put(metadata_hot_standby.sequence_key, &sequence_bytes);
        var effect_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(payload, &effect_digest, .{});
        try txn.put(metadata_hot_standby.digest_key, &effect_digest);
        try txn.put(metadata_hot_standby.outbox_key, outbox);
    }

    /// Caller retains the outer mutation lease. apply_mutex serializes the
    /// single durable outbox; transition lock covers only authority + append.
    fn flushHotStandbyOutboxLocked(self: *RaftApplyStore) !void {
        const raw = self.store.get(self.alloc, metadata_hot_standby.outbox_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        defer self.alloc.free(raw);
        if (raw.len < 24) return error.InvalidMetadataHAEffect;
        if (self.hot_standby_port) |port| {
            _ = try metadata_hot_standby.Decoder.init(raw[24..]);
            try port.publishAndLock(raw);
            defer port.unlock();
            var txn = try self.store.beginWriteTxn();
            var committed = false;
            defer if (!committed) txn.abort();
            try txn.delete(metadata_hot_standby.outbox_key);
            try txn.commit();
            committed = true;
            try self.store.sync(true);
            return;
        }
        const mirror = self.hot_standby_mirror orelse return error.MetadataHAOutboxPending;
        _ = try metadata_hot_standby.Decoder.init(raw[24..]);
        const descriptor = try metadata_chunks.Descriptor.fromEffect(raw[24..]);
        try self.lockHotStandbyTransition();
        var transition_locked = true;
        defer if (transition_locked) self.unlockHotStandbyTransition();
        const gate = if (self.hot_standby_gate) |value| value.pinned() else null;
        if (gate) |value| try value.check();
        const same_timeline = std.mem.readInt(u64, raw[8..16], .little) == mirror.publisher.identity().timeline_id and std.mem.readInt(u64, raw[16..24], .little) == mirror.publisher.identity().epoch;
        var search_from = std.mem.readInt(u64, raw[0..8], .little);
        var lsn: u64 = 0;
        var index: u32 = 0;
        while (index < descriptor.chunk_count) : (index += 1) {
            self.unlockHotStandbyTransition();
            transition_locked = false;
            const offset = @as(usize, index) * metadata_chunks.max_chunk_payload_bytes;
            const end = @min(raw.len - 24, offset + metadata_chunks.max_chunk_payload_bytes);
            const frame = try metadata_chunks.encodeFrame(self.alloc, descriptor, index, raw[24..][offset..end]);
            defer self.alloc.free(frame);
            try self.lockHotStandbyTransition();
            transition_locked = true;
            if (gate) |value| try value.check();
            const prior = if (same_timeline) try (try hot_standby_publisher_adapter.runtimePrimary(mirror)).findMatchingRecordFrom(search_from, .metadata_mutation, frame, 0, 0) else null;
            lsn = prior orelse try (try hot_standby_publisher_adapter.runtimePrimary(mirror)).append(.{ .kind = .metadata_mutation, .payload_codec = .binary, .shard_id = 0, .table_id = 0, .payload = frame });
            search_from = lsn +| 1;
        }
        if (hot_standby_publisher_adapter.options(mirror).last_lsn) |last| last.store(lsn, .release);
        self.unlockHotStandbyTransition();
        transition_locked = false;
        if (hot_standby_publisher_adapter.options(mirror).sync_policy.mode != .async) {
            if (hot_standby_publisher_adapter.options(mirror).sync_wait_fn) |wait| try wait(hot_standby_publisher_adapter.options(mirror).sync_wait_ctx orelse return error.HASyncCommitWaitMissingContext, mirror.publisher.ptr, lsn, hot_standby_publisher_adapter.options(mirror).sync_policy);
            const decision = try @import("../../storage/hot_standby/commit_gate.zig").evaluate(try hot_standby_publisher_adapter.runtimePrimary(mirror), lsn, hot_standby_publisher_adapter.options(mirror).sync_policy);
            if (!decision.shouldAcknowledge()) return error.HASyncCommitWouldBlock;
        }
        // A remote acknowledgment can outlive the role generation that
        // appended it. Retain the outbox if that authority changed.
        try self.lockHotStandbyTransition();
        transition_locked = true;
        if (gate) |value| try value.check();
        var txn = try self.store.beginWriteTxn();
        var committed = false;
        defer if (!committed) txn.abort();
        try txn.delete(metadata_hot_standby.outbox_key);
        try txn.commit();
        committed = true;
        try self.store.sync(true);
    }

    pub fn flushHotStandbyOutbox(self: *RaftApplyStore) !void {
        self.apply_mutex.lockUncancelable(self.io_impl.io());
        defer self.apply_mutex.unlock(self.io_impl.io());
        try self.flushHotStandbyOutboxLocked();
    }

    pub fn applyHotStandbyRecord(self: *RaftApplyStore, record: @import("antfly_local_sources").storage_db_replication_record.RecordView) !void {
        if (record.payload_codec == .json) return self.applyLegacyCatalogCreate(record);
        return self.applyHotStandbyChunk(record);
    }

    // Released standalone primaries wrote this JSON envelope before atomic
    // metadata effects existed. Read it only: all new producers use AFMC.
    const LegacyCatalogCreate = struct {
        schema_version: u32 = 3,
        kind: enum { table_create } = .table_create,
        table: metadata.TableRecord,
        ranges: []const metadata.RangeRecord,
        binding: ?struct {
            previous_revision: u64,
            delta: system_catalog.Delta,
        } = null,
    };

    fn applyLegacyCatalogCreate(self: *RaftApplyStore, record: @import("antfly_local_sources").storage_db_replication_record.RecordView) !void {
        if (record.kind != .metadata_mutation or record.table_id != 0 or record.shard_id != 0 or record.lsn == 0 or record.previous_lsn >= record.lsn or record.payload.len > metadata_hot_standby.max_effect_bytes) return error.InvalidMetadataHAEffect;
        const parsed = std.json.parseFromSlice(LegacyCatalogCreate, self.alloc, record.payload, .{}) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidMetadataHAEffect,
        };
        defer parsed.deinit();
        const create = parsed.value;
        if ((create.schema_version != 3 and create.schema_version != 4) or
            (create.schema_version == 3 and create.binding != null)) return error.InvalidMetadataHAEffect;
        if (create.binding) |binding| {
            if (binding.delta.removes.len != 0 or binding.delta.upserts.len != 1) return error.InvalidMetadataHAEffect;
            const resource = binding.delta.upserts[0];
            if (resource.kind != .table or resource.id != create.table.table_id or
                !std.mem.eql(u8, resource.storage_name, create.table.name)) return error.InvalidMetadataHAEffect;
        }
        const mutation: TableTopologyMutation = .{ .create = .{ .table = create.table, .ranges = create.ranges, .expected_transition_generation = 0 } };
        try validateTransitionCommandDataGroupIds(.{ .apply_table_topology = mutation });
        if (create.table.storage_migration) |migration| try migration.request.validate();
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(record.payload, &digest, .{});

        self.apply_mutex.lockUncancelable(self.io_impl.io());
        defer self.apply_mutex.unlock(self.io_impl.io());
        var outcome = CommittedApplyOutcome{ .alloc = self.alloc, .collect_transition_deltas = false };
        defer outcome.deinit();
        std.debug.assert(self.active_outcome == null);
        self.active_outcome = &outcome;
        defer self.active_outcome = null;
        var txn = try self.store.beginWriteTxn();
        var committed = false;
        defer if (!committed) txn.abort();
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataHAOutboxPending;
        if (try stagingGet(&txn, metadata_hot_standby.replay_key)) |previous| {
            if (previous.len != 40) return error.InvalidMetadataHAEffect;
            if (std.mem.readInt(u64, previous[0..8], .little) != record.cluster_id) return error.MetadataHASourceChanged;
            const previous_epoch = std.mem.readInt(u64, previous[16..24], .little);
            const previous_timeline = std.mem.readInt(u64, previous[8..16], .little);
            if (record.epoch < previous_epoch or (record.epoch == previous_epoch and record.timeline_id != previous_timeline)) return error.MetadataHASourceChanged;
            if (record.epoch == previous_epoch) {
                const previous_lsn = std.mem.readInt(u64, previous[24..32], .little);
                if (record.lsn <= previous_lsn) {
                    // A covered prefix must not resurrect a table modified or
                    // removed by a later effect. Detect equivocation at the
                    // current JSON receipt, including after checkpoint/reopen.
                    if (record.lsn == previous_lsn and try stagingGet(&txn, metadata_hot_standby.source_key) == null) {
                        const previous_digest = (try stagingGet(&txn, legacy_catalog_digest_key)) orelse return error.InvalidMetadataHAEffect;
                        if (!std.mem.eql(u8, previous_digest, &digest)) return error.MetadataHASourceChanged;
                    }
                    return;
                }
            }
        }
        // Once a producer has upgraded, a new JSON effect cannot bypass its
        // ordered binary stream (nor interrupt an in-flight chunked effect).
        if (try stagingGet(&txn, metadata_hot_standby.source_key) != null or try stagingGet(&txn, metadata_pending_key) != null) return error.MetadataHASourceChanged;
        const group = group_ids.main_metadata_group_id;
        _ = try self.ensureDerivedCatalogIndexesTxn(&txn, group);
        // Released JSON producers do not carry relation ownership effects.
        // Derive those effects from their final binding/topology cut, in the
        // replay transaction itself, before acknowledging the source receipt.
        const relation_writer = try relationWriterEnabledTxn(&txn, group);
        var relation_journal = command_journal.Journal.init(self.alloc, &txn);
        defer relation_journal.deinit();
        if (relation_writer) try relation_journal.attach();
        errdefer if (relation_writer and !committed) {
            self.invalidateProjectedPlacementGroup(group);
            _ = self.verified_catalog_groups.remove(group);
        };
        if (create.binding) |binding| {
            const meta = try system_catalog_storage.readMeta(self.alloc, &txn, group);
            if (meta.revision == binding.previous_revision) {
                try self.applySystemCatalogDeltaTxn(self.alloc, &txn, group, binding.delta, meta, @splat(0));
            } else {
                if (meta.revision <= binding.previous_revision or meta.next_id < binding.delta.next_id) return error.HACatalogReplayConflict;
                for (binding.delta.upserts) |expected| {
                    var arena = std.heap.ArenaAllocator.init(self.alloc);
                    defer arena.deinit();
                    var actual = (try system_catalog_storage.getById(arena.allocator(), &txn, group, expected.kind, expected.id)) orelse return error.HACatalogReplayConflict;
                    defer actual.deinit();
                    if (!std.mem.eql(u8, try std.json.Stringify.valueAlloc(arena.allocator(), actual.value, .{}), try std.json.Stringify.valueAlloc(arena.allocator(), expected, .{}))) return error.HACatalogReplayConflict;
                }
            }
        }
        var table_key_buf: [160]u8 = undefined;
        const table_key = try tableKeyForGroup(&table_key_buf, group, create.table.table_id);
        if (try stagingGet(&txn, table_key) == null) try self.applyTableTopologyMutationTxn(&txn, group, mutation);
        const encoded_table = (try stagingGet(&txn, table_key)) orelse return error.TableLifecycleConflict;
        const table = try decodeTableRecord(self.alloc, encoded_table);
        defer metadata_table_manager.freeTable(self.alloc, table);
        if (!metadata_table_manager.tableDefinitionsEqual(table, create.table)) return error.TableLifecycleConflict;
        const ids = try self.indexedTableRangeIdsTxn(self.alloc, &txn, group, table.table_id);
        defer self.alloc.free(ids);
        if (ids.len != create.ranges.len) return error.TableLifecycleConflict;
        for (create.ranges) |expected| {
            var range_key_buf: [160]u8 = undefined;
            const encoded_range = (try stagingGet(&txn, try rangeKeyForGroup(&range_key_buf, group, expected.group_id))) orelse return error.TableLifecycleConflict;
            const actual = try decodeRangeRecord(self.alloc, encoded_range);
            defer metadata_table_manager.freeRange(self.alloc, actual);
            if (!metadata_table_manager.rangeRecordsEqual(expected, actual)) return error.TableLifecycleConflict;
        }
        if (try stagingGet(&txn, standalone_catalog_key) == null) try txn.put(standalone_catalog_key, "{\"epoch\":1,\"tables\":[],\"ranges\":[]}");
        if (relation_writer) {
            try self.publishCapturedRelationsTxn(&txn, group, &relation_journal);
            try relation_journal.accept();
        }
        try advanceStandaloneRevision(&txn);
        try txn.put(legacy_catalog_digest_key, &digest);
        try metadataReplayReceipt(&txn, record);
        self.notifyMetadataSnapshotInstalled(group);
        self.invalidateProjectedPlacementGroup(group);
        try self.commitStandaloneTxn(&txn, &outcome, &committed);
    }

    fn metadataReplayReceipt(txn: *docstore.DocStore.Txn, record: @import("antfly_local_sources").storage_db_replication_record.RecordView) !void {
        if (try stagingGet(txn, metadata_hot_standby.replay_key)) |previous| {
            if (previous.len != 40) return error.InvalidMetadataHAEffect;
            if (std.mem.readInt(u64, previous[0..8], .little) != record.cluster_id) return error.MetadataHASourceChanged;
            const previous_epoch = std.mem.readInt(u64, previous[16..24], .little);
            if (record.epoch < previous_epoch) return;
            if (record.epoch == previous_epoch and std.mem.readInt(u64, previous[8..16], .little) != record.timeline_id) return error.MetadataHASourceChanged;
            if (std.mem.readInt(u64, previous[8..16], .little) == record.timeline_id and std.mem.readInt(u64, previous[16..24], .little) == record.epoch and std.mem.readInt(u64, previous[24..32], .little) >= record.lsn) return;
        }
        var replay: [40]u8 = undefined;
        inline for (.{ "cluster_id", "timeline_id", "epoch", "lsn", "previous_lsn" }, 0..) |field, index| std.mem.writeInt(u64, replay[index * 8 ..][0..8], @field(record, field), .little);
        try txn.put(metadata_hot_standby.replay_key, &replay);
    }

    fn clearMetadataPending(txn: *docstore.DocStore.Txn, pending: MetadataPending) !void {
        var index: u32 = 0;
        while (index < pending.next) : (index += 1) try txn.delete(&metadataChunkKey(index));
        try txn.delete(metadata_pending_key);
    }

    fn metadataReplaySequenceTxn(txn: *docstore.DocStore.Txn, descriptor: metadata_chunks.Descriptor) !u64 {
        if (try stagingGet(txn, metadata_hot_standby.outbox_key) != null) return error.MetadataHAOutboxPending;
        const source = try stagingGet(txn, metadata_hot_standby.source_key);
        const sequence = try stagingGet(txn, metadata_hot_standby.sequence_key);
        if (source != null and (source.?.len != 16 or !std.mem.eql(u8, source.?, &descriptor.source))) return error.MetadataHASourceChanged;
        if ((source == null) != (sequence == null) or (sequence != null and sequence.?.len != 8)) return error.InvalidMetadataHAEffect;
        const current = if (sequence) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else 0;
        if (descriptor.sequence > current +| 1) return error.MetadataHASequenceGap;
        return current;
    }

    fn validateMetadataPendingFrame(pending: MetadataPending, record: @import("antfly_local_sources").storage_db_replication_record.RecordView, frame: metadata_chunks.Frame) !void {
        try pending.descriptor.validate();
        if (pending.next > pending.descriptor.chunk_count or pending.cluster_id != record.cluster_id or
            !std.mem.eql(u8, &pending.descriptor.source, &frame.descriptor.source)) return error.MetadataHASourceChanged;
        if (record.epoch > pending.epoch and frame.index == 0) {
            if (pending.descriptor.sequence != frame.descriptor.sequence) return error.MetadataHASequenceGap;
            return; // The locked transaction performs the actual supersession.
        }
        if (!pending.descriptor.eql(frame.descriptor)) return error.MetadataHAChunkConflict;
        if (frame.index > pending.next or ((record.epoch != pending.epoch or record.timeline_id != pending.timeline_id) and frame.index >= pending.next))
            return error.MetadataHAChunkSequenceGap;
    }

    fn standbyRelationActivationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, required: u16) !topology_protocol.Activation {
        return self.requireTopologyActivationTxn(txn, group, @max(required, topology_protocol.relation_publication_version));
    }

    fn requireTopologyActivationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, required: u16) !topology_protocol.Activation {
        var buf: [160]u8 = undefined;
        const raw = (try stagingGet(txn, try topologyActivationKeyForGroup(&buf, group))) orelse return error.TableTopologyProtocolUpgradeRequired;
        if (raw.len > 1024) return error.InvalidCatalogRecord;
        var parsed = try std.json.parseFromSlice(topology_protocol.Activation, self.alloc, raw, .{});
        defer parsed.deinit();
        const activation = parsed.value;
        if (activation.version < required) return error.TableTopologyProtocolUpgradeRequired;
        if (activation.version > topology_protocol.current_version or activation.member_count == 0 or
            std.mem.allEqual(u8, &activation.membership_fingerprint, 0)) return error.InvalidCatalogRecord;
        const identity_raw = (try stagingGet(txn, try metadataIncarnationKeyForGroup(&buf, group))) orelse return error.TableTopologyProtocolUpgradeRequired;
        if (!std.meta.eql((try decodeMetadataIncarnationRecord(identity_raw)).incarnation, activation.incarnation))
            return error.TableTopologyProtocolUpgradeRequired;
        return activation;
    }

    /// Inspect one frame and advance at most one local proof page before the
    /// apply lock. The durable receive WAL owns the supplied record until the
    /// callback succeeds; only earlier prefix frames need local staging. On
    /// restart reconstruct one staged prefix per call, never an entire effect.
    /// The cache owns fixed-size values only, not transactions or frame buffers.
    fn prepareStandbyRelationPublication(self: *RaftApplyStore, record: @import("antfly_local_sources").storage_db_replication_record.RecordView, frame: metadata_chunks.Frame) !?StandbyRelationPublication {
        if (!self.standby_probe_mutex.tryLock()) return error.CatalogPublicationProofPending;
        defer self.standby_probe_mutex.unlock(self.io_impl.io());
        var read = try self.store.beginReadTxn();
        defer read.abort();
        // Already applied effects have no staged prefix left. The locked path
        // still checks exact source/digest and timeline before acknowledging.
        if (frame.descriptor.sequence <= try metadataReplaySequenceTxn(&read, frame.descriptor)) return null;
        const staged = if (try stagingGet(&read, metadata_pending_key)) |raw| try MetadataPending.decode(raw) else null;
        if (staged) |pending| {
            try validateMetadataPendingFrame(pending, record, frame);
            if (pending.descriptor.eql(frame.descriptor) and frame.index < pending.next) {
                const prior = (try stagingGet(&read, &metadataChunkKey(frame.index))) orelse return error.InvalidMetadataHAEffect;
                if (!std.mem.eql(u8, prior, record.payload)) return error.MetadataHAChunkConflict;
                if (record.epoch != pending.epoch or record.timeline_id != pending.timeline_id) return null;
            }
        } else if (frame.index != 0) return error.MetadataHAChunkSequenceGap;
        if (self.standby_probe == null or self.standby_probe.?.failed or !self.standby_probe.?.descriptor.eql(frame.descriptor)) {
            var root_buf: [160]u8 = undefined;
            var live_buf: [160]u8 = undefined;
            self.standby_probe = try StandbyRelationProbe.init(frame.descriptor, .{
                try relation_reconciliation.rootKey(&root_buf, frame.descriptor.group_id),
                try relation_reconciliation.liveKey(&live_buf, frame.descriptor.group_id),
            });
        }
        const probe = &self.standby_probe.?;
        if (probe.next_frame < frame.index) {
            const pending = staged orelse return error.MetadataHAChunkSequenceGap;
            if (!pending.descriptor.eql(frame.descriptor)) return error.MetadataHAChunkConflict;
            if (frame.index > pending.next) return error.MetadataHAChunkSequenceGap;
            if (probe.next_frame >= pending.next) return error.MetadataHAChunkSequenceGap;
            const raw = (try stagingGet(&read, &metadataChunkKey(probe.next_frame))) orelse return error.InvalidMetadataHAEffect;
            try probe.feed(try metadata_chunks.decodeFrame(raw));
            return error.CatalogPublicationProofPending;
        }
        if (probe.next_frame == frame.index) try probe.feed(frame);
        if (frame.index + 1 != frame.descriptor.chunk_count) return null;
        const proposed_root = try probe.get(0);
        const proposed_live = try probe.get(1);
        if (proposed_root.kind == .missing and proposed_live.kind == .missing) return null;
        if (proposed_root.kind == .deleted or proposed_live.kind == .deleted) return error.InvalidCatalogRecord;
        var buf: [160]u8 = undefined;
        const before_live = if (try stagingGet(&read, try relation_reconciliation.liveKey(&buf, frame.descriptor.group_id))) |raw|
            try relation_reconciliation.LiveRoot.decode(raw)
        else
            null;
        if (proposed_live.kind == .missing) {
            const root = try relation_reconciliation.Generation.decode(proposed_root.value().?);
            if (before_live == null or !before_live.?.generation.eql(root)) return error.InvalidCatalogRecord;
            return null;
        }
        const live = try relation_reconciliation.LiveRoot.decode(proposed_live.value().?);
        if (before_live) |previous| if (previous.generation.eql(live.generation)) return null;
        if (proposed_root.kind != .value or !live.generation.eql(try relation_reconciliation.Generation.decode(proposed_root.value().?)))
            return error.InvalidCatalogRecord;
        const observed = try PreparedRelationBatch.capture(&read, frame.descriptor.group_id);
        const state = observed.job orelse return error.InvalidCatalogRecord;
        if (!std.meta.eql(live, try relation_reconciliation.LiveRoot.initial(state)) or observed.epoch == null or
            !observed.epoch.?.eql(state.epoch)) return error.InvalidCatalogRecord;
        if (observed.root) |root| {
            if (before_live == null or !root.eql(before_live.?.generation) or std.mem.order(u8, &root.job_id, &live.generation.job_id) != .lt)
                return error.InvalidCatalogRecord;
        } else if (before_live != null) return error.InvalidCatalogRecord;
        const activation = try self.standbyRelationActivationTxn(&read, state.group_id, relation_control.publicationVersion(state.coverage));
        const proof = try self.requireRelationPublicationProof(state, platform_time.monotonicNs());
        if (!std.meta.eql(proof.root, observed.root) or proof.applied_index != observed.applied_index) return error.CatalogPublicationProofPending;
        return .{ .proof = proof, .activation = activation };
    }

    fn applyHotStandbyChunk(self: *RaftApplyStore, record: @import("antfly_local_sources").storage_db_replication_record.RecordView) !void {
        if (record.kind != .metadata_mutation or record.payload_codec != .binary or record.table_id != 0 or record.shard_id != 0) return error.InvalidMetadataHAEffect;
        const frame = try metadata_chunks.decodeFrame(record.payload);
        const descriptor = frame.descriptor;
        const publication = try self.prepareStandbyRelationPublication(record, frame);
        self.apply_mutex.lockUncancelable(self.io_impl.io());
        defer self.apply_mutex.unlock(self.io_impl.io());
        var outcome = CommittedApplyOutcome{ .alloc = self.alloc, .collect_transition_deltas = false };
        defer outcome.deinit();
        std.debug.assert(self.active_outcome == null);
        self.active_outcome = &outcome;
        defer self.active_outcome = null;
        var txn = try self.store.beginWriteTxn();
        var committed = false;
        defer if (!committed) txn.abort();
        const current = try metadataReplaySequenceTxn(&txn, descriptor);
        if (descriptor.sequence <= current) {
            if (descriptor.sequence == current) {
                const digest = (try stagingGet(&txn, metadata_hot_standby.digest_key)) orelse return error.InvalidMetadataHAEffect;
                if (!std.mem.eql(u8, digest, &descriptor.digest)) return error.MetadataHASourceChanged;
            }
            // A replayed prefix cannot advance the atomic effect receipt.
            if (frame.index + 1 != descriptor.chunk_count) return;
            try metadataReplayReceipt(&txn, record);
            return self.commitStandaloneTxn(&txn, &outcome, &committed);
        }
        if (try stagingGet(&txn, metadata_hot_standby.replay_key)) |previous| {
            if (previous.len != 40 or std.mem.readInt(u64, previous[0..8], .little) != record.cluster_id) return error.MetadataHASourceChanged;
            const previous_epoch = std.mem.readInt(u64, previous[16..24], .little);
            if (record.epoch < previous_epoch or (record.epoch == previous_epoch and std.mem.readInt(u64, previous[8..16], .little) != record.timeline_id)) return error.MetadataHASourceChanged;
        }
        var pending: MetadataPending = if (try stagingGet(&txn, metadata_pending_key)) |raw| try MetadataPending.decode(raw) else .{
            .descriptor = descriptor,
            .next = 0,
            .cluster_id = record.cluster_id,
            .timeline_id = record.timeline_id,
            .epoch = record.epoch,
            .last_lsn = 0,
        };
        try validateMetadataPendingFrame(pending, record, frame);
        if (record.epoch > pending.epoch and frame.index == 0) {
            // The authenticated HA receiver admitted a newer timeline. Its
            // first frame may supersede only an uncommitted predecessor slot.
            if (pending.descriptor.sequence != descriptor.sequence) return error.MetadataHASequenceGap;
            if (!pending.descriptor.eql(descriptor)) {
                try clearMetadataPending(&txn, pending);
                pending.next = 0;
                pending.descriptor = descriptor;
            }
            pending.timeline_id = record.timeline_id;
            pending.epoch = record.epoch;
            pending.last_lsn = 0;
        }
        if (!pending.descriptor.eql(descriptor)) return error.MetadataHAChunkConflict;
        const current_timeline = pending.timeline_id == record.timeline_id and pending.epoch == record.epoch;
        if (frame.index < pending.next) {
            const prior = (try stagingGet(&txn, &metadataChunkKey(frame.index))) orelse return error.InvalidMetadataHAEffect;
            if (!std.mem.eql(u8, prior, record.payload)) return error.MetadataHAChunkConflict;
            if (!current_timeline) return;
            pending.last_lsn = @max(pending.last_lsn, record.lsn);
            try txn.put(metadata_pending_key, &pending.encode());
            return self.commitStandaloneTxn(&txn, &outcome, &committed);
        }
        if (!current_timeline or frame.index != pending.next or record.lsn <= pending.last_lsn) return error.MetadataHAChunkSequenceGap;
        if (publication) |verified| {
            if (!try verified.proof.matchesTxn(&txn)) return error.CatalogPublicationProofPending;
            if (verified.proof.fence) |fence| if (!self.relationProofTracking(descriptor.group_id).canAdopt(fence, verified.proof.applied_index, verified.proof.applied_index)) return error.CatalogPublicationProofPending;
            if (!std.meta.eql(verified.activation, try self.standbyRelationActivationTxn(&txn, descriptor.group_id, relation_control.publicationVersion(verified.proof.state.coverage))))
                return error.TableTopologyProtocolUpgradeRequired;
        }
        try txn.put(&metadataChunkKey(frame.index), record.payload);
        pending.next += 1;
        pending.last_lsn = record.lsn;
        try txn.put(metadata_pending_key, &pending.encode());
        if (pending.next != descriptor.chunk_count) return self.commitStandaloneTxn(&txn, &outcome, &committed);
        const Reader = struct {
            txn: *docstore.DocStore.Txn,
            pub fn read(ptr: *anyopaque, index: u32, buffer: []u8) !usize {
                const self_reader: *@This() = @ptrCast(@alignCast(ptr));
                const bytes = try self_reader.txn.get(&metadataChunkKey(index));
                if (bytes.len > buffer.len) return error.InvalidMetadataHAEffect;
                @memcpy(buffer[0..bytes.len], bytes);
                return bytes.len;
            }
        };
        var reader = Reader{ .txn = &txn };
        var decoder = try metadata_chunks.StreamingDecoder.init(self.alloc, descriptor, .{ .ptr = &reader, .read_frame = Reader.read });
        defer decoder.deinit();
        const relation_writer = try relationWriterEnabledTxn(&txn, descriptor.group_id);
        const source_tracked = try relation_reconciliation.readSourceRevision(&txn, descriptor.group_id) != 0;
        var relation_journal = command_journal.Journal.initVerification(self.alloc, &txn, descriptor.group_id, if (relation_writer) relationReplayBeforeKey else relationSourceReplayBeforeKey);
        defer relation_journal.deinit();
        if (relation_writer) try relation_journal.attach();
        var reconciliation_changed = false;
        // Each row is decoded once into bounded owned scratch. Store writes
        // remain invisible until next(null) verifies both complete hashes.
        while (try decoder.next()) |row| {
            if (source_tracked and try relationSourceReplayBeforeKey(descriptor.group_id, row.key) and !relation_journal.attached) try relation_journal.attach();
            if (try reconciliationReplayBeforeKey(descriptor.group_id, row.key)) {
                reconciliation_changed = true;
                if (!relation_journal.attached) try relation_journal.attach();
            }
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = descriptor.group_id, .key = row.key });
            if (row.value) |value| try txn.put(row.key, value) else txn.delete(row.key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
        }
        if (!relation_writer and try relationWriterEnabledTxn(&txn, descriptor.group_id) and publication == null)
            return error.InvalidCatalogRecord;
        if (relation_writer) {
            if (!try relationWriterEnabledTxn(&txn, descriptor.group_id)) return error.InvalidCatalogRecord;
            var plan = try self.capturedRelationsPlanTxn(&txn, descriptor.group_id, &relation_journal, true);
            defer plan.deinit();
            var before = relation_journal.beforeReader();
            var before_registry = try RelationRegistry(command_journal.Journal.BeforeReader).init(self.alloc, &before, descriptor.group_id);
            try plan.validate(&before_registry);
            var registry = try RelationRegistry(docstore.DocStore.Txn).init(self.alloc, &txn, descriptor.group_id);
            try plan.verifyPublished(&registry);
        }
        if (reconciliation_changed) {
            // A ready seal alone is never authority. Only this receiver's
            // independently prepared, still-fenced source/candidate proof can
            // admit a new generation. Canonical replay below separately checks
            // that adoption cannot mutate its sealed job or candidate rows.
            var buf: [128]u8 = undefined;
            const key = try relation_reconciliation.liveKey(&buf, descriptor.group_id);
            if (try stagingGet(&txn, key)) |bytes| {
                var before = relation_journal.beforeReader();
                const prior_bytes = before.get(key) catch |err| blk: {
                    if (err == error.NotFound) break :blk null;
                    return err;
                };
                const prior = if (prior_bytes) |raw| try relation_reconciliation.LiveRoot.decode(raw) else null;
                const live = try relation_reconciliation.LiveRoot.decode(bytes);
                if (prior == null or !prior.?.generation.eql(live.generation)) {
                    const verified = publication orelse return error.InvalidCatalogRecord;
                    if (!std.meta.eql(live, try relation_reconciliation.LiveRoot.initial(verified.proof.state)) or
                        !live.epoch.eql(try relationSourceEpochTxn(&txn, descriptor.group_id)) or
                        try durableAppliedIndexTxn(&txn, descriptor.group_id) != verified.proof.applied_index or
                        !try relationWriterEnabledTxn(&txn, descriptor.group_id)) return error.InvalidCatalogRecord;
                    if (!std.meta.eql(verified.activation, try self.standbyRelationActivationTxn(&txn, descriptor.group_id, relation_control.publicationVersion(verified.proof.state.coverage))))
                        return error.TableTopologyProtocolUpgradeRequired;
                }
            }
        }
        if (reconciliation_changed) {
            var before = relation_journal.beforeReader();
            var replay = try relation_reconciliation.ReplayVerifier(command_journal.Journal.BeforeReader, docstore.DocStore.Txn).init(self.alloc, &before, &txn, descriptor.group_id);
            defer replay.deinit();
            var keys = relation_journal.originals.keyIterator();
            while (keys.next()) |key| try replay.feed(key.*);
            try replay.finish();
            try verifyReconciliationEpochTxn(&txn, descriptor.group_id, &relation_journal);
            try self.verifyReconciliationSourceOwnersTxn(&txn, descriptor.group_id, &relation_journal);
        }
        if (relation_journal.attached) try verifyRelationSourceDeltaTxn(self.alloc, &txn, descriptor.group_id, &relation_journal);
        if (relation_journal.attached) try relation_journal.accept();
        var sequence_bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &sequence_bytes, descriptor.sequence, .little);
        try txn.put(metadata_hot_standby.source_key, &descriptor.source);
        try txn.put(metadata_hot_standby.sequence_key, &sequence_bytes);
        try txn.put(metadata_hot_standby.digest_key, &descriptor.digest);
        try clearMetadataPending(&txn, pending);
        try metadataReplayReceipt(&txn, record);
        self.notifyMetadataSnapshotInstalled(descriptor.group_id);
        self.invalidateProjectedPlacementGroup(descriptor.group_id);
        try self.commitStandaloneTxn(&txn, &outcome, &committed);
    }

    /// Seed caller already holds exclusive mutation barrier and transition
    /// mutex. This method never appends HA or recursively takes those locks.
    pub fn exportHotStandbyCheckpoint(self: *RaftApplyStore, io: std.Io, path: []const u8) !metadata_hot_standby.CheckpointArtifact {
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataHAOutboxPending;
        try verifyRelationCheckpointTxn(self.alloc, &txn);
        return writeHotStandbyCheckpointTxn(io, path, &txn);
    }

    /// One pinned cut supplies both the native artifact and its logical
    /// projection. A catalog alone cannot transport allocator high-water or
    /// durable admissions, including history after the last sequence is gone.
    pub fn captureHotStandbyCatalogCheckpoint(self: *RaftApplyStore, alloc: std.mem.Allocator, io: std.Io, group_id: u64, path: []const u8) !@import("../../system_catalog/projection.zig").CatalogCheckpoint {
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataHAOutboxPending;
        try verifyRelationCheckpointTxn(self.alloc, &txn);
        const checkpoint = try writeHotStandbyCheckpointTxn(io, path, &txn);
        return .{ .checkpoint = checkpoint, .catalog_json = try self.exportSystemCatalogTxn(alloc, &txn, group_id, checkpoint) };
    }

    fn writeHotStandbyCheckpointTxn(io: std.Io, path: []const u8, txn: *docstore.DocStore.Txn) !metadata_hot_standby.CheckpointArtifact {
        var file = try std.Io.Dir.cwd().createFile(io, path, .{ .exclusive = true });
        defer file.close(io);
        var writer: metadata_hot_standby.CheckpointWriter = .{ .file = file, .io = io };
        try writer.write("AFMCHK01");
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.first();
        while (entry) |row| : (entry = try cursor.next()) {
            try writer.write(&try metadata_hot_standby.checkpointHeader(row.key.len, row.value.len));
            try writer.write(row.key);
            try writer.write(row.value);
        }
        const result = try writer.finish();
        try fs_paths.syncDirPortable(io, std.fs.path.dirname(path) orelse ".");
        return result;
    }

    /// Imports only into a fresh, unpublished store. Bounded transactions may
    /// commit during import; the enclosing seed root remains invisible until
    /// its authenticated artifact digest and every owner proof are verified.
    pub fn importHotStandbyCheckpoint(self: *RaftApplyStore, io: std.Io, path: []const u8, size_bytes: u64) !void {
        if (size_bytes < 8) return error.InvalidMetadataHACheckpoint;
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        {
            var read = try self.store.beginReadTxn();
            defer read.abort();
            var cursor = try read.openCursor();
            defer cursor.close();
            if (try cursor.first() != null) return error.MetadataHACheckpointTargetNotEmpty;
        }
        var file = try std.Io.Dir.cwd().openFile(io, path, .{});
        defer file.close(io);
        var magic: [8]u8 = undefined;
        if (try file.readPositionalAll(io, &magic, 0) != 8 or !std.mem.eql(u8, &magic, "AFMCHK01")) return error.InvalidMetadataHACheckpoint;
        var offset: u64 = 8;
        var previous: ?[]u8 = null;
        defer if (previous) |key| self.alloc.free(key);
        while (offset < size_bytes) {
            var txn = try self.store.beginWriteTxn();
            var committed = false;
            defer if (!committed) txn.abort();
            var rows: usize = 0;
            var batch_bytes: usize = 0;
            while (rows < 128 and batch_bytes < 1024 * 1024 and offset < size_bytes) : (rows += 1) {
                var header: [12]u8 = undefined;
                if (size_bytes - offset < header.len or try file.readPositionalAll(io, &header, offset) != header.len) return error.InvalidMetadataHACheckpoint;
                offset += header.len;
                const key_len = std.mem.readInt(u32, header[0..4], .little);
                const value_len = std.mem.readInt(u64, header[4..12], .little);
                const length = std.math.add(u64, key_len, value_len) catch return error.InvalidMetadataHACheckpoint;
                if (key_len == 0 or length > metadata_hot_standby.max_row_bytes or length > size_bytes - offset) return error.InvalidMetadataHACheckpoint;
                const bytes = try self.alloc.alloc(u8, @intCast(length));
                defer self.alloc.free(bytes);
                if (try file.readPositionalAll(io, bytes, offset) != bytes.len) return error.InvalidMetadataHACheckpoint;
                const key = bytes[0..key_len];
                if (std.mem.eql(u8, key, metadata_hot_standby.outbox_key)) return error.MetadataHAOutboxPending;
                if (previous) |before| if (!std.mem.lessThan(u8, before, key)) return error.InvalidMetadataHACheckpoint;
                const next_key = try self.alloc.dupe(u8, key);
                if (previous) |before| self.alloc.free(before);
                previous = next_key;
                try txn.put(key, bytes[key_len..]);
                offset += length;
                batch_bytes += bytes.len;
            }
            try self.commitUntrackedRelationTxn(&txn);
            committed = true;
        }
        var extra: [1]u8 = undefined;
        if (try file.readPositionalAll(io, &extra, offset) != 0) return error.InvalidMetadataHACheckpoint;
        {
            var read = try self.store.beginReadTxn();
            defer read.abort();
            try verifyRelationCheckpointTxn(self.alloc, &read);
        }
        try self.store.sync(true);
    }

    pub fn migrateStandaloneRestoreJobs(self: *RaftApplyStore, rows: []const RestoreJobRow) !void {
        const marker = "\x00\x00__metadata__:standalone_restore_jobs_migrated";
        self.apply_mutex.lockUncancelable(self.io_impl.io());
        defer self.apply_mutex.unlock(self.io_impl.io());
        if (self.hasHotStandbyMirror()) return error.MetadataHAMigrationAfterBinding;
        var outcome = CommittedApplyOutcome{ .alloc = self.alloc, .collect_transition_deltas = false };
        defer outcome.deinit();
        std.debug.assert(self.active_outcome == null);
        self.active_outcome = &outcome;
        defer self.active_outcome = null;
        var txn = try self.store.beginWriteTxn();
        var committed = false;
        defer if (!committed) txn.abort();
        if (try stagingGet(&txn, marker) != null) return;
        for (rows) |row| {
            const group_id = @import("antfly_local_sources").common_group_ids.main_metadata_group_id;
            var key_buf: [256]u8 = undefined;
            const key = try restoreJobKeyForGroup(&key_buf, group_id, row.key);
            if (try stagingGet(&txn, key)) |existing| {
                if (!std.mem.eql(u8, existing, row.value)) return error.RestoreJobMigrationConflict;
            } else try self.applyTransitionCommandTxn(&txn, group_id, .{ .create_restore_job = .{ .key = row.key, .value = row.value } });
        }
        try txn.put(marker, "1");
        try advanceStandaloneRevision(&txn);
        try self.commitStandaloneTxn(&txn, &outcome, &committed);
    }

    /// The standalone embedding uses the same transactional catalog and
    /// lifecycle admission as clustered metadata, without a consensus log.
    /// Its auxiliary extension projection is committed with the indexed
    /// tables/ranges; after restore publication those indexes are authoritative.
    pub fn loadStandaloneCatalog(self: *RaftApplyStore, alloc: std.mem.Allocator) !?[]u8 {
        return self.store.get(alloc, standalone_catalog_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
    }

    pub fn loadStandaloneCatalogSnapshot(self: *RaftApplyStore, alloc: std.mem.Allocator) !?[]u8 {
        return self.standaloneCatalogSnapshot(alloc);
    }

    pub fn exportStandalonePortableCatalog(self: *RaftApplyStore, alloc: std.mem.Allocator) ![]u8 {
        return self.exportSystemCatalog(alloc, group_ids.main_metadata_group_id);
    }

    fn standaloneCatalogSnapshot(self: *RaftApplyStore, alloc: std.mem.Allocator) !?[]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const bytes = (try stagingGet(&txn, standalone_catalog_key)) orelse return null;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const auxiliary = try std.json.parseFromSliceLeaky(StandaloneCatalogAuxiliary, a, bytes, .{ .ignore_unknown_fields = true });
        const revision = (try stagingGet(&txn, standalone_revision_key)) orelse return error.InvalidStandaloneCatalog;
        if (revision.len != 8) return error.InvalidStandaloneCatalog;
        const group = group_ids.main_metadata_group_id;
        var logical = try system_catalog_storage.loadState(a, &txn, group);
        defer logical.deinit();
        return try std.json.Stringify.valueAlloc(alloc, @import("../../system_catalog/projection.zig").Export{
            .epoch = std.mem.readInt(u64, revision[0..8], .little),
            .tables = try self.listTablesTxn(a, &txn, group),
            .ranges = try self.listRangesTxn(a, &txn, group),
            .system_catalog = logical.value,
            // This is the live manager projection, not a portable export.
            // In-flight publications must remain reloadable between their
            // durable phase commits; immutable programs stay in this store
            // and are fetched by exact table/generation/phase on install.
            .policy_install_snapshots = &.{},
            .extension_packages = auxiliary.extension_packages,
            .installed_extensions = auxiliary.installed_extensions,
            .extension_members = auxiliary.extension_members,
            .extension_dependencies = auxiliary.extension_dependencies,
        }, .{});
    }

    pub fn standaloneRevision(self: *RaftApplyStore) !u64 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const raw = (try stagingGet(&txn, standalone_revision_key)) orelse return 0;
        if (raw.len != 8) return error.InvalidStandaloneCatalog;
        return std.mem.readInt(u64, raw[0..8], .little);
    }

    pub const StandaloneRevisionState = apply_contract.StandaloneRevisionState;

    pub fn standaloneRevisionState(self: *RaftApplyStore) !StandaloneRevisionState {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const raw = try stagingGet(&txn, standalone_revision_key);
        if (raw != null and raw.?.len != 8) return error.InvalidStandaloneCatalog;
        const revision = if (raw) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else 0;
        const projection_raw = try stagingGet(&txn, standalone_projection_revision_key);
        if (projection_raw != null and projection_raw.?.len != 8) return error.InvalidStandaloneCatalog;
        // Catalogs predating the watermark must reconcile conservatively.
        const projection_revision = if (projection_raw) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else revision;
        if (projection_revision > revision) return error.InvalidStandaloneCatalog;
        return .{ .revision = revision, .projection_revision = projection_revision };
    }

    fn advanceStandaloneRevision(txn: *docstore.DocStore.Txn) !void {
        try advanceStandaloneRevisionWithProjection(txn, true);
    }

    fn advanceStandaloneRevisionWithProjection(txn: *docstore.DocStore.Txn, changes_projection: bool) !void {
        const raw = try stagingGet(txn, standalone_revision_key);
        if (raw != null and raw.?.len != 8) return error.InvalidStandaloneCatalog;
        const previous = if (raw) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else 0;
        const projection_raw = try stagingGet(txn, standalone_projection_revision_key);
        if (projection_raw != null and projection_raw.?.len != 8) return error.InvalidStandaloneCatalog;
        const projection_revision = if (projection_raw) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else previous;
        if (projection_revision > previous) return error.InvalidStandaloneCatalog;
        const next = std.math.add(u64, previous, 1) catch return error.InvalidStandaloneCatalog;
        var encoded: [8]u8 = undefined;
        std.mem.writeInt(u64, &encoded, next, .little);
        try txn.put(standalone_revision_key, &encoded);
        if (changes_projection or projection_raw == null) {
            std.mem.writeInt(u64, &encoded, if (changes_projection) next else projection_revision, .little);
            try txn.put(standalone_projection_revision_key, &encoded);
        }
    }

    pub fn applyStandaloneCommand(self: *RaftApplyStore, group_id: u64, command: TransitionCommand) !void {
        try validateTransitionCommandSchemaReaderRequirements(command);
        if (command == .compare_and_replace_table and command.compare_and_replace_table.relation_guard != null)
            try validateTransitionCommandDataGroupIds(command);
        var publication: ?RelationPublicationProof = null;
        var page: ?relation_reconciliation.Page = null;
        var failure: ?relation_reconciliation.FailurePlan = null;
        defer if (page) |*value| value.deinit();
        var garbage: ?relation_reconciliation.GarbagePage = null;
        defer if (garbage) |*value| value.deinit();
        if (command == .apply_relation_reconciliation) {
            const intent = try relation_control.Command.decode(command.apply_relation_reconciliation);
            if (intent == .publish) {
                if (intent.publish.state.group_id != group_id) return error.InvalidRelationReconciliationCommand;
                publication = try self.prepareRequestedRelationPublication(intent.publish);
            }
            if (intent == .advance) {
                if (intent.advance.group_id != group_id) return error.InvalidRelationReconciliationCommand;
                page = self.prepareRelationReconciliationPage(self.alloc, intent.advance) catch |err| blk: {
                    const reason = relation_reconciliation.FailureReason.fromError(err) orelse return err;
                    failure = .{ .before = intent.advance, .reason = reason };
                    break :blk null;
                };
            }
            if (intent == .garbage) {
                if (intent.garbage.generation.group_id != group_id) return error.InvalidRelationReconciliationCommand;
                garbage = try self.prepareRelationGarbagePage(self.alloc, intent.garbage);
            }
        }
        const io = self.io_impl.io();
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        std.debug.assert(self.active_relation_page == null);
        self.active_relation_page = if (page) |*value| value else null;
        defer self.active_relation_page = null;
        std.debug.assert(self.active_relation_failure == null);
        self.active_relation_failure = if (failure) |*value| value else null;
        defer self.active_relation_failure = null;
        std.debug.assert(self.active_relation_garbage == null);
        self.active_relation_garbage = if (garbage) |*value| value else null;
        defer self.active_relation_garbage = null;
        std.debug.assert(self.active_relation_publication == null);
        self.active_relation_publication = if (publication) |*value| value else null;
        defer self.active_relation_publication = null;
        try self.flushHotStandbyOutboxLocked();
        try self.lockHotStandbyTransition();
        var transition_locked = true;
        defer if (transition_locked) self.unlockHotStandbyTransition();
        try self.checkHotStandby();
        var capture = @import("antfly_local_sources").storage_txn_mutation_capture.Capture.init(self.alloc);
        defer capture.deinit();
        var outcome = CommittedApplyOutcome{ .alloc = self.alloc, .collect_transition_deltas = false };
        defer outcome.deinit();
        std.debug.assert(self.active_outcome == null);
        self.active_outcome = &outcome;
        defer self.active_outcome = null;
        var txn = try self.store.beginWriteTxn();
        var committed = false;
        defer if (!committed) txn.abort();
        if (self.hasHotStandbyMirror()) txn.mutation_capture = &capture;
        if (command == .comment_column) {
            const candidate = try self.prepareColumnDescriptionTxn(&txn, group_id, command.comment_column);
            self.alloc.free(candidate);
        }
        if (command == .compare_and_replace_table) if (command.compare_and_replace_table.relation_guard) |guard| {
            try self.validateRelationMutationTxn(&txn, group_id, guard, command.compare_and_replace_table.expected, command.compare_and_replace_table.replacement);
        };
        const index_ack_source_before = if (command == .ack_relational_index_publication)
            try relation_reconciliation.readSourceRevision(&txn, group_id)
        else
            null;
        _ = try self.ensureDerivedCatalogIndexesTxn(&txn, group_id);
        try self.applyTransitionCommandTxn(&txn, group_id, command);
        // Ordinary ACKs preserve the projection. The final cancellation ACK
        // retires the pending name source and must invalidate it atomically.
        // All other and future commands conservatively invalidate projection.
        try advanceStandaloneRevisionWithProjection(&txn, switch (command) {
            .ack_relational_index_publication => index_ack_source_before.? != try relation_reconciliation.readSourceRevision(&txn, group_id),
            .apply_schema_validation, .apply_store_report_update => outcomeChangesCatalog(outcome.projection_signals.items),
            .apply_sql_sequence_counter, .complete_relational_index_source, .accept_relational_index_delivery, .apply_store_root_enrollment => false,
            else => true,
        });
        try self.stageStandaloneHotStandby(&txn, &capture, group_id);
        try self.checkHotStandby();
        try self.commitStandaloneTxnWithImpact(&txn, &outcome, &committed, relationProofNeutralCommand(command));
        self.unlockHotStandbyTransition();
        transition_locked = false;
        try self.flushHotStandbyOutboxLocked();
    }

    pub fn replaceStandaloneCatalog(self: *RaftApplyStore, group_id: u64, expected_revision: u64, tables: []const metadata.TableRecord, ranges: []const metadata.RangeRecord, auxiliary_json: []const u8) !void {
        return self.updateStandaloneCatalog(group_id, expected_revision, .{ .replace = true, .tables = tables, .ranges = ranges, .auxiliary_json = auxiliary_json });
    }

    /// Constant-size preimage check shared by read-only restart observation and
    /// apply. Returned headers never include report membership or components.
    fn checkStandaloneNativeOwnerTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, request: standalone_native_owner.Registration) !?metadata.StoreRecord {
        try request.validate();
        const activation = try self.requireTopologyActivationTxn(txn, group_id, topology_protocol.store_root_enrollment_version);
        if (activation.version < topology_protocol.store_root_enrollment_version) return error.TableTopologyProtocolUpgradeRequired;
        var buf: [256]u8 = undefined;
        const raw_binding = (try stagingGet(txn, try standalone_native_owner.key(&buf, group_id))) orelse return error.StoreRootEnrollmentChanged;
        const binding = standalone_native_owner.decode(raw_binding) catch return error.InvalidCatalogRecord;
        if (!binding.eql(request.binding()) or !std.mem.eql(u8, &activation.incarnation, &request.identity.metadata_incarnation))
            return error.StoreRootEnrollmentChanged;
        const current = try self.loadStoreHeaderTxn(txn, group_id, request.identity.store_id);
        errdefer if (current) |record| metadata_table_manager.freeStore(self.alloc, record);
        if (current) |record| {
            if (record.store_id != request.identity.store_id or record.node_id != request.identity.node_id or
                record.replica_root_incarnation != request.identity.root_incarnation or
                (!std.mem.allEqual(u8, &record.replica_root_public_key, 0) and !std.mem.eql(u8, &record.replica_root_public_key, &request.identity.public_key)))
                return error.StoreRootEnrollmentChanged;
            // Exact lost-reply recovery is harmless; a different reporter
            // requires the signed preimage and cannot steal a newer process.
            if (record.reporter_incarnation == request.reporter_incarnation) {
                if (!std.mem.eql(u8, &record.replica_root_public_key, &request.identity.public_key)) return error.StoreRootEnrollmentChanged;
                if (!std.meta.eql(record.schema_reader, request.schema_reader) or
                    record.artifact_sources_protocol_version != request.artifact_sources_protocol_version or
                    record.native_generation_restore_version != request.native_generation_restore_version or
                    record.dense_native_storage_protocol_version != request.dense_native_storage_protocol_version or
                    record.relational_topology_protocol_version != request.relational_topology_protocol_version) return error.GenerationPublicationChanged;
                return current;
            }
            if (request.expected_reporter_incarnation == null or request.expected_reporter_incarnation.? != record.reporter_incarnation)
                return error.GenerationPublicationChanged;
        } else if (request.expected_reporter_incarnation != null) return error.GenerationPublicationChanged;
        return current;
    }

    /// Observe restart obligations without staging a command or walking old
    /// report membership. This does not authorize reporter turnover: the old
    /// registration writer still needs bounded namespace retirement and an
    /// exclusive physical-owner startup lease before automatic activation.
    pub fn observeStandaloneNativeReporter(self: *RaftApplyStore, group_id: u64, request: standalone_native_owner.Registration) !standalone_native_owner.RestartObservation {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return self.observeStandaloneNativeReporterTxn(&txn, group_id, request);
    }

    fn observeStandaloneNativeReporterTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, request: standalone_native_owner.Registration) !standalone_native_owner.RestartObservation {
        const current = try self.checkStandaloneNativeOwnerTxn(txn, group_id, request);
        defer if (current) |record| metadata_table_manager.freeStore(self.alloc, record);
        const state = try baselineStateTxn(self.alloc, txn, group_id, request.identity.store_id);
        try state.validateRestartObservation();
        const root_enrolled = enrolled: {
            self.requireStoreRootEnrollmentTxn(txn, group_id, request.identity) catch |err| switch (err) {
                error.StoreRootEnrollmentChanged => break :enrolled false,
                else => return err,
            };
            break :enrolled true;
        };
        const raw_revision = try txn.get(standalone_revision_key);
        if (raw_revision.len != 8) return error.InvalidStandaloneCatalog;
        return .{
            .revision = std.mem.readInt(u64, raw_revision[0..8], .little),
            .request_digest = try request.message(),
            .header_digest = if (current) |record| try reportHeaderDigest(self.alloc, record) else null,
            .baseline_digest = try store_report_baseline.reportDigest(state),
            .reporter_matches = if (current) |record| record.reporter_incarnation == request.reporter_incarnation else false,
            .root_enrolled = root_enrolled,
            .replication_pending = try stagingGet(txn, metadata_hot_standby.outbox_key) != null,
            .active = state.active,
            .pending = if (state.upload) |upload| upload.cursor else null,
            .retired = state.garbage,
            .gc_page = state.gc_page,
            .gc_fragment = state.gc_fragment,
            .gc_fragment_end = state.gc_fragment_end,
        };
    }

    const NativeRestartRecord = struct {
        version: u8 = 1,
        request: standalone_native_owner.Registration,
        baseline: BaselineState,
        frozen_header: ?[32]u8,
        phase: enum { retired, upload, active, install } = .retired,
        page: usize = 0,
        fragment: u32 = 0,
        fragment_end: u32 = 0,
    };

    fn nativeRestartDigest(bytes: []const u8) [32]u8 {
        var result: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(bytes, &result, .{});
        return result;
    }

    fn decodeNativeRestart(a: std.mem.Allocator, bytes: []const u8) !NativeRestartRecord {
        if (bytes.len > 16384) return error.InvalidCatalogRecord;
        var parsed = try std.json.parseFromSlice(NativeRestartRecord, a, bytes, .{});
        defer parsed.deinit();
        const value = parsed.value;
        if (value.version != 1 or value.fragment > value.fragment_end or value.fragment_end > store_report_baseline.max_chunks)
            return error.InvalidCatalogRecord;
        try value.request.validate();
        try value.baseline.validateRestartObservation();
        return value;
    }

    fn requireNativeRestartHeader(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: NativeRestartRecord) !void {
        _ = try self.requireTopologyActivationTxn(txn, group_id, topology_protocol.native_reporter_restart_version);
        const current = try self.checkStandaloneNativeOwnerTxn(txn, group_id, record.request);
        defer if (current) |header| metadata_table_manager.freeStore(self.alloc, header);
        if ((current != null) != (record.frozen_header != null)) return error.GenerationPublicationChanged;
        if (current) |header| if (header.live or !std.mem.eql(u8, &record.frozen_header.?, &try reportHeaderDigest(a, header)))
            return error.GenerationPublicationChanged;
        const baseline = try baselineStateTxn(a, txn, group_id, record.request.identity.store_id);
        if (!std.meta.eql(baseline, record.baseline)) return error.GenerationPublicationChanged;
    }

    /// A partial inventory is not an empty, authoritative inventory. Only this
    /// validated, non-live startup witness permits readers to omit its bodies.
    fn nativeRestartPendingTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, header: metadata.StoreRecord) !bool {
        var buf: [256]u8 = undefined;
        const bytes = (try stagingGet(txn, try standalone_native_owner.restartKey(&buf, group_id, header.store_id))) orelse return false;
        const record = try decodeNativeRestart(a, bytes);
        try self.requireNativeRestartHeader(a, txn, group_id, record);
        return true;
    }

    pub fn standaloneNativeOwnerBinding(self: *RaftApplyStore, group_id: u64) !?standalone_native_owner.Binding {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [256]u8 = undefined;
        const bytes = (try stagingGet(&txn, try standalone_native_owner.key(&key_buf, group_id))) orelse return null;
        return try standalone_native_owner.decode(bytes);
    }

    pub fn nativeReporterRestartProgress(self: *RaftApplyStore, group_id: u64, store_id: u64) !?standalone_native_owner.RestartProgress {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var buf: [256]u8 = undefined;
        const bytes = (try stagingGet(&txn, try standalone_native_owner.restartKey(&buf, group_id, store_id))) orelse return null;
        const record = try decodeNativeRestart(self.alloc, bytes);
        try self.requireNativeRestartHeader(self.alloc, &txn, group_id, record);
        return .{ .request = record.request, .digest = nativeRestartDigest(bytes) };
    }

    fn notifyNativeRestart(self: *RaftApplyStore, group_id: u64, request: standalone_native_owner.Registration) !void {
        var buf: [256]u8 = undefined;
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = try storeKeyForGroup(&buf, group_id, request.identity.store_id) });
        self.notifyProjectionListeners(.{ .kind = .store, .metadata_group_id = group_id, .store_id = request.identity.store_id, .node_id = request.identity.node_id, .store_reports_changed = true, .store_runtime_changed = true });
    }

    fn applyNativeReporterRestartTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, command: standalone_native_owner.Restart) !void {
        try command.request.validate();
        _ = try self.requireTopologyActivationTxn(txn, group_id, topology_protocol.native_reporter_restart_version);
        if (!command.request.schema_reader.known()) return error.SchemaReaderUpgradeRequired;
        if (!try admitSchemaAndTopologyStoreTxn(txn, group_id, .{ .store_id = command.request.identity.store_id, .node_id = command.request.identity.node_id, .reporter_incarnation = command.request.reporter_incarnation, .schema_reader = command.request.schema_reader, .relational_topology_protocol_version = command.request.relational_topology_protocol_version })) return error.SchemaReaderUpgradeRequired;
        if ((command.expected == null) == (command.progress == null)) return error.InvalidStandaloneCatalog;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var buf: [256]u8 = undefined;
        const key = try standalone_native_owner.restartKey(&buf, group_id, command.request.identity.store_id);
        const previous = try stagingGet(txn, key);
        if (previous == null) {
            if (command.progress != null) {
                const observed = try self.observeStandaloneNativeReporterTxn(txn, group_id, command.request);
                if (!observed.reporter_matches) return error.GenerationPublicationChanged;
                return; // Exact lost final reply; no retirement to repeat.
            }
            const expected = command.expected.?;
            const observed = try self.observeStandaloneNativeReporterTxn(txn, group_id, command.request);
            if (!std.meta.eql(expected, observed)) return error.GenerationPublicationChanged;
            if (observed.reporter_matches) return;
            var record: NativeRestartRecord = .{ .request = command.request, .baseline = try baselineStateTxn(a, txn, group_id, command.request.identity.store_id), .frozen_header = null };
            record.page = record.baseline.gc_page;
            record.fragment = record.baseline.gc_fragment;
            record.fragment_end = record.baseline.gc_fragment_end;
            if (try self.loadStoreHeaderTxn(txn, group_id, command.request.identity.store_id)) |current| {
                defer metadata_table_manager.freeStore(self.alloc, current);
                var frozen = current;
                frozen.live = false;
                frozen.group_statuses = &.{};
                frozen.runtime_statuses = &.{};
                record.frozen_header = try reportHeaderDigest(a, frozen);
                var header_buf: [256]u8 = undefined;
                try txn.put(try storeKeyForGroup(&header_buf, group_id, current.store_id), try std.mem.concat(a, u8, &.{ store_header_magic, try encodeStoreRecord(a, frozen) }));
            }
            try txn.put(key, try std.json.Stringify.valueAlloc(a, record, .{}));
            try self.notifyNativeRestart(group_id, command.request);
            return;
        }
        var record = try decodeNativeRestart(a, previous.?);
        if (!std.mem.eql(u8, &try record.request.message(), &try command.request.message())) return error.GenerationPublicationChanged;
        try self.requireNativeRestartHeader(a, txn, group_id, record);
        if (command.expected != null) return; // Repeated BEGIN cannot rewind work.
        if (!std.mem.eql(u8, &command.progress.?, &nativeRestartDigest(previous.?))) return error.GenerationPublicationChanged;
        const store_id = command.request.identity.store_id;
        const generation: ?store_report_baseline.Generation = switch (record.phase) {
            .retired => record.baseline.garbage,
            .upload => if (record.baseline.upload) |upload| .{ .incarnation = upload.cursor.reporter_incarnation, .sequence = upload.cursor.sequence } else null,
            .active => record.baseline.active,
            .install => null,
        };
        if (generation) |address| {
            const complete = try collectReportGenerationPageTxn(a, txn, group_id, store_id, address, &record.page, &record.fragment, record.fragment_end);
            if (record.fragment == record.fragment_end) {
                record.fragment = 0;
                record.fragment_end = 0;
            }
            if (!complete) {
                try txn.put(key, try std.json.Stringify.valueAlloc(a, record, .{}));
                return;
            }
        }
        switch (record.phase) {
            .retired => {
                record.phase = .upload;
                record.page = 0;
                if (record.baseline.upload) |upload| {
                    record.fragment = upload.fragment_start;
                    record.fragment_end = std.math.add(u32, upload.fragment_start, upload.fragment_count) catch return error.InvalidCatalogRecord;
                    if (record.fragment_end > store_report_baseline.max_chunks) return error.InvalidCatalogRecord;
                }
            },
            .upload => {
                record.phase = .active;
                record.page = 0;
                record.fragment = 0;
                record.fragment_end = 0;
            },
            .active => {
                record.phase = .install;
                record.page = 0;
            },
            .install => {
                // All old namespaces are gone. Registration's ordinary writer
                // now has no inventory to materialize, regardless of table count.
                try txn.delete(try baselineKey(a, group_id, store_id));
                try txn.delete(try reportCursorKey(a, group_id, store_id));
                try txn.delete(key);
                try self.registerStandaloneNativeOwnerTxn(txn, group_id, command.request);
                return;
            },
        }
        try txn.put(key, try std.json.Stringify.valueAlloc(a, record, .{}));
    }

    fn registerStandaloneNativeOwnerTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, request: standalone_native_owner.Registration) !void {
        const current = try self.checkStandaloneNativeOwnerTxn(txn, group_id, request);
        defer if (current) |record| metadata_table_manager.freeStore(self.alloc, record);
        if (current) |record| if (record.reporter_incarnation == request.reporter_incarnation) return;
        var replacement: metadata.StoreRecord = current orelse .{ .store_id = request.identity.store_id, .node_id = request.identity.node_id };
        replacement.reporter_incarnation = request.reporter_incarnation;
        replacement.schema_reader = request.schema_reader;
        replacement.artifact_sources_protocol_version = request.artifact_sources_protocol_version;
        replacement.native_generation_restore_version = request.native_generation_restore_version;
        replacement.dense_native_storage_protocol_version = request.dense_native_storage_protocol_version;
        replacement.relational_topology_protocol_version = request.relational_topology_protocol_version;
        replacement.replica_root_incarnation = request.identity.root_incarnation;
        replacement.replica_root_public_key = request.identity.public_key;
        replacement.status_generation = 0;
        replacement.group_statuses = &.{};
        replacement.runtime_statuses = &.{};
        replacement.live = true;
        // This primitive accepts only an empty inventory. Production restart
        // retires populated namespaces through its durable cursor first.
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const baseline = try baselineStateTxn(a, txn, group_id, request.identity.store_id);
        try baseline.validateRestartObservation();
        if (baseline.garbage != null or baseline.upload != null) return error.StoreReportBaseMismatch;
        const address: ReportAddress = .{ .store_id = replacement.store_id, .generation = baseline.active };
        const members_key = try reportMembershipKey(a, group_id, address);
        if (try stagingGet(txn, members_key)) |directory| {
            if (!std.mem.eql(u8, directory, report_members_magic)) return error.StoreReportBaseMismatch;
        }
        if (!try admitSchemaAndTopologyStoreTxn(txn, group_id, replacement)) return error.SchemaReaderUpgradeRequired;
        var incarnation_buf: [256]u8 = undefined;
        const incarnation = try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&incarnation_buf, group_id)));
        if (incarnation.dense_native_storage_protocol_activated_version != 0 and
            !metadata_table_manager.denseNativeStorageProtocolSupported(replacement.reporter_incarnation, replacement.dense_native_storage_protocol_version)) return error.SchemaReaderUpgradeRequired;
        // Advertising one native implementation does not prove a Raft rollout
        // cohort. Do not activate a cluster floor or enumerate other stores.
        try txn.delete(members_key);
        try txn.delete(try reportSlotsKey(a, group_id, address));
        if (address.generation.sequence != 0) try txn.delete(try address.key(a, group_id, "header", 0));
        try txn.delete(try baselineKey(a, group_id, replacement.store_id));
        try txn.delete(try reportCursorKey(a, group_id, replacement.store_id));
        try txn.put(try reportMembershipKey(a, group_id, replacement.store_id), report_members_magic);
        var header_buf: [256]u8 = undefined;
        try txn.put(try storeKeyForGroup(&header_buf, group_id, replacement.store_id), try std.mem.concat(a, u8, &.{ store_header_magic, try encodeStoreRecord(a, replacement) }));
        try self.notifyNativeRestart(group_id, request);
        const admitted = (try self.loadStoreHeaderTxn(txn, group_id, request.identity.store_id)) orelse return error.StoreRootEnrollmentChanged;
        defer metadata_table_manager.freeStore(self.alloc, admitted);
        if (admitted.node_id != request.identity.node_id or admitted.reporter_incarnation != request.reporter_incarnation or
            admitted.replica_root_incarnation != request.identity.root_incarnation or !std.mem.eql(u8, &admitted.replica_root_public_key, &request.identity.public_key))
            return error.StoreRootEnrollmentChanged;
    }

    pub fn updateStandaloneCatalog(self: *RaftApplyStore, group_id: u64, expected_revision: u64, update: @import("raft_apply_contract.zig").StandaloneCatalogUpdate) !void {
        const tables = update.tables;
        const ranges = update.ranges;
        const io = self.io_impl.io();
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        try self.flushHotStandbyOutboxLocked();
        try self.lockHotStandbyTransition();
        var transition_locked = true;
        defer if (transition_locked) self.unlockHotStandbyTransition();
        try self.checkHotStandby();
        var capture = @import("antfly_local_sources").storage_txn_mutation_capture.Capture.init(self.alloc);
        defer capture.deinit();
        var outcome = CommittedApplyOutcome{ .alloc = self.alloc, .collect_transition_deltas = false };
        defer outcome.deinit();
        std.debug.assert(self.active_outcome == null);
        self.active_outcome = &outcome;
        defer self.active_outcome = null;
        var txn = try self.store.beginWriteTxn();
        var committed = false;
        defer if (!committed) txn.abort();
        if (self.hasHotStandbyMirror()) txn.mutation_capture = &capture;
        // Restart progress owns only point-addressed authority and bounded
        // retirement pages. Lookup-index reconciliation is a separate reader
        // concern; it must not turn a control quantum into a catalog scan.
        if (update.native_restart == null) _ = try self.ensureDerivedCatalogIndexesTxn(&txn, group_id);
        // A bulk edit is one ownership cut, not independently admitted table
        // changes: logical moves and name swaps must see the final proposal.
        const relation_writer = try relationWriterEnabledTxn(&txn, group_id);
        var relation_journal = command_journal.Journal.init(self.alloc, &txn);
        defer relation_journal.deinit();
        if (relation_writer) try relation_journal.attach();
        errdefer if (relation_writer and !committed) {
            self.invalidateProjectedPlacementGroup(group_id);
            _ = self.verified_catalog_groups.remove(group_id);
        };
        const bootstrap = try stagingGet(&txn, standalone_catalog_key) == null;
        const revision = try stagingGet(&txn, standalone_revision_key);
        if (revision != null and revision.?.len != 8) return error.InvalidStandaloneCatalog;
        if (revision == null and !bootstrap) return error.InvalidStandaloneCatalog;
        const current_revision = if (revision) |bytes| std.mem.readInt(u64, bytes[0..8], .little) else 0;
        if (current_revision != expected_revision) return error.TableLifecycleConflict;
        if (update.native_registration != null or update.native_restart != null) {
            // Registration cannot smuggle schema/catalog changes or establish
            // its own physical binding in the same request.
            if (bootstrap or tables.len != 0 or ranges.len != 0 or update.table_replacements.len != 0 or
                update.remove_tables.len != 0 or update.remove_ranges.len != 0 or update.replace or update.native_owner != null or
                update.logical != null or update.auxiliary_json != null or update.import_catalog != null or
                update.setting_command != null or update.policy_command != null or
                (update.native_registration != null and update.native_restart != null)) return error.InvalidStandaloneCatalog;
            if (update.native_restart) |command| try self.applyNativeReporterRestartTxn(&txn, group_id, command) else try self.registerStandaloneNativeOwnerTxn(&txn, group_id, update.native_registration.?);
        }
        if (update.native_owner) |owner| {
            try owner.validate();
            if (bootstrap) return error.InvalidStandaloneNativeOwner;
            var incarnation_buf: [160]u8 = undefined;
            const raw_incarnation = (try stagingGet(&txn, try metadataIncarnationKeyForGroup(&incarnation_buf, group_id))) orelse
                return error.InvalidStandaloneNativeOwner;
            const current_incarnation = try decodeMetadataIncarnationRecord(raw_incarnation);
            if (!std.mem.eql(u8, &current_incarnation.incarnation, &owner.metadata_incarnation))
                return error.StoreRootEnrollmentChanged;
            var owner_buf: [160]u8 = undefined;
            const owner_key = try standalone_native_owner.key(&owner_buf, group_id);
            if (try stagingGet(&txn, owner_key)) |encoded| {
                if (!(try standalone_native_owner.decode(encoded)).eql(owner)) return error.StoreRootEnrollmentChanged;
            } else {
                // A first binding is a standalone bootstrap operation, never
                // retroactive authority for an already locked FK generation.
                if (tables.len != 0 or ranges.len != 0 or update.table_replacements.len != 0 or
                    update.remove_tables.len != 0 or update.remove_ranges.len != 0 or
                    update.logical != null or update.auxiliary_json != null or update.replace) return error.StoreRootEnrollmentChanged;
                var lock_buf: [160]u8 = undefined;
                const prefix = try fk_generation_publication.tableLockPrefix(&lock_buf, group_id);
                var cursor = try txn.openCursor();
                defer cursor.close();
                if (try cursor.seekAtOrAfter(prefix)) |row| if (std.mem.startsWith(u8, row.key, prefix))
                    return error.StoreRootEnrollmentChanged;
                const encoded = try standalone_native_owner.encode(owner);
                try txn.put(owner_key, &encoded);
            }
            outcome.native_owner_proof = owner;
        }
        // Apply explicit bindings before physical rows within this transaction.
        // Otherwise remove_table's automatic unbind advances the logical epoch
        // a second time, defeating the caller's single catalog-generation CAS.
        if (update.logical) |logical| {
            if (bootstrap or update.import_catalog != null or update.setting_command != null or update.policy_command != null) return error.InvalidStandaloneCatalog;
            const meta = try system_catalog_storage.readMeta(self.alloc, &txn, group_id);
            if (meta.revision != logical.previous_revision) return error.CatalogGenerationChanged;
            try self.applySystemCatalogDeltaTxn(self.alloc, &txn, group_id, logical.delta, meta, @splat(0));
        }
        if (update.setting_command) |command| {
            if (bootstrap or update.import_catalog != null or update.replace or update.policy_command != null) return error.InvalidStandaloneCatalog;
            const bytes = try std.json.Stringify.valueAlloc(self.alloc, command, .{});
            defer self.alloc.free(bytes);
            if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
            var hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
            try system_catalog_storage.applySettingCommand(self.alloc, &txn, group_id, command, hash);
            const observed = try system_catalog_storage.readMeta(self.alloc, &txn, group_id);
            if (observed.revision != command.expected_revision + 1 or !std.mem.eql(u8, &observed.last_command, &hash)) return error.CatalogGenerationChanged;
        }
        if (update.policy_command) |command| {
            if (bootstrap or update.import_catalog != null or update.replace) return error.InvalidStandaloneCatalog;
            const bytes = try std.json.Stringify.valueAlloc(self.alloc, command, .{});
            defer self.alloc.free(bytes);
            if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
            var hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
            try system_catalog_storage.applyPolicyCommand(self.alloc, &txn, group_id, command, hash);
            const observed = try system_catalog_storage.readMeta(self.alloc, &txn, group_id);
            if (observed.revision != command.expected_revision + 1 or !std.mem.eql(u8, &observed.last_command, &hash)) return error.CatalogGenerationChanged;
        }
        const old_tables = if (update.replace) try self.listTablesTxn(self.alloc, &txn, group_id) else try self.alloc.alloc(metadata.TableRecord, 0);
        defer self.freeTables(self.alloc, old_tables);
        const old_ranges = if (update.replace) try self.listRangesTxn(self.alloc, &txn, group_id) else try self.alloc.alloc(metadata.RangeRecord, 0);
        defer self.freeRanges(self.alloc, old_ranges);
        for (old_ranges) |old| {
            for (ranges) |record| if (record.group_id == old.group_id) break else {} else {
                try self.applyTransitionCommandTxn(&txn, group_id, .{ .remove_range = .{ .group_id = old.group_id } });
                var key_buf: [160]u8 = undefined;
                if (try stagingGet(&txn, try rangeKeyForGroup(&key_buf, group_id, old.group_id)) != null) return error.TableLifecycleConflict;
            }
        }
        for (old_tables) |old| {
            for (tables) |record| if (record.table_id == old.table_id) break else {} else {
                const fence = try self.loadTableTransitionFenceTxn(&txn, group_id, old.table_id);
                try self.removeTableTxn(&txn, group_id, old.table_id, fence.generation);
            }
        }
        for (update.remove_ranges) |id| {
            try self.applyTransitionCommandTxn(&txn, group_id, .{ .remove_range = .{ .group_id = id } });
            var key_buf: [160]u8 = undefined;
            if (try stagingGet(&txn, try rangeKeyForGroup(&key_buf, group_id, id)) != null) return error.TableLifecycleConflict;
        }
        for (update.remove_tables) |id| {
            const fence = try self.loadTableTransitionFenceTxn(&txn, group_id, id);
            try self.removeTableTxn(&txn, group_id, id, fence.generation);
        }
        // A one-time import trusts the already durable local catalog and loads
        // all definitions before FK validation; ordinary edits use exact same
        // admission gates as replicated DDL and verify every no-op outcome.
        for (tables) |record| {
            var key_buf: [160]u8 = undefined;
            const key = try tableKeyForGroup(&key_buf, group_id, record.table_id);
            const before = try stagingGet(&txn, key);
            if (before) |bytes| {
                const old = try decodeTableRecord(self.alloc, bytes);
                defer metadata_table_manager.freeTable(self.alloc, old);
                if (metadata_table_manager.tableDefinitionsEqual(old, record)) continue;
            }
            if (bootstrap) try self.putTableRecordTxn(&txn, group_id, key, record) else try self.applyTableUpsertTxn(&txn, group_id, record);
            const actual = try decodeTableRecord(self.alloc, (try stagingGet(&txn, key)) orelse return error.TableLifecycleConflict);
            defer metadata_table_manager.freeTable(self.alloc, actual);
            var projection_arena = std.heap.ArenaAllocator.init(self.alloc);
            defer projection_arena.deinit();
            const projected = try self.projectResolverNamespacesTxn(projection_arena.allocator(), &txn, group_id, record);
            if (!metadata_table_manager.tableDefinitionsEqual(actual, projected)) return error.TableLifecycleConflict;
        }
        for (update.table_replacements) |change| {
            if (bootstrap or update.replace or change.expected.table_id != change.replacement.table_id) return error.InvalidStandaloneCatalog;
            var key_buf: [160]u8 = undefined;
            const key = try tableKeyForGroup(&key_buf, group_id, change.expected.table_id);
            const before = try decodeTableRecord(self.alloc, (try stagingGet(&txn, key)) orelse return error.TableGenerationChanged);
            defer metadata_table_manager.freeTable(self.alloc, before);
            if (!metadata_table_manager.tableDefinitionsEqual(before, change.expected)) return error.TableGenerationChanged;
            // Reuse replicated lifecycle admission, including owner coverage,
            // dependencies and topology fences. A rejected CAS aborts the whole
            // local transaction, including its logical delta and standby record.
            if (!try self.tryApplyTableCompareAndReplaceTxn(&txn, group_id, change.expected, change.replacement))
                return error.TableLifecycleConflict;
            const actual = try decodeTableRecord(self.alloc, (try stagingGet(&txn, key)) orelse return error.TableLifecycleConflict);
            defer metadata_table_manager.freeTable(self.alloc, actual);
            var projection_arena = std.heap.ArenaAllocator.init(self.alloc);
            defer projection_arena.deinit();
            const projected = try self.projectResolverNamespacesTxn(projection_arena.allocator(), &txn, group_id, change.replacement);
            if (!metadata_table_manager.tableDefinitionsEqual(actual, projected)) return error.TableLifecycleConflict;
        }
        for (ranges) |record| {
            var key_buf: [160]u8 = undefined;
            const key = try rangeKeyForGroup(&key_buf, group_id, record.group_id);
            if (try stagingGet(&txn, key)) |bytes| {
                const old = try decodeRangeRecord(self.alloc, bytes);
                defer metadata_table_manager.freeRange(self.alloc, old);
                if (metadata_table_manager.rangeRecordsEqual(old, record)) continue;
            }
            try self.applyTransitionCommandTxn(&txn, group_id, .{ .upsert_range = record });
            const actual = try decodeRangeRecord(self.alloc, (try stagingGet(&txn, key)) orelse return error.TableLifecycleConflict);
            defer metadata_table_manager.freeRange(self.alloc, actual);
            if (!metadata_table_manager.rangeRecordsEqual(actual, record)) return error.TableLifecycleConflict;
        }
        if (update.import_catalog) |state| {
            if (!bootstrap or update.logical != null) return error.InvalidStandaloneCatalog;
            try system_catalog_storage.importState(self.alloc, &txn, group_id, state);
            try relation_reconciliation.advanceTrackedSource(&txn, group_id);
        }
        if (update.auxiliary_json) |auxiliary| try txn.put(standalone_catalog_key, auxiliary);
        if (bootstrap and update.auxiliary_json == null) return error.InvalidStandaloneCatalog;
        if (relation_writer) {
            try self.publishCapturedRelationsTxn(&txn, group_id, &relation_journal);
            try relation_journal.accept();
        }
        try advanceStandaloneRevisionWithProjection(&txn, update.native_registration == null and update.native_restart == null);
        try self.stageStandaloneHotStandby(&txn, &capture, group_id);
        try self.checkHotStandby();
        self.commitStandaloneTxn(&txn, &outcome, &committed) catch |err| {
            // Only this transaction's commit establishes an ambiguous write.
            // A concurrent revision advance or an outbox preflight failure
            // must not turn a rejected proposal into a committed mutation.
            if (committed) return error.MetadataMutationOutcomeUnknown;
            return err;
        };
        self.unlockHotStandbyTransition();
        transition_locked = false;
        // Local commit and sync succeeded. Failure to publish/acknowledge its
        // outbox must preserve the committed catalog without poisoning local
        // durability or admitting a subsequent mutation past that outbox.
        self.flushHotStandbyOutboxLocked() catch return error.MetadataReplicationPending;
    }

    fn commitUntrackedRelationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn) !void {
        self.invalidateRelationProofTracking();
        defer self.invalidateRelationProofTracking();
        try txn.commit();
    }

    fn commitStandaloneTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, outcome: *CommittedApplyOutcome, committed: *bool) !void {
        return self.commitStandaloneTxnWithImpact(txn, outcome, committed, false);
    }

    fn commitStandaloneTxnWithImpact(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, outcome: *CommittedApplyOutcome, committed: *bool, neutral: bool) !void {
        if (outcome.failure) |err| return err;
        self.beginProjectionCommitBarriers(outcome);
        defer self.endProjectionCommitBarriers(outcome);
        if (neutral) try txn.commit() else try self.commitUntrackedRelationTxn(txn);
        committed.* = true;
        self.active_outcome = null;
        self.dispatchCommittedOutcome(outcome);
        try self.store.sync(true);
    }

