    pub fn listSplitTransitions(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]metadata.SplitTransitionRecord {
        var prefix_buf: [128]u8 = undefined;
        const prefix = try splitTransitionPrefixForGroup(&prefix_buf, group_id);
        const kvs = try self.store.scanPrefix(alloc, prefix);
        defer {
            for (kvs) |kv| {
                alloc.free(kv.key);
                alloc.free(kv.value);
            }
            alloc.free(kvs);
        }

        const out = try alloc.alloc(metadata.SplitTransitionRecord, kvs.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |record|
                metadata_table_manager.freeSplitTransitionRecord(alloc, record);
            alloc.free(out);
        }

        for (kvs, 0..) |kv, i| {
            out[i] = try decodeSplitTransitionRecord(alloc, kv.value);
            initialized += 1;
        }
        return out;
    }

    pub fn listPlacementIntents(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]raft_reconciler.PlacementIntent {
        // The in-memory placement projection is updated while a committed
        // batch holds apply_mutex. Clone it under the same lock so background
        // snapshot readers cannot copy an intent while apply frees/replaces
        // its owned bootstrap strings.
        const io = self.io_impl.io();
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        try self.ensurePlacementIntentsLoaded(alloc, group_id);

        var count: usize = 0;
        for (self.projected_placement_intents.items) |entry| {
            if (entry.metadata_group_id == group_id) count += 1;
        }

        const out = try alloc.alloc(raft_reconciler.PlacementIntent, count);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |intent| freePlacementIntent(alloc, intent);
            alloc.free(out);
        }

        for (self.projected_placement_intents.items) |entry| {
            if (entry.metadata_group_id != group_id) continue;
            out[initialized] = try clonePlacementIntent(alloc, entry.intent);
            initialized += 1;
        }
        return out;
    }

    pub fn listPlacementVersionFences(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        group_id: u64,
    ) ![]metadata_reconciler.PlacementVersionFence {
        var prefix_buf: [160]u8 = undefined;
        const prefix = try placementVersionPrefixForGroup(&prefix_buf, group_id);
        const kvs = try self.store.scanPrefix(alloc, prefix);
        defer {
            for (kvs) |kv| {
                alloc.free(kv.key);
                alloc.free(kv.value);
            }
            alloc.free(kvs);
        }

        const out = try alloc.alloc(metadata_reconciler.PlacementVersionFence, kvs.len);
        errdefer alloc.free(out);
        for (kvs, 0..) |kv, i| {
            if (kv.key.len <= prefix.len or kv.value.len != @sizeOf(u64))
                return error.InvalidPlacementVersionFence;
            var parts = std.mem.splitScalar(u8, kv.key[prefix.len..], ':');
            const range_group_id = try std.fmt.parseInt(
                u64,
                parts.next() orelse return error.InvalidPlacementVersionFence,
                10,
            );
            const local_node_id = try std.fmt.parseInt(
                u64,
                parts.next() orelse return error.InvalidPlacementVersionFence,
                10,
            );
            if (parts.next() != null) return error.InvalidPlacementVersionFence;
            out[i] = .{
                .group_id = range_group_id,
                .local_node_id = local_node_id,
                .version = std.mem.readInt(u64, kv.value[0..@sizeOf(u64)], .little),
            };
        }
        return out;
    }

    pub fn listLocalPlacementIntents(self: *RaftApplyStore, alloc: std.mem.Allocator, metadata_group_id: u64, local_node_id: u64) ![]raft_reconciler.PlacementIntent {
        const io = self.io_impl.io();
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        try self.ensurePlacementIntentsLoaded(alloc, metadata_group_id);

        var count: usize = 0;
        for (self.projected_placement_intents.items) |entry| {
            if (entry.metadata_group_id != metadata_group_id) continue;
            if (entry.intent.record.local_node_id != local_node_id) continue;
            count += 1;
        }

        const out = try alloc.alloc(raft_reconciler.PlacementIntent, count);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |intent| freePlacementIntent(alloc, intent);
            alloc.free(out);
        }

        for (self.projected_placement_intents.items) |entry| {
            if (entry.metadata_group_id != metadata_group_id) continue;
            if (entry.intent.record.local_node_id != local_node_id) continue;
            out[initialized] = try clonePlacementIntent(alloc, entry.intent);
            initialized += 1;
        }
        return out;
    }

    pub fn freePlacementIntents(_: *RaftApplyStore, alloc: std.mem.Allocator, intents: []raft_reconciler.PlacementIntent) void {
        for (intents) |intent| {
            freePlacementIntent(alloc, intent);
        }
        alloc.free(intents);
    }

    fn ensurePlacementIntentsLoaded(self: *RaftApplyStore, alloc: std.mem.Allocator, metadata_group_id: u64) !void {
        if (self.loaded_placement_groups.contains(metadata_group_id)) return;

        var prefix_buf: [128]u8 = undefined;
        const prefix = try placementPrefixForGroup(&prefix_buf, metadata_group_id);
        const kvs = try self.store.scanPrefix(alloc, prefix);
        defer {
            for (kvs) |kv| {
                alloc.free(kv.key);
                alloc.free(kv.value);
            }
            alloc.free(kvs);
        }

        for (kvs) |kv| {
            const intent = try decodePlacementIntent(alloc, kv.value);
            defer freePlacementIntent(alloc, intent);
            try self.upsertProjectedPlacementIntent(metadata_group_id, intent);
        }
        try self.loaded_placement_groups.put(self.alloc, metadata_group_id, {});
    }

    fn upsertProjectedPlacementIntent(self: *RaftApplyStore, metadata_group_id: u64, intent: raft_reconciler.PlacementIntent) !void {
        for (self.projected_placement_intents.items) |*entry| {
            if (entry.metadata_group_id != metadata_group_id) continue;
            if (entry.intent.record.group_id != intent.record.group_id) continue;
            if (entry.intent.record.local_node_id != intent.record.local_node_id) continue;
            freePlacementIntent(self.alloc, entry.intent);
            entry.* = .{
                .metadata_group_id = metadata_group_id,
                .intent = try clonePlacementIntent(self.alloc, intent),
            };
            return;
        }
        try self.projected_placement_intents.append(self.alloc, .{
            .metadata_group_id = metadata_group_id,
            .intent = try clonePlacementIntent(self.alloc, intent),
        });
    }

    fn removeProjectedPlacementIntent(self: *RaftApplyStore, metadata_group_id: u64, range_group_id: u64, local_node_id: u64) void {
        for (self.projected_placement_intents.items, 0..) |entry, i| {
            if (entry.metadata_group_id != metadata_group_id) continue;
            if (entry.intent.record.group_id != range_group_id) continue;
            if (entry.intent.record.local_node_id != local_node_id) continue;
            freePlacementIntent(self.alloc, entry.intent);
            _ = self.projected_placement_intents.swapRemove(i);
            return;
        }
    }

    pub fn listNodes(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]metadata.NodeRecord {
        var prefix_buf: [128]u8 = undefined;
        const prefix = try nodePrefixForGroup(&prefix_buf, group_id);
        const kvs = try self.store.scanPrefix(alloc, prefix);
        defer {
            for (kvs) |kv| {
                alloc.free(kv.key);
                alloc.free(kv.value);
            }
            alloc.free(kvs);
        }

        const out = try alloc.alloc(metadata.NodeRecord, kvs.len);
        errdefer {
            for (out[0..kvs.len]) |record| metadata_table_manager.freeNode(alloc, record);
            alloc.free(out);
        }

        for (kvs, 0..) |kv, i| out[i] = try decodeNodeRecord(alloc, kv.value);
        return out;
    }

    pub fn freeNodes(_: *RaftApplyStore, alloc: std.mem.Allocator, records: []metadata.NodeRecord) void {
        for (records) |record| metadata_table_manager.freeNode(alloc, record);
        alloc.free(records);
    }

    pub fn listStores(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]metadata.StoreRecord {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const rows = try docstore.DocStore.scanPrefixTxn(a, &txn, try listingStorePrefix(a, group_id));
        const out = try alloc.alloc(metadata.StoreRecord, rows.len);
        var filled: usize = 0;
        errdefer {
            for (out[0..filled]) |record| metadata_table_manager.freeStore(alloc, record);
            alloc.free(out);
        }
        for (rows, out) |row, *record| {
            record.* = try self.readStoredStoreTxn(alloc, &txn, group_id, row.value);
            filled += 1;
        }
        return out;
    }

    /// One consistent read of store headers and authoritative group facts.
    /// Report payloads for unrelated groups and all index diagnostics stay in
    /// storage. Work scales with actual reporting replicas, not inventory size.
    pub fn readControlStores(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, groups: []const u64) ![]metadata.StoreRecord {
        var txn = try self.beginIndexedReportRead(group_id);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const rows = try docstore.DocStore.scanPrefixTxn(a, &txn, try listingStorePrefix(a, group_id));
        const headers = try a.alloc(metadata.StoreRecord, rows.len);
        const addresses = try a.alloc(ReportAddress, rows.len);
        const reports = try a.alloc(std.ArrayListUnmanaged(metadata.GroupStatusReport), rows.len);
        @memset(reports, .empty);
        var positions: std.AutoHashMapUnmanaged(u64, usize) = .empty;
        for (rows, headers, addresses, 0..) |row, *header, *address, i| {
            header.* = try decodeStoredHeader(a, row.value);
            address.* = try ReportAddress.active(a, &txn, group_id, header.store_id);
            try positions.put(a, header.store_id, i);
        }
        const Address = struct { store_index: usize, page: u64 };
        var pages: std.AutoHashMapUnmanaged(Address, [2][]const u8) = .empty;
        var selected: std.AutoHashMapUnmanaged(u64, void) = .empty;
        var cursor = try txn.openCursor();
        defer cursor.close();
        for (groups) |id| {
            const entry = try selected.getOrPut(a, id);
            if (entry.found_existing) continue;
            const prefix = try listingReportPrefix(a, group_id, id);
            var row = try cursor.seekAtOrAfter(prefix);
            while (row) |kv| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, kv.key, prefix)) break;
                if (kv.value.len != 16) return error.InvalidCatalogRecord;
                const store_id = std.mem.readInt(u64, kv.value[0..8], .little);
                const i = positions.get(store_id) orelse continue;
                if (!std.mem.eql(u8, kv.key, try listingReportKey(a, group_id, addresses[i], id))) continue;
                const slot = std.mem.readInt(u64, kv.value[8..16], .little);
                const page = try pages.getOrPut(a, .{ .store_index = i, .page = slot / report_page_slots });
                if (!page.found_existing) for (0..2) |component| {
                    page.value_ptr[component] = try txn.get(try reportComponentKey(a, group_id, addresses[i], slot / report_page_slots, component + 2));
                };
                var decoded = try decodeReportComponent(a, try reportPageEntry(page.value_ptr[0], slot), false);
                try applyReportClocks(&decoded, try reportPageEntry(page.value_ptr[1], slot));
                for (decoded.group_statuses) |report| if (report.group_id != id) return error.InvalidCatalogRecord;
                try reports[i].appendSlice(a, decoded.group_statuses);
            }
        }
        const out = try alloc.alloc(metadata.StoreRecord, headers.len);
        var filled: usize = 0;
        errdefer {
            for (out[0..filled]) |record| metadata_table_manager.freeStore(alloc, record);
            alloc.free(out);
        }
        for (headers, reports, out) |header, facts, *record| {
            var value = header;
            value.group_statuses = facts.items;
            value.runtime_statuses = &.{};
            record.* = try metadata_table_manager.cloneStore(alloc, value);
            filled += 1;
        }
        return out;
    }

    pub fn readStore(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, store_id: u64, reports: bool) !?metadata.StoreRecord {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [160]u8 = undefined;
        const bytes = txn.get(try storeKeyForGroup(&key_buf, group_id, store_id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return if (reports) try self.readStoredStoreTxn(alloc, &txn, group_id, bytes) else try decodeStoredHeader(alloc, bytes);
    }

    pub fn readStoreGroupFacts(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, store_id: u64) !?metadata.StoreRecord {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [160]u8 = undefined;
        const bytes = txn.get(try storeKeyForGroup(&key_buf, group_id, store_id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        var record = try self.readStoredStoreComponentsTxn(alloc, arena.allocator(), &txn, group_id, bytes, false);
        metadata_table_manager.freeRuntimeGroupStatusReports(alloc, record.runtime_statuses);
        record.runtime_statuses = &.{};
        return record;
    }

    pub fn freeStores(_: *RaftApplyStore, alloc: std.mem.Allocator, records: []metadata.StoreRecord) void {
        for (records) |record| metadata_table_manager.freeStore(alloc, record);
        alloc.free(records);
    }

