    fn getTableByNameTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, name: []const u8) !?metadata.TableRecord {
        return self.getTableByNameResultTxn(metadata.TableRecord, alloc, txn, group_id, name);
    }

    fn getTableByNameResultTxn(self: *RaftApplyStore, comptime Result: type, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, name: []const u8) !?Result {
        _ = self;
        try requireDerivedCatalogIndexesTxn(txn, group_id);
        var name_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        const encoded_id = txn.get(try tableNameIndexKey(&name_buf, group_id, name)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        if (encoded_id.len != 8) return error.InvalidDerivedCatalogIndex;
        const id = std.mem.readInt(u64, encoded_id[0..8], .little);
        var key_buf: [160]u8 = undefined;
        const bytes = txn.get(try tableKeyForGroup(&key_buf, group_id, id)) catch |err| switch (err) {
            error.NotFound => return error.InvalidDerivedCatalogIndex,
            else => return err,
        };
        const table: Result = if (Result == metadata.TableRecord) try decodeTableRecord(alloc, bytes) else try decodeTableIdentity(alloc, bytes);
        errdefer if (Result == metadata.TableRecord) metadata_table_manager.freeTable(alloc, table) else table.deinit(alloc);
        if (table.table_id != id or !std.mem.eql(u8, table.name, name)) return error.InvalidDerivedCatalogIndex;
        return table;
    }

    pub fn systemCatalogRead(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.Read) ![]u8 {
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = &txn, .group_id = group_id, .meta = try system_catalog_storage.readMeta(a, &txn, group_id) };
        return std.json.Stringify.valueAlloc(alloc, try view.read(request), .{});
    }

    /// Arena-owned rows from one transaction; used by portable export and
    /// scoped listing so neither can join independently captured generations.
    fn catalogRowsTxn(comptime T: type, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, comptime prefixFn: anytype, comptime decode: anytype) ![]T {
        var buf: [192]u8 = undefined;
        const rows = try docstore.DocStore.scanPrefixTxn(alloc, txn, try prefixFn(&buf, group_id));
        const out = try alloc.alloc(T, rows.len);
        for (rows, out) |row, *value| value.* = try decode(alloc, row.value);
        return out;
    }

    fn exportPolicyInstallSnapshotsTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, publications: []const sql_policies.Publication) ![]const sql_policies.InstallSnapshot {
        var snapshots: std.ArrayList(sql_policies.InstallSnapshot) = .empty;
        for (publications) |publication| {
            switch (publication.phase) {
                .disabled => {
                    if (system_catalog_storage.policyPublicationNeedsWork(publication)) return error.RowPolicyCatalogChanged;
                },
                .active => {
                    const installed = try system_catalog_storage.loadServingPolicyInstallSnapshot(alloc, txn, group_id, publication.table_id);
                    if (installed.value.policy_generation != publication.generation or
                        installed.value.catalog_epoch != publication.catalog_epoch or
                        installed.value.phase != .active) return error.RowPolicyCatalogChanged;
                    try snapshots.append(alloc, installed.value);
                },
                else => return error.RowPolicyPublicationInProgress,
            }
        }
        const result = try snapshots.toOwnedSlice(alloc);
        try @import("../../system_catalog/projection.zig").validatePolicyPrograms(alloc, publications, result);
        return result;
    }

    /// Portable catalog exports carry complete authority, rather than native
    /// discovery references whose row store belongs to this metadata instance.
    fn exportResolverTablesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64) ![]metadata.TableRecord {
        const tables = try self.listTablesTxn(a, txn, group);
        var projections: ResolverProjectionCache = .empty;
        for (tables) |*table| {
            // Ordinary SQL/document definitions have no resolver projection to
            // detach. Preserve their exact index bytes and avoid extra parsing.
            if (!topology_protocol.usesResolverRecords(table.indexes_json) and !topology_protocol.usesResolverNamespaces(table.indexes_json)) continue;
            const original_indexes = table.indexes_json;
            table.indexes_json = try self.resolverExecutionIndexesTxn(a, txn, group, table.indexes_json, &projections);
            if (table.indexes_json.len == 0) continue;
            var root = try std.json.parseFromSliceLeaky(std.json.Value, a, table.indexes_json, .{});
            const identities = try resolver_curation.metadataFromValue(a, root);
            // Admission's substring classifier is conservative. An ordinary
            // index name/value can contain those words without owning resolver
            // metadata; never rewrite its descriptor as a side effect.
            if (identities.identities.len == 0 and !root.object.contains(resolver_curation.namespaces_key) and !@import("../resolver_authority.zig").isNative(root)) {
                table.indexes_json = original_indexes;
                continue;
            }
            const detached = try a.dupe(resolver_curation.MetadataIdentity, identities.identities);
            for (detached) |*portable| {
                portable.authority_table_id = 0;
                portable.projection_ref = null;
                portable.revision = @max(@as(u64, 1), portable.revision);
            }
            try root.object.put(a, resolver_curation.metadata_key, try std.json.parseFromSliceLeaky(std.json.Value, a, try std.json.Stringify.valueAlloc(a, resolver_curation.Metadata{ .identities = detached }, .{}), .{}));
            table.indexes_json = try std.json.Stringify.valueAlloc(a, root, .{});
            if (!@import("../resolver_authority.zig").isNative(root)) continue;
            var bridge: NativeResolverTxn = .{ .txn = txn };
            const native = try nativeResolverStore(a, &bridge, group, table.table_id);
            var namespaces: std.ArrayList(resolver_curation.Namespace) = .empty;
            for (try native.heads()) |head| {
                var namespace = (try native.exportNamespace(head.key_template)).?.namespace;
                namespace.record_store = false;
                namespace.revision = @max(@as(u64, 1), namespace.revision);
                namespace.adoption_revision = null;
                namespace.adoption_standalone = false;
                try namespaces.append(a, namespace);
            }
            var proposals: std.ArrayList(@import("antfly_resolver").curation.Proposal) = .empty;
            var after: ?[]const u8 = null;
            while (true) {
                const page = try native.proposalPage(null, null, after, 256);
                try proposals.appendSlice(a, page.proposals);
                after = page.next_cursor;
                if (after == null) break;
            }
            try root.object.put(a, resolver_curation.namespaces_key, try std.json.parseFromSliceLeaky(std.json.Value, a, try std.json.Stringify.valueAlloc(a, resolver_curation.Namespaces{ .namespaces = namespaces.items }, .{}), .{}));
            const queue = @import("antfly_resolver").curation.State{ .receipt_scope = (try native.queueHead()).receipt_scope, .proposals = proposals.items };
            try root.object.put(a, resolver_curation.proposals_key, try std.json.parseFromSliceLeaky(std.json.Value, a, try std.json.Stringify.valueAlloc(a, queue, .{}), .{}));
            _ = root.object.swapRemove(@import("../resolver_authority.zig").marker);
            _ = root.object.swapRemove(@import("../resolver_authority.zig").owners_key);
            table.indexes_json = try std.json.Stringify.valueAlloc(a, root, .{});
        }
        return tables;
    }

    pub fn exportSystemCatalog(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return self.exportSystemCatalogTxn(alloc, &txn, group_id, null);
    }

    /// Staged recovery has authenticated/imported this checkpoint. Return a
    /// projection that STILL requires that artifact, never a portable logical
    /// envelope which could reconstruct counters from sequence definitions.
    pub fn projectHotStandbyCheckpointCatalog(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, checkpoint: metadata_hot_standby.CheckpointArtifact) ![]u8 {
        if (checkpoint.size_bytes < 8) return error.InvalidMetadataHACheckpoint;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        try verifyRelationCheckpointTxn(alloc, &txn);
        return self.exportSystemCatalogTxn(alloc, &txn, group_id, checkpoint);
    }

    fn exportSystemCatalogTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, checkpoint: ?metadata_hot_standby.CheckpointArtifact) ![]u8 {
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var state = try system_catalog_storage.loadState(a, txn, group_id);
        defer state.deinit();
        // Do not publish a definition-only portable envelope which would
        // rewind allocation on import. Binary snapshots carry the full cut.
        if (checkpoint == null) {
            if (state.meta.sequence_outcome_head != null) return error.SequenceCatalogStateRequired;
            for (state.value.resources) |resource| if (resource.kind == .sequence) return error.SequenceCatalogStateRequired;
        }
        const policy_install_snapshots = try exportPolicyInstallSnapshotsTxn(a, txn, group_id, state.value.policy_publications);
        var buf: [160]u8 = undefined;
        // The durable standalone marker owns its revision and extension
        // projection. Physical distributed catalog counters are a different
        // authority: auxiliary/DDL-only edits need not advance them. Capture
        // the correct revision and every payload from this same read txn.
        const auxiliary_bytes = if (group_id == group_ids.main_metadata_group_id) try stagingGet(txn, standalone_catalog_key) else null;
        const auxiliary = if (auxiliary_bytes) |bytes| try std.json.parseFromSliceLeaky(StandaloneCatalogAuxiliary, a, bytes, .{ .ignore_unknown_fields = true }) else null;
        const revision = try stagingGet(txn, if (auxiliary != null) standalone_revision_key else try catalogRevisionKeyForGroup(&buf, group_id));
        const epoch = if (revision) |bytes| if (bytes.len == 8) std.mem.readInt(u64, bytes[0..8], .little) else return error.InvalidCatalogRecord else if (auxiliary != null) return error.InvalidStandaloneCatalog else 1;
        if (auxiliary != null and epoch == 0) return error.InvalidStandaloneCatalog;
        return std.json.Stringify.valueAlloc(alloc, @import("../../system_catalog/projection.zig").Export{
            .epoch = @max(1, epoch),
            .native_checkpoint = checkpoint,
            .system_catalog = state.value,
            .policy_install_snapshots = policy_install_snapshots,
            .tables = if (checkpoint == null) try self.exportResolverTablesTxn(a, txn, group_id) else try self.listTablesTxn(a, txn, group_id),
            .ranges = try self.listRangesTxnUntil(a, txn, group_id, null, null),
            .extension_packages = if (auxiliary) |value| value.extension_packages else try catalogRowsTxn(extension_domain.PackageManifest, a, txn, group_id, extensionPackagePrefixForGroup, decodeExtensionPackageRecord),
            .installed_extensions = if (auxiliary) |value| value.installed_extensions else try catalogRowsTxn(extension_domain.InstalledExtension, a, txn, group_id, installedExtensionPrefixForGroup, decodeInstalledExtensionRecord),
            .extension_members = if (auxiliary) |value| value.extension_members else try catalogRowsTxn(extension_domain.ExtensionMember, a, txn, group_id, extensionMemberPrefixForGroup, decodeExtensionMemberRecord),
            .extension_dependencies = if (auxiliary) |value| value.extension_dependencies else try catalogRowsTxn(extension_domain.ExtensionDependency, a, txn, group_id, extensionDependencyPrefixForGroup, decodeExtensionDependencyRecord),
        }, .{});
    }

    /// One catalog transaction across every namespace, including legacy
    /// default-public bindings. The limit is checked before reading schemas.
    pub fn sqlSnapshotCohort(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, database: []const u8) ![]u8 {
        try system_catalog.validateName(database);
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = &txn, .group_id = group_id, .meta = try system_catalog_storage.readMeta(a, &txn, group_id) };
        const db = (try view.lookup(.database, 0, database)) orelse return error.DatabaseNotFound;
        const namespaces = try view.children(.namespace, db.id, 257);
        if (namespaces.len > 256) return error.SqlProgramLimitExceeded;
        var ids: std.ArrayList(u64) = .empty;
        for (namespaces) |namespace| {
            for (try view.children(.table, namespace.id, 257 - ids.items.len)) |binding| {
                try ids.append(a, binding.id);
                if (ids.items.len > 256) return error.SqlProgramLimitExceeded;
            }
        }
        if (db.id == system_catalog.default_database_id) {
            const prefix = try legacyListingPrefix(a, group_id);
            var cursor = try txn.openCursor();
            defer cursor.close();
            var row = try cursor.seekAtOrAfter(prefix);
            while (row) |kv| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, kv.key, prefix)) break;
                if (kv.value.len != 8) return error.InvalidDerivedCatalogIndex;
                const id = std.mem.readInt(u64, kv.value[0..8], .little);
                if (std.mem.indexOfScalar(u64, ids.items, id) != null) return error.InvalidDerivedCatalogIndex;
                try ids.append(a, id);
                if (ids.items.len > 256) return error.SqlProgramLimitExceeded;
            }
        }
        const Result = @import("../../system_catalog/server_call.zig").SqlSnapshotCohort;
        const tables = try a.alloc(@typeInfo(@FieldType(Result, "tables")).pointer.child, ids.items.len);
        var header_arena = std.heap.ArenaAllocator.init(alloc);
        defer header_arena.deinit();
        for (ids.items, tables) |id, *table| {
            _ = header_arena.reset(.retain_capacity);
            const temporary = header_arena.allocator();
            var buf: [160]u8 = undefined;
            const bytes = try txn.get(try tableKeyForGroup(&buf, group_id, id));
            const header = try borrowTableProjection(bytes, .schema);
            const schema_json = header.query_definition.?.schema_json;
            if (header.table_id != id) return error.InvalidCatalogRecord;
            // A restore has not published a readable cut yet.
            if (header.restore_pending) return error.ReadUnavailable;
            const SchemaHeader = struct { version: u32 = 0, base_source: ?struct { kind: []const u8 } = null };
            const schema_header = if (schema_json.len == 0) SchemaHeader{} else try std.json.parseFromSliceLeaky(SchemaHeader, temporary, schema_json, .{ .ignore_unknown_fields = true });
            table.* = .{ .id = id, .table = try a.dupe(u8, header.name), .schema_version = schema_header.version, .external = if (schema_header.base_source) |source| std.mem.eql(u8, source.kind, "external") else false };
        }
        return std.json.Stringify.valueAlloc(alloc, Result{ .revision = view.meta.revision, .tables = tables }, .{});
    }

    pub fn listSystemCatalogTables(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, input: system_catalog.TableList) ![]u8 {
        var request = input;
        const projection = @import("../../system_catalog/projection.zig");
        try system_catalog.validateName(request.database);
        try system_catalog.validateName(request.namespace);
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = &txn, .group_id = group_id, .meta = try system_catalog_storage.readMeta(a, &txn, group_id) };
        const membership = if (std.mem.eql(u8, request.database, "default") and std.mem.eql(u8, request.namespace, "public")) try legacyMembershipTxn(a, &txn, group_id) else @as([32]u8, @splat(0));
        try projection.checkMembership(request, membership);
        if (request.revision) |revision| if (revision != view.meta.revision) return error.CatalogGenerationChanged;
        if (request.limit) |limit| if (limit == 0 or limit > 1000) return error.InvalidCatalogName;
        var entries: std.ArrayListUnmanaged(projection.TableEntry) = .empty;
        if (request.target) |target| {
            const table = (try self.resolveSystemCatalogResultTxn(metadata.TableRecord, a, &txn, group_id, target)) orelse return error.TableNotFound;
            try entries.append(a, .{ .name = target.table, .table = table });
        } else if (request.physical_name) |name| {
            const table = (try self.getTableByNameTxn(a, &txn, group_id, name)) orelse return error.TableNotFound;
            try entries.append(a, .{ .name = table.name, .table = table });
        } else {
            const namespace = try view.namespaceFor(request.database, request.namespace);
            if (request.after_table_id) |id| {
                if (try view.byId(.table, id)) |binding| {
                    if (binding.parent_id != namespace.id) return error.InvalidCatalogName;
                    request.after = binding.name;
                } else {
                    if (namespace.id != system_catalog.default_namespace_id) return error.CatalogGenerationChanged;
                    var buf: [160]u8 = undefined;
                    const bytes = txn.get(try tableKeyForGroup(&buf, group_id, id)) catch |err| switch (err) {
                        error.NotFound => return error.CatalogGenerationChanged,
                        else => return err,
                    };
                    request.after = (try decodeTableIdentity(a, bytes)).name;
                }
                if (!std.mem.startsWith(u8, request.after.?, request.prefix orelse "")) return error.InvalidCatalogName;
            }
            const count: usize = if (request.limit) |limit| limit + 1 else 0;
            for (try view.childrenPage(.table, namespace.id, count, request.prefix orelse "", request.after)) |binding| {
                try entries.append(a, .{ .name = binding.name, .table = .{ .table_id = binding.id, .name = binding.storage_name } });
            }
            if (namespace.id == system_catalog.default_namespace_id) {
                const base = try legacyListingPrefix(a, group_id);
                const prefix = try std.mem.concat(a, u8, &.{ base, request.prefix orelse "" });
                const after = if (request.after) |name| try std.mem.concat(a, u8, &.{ base, name }) else prefix;
                var cursor = try txn.openCursor();
                defer cursor.close();
                var row = try cursor.seekAtOrAfter(if (std.mem.lessThan(u8, after, prefix)) prefix else after);
                var found: usize = 0;
                while (row) |kv| : (row = try cursor.next()) {
                    if (!std.mem.startsWith(u8, kv.key, prefix)) break;
                    const name = kv.key[base.len..];
                    if (request.after) |previous| if (!std.mem.lessThan(u8, previous, name)) continue;
                    if (kv.value.len != 8) return error.InvalidDerivedCatalogIndex;
                    const id = std.mem.readInt(u64, kv.value[0..8], .little);
                    if (try view.byId(.table, id) != null) return error.InvalidDerivedCatalogIndex;
                    const owned_name = try a.dupe(u8, name);
                    try entries.append(a, .{ .name = owned_name, .table = .{ .table_id = id, .name = owned_name } });
                    found += 1;
                    if (count != 0 and found >= count) break;
                }
            }
        }
        const page = try projection.selectPage(entries.items, request, view.meta.revision);
        if (request.physical_name == null and request.target == null) {
            const lookups = try a.alloc(ListingLookup, page.entries.len);
            for (page.entries, lookups, 0..) |entry, *lookup, i| {
                var buf: [160]u8 = undefined;
                lookup.* = .{ .key = try a.dupe(u8, try tableKeyForGroup(&buf, group_id, entry.table.table_id)), .index = i };
            }
            const values = try readListingKeys(a, &txn, lookups);
            for (lookups, values) |lookup, bytes| {
                const entry = &page.entries[lookup.index];
                const table = try decodeTableRecord(a, bytes orelse return error.InvalidCatalogRecord);
                if (table.table_id != entry.table.table_id or !std.mem.eql(u8, table.name, entry.table.name)) return error.InvalidCatalogRecord;
                entry.table = table;
            }
        }
        var replication: std.ArrayListUnmanaged(metadata.ReplicationSourceStatusRecord) = .empty;
        if (request.target != null or request.physical_name != null) for (page.entries) |entry| {
            const prefix = try std.fmt.allocPrint(a, "\x00\x00__metadata__:metadata_replication_source_status:{d}:{d}:", .{ group_id, entry.table.table_id });
            for (try docstore.DocStore.scanPrefixTxn(a, &txn, prefix)) |row| {
                const status = try decodeReplicationSourceStatusRecord(a, row.value);
                if (status.table_id != entry.table.table_id) return error.InvalidCatalogRecord;
                try replication.append(a, status);
            }
        };
        var ranges: std.ArrayListUnmanaged(metadata.RangeRecord) = .empty;
        var intents: std.ArrayListUnmanaged(raft_reconciler.PlacementIntent) = .empty;
        for (page.entries) |entry| {
            for (try self.indexedTableRangeIdsTxn(a, &txn, group_id, entry.table.table_id)) |id| {
                var buf: [192]u8 = undefined;
                const range = try decodeRangeRecord(a, try txn.get(try rangeKeyForGroup(&buf, group_id, id)));
                if (range.table_id != entry.table.table_id or range.group_id != id) return error.InvalidDerivedCatalogIndex;
                try ranges.append(a, range);
                const prefix = try std.fmt.bufPrint(&buf, "\x00\x00__metadata__:metadata_placement:{d}:{d}:", .{ group_id, id });
                for (try docstore.DocStore.scanPrefixTxn(a, &txn, prefix)) |row| try intents.append(a, try decodePlacementIntent(a, row.value));
            }
        }
        const store_rows = if (ranges.items.len == 0) &.{} else try docstore.DocStore.scanPrefixTxn(a, &txn, try listingStorePrefix(a, group_id));
        const stores = try a.alloc(metadata.StoreRecord, store_rows.len);
        const addresses = try a.alloc(ReportAddress, store_rows.len);
        var store_positions: std.AutoHashMapUnmanaged(u64, usize) = .empty;
        const group_reports = try a.alloc(std.ArrayListUnmanaged(metadata.GroupStatusReport), stores.len);
        const runtime_reports = try a.alloc(std.ArrayListUnmanaged(metadata.RuntimeGroupStatusReport), stores.len);
        @memset(group_reports, .empty);
        @memset(runtime_reports, .empty);
        for (store_rows, stores, 0..) |row, *store, i| {
            store.* = try decodeStoredHeader(a, row.value);
            try store_positions.put(a, store.store_id, i);
            addresses[i] = try ReportAddress.active(a, &txn, group_id, store.store_id);
        }
        // Visit actual reporters instead of the stores x selected-groups product.
        const ReportPageAddress = struct { store_id: u64, page_id: u64 };
        const ReportPageValues = [4][]const u8;
        var report_pages: std.AutoHashMapUnmanaged(ReportPageAddress, ReportPageValues) = .empty;
        var cursor = try txn.openCursor();
        defer cursor.close();
        for (ranges.items) |range| {
            const prefix = try listingReportPrefix(a, group_id, range.group_id);
            var row = try cursor.seekAtOrAfter(prefix);
            while (row) |kv| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, kv.key, prefix)) break;
                if (kv.value.len != 16) return error.InvalidCatalogRecord;
                const store_id = std.mem.readInt(u64, kv.value[0..8], .little);
                const slot = std.mem.readInt(u64, kv.value[8..16], .little);
                const i = store_positions.get(store_id) orelse continue;
                const address = addresses[i];
                if (!std.mem.eql(u8, kv.key, try listingReportKey(a, group_id, address, range.group_id))) continue;
                const cached_report_page = try report_pages.getOrPut(a, .{ .store_id = store_id, .page_id = slot / report_page_slots });
                if (!cached_report_page.found_existing) for (0..4) |component| {
                    cached_report_page.value_ptr[component] = try txn.get(try reportComponentKey(a, group_id, address, slot / report_page_slots, component));
                };
                for ([_]usize{ 0, 2 }) |component| {
                    var report = try decodeReportComponent(a, try reportPageEntry(cached_report_page.value_ptr[component], slot), component == 0);
                    try applyReportClocks(&report, try reportPageEntry(cached_report_page.value_ptr[component + 1], slot));
                    for (report.group_statuses) |item| {
                        if (item.group_id != range.group_id) return error.InvalidCatalogRecord;
                        try group_reports[i].append(a, item);
                    }
                    for (report.runtime_statuses) |item| {
                        if (item.group_id != range.group_id) return error.InvalidCatalogRecord;
                        try runtime_reports[i].append(a, item);
                    }
                }
            }
        }
        for (stores, 0..) |*store, i| {
            store.group_statuses = group_reports[i].items;
            store.runtime_statuses = runtime_reports[i].items;
        }
        return std.json.Stringify.valueAlloc(alloc, projection.TableListing{ .revision = view.meta.revision, .entries = page.entries, .legacy_membership = membership, .next_after = page.next, .next_table_id = if (page.next != null) page.entries[page.entries.len - 1].table.table_id else null, .ranges = ranges.items, .stores = stores, .placement_intents = intents.items, .replication_source_statuses = replication.items }, .{});
    }

    pub fn systemCatalogSnapshot(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) !system_catalog_storage.OwnedState {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return system_catalog_storage.loadState(alloc, &txn, group_id);
    }

    pub const SqlSettingMutationCut = struct {
        arena: std.heap.ArenaAllocator,
        meta: system_catalog_storage.Meta,
        records: []const sql_settings.Record,
        database_exists: bool,
        database_id: ?u64,
        pub fn deinit(self: *@This()) void {
            self.arena.deinit();
            self.* = undefined;
        }
    };

    /// Settings writes do not need the complete table/policy/publication
    /// catalog. Capture only the settings prefix and an optional point-bound
    /// database at one visibility cut under the caller's mutation lane.
    pub fn sqlSettingMutationCut(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, database: ?[]const u8) !SqlSettingMutationCut {
        var arena = std.heap.ArenaAllocator.init(alloc);
        errdefer arena.deinit();
        const a = arena.allocator();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const meta = try system_catalog_storage.readMeta(a, &txn, group_id);
        const records = try system_catalog_storage.loadSettings(a, &txn, group_id);
        var database_exists = true;
        var database_id: ?u64 = null;
        if (database) |name| {
            var found = try system_catalog_storage.find(a, &txn, group_id, .database, 0, name);
            defer if (found) |*value| value.deinit();
            database_exists = found != null or std.mem.eql(u8, name, system_catalog.default_database_name);
            database_id = if (found) |value| value.value.id else if (database_exists) system_catalog.default_database_id else null;
        }
        return .{ .arena = arena, .meta = meta, .records = records, .database_exists = database_exists, .database_id = database_id };
    }

    pub fn sqlSettingSnapshotJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, scope: sql_settings.Scope) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, &txn, group_id);
        const records = try system_catalog_storage.loadSettings(a, &txn, group_id);
        const definitions = try a.alloc(sql_settings.Definition, records.len);
        var bound = scope;
        var database = try system_catalog_storage.find(a, &txn, group_id, .database, 0, scope.database);
        defer if (database) |*value| value.deinit();
        bound.database_id = if (database) |value| value.value.id else if (std.mem.eql(u8, scope.database, system_catalog.default_database_name)) system_catalog.default_database_id else null;
        for (records, definitions) |record, *definition| definition.* = try record.effectiveAlloc(a, bound);
        return std.json.Stringify.valueAlloc(alloc, sql_settings.Snapshot.init(bound, @max(1, meta.revision), definitions), .{});
    }

    pub fn sqlPolicySnapshotJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, table_id: u64, principal: []const u8, database: []const u8, roles: []const []const u8) ![]u8 {
        if (roles.len != 0) return error.RowPolicyAuthenticationRequired;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var serving = try system_catalog_storage.loadServingPolicyInstallSnapshot(a, &txn, group_id, table_id);
        defer serving.deinit();
        return std.json.Stringify.valueAlloc(alloc, sql_policies.Snapshot{
            .table_id = table_id,
            .schema_version = serving.value.schema_version,
            .schema_digest = serving.value.schema_digest,
            .policy_generation = serving.value.policy_generation,
            .catalog_epoch = serving.value.catalog_epoch,
            .principal = principal,
            .database = database,
            .roles = roles,
            .records = serving.value.records,
        }, .{});
    }

    pub fn sqlPolicyInstallSnapshotJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: sql_policies.InstallRequest) ![]u8 {
        if (request.table_id == 0 or request.expected_generation == 0 or request.expected_catalog_epoch == 0) return error.InvalidRowPolicyPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return system_catalog_storage.loadPolicyInstallSnapshotBytes(alloc, &txn, group_id, request);
    }

    pub fn sqlPolicyPublicationStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, table_id: u64) ![]u8 {
        if (table_id == 0) return error.InvalidRowPolicyPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const stamp = (try system_catalog_storage.loadPolicyPublicationStamp(alloc, &txn, group_id, table_id)) orelse {
            // Absence is data, not an unsupported capability or a stale fence.
            // A publication without its transactionally written stamp is corrupt.
            if (try system_catalog_storage.loadPolicyPublication(alloc, &txn, group_id, table_id)) |publication| {
                publication.deinit();
                return error.RowPolicyCatalogChanged;
            }
            return alloc.dupe(u8, "null");
        };
        if (stamp.topology_generation != 0 and
            !std.mem.eql(u8, &stamp.schema_record_digest, &(@as([32]u8, @splat(0)))))
        {
            // Every descriptor/membership change advances this durable fence
            // in the same metadata transaction as the range record. Keep the
            // per-request proof read O(1) in shard count. Begin validates the
            // physical owner cut; later ACKs and promotion validate its
            // transactionally maintained topology and schema fences.
            try self.validatePolicyOwnerStampTxn(&txn, group_id, stamp);
        } else {
            var publication = (try system_catalog_storage.loadPolicyPublication(alloc, &txn, group_id, table_id)) orelse return error.RowPolicyCatalogChanged;
            defer publication.deinit();
            try self.validatePolicyOwnerCutTxn(&txn, group_id, publication.value);
        }
        return std.json.Stringify.valueAlloc(alloc, stamp, .{});
    }

    pub fn sqlPolicyPublicationWorkJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, after_table_id: u64) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const meta = try system_catalog_storage.readMeta(alloc, &txn, group_id);
        var publication = try system_catalog_storage.nextPolicyPublicationWork(alloc, &txn, group_id, after_table_id);
        defer if (publication) |*value| value.deinit();
        return std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationWork{
            .revision = meta.revision,
            .publication = if (publication) |value| value.value else null,
        }, .{});
    }

    pub fn requirePolicyIndexMutationAllowed(self: *RaftApplyStore, group_id: u64, table_id: u64) !void {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var publication = try system_catalog_storage.loadPolicyPublication(self.alloc, &txn, group_id, table_id);
        defer if (publication) |*value| value.deinit();
        if (publication) |value| {
            if (value.value.phase != .disabled or system_catalog_storage.policyPublicationNeedsWork(value.value))
                return error.RowPolicyUnsupported;
        }
    }

    fn policyDefinitionMutationAllowedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, previous: metadata.TableRecord, next: metadata.TableRecord) !bool {
        if (std.mem.eql(u8, previous.schema_json, next.schema_json) and
            std.mem.eql(u8, previous.read_schema_json, next.read_schema_json) and
            std.mem.eql(u8, previous.indexes_json, next.indexes_json)) return true;
        var publication = try system_catalog_storage.loadPolicyPublication(self.alloc, txn, group_id, previous.table_id);
        defer if (publication) |*value| value.deinit();
        const current = publication orelse return true;
        return current.value.phase == .disabled and !system_catalog_storage.policyPublicationNeedsWork(current.value);
    }

    /// A newly routed owner has no installed policy bundle. Until owner
    /// transfer carries and acknowledges that bundle, changing the physical
    /// owner cut of a protected table is not an admissible topology operation.
    fn policyTopologyMutationAllowedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !bool {
        var publication = try system_catalog_storage.loadPolicyPublication(self.alloc, txn, group_id, table_id);
        defer if (publication) |*value| value.deinit();
        const value = publication orelse return true;
        return value.value.phase == .disabled and !system_catalog_storage.policyPublicationNeedsWork(value.value);
    }

    /// Admission gives callers a useful conflict before proposing a command;
    /// apply repeats the check against the committed metadata cut so a racing
    /// policy publication cannot create an unprotected owner.
    pub fn requirePolicyTopologyMutationAllowed(self: *RaftApplyStore, group_id: u64, table_id: u64) !void {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        if (!try self.policyTopologyMutationAllowedTxn(&txn, group_id, table_id)) return error.RowPolicyUnsupported;
    }

    /// Build the only accepted publication-begin payload from one metadata
    /// read-index cut. The caller supplies no schema or owner authority; the
    /// Raft apply path revalidates the topology and schema before commit.
    pub fn sqlPolicyBeginCommandJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: sql_policies.BeginRequest) ![]u8 {
        if (request.table_id == 0) return error.InvalidRowPolicyPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, &txn, group_id);
        if (meta.revision != request.expected_revision) return error.RowPolicyCatalogChanged;
        if (try backupCohortLocksTableTxn(&txn, group_id, request.table_id) or
            try restoreStagingLocksTableTxn(&txn, group_id, request.table_id) or
            try self.fkGenerationTableLockedTxn(&txn, group_id, request.table_id)) return error.RowPolicyCatalogChanged;
        const identity = try self.policyTableSchemaTxn(a, &txn, group_id, request.table_id);
        if (request.enable and (identity.has_indexes or identity.has_schema_search)) return error.RowPolicyUnsupported;
        var fingerprint_key_buf: [192]u8 = undefined;
        const stored_fingerprint = txn.get(try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group_id, request.table_id)) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (stored_fingerprint) |value| if (value.len != 32 or !std.mem.eql(u8, value, &identity.record_digest)) return error.RowPolicyCatalogChanged;
        const fence = try self.loadTableTransitionFenceTxn(&txn, group_id, request.table_id);
        if (fence.active()) return error.RowPolicyCatalogChanged;
        const group_ids_for_table = try self.indexedTableRangeIdsTxn(a, &txn, group_id, request.table_id);
        if (group_ids_for_table.len == 0 or !try self.indexedRangeMembershipMatchesTxn(&txn, group_id, request.table_id, group_ids_for_table, fence.membership(request.table_id))) return error.RowPolicyCatalogChanged;
        const owners = try a.alloc(sql_policies.Publication.OwnerIdentity, group_ids_for_table.len);
        for (group_ids_for_table, owners) |owner_group_id, *owner| {
            var range_key_buf: [160]u8 = undefined;
            const range = try decodeRangeRecord(a, try txn.get(try rangeKeyForGroup(&range_key_buf, group_id, owner_group_id)));
            if (range.table_id != request.table_id or range.group_id != owner_group_id) return error.RowPolicyCatalogChanged;
            owner.* = .{ .group_id = owner_group_id, .descriptor_digest = try (sql_policies.OwnerDescriptor{
                .table_id = request.table_id,
                .group_id = owner_group_id,
                .shard_id = metadata_table_manager.rangeDocIdentityShardId(range),
                .range_id = metadata_table_manager.rangeDocIdentityRangeId(range),
                .schema_version = identity.version,
                .schema_digest = identity.digest,
                .range_start = range.start_key,
                .range_end = range.end_key orelse "",
            }).digest() };
        }
        std.sort.pdq(sql_policies.Publication.OwnerIdentity, owners, {}, struct {
            fn lessThan(_: void, lhs: sql_policies.Publication.OwnerIdentity, rhs: sql_policies.Publication.OwnerIdentity) bool {
                return lhs.group_id < rhs.group_id;
            }
        }.lessThan);
        var prior = try system_catalog_storage.loadPolicyPublication(a, &txn, group_id, request.table_id);
        defer if (prior) |*value| value.deinit();
        if (prior) |value| {
            if (value.value.phase != .active and value.value.phase != .disabled) return error.RowPolicyCatalogChanged;
            if (value.value.phase == .active and (value.value.schema_version != identity.version or !std.mem.eql(u8, &value.value.schema_digest, &identity.digest))) return error.RowPolicyCatalogChanged;
            if (value.value.phase == .disabled and system_catalog_storage.policyPublicationNeedsWork(value.value)) return error.RowPolicyCatalogChanged;
            if (!request.enable and value.value.phase == .disabled) return error.RowPolicyCatalogChanged;
        } else if (!request.enable) return error.RowPolicyCatalogChanged;
        if (request.enable) {
            const records = try system_catalog_storage.loadPolicies(a, &txn, group_id);
            for (records) |record| if (record.table_id == request.table_id) {
                if (record.schema_version != identity.version or !std.mem.eql(u8, &record.schema_digest, &identity.digest)) return error.RowPolicyCatalogChanged;
            };
        }
        const publication: sql_policies.Publication = .{
            .table_id = request.table_id,
            .schema_version = identity.version,
            .schema_digest = identity.digest,
            .generation = if (prior) |value| try std.math.add(u64, value.value.generation, 1) else 1,
            .catalog_epoch = try std.math.add(u64, meta.revision, 1),
            .topology_generation = fence.generation,
            .schema_record_digest = identity.record_digest,
            .serving_generation = if (prior) |value| if (value.value.phase == .active) value.value.generation else null else null,
            .serving_catalog_epoch = if (prior) |value| if (value.value.phase == .active) value.value.catalog_epoch else null else null,
            .phase = if (request.enable) .pending_install else .pending_disable,
            .required_owners = owners,
            .acknowledged_owners = &.{},
        };
        try publication.validateShape();
        return std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = meta.revision, .change = .{ .begin = publication } }, .{});
    }

    fn policyTableSchemaTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !struct { version: u32, digest: [32]u8, record_digest: [32]u8, has_indexes: bool, has_schema_search: bool } {
        _ = self;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var key_buf: [160]u8 = undefined;
        const encoded = txn.get(try tableKeyForGroup(&key_buf, group_id, table_id)) catch |err| switch (err) {
            error.NotFound => return error.TableNotFound,
            else => return err,
        };
        const table = try decodeTableRecord(a, encoded);
        if (table.read_schema_json.len != 0 or table.storage_migration != null) return error.RowPolicyCatalogChanged;
        const has_indexes = try policyHasUnsupportedArtifactIndexes(a, table.indexes_json);
        const record_digest = policyTableSchemaRecordDigest(table);
        var parsed = try @import("antfly_local_sources").schema_mod.parseValidatedTableSchema(a, table.schema_json);
        defer parsed.deinit(a);
        const native = try @import("antfly_local_sources").schema_mod.deriveRuntimeTableSchema(a, parsed);
        if (native.storage_mode != .relational) return error.RowPolicyCatalogChanged;
        var has_schema_search = native.index_sort.len != 0;
        // These mappings also describe ordinary keyword SQL columns when no
        // search artifact exists. Their presence is not a search capability:
        // actual artifact indexes are checked above, and search entry points
        // independently reject active policies before producing candidates.
        for (native.relational_columns) |column| {
            if (column.column_type == .dense_vector) has_schema_search = true;
        }
        const layout = try @import("antfly_local_sources").storage_schema.serializeSchema(a, native);
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(layout, &digest, .{});
        return .{ .version = native.version, .digest = digest, .record_digest = record_digest, .has_indexes = has_indexes, .has_schema_search = has_schema_search };
    }

    /// Shared distributed/standalone admission. The caller owns its catalog
    /// mutation mutex; apply repeats the revision and physical-owner cut.
    pub fn sqlPolicyDefinitionCommandJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, command: sql_policies.Command) ![]u8 {
        if ((try self.systemCatalogMeta(alloc, group_id)).revision != command.expected_revision) return error.RowPolicyCatalogChanged;
        var admitted = command;
        admitted.publication = null;
        const table_id = switch (command.change) {
            .put => |record| record.table_id,
            .drop => |identity| identity.table_id,
        };
        const status_bytes = try self.sqlPolicyPublicationStatusJson(alloc, group_id, table_id);
        defer alloc.free(status_bytes);
        var status = try std.json.parseFromSlice(?sql_policies.PublicationStamp, alloc, status_bytes, .{});
        defer status.deinit();
        var publication: ?std.json.Parsed(sql_policies.PublicationCommand) = null;
        defer if (publication) |*value| value.deinit();
        if (status.value) |prior| {
            if (prior.phase == .active) {
                const begin_bytes = try self.sqlPolicyBeginCommandJson(alloc, group_id, .{ .table_id = table_id, .enable = true, .expected_revision = command.expected_revision });
                defer alloc.free(begin_bytes);
                publication = try std.json.parseFromSlice(sql_policies.PublicationCommand, alloc, begin_bytes, .{});
                admitted.publication = publication.?.value.change.begin;
            } else if (prior.phase != .disabled) return error.RowPolicyCatalogChanged;
        }
        var output: std.Io.Writer.Allocating = .init(alloc);
        defer output.deinit();
        var stream: std.json.Stringify = .{ .writer = &output.writer, .options = .{} };
        try @import("antfly_local_sources").storage_db_relational_integrity_json.write(admitted, &stream);
        return output.toOwnedSlice();
    }

    fn applySqlPoliciesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
        var parsed = try std.json.parseFromSlice(sql_policies.Command, self.alloc, bytes, .{});
        defer parsed.deinit();
        const previous = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
        if (previous.revision == parsed.value.expected_revision) {
            if (parsed.value.publication) |publication| {
                if (try backupCohortLocksTableTxn(txn, group_id, publication.table_id) or
                    try restoreStagingLocksTableTxn(txn, group_id, publication.table_id) or
                    try self.fkGenerationTableLockedTxn(txn, group_id, publication.table_id)) return error.RowPolicyCatalogChanged;
                try self.validatePolicyOwnerCutTxn(txn, group_id, publication);
            }
        }
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
        try system_catalog_storage.applyPolicyCommand(self.alloc, txn, group_id, parsed.value, hash);
        const observed = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
        if (observed.revision != previous.revision) self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id });
    }

    fn applySqlPolicyPublicationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
        var parsed = try std.json.parseFromSlice(sql_policies.PublicationCommand, self.alloc, bytes, .{});
        defer parsed.deinit();
        const previous = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
        // Re-evaluate the exact owner cut inside the metadata apply
        // transaction. A receipt from an owner split or replaced since begin
        // can never promote the old policy generation.
        if (previous.revision == parsed.value.expected_revision) {
            switch (parsed.value.change) {
                .begin => |publication| {
                    if (try backupCohortLocksTableTxn(txn, group_id, publication.table_id) or
                        try restoreStagingLocksTableTxn(txn, group_id, publication.table_id) or
                        try self.fkGenerationTableLockedTxn(txn, group_id, publication.table_id)) return error.RowPolicyCatalogChanged;
                    try self.validatePolicyOwnerCutTxn(txn, group_id, publication);
                    // Existing tables created before this derived index gain
                    // it atomically with their first policy publication.
                    var fingerprint_key_buf: [192]u8 = undefined;
                    const key = try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group_id, publication.table_id);
                    const persisted = txn.get(key) catch |err| switch (err) {
                        error.NotFound => null,
                        else => return err,
                    };
                    if (persisted) |value| {
                        if (value.len != 32 or !std.mem.eql(u8, value, &publication.schema_record_digest)) return error.RowPolicyCatalogChanged;
                    } else try txn.put(key, &publication.schema_record_digest);
                },
                .acknowledge => |input| {
                    var publication = (try system_catalog_storage.loadPolicyPublication(self.alloc, txn, group_id, input.table_id)) orelse return error.RowPolicyCatalogChanged;
                    defer publication.deinit();
                    try self.validatePolicyPublicationStampTxn(txn, group_id, publication.value);
                },
                .promote => |input| {
                    var publication = (try system_catalog_storage.loadPolicyPublication(self.alloc, txn, group_id, input.table_id)) orelse return error.RowPolicyCatalogChanged;
                    defer publication.deinit();
                    try self.validatePolicyPublicationStampTxn(txn, group_id, publication.value);
                },
            }
        }
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
        try system_catalog_storage.applyPolicyPublicationCommand(self.alloc, txn, group_id, parsed.value, hash);
        const observed = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
        if (observed.revision != previous.revision) self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id });
    }

    fn validatePolicyPublicationStampTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, publication: sql_policies.Publication) !void {
        if (publication.topology_generation == 0 or std.mem.eql(u8, &publication.schema_record_digest, &(@as([32]u8, @splat(0)))))
            return self.validatePolicyOwnerCutTxn(txn, group_id, publication);
        const stamp = (try system_catalog_storage.loadPolicyPublicationStamp(self.alloc, txn, group_id, publication.table_id)) orelse return error.RowPolicyCatalogChanged;
        if (!std.meta.eql(stamp, sql_policies.PublicationStamp.fromPublication(publication))) return error.RowPolicyCatalogChanged;
        try self.validatePolicyOwnerStampTxn(txn, group_id, stamp);
    }

    fn validatePolicyOwnerStampTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, stamp: sql_policies.PublicationStamp) !void {
        if (try self.fkGenerationTableLockedTxn(txn, group_id, stamp.table_id)) return error.RowPolicyCatalogChanged;
        const fence = try self.loadTableTransitionFenceTxn(txn, group_id, stamp.table_id);
        if (fence.active() or fence.generation != stamp.topology_generation) return error.RowPolicyCatalogChanged;
        var fingerprint_key_buf: [192]u8 = undefined;
        const fingerprint = txn.get(try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group_id, stamp.table_id)) catch |err| switch (err) {
            error.NotFound => return error.RowPolicyCatalogChanged,
            else => return err,
        };
        if (fingerprint.len != 32 or !std.mem.eql(u8, fingerprint, &stamp.schema_record_digest)) return error.RowPolicyCatalogChanged;
    }

    fn validatePolicyOwnerCutTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, publication: sql_policies.Publication) !void {
        if (builtin.is_test) self.policy_full_owner_cut_validations += 1;
        try publication.validateShape();
        if (try self.fkGenerationTableLockedTxn(txn, group_id, publication.table_id)) return error.RowPolicyCatalogChanged;
        const identity = try self.policyTableSchemaTxn(self.alloc, txn, group_id, publication.table_id);
        if (publication.phase == .pending_install and (identity.has_indexes or identity.has_schema_search)) return error.RowPolicyUnsupported;
        if (identity.version != publication.schema_version or !std.mem.eql(u8, &identity.digest, &publication.schema_digest) or
            (!std.mem.eql(u8, &publication.schema_record_digest, &(@as([32]u8, @splat(0)))) and
                !std.mem.eql(u8, &identity.record_digest, &publication.schema_record_digest))) return error.RowPolicyCatalogChanged;
        const fence = try self.loadTableTransitionFenceTxn(txn, group_id, publication.table_id);
        if (fence.active() or (publication.topology_generation != 0 and fence.generation != publication.topology_generation)) return error.RowPolicyCatalogChanged;
        const owners = try self.indexedTableRangeIdsTxn(self.alloc, txn, group_id, publication.table_id);
        defer self.alloc.free(owners);
        if (owners.len == 0 or owners.len != publication.required_owners.len or
            !try self.indexedRangeMembershipMatchesTxn(txn, group_id, publication.table_id, owners, fence.membership(publication.table_id)))
            return error.RowPolicyCatalogChanged;
        for (owners) |owner_group_id| {
            var key_buf: [160]u8 = undefined;
            const encoded = txn.get(try rangeKeyForGroup(&key_buf, group_id, owner_group_id)) catch |err| switch (err) {
                error.NotFound => return error.RowPolicyCatalogChanged,
                else => return err,
            };
            const range = try decodeRangeRecord(self.alloc, encoded);
            defer metadata_table_manager.freeRange(self.alloc, range);
            if (range.table_id != publication.table_id or range.group_id != owner_group_id) return error.RowPolicyCatalogChanged;
            const descriptor: sql_policies.OwnerDescriptor = .{
                .table_id = range.table_id,
                .group_id = range.group_id,
                .shard_id = metadata_table_manager.rangeDocIdentityShardId(range),
                .range_id = metadata_table_manager.rangeDocIdentityRangeId(range),
                .schema_version = publication.schema_version,
                .schema_digest = publication.schema_digest,
                .range_start = range.start_key,
                .range_end = range.end_key orelse "",
            };
            const digest = try descriptor.digest();
            var left: usize = 0;
            var right = publication.required_owners.len;
            while (left < right) {
                const mid = left + (right - left) / 2;
                if (publication.required_owners[mid].group_id < range.group_id) left = mid + 1 else right = mid;
            }
            if (left == publication.required_owners.len or
                publication.required_owners[left].group_id != range.group_id or
                !std.mem.eql(u8, &publication.required_owners[left].descriptor_digest, &digest))
                return error.RowPolicyCatalogChanged;
        }
    }

    fn validateFkGenerationCutTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, plan: fk_generation_publication.Plan, published: bool) !void {
        try self.validateFkGenerationTableTxn(txn, group_id, if (published) plan.child_after else plan.child_before, plan.child_ranges);
        for (plan.parents) |parent| {
            // A self-parent is the child descriptor, not a second table. Its
            // after-image was checked by the first validation above.
            if (published and parent.table.table_id == plan.child_before.table_id) continue;
            try self.validateFkGenerationTableTxn(txn, group_id, parent.table, parent.ranges);
        }
    }

    const FkTableLockKind = @import("../table_lifecycle_lock.zig").Kind;

    fn fkTableLockValue(kind: FkTableLockKind, plan_id: fk_generation_publication.Id) [1 + @sizeOf(fk_generation_publication.Id)]u8 {
        return @import("../table_lifecycle_lock.zig").value(kind, plan_id);
    }

    fn fkTableLockKindTxn(_: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !?FkTableLockKind {
        const lock = (try @import("../table_lifecycle_lock.zig").read(txn, group_id, table_id)) orelse return null;
        return lock.kind;
    }

    fn fkGenerationTableLockedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !bool {
        return (try self.fkTableLockKindTxn(txn, group_id, table_id)) != null;
    }

    /// Recheck the reconciler's durable schema-progress predicate at apply
    /// time. A caller with generic compare-and-replace authority must not
    /// retire the old read layout before every placed owner acknowledges the
    /// new schema, even if it submits the exact final descriptor.
    fn schemaMigrationReadyTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64, version: u32) !bool {
        const range_ids = try self.indexedTableRangeIdsTxn(self.alloc, txn, group_id, table_id);
        defer self.alloc.free(range_ids);
        if (try stagingGet(txn, standalone_catalog_key) != null) {
            // Native standalone has one local physical owner and intentionally
            // no Raft placement rows. A copied catalog's progress rows alone
            // cannot authorize publication: the current update must supply
            // the exact root proof, matched to its durable binding.
            if (range_ids.len == 0) return false;
            const proof = if (self.active_outcome) |outcome| outcome.native_owner_proof orelse return false else return false;
            var owner_buf: [160]u8 = undefined;
            const encoded_owner = (try stagingGet(txn, try standalone_native_owner.key(&owner_buf, group_id))) orelse return false;
            if (!(try standalone_native_owner.decode(encoded_owner)).eql(proof)) return false;
            var progress_buf: [192]u8 = undefined;
            const encoded_progress = (try stagingGet(txn, try schemaProgressKeyForGroup(&progress_buf, group_id, table_id, proof.node_id))) orelse return false;
            const progress = try decodeSchemaProgressRecord(encoded_progress);
            if (progress.table_id != table_id or progress.node_id != proof.node_id or progress.schema_version != version) return false;
            for (range_ids) |range_id| {
                var range_buf: [160]u8 = undefined;
                const encoded_range = (try stagingGet(txn, try rangeKeyForGroup(&range_buf, group_id, range_id))) orelse return false;
                const range = try decodeRangeRecord(self.alloc, encoded_range);
                defer metadata_table_manager.freeRange(self.alloc, range);
                if (range.table_id != table_id) return false;
            }
            return true;
        }
        var saw_host = false;
        var cursor = try txn.openCursor();
        defer cursor.close();
        for (range_ids) |range_id| {
            var prefix_buf: [192]u8 = undefined;
            const prefix = try std.fmt.bufPrint(&prefix_buf, "\x00\x00__metadata__:metadata_placement:{d}:{d}:", .{ group_id, range_id });
            var row = try cursor.seekAtOrAfter(prefix);
            while (row) |entry| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, entry.key, prefix)) break;
                const intent = try decodePlacementIntent(self.alloc, entry.value);
                defer raft_reconciler.freeIntentOwned(self.alloc, intent);
                if (intent.record.group_id != range_id) return false;
                saw_host = true;
                var progress_key_buf: [192]u8 = undefined;
                const progress_key = try schemaProgressKeyForGroup(&progress_key_buf, group_id, table_id, intent.record.local_node_id);
                const encoded_progress = txn.get(progress_key) catch |err| switch (err) {
                    error.NotFound => return false,
                    else => return err,
                };
                const progress = try decodeSchemaProgressRecord(encoded_progress);
                if (progress.schema_version != version or progress.table_id != table_id or progress.node_id != intent.record.local_node_id) return false;
            }
        }
        return saw_host;
    }

    fn setFkGenerationTableLocksTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, plan: fk_generation_publication.Plan, acquire: bool) !void {
        const lifecycle = @import("../table_lifecycle_lock.zig");
        for (0..plan.parents.len + 1) |i| {
            const table_id = if (i == 0) plan.child_before.table_id else plan.parents[i - 1].table.table_id;
            // Dual-role self-FK owners share the child table lock. A second
            // acquisition would reject our own publication, while a second
            // release would fail after the first removal.
            if (i != 0 and table_id == plan.child_before.table_id) continue;
            const lock: lifecycle.Lock = .{ .kind = if (i == 0 and plan.sql_drop != null) .sql_drop else .generation, .id = plan.id };
            var key_buf: [160]u8 = undefined;
            const key = try fk_generation_publication.tableLockKey(&key_buf, group_id, table_id);
            if (acquire) {
                try lifecycle.acquire(txn, group_id, table_id, lock);
            } else {
                try lifecycle.release(txn, group_id, table_id, lock);
            }
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
    }

    fn validateFkGenerationTableTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, expected: metadata.TableRecord, ranges: []const metadata.RangeRecord) !void {
        if (try backupCohortLocksTableTxn(txn, group_id, expected.table_id) or
            try restoreStagingLocksTableTxn(txn, group_id, expected.table_id)) return error.GenerationPublicationChanged;
        var table_key_buf: [160]u8 = undefined;
        const encoded = txn.get(try tableKeyForGroup(&table_key_buf, group_id, expected.table_id)) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationChanged,
            else => return err,
        };
        const current = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, current);
        if (!metadata_table_manager.tableDefinitionsEqual(current, expected) or
            (try self.loadTableTransitionFenceTxn(txn, group_id, expected.table_id)).active()) return error.GenerationPublicationChanged;
        const ids = try self.indexedTableRangeIdsBoundedTxn(self.alloc, txn, group_id, expected.table_id, ranges.len);
        defer self.alloc.free(ids);
        if (ids.len != ranges.len) return error.GenerationPublicationChanged;
        // Compare membership as well as cardinality. Sort the already-owned
        // bounded IDs in place; no extra hash allocation or quadratic scans.
        std.sort.pdq(u64, ids, {}, std.sort.asc(u64));
        for (ranges) |expected_range| {
            var left: usize = 0;
            var right = ids.len;
            while (left < right) {
                const mid = left + (right - left) / 2;
                if (ids[mid] < expected_range.group_id) left = mid + 1 else right = mid;
            }
            if (left == ids.len or ids[left] != expected_range.group_id) return error.GenerationPublicationChanged;
            var range_key_buf: [160]u8 = undefined;
            const range_encoded = txn.get(try rangeKeyForGroup(&range_key_buf, group_id, expected_range.group_id)) catch |err| switch (err) {
                error.NotFound => return error.GenerationPublicationChanged,
                else => return err,
            };
            const current_range = try decodeRangeRecord(self.alloc, range_encoded);
            defer metadata_table_manager.freeRange(self.alloc, current_range);
            if (!metadata_table_manager.rangeRecordsEqual(current_range, expected_range)) return error.GenerationPublicationChanged;
        }
    }

    pub fn fkGenerationPublicationStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, child_table_id: u64) ![]u8 {
        if (child_table_id == 0) return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [160]u8 = undefined;
        const bytes = txn.get(try fk_generation_publication.key(&key_buf, group_id, child_table_id)) catch return error.GenerationPublicationNotFound;
        return alloc.dupe(u8, bytes);
    }

    pub fn fkInitialCreatePrepareJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: fk_generation_publication.InitialCreatePrepareRequest) ![]u8 {
        return self.fkInitialCreatePrepareJsonWithContext(alloc, group_id, request, .{});
    }

    pub fn fkInitialCreatePrepareJsonWithContext(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: fk_generation_publication.InitialCreatePrepareRequest, context: @import("antfly_local_sources").api_operation.RequestContext) ![]u8 {
        try context.ensureActive();
        if (request.namespace_id == 0 or request.logical_name.len == 0 or request.logical_name.len > 256 or
            request.candidate.table_id != 0 or request.candidate.name.len != 0 or
            !try fk_generation_publication.schemaHasForeignKeys(self.alloc, request.candidate.schema_json))
            return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, &txn, group_id);
        if (meta.next_id < 3 or meta.next_id == std.math.maxInt(u64)) return error.InvalidGenerationPublication;
        var namespace: system_catalog.Resource = system_catalog.default_namespace;
        if (request.namespace_id != system_catalog.default_namespace_id) {
            const owned = (try system_catalog_storage.getById(a, &txn, group_id, .namespace, request.namespace_id)) orelse return error.NamespaceNotFound;
            namespace = owned.value;
        }
        if (try system_catalog_storage.find(a, &txn, group_id, .table, request.namespace_id, request.logical_name)) |existing| {
            var owned = existing;
            owned.deinit();
            return error.CatalogAlreadyExists;
        }
        var name_buf: [512]u8 = undefined;
        if (try stagingGet(&txn, try fk_generation_publication.initialNameKey(&name_buf, group_id, request.namespace_id, request.logical_name)) != null)
            return error.GenerationPublicationChanged;
        const physical_name = try std.fmt.allocPrint(a, "table:{d}", .{meta.next_id});
        var child = request.candidate;
        var name_admission: ?relation_names.constraint_naming.Admission = null;
        if (request.generated_constraint_names.len != 0) {
            var names = try self.prepareGeneratedConstraintNamesTxn(a, &txn, group_id, request.namespace_id, request.logical_name, null, child.schema_json, request.generated_constraint_names, context);
            defer names.deinit();
            child.schema_json = try a.dupe(u8, names.schema_json);
            name_admission = try names.admission.dupe(a);
        }
        child.name = physical_name;
        const derived_id = std.hash.Wyhash.hash(0x54424c45, physical_name);
        child.table_id = if (derived_id == 0) 1 else derived_id;
        const catalog_view: system_catalog_storage.View = .{ .alloc = a, .txn = &txn, .group_id = group_id, .meta = meta };
        const explicit_tablespace_id = if (request.tablespace_name) |name| blk: {
            const space = (try catalog_view.lookup(.tablespace, 0, name)) orelse return error.TablespaceNotFound;
            break :blk space.id;
        } else @as(u64, 0);
        if (try catalog_view.effectiveTablespace(namespace, explicit_tablespace_id)) |space| {
            const policy = space.placement_policy;
            try policy.validate();
            child.placement_role = policy.placement_role orelse "data";
            child.desired_replica_count = policy.desired_replica_count orelse 3;
            if (!request.min_ranges_explicit) child.min_ranges = policy.min_ranges orelse 1;
        }
        var table_key_buf: [160]u8 = undefined;
        if (try stagingGet(&txn, try tableKeyForGroup(&table_key_buf, group_id, child.table_id)) != null or
            try stagingGet(&txn, try tableNameIndexKey(&name_buf, group_id, physical_name)) != null or
            try stagingGet(&txn, try restore_staging.nameKey(&name_buf, group_id, physical_name)) != null or
            try stagingGet(&txn, try fk_generation_publication.initialPhysicalNameKey(&name_buf, group_id, physical_name)) != null)
            return error.TableAlreadyExists;
        const fence = try self.loadTableTransitionFenceTxn(&txn, group_id, child.table_id);
        if (fence.active()) return error.TableTransitionActive;
        const existing_groups = try self.indexedTableRangeIdsTxn(a, &txn, group_id, child.table_id);
        if (existing_groups.len != 0 or fence.range_membership.count != 0) return error.TableTransitionActive;
        const ranges = try @import("../../api/tables.zig").deriveInitialRangesForGeneration(a, child, fence.generation);
        for (ranges) |range| {
            var group_buf: [160]u8 = undefined;
            if (try stagingGet(&txn, try rangeKeyForGroup(&group_buf, group_id, range.group_id)) != null or
                try stagingGet(&txn, try fk_generation_publication.initialGroupKey(&group_buf, group_id, range.group_id)) != null or
                try stagingGet(&txn, try restore_staging.identityKey(&group_buf, group_id, .group, range.group_id)) != null)
                return error.TableAlreadyExists;
        }
        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_bytes = txn.get(try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id)) catch return error.InvalidMetadataIncarnation;
        const incarnation = (try decodeMetadataIncarnationRecord(incarnation_bytes)).incarnation;
        const result: fk_generation_publication.InitialCreatePrepare = .{
            .constraint_name_admission = name_admission,
            .catalog_id = meta.next_id,
            .expected_catalog_revision = meta.revision,
            .tablespace_id = explicit_tablespace_id,
            .min_ranges_explicit = request.min_ranges_explicit,
            .child = child,
            .child_ranges = ranges,
            .transition_generation = fence.generation,
            .metadata_incarnation = incarnation,
            .metadata_epoch = meta.revision,
        };
        return std.json.Stringify.valueAlloc(alloc, result, .{});
    }

    pub fn fkInitialChildDecisionJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: fk_generation_publication.InitialChildDecisionRequest) ![]u8 {
        if (request.child_table_id == 0 or request.child_group_id == 0 or std.mem.allEqual(u8, &request.plan_id, 0))
            return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var key_buf: [160]u8 = undefined;
        var parsed = try std.json.parseFromSlice(fk_generation_publication.InitialPublication, a, txn.get(try fk_generation_publication.initialKey(&key_buf, group_id, request.child_table_id)) catch return error.GenerationPublicationNotFound, .{});
        defer parsed.deinit();
        const publication = parsed.value;
        if (!std.mem.eql(u8, &publication.plan.id, &request.plan_id) or
            publication.phase != switch (request.action) {
                .provision => fk_generation_publication.InitialPhase.provisioning_child,
                .release => fk_generation_publication.InitialPhase.published_hidden,
                .cancel => fk_generation_publication.InitialPhase.canceling,
            }) return error.GenerationPublicationChanged;
        const range = for (publication.plan.child_ranges) |candidate| {
            if (candidate.group_id == request.child_group_id) break candidate;
        } else return error.GenerationPublicationChanged;
        var reservation_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        const reserved = (try stagingGet(&txn, try fk_generation_publication.initialGroupKey(&reservation_buf, group_id, range.group_id))) orelse return error.GenerationPublicationChanged;
        const reservation = try fk_generation_publication.InitialGroupReservation.decode(reserved);
        if (reservation.child_table_id != request.child_table_id or
            reservation.range_id != range.range_id or reservation.canceled or
            !std.mem.eql(u8, &reservation.plan_id, &publication.plan.id) or
            !std.mem.eql(u8, &reservation.plan_digest, &publication.plan_digest)) return error.GenerationPublicationChanged;
        if (try stagingGet(&txn, try tableKeyForGroup(&key_buf, group_id, request.child_table_id)) != null or
            try stagingGet(&txn, try rangeKeyForGroup(&key_buf, group_id, request.child_group_id)) != null)
            return error.GenerationPublicationChanged;
        var schema = try @import("antfly_local_sources").schema_mod.parseValidatedTableSchema(a, publication.plan.child.schema_json);
        defer schema.deinit(a);
        var catalog = try fk_generation_publication.compileCatalogWithCoverage(a, schema, publication.plan.child.table_id, null, publication.plan.catalog_coverage);
        defer catalog.deinit();
        const catalog_b64 = try a.alloc(u8, std.base64.standard.Encoder.calcSize(catalog.value.len));
        _ = std.base64.standard.Encoder.encode(catalog_b64, catalog.value);
        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_bytes = txn.get(try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id)) catch return error.InvalidMetadataIncarnation;
        const incarnation = (try decodeMetadataIncarnationRecord(incarnation_bytes)).incarnation;
        const decision: fk_generation_publication.InitialChildDecision = .{
            .catalog_coverage = publication.plan.catalog_coverage,
            .plan_id = publication.plan.id,
            .plan_digest = publication.plan_digest,
            .revision = publication.revision,
            .phase = switch (publication.phase) {
                .provisioning_child => .provisioning_child,
                .published_hidden => .published_hidden,
                .canceling => .canceling,
                else => return error.GenerationPublicationChanged,
            },
            .child = publication.plan.child,
            .range = range,
            .catalog_b64 = catalog_b64,
            .catalog_digest = publication.candidate.catalog_digest,
            .schema_digest = publication.candidate.schema_digest,
            .metadata_group_id = group_id,
            .metadata_incarnation = incarnation,
            .metadata_epoch = publication.revision,
        };
        try decision.validate();
        return std.json.Stringify.valueAlloc(alloc, decision, .{});
    }

    pub fn fkInitialCreateStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, child_table_id: u64) ![]u8 {
        if (child_table_id == 0) return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [160]u8 = undefined;
        const bytes = txn.get(try fk_generation_publication.initialKey(&key_buf, group_id, child_table_id)) catch return error.GenerationPublicationNotFound;
        return alloc.dupe(u8, bytes);
    }

    pub const InitialFkRetirementPage = struct {
        items: []fk_initial_retirement.Replica,
        next_key: ?[]u8,

        pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.items);
            if (self.next_key) |key| alloc.free(key);
            self.* = undefined;
        }
    };

    /// Read-only store-local work enumeration. A canceled item is not an
    /// unlink grant: the physical store-root UUID and exact local receipt
    /// must be bound by the future ACK protocol before deletion is enabled.
    pub fn fkInitialRetirementPage(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, store_id: u64, after_key: ?[]const u8, limit: u16) !InitialFkRetirementPage {
        if (group_id == 0 or limit == 0 or limit > 128) return error.InvalidInitialFkRetirement;
        var prefix_buf: [160]u8 = undefined;
        const prefix = try fk_initial_retirement.storePrefix(&prefix_buf, group_id, store_id);
        if (after_key) |key| if (!std.mem.startsWith(u8, key, prefix)) return error.InvalidInitialFkRetirement;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entries: std.ArrayList(fk_initial_retirement.Replica) = .empty;
        errdefer entries.deinit(alloc);
        var next_key: ?[]u8 = null;
        errdefer if (next_key) |key| alloc.free(key);
        var key_buf: [256]u8 = undefined;
        var scanned: usize = 0;
        var row = try cursor.seekAtOrAfter(after_key orelse prefix);
        while (row) |item| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, prefix)) break;
            if (after_key) |key| if (std.mem.order(u8, item.key, key) != .gt) continue;
            scanned += 1;
            const work = try fk_initial_retirement.Replica.decode(item.value);
            if (work.store_id != store_id or !std.mem.eql(u8, item.key, try fk_initial_retirement.storeKey(&key_buf, group_id, work))) return error.InvalidInitialFkRetirement;
            if (work.canceled and !work.acked) try entries.append(alloc, work);
            if (entries.items.len == limit or scanned == 512) {
                next_key = try alloc.dupe(u8, item.key);
                break;
            }
        }
        return .{ .items = try entries.toOwnedSlice(alloc), .next_key = next_key };
    }

    /// Standalone admission uses the same durable capability and incarnation
    /// proof as other metadata lifecycle operations, never a local version flag.
    pub fn validateStoreRootEnrollmentProtocol(self: *RaftApplyStore, group_id: u64) !void {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.requireTopologyActivationTxn(&txn, group_id, topology_protocol.store_root_enrollment_version);
    }

    pub fn storeRootControlJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, control: fk_initial_retirement_wire.Control) ![]u8 {
        // Write preflights use an aborting transaction so the proposer and the
        // apply path execute the same authority comparisons.
        switch (control) {
            .preflight_enrollment => |request| {
                const bytes = try std.json.Stringify.valueAlloc(alloc, request, .{});
                defer alloc.free(bytes);
                var txn = try self.store.beginWriteTxn();
                defer txn.abort();
                try self.applyStoreRootEnrollmentTxn(&txn, group_id, bytes);
                return std.json.Stringify.valueAlloc(alloc, request.identity, .{});
            },
            .preflight_ack, .ack_status => |request| {
                var txn = try self.store.beginWriteTxn();
                defer txn.abort();
                const disposition = try self.ackInitialFkRetirementTxn(&txn, group_id, request.signed);
                if (control == .ack_status and disposition != .already_acked) return error.MetadataMutationOutcomeUnknown;
                return std.json.Stringify.valueAlloc(alloc, fk_initial_retirement_wire.AckResponse{
                    .ticket_digest = try request.signed.receipt.ticket.digest(),
                    .disposition = if (disposition == .newly_acked) .newly_acked else .already_acked,
                }, .{});
            },
            .enrollment_status, .authorized_page => {
                const identity = if (control == .enrollment_status) control.enrollment_status else control.authorized_page.identity;
                var txn = try self.store.beginReadTxn();
                defer txn.abort();
                try self.requireStoreRootEnrollmentTxn(&txn, group_id, identity);
                if (control == .enrollment_status) return std.json.Stringify.valueAlloc(alloc, identity, .{});
                const request = control.authorized_page;
                try request.verify();
                try request.page.validate(group_id);
                const current = (try self.loadStoreHeaderTxn(&txn, group_id, identity.store_id)) orelse return error.InitialFkRetirementReporterChanged;
                defer metadata_table_manager.freeStore(self.alloc, current);
                if (!current.live or current.node_id != identity.node_id or current.reporter_incarnation != request.reporter_incarnation or
                    current.replica_root_incarnation != identity.root_incarnation or !std.mem.eql(u8, &current.replica_root_public_key, &identity.public_key))
                    return error.InitialFkRetirementReporterChanged;
                return self.fkInitialRetirementTicketPageTxn(alloc, &txn, group_id, request.page);
            },
        }
    }

    fn requireStoreRootEnrollmentTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, identity: store_root_enrollment.Identity) !void {
        try identity.validate();
        var key_buf: [256]u8 = undefined;
        const bytes = (try stagingGet(txn, try store_root_enrollment.key(&key_buf, group_id, identity.store_id, identity.root_incarnation))) orelse return error.StoreRootEnrollmentChanged;
        var parsed = try std.json.parseFromSlice(store_root_enrollment.Identity, self.alloc, bytes, .{});
        defer parsed.deinit();
        if (!std.meta.eql(parsed.value, identity)) return error.StoreRootEnrollmentChanged;
    }

    fn applyStoreRootEnrollmentTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        var parsed = try std.json.parseFromSlice(store_root_enrollment.Request, self.alloc, bytes, .{});
        defer parsed.deinit();
        const request = parsed.value;
        try request.validate();
        const identity = request.identity;
        var key_buf: [256]u8 = undefined;
        const raw_incarnation = (try stagingGet(txn, try metadataIncarnationKeyForGroup(&key_buf, group_id))) orelse return error.StoreRootEnrollmentChanged;
        if (!std.mem.eql(u8, &(try decodeMetadataIncarnationRecord(raw_incarnation)).incarnation, &identity.metadata_incarnation)) return error.StoreRootEnrollmentChanged;
        const current = (try self.loadStoreHeaderTxn(txn, group_id, identity.store_id)) orelse return error.UnknownStore;
        defer metadata_table_manager.freeStore(self.alloc, current);
        if (current.node_id != identity.node_id or current.replica_root_incarnation != identity.root_incarnation or
            !std.mem.eql(u8, &current.replica_root_public_key, &identity.public_key)) return error.StoreRootEnrollmentChanged;
        const enrollment_key = try store_root_enrollment.key(&key_buf, group_id, identity.store_id, identity.root_incarnation);
        if (try stagingGet(txn, enrollment_key)) |prior| {
            var old = try std.json.parseFromSlice(store_root_enrollment.Identity, self.alloc, prior, .{});
            defer old.deinit();
            if (!std.meta.eql(old.value, identity)) return error.StoreRootEnrollmentChanged;
            return;
        }
        const encoded = try std.json.Stringify.valueAlloc(self.alloc, identity, .{});
        defer self.alloc.free(encoded);
        try txn.put(enrollment_key, encoded);
    }

    fn applyInitialFkRetirementAckTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        var parsed = try std.json.parseFromSlice(fk_initial_retirement_wire.AckRequest, self.alloc, bytes, .{});
        defer parsed.deinit();
        try parsed.value.validate(group_id);
        _ = try self.ackInitialFkRetirementTxn(txn, group_id, parsed.value.signed);
    }

    /// One linearizable caller cut and one local read transaction bind each
    /// store-indexed work item to terminal cancellation or published-obsolete
    /// placement exclusion. This is discovery only, never an unlink grant.
    pub fn fkInitialRetirementTicketPageJson(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        metadata_group_id: u64,
        request: fk_initial_retirement_wire.PageRequest,
    ) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return self.fkInitialRetirementTicketPageTxn(alloc, &txn, metadata_group_id, request);
    }

    fn fkInitialRetirementTicketPageTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, metadata_group_id: u64, request: fk_initial_retirement_wire.PageRequest) ![]u8 {
        try request.validate(metadata_group_id);
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_raw = txn.get(try metadataIncarnationKeyForGroup(&incarnation_key_buf, metadata_group_id)) catch
            return error.InvalidMetadataIncarnation;
        const cluster_incarnation = (try decodeMetadataIncarnationRecord(incarnation_raw)).incarnation;
        var prefix_buf: [160]u8 = undefined;
        const prefix = try fk_initial_retirement.storePrefix(&prefix_buf, metadata_group_id, request.store_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        const Summary = struct {
            plan_id: fk_generation_publication.Id,
            plan_digest: fk_generation_publication.Digest,
            revision: u64,
            publication: fk_generation_publication.InitialPublication,
        };
        var publication_summaries: std.AutoHashMapUnmanaged(u64, Summary) = .empty;
        defer publication_summaries.deinit(a);
        var tickets: std.ArrayList(fk_initial_retirement_contract.Ticket) = .empty;
        defer tickets.deinit(a);
        var next_key: ?[]const u8 = null;
        var scanned: usize = 0;
        var key_buf: [256]u8 = undefined;
        var row = try cursor.seekAtOrAfter(request.after_key orelse prefix);
        while (row) |item| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, prefix)) break;
            if (request.after_key) |key| if (std.mem.order(u8, item.key, key) != .gt) continue;
            scanned += 1;
            const work = try fk_initial_retirement.Replica.decode(item.value);
            if (work.store_id != request.store_id or
                !std.mem.eql(u8, item.key, try fk_initial_retirement.storeKey(&key_buf, metadata_group_id, work)))
                return error.InvalidInitialFkRetirement;
            if (work.canceled and !work.acked and (request.root_incarnation == 0 or work.store_root_incarnation == request.root_incarnation)) {
                const summary = publication_summaries.get(work.child_table_id) orelse summary: {
                    const publication_raw = txn.get(try fk_generation_publication.initialKey(&key_buf, metadata_group_id, work.child_table_id)) catch
                        return error.InvalidInitialFkRetirement;
                    const publication = try std.json.parseFromSliceLeaky(fk_generation_publication.InitialPublication, a, publication_raw, .{ .allocate = .alloc_always });
                    if ((publication.phase != .canceled and publication.phase != .published) or publication.revision == 0 or
                        publication.plan.retirement_scope != .hosted_store or
                        publication.plan.child.table_id != work.child_table_id or
                        !std.mem.eql(u8, &publication.plan.id, &work.plan_id) or
                        !std.mem.eql(u8, &publication.plan_digest, &work.plan_digest))
                        return error.InvalidInitialFkRetirement;
                    const value: Summary = .{
                        .plan_id = publication.plan.id,
                        .plan_digest = publication.plan_digest,
                        .revision = publication.revision,
                        .publication = publication,
                    };
                    try publication_summaries.put(a, work.child_table_id, value);
                    break :summary value;
                };
                if (!std.mem.eql(u8, &summary.plan_id, &work.plan_id) or
                    !std.mem.eql(u8, &summary.plan_digest, &work.plan_digest))
                    return error.InvalidInitialFkRetirement;
                _ = try self.initialFkRetirementAuthorityTxn(txn, metadata_group_id, summary.publication, work);
                const ticket: fk_initial_retirement_contract.Ticket = .{
                    .metadata_incarnation = cluster_incarnation,
                    .cancel_revision = summary.revision,
                    .replica = work,
                };
                try ticket.validate();
                try tickets.append(a, ticket);
            }
            if (tickets.items.len == request.limit or scanned == 512) {
                next_key = try a.dupe(u8, item.key);
                break;
            }
        }
        const response: fk_initial_retirement_wire.PageResponse = .{ .items = tickets.items, .next_key = next_key };
        try response.validate(metadata_group_id, request);
        return std.json.Stringify.valueAlloc(alloc, response, .{});
    }

    /// Root-authenticated internal ACK. Enrollment, current reporter and exact
    /// canceled work are rechecked in the Raft transaction, not merely at HTTP
    /// admission. Both discovery indexes advance atomically with the receipt.
    fn ackInitialFkRetirementTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        signed: fk_initial_retirement_auth.SignedReceipt,
    ) !fk_initial_retirement_ack.Disposition {
        if (metadata_group_id == 0) return error.InvalidInitialFkRetirementAck;
        const ticket = signed.receipt.ticket;
        try ticket.validate();
        var key_buf: [256]u8 = undefined;
        const incarnation_raw = (try stagingGet(txn, try metadataIncarnationKeyForGroup(&key_buf, metadata_group_id))) orelse
            return error.InvalidMetadataIncarnation;
        const cluster_incarnation = (try decodeMetadataIncarnationRecord(incarnation_raw)).incarnation;

        const publication_raw = (try stagingGet(txn, try fk_generation_publication.initialKey(&key_buf, metadata_group_id, ticket.replica.child_table_id))) orelse
            return error.InitialFkRetirementPublicationChanged;
        var parsed = try std.json.parseFromSlice(fk_generation_publication.InitialPublication, self.alloc, publication_raw, .{});
        defer parsed.deinit();
        const publication = parsed.value;
        const reservation = try self.initialFkRetirementAuthorityTxn(txn, metadata_group_id, publication, ticket.replica);

        var group_key_buf: [256]u8 = undefined;
        const group_key = try fk_initial_retirement.groupKey(&group_key_buf, metadata_group_id, ticket.replica);
        const group_raw = (try stagingGet(txn, group_key)) orelse return error.InitialFkRetirementWorkChanged;
        const group_work = try fk_initial_retirement.Replica.decode(group_raw);
        var store_key_buf: [256]u8 = undefined;
        const store_key = try fk_initial_retirement.storeKey(&store_key_buf, metadata_group_id, ticket.replica);
        const store_raw = (try stagingGet(txn, store_key)) orelse return error.InitialFkRetirementWorkChanged;
        const store_work = try fk_initial_retirement.Replica.decode(store_raw);

        const current_store = (try self.loadStoreHeaderTxn(txn, metadata_group_id, ticket.replica.store_id)) orelse
            return error.InitialFkRetirementReporterChanged;
        defer metadata_table_manager.freeStore(self.alloc, current_store);
        const current_node = (try self.loadNodeRecordTxn(txn, metadata_group_id, ticket.replica.node_id)) orelse
            return error.InitialFkRetirementReporterChanged;
        defer metadata_table_manager.freeNode(self.alloc, current_node);
        try self.requireStoreRootEnrollmentTxn(txn, metadata_group_id, .{
            .metadata_incarnation = cluster_incarnation,
            .node_id = current_store.node_id,
            .store_id = current_store.store_id,
            .root_incarnation = current_store.replica_root_incarnation,
            .public_key = current_store.replica_root_public_key,
        });
        const disposition = try fk_initial_retirement_ack.validate(
            signed,
            cluster_incarnation,
            .{
                .child_table_id = publication.plan.child.table_id,
                .plan_id = publication.plan.id,
                .plan_digest = publication.plan_digest,
                .revision = publication.revision,
                .hosted = publication.plan.retirement_scope == .hosted_store,
                .canceled = publication.phase == .canceled,
                .published = publication.phase == .published,
            },
            reservation,
            group_work,
            store_work,
            .{
                .reporter = .{
                    .node_id = current_store.node_id,
                    .store_id = current_store.store_id,
                    .reporter_incarnation = current_store.reporter_incarnation,
                    .store_root_incarnation = current_store.replica_root_incarnation,
                    // Draining owners may finish a previously fsynced unlink,
                    // but an offline store or finalized node is not a
                    // presently registered reporter. Never infer liveness
                    // from ID equality alone.
                    .live = current_node.node_id == current_store.node_id and
                        current_store.live and !metadata_table_manager.nodeLifecycleFinalizing(current_node.lifecycle),
                },
                .public_key = current_store.replica_root_public_key,
            },
        );
        if (disposition == .newly_acked) {
            var acknowledged = group_work;
            acknowledged.acked = true;
            const bytes = try acknowledged.encode();
            try txn.put(group_key, &bytes);
            try txn.put(store_key, &bytes);
        }
        return disposition;
    }

    /// One indexed point read protects support indexes owned by an in-flight
    /// FK publication from orphan cleanup. The lock is released at the
    /// publication's terminal transition, so cleanup resumes after cancel.
    pub fn fkGenerationTableLockedJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, table_id: u64) ![]u8 {
        if (table_id == 0) return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return std.json.Stringify.valueAlloc(alloc, try self.fkGenerationTableLockedTxn(&txn, group_id, table_id), .{});
    }

    pub fn fkInitialCreateWorkJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, after_child_table_id: u64) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var prefix_buf: [160]u8 = undefined;
        const key_prefix = try fk_generation_publication.initialWorkPrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var after_key_buf: [160]u8 = undefined;
        var entry = if (after_child_table_id == std.math.maxInt(u64))
            null
        else
            try cursor.seekAtOrAfter(try fk_generation_publication.initialWorkKey(&after_key_buf, group_id, after_child_table_id + 1));
        if (entry == null or !std.mem.startsWith(u8, entry.?.key, key_prefix))
            entry = try cursor.seekAtOrAfter(key_prefix);
        const row = entry orelse return alloc.dupe(u8, "null");
        if (!std.mem.startsWith(u8, row.key, key_prefix)) return alloc.dupe(u8, "null");
        if (row.key.len != key_prefix.len + 16 or row.value.len != 16) return error.InvalidGenerationPublication;
        const table_id = std.fmt.parseInt(u64, row.key[key_prefix.len..], 16) catch return error.InvalidGenerationPublication;
        var key_buf: [160]u8 = undefined;
        const publication_key = try fk_generation_publication.initialKey(&key_buf, group_id, table_id);
        const publication_bytes = txn.get(publication_key) catch {
            std.log.err("FK initial pending index orphan group={d} indexed_id={d} key={s}", .{ group_id, table_id, publication_key });
            return error.InvalidGenerationPublication;
        };
        var publication = try std.json.parseFromSlice(fk_generation_publication.InitialPublication, self.alloc, publication_bytes, .{});
        defer publication.deinit();
        if (publication.value.plan.child.table_id != table_id or
            !std.mem.eql(u8, row.value, &publication.value.plan.id) or
            publication.value.phase == .published or publication.value.phase == .canceled)
            return error.InvalidGenerationPublication;
        try publication.value.validateState(self.alloc);
        return std.json.Stringify.valueAlloc(alloc, (try publication.value.nextWork()) orelse return error.InvalidGenerationPublication, .{});
    }

    pub fn fkInitialParentDecisionJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: fk_generation_publication.DecisionRequest) ![]u8 {
        if (request.parent_table_id == 0 or request.parent_group_id == 0 or request.child_table_id == 0 or std.mem.allEqual(u8, &request.plan_id, 0))
            return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var key_buf: [160]u8 = undefined;
        var parsed = try std.json.parseFromSlice(fk_generation_publication.InitialPublication, a, txn.get(try fk_generation_publication.initialKey(&key_buf, group_id, request.child_table_id)) catch return error.GenerationPublicationNotFound, .{});
        defer parsed.deinit();
        const publication = parsed.value;
        if (!std.mem.eql(u8, &publication.plan.id, &request.plan_id) or
            !std.mem.eql(u8, publication.plan.child.name, request.child_table_name) or
            publication.phase != switch (request.action) {
                .stage => fk_generation_publication.InitialPhase.staging_parents,
                .activate => .activating_parents,
                .acknowledge => .acknowledging_parents,
                .cancel => .canceling,
            }) return error.GenerationPublicationChanged;
        const parent = for (publication.plan.parents) |candidate| {
            if (candidate.table.table_id == request.parent_table_id) break candidate;
        } else return error.GenerationPublicationChanged;
        try self.validateFkGenerationTableTxn(&txn, group_id, parent.table, parent.ranges);
        const index = for (parent.ranges, 0..) |range, i| {
            if (range.group_id == request.parent_group_id) break i;
        } else return error.GenerationPublicationChanged;
        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_bytes = txn.get(try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id)) catch return error.InvalidMetadataIncarnation;
        const incarnation = (try decodeMetadataIncarnationRecord(incarnation_bytes)).incarnation;
        const decision: fk_generation_publication.InitialParentDecision = .{
            .phase = publication.phase,
            .metadata_group_id = group_id,
            .metadata_incarnation = incarnation,
            .metadata_epoch = publication.revision,
            .plan_digest = publication.plan_digest,
            .fence = parent.fences[index],
            .transitions = parent.transitions,
            .parent_table = parent.table,
            .parent_range = parent.ranges[index],
            .partial_support_indexes = try fk_generation_publication.initialPartialSupportNames(a, publication.plan.child.schema_json, parent.table),
        };
        return std.json.Stringify.valueAlloc(alloc, decision, .{});
    }

    fn requireInitialChildRootReceiptTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, receipt: @import("../../api/relational_fk_generation_publication.zig").InitialChildReceipt) !void {
        const proof = receipt.root_attestation orelse return error.InitialChildRootReceiptChanged;
        proof.verify(receipt.digest()) catch return error.InitialChildRootReceiptChanged;
        self.requireStoreRootEnrollmentTxn(txn, group_id, proof.identity) catch |err| switch (err) {
            error.InvalidStoreRootEnrollment, error.StoreRootEnrollmentChanged => return error.InitialChildRootReceiptChanged,
            else => return err,
        };
        const current = (try self.loadStoreHeaderTxn(txn, group_id, proof.identity.store_id)) orelse return error.InitialChildRootReceiptChanged;
        defer metadata_table_manager.freeStore(self.alloc, current);
        if (!current.live or current.node_id != proof.identity.node_id or current.reporter_incarnation != proof.reporter_incarnation or
            current.replica_root_incarnation != proof.identity.root_incarnation or !std.mem.eql(u8, &current.replica_root_public_key, &proof.identity.public_key))
            return error.InitialChildRootReceiptChanged;
        var key_buf: [256]u8 = undefined;
        const cluster_bytes = (try stagingGet(txn, try metadataIncarnationKeyForGroup(&key_buf, group_id))) orelse return error.InitialChildRootReceiptChanged;
        if (!std.mem.eql(u8, &(try decodeMetadataIncarnationRecord(cluster_bytes)).incarnation, &proof.identity.metadata_incarnation)) return error.InitialChildRootReceiptChanged;
        const live_bytes = (try stagingGet(txn, try fk_initial_retirement.liveKey(&key_buf, group_id, receipt.child_group_id, proof.identity.node_id))) orelse return error.InitialChildRootReceiptChanged;
        const replica = try fk_initial_retirement.Replica.decode(live_bytes);
        if (replica.canceled or replica.acked or replica.group_id != receipt.child_group_id or replica.node_id != proof.identity.node_id or
            replica.replica_id != proof.replica_id or replica.root_generation != proof.root_generation or
            replica.store_id != proof.identity.store_id or replica.store_root_incarnation != proof.identity.root_incarnation or
            replica.child_table_id != receipt.child_table_id or replica.range_id != receipt.namespace.range_id or
            !std.mem.eql(u8, &replica.plan_id, &receipt.plan_id) or !std.mem.eql(u8, &replica.plan_digest, &receipt.plan_digest))
            return error.InitialChildRootReceiptChanged;
    }

    fn applyFkInitialCreateTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8, committed: bool) !void {
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var parsed = try std.json.parseFromSlice(fk_generation_publication.InitialCommand, a, bytes, .{});
        defer parsed.deinit();
        const command = parsed.value;
        try command.validateShape();
        if (command.plan) |plan| {
            if (plan.historical_reference_coverage) _ = try self.requireTopologyActivationTxn(txn, group_id, topology_protocol.fk_historical_references_version);
        }

        var key_buf: [160]u8 = undefined;
        // Validation below reuses key_buf for range and collision probes.
        // Keep the final publication key stable through the entire Raft txn.
        const publication_key = try a.dupe(u8, try fk_generation_publication.initialKey(&key_buf, group_id, command.child_table_id));
        const prior = try stagingGet(txn, publication_key);
        var publication: fk_generation_publication.InitialPublication = undefined;
        const source_tracked = try relation_reconciliation.readSourceRevision(txn, group_id) != 0;
        var previous_source_digest: ?[32]u8 = null;
        if (command.action == .begin) {
            if (prior != null) return error.GenerationPublicationChanged;
            const plan = command.plan.?;
            const digest = try plan.digest(a);
            if (plan.readerPublicationRequired())
                _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_reader_publication_version);
            const meta = try system_catalog_storage.readMeta(a, txn, group_id);
            if (plan.catalog_id != meta.next_id or plan.expected_catalog_revision != meta.revision or
                plan.child.table_id != command.child_table_id or meta.next_id == std.math.maxInt(u64))
                return error.GenerationPublicationChanged;
            if (plan.constraint_name_admission) |admission| {
                self.validateInitialConstraintNameAdmissionTxn(a, txn, group_id, admission, plan) catch |err| {
                    // Only this pre-write guard may classify a new admission
                    // failure as a committed no-op. The same error emitted by
                    // later storage/publication work must still abort apply.
                    switch (err) {
                        error.CatalogGenerationChanged, error.CatalogOccupancyNotReady, error.TableTopologyProtocolUpgradeRequired => if (committed) return error.StaleInitialConstraintNameAdmission,
                        else => {},
                    }
                    return err;
                };
            }
            // Prepare is a read-index hint, not authority. Re-evaluate the
            // namespace and placement policy in this same Raft transaction so
            // a stale or forged plan cannot reserve a differently placed table.
            var namespace: system_catalog.Resource = system_catalog.default_namespace;
            var owned_namespace: ?std.json.Parsed(system_catalog.Resource) = null;
            defer if (owned_namespace) |*owned| owned.deinit();
            if (plan.namespace_id != system_catalog.default_namespace_id) {
                owned_namespace = (try system_catalog_storage.getById(a, txn, group_id, .namespace, plan.namespace_id)) orelse return error.NamespaceNotFound;
                namespace = owned_namespace.?.value;
            }
            const catalog_view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group_id, .meta = meta };
            var expected_role: []const u8 = "data";
            var expected_replicas: u16 = 3;
            var expected_ranges_count: u32 = if (plan.min_ranges_explicit) plan.child.min_ranges else 1;
            if (try catalog_view.effectiveTablespace(namespace, plan.tablespace_id)) |space| {
                const policy = space.placement_policy;
                try policy.validate();
                expected_role = policy.placement_role orelse "data";
                expected_replicas = policy.desired_replica_count orelse 3;
                if (!plan.min_ranges_explicit) expected_ranges_count = policy.min_ranges orelse 1;
            }
            if (!std.mem.eql(u8, plan.child.placement_role, expected_role) or
                plan.child.desired_replica_count != expected_replicas or
                plan.child.min_ranges != expected_ranges_count)
                return error.GenerationPublicationChanged;
            var name_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
            if (try system_catalog_storage.find(a, txn, group_id, .table, plan.namespace_id, plan.logical_name)) |existing| {
                var owned = existing;
                owned.deinit();
                return error.CatalogAlreadyExists;
            }
            if (try system_catalog_storage.getById(a, txn, group_id, .table, plan.child.table_id)) |existing| {
                var owned = existing;
                owned.deinit();
                return error.GenerationPublicationChanged;
            }
            if (try stagingGet(txn, try fk_generation_publication.initialNameKey(&name_buf, group_id, plan.namespace_id, plan.logical_name)) != null or
                try stagingGet(txn, try fk_generation_publication.initialPhysicalNameKey(&name_buf, group_id, plan.child.name)) != null or
                try stagingGet(txn, try restore_staging.nameKey(&name_buf, group_id, plan.child.name)) != null or
                try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, plan.child.table_id)) != null or
                try self.fkGenerationTableLockedTxn(txn, group_id, plan.child.table_id))
                return error.GenerationPublicationChanged;
            const fence = try self.loadTableTransitionFenceTxn(txn, group_id, plan.child.table_id);
            if (fence.active()) return error.TableTransitionActive;
            const prior_groups = try self.indexedTableRangeIdsTxn(a, txn, group_id, plan.child.table_id);
            if (prior_groups.len != 0 or fence.range_membership.count != 0) return error.TableTransitionActive;
            const expected_ranges = try @import("../../api/tables.zig").deriveInitialRangesForGeneration(a, plan.child, fence.generation);
            if (expected_ranges.len != plan.child_ranges.len) return error.GenerationPublicationChanged;
            for (expected_ranges, plan.child_ranges) |expected, supplied| {
                if (!metadata_table_manager.rangeRecordsEqual(expected, supplied)) return error.GenerationPublicationChanged;
                if (try stagingGet(txn, try rangeKeyForGroup(&key_buf, group_id, supplied.group_id)) != null or
                    try stagingGet(txn, try fk_generation_publication.initialGroupKey(&key_buf, group_id, supplied.group_id)) != null or
                    try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .group, supplied.group_id)) != null)
                    return error.GenerationPublicationChanged;
            }
            for (plan.parents) |parent| {
                if (try self.fkGenerationTableLockedTxn(txn, group_id, parent.table.table_id)) return error.GenerationPublicationChanged;
                // A hidden child still installs structural parent controls.
                // Reject active policy owners before reserving the child;
                // otherwise an accepted plan cannot complete its parent cut.
                if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, parent.table.table_id))
                    return error.RowPolicyUnsupported;
                try self.validateFkGenerationTableTxn(txn, group_id, parent.table, parent.ranges);
                if (plan.support_pending and parent.support_after != null and
                    !try self.policyDefinitionMutationAllowedTxn(txn, group_id, parent.table, parent.support_after.?))
                    return error.RowPolicyUnsupported;
            }
            publication = .{ .plan = plan, .plan_digest = digest, .candidate = try plan.candidateIdentity(a), .revision = 1, .phase = if (plan.support_pending) .preparing_support else .provisioning_child };
            try publication.validateState(a);
            var prepared_support: std.ArrayList(PreparedTableRecordWrite) = .empty;
            defer {
                for (prepared_support.items) |*prepared| prepared.deinit(self.alloc);
                prepared_support.deinit(self.alloc);
            }
            // Admit and encode the entire parent cut before changing catalog
            // counters, table rows, name indexes or source revisions. Future
            // reader-floor publication must join this same admitted batch.
            if (plan.support_pending) for (plan.parents) |parent| {
                if (parent.support_after) |after| {
                    var prepared = (try self.prepareTableRecordTxnMode(txn, group_id, try tableKeyForGroup(&key_buf, group_id, after.table_id), after, true)) orelse return error.GenerationPublicationChanged;
                    errdefer prepared.deinit(self.alloc);
                    try prepared_support.append(self.alloc, prepared);
                }
            };
            var empty: [0]system_catalog.Resource = .{};
            var command_hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(bytes, &command_hash, .{});
            try self.applySystemCatalogDeltaTxn(a, txn, group_id, .{ .upserts = &empty, .removes = &empty, .next_id = meta.next_id + 1 }, meta, command_hash);
            for (prepared_support.items) |prepared|
                try self.writePreparedTableRecordTxn(txn, group_id, try tableKeyForGroup(&key_buf, group_id, prepared.identity.table_id), prepared);
            try txn.put(try fk_generation_publication.initialNameKey(&name_buf, group_id, plan.namespace_id, plan.logical_name), &plan.id);
            try txn.put(try fk_generation_publication.initialPhysicalNameKey(&name_buf, group_id, plan.child.name), &plan.id);
            try txn.put(try fk_generation_publication.initialWorkKey(&name_buf, group_id, plan.child.table_id), &plan.id);
            for (plan.child_ranges) |range| {
                const group_reservation = (fk_generation_publication.InitialGroupReservation{
                    .plan_id = plan.id,
                    .child_table_id = plan.child.table_id,
                    .range_id = range.range_id,
                    .plan_digest = digest,
                    .retirement_scope = plan.retirement_scope,
                }).encode();
                try txn.put(try fk_generation_publication.initialGroupKey(&name_buf, group_id, range.group_id), &group_reservation);
            }
            try self.setFkInitialTableLocksTxn(txn, group_id, plan, true);
        } else {
            // apply retains immutable plan/receipt slices from the previous
            // value. Keep them in the transaction arena through serialization.
            const previous = try std.json.parseFromSliceLeaky(fk_generation_publication.InitialPublication, a, prior orelse return error.GenerationPublicationNotFound, .{});
            if (source_tracked) previous_source_digest = try relationInitialSourceDigest(previous, command.child_table_id);
            if (command.action == .seal_support) {
                const sealed = command.plan orelse return error.InvalidGenerationPublication;
                for (sealed.parents) |parent| try self.validateFkGenerationTableTxn(txn, group_id, parent.table, parent.ranges);
            }
            if (command.child_receipt) |receipt| if (previous.plan.retirement_scope == .hosted_store) {
                // Logical cancellation does not retire a physical replica:
                // every historical placement still needs its unlink ACK.
                // Public visibility, in contrast, requires an enrolled live
                // root with the exact current placement generation.
                if (receipt.action != .cancel)
                    try self.requireInitialChildRootReceiptTxn(txn, group_id, receipt);
            };
            // A competing proposer may already have committed this revision.
            // This check precedes all writes; committed Raft replay can skip
            // only that stale command while preserving all other validation.
            if (command.expected_revision != previous.revision)
                return error.StaleInitialFkCreateCommand;
            publication = try previous.apply(a, command);
            if (command.action == .seal_support or publication.phase == .canceled) {
                // The support-seal changes the immutable plan digest before
                // any hidden owner may be placed. Cancellation converts each
                // reservation to an exact terminal proof in this same Raft
                // transaction; a late proposal cannot revive the group.
                var reservation_key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                for (publication.plan.child_ranges) |range| {
                    const proof = (fk_generation_publication.InitialGroupReservation{
                        .plan_id = publication.plan.id,
                        .child_table_id = publication.plan.child.table_id,
                        .range_id = range.range_id,
                        .plan_digest = publication.plan_digest,
                        .retirement_scope = publication.plan.retirement_scope,
                        .canceled = publication.phase == .canceled,
                    }).encode();
                    try txn.put(try fk_generation_publication.initialGroupKey(&reservation_key_buf, group_id, range.group_id), &proof);
                }
            }
            if (publication.phase == .published and command.action == .publish_child) {
                // The durable owner release ACKs precede this one visibility
                // transaction; no user route can observe a partially ready
                // child or a parent generation that is not yet accepted.
                var table_key_buf: [160]u8 = undefined;
                try self.putTableRecordTxnMode(txn, group_id, try tableKeyForGroup(&table_key_buf, group_id, publication.plan.child.table_id), publication.plan.child, true);
                var added: std.ArrayList(u64) = .empty;
                defer added.deinit(a);
                for (publication.plan.child_ranges) |range| {
                    const encoded = try encodeRangeRecord(a, range);
                    try txn.put(try rangeKeyForGroup(&table_key_buf, group_id, range.group_id), encoded);
                    try self.putTableRangeIndexTxn(txn, group_id, publication.plan.child.table_id, range.group_id);
                    try added.append(a, range.group_id);
                }
                try self.advanceTableTransitionGenerationWithRangeChangesTxn(txn, group_id, publication.plan.child.table_id, added.items, &.{});
                const meta = try system_catalog_storage.readMeta(a, txn, group_id);
                // The resource identity must match the physical table ID.
                // catalog_id reserves only the monotonic name/allocator slot.
                var upserts = [_]system_catalog.Resource{.{ .kind = .table, .id = publication.plan.child.table_id, .parent_id = publication.plan.namespace_id, .name = publication.plan.logical_name, .tablespace_id = publication.plan.tablespace_id, .storage_name = publication.plan.child.name }};
                var empty: [0]system_catalog.Resource = .{};
                var command_hash: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(bytes, &command_hash, .{});
                const next_id = std.math.add(u64, publication.plan.catalog_id, 1) catch return error.InvalidGenerationPublication;
                try self.applySystemCatalogDeltaTxn(a, txn, group_id, .{ .upserts = &upserts, .removes = &empty, .next_id = @max(meta.next_id, next_id) }, meta, command_hash);
            }
            if (publication.phase == .published or publication.phase == .canceled) {
                try self.terminalizeInitialFkReplicasTxn(txn, group_id, publication);
                try self.setFkInitialTableLocksTxn(txn, group_id, publication.plan, false);
                var name_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                try txn.delete(try fk_generation_publication.initialNameKey(&name_buf, group_id, publication.plan.namespace_id, publication.plan.logical_name));
                try txn.delete(try fk_generation_publication.initialPhysicalNameKey(&name_buf, group_id, publication.plan.child.name));
                try txn.delete(try fk_generation_publication.initialWorkKey(&name_buf, group_id, publication.plan.child.table_id));
                // A canceled unpublished group has no public range key. Keep
                // its compact reservation as a durable retirement tombstone:
                // delayed placement proposals must not resurrect an owner
                // after the supervisor removes its placement. Published
                // groups transfer authority to their public range record.
                if (publication.phase == .published) for (publication.plan.child_ranges) |range| {
                    try txn.delete(try fk_generation_publication.initialGroupKey(&name_buf, group_id, range.group_id));
                };
            }
        }
        const encoded = try std.json.Stringify.valueAlloc(a, publication, .{});
        if (encoded.len > fk_generation_publication.max_bytes) return error.InvalidGenerationPublication;
        if (source_tracked) {
            const digest = try relationInitialSourceDigest(publication, command.child_table_id);
            if (previous_source_digest == null or !std.mem.eql(u8, &previous_source_digest.?, &digest)) try relation_reconciliation.advanceSource(txn, group_id);
        }
        try txn.put(publication_key, encoded);
    }

    /// Evaluate the exact state-machine command against the current
    /// projection before proposing it. The write transaction is always
    /// aborted: validation and the candidate's writes share one code path,
    /// but no hidden reservation becomes visible before Raft commits it.
    pub fn preflightFkInitialCreateCommand(self: *RaftApplyStore, group_id: u64, bytes: []const u8) !void {
        const io = self.io_impl.io();
        self.apply_mutex.lockUncancelable(io);
        defer self.apply_mutex.unlock(io);
        var txn = try self.store.beginWriteTxn();
        // The real apply path buffers notifications until commit. Preflight
        // runs the same mutation helpers against an aborted transaction, so
        // it must also buffer (and discard) every nested table/range/catalog
        // signal instead of waking readers for state that never committed.
        var discarded: CommittedApplyOutcome = .{ .alloc = self.alloc, .collect_transition_deltas = false };
        std.debug.assert(self.active_outcome == null);
        self.active_outcome = &discarded;
        defer {
            txn.abort();
            self.active_outcome = null;
            discarded.deinit();
        }
        self.applyFkInitialCreateTxn(&txn, group_id, bytes, false) catch |err| switch (err) {
            error.StaleInitialFkCreateCommand => return error.GenerationPublicationChanged,
            else => return err,
        };
        if (discarded.failure) |err| return err;
    }

    fn applyCommittedFkInitialCreateTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        var parsed = try std.json.parseFromSlice(fk_generation_publication.InitialCommand, self.alloc, bytes, .{});
        defer parsed.deinit();
        const command = parsed.value;
        const action = command.action;
        var publication_arena = std.heap.ArenaAllocator.init(self.alloc);
        defer publication_arena.deinit();
        var key_buf: [160]u8 = undefined;
        const publication_key = try fk_generation_publication.initialKey(&key_buf, group_id, command.child_table_id);
        // Pin the exact admitted plan before applying the transition, which
        // may replace or retire this publication in the same transaction.
        // Notifications must describe that original cut, not a later lookup.
        const prior_publication: ?fk_generation_publication.InitialPublication = if (action == .publish_child)
            try std.json.parseFromSliceLeaky(fk_generation_publication.InitialPublication, publication_arena.allocator(), try txn.get(publication_key), .{})
        else
            null;
        self.applyFkInitialCreateTxn(txn, group_id, bytes, true) catch |err| {
            if (err == error.StaleInitialConstraintNameAdmission) return;
            if (err == error.StaleInitialFkCreateCommand) return;
            // Attestation is checked before any writes. A placement/reporter
            // replacement between preflight and apply is a stale receipt, not
            // a reason to halt the metadata log.
            if (err == error.InitialChildRootReceiptChanged) return;
            // A different metadata proposer can win after our preflight but
            // before this entry applies. Every begin CAS check runs before
            // the first txn.put, so a stale begin is a safe committed no-op.
            // Malformed commands, I/O errors, and later-phase failures are
            // not swallowed here; those need their own pre-write proof.
            if (action == .seal_support and err == error.GenerationPublicationChanged) return;
            if (action == .begin) switch (err) {
                error.GenerationPublicationChanged,
                error.CatalogAlreadyExists,
                error.TableTransitionActive,
                => return,
                else => {},
            };
            return err;
        };
        // Preflight uses applyFkInitialCreateTxn directly. Only a committed
        // transition may wake readers; the apply outcome dispatches these
        // signals after the transaction commits. In particular, publishing a
        // hidden child also publishes its table, ranges, and logical catalog
        // binding, so cached public routes must advance with that same cut.
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = publication_key });
        if (action == .publish_child) {
            const child = prior_publication.?.plan.child;
            // putTableRecordTxnMode above already buffers the child table-key
            // and table-projection signals. The manually published ranges do
            // not pass through that helper and need their own notifications.
            for (prior_publication.?.plan.child_ranges) |range| {
                const range_key = try rangeKeyForGroup(&key_buf, group_id, range.group_id);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = range_key });
                self.notifyProjectionListeners(.{ .kind = .range, .metadata_group_id = group_id, .group_id = range.group_id, .table_id = child.table_id });
            }
        }
    }

    fn setFkInitialTableLocksTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, plan: fk_generation_publication.InitialCreatePlan, acquire: bool) !void {
        _ = self;
        const value = fkTableLockValue(.initial_support, plan.id);
        var buf: [160]u8 = undefined;
        const child_key = try fk_generation_publication.tableLockKey(&buf, group_id, plan.child.table_id);
        if (acquire) {
            try txn.put(child_key, &value);
        } else {
            const existing = txn.get(child_key) catch return error.GenerationPublicationChanged;
            if (!std.mem.eql(u8, existing, &value)) return error.GenerationPublicationChanged;
            try txn.delete(child_key);
        }
        for (plan.parents) |parent| {
            if (parent.table.table_id == plan.child.table_id) continue;
            const key = try fk_generation_publication.tableLockKey(&buf, group_id, parent.table.table_id);
            if (acquire) {
                try txn.put(key, &value);
            } else {
                const existing = txn.get(key) catch return error.GenerationPublicationChanged;
                if (!std.mem.eql(u8, existing, &value)) return error.GenerationPublicationChanged;
                try txn.delete(key);
            }
        }
    }

    pub fn fkGenerationPublicationWorkJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, after_child_table_id: u64) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var prefix_buf: [160]u8 = undefined;
        const key_prefix = try fk_generation_publication.workPrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var after_key_buf: [160]u8 = undefined;
        var entry = if (after_child_table_id == std.math.maxInt(u64))
            null
        else
            try cursor.seekAtOrAfter(try fk_generation_publication.workKey(&after_key_buf, group_id, after_child_table_id + 1));
        if (entry == null or !std.mem.startsWith(u8, entry.?.key, key_prefix))
            entry = try cursor.seekAtOrAfter(key_prefix);
        const row = entry orelse return alloc.dupe(u8, "null");
        if (!std.mem.startsWith(u8, row.key, key_prefix)) return alloc.dupe(u8, "null");
        if (row.key.len != key_prefix.len + 16 or row.value.len != 16) return error.InvalidGenerationPublication;
        const table_id = std.fmt.parseInt(u64, row.key[key_prefix.len..], 16) catch return error.InvalidGenerationPublication;
        var key_buf: [160]u8 = undefined;
        const publication_bytes = txn.get(try fk_generation_publication.key(&key_buf, group_id, table_id)) catch |err| switch (err) {
            error.NotFound => return error.InvalidGenerationPublication,
            else => return err,
        };
        var publication = try std.json.parseFromSlice(fk_generation_publication.Publication, self.alloc, publication_bytes, .{});
        defer publication.deinit();
        if (publication.value.plan.child_before.table_id != table_id or
            !std.mem.eql(u8, row.value, &publication.value.plan.id) or
            publication.value.phase == .published or publication.value.phase == .canceled)
            return error.InvalidGenerationPublication;
        try publication.value.validateState(self.alloc);
        return alloc.dupe(u8, publication_bytes);
    }

    pub fn fkGenerationPublicationDecisionJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: fk_generation_publication.DecisionRequest) ![]u8 {
        if (request.parent_table_id == 0 or request.parent_group_id == 0 or request.child_table_id == 0 or
            request.child_table_name.len == 0 or std.mem.allEqual(u8, &request.plan_id, 0)) return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var key_buf: [160]u8 = undefined;
        var parsed = try std.json.parseFromSlice(fk_generation_publication.Publication, a, txn.get(try fk_generation_publication.key(&key_buf, group_id, request.child_table_id)) catch return error.GenerationPublicationNotFound, .{});
        defer parsed.deinit();
        const publication = parsed.value;
        if (!std.mem.eql(u8, &publication.plan.id, &request.plan_id) or
            !std.mem.eql(u8, publication.plan.child_before.name, request.child_table_name) or
            publication.phase != switch (request.action) {
                .stage => fk_generation_publication.Phase.staging_parents,
                .activate => .activating_parents,
                .acknowledge => @as(fk_generation_publication.Phase, if (publication.phase == .acknowledging_reference_coverage) .acknowledging_reference_coverage else .acknowledging_parents),
                .cancel => .canceling,
            }) return error.GenerationPublicationChanged;
        // DROP proves empty future reference coverage from the frozen source
        // and retire-only parent generations before deleting the source owner.
        // Ordinary ALTER still requires the installed successor child image.
        try self.validateFkGenerationCutTxn(&txn, group_id, publication.plan, publication.phase == .acknowledging_reference_coverage and publication.plan.sql_drop == null);
        const parent = for (publication.plan.parents) |candidate| {
            if (candidate.table.table_id == request.parent_table_id) break candidate;
        } else return error.GenerationPublicationChanged;
        if (publication.phase == .acknowledging_reference_coverage and !publication.plan.needsParentCoverage(parent)) return error.GenerationPublicationChanged;
        const index = for (parent.ranges, 0..) |range, i| {
            if (range.group_id == request.parent_group_id) break i;
        } else return error.GenerationPublicationChanged;
        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_bytes = txn.get(try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id)) catch return error.InvalidMetadataIncarnation;
        const incarnation = (try decodeMetadataIncarnationRecord(incarnation_bytes)).incarnation;
        const decision: fk_generation_publication.Decision = .{
            .sql_drop_control = publication.plan.sql_drop != null,
            .historical_reference_coverage = publication.plan.historical_reference_coverage,
            .reference_coverage_ready = publication.phase == .acknowledging_reference_coverage,
            .phase = publication.phase,
            .metadata_group_id = group_id,
            .metadata_incarnation = incarnation,
            .metadata_epoch = publication.revision,
            .plan_digest = publication.plan_digest,
            .fence = parent.fences[index],
            .transitions = parent.transitions,
            .parent_table = parent.table,
            .parent_range = parent.ranges[index],
        };
        return std.json.Stringify.valueAlloc(alloc, decision, .{});
    }

    pub fn fkGenerationPublicationSourceDecisionJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: fk_generation_publication.SourceDecisionRequest) ![]u8 {
        if (request.child_table_id == 0 or request.child_group_id == 0 or request.child_table_name.len == 0 or
            std.mem.allEqual(u8, &request.plan_id, 0)) return error.InvalidGenerationPublication;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var key_buf: [160]u8 = undefined;
        var parsed = try std.json.parseFromSlice(fk_generation_publication.Publication, a, txn.get(try fk_generation_publication.key(&key_buf, group_id, request.child_table_id)) catch return error.GenerationPublicationNotFound, .{});
        defer parsed.deinit();
        const publication = parsed.value;
        if (!std.mem.eql(u8, &publication.plan.id, &request.plan_id) or
            !std.mem.eql(u8, publication.plan.child_before.name, request.child_table_name) or
            publication.phase != switch (request.action) {
                .fence => fk_generation_publication.Phase.fencing_child,
                .install => .installing_child,
                .cancel => .canceling,
            }) return error.GenerationPublicationChanged;
        try self.validateFkGenerationCutTxn(&txn, group_id, publication.plan, request.action == .install);
        const index = for (publication.plan.child_ranges, 0..) |range, i| {
            if (range.group_id == request.child_group_id) break i;
        } else return error.GenerationPublicationChanged;
        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_bytes = txn.get(try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id)) catch return error.InvalidMetadataIncarnation;
        const incarnation = (try decodeMetadataIncarnationRecord(incarnation_bytes)).incarnation;
        const decision: fk_generation_publication.SourceDecision = .{
            .sql_drop_control = publication.plan.sql_drop != null,
            .historical_reference_coverage = publication.plan.historical_reference_coverage,
            .phase = publication.phase,
            .metadata_group_id = group_id,
            .metadata_incarnation = incarnation,
            .metadata_epoch = publication.revision,
            .plan_digest = publication.plan_digest,
            .fence = publication.plan.child_fences[index],
            .child_before = publication.plan.child_before,
            .child_after = publication.plan.child_after,
            .child_catalog_before_b64 = publication.plan.child_catalog_before_b64,
            .child_range = publication.plan.child_ranges[index],
            .catalog_coverage = publication.plan.catalog_coverage,
        };
        return std.json.Stringify.valueAlloc(alloc, decision, .{});
    }

    pub fn preflightFkGenerationNameAdmission(self: *RaftApplyStore, group_id: u64, plan: fk_generation_publication.Plan) !void {
        try plan.validate(self.alloc);
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [160]u8 = undefined;
        const existing = txn.get(try fk_generation_publication.key(&key_buf, group_id, plan.child_before.table_id)) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (existing) |bytes| {
            var prior = try std.json.parseFromSlice(fk_generation_publication.Publication, self.alloc, bytes, .{});
            defer prior.deinit();
            try prior.value.validate(self.alloc);
            if (prior.value.phase != .published and prior.value.phase != .canceled) return error.GenerationPublicationChanged;
        }
        try self.validateFkGenerationBeginAdmissionTxn(&txn, group_id, plan);
    }

    /// Every expected rejection in this helper is read-only. Lock acquisition
    /// begins only after all owners pass; errors after that point must abort.
    fn validateSqlDropDependenciesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, table: metadata.TableRecord) !void {
        if (try sql_views.firstDependent(txn, group, .table, table.table_id, null) != null) return error.SqlDependentObjectsExist;
        if (try self.extensionOwnsTableTxn(txn, group, table.name)) return error.ExtensionOwnedObject;
        if (try backupCohortLocksTableTxn(txn, group, table.table_id) or try restoreStagingLocksTableTxn(txn, group, table.table_id)) return error.TableTransitionActive;
        var prefix_buffer: [128]u8 = undefined;
        const prefix = try tablePrefixForGroup(&prefix_buffer, group);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        while (row) |entry| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            const candidate = try borrowTableProjection(entry.value, .schema);
            if (candidate.table_id == table.table_id) continue;
            const definition = candidate.query_definition orelse return error.InvalidCatalogRecord;
            // Historical read layouts decode old rows; they do not resurrect
            // a logically removed FK. In-flight generation publication holds
            // the shared parent lifecycle lock until its native ACKs finish.
            var declarations = try RelationalDeclarations.parse(self.alloc, definition.schema_json);
            defer declarations.deinit();
            if (declarations.value.references(table.name)) return error.ForeignKeyReferenced;
        }
    }

    fn validateFkGenerationBeginAdmissionTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, plan: fk_generation_publication.Plan) !void {
        if (plan.sql_drop) |guard| {
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.sql_drop_generation_version);
            try self.validateRelationMutationTxn(txn, group_id, guard, plan.child_before, plan.child_before);
            try self.validateSqlDropDependenciesTxn(txn, group_id, plan.child_before);
        }
        if (plan.readerPublicationRequired())
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_reader_publication_version);
        if (plan.constraint_name_guard) |guard|
            try self.validateRelationMutationTxn(txn, group_id, guard, plan.child_before, plan.child_after);
        var policy = try system_catalog_storage.loadPolicyPublication(self.alloc, txn, group_id, plan.child_before.table_id);
        defer if (policy) |*record| record.deinit();
        if (policy) |record| if ((plan.sql_drop == null and record.value.phase != .disabled) or system_catalog_storage.policyPublicationNeedsWork(record.value)) return error.RowPolicyUnsupported;
        try self.validateFkGenerationCutTxn(txn, group_id, plan, false);
        for (plan.parents) |parent| {
            if (plan.sql_drop == null) {
                if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, parent.table.table_id)) return error.RowPolicyUnsupported;
            } else {
                var parent_policy = try system_catalog_storage.loadPolicyPublication(self.alloc, txn, group_id, parent.table.table_id);
                defer if (parent_policy) |*record| record.deinit();
                if (parent_policy) |record| if (system_catalog_storage.policyPublicationNeedsWork(record.value)) return error.RowPolicyUnsupported;
            }
        }
        for (0..plan.parents.len + 1) |i| {
            const table_id = if (i == 0) plan.child_before.table_id else plan.parents[i - 1].table.table_id;
            if (i != 0 and table_id == plan.child_before.table_id) continue;
            if (try self.fkTableLockKindTxn(txn, group_id, table_id) != null) return error.GenerationPublicationChanged;
        }
    }

    /// A preflight is only a hint. Committed apply repeats every check against
    /// its own transaction before staging either progress record.
    pub fn validateRelationalIndexOwnerAck(self: *RaftApplyStore, group_id: u64, bytes: []const u8) !void {
        if (bytes.len == 0 or bytes.len > index_publication.max_ack_bytes) return error.InvalidGenerationPublication;
        var txn = try self.beginIndexedReportRead(group_id);
        defer txn.abort();
        _ = try self.prepareRelationalIndexOwnerAckTxn(&txn, group_id, bytes);
    }

    const IndexOwnerAck = struct {
        table_id: u64,
        ordinal: u16,
        update: @import("antfly_local_sources").storage_db_relational_index_publication_progress.PreparedAck,
        action: index_progress.Action,
        proof_bytes: index_publication.StoredProof,

        /// Every failure after staging begins must abort the outer transaction.
        /// Proof persistence and terminal lock retirement share the same
        /// atomic cut in production and fault-injected transaction adapters.
        fn stage(self: *const @This(), txn: anytype, group_id: u64) !void {
            var head_buf: [192]u8 = undefined;
            var owner_buf: [192]u8 = undefined;
            try self.update.stage(txn, try index_publication.headKey(&head_buf, group_id, self.table_id), try index_publication.ownerKey(&owner_buf, group_id, self.table_id, self.ordinal));
            if (self.update.changed) {
                var proof_buf: [160]u8 = undefined;
                try txn.put(try index_publication.proofKey(&proof_buf, group_id, self.table_id, self.ordinal, self.action), self.proof_bytes.slice());
                const next = try index_progress.Head.decode(&self.update.next_head);
                if (next.phase == .canceled) {
                    // The shared relation-command journal derives the exact
                    // name removal from this source deletion. Never release
                    // the lock while leaving a phantom pending publication.
                    try txn.delete(try index_publication.activeKey(&proof_buf, group_id, self.table_id));
                    try relation_reconciliation.advanceTrackedSource(txn, group_id);
                }
                if (next.phase == .published or next.phase == .canceled)
                    try @import("../table_lifecycle_lock.zig").release(txn, group_id, self.table_id, .{ .kind = .index_build, .id = next.plan_id });
            }
        }
    };

    fn prepareRelationalIndexOwnerAckTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !IndexOwnerAck {
        const progress = @import("antfly_local_sources").storage_db_relational_index_publication_progress;
        if (bytes.len == 0 or bytes.len > index_publication.max_ack_bytes) return error.InvalidGenerationPublication;
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_head_version);
        var parsed = try std.json.parseFromSlice(index_publication.Ack, self.alloc, bytes, .{});
        defer parsed.deinit();
        const ack = parsed.value;
        try ack.validate();
        if (ack.table_id == 0 or ack.signed.receipt.owner.namespace.table_id != ack.table_id) return error.InvalidIndexOwnerReceipt;
        const lifecycle = @import("../table_lifecycle_lock.zig");
        const lock = (try lifecycle.read(txn, group_id, ack.table_id)) orelse return error.GenerationPublicationChanged;
        if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &ack.signed.receipt.owner.plan_id)) return error.GenerationPublicationChanged;
        var buf: [192]u8 = undefined;
        const ordinal = index_publication.ownerOrdinal(txn, group_id, ack.table_id, ack.signed.receipt.owner.group_id) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationChanged,
            else => return err,
        };
        if (ordinal != ack.signed.receipt.owner.ordinal) return error.InvalidIndexOwnerReceipt;
        // Copy the fixed head before another get can reuse its borrowed buffer.
        const head_bytes = (try stagingGet(txn, try index_publication.headKey(&buf, group_id, ack.table_id))) orelse return error.InvalidCatalogRecord;
        if (head_bytes.len != progress.Head.encoded_len) return error.InvalidCatalogRecord;
        const owned_head = head_bytes[0..progress.Head.encoded_len].*;
        const head = try progress.Head.decode(&owned_head);
        try index_publication.requireActivePointer(txn, group_id, head);
        const owner_bytes = (try stagingGet(txn, try index_publication.ownerKey(&buf, group_id, ack.table_id, ordinal))) orelse return error.InvalidCatalogRecord;
        const previous_owner = try progress.OwnerState.decode(owner_bytes);
        var update = try progress.PreparedAck.prepare(&owned_head, owner_bytes, ack.expected_revision, ack.signed.receipt);
        const action = ack.signed.receipt.action;
        const action_index = @backingInt(action);
        const previous_root = previous_owner.attestations[action_index];
        const logical_present = !std.mem.allEqual(u8, &previous_owner.receipts[action_index], 0);
        if (logical_present != !std.mem.allEqual(u8, &previous_root, 0)) return error.InvalidCatalogRecord;
        const retained = try stagingGet(txn, try index_publication.proofKey(&buf, group_id, ack.table_id, ordinal, action));
        var previous_evidence: ?index_publication.AuditEvidence = null;
        var previous_terminal: ?[32]u8 = null;
        var previous_cancellation_predecessor: ?[32]u8 = null;
        if (logical_present) {
            const previous = try index_publication.storedProof(self.alloc, retained orelse return error.InvalidCatalogRecord, head, previous_owner, action);
            if (previous.validation) |witness| previous_evidence = .{ .outcome = witness.outcome, .signed = witness.signed };
            if (previous.installation) |witness| previous_evidence = .{ .outcome = witness.outcome, .signed = witness.signed };
            if (previous.terminal) |witness| previous_terminal = witness.record_digest;
            if (previous.cancellation) |witness| previous_cancellation_predecessor = witness.predecessor_commitment;
        } else if (retained != null) return error.InvalidCatalogRecord;
        const cleanup_refresh = head.phase == .canceling and logical_present and (action == .fenced or action == .reserved) and (try previous_owner.latestReceiptAction()) == action;
        try self.requireIndexOwnerRootProofTxn(txn, group_id, ack.signed.receipt.owner, ack.signed.receipt.position, ack.signed.proof, head.reader_requirements, action == .canceled or action == .cancel_released or cleanup_refresh);
        if (ack.validation) |witness| {
            if (logical_present and (try previous_owner.latestReceiptAction()) == .validated) {
                _ = try self.verifyRelationalIndexAuditModeTxn(txn, group_id, witness.signed, witness.outcome, .validation_recovery);
            } else _ = try self.verifyRelationalIndexAuditTxn(txn, group_id, witness.signed, witness.outcome);
        }
        if (ack.installation) |witness| try self.verifyRelationalIndexInstallationTxn(txn, group_id, witness);
        if (ack.cancellation) |witness| try self.verifyRelationalIndexCancellationTxn(txn, group_id, head, previous_owner, witness, ack.signed);
        if (action == .released)
            try self.verifyRelationalIndexReleaseTxn(txn, group_id, head, previous_owner, ack.signed, ack.terminal);
        if (action == .cancel_released)
            try self.verifyRelationalIndexCancellationReleaseTxn(txn, group_id, head, previous_owner, ack.signed, ack.terminal);
        const root = try ack.signed.commitment();
        if (previous_evidence) |previous| {
            const old_grant = previous.signed.proof;
            const next_evidence = ack.auditEvidence() orelse return error.InvalidIndexOwnerReceipt;
            const new_grant = next_evidence.signed.proof;
            if (std.meta.eql(old_grant.identity, new_grant.identity) and std.meta.eql(old_grant.authority, new_grant.authority) and
                old_grant.root_generation == new_grant.root_generation and old_grant.reporter_incarnation == new_grant.reporter_incarnation and
                !std.mem.eql(u8, &previous.signed.outcome_digest, &next_evidence.signed.outcome_digest)) return error.IndexOwnerReceiptChanged;
        }
        const terminal_changed = if (ack.terminal) |witness| logical_present and (previous_terminal == null or !std.mem.eql(u8, &witness.record_digest, &previous_terminal.?)) else false;
        const cancellation_join_changed = if (ack.cancellation) |witness| logical_present and !std.meta.eql(witness.predecessor_commitment, previous_cancellation_predecessor) else false;
        if (!std.mem.eql(u8, &root, &previous_root) or terminal_changed or cancellation_join_changed) {
            if (!update.changed) {
                // A different current root can re-attest only the latest
                // completed stage. Never rewrite historical phase evidence.
                if ((try previous_owner.latestReceiptAction()) != action) return error.GenerationPublicationChanged;
                var refreshed = head;
                refreshed.revision = std.math.add(u64, head.revision, 1) catch return error.GenerationPublicationChanged;
                update.next_head = try refreshed.encode();
                update.changed = true;
            }
            var next_owner = try progress.OwnerState.decode(&update.next_owner);
            next_owner.attestations[action_index] = root;
            update.next_owner = try next_owner.encode();
        }
        return .{ .table_id = ack.table_id, .ordinal = ordinal, .update = update, .action = action, .proof_bytes = if (update.changed) try index_publication.StoredProof.encode(ack.signed, ack.validation, ack.installation, ack.cancellation, ack.terminal) else undefined };
    }

    fn ackRelationalIndexPublicationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        const prepared = self.prepareRelationalIndexOwnerAckTxn(txn, group_id, bytes) catch |err| switch (err) {
            // A valid proposer can lose its preflight cut to another ACK or
            // owner replacement. These checks have staged NO writes. Never
            // swallow errors from stage(), where a storage write can fail.
            error.GenerationPublicationChanged, error.IndexOwnerReceiptChanged => return,
            else => return err,
        };
        try prepared.stage(txn, group_id);
    }

    fn requireIndexOwnerRootReceiptTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, signed: index_publication.SignedReceipt, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !void {
        return self.requireIndexOwnerRootProofTxn(txn, group_id, signed.receipt.owner, signed.receipt.position, signed.proof, requirements, signed.receipt.action == .canceled or signed.receipt.action == .cancel_released);
    }

    /// Shared physical authority checks. Callers verify the domain-specific
    /// signature first; this never interprets a delivery as a publication ACK.
    fn requireIndexOwnerRootProofTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, owner: index_progress.Owner, cut: @import("antfly_local_sources").storage_db_receipt_position.Position, proof: index_publication.RootProof, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements, cleanup: bool) !void {
        try owner.validate();
        return self.requireOwnerRootProofTxn(txn, group_id, .{
            .group_id = owner.group_id,
            .namespace = owner.namespace,
            .authority = switch (owner.authority) {
                .native => .native,
                .raft => .raft,
            },
        }, cut, proof, requirements, .{ .cleanup = cleanup });
    }

    const OwnerRootProofOptions = struct {
        cleanup: bool = false,
        require_source_authority: bool = false,
        allow_empty_preparation: bool = false,
        /// Only an independently signed native view with a certified shared
        /// prefix may have a genuinely empty data cut below that prefix.
        allow_empty_snapshot_cut: bool = false,
        completed: ?@import("antfly_local_sources").storage_read_consistency.ReadSafetyBarrier.FrozenProof = null,
    };

    /// Enrollment, placement, reporter and actual source-cut verification is
    /// shared across owner protocols. Callers MUST verify their domain-specific
    /// signature and admitted logical identity before entering this helper.
    /// No schema-validation receipt is converted into an index-build receipt.
    fn requireOwnerRootProofTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, owner: @import("../store_root_attestation.zig").OwnerScope, cut: ?@import("antfly_local_sources").storage_db_receipt_position.Position, proof: anytype, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements, options: OwnerRootProofOptions) !void {
        try owner.validate();
        if (options.allow_empty_snapshot_cut and (cut != null or options.completed == null or owner.authority != .raft)) return error.InvalidControlReceiptPosition;
        if (cut) |position| try position.requireNamespace(owner.namespace) else if (!options.allow_empty_preparation) return error.InvalidControlReceiptPosition;
        if (owner.authority != switch (proof.authority) {
            .native => @FieldType(@import("../store_root_attestation.zig").OwnerScope, "authority").native,
            .raft => @FieldType(@import("../store_root_attestation.zig").OwnerScope, "authority").raft,
        }) return error.IndexOwnerReceiptChanged;
        if (cut) |position| if ((owner.authority == .native) != (position == .native)) return error.IndexOwnerReceiptChanged;
        self.requireStoreRootEnrollmentTxn(txn, group_id, proof.identity) catch |err| switch (err) {
            error.InvalidStoreRootEnrollment, error.StoreRootEnrollmentChanged => return error.IndexOwnerReceiptChanged,
            else => return err,
        };
        const current = (try self.loadStoreHeaderTxn(txn, group_id, proof.identity.store_id)) orelse return error.IndexOwnerReceiptChanged;
        defer metadata_table_manager.freeStore(self.alloc, current);
        if (!current.live or current.node_id != proof.identity.node_id or current.reporter_incarnation != proof.reporter_incarnation or
            current.replica_root_incarnation != proof.identity.root_incarnation or !std.mem.eql(u8, &current.replica_root_public_key, &proof.identity.public_key))
            return error.IndexOwnerReceiptChanged;
        var buf: [256]u8 = undefined;
        const cluster = (try stagingGet(txn, try metadataIncarnationKeyForGroup(&buf, group_id))) orelse return error.IndexOwnerReceiptChanged;
        if (!std.mem.eql(u8, &(try decodeMetadataIncarnationRecord(cluster)).incarnation, &proof.identity.metadata_incarnation)) return error.IndexOwnerReceiptChanged;
        // Use the current enrolled reporter, never a capability in the ACK.
        // Pre-install cancellation must remain possible after capability loss;
        // its cleanup proves that no candidate became public.
        if (!options.cleanup) {
            if (!metadata_table_manager.storeServesTableData(current.role)) return error.IndexOwnerReceiptChanged;
            if (requirements) |required| if (!current.schema_reader.supports(required)) return error.IndexOwnerReceiptChanged;
        }
        const range_bytes = (try stagingGet(txn, try rangeKeyForGroup(&buf, group_id, owner.group_id))) orelse return error.IndexOwnerReceiptChanged;
        const range = try decodeRangeRecord(self.alloc, range_bytes);
        defer metadata_table_manager.freeRange(self.alloc, range);
        if (range.group_id != owner.group_id or range.table_id != owner.namespace.table_id or
            metadata_table_manager.rangeDocIdentityShardId(range) != owner.namespace.shard_id or
            metadata_table_manager.rangeDocIdentityRangeId(range) != owner.namespace.range_id) return error.IndexOwnerReceiptChanged;
        switch (proof.authority) {
            .raft => |replica_id| {
                const placement = (try self.loadPlacementIntentTxn(txn, try placementKeyForGroup(&buf, group_id, owner.group_id, proof.identity.node_id))) orelse return error.IndexOwnerReceiptChanged;
                defer raft_reconciler.freeIntentOwned(self.alloc, placement);
                if (placement.store_id != proof.identity.store_id or placement.record.group_id != owner.group_id or
                    placement.record.local_node_id != proof.identity.node_id or placement.record.replica_id != replica_id or
                    placement.serving_state != .serving) return error.IndexOwnerReceiptChanged;
            },
            .native => |binding_digest| {
                const raw_binding = (try stagingGet(txn, try standalone_native_owner.key(&buf, group_id))) orelse return error.IndexOwnerReceiptChanged;
                const binding = standalone_native_owner.decode(raw_binding) catch return error.InvalidCatalogRecord;
                if (!std.mem.eql(u8, &binding.metadata_incarnation, &proof.identity.metadata_incarnation) or
                    binding.node_id != proof.identity.node_id or binding.store_id != proof.identity.store_id or
                    binding.root_incarnation != proof.identity.root_incarnation or
                    !std.mem.eql(u8, &try binding.digest(), &binding_digest)) return error.IndexOwnerReceiptChanged;
            },
        }
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const address = try ReportAddress.active(a, txn, group_id, current.store_id);
        const report = (try readStoreGroupReportTxn(a, txn, group_id, address, owner.group_id, true)) orelse return error.IndexOwnerReceiptChanged;
        if (report.runtime_statuses.len != 1) return error.IndexOwnerReceiptChanged;
        const runtime = report.runtime_statuses[0];
        if (options.require_source_authority and runtime.source_authority == null) return error.IndexOwnerReceiptChanged;
        const root_epoch = @import("antfly_local_sources").storage_db_root_signing_identity.attestedRootGeneration(runtime.lsm_root_generation) catch return error.IndexOwnerReceiptChanged;
        if (runtime.table_id != owner.namespace.table_id or runtime.store_id != current.store_id or runtime.node_id != current.node_id or
            root_epoch != proof.root_generation) return error.IndexOwnerReceiptChanged;
        // Raft cuts require the owner observation to have caught up; a native
        // commit sequence is deliberately never compared to a Raft index.
        switch (proof.authority) {
            .raft => {
                if (runtime.source_authority) |state| {
                    if (state.kind != .raft or !std.mem.eql(u8, &state.namespace, &@import("antfly_local_sources").storage_db_online_source_contract.namespaceBytes(owner.namespace)))
                        return error.IndexOwnerReceiptChanged;
                }
                if (report.group_statuses.len != 1) return error.IndexOwnerReceiptChanged;
                const status = report.group_statuses[0];
                // The report and completed-prefix proof have independent
                // clocks from the last actual data entry. Recheck both in the
                // accepting metadata transaction, never synthesize an entry.
                if (options.completed) |completed| {
                    if (completed.incarnation == 0 or completed.term == 0 or completed.applied_index == 0 or
                        status.raft_applied_index < completed.applied_index or status.raft_term < completed.term)
                        return error.IndexOwnerReceiptChanged;
                }
                if (cut) |position| {
                    if (status.raft_applied_index < position.raft.index or status.raft_term < position.raft.term) return error.IndexOwnerReceiptChanged;
                } else if (status.raft_applied_index != 0 and !options.allow_empty_snapshot_cut) return error.IndexOwnerReceiptChanged;
            },
            .native => {
                if (options.completed != null) return error.IndexOwnerReceiptChanged;
                const state = runtime.source_authority orelse return error.IndexOwnerReceiptChanged;
                if (state.kind != .native or
                    !std.mem.eql(u8, &state.namespace, &@import("antfly_local_sources").storage_db_online_source_contract.namespaceBytes(owner.namespace)))
                    return error.IndexOwnerReceiptChanged;
                if (cut) |position| {
                    if (state.sequence < position.native.sequence) return error.IndexOwnerReceiptChanged;
                } else if (state.sequence != 0) return error.IndexOwnerReceiptChanged;
            },
        }
    }

    /// Pre-job root discovery is authenticated independently of progress ACKs.
    /// Empty clocks remain empty: metadata checks the actual zero report rather
    /// than inventing a commit position. The exact live table/cover and SQL
    /// mutation guard remain admission's additional obligations.
    pub fn verifySchemaValidationPreparationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, binding: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Binding, physical_root: u128, signed: @import("../schema_validation_attestation.zig").SignedPreparation, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !void {
        try signed.verifyFor(binding, physical_root);
        try self.requireOwnerRootProofTxn(txn, group_id, .{
            .group_id = binding.fence.owner_group_id,
            .namespace = binding.fence.namespace,
            .authority = binding.authority,
        }, signed.value.position, signed.proof, requirements, .{ .require_source_authority = true, .allow_empty_preparation = true });
    }

    /// Pre-transfer source authentication for a durable parent grant. A later
    /// adopter must consume that retained grant rather than demand the old
    /// source remain live. This helper stages no grant or owner mutation.
    pub fn verifySchemaValidationSnapshotParentTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, binding: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Binding, physical_root: u128, signed: @import("../schema_validation_attestation.zig").SignedSnapshotParent, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !void {
        try signed.verifyFor(binding, physical_root);
        const cut: ?@import("antfly_local_sources").storage_db_receipt_position.Position = if (signed.value.origin.applied) |value| .{ .raft = .{ .term = value.term, .index = value.index } } else null;
        try self.requireOwnerRootProofTxn(txn, group_id, .{
            .group_id = binding.fence.owner_group_id,
            .namespace = binding.fence.namespace,
            .authority = .raft,
        }, cut, signed.proof, requirements, .{
            .require_source_authority = true,
            .allow_empty_preparation = true,
            .allow_empty_snapshot_cut = cut == null,
            .completed = signed.value.completed,
        });
    }

    /// Join a complete physical witness with the frozen source/target ledger
    /// and current root authority in one read set. This stages no writes; any
    /// accepting publication transaction must repeat this exact verification.
    pub fn verifyRelationalIndexAuditTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, signed: index_publication.SignedAudit, outcome: @import("antfly_local_sources").storage_db_relational_index_owner_control.AuditOutcome) ![32]u8 {
        return self.verifyRelationalIndexAuditModeTxn(txn, group_id, signed, outcome, .validation);
    }

    /// The binding must come from the retained metadata plan, not the ACK.
    /// Root/enrollment/report facts are independently read in the SAME txn
    /// that accepts this result. This method itself stages no writes, grants
    /// no admission and cannot replace the all-owner publication barrier.
    pub fn verifySchemaValidationObservationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, binding: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Binding, signed: @import("../schema_validation_attestation.zig").SignedObservation, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !@import("../schema_validation_attestation.zig").VerifiedObservation {
        return self.verifySchemaValidationObservationTxnMode(txn, group_id, binding, signed, requirements, false);
    }

    fn verifySchemaValidationObservationTxnMode(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, binding: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Binding, signed: @import("../schema_validation_attestation.zig").SignedObservation, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements, cancellation_cleanup: bool) !@import("../schema_validation_attestation.zig").VerifiedObservation {
        try binding.validate();
        switch (signed) {
            inline else => |evidence| {
                const observation = evidence.rooted.observation;
                try observation.validateFor(binding);
                const logical = try evidence.logicalDigest();
                if (evidence.rooted.root_generation == 0 or evidence.proof.root_generation != evidence.rooted.root_generation or
                    (binding.authority == .native) != (evidence.proof.authority == .native)) return error.SchemaValidationJobChanged;
                try evidence.proof.verify(try evidence.evidenceDigest());
                const cut: @import("antfly_local_sources").storage_db_receipt_position.Position = if (comptime @hasField(@TypeOf(observation), "sequence"))
                    .{ .native = .{ .namespace = binding.fence.namespace, .sequence = observation.sequence } }
                else
                    .{ .raft = observation.applied orelse return error.InvalidControlReceiptPosition };
                try self.requireOwnerRootProofTxn(txn, group_id, .{
                    .group_id = binding.fence.owner_group_id,
                    .namespace = binding.fence.namespace,
                    .authority = binding.authority,
                }, cut, evidence.proof, requirements, .{
                    .cleanup = cancellation_cleanup,
                    .require_source_authority = true,
                    .completed = if (comptime @hasField(@TypeOf(evidence.rooted), "completed")) evidence.rooted.completed else null,
                });
                return .{
                    .header = observation.header.?,
                    .logical_digest = logical,
                    .root_commitment = try evidence.commitment(),
                    .physical_root_incarnation = observation.physical_root_incarnation,
                };
            },
        }
    }

    /// Reconstruct release from metadata's accepted installed cut. Replaying
    /// the old generation audit after release would incorrectly reject normal
    /// user writes; the terminal native receipt binds the immutable build cut.
    fn verifyRelationalIndexCancellationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, head: index_progress.Head, owner: index_progress.OwnerState, witness: index_publication.CancellationWitness, signed: index_publication.SignedReceipt) !void {
        _ = try self.currentIndexBuildOwnerTxnImpl(txn, group_id, witness.record.binding, null, .cancellation);
        var dispatch = try index_publication.readDispatch(self.alloc, txn, group_id, owner.owner);
        defer dispatch.deinit();
        var prior: ?index_publication.StoredProof.Decoded = null;
        var buf: [192]u8 = undefined;
        for ([_]index_progress.Action{ .validated, .reserved, .fenced }) |action| {
            if (std.mem.allEqual(u8, &owner.receipts[@backingInt(action)], 0)) continue;
            prior = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, head.table_id, owner.owner.ordinal, action)), head, owner, action);
            break;
        }
        try index_publication.requireCancellationWitness(group_id, head, owner, dispatch.value, witness, signed, prior);
    }

    fn verifyRelationalIndexReleaseTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, head: index_progress.Head, owner: index_progress.OwnerState, signed: index_publication.SignedReceipt, terminal: ?index_publication.TerminalWitness) !void {
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_release_version);
        var buf: [192]u8 = undefined;
        const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, head.table_id, owner.owner.ordinal, .installed)), head, owner, .installed);
        const witness = accepted.installation orelse return error.InvalidCatalogRecord;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        const grant: index_publication.ReleaseGrant = .{
            .installed = .{ .command = witness.command, .position = accepted.signed.receipt.position },
            .decision_digest = try index_publication.ReleaseGrant.decisionDigest(group_id, incarnation, head),
            .installation_proof = accepted.signed.proof,
        };
        try grant.validateFor(group_id, incarnation, head, owner);
        _ = try self.currentIndexBuildOwnerTxnImpl(txn, group_id, grant.installed.command.validation.command.binding, null, .installation);
        try index_publication.requireReleaseReceipt(group_id, incarnation, head, owner, accepted, signed, terminal);
    }

    fn verifyRelationalIndexCancellationReleaseTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, head: index_progress.Head, owner: index_progress.OwnerState, signed: index_publication.SignedReceipt, terminal: ?index_publication.TerminalWitness) !void {
        var buf: [192]u8 = undefined;
        const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, head.table_id, owner.owner.ordinal, .canceled)), head, owner, .canceled);
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        _ = try self.currentIndexBuildOwnerTxnImpl(txn, group_id, (accepted.cancellation orelse return error.InvalidCatalogRecord).record.binding, null, .cancellation);
        try index_publication.requireCancellationReleaseReceipt(group_id, incarnation, head, owner, accepted, signed, terminal);
    }

    fn verifyRelationalIndexInstallationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, witness: index_publication.InstallationWitness) !void {
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_installation_version);
        _ = try self.verifyRelationalIndexAuditModeTxn(txn, group_id, witness.signed, witness.outcome, .installation);
        const table_id = witness.outcome.binding.fence.namespace.table_id;
        const ordinal = witness.outcome.binding.ordinal;
        var buf: [192]u8 = undefined;
        const head = try index_progress.Head.decode(try txn.get(try index_publication.headKey(&buf, group_id, table_id)));
        const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, table_id, ordinal)));
        const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, table_id, ordinal, .validated)), head, owner, .validated);
        const validation_witness = accepted.validation orelse return error.InvalidCatalogRecord;
        const expected_seal: @import("antfly_local_sources").storage_db_relational_index_validation.Seal = .{ .command = try validation_witness.outcome.logicalCommand(), .position = accepted.signed.receipt.position };
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        if (!std.meta.eql(witness.command.validation, expected_seal) or
            !std.mem.eql(u8, &witness.command.metadata_decision, &try index_publication.InstallGrant.decisionDigest(group_id, incarnation, head))) return error.IndexOwnerReceiptChanged;
    }

    fn verifyRelationalIndexAuditModeTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, signed: index_publication.SignedAudit, outcome: @import("antfly_local_sources").storage_db_relational_index_owner_control.AuditOutcome, comptime mode: enum { validation, validation_recovery, installation }) ![32]u8 {
        const audit_digest = try signed.verifiedDigest(outcome);
        const current = try self.currentIndexBuildOwnerTxnImpl(txn, group_id, outcome.binding, null, switch (mode) {
            .validation => .validation,
            .validation_recovery => .validation_recovery,
            .installation => .installation,
        });
        var buf: [192]u8 = undefined;
        const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, current.head.table_id, outcome.binding.ordinal)));
        const frozen = if (mode == .validation) try index_delivery.frozenTarget(self.alloc, txn, group_id, current.head, owner, signed.proof.identity.metadata_incarnation) else try index_delivery.frozenTargetForRecovery(self.alloc, txn, group_id, current.head, owner, signed.proof.identity.metadata_incarnation);
        if (!std.mem.eql(u8, &try frozen.expected.digest(), &try outcome.expected.digest()) or
            outcome.audit.source_members.? != frozen.source_members or
            !outcome.audit.canonical_position.?.strictlyAfter(frozen.source_position)) return error.IndexOwnerReceiptChanged;
        try self.requireIndexOwnerRootProofTxn(txn, group_id, current.owner, outcome.audit.canonical_position.?, signed.proof, current.head.reader_requirements, false);
        return signed.proof.commitment(audit_digest);
    }

    /// Verify one exact target partition against a single current metadata
    /// cut. Read-only: this is neither source provenance nor source consumption.
    /// A future durable ACK must repeat these reads in its accepting transaction.
    pub fn verifyRelationalIndexClaimDeliveryTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, signed: index_publication.SignedClaimDelivery, command: @import("antfly_local_sources").storage_db_relational_index_owner_control.ClaimCommand) ![32]u8 {
        try signed.verifyFor(command);
        const cut = try self.currentIndexBuildOwnerTxn(txn, group_id, command.binding, null);
        try self.requireIndexOwnerRootProofTxn(txn, group_id, cut.owner, signed.outcome.position, signed.proof, cut.head.reader_requirements, false);
        return signed.commitment();
    }

    /// Authenticate source provenance against the same current metadata cut as
    /// target delivery. Read-only; a durable all-partition ACK must repeat this
    /// check in its accepting transaction before it can authorize consumption.
    pub fn verifyRelationalIndexSourceBatchTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, signed: index_publication.SignedSourceBatch, read: *const @import("antfly_local_sources").storage_db_relational_index_owner_control.SourceRead) ![32]u8 {
        const source_digest = try signed.verifiedDigest(read);
        const cut = try self.currentIndexBuildOwnerTxn(txn, group_id, read.binding, read.batch.?.scope.table_name);
        try self.requireIndexOwnerRootProofTxn(txn, group_id, cut.owner, try signed.header.orderedPosition(), signed.proof, cut.head.reader_requirements, false);
        return signed.proof.commitment(source_digest);
    }

    const CurrentIndexBuildOwner = struct { head: index_progress.Head, owner: index_progress.Owner };

    fn readIndexClaimRoutesTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, head: index_progress.Head, groups: index_publication.ClaimGroups) !index_publication.ClaimRoutes {
        try groups.validate();
        try head.validate();
        try index_publication.requireActivePointer(txn, group_id, head);
        const lock = (try @import("../table_lifecycle_lock.zig").read(txn, group_id, head.table_id)) orelse return error.GenerationPublicationChanged;
        if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &head.plan_id)) return error.GenerationPublicationChanged;
        const routing = @import("antfly_local_sources").storage_db_relational_index_owner_job.private_claims.delivery;
        const routes = try alloc.alloc(routing.Target, groups.items.len);
        var buf: [192]u8 = undefined;
        for (groups.items, routes) |peer_group, *target| {
            const ordinal = index_publication.ownerOrdinal(txn, group_id, head.table_id, peer_group) catch |err| switch (err) {
                error.NotFound => return error.GenerationPublicationChanged,
                else => return err,
            };
            const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, head.table_id, ordinal)));
            if (try index_publication.ownerPermission(head, owner, .build) != .execute) return error.GenerationPublicationChanged;
            var dispatch = try index_publication.readDispatch(self.alloc, txn, group_id, owner.owner);
            defer dispatch.deinit();
            const range = try decodeRangeRecord(self.alloc, try txn.get(try rangeKeyForGroup(&buf, group_id, peer_group)));
            defer metadata_table_manager.freeRange(self.alloc, range);
            if (!metadata_table_manager.rangeRecordsEqual(range, dispatch.value.owner.range)) return error.GenerationPublicationChanged;
            target.* = .{ .owner = owner.owner, .start = try alloc.dupe(u8, routing.routingBound(range.start_key)), .end = try alloc.dupe(u8, routing.routingBound(range.end_key orelse "")) };
        }
        return .{ .items = routes };
    }

    /// Compact all-partition preflight, without row bodies or schema-sized
    /// projections. This is not a durable decision or consumption permission.
    pub fn verifyRelationalIndexSourceDeliveryTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, signed: @import("../relational_index_source_delivery.zig").Signed) ![32]u8 {
        try signed.verify();
        const data = signed.data;
        const source = try self.currentIndexBuildOwnerTxn(txn, group_id, data.source, null);
        var dispatch = try index_publication.readDispatch(self.alloc, txn, group_id, source.owner);
        defer dispatch.deinit();
        const Source = @import("antfly_local_sources").storage_db_relational_index_owner_job.private_claims.SourceStream;
        const raw = &data.header.bytes;
        const scope: Source.Scope = .{ .table_name = dispatch.value.table_name, .generation = raw[72..88].*, .schema_version = std.mem.readInt(u32, raw[88..92], .little), .tuple_fingerprint = raw[192..224].*, .nulls_not_distinct = raw[185] != 0 };
        if (scope.table_name.len != std.mem.readInt(u32, raw[92..96], .little) or !std.mem.eql(u8, &try scope.digest(), raw[40..72])) return error.PrivateIndexOwnerJobChanged;
        try self.requireIndexOwnerRootProofTxn(txn, group_id, source.owner, try data.header.orderedPosition(), signed.proof, source.head.reader_requirements, false);
        for (data.parts.items) |part| {
            try part.target.verifyRecorded(part.rows);
            const target = try self.currentIndexBuildOwnerTxn(txn, group_id, part.target.outcome.binding, null);
            try self.requireIndexOwnerRootProofTxn(txn, group_id, target.owner, part.target.outcome.position, part.target.proof, target.head.reader_requirements, false);
        }
        return signed.proof.commitment(try data.digest());
    }

    const SourceDeliveryAuthority = struct {
        store: *RaftApplyStore,
        pub fn verifyDelivery(self: @This(), txn: *docstore.DocStore.Txn, group: u64, signed: @import("../relational_index_source_delivery.zig").Signed) ![32]u8 {
            return self.store.verifyRelationalIndexSourceDeliveryTxn(txn, group, signed);
        }
        pub fn verifyConsumption(self: @This(), txn: *docstore.DocStore.Txn, group: u64, binding: @import("antfly_local_sources").storage_db_relational_index_owner_job.Binding, consumed: @import("../relational_index_delivery_journal.zig").Consumed) !void {
            try consumed.verify();
            const current = try self.store.currentIndexBuildOwnerTxn(txn, group, binding, null);
            try self.store.requireIndexOwnerRootProofTxn(txn, group, current.owner, consumed.position, consumed.proof, current.head.reader_requirements, false);
        }
    };

    /// Read-only preparation; the accepting command additionally enforces its
    /// coordinated decoder floor. Native consumption remains a separate effect.
    fn prepareRelationalIndexSourceAcceptanceTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, request: @import("../relational_index_delivery_journal.zig").Request) !@import("../relational_index_delivery_journal.zig").Prepared {
        return @import("../relational_index_delivery_journal.zig").prepare(self.alloc, txn, group, request, SourceDeliveryAuthority{ .store = self });
    }

    pub fn validateRelationalIndexSourceAcceptance(self: *RaftApplyStore, group: u64, bytes: []const u8) !void {
        if (bytes.len == 0 or bytes.len > index_delivery.max_command_bytes) return error.InvalidGenerationPublication;
        var txn = try self.beginIndexedReportRead(group);
        defer txn.abort();
        var prepared = try self.parseRelationalIndexSourceAcceptanceTxn(&txn, group, bytes);
        defer prepared.deinit();
    }
    pub fn validateRelationalIndexSourceCompletion(self: *RaftApplyStore, group: u64, bytes: []const u8) !void {
        var txn = try self.beginIndexedReportRead(group);
        defer txn.abort();
        var prepared = try self.parseRelationalIndexSourceCompletionTxn(&txn, group, bytes);
        defer prepared.deinit();
    }
    fn parseRelationalIndexSourceCompletionTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, bytes: []const u8) !index_delivery.PreparedCompletion {
        if (bytes.len == 0 or bytes.len > index_delivery.max_completion_bytes) return error.InvalidGenerationPublication;
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.index_delivery_version);
        var request = try std.json.parseFromSlice(index_delivery.CompletionRequest, self.alloc, bytes, .{ .ignore_unknown_fields = false, .max_value_len = 128 });
        defer request.deinit();
        return index_delivery.prepareCompletion(self.alloc, txn, group, request.value, SourceDeliveryAuthority{ .store = self });
    }
    fn completeRelationalIndexSourceTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, bytes: []const u8) !void {
        var prepared = self.parseRelationalIndexSourceCompletionTxn(txn, group, bytes) catch |err| switch (err) {
            error.GenerationPublicationChanged, error.IndexOwnerReceiptChanged, error.PrivateIndexOwnerJobChanged => return,
            else => return err,
        };
        defer prepared.deinit();
        try prepared.stage(txn, group);
    }
    fn parseRelationalIndexSourceAcceptanceTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, bytes: []const u8) !index_delivery.Prepared {
        if (bytes.len == 0 or bytes.len > index_delivery.max_command_bytes) return error.InvalidGenerationPublication;
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.index_delivery_version);
        var request = try std.json.parseFromSlice(index_delivery.Request, self.alloc, bytes, .{ .max_value_len = 128 });
        defer request.deinit();
        return self.prepareRelationalIndexSourceAcceptanceTxn(txn, group, request.value);
    }
    fn acceptRelationalIndexDeliveryTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, bytes: []const u8) !void {
        var prepared = self.parseRelationalIndexSourceAcceptanceTxn(txn, group, bytes) catch |err| switch (err) {
            // Preflight may lose current authority before ordered apply. These
            // paths have staged no writes; status resolves ambiguous outcomes.
            error.GenerationPublicationChanged, error.IndexOwnerReceiptChanged, error.PrivateIndexOwnerJobChanged => return,
            else => return err,
        };
        defer prepared.deinit();
        try prepared.stage(txn, group);
    }
    pub fn relationalIndexSourceAcceptanceStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, query: index_delivery.Query) ![]u8 {
        try query.validate();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.index_delivery_version);
        var buf: [192]u8 = undefined;
        const head = try index_progress.Head.decode(try txn.get(try index_publication.headKey(&buf, group, query.table_id)));
        if (!std.mem.eql(u8, &head.plan_id, &query.id)) return error.GenerationPublicationChanged;
        const ordinal = try index_publication.ownerOrdinal(&txn, group, query.table_id, query.group_id);
        const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group, query.table_id, ordinal)));
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group)))).incarnation;
        const raw = try stagingGet(&txn, try index_delivery.sourceKey(&buf, group, query.table_id, ordinal));
        var accepted: ?index_delivery.Head = null;
        if (raw) |bytes| {
            var hash: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(bytes, &hash, .{});
            if (!std.mem.eql(u8, &hash, &owner.source_delivery)) return error.InvalidCatalogRecord;
            const prefix_ = try index_delivery.SourceRecord.peek(alloc, bytes);
            if (owner.source_completed != (prefix_.completion != null)) return error.InvalidCatalogRecord;
            accepted = prefix_.head;
            if (!std.mem.eql(u8, &accepted.?.metadata_incarnation, &incarnation)) return error.GenerationPublicationChanged;
        } else if (!std.mem.allEqual(u8, &owner.source_delivery, 0)) return error.InvalidCatalogRecord;
        const pending = try stagingGet(&txn, metadata_hot_standby.outbox_key) != null;
        return std.json.Stringify.valueAlloc(alloc, index_delivery.Status{ .query = query, .head = accepted, .replication_pending = pending, .completed = owner.source_completed }, .{});
    }

    /// Shared fixed-directory/catalog/range checks, not a caller-supplied
    /// verification flag or schema-sized candidate recompilation.
    fn currentIndexBuildOwnerTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, binding: @import("antfly_local_sources").storage_db_relational_index_owner_job.Binding, table_name: ?[]const u8) !CurrentIndexBuildOwner {
        return self.currentIndexBuildOwnerTxnImpl(txn, group_id, binding, table_name, .source);
    }
    fn currentIndexBuildOwnerTxnImpl(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, binding: @import("antfly_local_sources").storage_db_relational_index_owner_job.Binding, table_name: ?[]const u8, comptime mode: enum { source, validation, validation_recovery, installation, cancellation }) !CurrentIndexBuildOwner {
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_head_version);
        const table_id = binding.fence.namespace.table_id;
        const owner_group = binding.fence.owner_group_id;
        var buf: [192]u8 = undefined;
        const head = try index_progress.Head.decode(try txn.get(try index_publication.headKey(&buf, group_id, table_id)));
        try index_publication.requireActivePointer(txn, group_id, head);
        const lock = (try @import("../table_lifecycle_lock.zig").read(txn, group_id, table_id)) orelse return error.GenerationPublicationChanged;
        if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &binding.id)) return error.GenerationPublicationChanged;
        const ordinal = try index_publication.ownerOrdinal(txn, group_id, table_id, owner_group);
        if (ordinal != binding.ordinal) return error.PrivateIndexOwnerJobChanged;
        const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, table_id, ordinal)));
        var dispatch = try index_publication.readDispatch(self.alloc, txn, group_id, owner.owner);
        defer dispatch.deinit();
        const d = dispatch.value;
        if (table_name) |name| if (!std.mem.eql(u8, name, d.table_name)) return error.PrivateIndexOwnerJobChanged;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        const decision: index_publication.OwnerDecision = .{ .metadata_group_id = group_id, .metadata_incarnation = incarnation, .head = head, .owner = owner, .disposition = .execute, .dispatch = d };
        if (mode == .validation or mode == .validation_recovery or mode == .installation or mode == .cancellation) {
            const permitted_phase = if (mode == .validation) head.phase == .building else if (mode == .validation_recovery) (head.phase == .building or head.phase == .installing or head.phase == .releasing or head.phase == .canceling) and (try owner.latestReceiptAction()) == .validated else if (mode == .installation) head.phase == .installing or head.phase == .releasing else head.phase == .canceling or head.phase == .cancel_releasing;
            if (!permitted_phase or (mode != .cancellation and std.mem.allEqual(u8, &owner.receipts[@backingInt(index_progress.Action.reserved)], 0))) return error.GenerationPublicationChanged;
            if (binding.authority == .raft) try decision.requireRetainedRaftBinding(binding) else try decision.requireRetainedNativeBinding(binding);
        } else {
            const request: index_publication.OwnerRequest = .{ .table_id = table_id, .group_id = owner_group, .id = binding.id, .operation = .build };
            if (binding.authority == .native) _ = try decision.nativeBuild(request, binding, .{}) else _ = try decision.raftBuild(request, binding, .{});
        }
        const range = try decodeRangeRecord(self.alloc, try txn.get(try rangeKeyForGroup(&buf, group_id, owner_group)));
        defer metadata_table_manager.freeRange(self.alloc, range);
        if (!metadata_table_manager.rangeRecordsEqual(range, d.owner.range)) return error.GenerationPublicationChanged;
        try IndexPublicationVerification.verifyAuthority(self.alloc, txn, group_id, d, .{ .table_id = table_id, .name = d.table_name });
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        const claim = (try live.getClaim(.{ .namespace_id = d.namespace_id, .name = d.table_guard.logical_table })) orelse return error.GenerationPublicationChanged;
        const after = mode == .installation or (mode == .validation_recovery and (head.phase == .installing or head.phase == .releasing));
        const schema_version = if (after) d.successor_schema_version else d.table_guard.owner.schema_version;
        const schema_digest = if (after) d.successor_schema_digest else d.table_guard.owner.schema_digest;
        if (claim.kind != .table or claim.phase != .active or claim.table_id != table_id or
            claim.schema_version != schema_version or !std.mem.eql(u8, &claim.schema_digest, &schema_digest)) return error.GenerationPublicationChanged;
        return .{ .head = head, .owner = owner.owner };
    }

    /// Bounded hot dispatch: point directory/head/owner/projection/catalog/range
    /// reads only. Immutable schema-sized inputs are fetched at admission only.
    pub fn relationalIndexOwnerAckStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: index_publication.Ack) ![]u8 {
        try request.validate();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_head_version);
        var buf: [192]u8 = undefined;
        const head = index_progress.Head.decode(txn.get(try index_publication.headKey(&buf, group_id, request.table_id)) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationNotFound,
            else => return err,
        }) catch return error.InvalidCatalogRecord;
        try index_publication.requireActivePointer(&txn, group_id, head);
        const ordinal = index_publication.ownerOrdinal(&txn, group_id, request.table_id, request.signed.receipt.owner.group_id) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationChanged,
            else => return err,
        };
        if (ordinal != request.signed.receipt.owner.ordinal) return error.GenerationPublicationChanged;
        const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, request.table_id, ordinal)));
        var status: index_publication.AckStatus = .{ .head = head, .owner = owner, .replication_pending = try stagingGet(&txn, metadata_hot_standby.outbox_key) != null };
        if (request.validation != null and !std.mem.allEqual(u8, &owner.receipts[@backingInt(index_progress.Action.validated)], 0)) {
            const retained = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, .validated)), head, owner, .validated);
            status.validation_digest = (retained.validation orelse return error.InvalidCatalogRecord).signed.outcome_digest;
        }
        if (request.installation != null and !std.mem.allEqual(u8, &owner.receipts[@backingInt(index_progress.Action.installed)], 0)) {
            const retained = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, .installed)), head, owner, .installed);
            status.installation_digest = (retained.installation orelse return error.InvalidCatalogRecord).signed.outcome_digest;
        }
        if (request.terminal != null and !std.mem.allEqual(u8, &owner.receipts[@backingInt(request.signed.receipt.action)], 0)) {
            const retained = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, request.signed.receipt.action)), head, owner, request.signed.receipt.action);
            if (retained.terminal) |witness| status.terminal_digest = witness.record_digest;
        }
        if (request.cancellation) |witness| if (!std.mem.allEqual(u8, &owner.receipts[@backingInt(index_progress.Action.canceled)], 0)) {
            const retained = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, .canceled)), head, owner, .canceled);
            const accepted = retained.cancellation orelse return error.InvalidCatalogRecord;
            if (!std.meta.eql(accepted.record, witness.record)) return error.InvalidCatalogRecord;
            status.cancellation_predecessor = accepted.predecessor_commitment;
        };
        _ = try status.isAcknowledged(request);
        return std.json.Stringify.valueAlloc(alloc, status, .{});
    }

    /// Read only fixed-size native ownership, current reporter and explicit
    /// enrollment. No synthetic listing or caller-provided identity qualifies.
    fn nativeIndexSigningViewTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, incarnation: metadata_incarnation.MetadataClusterIncarnation) !?index_publication.NativeSigningView {
        var buf: [256]u8 = undefined;
        const raw = (try stagingGet(txn, try standalone_native_owner.key(&buf, group_id))) orelse return null;
        const binding = standalone_native_owner.decode(raw) catch return error.InvalidCatalogRecord;
        if (!std.mem.eql(u8, &binding.metadata_incarnation, &incarnation)) return error.InvalidCatalogRecord;
        const current = (try self.loadStoreHeaderTxn(txn, group_id, binding.store_id)) orelse return null;
        defer metadata_table_manager.freeStore(self.alloc, current);
        if (!current.live or current.reporter_incarnation == 0 or current.node_id != binding.node_id or
            current.replica_root_incarnation != binding.root_incarnation or std.mem.allEqual(u8, &current.replica_root_public_key, 0)) return null;
        const view: index_publication.NativeSigningView = .{
            .identity = .{ .metadata_incarnation = incarnation, .node_id = binding.node_id, .store_id = binding.store_id, .root_incarnation = binding.root_incarnation, .public_key = current.replica_root_public_key },
            .reporter_incarnation = current.reporter_incarnation,
            .binding_digest = try binding.digest(),
        };
        try view.validate(incarnation);
        self.requireStoreRootEnrollmentTxn(txn, group_id, view.identity) catch |err| switch (err) {
            error.StoreRootEnrollmentChanged => return null,
            else => return err,
        };
        return view;
    }

    /// One reporter's enrolled root and serving placement from the same
    /// permission snapshot. Request IDs select records, never grant authority.
    /// A missing/stale report returns no signer; corrupt durable reads propagate.
    fn raftIndexSigningViewTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, incarnation: metadata_incarnation.MetadataClusterIncarnation, owner: index_progress.Owner, reporter: index_publication.RaftReporter, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !?index_publication.RaftSigningView {
        return self.raftIndexSigningViewModeTxn(txn, group_id, incarnation, owner, reporter, requirements, false);
    }

    fn raftIndexSigningViewModeTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, incarnation: metadata_incarnation.MetadataClusterIncarnation, owner: index_progress.Owner, reporter: index_publication.RaftReporter, requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements, cleanup: bool) !?index_publication.RaftSigningView {
        try reporter.validate();
        try owner.validate();
        if (owner.authority != .raft) return error.InvalidGenerationPublication;
        const current = (try self.loadStoreHeaderTxn(txn, group_id, reporter.store_id)) orelse return null;
        defer metadata_table_manager.freeStore(self.alloc, current);
        if (current.store_id != reporter.store_id or current.node_id != reporter.node_id or !current.live or
            current.reporter_incarnation == 0 or current.replica_root_incarnation == 0 or
            std.mem.allEqual(u8, &current.replica_root_public_key, 0)) return null;
        if (!cleanup) {
            if (!metadata_table_manager.storeServesTableData(current.role)) return null;
            if (requirements) |required| if (!current.schema_reader.supports(required)) return null;
        }
        const identity: store_root_enrollment.Identity = .{ .metadata_incarnation = incarnation, .node_id = current.node_id, .store_id = current.store_id, .root_incarnation = current.replica_root_incarnation, .public_key = current.replica_root_public_key };
        self.requireStoreRootEnrollmentTxn(txn, group_id, identity) catch |err| switch (err) {
            error.StoreRootEnrollmentChanged => return null,
            else => return err,
        };
        var buf: [256]u8 = undefined;
        const range_bytes = (try stagingGet(txn, try rangeKeyForGroup(&buf, group_id, owner.group_id))) orelse return null;
        const range = try decodeRangeRecord(self.alloc, range_bytes);
        defer metadata_table_manager.freeRange(self.alloc, range);
        if (range.group_id != owner.group_id or range.table_id != owner.namespace.table_id or
            metadata_table_manager.rangeDocIdentityShardId(range) != owner.namespace.shard_id or
            metadata_table_manager.rangeDocIdentityRangeId(range) != owner.namespace.range_id) return null;
        const placement = (try self.loadPlacementIntentTxn(txn, try placementKeyForGroup(&buf, group_id, owner.group_id, reporter.node_id))) orelse return null;
        defer raft_reconciler.freeIntentOwned(self.alloc, placement);
        if (placement.store_id != current.store_id or placement.record.group_id != owner.group_id or
            placement.record.local_node_id != current.node_id or placement.record.replica_id == 0 or placement.serving_state != .serving) return null;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const address = try ReportAddress.active(a, txn, group_id, current.store_id);
        const report = (try readStoreGroupReportTxn(a, txn, group_id, address, owner.group_id, true)) orelse return null;
        if (report.runtime_statuses.len != 1 or report.group_statuses.len != 1) return null;
        const runtime = report.runtime_statuses[0];
        const status = report.group_statuses[0];
        if (runtime.group_id != owner.group_id or runtime.table_id != owner.namespace.table_id or
            runtime.store_id != current.store_id or runtime.node_id != current.node_id or
            status.group_id != owner.group_id or status.raft_term == 0) return null;
        const source = runtime.source_authority orelse return null;
        if (source.kind != .raft or source.sequence != 0 or !std.mem.eql(u8, &source.namespace, &@import("antfly_local_sources").storage_db_online_source_contract.namespaceBytes(owner.namespace))) return null;
        const root_epoch = @import("antfly_local_sources").storage_db_root_signing_identity.attestedRootGeneration(runtime.lsm_root_generation) catch return null;
        const view: index_publication.RaftSigningView = .{ .identity = identity, .reporter_incarnation = current.reporter_incarnation, .group_id = owner.group_id, .namespace = owner.namespace, .replica_id = placement.record.replica_id, .root_generation = root_epoch, .reported_term = status.raft_term, .reported_applied_index = status.raft_applied_index };
        try view.validate(incarnation, owner);
        return view;
    }

    pub fn relationalIndexWorkJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: @import("../relational_index_work.zig").Query) ![]u8 {
        try request.validate();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_head_version);
        return @import("../relational_index_work.zig").readJson(alloc, &txn, group_id, request);
    }

    pub fn relationalIndexOwnerDecisionJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: index_publication.OwnerRequest) ![]u8 {
        try request.validate();
        // Snapshot installation retains logical reports. Use the shared
        // derived-index barrier before inspecting paged current-root reports.
        var txn = try self.beginIndexedReportRead(group_id);
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_head_version);
        // Do not let physical execution consume an unmirrored metadata phase.
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        var buf: [192]u8 = undefined;
        const head = index_progress.Head.decode(txn.get(try index_publication.headKey(&buf, group_id, request.table_id)) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationNotFound,
            else => return err,
        }) catch return error.InvalidCatalogRecord;
        if (!std.mem.eql(u8, &head.plan_id, &request.id) or head.table_id != request.table_id) return error.GenerationPublicationChanged;
        const ordinal = index_publication.ownerOrdinal(&txn, group_id, request.table_id, request.group_id) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationChanged,
            else => return err,
        };
        const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, request.table_id, ordinal)));
        if (owner.owner.group_id != request.group_id or owner.owner.ordinal != ordinal) return error.InvalidCatalogRecord;
        if (request.raft_reporter != null and owner.owner.authority != .raft) return error.InvalidGenerationPublication;
        const permission = try index_publication.ownerPermission(head, owner, request.operation);
        try index_publication.requireActivePointer(&txn, group_id, head);
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        var decision: index_publication.OwnerDecision = .{ .metadata_group_id = group_id, .metadata_incarnation = incarnation, .head = head, .owner = owner, .disposition = permission };
        var attest = false;
        var raft_recovery_proof: ?index_publication.StoredProof.Decoded = null;
        // Cleanup has its own immutable admission and current-root inspection.
        // It cannot reopen ordinary work, and must not wait for a build audit
        // of the candidate it is retiring. Its ACK explicitly rejoins the
        // retained predecessor commitment in the accepting transaction.
        if (owner.owner.authority == .raft and head.phase != .published and head.phase != .canceled and !(request.operation == .cancel and permission == .execute)) {
            if (try owner.latestReceiptAction()) |latest| if (latest == .fenced or latest == .reserved or latest == .validated or latest == .installed or latest == .released or latest == .cancel_released or latest == .canceled) {
                const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, latest)), head, owner, latest);
                const control_cleanup = (head.phase == .canceling and (latest == .fenced or latest == .reserved)) or latest == .canceled or latest == .cancel_released;
                self.requireIndexOwnerRootProofTxn(&txn, group_id, accepted.signed.receipt.owner, accepted.signed.receipt.position, accepted.signed.proof, head.reader_requirements, control_cleanup) catch |err| switch (err) {
                    error.IndexOwnerReceiptChanged => raft_recovery_proof = accepted,
                    else => return err,
                };
            };
        }
        if (permission == .acknowledged and raft_recovery_proof == null) {
            const action: ?index_progress.Action = switch (request.operation) {
                .fence => .fenced,
                .reserve => .reserved,
                .validate => .validated,
                .install => .installed,
                .release => .released,
                .cancel => .canceled,
                .cancel_release => .cancel_released,
                .build => null,
            };
            if (head.phase != .published and head.phase != .canceled and action != null and (try owner.latestReceiptAction()) == action) {
                const retained = try stagingGet(&txn, try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, action.?)) orelse return error.InvalidCatalogRecord;
                const accepted = try index_publication.storedReceipt(self.alloc, retained, head, owner, action.?);
                self.requireIndexOwnerRootReceiptTxn(&txn, group_id, accepted, head.reader_requirements) catch |err| switch (err) {
                    error.IndexOwnerReceiptChanged => attest = true,
                    else => return err,
                };
            }
            if (!attest) return std.json.Stringify.valueAlloc(alloc, decision, .{});
            // Later native phases need their own durable receipt recovery;
            // never report an old root's proof as a fresh acknowledgment.
            if (owner.owner.authority != .native or (request.operation != .fence and request.operation != .reserve)) return error.IndexOwnerReceiptChanged;
        }
        const lock = (try @import("../table_lifecycle_lock.zig").read(&txn, group_id, request.table_id)) orelse return error.GenerationPublicationChanged;
        if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &head.plan_id)) return error.GenerationPublicationChanged;
        var dispatch = try index_publication.readDispatch(self.alloc, &txn, group_id, owner.owner);
        defer dispatch.deinit();
        const d = dispatch.value;
        const range = try decodeRangeRecord(self.alloc, try txn.get(try rangeKeyForGroup(&buf, group_id, request.group_id)));
        defer metadata_table_manager.freeRange(self.alloc, range);
        if (!metadata_table_manager.rangeRecordsEqual(range, d.owner.range)) return error.GenerationPublicationChanged;
        try IndexPublicationVerification.verifyAuthority(self.alloc, &txn, group_id, d, .{ .table_id = request.table_id, .name = d.table_name });
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        const claim = (try live.getClaim(.{ .namespace_id = d.namespace_id, .name = d.table_guard.logical_table })) orelse return error.GenerationPublicationChanged;
        const after = head.phase == .installing or head.phase == .releasing;
        const schema_version = if (after) d.successor_schema_version else d.table_guard.owner.schema_version;
        const schema_digest = if (after) d.successor_schema_digest else d.table_guard.owner.schema_digest;
        if (claim.kind != .table or claim.phase != .active or claim.table_id != request.table_id or
            claim.schema_version != schema_version or !std.mem.eql(u8, &claim.schema_digest, &schema_digest)) return error.GenerationPublicationChanged;
        if (raft_recovery_proof) |accepted| {
            if (request.claim_groups != null) return error.IndexOwnerReceiptChanged;
            const reporter = request.raft_reporter orelse return error.IndexOwnerReceiptChanged;
            const action = accepted.signed.receipt.action;
            const control = action == .fenced or action == .reserved;
            const cancellation_terminal = head.phase == .cancel_releasing and (action == .canceled or action == .cancel_released);
            const terminal = cancellation_terminal or (head.phase == .releasing and (action == .installed or action == .released));
            const signing = (try self.raftIndexSigningViewModeTxn(&txn, group_id, incarnation, owner.owner, reporter, head.reader_requirements, (head.phase == .canceling and control) or action == .canceled or cancellation_terminal)) orelse return error.IndexOwnerReceiptChanged;
            if (terminal) {
                const predecessor = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, if (cancellation_terminal) .canceled else .installed)), head, owner, if (cancellation_terminal) .canceled else .installed);
                const metadata_decision = if (cancellation_terminal) try index_publication.cancellationReleaseDecisionDigest(group_id, incarnation, head) else try index_publication.ReleaseGrant.decisionDigest(group_id, incarnation, head);
                decision.raft_recovery = try index_publication.RaftRecoveryGrant.initTerminal(group_id, incarnation, head, owner, d, accepted.signed, predecessor, metadata_decision, signing);
            } else if (action == .canceled) {
                decision.raft_recovery = try index_publication.RaftRecoveryGrant.initRetained(incarnation, head, owner, d, accepted, signing);
            } else if (!control) {
                const frozen = try index_delivery.frozenTargetForRecovery(alloc, &txn, group_id, head, owner, incarnation);
                const expected = if (accepted.validation) |w| w.outcome.expected else (accepted.installation orelse return error.InvalidCatalogRecord).outcome.expected;
                if (!std.meta.eql(frozen.expected, expected)) return error.InvalidCatalogRecord;
                decision.raft_recovery = try index_publication.RaftRecoveryGrant.initRetained(incarnation, head, owner, d, accepted, signing);
            } else {
                decision.raft_recovery = try index_publication.RaftRecoveryGrant.init(incarnation, head, owner, d, accepted.signed, signing);
            }
            try decision.requireRequest(request);
            return std.json.Stringify.valueAlloc(alloc, decision, .{});
        }
        if (attest) {
            const signing = (try self.nativeIndexSigningViewTxn(&txn, group_id, incarnation)) orelse return error.IndexOwnerReceiptChanged;
            const current = (try self.loadStoreHeaderTxn(&txn, group_id, signing.identity.store_id)) orelse return error.IndexOwnerReceiptChanged;
            defer metadata_table_manager.freeStore(self.alloc, current);
            if (!metadata_table_manager.storeServesTableData(current.role)) return error.IndexOwnerReceiptChanged;
            if (head.reader_requirements) |requirements| if (!current.schema_reader.supports(requirements)) return error.IndexOwnerReceiptChanged;
            decision.attestation = .{ .table_name = d.table_name, .identity = try d.nativeIdentity(owner.owner), .signing = signing };
            try decision.requireRequest(request);
            return std.json.Stringify.valueAlloc(alloc, decision, .{});
        }
        decision.dispatch = d;
        if (owner.owner.authority == .native) decision.native_signing = try self.nativeIndexSigningViewTxn(&txn, group_id, incarnation);
        if (request.raft_reporter) |reporter| decision.raft_signing = try self.raftIndexSigningViewModeTxn(&txn, group_id, incarnation, owner.owner, reporter, head.reader_requirements, request.operation == .cancel or request.operation == .cancel_release);
        if (request.operation == .validate)
            decision.target_expectation = try index_delivery.targetExpectation(alloc, &txn, group_id, head, owner, incarnation);
        if (request.operation == .install) {
            _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_decision_version);
            const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, .validated)), head, owner, .validated);
            const witness = accepted.validation orelse return error.InvalidCatalogRecord;
            const frozen = try index_delivery.frozenTargetForRecovery(alloc, &txn, group_id, head, owner, incarnation);
            if (!std.meta.eql(frozen.expected, witness.outcome.expected)) return error.InvalidCatalogRecord;
            decision.installation = .{
                .validation = .{ .command = try witness.outcome.logicalCommand(), .position = accepted.signed.receipt.position },
                .decision_digest = try index_publication.InstallGrant.decisionDigest(group_id, incarnation, head),
            };
        }
        if (request.operation == .release) {
            _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_release_version);
            const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, .installed)), head, owner, .installed);
            const witness = accepted.installation orelse return error.InvalidCatalogRecord;
            try self.requireIndexOwnerRootReceiptTxn(&txn, group_id, accepted.signed, head.reader_requirements);
            decision.release = .{
                .installed = .{ .command = witness.command, .position = accepted.signed.receipt.position },
                .decision_digest = try index_publication.ReleaseGrant.decisionDigest(group_id, incarnation, head),
                .installation_proof = accepted.signed.proof,
            };
        }
        if (request.operation == .cancel_release) {
            const accepted = try index_publication.storedProof(self.alloc, try txn.get(try index_publication.proofKey(&buf, group_id, request.table_id, ordinal, .canceled)), head, owner, .canceled);
            const witness = accepted.cancellation orelse return error.InvalidCatalogRecord;
            // A replacement root/report is not permission to lift a fence on
            // behalf of the root that actually acknowledged cohort cleanup.
            try self.requireIndexOwnerRootReceiptTxn(&txn, group_id, accepted.signed, head.reader_requirements);
            decision.cancellation_release = .{ .canceled = witness.record, .decision_digest = try index_publication.cancellationReleaseDecisionDigest(group_id, incarnation, head), .cleanup_proof = accepted.signed.proof };
        }
        var route_arena = std.heap.ArenaAllocator.init(self.alloc);
        defer route_arena.deinit();
        if (request.claim_groups) |groups| {
            decision.claim_routes = try self.readIndexClaimRoutesTxn(route_arena.allocator(), &txn, group_id, head, groups);
        }
        var inputs: ?std.json.Parsed(index_publication.Inputs) = null;
        defer if (inputs) |*value| value.deinit();
        if (request.projection == .admission) {
            inputs = try index_publication.readInputs(self.alloc, &txn, group_id, head);
            decision.inputs = inputs.?.value;
        }
        try decision.requireRequest(request);
        return std.json.Stringify.valueAlloc(alloc, decision, .{});
    }

    /// Accepted validation ACKs are durable logical prepare facts. This
    /// decision does not grant physical-root adoption or lift an owner fence.
    /// Cohort/schema/topology changes remain excluded by the exact lifecycle
    /// lock; install receivers must independently attest their current roots.
    pub fn validateRelationalIndexPublicationDecision(self: *RaftApplyStore, group_id: u64, decision: index_publication.DecidePublish) !void {
        var txn = try self.beginIndexedReportRead(group_id);
        defer txn.abort();
        var prepared = try self.prepareRelationalIndexPublicationDecisionTxn(&txn, group_id, decision);
        defer if (prepared) |*value| value.deinit(self.alloc);
    }

    fn relationalIndexAdmissionStatusTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, request: index_publication.AdmissionRequest) !index_publication.AdmissionStatus {
        try request.validate();
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_head_version);
        var buf: [192]u8 = undefined;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        const raw = try stagingGet(txn, try index_publication.headKey(&buf, group_id, request.table_id));
        const head: ?index_progress.Head = if (raw) |bytes| index_progress.Head.decode(bytes) catch return error.InvalidCatalogRecord else null;
        if (head) |value| {
            try index_publication.requireActivePointer(txn, group_id, value);
        } else {
            // A partially retained job is corruption, not evidence of absence.
            if (try stagingGet(txn, try index_publication.activeKey(&buf, group_id, request.table_id)) != null or
                try stagingGet(txn, try index_publication.planKey(&buf, group_id, request.table_id)) != null) return error.InvalidCatalogRecord;
        }
        const status: index_publication.AdmissionStatus = .{ .metadata_incarnation = incarnation, .head = head, .replication_pending = try stagingGet(txn, metadata_hot_standby.outbox_key) != null };
        _ = try status.isAdmitted(request);
        return status;
    }

    pub fn relationalIndexAdmissionStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: index_publication.AdmissionRequest) ![]u8 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const status = try self.relationalIndexAdmissionStatusTxn(&txn, group_id, request);
        return std.json.Stringify.valueAlloc(alloc, status, .{});
    }

    pub fn relationalIndexStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: index_publication.StatusRequest) ![]u8 {
        try request.validate();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_head_version);
        if (!try relationWriterEnabledTxn(&txn, group_id)) return error.CatalogOccupancyNotReady;
        var buf: [192]u8 = undefined;
        // Authorization follows the current logical table, not a retained
        // token. Keep ownership validation and job observation in one snapshot.
        var scope = try self.guardedRelationOwnerTxn(&txn, group_id, request.guard);
        defer scope.deinit();
        const status = try self.relationalIndexAdmissionStatusTxn(&txn, group_id, request.admission);
        if (status.head) |head| {
            const owner = try index_progress.OwnerState.decode(try txn.get(try index_publication.ownerKey(&buf, group_id, head.table_id, 0)));
            if (owner.owner.ordinal != 0 or owner.owner.namespace.table_id != head.table_id or
                !std.mem.eql(u8, &owner.owner.plan_id, &head.plan_id) or !std.mem.eql(u8, &owner.owner.plan_digest, &head.plan_digest)) return error.InvalidCatalogRecord;
            var dispatch = try index_publication.readDispatch(self.alloc, &txn, group_id, owner.owner);
            defer dispatch.deinit();
            var name_digest: index_publication.Digest = undefined;
            std.crypto.hash.Blake3.hash(request.index_name, &name_digest, .{});
            if (!std.mem.eql(u8, &name_digest, &dispatch.value.index_name_digest) or
                !std.mem.eql(u8, scope.physicalName(request.guard), dispatch.value.table_name)) return error.GenerationPublicationChanged;
        }
        return std.json.Stringify.valueAlloc(alloc, status, .{});
    }

    pub fn relationalIndexPublicationDecisionStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: index_publication.DecidePublish) ![]u8 {
        try request.validate();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_decision_version);
        var buf: [192]u8 = undefined;
        const head = index_progress.Head.decode(txn.get(try index_publication.headKey(&buf, group_id, request.table_id)) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationNotFound,
            else => return err,
        }) catch return error.InvalidCatalogRecord;
        try index_publication.requireActivePointer(&txn, group_id, head);
        const status: index_publication.DecisionStatus = .{ .head = head, .replication_pending = try stagingGet(&txn, metadata_hot_standby.outbox_key) != null };
        _ = try status.isDecided(request);
        return std.json.Stringify.valueAlloc(alloc, status, .{});
    }

    const IndexPublicationCancellation = struct {
        table_id: u64,
        expected: [index_progress.Head.encoded_len]u8,
        next: [index_progress.Head.encoded_len]u8,
        id: index_publication.Id,

        fn stage(self: *const @This(), txn: anytype, group: u64) !void {
            var buf: [192]u8 = undefined;
            const head_key = try index_publication.headKey(&buf, group, self.table_id);
            if (!std.mem.eql(u8, try txn.get(head_key), &self.expected)) return error.GenerationPublicationChanged;
            const previous = try index_progress.Head.decode(&self.expected);
            try index_publication.requireActivePointer(txn, group, previous);
            const lock = (try @import("../table_lifecycle_lock.zig").read(txn, group, self.table_id)) orelse return error.GenerationPublicationChanged;
            if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &self.id)) return error.GenerationPublicationChanged;
            try txn.put(try index_publication.headKey(&buf, group, self.table_id), &self.next);
        }
    };

    fn requireIndexCancellationIdentityTxn(txn: anytype, group: u64, request: index_publication.CancelDecision, head: index_progress.Head) !void {
        if (request.expected) |identity| {
            var buf: [192]u8 = undefined;
            const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group)))).incarnation;
            if (!std.mem.eql(u8, &identity.metadata_incarnation, &incarnation) or !std.mem.eql(u8, &identity.plan_digest, &head.plan_digest)) return error.GenerationPublicationChanged;
        }
    }

    fn prepareRelationalIndexCancellationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, request: index_publication.CancelDecision) !?IndexPublicationCancellation {
        try request.validate();
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.index_publication_head_version);
        if (!try relationWriterEnabledTxn(txn, group)) return error.CatalogOccupancyNotReady;
        if (try stagingGet(txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        var buf: [192]u8 = undefined;
        const head = try index_progress.Head.decode(txn.get(try index_publication.headKey(&buf, group, request.table_id)) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationNotFound,
            else => return err,
        });
        if (head.table_id != request.table_id or !std.mem.eql(u8, &head.plan_id, &request.id)) return error.GenerationPublicationChanged;
        try requireIndexCancellationIdentityTxn(txn, group, request, head);
        try index_publication.requireActivePointer(txn, group, head);
        if (head.phase == .canceling or head.phase == .cancel_releasing or head.phase == .canceled) {
            if (head.failure != request.failure or request.expected_revision >= head.revision) return error.GenerationPublicationChanged;
            return null;
        }
        const next = try head.cancel(request.expected_revision, request.failure);
        const lock = (try @import("../table_lifecycle_lock.zig").read(txn, group, request.table_id)) orelse return error.GenerationPublicationChanged;
        if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &request.id)) return error.GenerationPublicationChanged;
        return .{ .table_id = request.table_id, .expected = try head.encode(), .next = try next.encode(), .id = request.id };
    }

    pub fn validateRelationalIndexCancellation(self: *RaftApplyStore, group: u64, request: index_publication.CancelDecision) !void {
        var txn = try self.beginIndexedReportRead(group);
        defer txn.abort();
        _ = try self.prepareRelationalIndexCancellationTxn(&txn, group, request);
    }

    pub fn relationalIndexCancellationStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: index_publication.CancelDecision) ![]u8 {
        try request.validate();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.index_publication_head_version);
        var buf: [192]u8 = undefined;
        const head = try index_progress.Head.decode(txn.get(try index_publication.headKey(&buf, group, request.table_id)) catch |err| switch (err) {
            error.NotFound => return error.GenerationPublicationNotFound,
            else => return err,
        });
        try index_publication.requireActivePointer(&txn, group, head);
        const status: index_publication.CancellationStatus = .{ .head = head, .replication_pending = try stagingGet(&txn, metadata_hot_standby.outbox_key) != null };
        try requireIndexCancellationIdentityTxn(&txn, group, request, head);
        _ = try status.isCanceled(request);
        return std.json.Stringify.valueAlloc(alloc, status, .{});
    }

    fn cancelRelationalIndexPublicationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, request: index_publication.CancelDecision) !void {
        const prepared = self.prepareRelationalIndexCancellationTxn(txn, group, request) catch |err| switch (err) {
            error.GenerationPublicationChanged => return,
            else => return err,
        };
        if (prepared) |value| try value.stage(txn, group);
    }

    const IndexPublicationDecision = struct {
        inputs: std.json.Parsed(index_publication.DecisionInputs),
        table: PreparedTableRecordWrite,
        head: index_progress.Head,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            self.table.deinit(alloc);
            self.inputs.deinit();
        }
    };

    fn prepareRelationalIndexPublicationDecisionTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, decision: index_publication.DecidePublish) !?IndexPublicationDecision {
        try decision.validate();
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_decision_version);
        if (!try relationWriterEnabledTxn(txn, group_id)) return error.CatalogOccupancyNotReady;
        if (try stagingGet(txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        var buf: [192]u8 = undefined;
        const head = try index_progress.Head.decode(try txn.get(try index_publication.headKey(&buf, group_id, decision.table_id)));
        if (head.table_id != decision.table_id or !std.mem.eql(u8, &head.plan_id, &decision.id)) return error.GenerationPublicationChanged;
        try index_publication.requireActivePointer(txn, group_id, head);
        if (head.phase == .installing or head.phase == .releasing or head.phase == .published) {
            if (decision.expected_revision >= head.revision) return error.GenerationPublicationChanged;
            return null; // Recover an already committed decision, never replay DDL.
        }
        const next = try head.decidePublish(decision.expected_revision);
        const lifecycle = @import("../table_lifecycle_lock.zig");
        const lock = (try lifecycle.read(txn, group_id, decision.table_id)) orelse return error.GenerationPublicationChanged;
        if (lock.kind != .index_build or !std.mem.eql(u8, &lock.id, &decision.id)) return error.GenerationPublicationChanged;
        var inputs = try index_publication.readDecisionInputs(self.alloc, txn, group_id, head);
        errdefer inputs.deinit();
        const plan = inputs.value;
        const current = try decodeTableRecord(self.alloc, try txn.get(try tableKeyForGroup(&buf, group_id, decision.table_id)));
        defer metadata_table_manager.freeTable(self.alloc, current);
        if (!metadata_table_manager.tableDefinitionsEqual(current, plan.before)) return error.GenerationPublicationChanged;
        try IndexPublicationVerification.verifyAuthority(self.alloc, txn, group_id, plan, current);
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        const claim = (try live.getClaim(.{ .namespace_id = plan.namespace_id, .name = plan.table_guard.logical_table })) orelse return error.GenerationPublicationChanged;
        if (!std.meta.eql(claim, plan.table_guard.owner)) return error.GenerationPublicationChanged;
        const reserved = (try live.getEntry(.{ .namespace_id = plan.namespace_id, .name = plan.index_name })) orelse return error.GenerationPublicationChanged;
        if (reserved.active != null) return error.GenerationPublicationChanged;
        const pending = reserved.pending orelse return error.GenerationPublicationChanged;
        if (pending.kind != .index or pending.phase != .reserved or pending.table_id != decision.table_id or
            !std.mem.eql(u8, &pending.publication_id, &decision.id) or
            pending.schema_version != (try @import("../../api/tables.zig").schemaVersion(plan.after.schema_json)) or
            !std.mem.eql(u8, &pending.schema_digest, &@import("antfly_local_sources").storage_db_relational_integrity_contract.hash(plan.after.schema_json))) return error.GenerationPublicationChanged;
        const table = (try self.prepareTableRecordTxnMode(txn, group_id, try tableKeyForGroup(&buf, group_id, decision.table_id), plan.after, true)) orelse return error.GenerationPublicationChanged;
        return .{ .inputs = inputs, .table = table, .head = next };
    }

    fn decideRelationalIndexPublicationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, decision: index_publication.DecidePublish) !void {
        var prepared = self.prepareRelationalIndexPublicationDecisionTxn(txn, group_id, decision) catch |err| switch (err) {
            error.GenerationPublicationChanged => return, // Losing CAS, before any writes.
            else => return err,
        };
        defer if (prepared) |*value| value.deinit(self.alloc);
        const value = if (prepared) |*record| record else return;
        var buf: [192]u8 = undefined;
        // Namespace admission consumes the pending source and publishes the
        // successor names from these exact table bytes in this same transaction.
        try self.writePreparedTableRecordTxn(txn, group_id, try tableKeyForGroup(&buf, group_id, decision.table_id), value.table);
        try txn.put(try index_publication.headKey(&buf, group_id, decision.table_id), &try value.head.encode());
        try txn.delete(try index_publication.activeKey(&buf, group_id, decision.table_id));
    }

    pub fn relationalIndexPrepareCutJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: index_publication.PrepareRequest) ![]u8 {
        try request.validate();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var txn = try self.beginIndexedReportRead(group_id);
        defer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group_id, topology_protocol.index_publication_head_version);
        if (!try relationWriterEnabledTxn(&txn, group_id)) return error.CatalogOccupancyNotReady;
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        var buf: [192]u8 = undefined;
        const before = try decodeTableRecord(a, txn.get(try tableKeyForGroup(&buf, group_id, request.guard.owner.table_id)) catch |err| switch (err) {
            error.NotFound => return error.CatalogGenerationChanged,
            else => return err,
        });
        try self.validateRelationMutationTxn(&txn, group_id, request.guard, before, before);
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        const namespace_id = (try resolveSystemCatalogNamespaceTxn(a, &txn, group_id, request.guard.target.database, request.guard.target.namespace)) orelse return error.CatalogGenerationChanged;
        if (try live.nameOccupied(namespace_id, request.index_name, true)) return error.CatalogAlreadyExists;
        if (try @import("../table_lifecycle_lock.zig").read(&txn, group_id, before.table_id) != null) return error.GenerationPublicationChanged;
        if (!try self.policyTopologyMutationAllowedTxn(&txn, group_id, before.table_id)) return error.RowPolicyUnsupported;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        // Authority is selected by the metadata owner, never by a public index
        // option or a caller-supplied placement/report description.
        const authority: index_progress.Authority = if (try stagingGet(&txn, standalone_catalog_key) != null) blk: {
            // A missing standalone binding is not evidence of Raft ownership.
            if (try stagingGet(&txn, try standalone_native_owner.key(&buf, group_id)) == null) return error.UnsupportedNativeIndexOwner;
            _ = (try self.nativeIndexSigningViewTxn(&txn, group_id, incarnation)) orelse return error.CatalogPublicationProofPending;
            break :blk .native;
        } else .raft;
        const ids = try self.indexedTableRangeIdsBoundedTxn(a, &txn, group_id, before.table_id, index_progress.max_owners);
        if (ids.len == 0) return error.GenerationPublicationChanged;
        const ranges = try a.alloc(metadata.RangeRecord, ids.len);
        for (ids, ranges) |id, *range| range.* = try decodeRangeRecord(a, try txn.get(try rangeKeyForGroup(&buf, group_id, id)));
        metadata_table_manager.sortKeyspaceRanges(metadata.RangeRecord, ranges);
        try self.validateFkGenerationTableTxn(&txn, group_id, before, ranges);
        var expected_head: ?[index_progress.Head.encoded_len]u8 = null;
        if (try stagingGet(&txn, try index_publication.headKey(&buf, group_id, before.table_id))) |bytes| {
            const head = try index_progress.Head.decode(bytes);
            if (head.phase != .published and head.phase != .canceled) return error.GenerationPublicationChanged;
            try index_publication.requireActivePointer(&txn, group_id, head);
            _ = try index_publication.verifyJob(self.alloc, &txn, group_id, before.table_id);
            expected_head = try head.encode();
        }
        const cut: index_publication.PrepareCut = .{ .metadata_incarnation = incarnation, .namespace_id = namespace_id, .table_guard = request.guard, .before = before, .ranges = ranges, .authority = authority, .expected_head = expected_head };
        try cut.requireRequest(a, request);
        return cut.encode(alloc);
    }

    /// Uses a pinned indexed read; neither stages job rows nor installs a
    /// command journal/outcome. Preparation belongs outside the catalog gate.
    pub fn validateRelationalIndexBegin(self: *RaftApplyStore, group_id: u64, request: index_publication.BeginRequest, prepared: *const index_publication.Prepared) !void {
        const observation = try request.observation(prepared);
        var txn = try self.beginIndexedReportRead(group_id);
        defer txn.abort();
        var buf: [192]u8 = undefined;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
        if (!std.mem.eql(u8, &incarnation, &observation.metadata_incarnation)) return error.MetadataIncarnationMismatch;
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        try self.validateRelationalIndexBeginTxn(&txn, group_id, request.begin);
        _ = try prepared.requireBegin(&txn, group_id, request.begin.expected_head);
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (try live.nameOccupied(request.begin.plan.namespace_id, request.begin.plan.index_name, true)) return error.CatalogAlreadyExists;
    }

    fn validateRelationalIndexBeginTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, request: index_publication.Begin) !void {
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_head_version);
        if (!try relationWriterEnabledTxn(txn, group_id)) return error.CatalogOccupancyNotReady;
        const plan = request.plan;
        // Readiness at proposal time is not durable decoder activation. Once
        // a marked plan is retained, ordinary later commands must keep every
        // metadata member capable of decoding it, even before native install.
        if (plan.before.schema_reader_requirements != null or plan.after.schema_reader_requirements != null)
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_reader_publication_version);
        try self.validateRelationMutationTxn(txn, group_id, plan.table_guard, plan.before, plan.after);
        const live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        const namespace_id = (try resolveSystemCatalogNamespaceTxn(self.alloc, txn, group_id, plan.table_guard.target.database, plan.table_guard.target.namespace)) orelse return error.CatalogGenerationChanged;
        if (namespace_id != plan.namespace_id) return error.CatalogGenerationChanged;
        if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, plan.before.table_id)) return error.RowPolicyUnsupported;
        const ranges = try self.alloc.alloc(metadata.RangeRecord, plan.owners.len);
        defer self.alloc.free(ranges);
        for (plan.owners, ranges) |owner, *range| range.* = owner.range;
        try self.validateFkGenerationTableTxn(txn, group_id, plan.before, ranges);
        if (request.expected_head != null) _ = try index_publication.verifyJob(self.alloc, txn, group_id, plan.before.table_id);
    }

    const SchemaValidationOwnerReadContext = struct {
        store: *RaftApplyStore,
        group: u64,
        witness: ?@import("../schema_validation_read.zig").OwnerWitness = null,

        pub fn authorize(self: @This(), txn: *docstore.DocStore.Txn, head: @import("../schema_validation_publication.zig").Head, owner: @import("../schema_validation_publication.zig").Owner, action: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Action) !void {
            const contract = @import("antfly_local_sources").storage_db_relational_schema_owner_contract;
            if (head.metadata_group_id != self.group) return error.InvalidGenerationPublication;
            var buf: [192]u8 = undefined;
            const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, self.group)))).incarnation;
            if (!std.mem.eql(u8, &incarnation, &head.metadata_incarnation)) return error.MetadataIncarnationMismatch;
            const table = try decodeTableRecord(self.store.alloc, try txn.get(try tableKeyForGroup(&buf, self.group, head.table_id)));
            defer metadata_table_manager.freeTable(self.store.alloc, table);
            const published = head.phase == .releasing or head.phase == .succeeded;
            const expected = if (published) owner.binding.after_public else owner.binding.before_public;
            if (table.table_id != head.table_id or table.storage_migration != null or table.read_schema_json.len != 0 or
                !std.mem.eql(u8, &contract.hash(table.schema_json), &expected)) return error.GenerationPublicationChanged;
            const key: schema_validation.Key = .{ .group = self.group, .table = head.table_id, .id = head.id, .kind = .preparation, .ordinal = owner.ordinal };
            const preparation = try schema_validation.PreparationRecord.decode(try txn.get(try key.encode(&buf)));
            try preparation.verifyFor(owner.binding, owner.initialRoot());
            if (!std.mem.eql(u8, &preparation.proof.identity.metadata_incarnation, &head.metadata_incarnation)) return error.MetadataIncarnationMismatch;
            if (self.witness) |witness| {
                if (owner.root_epoch != 0) _ = try schema_validation.readRootEpoch(txn, head, owner, owner.root_epoch);
                // Fresh facts must name the ALREADY accepted physical root.
                // They cannot substitute for audited replacement-root adoption.
                switch (witness) {
                    .preparation => |fresh| {
                        try fresh.verifyFor(owner.binding, owner.physical_root_incarnation);
                        try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                            .group_id = owner.binding.fence.owner_group_id,
                            .namespace = owner.binding.fence.namespace,
                            .authority = owner.binding.authority,
                        }, fresh.value.position, fresh.proof, head.reader_requirements, .{ .cleanup = action == .cancel, .require_source_authority = true, .allow_empty_preparation = true });
                    },
                    .observation => |fresh| {
                        _ = try schema_validation.verified(fresh, owner);
                        switch (fresh) {
                            inline else => |signed| {
                                const observed = signed.rooted.observation;
                                const cut: @import("antfly_local_sources").storage_db_receipt_position.Position = if (comptime @hasField(@TypeOf(observed), "sequence"))
                                    .{ .native = .{ .namespace = owner.binding.fence.namespace, .sequence = observed.sequence } }
                                else
                                    .{ .raft = observed.applied orelse return error.InvalidControlReceiptPosition };
                                try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                                    .group_id = owner.binding.fence.owner_group_id,
                                    .namespace = owner.binding.fence.namespace,
                                    .authority = owner.binding.authority,
                                }, cut, signed.proof, head.reader_requirements, .{
                                    .cleanup = action == .cancel,
                                    .require_source_authority = true,
                                    .completed = if (comptime @hasField(@TypeOf(signed.rooted), "completed")) signed.rooted.completed else null,
                                });
                            },
                        }
                    },
                }
                return;
            }
            if (owner.root_epoch != 0) {
                const epoch = try schema_validation.readRootEpoch(txn, head, owner, owner.root_epoch);
                if (epoch.request.proposal == .native_bootstrap) {
                    const signed = epoch.request.proposal.native_bootstrap;
                    try signed.verifyFor(owner.binding, owner.physical_root_incarnation);
                    try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                        .group_id = owner.binding.fence.owner_group_id,
                        .namespace = owner.binding.fence.namespace,
                        .authority = owner.binding.authority,
                    }, signed.value.position, signed.proof, head.reader_requirements, .{
                        .cleanup = action == .cancel,
                        .require_source_authority = true,
                        .allow_empty_preparation = true,
                    });
                    return;
                }
                if (epoch.request.proposal == .audited_native) {
                    const signed = epoch.request.proposal.audited_native.observation;
                    _ = try schema_validation.verified(.{ .native = signed }, owner);
                    try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                        .group_id = owner.binding.fence.owner_group_id,
                        .namespace = owner.binding.fence.namespace,
                        .authority = owner.binding.authority,
                    }, .{ .native = .{ .namespace = owner.binding.fence.namespace, .sequence = signed.rooted.observation.sequence } }, signed.proof, head.reader_requirements, .{ .cleanup = action == .cancel, .require_source_authority = true });
                    return;
                }
                if (epoch.request.proposal == .bootstrap) {
                    const signed = epoch.request.proposal.bootstrap;
                    _ = try signed.attestedScope(owner.binding, head.metadata_incarnation);
                    if (signed.preparation.value.physical_root_incarnation != owner.physical_root_incarnation) return error.SchemaValidationJobChanged;
                    try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                        .group_id = owner.binding.fence.owner_group_id,
                        .namespace = owner.binding.fence.namespace,
                        .authority = owner.binding.authority,
                    }, signed.preparation.value.position, signed.proof, head.reader_requirements, .{
                        .cleanup = action == .cancel,
                        .require_source_authority = true,
                        .allow_empty_preparation = true,
                        .allow_empty_snapshot_cut = signed.preparation.value.position == null,
                        .completed = signed.completed,
                    });
                    return;
                }
                const signed = epoch.request.proposal.audited.observation;
                _ = try schema_validation.verified(.{ .raft = signed }, owner);
                const observed = signed.rooted.observation;
                const cut: ?@import("antfly_local_sources").storage_db_receipt_position.Position = if (observed.applied) |value| .{ .raft = value } else null;
                try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                    .group_id = owner.binding.fence.owner_group_id,
                    .namespace = owner.binding.fence.namespace,
                    .authority = owner.binding.authority,
                }, cut, signed.proof, head.reader_requirements, .{ .cleanup = action == .cancel, .require_source_authority = true, .completed = signed.rooted.completed });
                return;
            }
            // Neither a signed historical receipt nor this body's requested
            // action may adopt a replacement root. Rejoin the original proof
            // with current enrollment, serving placement and source report.
            try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                .group_id = owner.binding.fence.owner_group_id,
                .namespace = owner.binding.fence.namespace,
                .authority = owner.binding.authority,
            }, preparation.value.position, preparation.proof, head.reader_requirements, .{ .cleanup = action == .cancel, .require_source_authority = true, .allow_empty_preparation = true });
        }
    };

    fn beginSchemaValidationOwnerRead(self: *RaftApplyStore, group: u64) !docstore.DocStore.Txn {
        var txn = try self.beginIndexedReportRead(group);
        errdefer txn.abort();
        _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.schema_validation_publication_version);
        if (!try relationWriterEnabledTxn(&txn, group)) return error.CatalogOccupancyNotReady;
        if (try stagingGet(&txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        return txn;
    }

    /// Private owner-dispatch read. The service ingress must independently
    /// authenticate the caller and establish a linearizable metadata read.
    /// This does not enable a public producer or advertise the reserved floor.
    pub fn schemaValidationOwnerControlJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, lookup: schema_validation.Lookup, ordinal: u16, action: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Action) ![]u8 {
        return self.schemaValidationOwnerRead(alloc, group, .{ .lookup = lookup, .ordinal = ordinal, .action = action });
    }

    /// Raw immutable ASVI admission inputs, never JSON arrays or base64. Own
    /// the response before closing the same snapshot that authorized access.
    pub fn schemaValidationOwnerInputBytes(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, lookup: schema_validation.Lookup, ordinal: u16) ![]u8 {
        return self.schemaValidationOwnerRead(alloc, group, .{ .lookup = lookup, .ordinal = ordinal, .projection = .inputs });
    }

    pub fn schemaValidationOwnerRead(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../schema_validation_read.zig").OwnerReadRequest) ![]u8 {
        try request.validate();
        if (request.lookup.group != group) return error.InvalidGenerationPublication;
        switch (request.projection) {
            .parent => return self.schemaValidationParentJson(alloc, group, request.lookup, request.source_image.?),
            .recovery_inputs => return self.schemaValidationRecoveryInputBytes(alloc, group, request.lookup, request.ordinal, request.source_image.?),
            .replay, .replay_inputs => {
                var txn = try self.beginSchemaValidationHistoryRead(group, request.lookup);
                defer txn.abort();
                if (request.projection == .replay) return std.json.Stringify.valueAlloc(alloc, try schema_validation.readReplayControl(&txn, request.lookup, request.source_owner.?), .{});
                return alloc.dupe(u8, try schema_validation.readReplayInputs(&txn, request.lookup, request.source_owner.?, request.ordinal));
            },
            .control, .inputs => {},
        }
        var txn = try self.beginSchemaValidationOwnerRead(group);
        defer txn.abort();
        const context: SchemaValidationOwnerReadContext = .{ .store = self, .group = group, .witness = request.witness };
        if (request.projection == .control) {
            const value = try schema_validation.readOwnerControl(&txn, request.lookup, request.ordinal, request.action, context);
            return std.json.Stringify.valueAlloc(alloc, value, .{});
        }
        const input = try schema_validation.readOwnerInputs(&txn, request.lookup, request.ordinal, context);
        return alloc.dupe(u8, input);
    }

    /// Historical acceptance does not depend on a live data owner, current
    /// table definition or report-index reconciliation. It still requires the
    /// current metadata incarnation and a fully mirrored committed snapshot.
    pub fn schemaValidationReceiptJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../schema_validation_receipt.zig").Request) ![]u8 {
        try request.validate();
        if (request.lookup.group != group) return error.InvalidGenerationPublication;
        var txn = try self.beginSchemaValidationHistoryRead(group, request.lookup);
        defer txn.abort();
        const observed = try schema_validation.observeReceipt(&txn, request);
        return std.json.Stringify.valueAlloc(alloc, observed, .{});
    }

    pub fn schemaValidationDiscover(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../schema_validation_read.zig").DiscoveryRequest) ![]u8 {
        try request.validate();
        if (request.group != group) return error.InvalidGenerationPublication;
        var txn = try self.beginSchemaValidationIncarnationRead(group, request.metadata_incarnation);
        defer txn.abort();
        return std.json.Stringify.valueAlloc(alloc, try schema_validation.discoverActive(&txn, request), .{});
    }

    pub fn schemaValidationStatusJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../schema_validation_admission.zig").StatusRequest) ![]u8 {
        try request.validate();
        var txn = try self.beginSchemaValidationHistoryRead(group, request.lookup);
        defer txn.abort();
        var scope = try self.guardedRelationOwnerTxn(&txn, group, request.guard);
        defer scope.deinit();
        const observed = try schema_validation.observeReceipt(&txn, .{ .lookup = request.lookup, .expected = .admission });
        const status: @import("../schema_validation_admission.zig").Status = .{ .lookup = observed.lookup, .head = observed.head, .active_schema_version = request.guard.owner.schema_version };
        try status.requireFor(request);
        return std.json.Stringify.valueAlloc(alloc, status, .{});
    }

    pub fn schemaValidationPrepareCut(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../schema_validation_admission.zig").Request) ![]u8 {
        const admission = @import("../schema_validation_admission.zig");
        try request.validate();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var txn = try self.beginIndexedReportRead(group);
        defer txn.abort();
        const incarnation = std.fmt.bytesToHex(request.guard.incarnation, .lower);
        try self.requireSchemaValidationIncarnationTxn(&txn, group, incarnation);
        var buf: [192]u8 = undefined;
        const before = try decodeTableRecord(a, txn.get(try tableKeyForGroup(&buf, group, request.guard.owner.table_id)) catch |err| switch (err) {
            error.NotFound => return error.CatalogGenerationChanged,
            else => return err,
        });
        const after = try @import("../../api/tables.zig").prepareSchemaValidationPublicationRecord(a, &before, request.selection);
        try self.validateRelationMutationTxn(&txn, group, request.guard, before, after);
        if (try @import("../table_lifecycle_lock.zig").read(&txn, group, before.table_id) != null) return error.GenerationPublicationChanged;
        if (!try self.policyTopologyMutationAllowedTxn(&txn, group, before.table_id)) return error.RowPolicyUnsupported;
        const authority: @import("antfly_local_sources").storage_source_authority.Kind = if (try stagingGet(&txn, standalone_catalog_key) != null) native: {
            if (try stagingGet(&txn, try standalone_native_owner.key(&buf, group)) == null) return error.UnsupportedNativeIndexOwner;
            _ = (try self.nativeIndexSigningViewTxn(&txn, group, incarnation)) orelse return error.CatalogPublicationProofPending;
            break :native .native;
        } else .raft;
        const ids = try self.indexedTableRangeIdsBoundedTxn(a, &txn, group, before.table_id, @import("../schema_validation_publication.zig").max_owners);
        if (ids.len == 0) return error.GenerationPublicationChanged;
        const ranges = try a.alloc(metadata.RangeRecord, ids.len);
        var count = std.Io.Writer.Discarding.init(&.{});
        try std.json.Stringify.value(before, .{}, &count.writer);
        try std.json.Stringify.value(after, .{}, &count.writer);
        for (ids, ranges) |id, *range| {
            range.* = try decodeRangeRecord(a, try txn.get(try rangeKeyForGroup(&buf, group, id)));
            try std.json.Stringify.value(range.*, .{}, &count.writer);
            // Bound accumulation before decoding the rest of a large cohort.
            if (count.fullCount() > admission.max_wire_bytes - 16 * 1024) return error.InvalidGenerationPublication;
        }
        metadata_table_manager.sortKeyspaceRanges(metadata.RangeRecord, ranges);
        try self.validateFkGenerationTableTxn(&txn, group, before, ranges);
        const cut: admission.Cut = .{ .metadata_group_id = group, .metadata_incarnation = incarnation, .table_guard = request.guard, .before = before, .after = after, .ranges = ranges, .authority = authority };
        try cut.requireRequest(a, request);
        return cut.encode(alloc);
    }

    pub fn schemaValidationWork(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../schema_validation_work.zig").Query) ![]u8 {
        try request.validate();
        if (request.group != group) return error.InvalidGenerationPublication;
        var txn = try self.beginSchemaValidationIncarnationRead(group, request.metadata_incarnation);
        defer txn.abort();
        const page = try @import("../schema_validation_work.zig").read(&txn, request);
        try page.validate(request);
        const bytes = try std.json.Stringify.valueAlloc(alloc, page, .{});
        errdefer alloc.free(bytes);
        if (bytes.len > @import("../schema_validation_work.zig").max_wire_bytes) return error.InvalidCatalogRecord;
        return bytes;
    }

    fn beginSchemaValidationHistoryRead(self: *RaftApplyStore, group: u64, lookup: schema_validation.Lookup) !docstore.DocStore.Txn {
        if (lookup.group != group) return error.InvalidGenerationPublication;
        return self.beginSchemaValidationIncarnationRead(group, lookup.metadata_incarnation);
    }

    fn beginSchemaValidationIncarnationRead(self: *RaftApplyStore, group: u64, expected_incarnation: [32]u8) !docstore.DocStore.Txn {
        var txn = try self.store.beginReadTxn();
        errdefer txn.abort();
        try self.requireSchemaValidationIncarnationTxn(&txn, group, expected_incarnation);
        return txn;
    }

    fn requireSchemaValidationIncarnationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, expected_incarnation: [32]u8) !void {
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.schema_validation_publication_version);
        if (!try relationWriterEnabledTxn(txn, group)) return error.CatalogOccupancyNotReady;
        if (try stagingGet(txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        var buf: [192]u8 = undefined;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group)))).incarnation;
        if (!std.mem.eql(u8, &incarnation, &expected_incarnation)) return error.MetadataIncarnationMismatch;
    }

    pub fn schemaValidationParentJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, lookup: schema_validation.Lookup, image: @import("../schema_validation_read.zig").ImageIdentity) ![]u8 {
        try image.validate();
        var txn = try self.beginSchemaValidationHistoryRead(group, lookup);
        defer txn.abort();
        return std.json.Stringify.valueAlloc(alloc, try schema_validation.readRestorationControl(&txn, lookup, image), .{});
    }

    pub fn schemaValidationRecoveryInputBytes(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, lookup: schema_validation.Lookup, ordinal: u16, image: @import("../schema_validation_read.zig").ImageIdentity) ![]u8 {
        try image.validate();
        var txn = try self.beginSchemaValidationHistoryRead(group, lookup);
        defer txn.abort();
        return alloc.dupe(u8, try schema_validation.readRecoveryInputs(&txn, lookup, ordinal, image));
    }

    /// Abort-only, read-only command preflight. Results are acceptance intent,
    /// never permission to skip the SAME checks during replicated application.
    /// The raw command stays binary through the importing facade and ABI.
    pub fn schemaValidationPreflightJson(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, bytes: []const u8) ![]u8 {
        if (bytes.len == 0 or bytes.len > schema_validation.max_command_bytes) return error.InvalidGenerationPublication;
        var txn = try self.beginSchemaValidationOwnerRead(group);
        defer txn.abort();
        var parsed = try schema_validation.parseCommand(alloc, bytes);
        defer parsed.deinit();
        const lookup = try schema_validation.commandLookup(parsed.value);
        if (lookup.group != group) return error.InvalidGenerationPublication;
        var buf: [192]u8 = undefined;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group)))).incarnation;
        if (!std.mem.eql(u8, &lookup.metadata_incarnation, &incarnation)) return error.MetadataIncarnationMismatch;
        const context: SchemaValidationContext = .{ .store = self, .group = group };
        const effect: @import("../schema_validation_receipt.zig").Effect = switch (parsed.value) {
            .begin => |request| blk: {
                var prepared = try @import("../schema_validation_plan.zig").Prepared.init(alloc, request.plan);
                defer prepared.deinit();
                _ = try schema_validation.checkBegin(alloc, &txn, &prepared, request.preparations, request.inputs, context);
                break :blk .admission;
            },
            .ack => |request| blk: {
                _ = try schema_validation.prepareAcknowledgement(&txn, lookup, request.ordinal, request.revision, request.signed, context);
                break :blk (try schema_validation.acknowledgementReceipt(lookup, request.ordinal, request.signed)).expected;
            },
            .authorize_parent => |request| blk: {
                _ = try schema_validation.prepareParentAuthorization(&txn, request, context);
                break :blk .{ .parent_authorization = .{ .ordinal = request.ordinal, .grant = try request.id() } };
            },
            .adopt_root => |request| blk: {
                const prepared = try schema_validation.prepareRootAdoption(&txn, request, context);
                break :blk (try schema_validation.commandReceipt(.{ .adopt_root = request }, prepared.head)).expected;
            },
            .install => |decision| blk: {
                const prepared = try schema_validation.checkInstall(&txn, lookup, decision.revision);
                if (prepared.changed) try context.requireReadyOwners(&txn, lookup);
                break :blk .{ .installation = .{ .revision = decision.revision, .digest = try prepared.head.installDecision() } };
            },
            .publish => |decision| blk: {
                var prepared = try schema_validation.checkPublication(alloc, &txn, lookup, decision.revision, context);
                defer prepared.deinit();
                if (prepared.recovery) |value| try context.requireCut(&txn, value.plan.value, false);
                break :blk .{ .publication = .{ .revision = decision.revision, .digest = try prepared.head.publicationDecision() } };
            },
            .cancel => |request| blk: {
                const prepared = try schema_validation.checkCancellation(&txn, lookup, request.decision.revision, request.failure);
                break :blk .{ .cancellation = .{ .decision = .{ .revision = request.decision.revision, .digest = try prepared.head.cancellationDecision() }, .failure = request.failure } };
            },
        };
        const expected: @import("../schema_validation_receipt.zig").Request = .{ .lookup = lookup, .expected = effect };
        try expected.validate();
        return std.json.Stringify.valueAlloc(alloc, expected, .{});
    }

    const SchemaValidationContext = struct {
        store: *RaftApplyStore,
        group: u64,

        fn requireCut(self: @This(), txn: *docstore.DocStore.Txn, plan: @import("../schema_validation_plan.zig").Plan, published: bool) !void {
            if (plan.metadata_group_id != self.group) return error.InvalidGenerationPublication;
            var buf: [192]u8 = undefined;
            const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, self.group)))).incarnation;
            if (!std.mem.eql(u8, &incarnation, &plan.metadata_incarnation)) return error.MetadataIncarnationMismatch;
            const guard = plan.table_guard orelse return error.InvalidCatalogMutation;
            const expected = if (published) plan.after else plan.before;
            const namespace = (try resolveSystemCatalogNamespaceTxn(self.store.alloc, txn, self.group, guard.target.database, guard.target.namespace)) orelse return error.CatalogGenerationChanged;
            try IndexPublicationVerification.verifyAuthority(self.store.alloc, txn, self.group, .{ .table_guard = guard, .namespace_id = namespace }, expected);
            const ranges = try self.store.alloc.alloc(metadata.RangeRecord, plan.owners.len);
            defer self.store.alloc.free(ranges);
            for (plan.owners, ranges) |owner, *range| range.* = owner.range;
            try self.store.validateFkGenerationTableTxn(txn, self.group, expected, ranges);
            if (!try self.store.policyTopologyMutationAllowedTxn(txn, self.group, expected.table_id)) return error.RowPolicyUnsupported;
            try self.requireForeignKeyTargets(txn, plan);
        }

        fn requireForeignKeyTargets(self: @This(), txn: *docstore.DocStore.Txn, plan: @import("../schema_validation_plan.zig").Plan) !void {
            if (plan.selection != .foreign_keys) return;
            const local = @import("antfly_local_sources");
            const parents = plan.selection.foreign_keys.parents;
            var scratch = std.heap.ArenaAllocator.init(self.store.alloc);
            defer scratch.deinit();
            parent_loop: for (parents, 0..) |scope, ordinal| {
                for (parents[0..ordinal]) |prior| if (prior.parent_table_id == scope.parent_table_id) continue :parent_loop;
                _ = scratch.reset(.retain_capacity);
                const a = scratch.allocator();
                var buf: [192]u8 = undefined;
                const parent = try decodeTableRecord(a, try txn.get(try tableKeyForGroup(&buf, self.group, scope.parent_table_id)));
                if (parent.table_id != scope.parent_table_id or parent.storage.engine != .local or parent.restore_backup_id.len != 0) return error.CatalogGenerationChanged;
                var public = try local.schema_mod.parseValidatedTableSchema(a, parent.schema_json);
                defer public.deinit(a);
                const runtime = try local.schema_mod.deriveRelationalCheckLayout(a, public);
                defer local.storage_schema.freeSchema(a, runtime);
                const definitions = try local.schema_relational_declarations.definitionFingerprints(a, public, runtime);
                defer local.schema_relational_declarations.freeDefinitions(a, definitions);
                for (parents) |selected| {
                    if (selected.parent_table_id != scope.parent_table_id) continue;
                    if (!std.mem.eql(u8, selected.parent_table, parent.name) or !std.mem.eql(u8, selected.declared_parent, selected.parent_table)) return error.CatalogGenerationChanged;
                    const fingerprint = selected.parent_definition orelse return error.InvalidGenerationPublication;
                    const retained = for (definitions) |definition| {
                        if (definition.kind == .unique and std.mem.eql(u8, definition.name, selected.parent_unique) and std.mem.eql(u8, &definition.fingerprint, &fingerprint)) break true;
                    } else false;
                    if (!retained) return error.CatalogGenerationChanged;
                }
            }
        }
        pub fn admit(self: @This(), txn: *docstore.DocStore.Txn, plan: @import("../schema_validation_plan.zig").Plan, preparations: []const @import("../schema_validation_attestation.zig").SignedPreparation) !void {
            try self.requireCut(txn, plan, false);
            try self.store.validateRelationMutationTxn(txn, self.group, plan.table_guard.?, plan.before, plan.after);
            var floor: @import("antfly_local_sources").common_schema_readers.ReaderFloor = .{};
            if (plan.before.schema_reader_requirements) |required| floor = try floor.include(required);
            if (plan.after.schema_reader_requirements) |required| floor = try floor.include(required);
            const required: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements = if (floor.active()) .{ .semantic_version = floor.semantic_version, .encoding_version = floor.encoding_version } else null;
            for (plan.owners, preparations) |owner, signed|
                try self.store.verifySchemaValidationPreparationTxn(txn, self.group, owner.binding, owner.physical_root_incarnation, signed, required);
        }
        pub fn verify(self: @This(), txn: *docstore.DocStore.Txn, binding: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Binding, signed: @import("../schema_validation_attestation.zig").SignedObservation, required: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !@import("../schema_validation_attestation.zig").VerifiedObservation {
            const header = switch (signed) {
                inline else => |value| value.rooted.observation.header,
            };
            if (header) |value| if (value.phase == .canceled) {
                const incarnation = switch (signed) {
                    inline else => |observation| observation.proof.identity.metadata_incarnation,
                };
                const head = try schema_validation.readHead(txn, .{ .group = self.group, .table = binding.fence.namespace.table_id, .id = binding.id, .metadata_incarnation = incarnation, .plan_digest = binding.plan_digest });
                // A caller-selected canceled phase is not cleanup authority.
                // Rejoin THIS writer's durable decision; all enrollment, cut,
                // placement and namespace checks remain current and mandatory.
                const cleanup = (head.phase == .canceling or head.phase == .canceled) and head.install_revision == 0;
                return self.store.verifySchemaValidationObservationTxnMode(txn, self.group, binding, signed, required, cleanup);
            };
            return self.store.verifySchemaValidationObservationTxn(txn, self.group, binding, signed, required);
        }
        pub fn verifyAdoption(self: @This(), txn: *docstore.DocStore.Txn, head: @import("../schema_validation_publication.zig").Head, owner: @import("../schema_validation_publication.zig").Owner, signed: @import("../schema_validation_attestation.zig").SignedObservation) !@import("../schema_validation_attestation.zig").VerifiedObservation {
            // Only THIS writer's irreversible pre-install cancellation may
            // relax reader-role checks. Enrollment, serving placement, source
            // authority and all native/replay/epoch checks remain mandatory.
            if (head.metadata_group_id != self.group) return error.InvalidGenerationPublication;
            const cleanup = head.phase == .canceling and head.install_revision == 0;
            return self.store.verifySchemaValidationObservationTxnMode(txn, self.group, owner.binding, signed, head.reader_requirements, cleanup);
        }
        pub fn verifyBootstrap(self: @This(), txn: *docstore.DocStore.Txn, head: @import("../schema_validation_publication.zig").Head, owner: @import("../schema_validation_publication.zig").Owner, signed: @import("../schema_validation_bootstrap.zig").CertifiedPreparation) !void {
            if (head.metadata_group_id != self.group) return error.InvalidGenerationPublication;
            try owner.validate(head);
            for (std.meta.tags(@import("../schema_validation_publication.zig").Stage)) |stage| if (owner.has(stage)) return error.SchemaValidationRuntimeRecoveryRequired;
            _ = try signed.attestedScope(owner.binding, head.metadata_incarnation);
            try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                .group_id = owner.binding.fence.owner_group_id,
                .namespace = owner.binding.fence.namespace,
                .authority = owner.binding.authority,
            }, signed.preparation.value.position, signed.proof, head.reader_requirements, .{
                .cleanup = head.phase == .canceling and head.install_revision == 0,
                .require_source_authority = true,
                .allow_empty_preparation = true,
                .allow_empty_snapshot_cut = signed.preparation.value.position == null,
                .completed = signed.completed,
            });
        }
        pub fn verifyNativeBootstrap(self: @This(), txn: *docstore.DocStore.Txn, head: @import("../schema_validation_publication.zig").Head, owner: @import("../schema_validation_publication.zig").Owner, signed: @import("../schema_validation_attestation.zig").SignedPreparation) !void {
            if (head.metadata_group_id != self.group or owner.binding.authority != .native) return error.InvalidGenerationPublication;
            try owner.validate(head);
            for (std.meta.tags(@import("../schema_validation_publication.zig").Stage)) |stage| if (owner.has(stage)) return error.SchemaValidationRuntimeRecoveryRequired;
            try signed.verifyFor(owner.binding, signed.value.physical_root_incarnation);
            try self.store.requireOwnerRootProofTxn(txn, self.group, .{
                .group_id = owner.binding.fence.owner_group_id,
                .namespace = owner.binding.fence.namespace,
                .authority = .native,
            }, signed.value.position, signed.proof, head.reader_requirements, .{
                .cleanup = head.phase == .canceling and head.install_revision == 0,
                .require_source_authority = true,
                .allow_empty_preparation = true,
            });
        }
        pub fn verifyParent(self: @This(), txn: *docstore.DocStore.Txn, binding: @import("antfly_local_sources").storage_db_relational_schema_owner_contract.Binding, physical_root: u128, signed: @import("../schema_validation_attestation.zig").SignedSnapshotParent, required: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements) !void {
            return self.store.verifySchemaValidationSnapshotParentTxn(txn, self.group, binding, physical_root, signed, required);
        }
        pub fn publish(self: @This(), txn: *docstore.DocStore.Txn, plan: @import("../schema_validation_plan.zig").Plan) !void {
            try self.requireCut(txn, plan, false);
            var buf: [192]u8 = undefined;
            const storage_key = try tableKeyForGroup(&buf, self.group, plan.before.table_id);
            // The exact immutable successor, all-installed receipts and shared
            // lifecycle lock are joined by schema_validation.publish in this
            // SAME metadata transaction. Only that path bypasses its own lock.
            try self.store.putTableRecordTxnMode(txn, self.group, storage_key, plan.after, true);
        }
        fn requireReadyOwners(self: @This(), txn: *docstore.DocStore.Txn, lookup: schema_validation.Lookup) !void {
            var recovered = try schema_validation.recover(self.store.alloc, txn, lookup);
            defer recovered.deinit();
            if (recovered.head.phase != .validated) return error.GenerationPublicationChanged;
            try self.requireCut(txn, recovered.plan.value, false);
            for (recovered.owners) |owner| {
                try schema_validation.requireCurrentStageAuthority(txn, recovered.head, owner, .ready, self);
            }
        }
    };

    fn applySchemaValidationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        // Reserved until dispatch, physical recovery and unified restore have
        // all been qualified. Receiving code alone never advertises this floor.
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_validation_publication_version);
        if (!try relationWriterEnabledTxn(txn, group_id)) return error.CatalogOccupancyNotReady;
        if (try stagingGet(txn, metadata_hot_standby.outbox_key) != null) return error.MetadataReplicationPending;
        var parsed = try schema_validation.parseCommand(self.alloc, bytes);
        defer parsed.deinit();
        const context: SchemaValidationContext = .{ .store = self, .group = group_id };
        const lookup: ?schema_validation.Lookup = switch (parsed.value) {
            .begin => null,
            .ack => |ack| ack.lookup,
            .authorize_parent => |request| request.lookup,
            .adopt_root => |request| request.lookup,
            .install, .publish => |decision| decision.lookup,
            .cancel => |request| request.decision.lookup,
        };
        if (lookup) |identity| {
            if (identity.group != group_id) return error.InvalidGenerationPublication;
            var buf: [192]u8 = undefined;
            const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
            if (!std.mem.eql(u8, &incarnation, &identity.metadata_incarnation)) return error.MetadataIncarnationMismatch;
        }
        switch (parsed.value) {
            .begin => |request| {
                var prepared = try @import("../schema_validation_plan.zig").Prepared.init(self.alloc, request.plan);
                defer prepared.deinit();
                var buf: [192]u8 = undefined;
                const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)))).incarnation;
                if (prepared.head.metadata_group_id != group_id or !std.mem.eql(u8, &incarnation, &prepared.head.metadata_incarnation)) return error.MetadataIncarnationMismatch;
                try schema_validation.begin(self.alloc, txn, &prepared, request.preparations, request.inputs, context);
            },
            .ack => |request| _ = try schema_validation.acknowledge(txn, request.lookup, request.ordinal, request.revision, request.signed, context),
            .authorize_parent => |request| _ = try schema_validation.authorizeParent(txn, request, context),
            .adopt_root => |request| _ = try schema_validation.adoptRoot(txn, request, context),
            .install => |decision| {
                const head = try schema_validation.readHead(txn, decision.lookup);
                if (head.install_revision == 0) try context.requireReadyOwners(txn, decision.lookup);
                _ = try schema_validation.decideInstall(txn, decision.lookup, decision.revision);
            },
            .publish => |decision| _ = try schema_validation.publish(self.alloc, txn, decision.lookup, decision.revision, context),
            .cancel => |request| _ = try schema_validation.cancel(txn, request.decision.lookup, request.decision.revision, request.failure),
        }
    }

    fn beginRelationalIndexPublicationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        if (bytes.len == 0 or bytes.len > index_publication.max_command_bytes) return error.InvalidGenerationPublication;
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.index_publication_head_version);
        var parsed = try std.json.parseFromSlice(index_publication.Begin, self.alloc, bytes, .{ .allocate = .alloc_always });
        defer parsed.deinit();
        var prepared = try parsed.value.plan.prepare(self.alloc);
        defer prepared.deinit();
        try self.validateRelationalIndexBeginTxn(txn, group_id, parsed.value);
        try prepared.stageBegin(txn, group_id, parsed.value.expected_head);
        if (try relation_reconciliation.readSourceRevision(txn, group_id) != 0) try relation_reconciliation.advanceSource(txn, group_id);
    }

    fn applyFkGenerationPublicationTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        if (bytes.len == 0 or bytes.len > fk_generation_publication.max_bytes) return error.InvalidGenerationPublication;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const alloc = arena.allocator();
        var parsed_command = try std.json.parseFromSlice(fk_generation_publication.Command, alloc, bytes, .{});
        defer parsed_command.deinit();
        const command = parsed_command.value;
        try command.validateShape();
        if (command.plan) |plan| {
            if (plan.historical_reference_coverage) _ = try self.requireTopologyActivationTxn(txn, group_id, topology_protocol.fk_historical_references_version);
        }

        const table_id = command.child_table_id;
        var key_buf: [160]u8 = undefined;
        const key = try fk_generation_publication.key(&key_buf, group_id, table_id);
        const existing = txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var publication: fk_generation_publication.Publication = undefined;
        const source_tracked = try relation_reconciliation.readSourceRevision(txn, group_id) != 0;
        var previous_source_digest: ?[32]u8 = null;
        // Publication.apply retains the prior plan and all of its string
        // slices. Keep the decoded owner alive until the replacement has been
        // fully serialized and copied into the transaction.
        var previous: ?std.json.Parsed(fk_generation_publication.Publication) = null;
        defer if (previous) |*value| value.deinit();
        if (command.action == .begin) {
            const plan = command.plan.?;
            const plan_digest = try plan.digest(alloc);
            if (existing) |current_bytes| {
                var prior_terminal = try std.json.parseFromSlice(fk_generation_publication.Publication, alloc, current_bytes, .{});
                defer prior_terminal.deinit();
                if (plan.constraint_name_guard != null or plan.sql_drop != null) try prior_terminal.value.validate(alloc);
                if (prior_terminal.value.phase != .published and prior_terminal.value.phase != .canceled) {
                    if (plan.constraint_name_guard != null or plan.sql_drop != null) return;
                    return error.GenerationPublicationChanged;
                }
                if (source_tracked) previous_source_digest = try relationFkSourceDigest(prior_terminal.value, table_id);
            }
            self.validateFkGenerationBeginAdmissionTxn(txn, group_id, plan) catch |err| {
                if (plan.constraint_name_guard != null or plan.sql_drop != null) switch (err) {
                    error.CatalogGenerationChanged, error.CatalogPublicationProofPending, error.CatalogOccupancyNotReady, error.TableTopologyProtocolUpgradeRequired, error.ExtensionOwnedObject, error.GenerationPublicationChanged, error.RowPolicyUnsupported, error.SqlDependentObjectsExist, error.ForeignKeyReferenced, error.TableTransitionActive => return,
                    else => {},
                };
                return err;
            };
            try self.setFkGenerationTableLocksTxn(txn, group_id, plan, true);
            publication = .{ .plan = plan, .plan_digest = plan_digest, .child_identity = try plan.childIdentity(alloc), .revision = 1, .phase = .fencing_child };
        } else {
            previous = try std.json.parseFromSlice(fk_generation_publication.Publication, alloc, existing orelse return error.GenerationPublicationNotFound, .{ .allocate = .alloc_always });
            if (source_tracked) previous_source_digest = try relationFkSourceDigest(previous.?.value, table_id);
            publication = try previous.?.value.apply(alloc, command);
            if (command.action == .publish_child) {
                try self.validateFkGenerationCutTxn(txn, group_id, publication.plan, false);
                if (publication.plan.sql_drop) |guard| {
                    _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.sql_drop_generation_version);
                    try publication.validate(alloc);
                    var owner = try self.guardedRelationOwnerTxn(txn, group_id, guard);
                    defer owner.deinit();
                    try self.validateSqlDropDependenciesTxn(txn, group_id, publication.plan.child_before);
                    const lifecycle = @import("../table_lifecycle_lock.zig");
                    const lock = (try lifecycle.read(txn, group_id, table_id)) orelse return error.GenerationPublicationChanged;
                    if (lock.kind != .sql_drop or !std.mem.eql(u8, &lock.id, &publication.plan.id)) return error.GenerationPublicationChanged;
                    const fence = try self.loadTableTransitionFenceTxn(txn, group_id, table_id);
                    try self.applyTableTopologyMutationWithSqlDropTxn(txn, group_id, .{ .drop = .{ .table_id = table_id, .expected_name = publication.plan.child_before.name, .expected_transition_generation = fence.generation, .range_contract = .{ .membership = fence.membership(table_id) } } }, true);
                    var table_key_buf: [160]u8 = undefined;
                    if (try stagingGet(txn, try tableKeyForGroup(&table_key_buf, group_id, table_id)) != null) return error.GenerationPublicationChanged;
                } else {
                    var table_key_buf: [160]u8 = undefined;
                    try self.putTableRecordTxnMode(txn, group_id, try tableKeyForGroup(&table_key_buf, group_id, table_id), publication.plan.child_after, true);
                }
            }
        }
        if (publication.phase == .published or publication.phase == .canceled) try self.setFkGenerationTableLocksTxn(txn, group_id, publication.plan, false);
        const encoded = try std.json.Stringify.valueAlloc(alloc, publication, .{});
        if (encoded.len > fk_generation_publication.max_bytes) return error.InvalidGenerationPublication;
        if (source_tracked) {
            const digest = try relationFkSourceDigest(publication, table_id);
            if (previous_source_digest == null or !std.mem.eql(u8, &previous_source_digest.?, &digest)) try relation_reconciliation.advanceSource(txn, group_id);
        }
        try txn.put(key, encoded);
        var work_key_buf: [160]u8 = undefined;
        const work_key = try fk_generation_publication.workKey(&work_key_buf, group_id, table_id);
        if (publication.phase == .published or publication.phase == .canceled)
            try txn.delete(work_key)
        else
            try txn.put(work_key, &publication.plan.id);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id, .table_name = publication.plan.child_before.name, .table_id = table_id });
    }

    fn applySqlSettingsTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
        var parsed = try std.json.parseFromSlice(sql_settings.Command, self.alloc, bytes, .{});
        defer parsed.deinit();
        if (parsed.value.requiresRoleDefaultReaders() or @import("../schema_reader_wire.zig").requiresRoleDefaults(bytes))
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.sql_role_defaults_version);
        const previous = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
        try system_catalog_storage.applySettingCommand(self.alloc, txn, group_id, parsed.value, hash);
        const observed = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
        if (observed.revision != previous.revision) self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id });
    }

    const CatalogReader = struct {
        store: *RaftApplyStore,
        view: system_catalog_storage.View,
        pub fn lookup(self: @This(), kind: system_catalog.Kind, parent: u64, name: []const u8) !?system_catalog.Resource {
            return self.view.lookup(kind, parent, name);
        }
        pub fn byId(self: @This(), kind: system_catalog.Kind, id: u64) !?system_catalog.Resource {
            return self.view.byId(kind, id);
        }
        pub fn namespaceFor(self: @This(), database: []const u8, namespace: []const u8) !system_catalog.Resource {
            return self.view.namespaceFor(database, namespace);
        }
        pub fn children(self: @This(), kind: system_catalog.Kind, parent: u64, limit: usize) ![]const system_catalog.Resource {
            return self.view.children(kind, parent, limit);
        }
        pub fn bindingForStorage(self: @This(), name: []const u8) !?system_catalog.Resource {
            return self.view.bindingForStorage(name);
        }
        pub fn tablespaceInUse(self: @This(), id: u64) !bool {
            return self.view.tablespaceInUse(id);
        }
        pub fn physicalByName(self: @This(), name: []const u8) !?system_catalog.PhysicalTable {
            const value = (try self.store.getTableByNameResultTxn(system_catalog.ResolvedTable, self.view.alloc, self.view.txn, self.view.group_id, name)) orelse return null;
            return .{ .id = value.table_id, .name = value.name };
        }
        pub fn physicalById(self: @This(), id: u64) !?system_catalog.PhysicalTable {
            var buf: [160]u8 = undefined;
            const bytes = self.view.txn.get(try tableKeyForGroup(&buf, self.view.group_id, id)) catch |err| switch (err) {
                error.NotFound => return null,
                else => return err,
            };
            const value = try decodeTableIdentity(self.view.alloc, bytes);
            if (value.table_id != id) return error.InvalidCatalogRecord;
            return .{ .id = value.table_id, .name = value.name };
        }
    };

    pub const CatalogAdmission = apply_contract.CatalogAdmission;
    pub fn systemCatalogAdmission(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.Mutation) !CatalogAdmission {
        return self.systemCatalogAdmissionWithBinding(alloc, group_id, request, null);
    }

    pub fn systemCatalogAdmissionWithBinding(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.Mutation, binding: ?system_catalog.RelationMutationGuard) !CatalogAdmission {
        try (system_catalog.Request{ .mutation = request, .binding_guard = binding }).validateBinding();
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        if (binding) |guard| {
            var scope = try self.guardedRelationOwnerTxn(&txn, group_id, guard);
            defer scope.deinit();
        }
        if (request.kind == .table and request.action == .drop) {
            const table = (try self.resolveSystemCatalogResultTxn(metadata.TableRecord, alloc, &txn, group_id, .{ .database = request.database, .namespace = request.namespace, .table = request.name })) orelse return error.TableNotFound;
            defer metadata_table_manager.freeTable(alloc, table);
            try self.validateSqlDropDependenciesTxn(&txn, group_id, table);
        }
        const meta = try system_catalog_storage.readMeta(alloc, &txn, group_id);
        // Reject live deletion intents before proposal. Apply repeats this
        // check, but an apply-only no-op would make a definite naming conflict
        // appear to callers as an ambiguous mutation outcome.
        const reader: CatalogReader = .{ .store = self, .view = .{ .alloc = alloc, .txn = &txn, .group_id = group_id, .meta = meta } };
        try validateSqlDropNameMutation(reader, .{ .expected_revision = meta.revision, .mutation = request });
        var result: CatalogAdmission = .{ .meta = meta };
        if (request.kind == .table and (request.action == .create or request.action == .set_tablespace)) {
            const view: system_catalog_storage.View = .{ .alloc = alloc, .txn = &txn, .group_id = group_id, .meta = meta };
            const namespace = try view.namespaceFor(request.database, request.namespace);
            result.namespace_id = namespace.id;
            const explicit = if (request.tablespace) |name| ((try view.lookup(.tablespace, 0, name)) orelse return error.TablespaceNotFound).id else 0;
            if (try view.effectiveTablespace(namespace, explicit)) |space| result.placement_policy = space.placement_policy;
        }
        return result;
    }

    pub fn systemCatalogMeta(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) !system_catalog_storage.Meta {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return system_catalog_storage.readMeta(alloc, &txn, group_id);
    }

    pub fn checkConstraintNamesWithContext(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.ConstraintNameCheck, context: @import("antfly_local_sources").api_operation.RequestContext) !void {
        try context.ensureActive();
        try request.guard.validate();
        if (request.guard.constraint_name_admission == null) return error.InvalidCatalogMutation;
        if (request.schema_json.len > 16 * 1024 * 1024) return error.ProgramLimitExceeded;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [160]u8 = undefined;
        const raw = txn.get(try tableKeyForGroup(&key_buf, group_id, request.guard.owner.table_id)) catch |err| switch (err) {
            error.NotFound => return error.CatalogGenerationChanged,
            else => return err,
        };
        const before = try decodeTableRecord(alloc, raw);
        defer metadata_table_manager.freeTable(alloc, before);
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(before.schema_json, &digest, .{});
        if (!std.mem.eql(u8, &digest, &request.guard.owner.schema_digest)) return error.CatalogGenerationChanged;
        var after = before;
        after.schema_json = request.schema_json;
        try self.validateRelationMutationTxn(&txn, group_id, request.guard, before, after);
        try context.ensureActive();
    }

    pub fn prepareConstraintNamesJsonWithContext(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.ConstraintNamePreparation, context: @import("antfly_local_sources").api_operation.RequestContext) ![]u8 {
        try context.ensureActive();
        if (topology_protocol.current_version < topology_protocol.constraint_occupancy_version) return error.TableTopologyProtocolUpgradeRequired;
        var plan = switch (request) {
            .create => |input| try self.prepareGeneratedConstraintNames(alloc, group_id, input.expected_revision, input.namespace_id, input.logical_name, input.schema_json, input.generated_names, context),
            .addition => |input| blk: {
                if (input.guard.constraint_name_admission != null) return error.InvalidCatalogMutation;
                break :blk try self.prepareGeneratedConstraintAddition(alloc, group_id, input.guard, input.fragment_json, &.{input.generated_name}, context);
            },
        };
        defer plan.deinit();
        return std.json.Stringify.valueAlloc(alloc, system_catalog.ConstraintNamePrepared{ .schema_json = if (request == .create) plan.schema_json else null, .admission = plan.admission }, .{});
    }

    pub fn prepareGeneratedConstraintNames(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, expected_revision: u64, namespace_id: u64, logical_name: []const u8, schema_json: []const u8, generated: []const []const u8, context: @import("antfly_local_sources").api_operation.RequestContext) !relation_names.constraint_naming.Plan {
        try context.ensureActive();
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        const meta = try system_catalog_storage.readMeta(alloc, &txn, group_id);
        if (meta.revision != expected_revision) return error.CatalogGenerationChanged;
        return self.prepareGeneratedConstraintNamesTxn(alloc, &txn, group_id, namespace_id, logical_name, null, schema_json, generated, context);
    }

    /// A read-only preparation hint, not mutation authority. The publication
    /// must retain the captured owner guard and revalidate selected predicates
    /// in its own transaction. Never accept a client-supplied baseline schema.
    pub fn prepareGeneratedConstraintAddition(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, guard: system_catalog.RelationMutationGuard, fragment_json: []const u8, generated: []const []const u8, context: @import("antfly_local_sources").api_operation.RequestContext) !relation_names.constraint_naming.Plan {
        try context.ensureActive();
        try guard.validate();
        if (guard.owner.kind != .table) return error.SqlWrongObjectType;
        if (!std.mem.eql(u8, guard.target.name, guard.logical_table)) return error.InvalidCatalogMutation;
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        var scratch = std.heap.ArenaAllocator.init(alloc);
        defer scratch.deinit();
        const a = scratch.allocator();
        const epoch = try relationSourceEpochTxn(&txn, group_id);
        if (!std.mem.eql(u8, &guard.incarnation, &epoch.incarnation)) return error.CatalogGenerationChanged;
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group_id)) orelse return error.CatalogOccupancyNotReady;
        if (!live.root.epoch.eql(epoch)) return error.CatalogGenerationChanged;
        const namespace_id = (try resolveSystemCatalogNamespaceTxn(a, &txn, group_id, guard.target.database, guard.target.namespace)) orelse return error.CatalogGenerationChanged;
        const owner = (try live.getClaim(.{ .namespace_id = namespace_id, .name = guard.target.name })) orelse return error.CatalogGenerationChanged;
        if (!owner.eql(guard.owner)) return error.CatalogGenerationChanged;
        var key_buf: [160]u8 = undefined;
        const raw = txn.get(try tableKeyForGroup(&key_buf, group_id, owner.table_id)) catch |err| switch (err) {
            error.NotFound => return error.CatalogGenerationChanged,
            else => return err,
        };
        const table = try decodeTableProjection(a, raw, .schema);
        defer table.deinit(a);
        if (table.table_id != owner.table_id) return error.InvalidCatalogRecord;
        const definition = table.query_definition orelse return error.InvalidCatalogRecord;
        var schema_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(definition.schema_json, &schema_digest, .{});
        if (!std.mem.eql(u8, &schema_digest, &owner.schema_digest)) return error.InvalidCatalogRecord;
        if (try system_catalog_storage.getById(a, &txn, group_id, .table, owner.table_id)) |binding| {
            if (binding.value.parent_id != namespace_id or !std.mem.eql(u8, binding.value.name, guard.logical_table) or
                !std.mem.eql(u8, binding.value.storage_name, table.name)) return error.CatalogGenerationChanged;
        } else if (namespace_id != system_catalog.default_namespace_id or !std.mem.eql(u8, table.name, guard.logical_table)) return error.CatalogGenerationChanged;
        return self.prepareGeneratedConstraintNamesTxn(alloc, &txn, group_id, namespace_id, guard.logical_table, definition.schema_json, fragment_json, generated, context);
    }

    fn prepareGeneratedConstraintNamesTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, namespace_id: u64, logical_name: []const u8, baseline_schema_json: ?[]const u8, schema_json: []const u8, generated: []const []const u8, context: @import("antfly_local_sources").api_operation.RequestContext) !relation_names.constraint_naming.Plan {
        _ = self;
        try context.ensureActive();
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(txn, group_id)) orelse return error.CatalogOccupancyNotReady;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        const Namespace = struct {
            live: *relation_reconciliation.LiveStore(docstore.DocStore.Txn),
            id: u64,
            context: @import("antfly_local_sources").api_operation.RequestContext,
            pub fn checkpoint(self_ns: *@This()) !void {
                try self_ns.context.ensureActive();
            }
            pub fn occupied(self_ns: *@This(), label: []const u8, kind: relation_names.constraint_naming.Kind) !bool {
                try self_ns.checkpoint();
                return self_ns.live.nameOccupied(self_ns.id, label, kind.includesRelationNames());
            }
            pub fn relationOccupied(self_ns: *@This(), label: []const u8) !bool {
                try self_ns.checkpoint();
                const entry = (try self_ns.live.getEntry(.{ .namespace_id = self_ns.id, .name = label })) orelse return false;
                if (entry.empty()) return error.InvalidCatalogRecord;
                return true;
            }
        };
        var namespace: Namespace = .{ .live = &live, .id = namespace_id, .context = context };
        if (baseline_schema_json) |baseline| return relation_names.constraint_naming.Plan.prepareAddition(alloc, logical_name, namespace_id, baseline, schema_json, generated, &namespace, 8192);
        return relation_names.constraint_naming.Plan.prepare(alloc, logical_name, namespace_id, schema_json, generated, &namespace, 8192);
    }

    fn validateGeneratedConstraintNamesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, command: SystemCatalogCommand, meta: system_catalog_storage.Meta) !void {
        const compound = command.column_sequences.len != 0;
        if (compound) {
            if (command.version != 3 or command.mutation.kind != .table or command.mutation.action != .create) return error.InvalidCatalogMutation;
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.sql_column_sequences_version);
        }
        const admission = command.constraint_name_admission orelse {
            if (command.version != (if (compound) @as(u16, 3) else 1)) return error.InvalidCatalogMutation;
            return;
        };
        if (command.version != (if (compound) @as(u16, 3) else 2) or command.mutation.kind != .table or command.mutation.action != .create) return error.InvalidCatalogMutation;
        const topology = command.topology orelse return error.InvalidCatalogMutation;
        if (topology != .create) return error.InvalidCatalogMutation;
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.constraint_occupancy_version);
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group_id, .meta = meta };
        const namespace = try view.namespaceFor(command.mutation.database, command.mutation.namespace);
        try self.validateConstraintNameOccupancyTxn(a, txn, group_id, admission, namespace.id, topology.create.table.schema_json);
    }

    fn validateConstraintNameOccupancyTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, admission: relation_names.constraint_naming.Admission, namespace_id: u64, schema_json: []const u8) !void {
        _ = self;
        if (admission.namespace_id != namespace_id) return error.InvalidCatalogRecord;
        try admission.validateSchema(a, schema_json);
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(txn, group_id)) orelse return error.CatalogOccupancyNotReady;
        for (admission.names) |name| if (try live.nameOccupied(namespace_id, name.name, name.kind.includesRelationNames())) return error.CatalogGenerationChanged;
    }

    fn validateInitialConstraintNameAdmissionTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, admission: relation_names.constraint_naming.Admission, plan: fk_generation_publication.InitialCreatePlan) !void {
        _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.constraint_occupancy_version);
        try self.validateConstraintNameOccupancyTxn(a, txn, group_id, admission, plan.namespace_id, plan.child.schema_json);
    }

    pub fn validateSystemCatalog(self: *RaftApplyStore, group_id: u64, command: SystemCatalogCommand) !void {
        const result = try self.prepareSystemCatalogResult(self.alloc, group_id, command);
        self.alloc.free(result);
    }

    fn validateCatalogTopology(command: SystemCatalogCommand) !void {
        const physical = command.mutation.kind == .table and (command.mutation.action == .create or command.mutation.action == .drop);
        if (physical != (command.topology != null)) return error.InvalidCatalogMutation;
        const placement = command.mutation.kind == .table and command.mutation.action == .set_tablespace;
        if (placement != (command.placement_update != null)) return error.InvalidCatalogMutation;
        if (command.topology) |topology| switch (topology) {
            .create => |create| if (command.mutation.action != .create or create.table.table_id != command.mutation.table_id or !std.mem.eql(u8, create.table.name, command.mutation.storage_name)) return error.InvalidCatalogMutation,
            .drop => |drop| if (command.mutation.action != .drop or drop.table_id != command.mutation.table_id or !std.mem.eql(u8, drop.expected_name, command.mutation.storage_name)) return error.InvalidCatalogMutation,
        };
    }

    fn validateSqlDropNameMutation(reader: CatalogReader, command: SystemCatalogCommand) !void {
        const mutation = command.mutation;
        if (mutation.kind == .table) {
            if (mutation.action == .create) return;
            const table = (try reader.store.resolveSystemCatalogResultTxn(system_catalog.ResolvedTable, reader.view.alloc, reader.view.txn, reader.view.group_id, .{ .database = mutation.database, .namespace = mutation.namespace, .table = mutation.name })) orelse return;
            if (try reader.store.fkTableLockKindTxn(reader.view.txn, reader.view.group_id, table.table_id) == .sql_drop) return error.TableTransitionActive;
            return;
        }
        if ((mutation.kind != .database and mutation.kind != .namespace) or
            (mutation.action != .rename and mutation.action != .drop)) return;
        // Ancestor renames would invalidate the admitted relation guard after
        // irreversible parent activation. Inspect only live lifecycle locks and
        // their compact namespace bindings, never complete publication plans.
        const target = if (mutation.kind == .database)
            (try reader.lookup(.database, 0, mutation.name)) orelse return
        else block: {
            const database = (try reader.lookup(.database, 0, mutation.database)) orelse return;
            break :block (try reader.lookup(.namespace, database.id, mutation.name)) orelse return;
        };
        const lifecycle = @import("../table_lifecycle_lock.zig");
        var prefix_buffer: [160]u8 = undefined;
        const prefix = try lifecycle.prefix(&prefix_buffer, reader.view.group_id);
        var cursor = try reader.view.txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        while (row) |entry| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            if ((try lifecycle.Lock.decode(entry.value)).kind != .sql_drop) continue;
            const table_id = (try lifecycle.tableFromKey(entry.key)) orelse return error.InvalidGenerationPublication;
            var binding = try system_catalog_storage.getById(reader.store.alloc, reader.view.txn, reader.view.group_id, .table, table_id);
            defer if (binding) |*value| value.deinit();
            // Unbound legacy tables belong only to the protected default scope.
            const namespace_id = if (binding) |value| value.value.parent_id else system_catalog.default_namespace_id;
            if (namespace_id == 0) return error.InvalidCatalogRecord;
            if (mutation.kind == .namespace) {
                if (namespace_id == target.id) return error.TableTransitionActive;
            } else {
                var namespace = try system_catalog_storage.getById(reader.store.alloc, reader.view.txn, reader.view.group_id, .namespace, namespace_id);
                defer if (namespace) |*value| value.deinit();
                const database_id = if (namespace) |value| value.value.parent_id else if (namespace_id == system_catalog.default_namespace_id) system_catalog.default_database_id else return error.InvalidCatalogRecord;
                if (database_id == target.id) return error.TableTransitionActive;
            }
        }
    }

    /// Bind placement to the logical target and derive the ONLY permitted
    /// physical delta from this same catalog cut. A placement command cannot
    /// substitute another table, smuggle schema changes, or omit its writer.
    fn validateCatalogPlacement(reader: CatalogReader, command: SystemCatalogCommand, delta: system_catalog.Delta) !void {
        const update = command.placement_update orelse return;
        if (delta.upserts.len != 1 or delta.removes.len != 0) return error.InvalidCatalogMutation;
        const binding = delta.upserts[0];
        if (binding.kind != .table or binding.id != update.expected.table_id or
            !std.mem.eql(u8, binding.storage_name, update.expected.name)) return error.InvalidCatalogMutation;
        const namespace = try reader.namespaceFor(command.mutation.database, command.mutation.namespace);
        const policy = if (try reader.view.effectiveTablespace(namespace, binding.tablespace_id)) |space|
            space.placement_policy
        else
            system_catalog.PlacementPolicy{};
        try policy.validate();
        var derived = update.expected;
        derived.placement_role = policy.placement_role orelse "data";
        derived.desired_replica_count = if (derived.storage.engine == .object) 0 else policy.desired_replica_count orelse 3;
        derived.min_ranges = if (derived.storage.engine == .object) 0 else policy.min_ranges orelse 1;
        if (!metadata_table_manager.tableDefinitionsEqual(derived, update.replacement)) return error.InvalidCatalogMutation;
    }

    /// Capture the complete indexed owned set in the same metadata cut as the
    /// source table and native attribute identities. No sequence is changed.
    pub fn prepareColumnSequenceHandoffs(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: @import("../column_sequence_handoff.zig").Request) ![]u8 {
        const handoff = @import("../column_sequence_handoff.zig");
        if (request.targets.len == 0 or request.targets.len > 128) return error.InvalidRestoreStaging;
        var txn = try self.beginQueryCatalogReadTxn(group);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const targets = try a.dupe(restore_staging.Target, request.targets);
        var total: usize = 0;
        for (targets) |*target| {
            if ((!target.empty_generation and target.rewrite == null) or target.sequence_handoffs.len != 0) return error.InvalidRestoreStaging;
            const old = target.replace orelse return error.InvalidRestoreStaging;
            const actual = (try self.getTableTxn(a, &txn, group, old.table.table_id)) orelse return error.CatalogGenerationChanged;
            if (!metadata_table_manager.tableDefinitionsEqual(actual, old.table)) return error.CatalogGenerationChanged;
            var moves: std.ArrayList(handoff.Move) = .empty;
            var prefix_buffer: [192]u8 = undefined;
            const prefix = try sql_sequences.ownerPrefix(&prefix_buffer, group, old.table.table_id);
            var cursor = try txn.openCursor();
            defer cursor.close();
            var row = try cursor.seekAtOrAfter(prefix);
            if (row == null or !std.mem.startsWith(u8, row.?.key, prefix)) continue;
            _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.sql_column_sequences_version);
            var before = try self.columnDescriptionStateTxn(a, &txn, group, old.table);
            defer before.deinit();
            var after = try column_identities.State.decode(a, try columnIdentityValue(a, target.table, null, &.{}));
            defer after.deinit();
            while (row) |entry| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, entry.key, prefix)) break;
                if (total == handoff.max_moves or !std.mem.eql(u8, entry.value, &.{1})) return error.InvalidRestoreStaging;
                const edge = try sql_sequences.ownershipFromKey(entry.key, group, old.table.table_id);
                const column = before.value.columnById(edge.owner.column_id) orelse return error.InvalidSequenceState;
                const next = for (after.value.columns) |candidate| {
                    if (std.mem.eql(u8, column.name, candidate.name)) break candidate;
                } else return error.InvalidSequenceState;
                var resource = (try system_catalog_storage.getById(a, &txn, group, .sequence, edge.sequence_id)) orelse return error.InvalidSequenceState;
                defer resource.deinit();
                const descriptor = try sql_sequences.sequence.Descriptor.decode(a, resource.value.source_json);
                if (!std.meta.eql((try descriptor.definition()).owned_by, @as(?sql_sequences.sequence.OwnedBy, edge.owner))) return error.InvalidSequenceState;
                try moves.append(a, .{ .before = try system_catalog.cloneResource(a, resource.value), .owner = .{ .table_id = target.table.table_id, .column_id = next.id }, .restart = request.restart });
                total += 1;
            }
            target.sequence_handoffs = try moves.toOwnedSlice(a);
            target.table.schema_json = try handoff.rewriteSchema(a, target.table.schema_json, old.table.table_id, after.value, target.sequence_handoffs);
            target.table.schema_reader_requirements = try @import("antfly_local_sources").schema_mod.readerRequirementsForDefinitions(a, target.table.schema_json, target.table.read_schema_json);
        }
        return std.json.Stringify.valueAlloc(alloc, targets, .{});
    }

    /// An immutable plan must cover every edge, including manually OWNED BY
    /// sequences. Concurrent ownership DDL invalidates admission/publication;
    /// advancing counters alone does not invalidate CONTINUE IDENTITY.
    fn validateColumnSequenceHandoffsTxn(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, target: restore_staging.Target) !void {
        const old = target.replace orelse {
            if (target.sequence_handoffs.len != 0) return error.InvalidRestoreStaging;
            return;
        };
        if (!target.empty_generation and target.rewrite == null) {
            if (target.sequence_handoffs.len != 0) return error.InvalidRestoreStaging;
            return;
        }
        var buffer: [192]u8 = undefined;
        const prefix = try sql_sequences.ownerPrefix(&buffer, group, old.table.table_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        var count: usize = 0;
        while (row) |entry| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            const edge = try sql_sequences.ownershipFromKey(entry.key, group, old.table.table_id);
            if (!std.mem.eql(u8, entry.value, &.{1}) or count == target.sequence_handoffs.len) return error.InvalidRestoreStaging;
            const move = for (target.sequence_handoffs) |candidate| {
                if (candidate.before.id == edge.sequence_id) break candidate;
            } else return error.InvalidRestoreStaging;
            var resource = (try system_catalog_storage.getById(a, txn, group, .sequence, edge.sequence_id)) orelse return error.InvalidSequenceState;
            defer resource.deinit();
            if (resource.value.parent_id != move.before.parent_id or !std.mem.eql(u8, resource.value.name, move.before.name) or
                !std.mem.eql(u8, resource.value.source_json, move.before.source_json)) return error.InvalidRestoreStaging;
            const descriptor = try sql_sequences.sequence.Descriptor.decode(a, resource.value.source_json);
            if (!std.meta.eql((try descriptor.definition()).owned_by, @as(?sql_sequences.sequence.OwnedBy, edge.owner))) return error.InvalidSequenceState;
            count += 1;
        }
        if (count != target.sequence_handoffs.len) return error.InvalidRestoreStaging;
        if (count == 0) return;
        var attributes = try column_identities.State.decode(a, try columnIdentityValue(a, target.table, null, &.{}));
        defer attributes.deinit();
        try @import("../column_sequence_handoff.zig").validateSchemaBindings(a, target.table.schema_json, attributes.value, target.sequence_handoffs);
    }

    /// The enclosing metadata transaction has validated every table, range,
    /// catalog preimage and complete ownership set before reaching this point.
    fn applyColumnSequenceHandoffsTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, plan: restore_staging.Plan) !void {
        const Change = struct { move: @import("../column_sequence_handoff.zig").Move, prior: sql_sequences.sequence.Record };
        var changes: std.ArrayList(Change) = .empty;
        for (plan.targets) |target| for (target.sequence_handoffs) |move| {
            _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_column_sequences_version);
            const definition = try (try sql_sequences.sequence.Descriptor.decode(a, move.before.source_json)).definition();
            const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = move.before.id } };
            const prior: sql_sequences.sequence.Record = .{ .definition = definition, .state = (try counter.load(a, definition)) orelse return error.InvalidSequenceState };
            _ = try move.definition(a);
            if (move.restart) _ = try prior.alter(.{ .owned_by = .{ .column = move.owner }, .restart = .{} });
            try changes.append(a, .{ .move = move, .prior = prior });
        };
        for (changes.items) |change| {
            const move = change.move;
            if (move.restart) {
                const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = move.before.id } };
                _ = try counter.alter(a, change.prior, .{ .owned_by = .{ .column = move.owner }, .restart = .{} });
            }
            var buffer: [192]u8 = undefined;
            try txn.delete(try sql_sequences.ownerKey(&buffer, group, change.prior.definition.owned_by.?, move.before.id));
            try txn.put(try sql_sequences.ownerKey(&buffer, group, move.owner, move.before.id), &.{1});
        }
    }

    /// First bind the compiler's owned-column intent in a read-only native
    /// transaction. The containing catalog command carries these exact bytes;
    /// preflight and Raft apply independently derive and verify them again.
    pub fn bindTableColumnSequences(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, command: SystemCatalogCommand) ![]u8 {
        var txn = try self.beginQueryCatalogReadTxn(group);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, &txn, group);
        if (meta.revision != command.expected_revision) return error.CatalogGenerationChanged;
        const reader: CatalogReader = .{ .store = self, .view = .{ .alloc = a, .txn = &txn, .group_id = group, .meta = meta } };
        try validateCatalogTopology(command);
        try validateSqlDropNameMutation(reader, command);
        var delta = try system_catalog.planWithTopology(a, reader, meta.next_id, command.mutation, false);
        defer delta.deinit(a);
        const prepared = try self.prepareTableColumnSequencesTxn(a, &txn, group, command, meta, delta.next_id, true);
        var bound = command;
        bound.topology.?.create.table.schema_json = prepared.schema_json;
        bound.topology.?.create.table.schema_reader_requirements = try @import("antfly_local_sources").schema_mod.readerRequirementsForDefinitions(a, prepared.schema_json, bound.topology.?.create.table.read_schema_json);
        return std.json.Stringify.valueAlloc(alloc, bound, .{});
    }

    fn prepareTableColumnSequencesTxn(
        self: *RaftApplyStore,
        a: std.mem.Allocator,
        txn: *docstore.DocStore.Txn,
        group: u64,
        command: SystemCatalogCommand,
        meta: system_catalog_storage.Meta,
        first_id: u64,
        allow_unbound: bool,
    ) !@import("antfly_local_sources").system_catalog_column_sequence_creation.Plan {
        const sources = @import("antfly_local_sources");
        if (command.version != 3 or command.column_sequences.len == 0 or command.column_sequences.len > 256 or
            command.mutation.kind != .table or command.mutation.action != .create or command.sql_sequence != null or
            command.sql_view != null or command.placement_update != null) return error.InvalidCatalogMutation;
        const topology = command.topology orelse return error.InvalidCatalogMutation;
        if (topology != .create or topology.create.table.table_id != command.mutation.table_id) return error.InvalidCatalogMutation;
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_column_sequences_version);
        const epoch = try relationSourceEpochTxn(txn, group);
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group, .meta = meta };
        const namespace = try view.namespaceFor(command.mutation.database, command.mutation.namespace);
        var registry = try RelationRegistry(docstore.DocStore.Txn).init(a, txn, group);
        const live = registry.live orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names or !live.root.epoch.eql(epoch) or !try relationWriterEnabledTxn(txn, group))
            return error.CatalogOccupancyNotReady;
        const table = topology.create.table;
        const attribute_bytes = try columnIdentityValue(a, table, null, &.{});
        var attributes = try column_identities.State.decode(a, attribute_bytes);
        defer attributes.deinit();
        var parsed = try sources.schema_mod.parseValidatedTableSchema(a, table.schema_json);
        defer parsed.deinit(a);
        const runtime = try sources.schema_mod.deriveRuntimeTableSchema(a, parsed);
        defer sources.storage_schema.freeSchema(a, runtime);
        const columns = try sources.sql_document_row.deriveRelationalColumnsLeaky(a, a, parsed, runtime);
        const Namespace = struct {
            view: system_catalog_storage.View,
            registry: *RelationRegistry(docstore.DocStore.Txn),
            namespace_id: u64,
            columns: []const sources.sql_catalog.Column,

            pub fn checkpoint(_: *@This()) !void {}
            pub fn relationOccupied(context: *@This(), name: []const u8) !bool {
                return try context.registry.getEntry(.{ .namespace_id = context.namespace_id, .name = name }) != null or
                    try context.view.lookup(.table, context.namespace_id, name) != null or
                    try context.view.lookup(.view, context.namespace_id, name) != null or
                    try context.view.lookup(.sequence, context.namespace_id, name) != null;
            }
            pub fn requireColumn(context: *@This(), name: []const u8, expected: sql_sequences.sequence.Integer) !void {
                const column = for (context.columns) |candidate| {
                    if (std.mem.eql(u8, candidate.name, name)) break candidate;
                } else return error.UndefinedColumn;
                if (column.type != .integer or column.nullable) return error.InvalidSequenceDefinition;
                const width: sql_sequences.sequence.Integer = switch (column.element_type orelse .int64) {
                    .int16 => .int16,
                    .int32 => .int32,
                    .int64 => .int64,
                    else => return error.InvalidSequenceDefinition,
                };
                if (width != expected) return error.InvalidSequenceDefinition;
            }
        };
        var occupied: Namespace = .{ .view = view, .registry = &registry, .namespace_id = namespace.id, .columns = columns };
        const prepared = try sources.system_catalog_column_sequence_creation.prepare(a, .{
            .target = .{ .database = command.mutation.database, .namespace = command.mutation.namespace, .table = command.mutation.name },
            .namespace_id = namespace.id,
            .incarnation = epoch.incarnation,
            .first_id = first_id,
            .identities = attributes.value,
            .schema_json = table.schema_json,
            .columns = command.column_sequences,
            .allow_unbound = allow_unbound,
        }, &occupied);
        for (prepared.sequences) |item| {
            const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = item.binding.sequence_id } };
            if (try counter.load(a, item.definition) != null) return error.InvalidSequenceState;
        }
        return prepared;
    }

    fn expandTableColumnSequenceDelta(a: std.mem.Allocator, delta: *system_catalog.Delta, prepared: @import("antfly_local_sources").system_catalog_column_sequence_creation.Plan) !void {
        const resources = try a.alloc(system_catalog.Resource, delta.upserts.len + prepared.sequences.len);
        @memcpy(resources[0..delta.upserts.len], delta.upserts);
        for (resources[delta.upserts.len..], prepared.sequences) |*resource, item| resource.* = .{
            .kind = .sequence,
            .id = item.binding.sequence_id,
            .parent_id = item.binding.namespace_id,
            .name = item.binding.target.table,
            .source_json = try (try sql_sequences.sequence.Descriptor.init(item.binding.sequence_id, item.definition)).encode(a),
        };
        a.free(delta.upserts);
        delta.upserts = resources;
        delta.next_id = prepared.next_id;
    }

    fn initializeTableColumnSequencesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, table: metadata.TableRecord, prepared: @import("antfly_local_sources").system_catalog_column_sequence_creation.Plan) !void {
        // No semantic nonadmission may occur after the first persistent write.
        // The caller has already verified the complete table/catalog preimage.
        try self.initializeColumnIdentitiesTxn(txn, group, table);
        for (prepared.sequences) |item| {
            const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = item.binding.sequence_id } };
            try counter.initialize(a, try sql_sequences.sequence.Record.create(.{
                .integer = item.definition.integer,
                .increment = item.definition.increment,
                .minimum = .{ .value = item.definition.minimum },
                .maximum = .{ .value = item.definition.maximum },
                .start = item.definition.start,
                .cache = item.definition.cache,
                .cycle = item.definition.cycle,
                .owned_by = .{ .column = item.binding.owner },
            }));
            var key_buffer: [192]u8 = undefined;
            try txn.put(try sql_sequences.ownerKey(&key_buffer, group, item.binding.owner, item.binding.sequence_id), &.{1});
        }
    }

    /// Validate and serialize the exact admitted projection before proposing.
    pub fn prepareSystemCatalogResult(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, command: SystemCatalogCommand) ![]u8 {
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        if (command.column_sequences.len != 0 and (command.sql_sequence != null or command.sql_view != null)) return error.InvalidCatalogMutation;
        if (command.sql_sequence != null) return std.json.Stringify.valueAlloc(alloc, try self.prepareSqlSequenceCatalogTxn(&txn, group_id, command), .{});
        if (command.sql_view != null) return std.json.Stringify.valueAlloc(alloc, try self.applySqlViewLifecycleTxn(&txn, group_id, command, false), .{});
        if (command.mutation.action == .comment) _ = try self.requireTopologyActivationTxn(&txn, group_id, topology_protocol.sql_resource_comments_version);
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, &txn, group_id);
        if (meta.revision != command.expected_revision) return error.CatalogGenerationChanged;
        try self.validateGeneratedConstraintNamesTxn(a, &txn, group_id, command, meta);
        const reader: CatalogReader = .{ .store = self, .view = .{ .alloc = a, .txn = &txn, .group_id = group_id, .meta = meta } };
        try validateCatalogTopology(command);
        var delta = try system_catalog.planWithTopology(a, reader, meta.next_id, command.mutation, command.mutation.kind == .table and command.mutation.action == .drop);
        defer delta.deinit(a);
        if (command.column_sequences.len != 0) {
            const prepared = try self.prepareTableColumnSequencesTxn(a, &txn, group_id, command, meta, delta.next_id, false);
            if (!std.mem.eql(u8, command.topology.?.create.table.schema_json, prepared.schema_json)) return error.InvalidCatalogMutation;
            try expandTableColumnSequenceDelta(a, &delta, prepared);
        }
        try validateCatalogPlacement(reader, command, delta);
        if (command.placement_update) |update| {
            if (command.mutation.kind != .table or command.mutation.action != .set_tablespace or update.expected.table_id != update.replacement.table_id or !std.mem.eql(u8, update.expected.name, update.replacement.name)) return error.InvalidCatalogMutation;
            if ((try self.loadTableTransitionFenceTxn(&txn, group_id, update.expected.table_id)).active()) return error.TableTransitionActive;
            const current = (try self.getTableByNameTxn(self.alloc, &txn, group_id, update.expected.name)) orelse return error.TableNotFound;
            defer metadata_table_manager.freeTable(self.alloc, current);
            if (!metadata_table_manager.tableDefinitionsEqual(current, update.expected)) return error.TableGenerationChanged;
        }
        return std.json.Stringify.valueAlloc(alloc, try system_catalog.mutationResult(reader, meta.revision + 1, delta), .{});
    }

    /// Qualified point lookup shares one read transaction across name indexes
    /// and the physical table record. Caller owns the returned table record.
    pub fn resolveSystemCatalogTable(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, target: system_catalog.Target) !?metadata.TableRecord {
        return self.resolveSystemCatalogResult(metadata.TableRecord, alloc, group_id, target);
    }

    pub fn resolveSystemCatalogIdentity(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, target: system_catalog.Target) !?system_catalog.ResolvedTable {
        return self.resolveSystemCatalogResult(system_catalog.ResolvedTable, alloc, group_id, target);
    }

    fn resolveSystemCatalogResult(self: *RaftApplyStore, comptime Result: type, alloc: std.mem.Allocator, group_id: u64, target: system_catalog.Target) !?Result {
        try target.validate();
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        return self.resolveSystemCatalogResultTxn(Result, alloc, &txn, group_id, target);
    }

    fn resolveSqlSourceTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, meta: system_catalog_storage.Meta, lookup: system_catalog.SqlSourceLookup, include_definition: bool) !?system_catalog.SqlSource {
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group, .meta = meta };
        var target: system_catalog.Target = undefined;
        var resource: ?system_catalog.Resource = null;
        var table: ?system_catalog.ResolvedTable = null;
        switch (lookup) {
            .name => |name| {
                try name.validate();
                target = name;
                const namespace = (try resolveSystemCatalogNamespaceTxn(a, txn, group, name.database, name.namespace)) orelse return null;
                resource = try view.lookup(.view, namespace, name.table);
                table = try self.resolveSystemCatalogResultTxn(system_catalog.ResolvedTable, a, txn, group, name);
                if (resource != null and table != null) return error.InvalidCatalogRecord;
            },
            .table_id, .view_id => |id| {
                if (id == 0) return error.InvalidCatalogMutation;
                const kind: system_catalog.Kind = if (lookup == .view_id) .view else .table;
                resource = try view.byId(kind, id);
                if (resource) |binding| {
                    const namespace = (try view.byId(.namespace, binding.parent_id)) orelse return error.InvalidCatalogRecord;
                    const database = (try view.byId(.database, namespace.parent_id)) orelse return error.InvalidCatalogRecord;
                    target = .{ .database = database.name, .namespace = namespace.name, .table = binding.name };
                    if (kind == .table) {
                        table = try self.resolveSystemCatalogResultTxn(system_catalog.ResolvedTable, a, txn, group, target);
                        if (table == null or table.?.table_id != id) return error.InvalidCatalogRecord;
                        resource = null;
                    }
                } else if (kind == .view) return null else {
                    var buffer: [160]u8 = undefined;
                    const bytes = (try stagingGet(txn, try tableKeyForGroup(&buffer, group, id))) orelse return null;
                    table = try decodeTableIdentity(a, bytes);
                    if (table.?.table_id != id) return error.InvalidCatalogRecord;
                    target = .{ .table = table.?.name };
                    // A raw physical record is not proof of public existence:
                    // hidden/retired restore generations can retain one. Use
                    // the ordinary name index and visibility rules as well.
                    table = (try self.resolveSystemCatalogResultTxn(system_catalog.ResolvedTable, a, txn, group, target)) orelse return null;
                    if (table.?.table_id != id) return error.InvalidCatalogRecord;
                }
            },
        }
        if (table == null and resource == null) return null;
        var result: system_catalog.SqlSource = .{
            .target = .{ .database = try alloc.dupe(u8, target.database), .namespace = "", .table = "" },
            .value = .{ .table = .{ .binding = .{ .table_id = 0, .name = "" } } },
        };
        errdefer result.deinit(alloc);
        result.target.namespace = try alloc.dupe(u8, target.namespace);
        result.target.table = try alloc.dupe(u8, target.table);
        if (resource) |binding| {
            _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_view_catalog_version);
            var record = try sql_views.Record.decode(a, binding.source_json);
            defer record.deinit();
            if (record.value.id != binding.id) return error.InvalidSqlViewRecord;
            if (record.value.definition.requiredFormat() >= 2) _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_view_domains_version);
            result.value = .{ .view = try system_catalog.cloneResource(alloc, binding) };
        } else {
            var binding = table.?;
            if (include_definition) binding.query_definition = try self.queryTableDefinitionTxn(a, txn, group, binding.name);
            result.value = .{ .table = .{ .binding = try binding.clone(alloc) } };
            if (include_definition) {
                const key = try column_identities.key(.{ .group = group, .table = binding.table_id });
                if (try stagingGet(txn, &key)) |bytes|
                    result.value.table.column_identities_json = try alloc.dupe(u8, bytes);
            }
        }
        return result;
    }

    pub fn resolveSystemCatalogIdentities(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.ResolveMany) !system_catalog.ResolvedMany {
        return self.resolveSystemCatalogIdentitiesWithContext(alloc, group_id, request, .{});
    }

    pub fn resolveSystemCatalogIdentitiesWithContext(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, request: system_catalog.ResolveMany, context: @import("antfly_local_sources").api_operation.RequestContext) !system_catalog.ResolvedMany {
        try context.ensureActive();
        if (request.targets.len > 256 or request.storage_names.len > 256 - request.targets.len or request.relations.len > 256 - request.targets.len - request.storage_names.len or request.sql_sources.len > 256 - request.targets.len - request.storage_names.len - request.relations.len) return error.CatalogCommandTooLarge;
        if (request.expected_relation_epoch != null and request.relations.len == 0) return error.InvalidCatalogMutation;
        for (request.relations) |target| try target.validate();
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        const meta = try system_catalog_storage.readMeta(alloc, &txn, group_id);
        if (request.expected_revision) |expected| if (expected != meta.revision) return error.CatalogGenerationChanged;
        if (request.sql_sources.len != 0) {
            if (request.name_allocation or request.relations.len != 0 or request.targets.len != 0 or request.storage_names.len != 0 or request.expected_relation_epoch != null) return error.InvalidCatalogMutation;
            const resolved = try alloc.alloc(?system_catalog.SqlSource, request.sql_sources.len);
            var initialized_sources: usize = 0;
            errdefer {
                for (resolved[0..initialized_sources]) |entry| if (entry) |value| value.deinit(alloc);
                alloc.free(resolved);
            }
            for (request.sql_sources, resolved) |lookup, *entry| {
                try context.ensureActive();
                entry.* = try self.resolveSqlSourceTxn(alloc, &txn, group_id, meta, lookup, request.include_query_definitions);
                initialized_sources += 1;
            }
            return .{ .revision = meta.revision, .tables = &.{}, .sql_sources = resolved, .sql_sources_resolved = true };
        }
        if (request.name_allocation and request.relations.len != 0 and
            (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group_id)) == null)
            return self.resolveAllocationNamesTxn(alloc, &txn, group_id, meta.revision, request, context);
        // One root and one source cut for the whole batch. An unpublished or
        // stale registry cannot attest absence, even for a missing namespace.
        var live = if (request.relations.len != 0)
            (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(&txn, group_id)) orelse return error.CatalogPublicationProofPending
        else
            null;
        if (live) |value| if (!value.root.epoch.eql(try relationSourceEpochTxn(&txn, group_id))) return error.CatalogGenerationChanged;
        if (request.expected_relation_epoch) |expected| if (!live.?.root.epoch.eql(expected)) return error.CatalogGenerationChanged;
        const tables = try alloc.alloc(?system_catalog.ResolvedTable, request.targets.len);
        var initialized: usize = 0;
        errdefer {
            for (tables[0..initialized]) |table| if (table) |value| value.deinit(alloc);
            alloc.free(tables);
        }
        for (request.targets, tables) |target, *table| {
            table.* = try self.resolveSystemCatalogResultTxn(system_catalog.ResolvedTable, alloc, &txn, group_id, target);
            initialized += 1;
            if (request.include_query_definitions) if (table.*) |*identity| {
                identity.query_definition = try self.queryTableDefinitionTxn(alloc, &txn, group_id, identity.name);
            };
        }
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const view: system_catalog_storage.View = .{ .alloc = arena.allocator(), .txn = &txn, .group_id = group_id, .meta = meta };
        const relations = try alloc.alloc(?system_catalog.ResolvedRelation, request.relations.len);
        @memset(relations, null);
        errdefer {
            for (relations) |relation| if (relation) |value| value.deinit(alloc);
            alloc.free(relations);
        }
        for (request.relations, relations) |target, *slot| {
            const namespace_id = (try resolveSystemCatalogNamespaceTxn(alloc, &txn, group_id, target.database, target.namespace)) orelse continue;
            const owner = (try live.?.getClaim(.{ .namespace_id = namespace_id, .name = target.name })) orelse continue;
            var key_buf: [160]u8 = undefined;
            const bytes = txn.get(try tableKeyForGroup(&key_buf, group_id, owner.table_id)) catch |err| switch (err) {
                error.NotFound => return error.InvalidCatalogRecord,
                else => return err,
            };
            var table = try decodeTableIdentity(alloc, bytes);
            errdefer table.deinit(alloc);
            if (table.table_id != owner.table_id) return error.InvalidCatalogRecord;
            var binding = try system_catalog_storage.getById(alloc, &txn, group_id, .table, owner.table_id);
            defer if (binding) |*value| value.deinit();
            if (binding) |value| table.native_service = value.value.native_service;
            const logical_name = if (binding) |value| blk: {
                if (value.value.parent_id != namespace_id or !std.mem.eql(u8, value.value.storage_name, table.name)) return error.InvalidCatalogRecord;
                break :blk value.value.name;
            } else blk: {
                if (namespace_id != system_catalog.default_namespace_id) return error.InvalidCatalogRecord;
                break :blk table.name;
            };
            if (request.include_query_definitions) {
                table.query_definition = try self.queryTableDefinitionTxn(alloc, &txn, group_id, table.name);
                const definition = table.query_definition orelse return error.InvalidCatalogRecord;
                var digest: [32]u8 = undefined;
                std.crypto.hash.Blake3.hash(definition.schema_json, &digest, .{});
                if (!std.mem.eql(u8, &digest, &owner.schema_digest)) return error.InvalidCatalogRecord;
            }
            slot.* = .{ .owner = owner, .table = table, .logical_table = try alloc.dupe(u8, logical_name) };
        }
        return .{ .revision = meta.revision, .tables = tables, .logical_names = try system_catalog.logicalNamesAlloc(alloc, view, request.storage_names), .relation_epoch = if (live) |value| value.root.epoch else null, .relations = relations };
    }

    /// Name selection can precede registry adoption. Read the complete source
    /// cut through the same bounded cursor used by reconciliation, including
    /// hidden creates and restores. This attests occupancy only; schema/index
    /// admission still requires the published registry and its guarded owner.
    fn resolveAllocationNamesTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, revision: u64, request: system_catalog.ResolveMany, context: @import("antfly_local_sources").api_operation.RequestContext) !system_catalog.ResolvedMany {
        _ = self;
        if (request.include_query_definitions or request.targets.len != 0 or request.storage_names.len != 0) return error.InvalidCatalogMutation;
        var buf: [160]u8 = undefined;
        const identity = try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, group_id)));
        var incarnation: [16]u8 = undefined;
        _ = std.fmt.hexToBytes(&incarnation, &identity.incarnation) catch return error.InvalidMetadataIncarnation;
        // Source-cut revisions and published-registry revisions are distinct
        // authorities. A coincident numeric revision must not join those cuts.
        var epoch_hash = std.crypto.hash.Blake3.init(.{});
        epoch_hash.update("antfly.catalog-name-allocation.v1");
        epoch_hash.update(&incarnation);
        var epoch_digest: [32]u8 = undefined;
        epoch_hash.final(&epoch_digest);
        incarnation = epoch_digest[0..16].*;
        // The published catalog cursor excludes hidden restore reservations.
        // Every hosted source mutation commits with the group's applied index;
        // read that complete watermark from this same pinned source cut.
        const epoch: relation_reconciliation.Epoch = .{ .incarnation = incarnation, .revision = try durableAppliedIndexTxn(txn, group_id) };
        if (epoch.revision == 0) return error.CatalogPublicationProofPending;
        if (request.expected_relation_epoch) |expected| if (!epoch.eql(expected)) return error.CatalogGenerationChanged;
        const relations = try alloc.alloc(?system_catalog.ResolvedRelation, request.relations.len);
        @memset(relations, null);
        errdefer {
            for (relations) |relation| if (relation) |value| value.deinit(alloc);
            alloc.free(relations);
        }
        var namespaces: [256]?u64 = undefined;
        for (request.relations, 0..) |target, i| namespaces[i] = try resolveSystemCatalogNamespaceTxn(alloc, txn, group_id, target.database, target.namespace);
        var buffers: RelationSourceBuffers = undefined;
        // Allocation reserves relation names, not table-qualified constraint
        // memberships. Keep pending creates/restores in the same source cut.
        var source = try relationTableSource(alloc, txn, group_id, &buffers, .relations);
        defer source.deinit();
        var cursor_buf: [relation_reconciliation.max_cursor_bytes]u8 = undefined;
        var cursor: []const u8 = "";
        while (true) {
            try context.ensureActive();
            const row = (try source.nextAfter(cursor)) orelse break;
            for (row.claims) |claim| {
                try context.ensureActive();
                for (request.relations, relations, namespaces[0..request.relations.len]) |target, *slot, namespace| {
                    if (namespace == null or namespace.? != claim.key.namespace_id or !std.mem.eql(u8, target.name, claim.key.name)) continue;
                    // Reserved names must not become a negative answer or an
                    // invented active owner while their publication is pending.
                    if (claim.owner.phase != .active) return error.CatalogPublicationProofPending;
                    if (slot.*) |prior| {
                        if (!prior.owner.eql(claim.owner)) return error.InvalidCatalogRecord;
                        continue;
                    }
                    const table_bytes = txn.get(try tableKeyForGroup(&buf, group_id, claim.owner.table_id)) catch |err| switch (err) {
                        error.NotFound => return error.CatalogPublicationProofPending,
                        else => return err,
                    };
                    var table = try decodeTableIdentity(alloc, table_bytes);
                    errdefer table.deinit(alloc);
                    var binding = try system_catalog_storage.getById(alloc, txn, group_id, .table, table.table_id);
                    defer if (binding) |*value| value.deinit();
                    if (binding) |value| table.native_service = value.value.native_service;
                    const logical_name = if (binding) |value| value.value.name else table.name;
                    slot.* = .{ .owner = claim.owner, .table = table, .logical_table = try alloc.dupe(u8, logical_name) };
                }
            }
            if (row.key.len > cursor_buf.len) return error.InvalidCatalogRecord;
            @memcpy(cursor_buf[0..row.key.len], row.key);
            cursor = cursor_buf[0..row.key.len];
        }
        try context.ensureActive();
        const tables = try alloc.alloc(?system_catalog.ResolvedTable, 0);
        return .{ .revision = revision, .tables = tables, .relations = relations, .relation_epoch = epoch, .relation_names_only = true };
    }

    pub fn writeValidationRevision(self: *RaftApplyStore, group_id: u64) !u64 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var buf: [160]u8 = undefined;
        const bytes = txn.get(try catalogRevisionKeyForGroup(&buf, group_id)) catch |err| switch (err) {
            error.NotFound => return 0,
            else => return err,
        };
        if (bytes.len != 8) return error.InvalidCatalogRecord;
        return std.mem.readInt(u64, bytes[0..8], .little);
    }

    pub fn tableWriteValidation(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, name: []const u8) ![]u8 {
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        const identity = (try self.getTableByNameResultTxn(system_catalog.ResolvedTable, a, &txn, group_id, name)) orelse return error.TableNotFound;
        var table_key_buf: [160]u8 = undefined;
        const table_bytes = try txn.get(try tableKeyForGroup(&table_key_buf, group_id, identity.table_id));
        const definition = (try decodeTableProjection(a, table_bytes, .schema)).query_definition.?;
        var shapes: std.ArrayList([]const u8) = .empty;
        var prefix_buf: [1024]u8 = undefined;
        const prefix = try extensionTableOwnerIndexPrefixForTable(&prefix_buf, group_id, name);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        while (row) |entry| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            const member = try decodeExtensionMemberRecord(a, try txn.get(entry.value));
            if (member.object_kind != .data_shape) continue;
            const kind = member.shape_kind orelse continue;
            if (kind == .document or kind == .row) try shapes.append(a, member.owner_metadata_json);
        }
        return std.json.Stringify.valueAlloc(alloc, @import("../../system_catalog/projection.zig").WriteValidation{
            .schema_json = definition.schema_json,
            .data_shapes = shapes.items,
        }, .{});
    }

    pub fn queryTableDefinition(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, name: []const u8) !?system_catalog.QueryDefinition {
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        return self.queryTableDefinitionTxn(alloc, &txn, group_id, name);
    }

    fn queryTableDefinitionTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, name: []const u8) !?system_catalog.QueryDefinition {
        const identity = (try self.getTableByNameResultTxn(system_catalog.ResolvedTable, alloc, txn, group_id, name)) orelse return null;
        defer identity.deinit(alloc);
        var key_buf: [160]u8 = undefined;
        const bytes = try txn.get(try tableKeyForGroup(&key_buf, group_id, identity.table_id));
        const projection = try decodeTableQueryProjection(alloc, bytes, true);
        defer alloc.free(projection.name);
        var definition = projection.query_definition;
        if (definition) |*value| {
            var projection_arena = std.heap.ArenaAllocator.init(alloc);
            defer projection_arena.deinit();
            var projections: ResolverProjectionCache = .empty;
            const indexes = try self.resolverExecutionIndexesTxn(projection_arena.allocator(), txn, group_id, value.indexes_json, &projections);
            const owned_indexes = try alloc.dupe(u8, indexes);
            alloc.free(value.indexes_json);
            value.indexes_json = owned_indexes;
            var binding = try system_catalog_storage.getById(alloc, txn, group_id, .table, identity.table_id);
            defer if (binding) |*owned| owned.deinit();
            if (binding) |owned| value.native_service = owned.value.native_service;
        }
        return definition;
    }

    fn resolveSystemCatalogNamespaceTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, database_name: []const u8, namespace_name: []const u8) !?u64 {
        var database = try system_catalog_storage.find(alloc, txn, group_id, .database, 0, database_name);
        defer if (database) |*parsed| parsed.deinit();
        const database_id = if (database) |parsed| parsed.value.id else if (std.mem.eql(u8, database_name, system_catalog.default_database_name)) system_catalog.default_database_id else return null;
        var namespace = try system_catalog_storage.find(alloc, txn, group_id, .namespace, database_id, namespace_name);
        defer if (namespace) |*parsed| parsed.deinit();
        return if (namespace) |parsed| parsed.value.id else if (database_id == system_catalog.default_database_id and std.mem.eql(u8, namespace_name, system_catalog.default_namespace_name)) system_catalog.default_namespace_id else null;
    }

    fn resolveSystemCatalogResultTxn(self: *RaftApplyStore, comptime Result: type, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, target: system_catalog.Target) !?Result {
        try target.validate();
        const namespace_id = (try resolveSystemCatalogNamespaceTxn(alloc, txn, group_id, target.database, target.namespace)) orelse return null;
        if (try system_catalog_storage.find(alloc, txn, group_id, .table, namespace_id, target.table)) |value| {
            var binding = value;
            defer binding.deinit();
            var key_buf: [160]u8 = undefined;
            const bytes = txn.get(try tableKeyForGroup(&key_buf, group_id, binding.value.id)) catch |err| switch (err) {
                error.NotFound => return error.InvalidCatalogRecord,
                else => return err,
            };
            var table: Result = if (Result == metadata.TableRecord) try decodeTableRecord(alloc, bytes) else try decodeTableIdentity(alloc, bytes);
            if (Result == system_catalog.ResolvedTable) table.native_service = binding.value.native_service;
            if (table.table_id != binding.value.id or !std.mem.eql(u8, table.name, binding.value.storage_name)) {
                if (Result == metadata.TableRecord) metadata_table_manager.freeTable(alloc, table) else table.deinit(alloc);
                return error.InvalidCatalogRecord;
            }
            return table;
        }
        if (namespace_id != system_catalog.default_namespace_id) return null;
        // Existing default.public tables retain their original routing name.
        const table = (try self.getTableByNameResultTxn(Result, alloc, txn, group_id, target.table)) orelse return null;
        if (try system_catalog_storage.getById(alloc, txn, group_id, .table, table.table_id)) |value| {
            var binding = value;
            binding.deinit();
            if (Result == metadata.TableRecord) metadata_table_manager.freeTable(alloc, table) else table.deinit(alloc);
            return null;
        }
        return table;
    }

    fn applySystemCatalogTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
        var parsed = try std.json.parseFromSlice(SystemCatalogCommand, self.alloc, bytes, .{});
        defer parsed.deinit();
        const command = parsed.value;
        if (command.sql_sequence != null) {
            self.applySqlSequenceOutcomeTxn(txn, group_id, command) catch |err| switch (err) {
                error.CatalogGenerationChanged, error.TableTopologyProtocolUpgradeRequired, error.SequenceAdmissionExpired, error.SequenceAdmissionConflict, error.CatalogRevisionExhausted => return,
                else => return err,
            };
            return;
        }
        if (command.version != 1 and command.version != 2 and command.version != 3) return error.InvalidCatalogMutation;
        if (command.column_sequences.len != 0 and (command.sql_sequence != null or command.sql_view != null)) return error.InvalidCatalogMutation;
        if (command.mutation.action == .comment) {
            _ = self.requireTopologyActivationTxn(txn, group_id, topology_protocol.sql_resource_comments_version) catch |err| switch (err) {
                error.TableTopologyProtocolUpgradeRequired => return,
                else => return err,
            };
        }
        if (command.sql_view != null) {
            _ = self.applySqlViewLifecycleTxn(txn, group_id, command, true) catch |err| switch (err) {
                error.CatalogGenerationChanged, error.CatalogAlreadyExists, error.CatalogNotFound, error.SqlDependentObjectsExist, error.SqlViewColumnRename, error.SqlViewColumnTypeChanged, error.SqlViewColumnDropped, error.TableTopologyProtocolUpgradeRequired, error.CatalogOccupancyNotReady, error.CatalogPublicationProofPending, error.SqlViewCycle, error.SqlProgramLimitExceeded, error.TableTransitionActive => return,
                else => return err,
            };
            return;
        }
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, txn, group_id);
        if (meta.revision != command.expected_revision) return;
        self.validateGeneratedConstraintNamesTxn(a, txn, group_id, command, meta) catch |err| switch (err) {
            error.CatalogGenerationChanged, error.CatalogOccupancyNotReady, error.TableTopologyProtocolUpgradeRequired => return,
            else => return err, // Storage/corruption failures must abort.
        };
        if (command.mutation.kind == .table and command.mutation.action == .create) {
            const namespace = if (std.mem.eql(u8, command.mutation.namespace, system_catalog.default_namespace_name) and
                std.mem.eql(u8, command.mutation.database, system_catalog.default_database_name))
                system_catalog.default_namespace
            else blk: {
                const database = (try system_catalog_storage.find(a, txn, group_id, .database, 0, command.mutation.database)) orelse return;
                const ns = (try system_catalog_storage.find(a, txn, group_id, .namespace, database.value.id, command.mutation.namespace)) orelse return;
                break :blk ns.value;
            };
            var reservation_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
            if (try stagingGet(txn, try fk_generation_publication.initialNameKey(&reservation_buf, group_id, namespace.id, command.mutation.name)) != null or
                try stagingGet(txn, try fk_generation_publication.initialPhysicalNameKey(&reservation_buf, group_id, command.mutation.storage_name)) != null)
                return;
        }
        const reader: CatalogReader = .{ .store = self, .view = .{ .alloc = a, .txn = txn, .group_id = group_id, .meta = meta } };
        validateCatalogTopology(command) catch return;
        validateSqlDropNameMutation(reader, command) catch |err| switch (err) {
            error.TableTransitionActive => return,
            else => return err,
        };
        var delta = system_catalog.planWithTopology(a, reader, meta.next_id, command.mutation, command.mutation.kind == .table and command.mutation.action == .drop) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return, // A concurrent catalog/topology operation defeated admission.
        };
        defer delta.deinit(a);
        const column_sequence_plan = if (command.column_sequences.len != 0) self.prepareTableColumnSequencesTxn(a, txn, group_id, command, meta, delta.next_id, false) catch |err| switch (err) {
            error.InvalidCatalogMutation, error.InvalidSequenceDefinition, error.CatalogGenerationChanged, error.TableTopologyProtocolUpgradeRequired, error.CatalogPublicationProofPending, error.CatalogOccupancyNotReady, error.CatalogSourceUntracked, error.UndefinedColumn, error.ProgramLimitExceeded => return,
            else => return err,
        } else null;
        if (column_sequence_plan) |prepared| {
            if (!std.mem.eql(u8, command.topology.?.create.table.schema_json, prepared.schema_json)) return;
            try expandTableColumnSequenceDelta(a, &delta, prepared);
        }
        validateCatalogPlacement(reader, command, delta) catch |err| switch (err) {
            error.InvalidCatalogMutation => return,
            else => return err, // Storage/corruption failures must abort.
        };
        if (command.placement_update) |update| {
            if (command.mutation.kind != .table or command.mutation.action != .set_tablespace or update.expected.table_id != update.replacement.table_id or !std.mem.eql(u8, update.expected.name, update.replacement.name)) return;
            if ((try self.loadTableTransitionFenceTxn(txn, group_id, update.expected.table_id)).active()) return;
            const current = (try self.getTableByNameTxn(self.alloc, txn, group_id, update.expected.name)) orelse return;
            defer metadata_table_manager.freeTable(self.alloc, current);
            if (!metadata_table_manager.tableDefinitionsEqual(current, update.expected)) return;
            if (!try self.tryApplyTableCompareAndReplaceTxn(txn, group_id, update.expected, update.replacement)) return;
        }
        if (command.topology) |topology| {
            try self.applyTableTopologyMutationTxn(txn, group_id, topology);
            var key_buf: [160]u8 = undefined;
            const encoded = txn.get(try tableKeyForGroup(&key_buf, group_id, command.mutation.table_id)) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            switch (topology) {
                .create => |create| {
                    const table = try decodeTableRecord(self.alloc, encoded orelse return);
                    defer metadata_table_manager.freeTable(self.alloc, table);
                    const admitted = (try self.admittedResolverProjectionTxn(a, txn, group_id, create.table)) orelse return;
                    if (!metadata_table_manager.tableDefinitionsEqual(table, admitted)) return;
                },
                .drop => if (encoded != null) return,
            }
        }
        if (column_sequence_plan) |prepared|
            try self.initializeTableColumnSequencesTxn(a, txn, group_id, command.topology.?.create.table, prepared);
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
        var published_meta = meta;
        // Table-owned sequence creation is one catalog transaction, with no
        // independent sequence-DDL receipt. Durably activate the empty journal
        // so backup/restore can distinguish it from a missing journal header.
        if (column_sequence_plan != null and published_meta.sequence_outcome_head == null) published_meta.sequence_outcome_head = 0;
        try self.applySystemCatalogDeltaTxn(self.alloc, txn, group_id, delta, published_meta, hash);
        // Invalidate metadata readers through the existing catalog event path.
        self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id });
    }

    fn applySystemCatalogDeltaTxn(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        delta: system_catalog.Delta,
        meta: system_catalog_storage.Meta,
        hash: [32]u8,
    ) !void {
        try system_catalog_storage.applyDelta(alloc, txn, group_id, delta, meta, hash);
        if (delta.presentation_only) return;
        // The installed physical relation root covers tables/indexes. Logical
        // views/sequences use indexed namespace ownership, not fake tables.
        const logical_only = for (delta.upserts) |resource| {
            if (resource.kind != .view and resource.kind != .sequence) break false;
        } else for (delta.removes) |resource| {
            if (resource.kind != .view and resource.kind != .sequence) break false;
        } else delta.upserts.len + delta.removes.len != 0;
        if (!logical_only) try relation_reconciliation.advanceTrackedSource(txn, group_id);
        // Physical rows can be installed before their binding (initial FK
        // publication) or afterward (restore). Bindings and the legacy-only
        // listing must always become visible in the same transaction.
        for (delta.upserts) |resource| if (resource.kind == .table)
            try self.deleteLegacyListingTxn(txn, group_id, resource.storage_name);
    }

    fn removeSystemCatalogTableTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !void {
        if (try system_catalog_storage.getById(self.alloc, txn, group_id, .table, table_id)) |value| {
            var binding = value;
            defer binding.deinit();
            const previous = try system_catalog_storage.readMeta(self.alloc, txn, group_id);
            var removes = [_]system_catalog.Resource{binding.value};
            try self.applySystemCatalogDeltaTxn(self.alloc, txn, group_id, .{ .upserts = &.{}, .removes = &removes, .next_id = previous.next_id }, previous, @splat(0));
        }
    }

    pub fn listTables(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]metadata.TableRecord {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        return try self.listTablesTxn(alloc, &txn, group_id);
    }

    /// The cursor lends record bytes; only identities survive each cursor step.
    /// Catalog DDL must not copy every table's schema into the apply arena.
    fn listPhysicalTableIdentities(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64) ![]system_catalog.PhysicalTable {
        var prefix_buf: [128]u8 = undefined;
        const prefix = try tablePrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var records = std.ArrayListUnmanaged(system_catalog.PhysicalTable).empty;
        errdefer {
            for (records.items) |record| alloc.free(record.name);
            records.deinit(alloc);
        }
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |kv| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            const identity = try decodeTableIdentity(alloc, kv.value);
            errdefer identity.deinit(alloc);
            var key_buf: [160]u8 = undefined;
            if (!std.mem.eql(u8, kv.key, try tableKeyForGroup(&key_buf, group_id, identity.table_id))) return error.InvalidMetadataRecord;
            try records.append(alloc, .{ .id = identity.table_id, .name = identity.name });
        }
        return records.toOwnedSlice(alloc);
    }

    fn freePhysicalTableIdentities(alloc: std.mem.Allocator, records: []system_catalog.PhysicalTable) void {
        for (records) |record| alloc.free(record.name);
        alloc.free(records);
    }

    fn listTablesTxn(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
    ) ![]metadata.TableRecord {
        return try self.listTablesTxnUntil(alloc, txn, group_id, null, null);
    }

    fn listTablesTxnUntil(
        _: *RaftApplyStore,
        alloc: std.mem.Allocator,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        deadline_ns: ?u64,
        deadline_io: ?@import("antfly_runtime_abi").io_abi.Borrow,
    ) ![]metadata.TableRecord {
        try catalogProjectionDeadline(deadline_ns, deadline_io);
        var prefix_buf: [128]u8 = undefined;
        const prefix = try tablePrefixForGroup(&prefix_buf, group_id);
        const kvs = try docstore.DocStore.scanPrefixTxn(alloc, txn, prefix);
        defer freeKvs(alloc, kvs);
        try catalogProjectionDeadline(deadline_ns, deadline_io);
        const out = try alloc.alloc(metadata.TableRecord, kvs.len);
        var filled: usize = 0;
        errdefer {
            for (out[0..filled]) |record| {
                metadata_table_manager.freeTable(alloc, record);
            }
            alloc.free(out);
        }
        for (kvs, 0..) |kv, i| {
            if (i % 64 == 0) try catalogProjectionDeadline(deadline_ns, deadline_io);
            out[i] = try decodeTableRecord(alloc, kv.value);
            filled = i + 1;
        }
        try catalogProjectionDeadline(deadline_ns, deadline_io);
        return out;
    }

    pub const InspectionCatalog = struct {
        tables: []metadata.TableRecord,
        ranges: []metadata.RangeRecord,
    };

    /// Offline inspection uses the normal record codecs, but bounds the whole
    /// projection before copying/decoding each row. Never load an unbounded
    /// catalog and only then discover that its inspection budget was exceeded.
    pub fn captureInspectionCatalog(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, max_records: usize, max_bytes: usize, cancellation: @import("antfly_cancellation").CancellationToken) !InspectionCatalog {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var bytes_left = max_bytes;
        var table_buf: [128]u8 = undefined;
        const tables = try inspectionRows(metadata.TableRecord, alloc, &txn, try tablePrefixForGroup(&table_buf, group_id), max_records, &bytes_left, cancellation, decodeTableRecord, metadata_table_manager.freeTable);
        errdefer self.freeTables(alloc, tables);
        var range_buf: [128]u8 = undefined;
        const ranges = try inspectionRows(metadata.RangeRecord, alloc, &txn, try rangePrefixForGroup(&range_buf, group_id), max_records, &bytes_left, cancellation, decodeRangeRecord, metadata_table_manager.freeRange);
        errdefer self.freeRanges(alloc, ranges);
        // Private FK owners have no public table/range projection yet. Until
        // their source generations can be inventoried, do not certify them.
        var private_buf: [160]u8 = undefined;
        const private_prefix = try fk_generation_publication.initialPrefixForGroup(&private_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        if (try cursor.seekAtOrAfter(private_prefix)) |kv| {
            if (std.mem.startsWith(u8, kv.key, private_prefix)) return error.UnsupportedLiteInspectionLayout;
        }
        return .{ .tables = tables, .ranges = ranges };
    }

    fn inspectionRows(comptime Row: type, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, prefix: []const u8, max_records: usize, bytes_left: *usize, cancellation: @import("antfly_cancellation").CancellationToken, comptime decode: anytype, comptime free: anytype) ![]Row {
        var rows: std.ArrayList(Row) = .empty;
        errdefer {
            for (rows.items) |row| free(alloc, row);
            rows.deinit(alloc);
        }
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |kv| : (entry = try cursor.next()) {
            try cancellation.check();
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            if (rows.items.len >= max_records or kv.value.len > bytes_left.*) return error.PreflightLimitExceeded;
            bytes_left.* -= kv.value.len;
            const row = try decode(alloc, kv.value);
            errdefer free(alloc, row);
            try rows.append(alloc, row);
        }
        return rows.toOwnedSlice(alloc);
    }

    /// Capture the table and range namespaces from one committed storage
    /// revision without acquiring either the apply or outer Raft runtime lock.
    pub fn captureCatalogProjection(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        group_id: u64,
        deadline_ns: ?u64,
    ) !CatalogProjectionSnapshot {
        return self.captureCatalogProjectionWithClock(alloc, group_id, deadline_ns, null);
    }

    pub fn captureCatalogProjectionWithClock(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        group_id: u64,
        deadline_ns: ?u64,
        deadline_io: ?@import("antfly_runtime_abi").io_abi.Borrow,
    ) !CatalogProjectionSnapshot {
        try catalogProjectionDeadline(deadline_ns, deadline_io);
        var txn = try self.store.beginReadTxn();
        defer txn.abort();

        var revision_key_buf: [160]u8 = undefined;
        const revision_key = try catalogRevisionKeyForGroup(&revision_key_buf, group_id);
        const applied = txn.get(revision_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const catalog_revision = if (applied) |encoded| blk: {
            if (encoded.len < @sizeOf(u64)) return error.InvalidMetadataApplyBatch;
            break :blk std.mem.readInt(u64, encoded[0..8], .little);
        } else 0;

        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_key = try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id);
        const incarnation_encoded = txn.get(incarnation_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const incarnation = if (incarnation_encoded) |encoded|
            (try decodeMetadataIncarnationRecord(encoded)).incarnation
        else
            null;

        const tables = try self.listTablesTxnUntil(alloc, &txn, group_id, deadline_ns, deadline_io);
        errdefer self.freeTables(alloc, tables);
        try catalogProjectionDeadline(deadline_ns, deadline_io);
        const ranges = try self.listRangesTxnUntil(alloc, &txn, group_id, deadline_ns, deadline_io);
        errdefer self.freeRanges(alloc, ranges);
        try catalogProjectionDeadline(deadline_ns, deadline_io);
        return .{
            .metadata_incarnation = incarnation,
            .catalog_revision = catalog_revision,
            .tables = tables,
            .ranges = ranges,
        };
    }

    /// Read the durable authority and applied revision from one storage
    /// transaction. Unlike listener epochs, this cursor survives restarts and
    /// is comparable across replicas of the same metadata group.
    pub fn captureCatalogCursor(self: *RaftApplyStore, group_id: u64) !CatalogCursor {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();

        var revision_key_buf: [160]u8 = undefined;
        const revision_key = try catalogRevisionKeyForGroup(&revision_key_buf, group_id);
        const applied = txn.get(revision_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const revision = if (applied) |encoded| blk: {
            if (encoded.len < @sizeOf(u64)) return error.InvalidMetadataApplyBatch;
            break :blk std.mem.readInt(u64, encoded[0..8], .little);
        } else 0;

        var incarnation_key_buf: [160]u8 = undefined;
        const incarnation_key = try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id);
        const encoded_incarnation = txn.get(incarnation_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        return .{
            .metadata_incarnation = if (encoded_incarnation) |encoded|
                (try decodeMetadataIncarnationRecord(encoded)).incarnation
            else
                null,
            .revision = revision,
        };
    }

    pub fn freeTables(_: *RaftApplyStore, alloc: std.mem.Allocator, records: []metadata.TableRecord) void {
        for (records) |record| {
            metadata_table_manager.freeTable(alloc, record);
        }
        alloc.free(records);
    }

    pub fn getTable(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_id: u64,
    ) !?metadata.TableRecord {
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, table_id);
        const encoded = self.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(encoded);
        return try decodeTableRecord(alloc, encoded);
    }

    pub fn getLakeIndexLifecycle(self: *RaftApplyStore, a: std.mem.Allocator, group_id: u64, table_id: u64) ![]u8 {
        var buffer: [160]u8 = undefined;
        return self.store.get(a, try lakeIndexLifecycleKeyForGroup(&buffer, group_id, table_id)) catch |err| switch (err) {
            error.NotFound => blk: {
                const table = (try self.getTable(a, group_id, table_id)) orelse return error.TableNotFound;
                defer metadata_table_manager.freeTable(a, table);
                var arena = std.heap.ArenaAllocator.init(a);
                defer arena.deinit();
                var catalog_state = try @import("antfly_local_sources").metadata_lake_index_catalog.parse(arena.allocator(), table.lake_index_catalog_json);
                defer catalog_state.deinit();
                const state = try (@import("../lake_index_lifecycle.zig").State{}).synchronize(arena.allocator(), catalog_state.value);
                break :blk try @import("../lake_index_lifecycle.zig").encode(a, state);
            },
            else => return err,
        };
    }
    /// Independent retained rows include DROP tombstones. A single bounded
    /// point-sized page avoids cloning the visible table inventory or losing
    /// collection obligations when their logical table has disappeared.
    pub fn lakeIndexLifecycleWork(self: *RaftApplyStore, a: std.mem.Allocator, group_id: u64, after: ?u64) ![]u8 {
        const lifecycle = @import("../lake_index_lifecycle.zig");
        var prefix_buffer: [160]u8 = undefined;
        const prefix = try lakeIndexLifecyclePrefixForGroup(&prefix_buffer, group_id);
        var after_buffer: [160]u8 = undefined;
        const rows = try self.store.scanPrefixPage(a, prefix, if (after) |id| try lakeIndexLifecycleKeyForGroup(&after_buffer, group_id, id) else null, 1);
        defer docstore.DocStore.freeResults(a, rows);
        if (rows.len == 0) return std.json.Stringify.valueAlloc(a, lifecycle.WorkPage{}, .{});
        const id = std.fmt.parseInt(u64, rows[0].key[prefix.len..], 10) catch return error.InvalidLakeIndexLifecycle;
        var arena = std.heap.ArenaAllocator.init(a);
        defer arena.deinit();
        const state = try lifecycle.parse(arena.allocator(), rows[0].value);
        return std.json.Stringify.valueAlloc(a, lifecycle.WorkPage{ .item = .{ .table_id = id, .state = state }, .after = id }, .{});
    }
    fn loadLakeIndexLifecycleTxn(_: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !@import("../lake_index_lifecycle.zig").State {
        var buffer: [160]u8 = undefined;
        const bytes = try stagingGet(txn, try lakeIndexLifecycleKeyForGroup(&buffer, group_id, table_id));
        if (bytes) |encoded| return @import("../lake_index_lifecycle.zig").parse(a, encoded);
        var table_buffer: [160]u8 = undefined;
        const table_bytes = (try stagingGet(txn, try tableKeyForGroup(&table_buffer, group_id, table_id))) orelse return error.TableNotFound;
        const table = try decodeTableRecord(a, table_bytes);
        var catalog_state = try @import("antfly_local_sources").metadata_lake_index_catalog.parse(a, table.lake_index_catalog_json);
        defer catalog_state.deinit();
        return (@import("../lake_index_lifecycle.zig").State{}).synchronize(a, catalog_state.value);
    }
    fn putLakeIndexLifecycleTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64, state: @import("../lake_index_lifecycle.zig").State) !void {
        var buffer: [160]u8 = undefined;
        const bytes = try @import("../lake_index_lifecycle.zig").encode(self.alloc, state);
        defer self.alloc.free(bytes);
        try txn.put(try lakeIndexLifecycleKeyForGroup(&buffer, group_id, table_id), bytes);
    }
    fn prepareLakeIndexLifecycleTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table: metadata.TableRecord) !?[]u8 {
        // Legacy/native tables without lake state don't create maintenance rows.
        var buffer: [160]u8 = undefined;
        const prior = try stagingGet(txn, try lakeIndexLifecycleKeyForGroup(&buffer, group_id, table.table_id));
        if (prior == null and table.lake_index_catalog_json.len == 0) return null;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const state = if (prior) |bytes| try @import("../lake_index_lifecycle.zig").parse(a, bytes) else @import("../lake_index_lifecycle.zig").State{};
        var catalog_state = try @import("antfly_local_sources").metadata_lake_index_catalog.parse(a, table.lake_index_catalog_json);
        defer catalog_state.deinit();
        return try @import("../lake_index_lifecycle.zig").encode(self.alloc, try state.synchronize(a, catalog_state.value));
    }
    fn dropLakeIndexLifecycleTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table: metadata.TableRecord) !void {
        var buffer: [160]u8 = undefined;
        const prior = try stagingGet(txn, try lakeIndexLifecycleKeyForGroup(&buffer, group_id, table.table_id));
        if (prior == null and table.lake_index_catalog_json.len == 0) return;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const state = try self.loadLakeIndexLifecycleTxn(arena.allocator(), txn, group_id, table.table_id);
        try self.putLakeIndexLifecycleTxn(txn, group_id, table.table_id, try state.drop());
    }
    fn applyLakeIndexLifecycleTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64, revision: u64, mutation: @import("../lake_index_lifecycle.zig").Mutation) !void {
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const state = self.loadLakeIndexLifecycleTxn(a, txn, group_id, table_id) catch |err| switch (err) {
            error.TableNotFound => return,
            else => return err,
        };
        if (state.revision != revision) return;
        const next = mutation.apply(a, state) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return,
        };
        const bounded = @import("../lake_index_lifecycle.zig").encode(a, next) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return,
        };
        _ = bounded;
        try self.putLakeIndexLifecycleTxn(txn, group_id, table_id, next);
    }

