    const RelationSourceCut = struct {
        revision: u64 = 0,
        rows: u64 = 0,
        fingerprint: u256 = 0,
        fn feed(self: *@This(), a: std.mem.Allocator, group: u64, key: []const u8, value: []const u8) !void {
            if (!try relationSourceKey(group, key)) return;
            // The default namespace/database exist logically before their
            // first durable catalog write. Materializing those exact defaults
            // is not a physical source change. Non-default options still hash
            // normally and remain protected by the equal-clock comparison.
            var prefix_buf: [160]u8 = undefined;
            const prefix = try system_catalog_storage.prefixForGroup(&prefix_buf, group);
            if (std.mem.startsWith(u8, key, prefix)) {
                const tail = key[prefix.len..];
                const implicit: ?system_catalog.Resource = if (std.mem.eql(u8, tail, "record:database:1"))
                    system_catalog.default_database
                else if (std.mem.eql(u8, tail, "record:namespace:2"))
                    system_catalog.default_namespace
                else
                    null;
                if (implicit) |resource| {
                    const canonical = try std.json.Stringify.valueAlloc(a, resource, .{});
                    defer a.free(canonical);
                    if (std.mem.eql(u8, canonical, value)) return;
                }
            }
            var hash = std.crypto.hash.Blake3.init(.{});
            hash.update("antfly.relation-source-cut.v2");
            const value_digest = try relationSourceValueDigest(a, group, key, value);
            var lengths: [16]u8 = undefined;
            std.mem.writeInt(u64, lengths[0..8], @intCast(key.len), .big);
            std.mem.writeInt(u64, lengths[8..16], value_digest.len, .big);
            hash.update(&lengths);
            hash.update(key);
            hash.update(&value_digest);
            var digest: [32]u8 = undefined;
            hash.final(&digest);
            // Commutative addition, not XOR: duplicate entries cannot cancel.
            self.fingerprint +%= std.mem.readInt(u256, &digest, .little);
            self.rows = std.math.add(u64, self.rows, 1) catch return error.InvalidMetadataSnapshot;
        }
        fn eql(self: @This(), other: @This()) bool {
            return self.rows == other.rows and self.fingerprint == other.fingerprint;
        }
    };
    /// Shared by writers, replay and equal-clock snapshots. Placement,
    /// descriptions, read layouts and runtime progress are not namespace input.
    fn relationTableSourceDigest(id: u64, name: []const u8, schema: []const u8) [32]u8 {
        var hash = std.crypto.hash.Blake3.init(.{});
        hash.update("antfly.relation-table-source.v1");
        var header: [24]u8 = undefined;
        std.mem.writeInt(u64, header[0..8], id, .big);
        std.mem.writeInt(u64, header[8..16], @intCast(name.len), .big);
        std.mem.writeInt(u64, header[16..24], @intCast(schema.len), .big);
        hash.update(&header);
        hash.update(name);
        hash.update(schema);
        var digest: [32]u8 = undefined;
        hash.final(&digest);
        return digest;
    }
    fn relationSourceValueDigest(a: std.mem.Allocator, group: u64, key: []const u8, bytes: []const u8) ![32]u8 {
        if (try index_publication.sourceKey(key, group)) |source| switch (source) {
            .plan => |id| {
                var parsed = try index_publication.Projection.decode(a, bytes, id);
                defer parsed.deinit();
                return parsed.value.sourceDigest();
            },
            .active => if (bytes.len != 16 or std.mem.allEqual(u8, bytes, 0)) return error.InvalidCatalogRecord,
        };
        if (try relationRestoreSourceKey(key, group)) |source| switch (source) {
            .job => |id| return relationRestoreSourceValueDigest(a, bytes, id),
            .active => |id| if (!std.mem.eql(u8, &id, bytes)) return error.InvalidCatalogRecord,
            .name, .table => if (bytes.len != 16 or std.mem.allEqual(u8, bytes, 0)) return error.InvalidCatalogRecord,
            .old_table => {
                if ((bytes.len != 16 and bytes.len != 24) or std.mem.allEqual(u8, bytes[0..16], 0)) return error.InvalidCatalogRecord;
                if (bytes.len == 24 and std.mem.readInt(u64, bytes[16..24], .little) == 0) return error.InvalidCatalogRecord;
            },
        };
        if (try system_catalog_storage.tableIdFromRecordKey(key, group)) |id| {
            // Logical bindings are JSON resources; physical table records use
            // the binary encoding below. Only namespace inputs belong to this
            // cut: placement, descriptions and service progress are independent.
            var parsed = try std.json.parseFromSlice(system_catalog.Resource, a, bytes, .{});
            defer parsed.deinit();
            const table = parsed.value;
            if (table.kind != .table or table.id != id or table.parent_id == 0 or table.storage_name.len == 0) return error.InvalidCatalogRecord;
            try system_catalog.validateResourceName(.table, table.name);
            const projection = try std.json.Stringify.valueAlloc(a, .{ .id = id, .parent_id = table.parent_id, .name = table.name, .storage_name = table.storage_name }, .{});
            defer a.free(projection);
