                var key_buf: [160]u8 = undefined;
                const key = try rangeKeyForGroup(&key_buf, group_id, record.group_id);
                if (existing == null) return;
                if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, existing_table_id)) return;
                try txn.delete(key);
                try self.deleteTableRangeIndexTxn(txn, group_id, existing_table_id, record.group_id);
                try self.deleteActiveRestoreRangeIndexTxn(txn, group_id, record.group_id);
                try self.advanceTableTransitionGenerationWithRangeChangesTxn(
                    txn,
                    group_id,
                    existing_table_id,
                    &.{},
                    &.{record.group_id},
                );
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .range,
                    .metadata_group_id = group_id,
                    .table_name = table_name,
                    .table_id = existing_table_id,
                    .group_id = record.group_id,
                });
            },
            .admit_split_transition => |admission| {
                try self.applySplitAdmissionTxn(txn, group_id, admission.expected_source_epoch, admission.record);
            },
            .upsert_split_transition => |record| {
                try self.applySplitTransitionUpsertTxn(txn, group_id, record);
            },
            .remove_split_transition => |record| {
                try self.applySplitTransitionRemovalTxn(txn, group_id, record.transition_id);
            },
            .upsert_merge_transition => |record| {
                try self.applyMergeTransitionUpsertTxn(txn, group_id, record);
            },
            .compare_and_set_online_merge => |update| try self.applyOnlineMergeUpdateTxn(txn, group_id, update),
            .admit_online_merge => |admission| try self.applyOnlineMergeAdmissionTxn(txn, group_id, admission),
            .remove_merge_transition => |record| {
                try self.applyMergeTransitionRemovalTxn(txn, group_id, record.transition_id);
            },
            .upsert_reconcile_lease => |record| {
                var key_buf: [160]u8 = undefined;
                const key = try reconcileLeaseKeyForGroup(&key_buf, group_id);
                const value = try encodeReconcileLeaseRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(key, value);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .reconcile_lease,
                    .metadata_group_id = group_id,
                });
            },
            .remove_reconcile_lease => {
                var key_buf: [160]u8 = undefined;
                const key = try reconcileLeaseKeyForGroup(&key_buf, group_id);
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .reconcile_lease,
                    .metadata_group_id = group_id,
                });
            },
            .upsert_shuffle_join_lease => |record| {
                var key_buf: [192]u8 = undefined;
                const key = try shuffleJoinLeaseKeyForGroup(&key_buf, group_id, record.job_id);
                const value = try encodeShuffleJoinLeaseRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(key, value);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .shuffle_join_lease,
                    .metadata_group_id = group_id,
                });
            },
            .remove_shuffle_join_lease => |record| {
                var key_buf: [192]u8 = undefined;
                const key = try shuffleJoinLeaseKeyForGroup(&key_buf, group_id, record.job_id);
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .shuffle_join_lease,
                    .metadata_group_id = group_id,
                });
            },
            .compare_and_set_backup_cohort => |record| {
                try self.applyBackupCohortTxn(txn, group_id, record);
            },
            .upsert_restore_job, .create_restore_job => |record| {
                var key_buf: [256]u8 = undefined;
                const key = try restoreJobKeyForGroup(&key_buf, group_id, record.key);
                if (command == .create_restore_job) {
                    const existing = txn.get(key) catch |err| switch (err) {
                        error.NotFound => null,
                        else => return err,
                    };
                    if (existing != null) return;
                }
                try txn.put(key, record.value);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .restore_job,
                    .metadata_group_id = group_id,
                });
            },
            .create_restore_job_with_staging => |record| try self.applyRestoreJobWithStagingTxn(txn, group_id, record),
            .remove_restore_job_if_matches => |record| {
                var key_buf: [256]u8 = undefined;
                const key = try restoreJobKeyForGroup(&key_buf, group_id, record.key);
                const existing = txn.get(key) catch |err| switch (err) {
                    error.NotFound => return,
                    else => return err,
                };
                var digest: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(existing, &digest, .{});
                if (!std.mem.eql(u8, &digest, record.value_hash)) return;
                try txn.delete(key);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{ .kind = .restore_job, .metadata_group_id = group_id });
            },
            .remove_restore_job => |record| {
                var key_buf: [256]u8 = undefined;
                const key = try restoreJobKeyForGroup(&key_buf, group_id, record.key);
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                self.notifyProjectionListeners(.{
                    .kind = .restore_job,
                    .metadata_group_id = group_id,
                });
            },
            .remove_restore_jobs => |record| {
                for (record.keys) |logical_key| {
                    var key_buf: [256]u8 = undefined;
                    const key = try restoreJobKeyForGroup(&key_buf, group_id, logical_key);
                    txn.delete(key) catch |err| switch (err) {
                        error.NotFound => {},
                        else => return err,
                    };
                    self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
                }
                self.notifyProjectionListeners(.{
                    .kind = .restore_job,
                    .metadata_group_id = group_id,
                });
            },
            .upsert_reallocation_request => |record| admit: {
                var active_key_buf: [160]u8 = undefined;
                const active_key = try reallocationRequestKeyForGroup(&active_key_buf, group_id);
                const active: ?[]const u8 = txn.get(active_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (active) |encoded| {
                    var pos: usize = 0;
                    const current = try readReallocationRequestRecord(encoded, &pos);
                    if (pos != encoded.len) return error.InvalidMetadataRecord;
                    // Reapplying the active command is idempotent and must not
                    // manufacture a successor generation.
                    if (current.request_id == record.request_id) break :admit;

                    // Keep the published generation stable while stores
                    // acknowledge it, but retain one durable rerun latch. A
                    // newer trigger may safely replace this private pending
                    // value because no store can observe it until promotion.
                    var pending_key_buf: [168]u8 = undefined;
                    const pending_key = try pendingReallocationRequestKeyForGroup(&pending_key_buf, group_id);
                    const value = try encodeReallocationRequestRecord(self.alloc, record);
                    defer self.alloc.free(value);
                    try txn.put(pending_key, value);
                    break :admit;
                }

                const value = try encodeReallocationRequestRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(active_key, value);
                // This key should only coexist with an active request. Remove
                // any orphan defensively when establishing a new generation.
                var pending_key_buf: [168]u8 = undefined;
                const pending_key = try pendingReallocationRequestKeyForGroup(&pending_key_buf, group_id);
                txn.delete(pending_key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = active_key });
            },
            .remove_reallocation_request => |expected| remove: {
                var active_key_buf: [160]u8 = undefined;
                const active_key = try reallocationRequestKeyForGroup(&active_key_buf, group_id);
                const encoded = txn.get(active_key) catch |err| switch (err) {
                    error.NotFound => break :remove,
                    else => return err,
                };
                var pos: usize = 0;
                const current = try readReallocationRequestRecord(encoded, &pos);
                if (pos != encoded.len) return error.InvalidMetadataRecord;
                if (current.request_id != expected.expected_request_id) break :remove;

                var pending_key_buf: [168]u8 = undefined;
                const pending_key = try pendingReallocationRequestKeyForGroup(&pending_key_buf, group_id);
                const pending_encoded: ?[]const u8 = txn.get(pending_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (pending_encoded) |pending_value| {
                    var pending_pos: usize = 0;
                    const pending = try readReallocationRequestRecord(pending_value, &pending_pos);
                    if (pending_pos != pending_value.len) return error.InvalidMetadataRecord;
                    const promoted_value = try encodeReallocationRequestRecord(self.alloc, pending);
                    defer self.alloc.free(promoted_value);
                    try txn.put(active_key, promoted_value);
                    try txn.delete(pending_key);
                } else {
                    txn.delete(active_key) catch |err| switch (err) {
                        error.NotFound => {},
                        else => return err,
                    };
                }
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = active_key });
            },
            .upsert_extension_package => |record| {
                var key_buf: [256]u8 = undefined;
                const key = try extensionPackageKeyForGroup(&key_buf, group_id, record.name, record.version);
                const value = try encodeExtensionPackageRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(key, value);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .remove_extension_package => |record| {
                var key_buf: [256]u8 = undefined;
                const key = try extensionPackageKeyForGroup(&key_buf, group_id, record.name, record.version);
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .upsert_installed_extension => |record| {
                var key_buf: [192]u8 = undefined;
                const key = try installedExtensionKeyForGroup(&key_buf, group_id, record.name);
                const value = try encodeInstalledExtensionRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(key, value);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .remove_installed_extension => |record| {
                var key_buf: [192]u8 = undefined;
                const key = try installedExtensionKeyForGroup(&key_buf, group_id, record.name);
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .upsert_extension_member => |record| {
                if (!try self.extensionOwnershipAdditionAllowedTxn(txn, group_id, record)) return;
                var key_buf: [256]u8 = undefined;
                const key = try extensionMemberKeyForGroup(&key_buf, group_id, record.extension_name, record.object_kind, record.object_name);
                const encoded_existing = txn.get(key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (encoded_existing) |encoded| {
                    var existing = try decodeExtensionMemberRecord(self.alloc, encoded);
                    defer existing.deinitOwned(self.alloc);
                    try self.deleteExtensionTableOwnerIndexTxn(txn, group_id, existing);
                }
                const value = try encodeExtensionMemberRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(key, value);
                try self.putExtensionTableOwnerIndexTxn(txn, group_id, record);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .remove_extension_member => |record| {
                var key_buf: [256]u8 = undefined;
                const key = try extensionMemberKeyForGroup(&key_buf, group_id, record.extension_name, record.object_kind, record.object_name);
                const encoded_existing = txn.get(key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (encoded_existing) |encoded| {
                    var existing = try decodeExtensionMemberRecord(self.alloc, encoded);
                    defer existing.deinitOwned(self.alloc);
                    try self.deleteExtensionTableOwnerIndexTxn(txn, group_id, existing);
                }
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .upsert_extension_dependency => |record| {
                var key_buf: [320]u8 = undefined;
                const key = try extensionDependencyKeyForGroup(&key_buf, group_id, record.extension_name, record.required_extension_name, record.package_name);
                const value = try encodeExtensionDependencyRecord(self.alloc, record);
                defer self.alloc.free(value);
                try txn.put(key, value);
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .remove_extension_dependency => |record| {
                var key_buf: [320]u8 = undefined;
                const key = try extensionDependencyKeyForGroup(&key_buf, group_id, record.extension_name, record.required_extension_name, record.package_name);
                txn.delete(key) catch |err| switch (err) {
                    error.NotFound => {},
                    else => return err,
                };
                self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            },
            .apply_extension_lifecycle, .apply_extension_lifecycle_v2 => |delta| {
                try self.applyExtensionLifecycleDeltaTxn(txn, group_id, delta);
            },
        }
    }

    /// Admission and mutation share the caller's transaction. In particular,
    /// rejection must precede logical unbinding: Raft commits rejected commands
    /// as no-ops, while standalone aborts and exposes the precise policy error.
    fn removeTableTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64, expected_generation: u64) !void {
        if (try self.fkGenerationTableLockedTxn(txn, group_id, table_id)) return error.TableTransitionActive;
        const fence = try self.loadTableTransitionFenceTxn(txn, group_id, table_id);
        if (fence.active()) return error.TableTransitionActive;
        if (fence.generation != expected_generation) return error.TableGenerationChanged;
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, table_id);
        if (try stagingGet(txn, key)) |encoded| {
            const existing = try decodeTableRecord(self.alloc, encoded);
            defer metadata_table_manager.freeTable(self.alloc, existing);
            if (try self.relationalDropBlockedTxn(txn, group_id, existing)) return error.ConstraintRetirementRequired;
            try self.dropLakeIndexLifecycleTxn(txn, group_id, existing);
        }
        {
            var arena = std.heap.ArenaAllocator.init(self.alloc);
            defer arena.deinit();
            const a = arena.allocator();
            var table_buf: [160]u8 = undefined;
            if (txn.get(try tableKeyForGroup(&table_buf, group_id, table_id)) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            }) |raw| try self.removeResolverDependenciesTxn(a, txn, group_id, try decodeTableRecord(a, raw));
            try self.retireResolverNamespaceDependenciesTxn(a, txn, group_id, table_id);
            try txn.delete(try resolverRejectionKey(a, group_id, table_id));
        }
        const existing_table_name = try self.lookupTableNameTxn(txn, group_id, table_id);
        defer if (existing_table_name) |name| self.alloc.free(name);
        try self.removeSystemCatalogTableTxn(txn, group_id, table_id);
        if (try index_publication.deleteTerminal(txn, group_id, table_id)) try relation_reconciliation.advanceTrackedSource(txn, group_id);
        if (try stagingGet(txn, key) != null) try relation_reconciliation.advanceTrackedSource(txn, group_id);
        txn.delete(key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        var fingerprint_key_buf: [192]u8 = undefined;
        try self.deleteColumnIdentitiesTxn(txn, group_id, table_id);
        txn.delete(try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group_id, table_id)) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        if (existing_table_name) |name| try self.deleteTableNameIndexTxn(txn, group_id, name);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id, .table_name = existing_table_name, .table_id = table_id });
    }

    fn applyTableUpsertTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.TableRecord,
    ) !void {
        var result = try self.prepareTableUpsertTxn(txn, group_id, record);
        defer result.deinit(self.alloc);
        if (result == .write) {
            var key_buf: [160]u8 = undefined;
            try self.writePreparedTableRecordTxn(txn, group_id, try tableKeyForGroup(&key_buf, group_id, record.table_id), result.write);
        }
    }

    const PreparedTableUpsert = union(enum) {
        rejected,
        unchanged,
        write: PreparedTableRecordWrite,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.* == .write) self.write.deinit(alloc);
            self.* = undefined;
        }
    };

    fn prepareTableUpsertTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !PreparedTableUpsert {
        if (!try self.relationalParentsExistTxn(txn, group_id, record)) return .rejected;
        var reservation_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        if (try stagingGet(txn, try fk_generation_publication.initialPhysicalNameKey(&reservation_buf, group_id, record.name)) != null) return .rejected;
        // Reconciliation uses upsert_table, not compare_and_replace_table.
        // The common writer checks the FK lock and permits only the exact
        // owner-ready schema finalization; rejecting here would starve a
        // preparatory initial FK publication indefinitely.
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, record.table_id);
        const encoded_existing = txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var retained: ?metadata.TableRecord = null;
        defer if (retained) |existing| metadata_table_manager.freeTable(self.alloc, existing);
        var admission = record;
        if (encoded_existing) |encoded| {
            const existing = try decodeTableRecord(self.alloc, encoded);
            retained = existing;
            metadata_table_manager.validateObjectTableMutation(self.alloc, existing, record) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return .rejected,
            };
            // Reconciliation may retain a generation but never publish, clear,
            // or steal one through an unconditional table upsert. Omission
            // retains internal state so schema reconciliation can continue
            // without taking ownership of the publication lifecycle.
            if (record.lake_index_catalog_json.len == 0) admission.lake_index_catalog_json = existing.lake_index_catalog_json else if (!std.mem.eql(u8, existing.lake_index_catalog_json, record.lake_index_catalog_json)) return .rejected;
            if (metadata_table_manager.tableDefinitionsEqual(existing, admission)) return .unchanged;
            if (!try self.policyDefinitionMutationAllowedTxn(txn, group_id, existing, admission)) return .rejected;
            if ((existing.relational_retirement_json.len != 0 or admission.relational_retirement_json.len != 0) and
                !try @import("../relational_retirement.zig").permitsMigrationCleanup(self.alloc, existing, admission)) return .rejected;
            if (!std.mem.eql(u8, existing.name, admission.name) and
                try self.relationalDropBlockedTxn(txn, group_id, existing)) return .rejected;
            if (!try self.relationalDefinitionsRetainedForMutationTxn(txn, group_id, existing, admission)) return .rejected;
        } else if (record.relational_retirement_json.len != 0 or record.lake_index_catalog_json.len != 0) return .rejected;
        if ((try self.loadTableTransitionFenceTxn(txn, group_id, record.table_id)).active()) return .rejected;
        return .{ .write = (try self.prepareTableRecordTxnMode(txn, group_id, key, admission, false)) orelse return .rejected };
    }

    fn indexedTableRangeIdsTxn(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
    ) ![]u64 {
        return self.indexedTableRangeIdsBoundedTxn(alloc, txn, group_id, table_id, std.math.maxInt(usize));
    }

    fn indexedTableRangeIdsBoundedTxn(
        self: *RaftApplyStore,
        alloc: std.mem.Allocator,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
        limit: usize,
    ) ![]u64 {
        _ = self;
        var prefix_buf: [192]u8 = undefined;
        const prefix = try tableRangeIndexPrefixForTable(&prefix_buf, group_id, table_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        return readTableRangeIdsBounded(alloc, &cursor, prefix, limit);
    }

    fn retireRangeRestoreProgressTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        range: metadata.RangeRecord,
        table_name: ?[]const u8,
    ) !void {
        var prefix_buf: [224]u8 = undefined;
        const prefix = try restoreProgressRangeIndexPrefix(&prefix_buf, metadata_group_id, range.table_id, range.group_id);
        const rows = try docstore.DocStore.scanPrefixTxn(self.alloc, txn, prefix);
        defer freeMetadataSnapshotRows(self.alloc, rows);
        for (rows) |row| {
            if (builtin.is_test) self.restore_cleanup_rows_visited += 1;
            if (row.value.len != @sizeOf(u64)) return error.InvalidDerivedCatalogIndex;
            const node_id = std.mem.readInt(u64, row.value[0..8], .little);
            var key_buf: [224]u8 = undefined;
            const key = try restoreProgressKeyForGroup(&key_buf, metadata_group_id, range.table_id, node_id, range.group_id);
            try txn.delete(key);
            try txn.delete(row.key);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = metadata_group_id, .key = key });
            self.notifyProjectionListeners(.{
                .kind = .restore_progress,
                .metadata_group_id = metadata_group_id,
                .table_name = table_name,
                .table_id = range.table_id,
                .node_id = node_id,
                .group_id = range.group_id,
            });
        }
    }

    fn indexedRangeMembershipMatchesTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
        ids: []const u64,
        expected: topology_protocol.RangeMembership,
    ) !bool {
        var accumulator: topology_protocol.RangeMembershipAccumulator = .{};
        for (ids) |range_group_id| {
            var range_key_buf: [160]u8 = undefined;
            const range_key = try rangeKeyForGroup(&range_key_buf, group_id, range_group_id);
            const encoded = txn.get(range_key) catch |err| switch (err) {
                error.NotFound => return false,
                else => return err,
            };
            const record = try decodeRangeRecord(self.alloc, encoded);
            defer metadata_table_manager.freeRange(self.alloc, record);
            if (record.table_id != table_id or record.group_id != range_group_id) return false;
            try accumulator.add(range_group_id);
        }
        return accumulator.finish(table_id).eql(expected);
    }

    /// Rare repair path for projections created before the derived index was
    /// introduced or after local index corruption. Normal drop apply never
    /// scans the cluster-wide range namespace.
    fn rebuildTableRangeIndexTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
    ) ![]u64 {
        var table_prefix_buf: [192]u8 = undefined;
        try self.deleteDerivedPrefixTxn(
            txn,
            try tableRangeIndexPrefixForTable(&table_prefix_buf, group_id, table_id),
        );
        var range_prefix_buf: [128]u8 = undefined;
        const rows = try docstore.DocStore.scanPrefixTxn(
            self.alloc,
            txn,
            try rangePrefixForGroup(&range_prefix_buf, group_id),
        );
        defer freeMetadataSnapshotRows(self.alloc, rows);
        var ids = std.ArrayListUnmanaged(u64).empty;
        errdefer ids.deinit(self.alloc);
        for (rows) |row| {
            const record = try decodeRangeRecord(self.alloc, row.value);
            defer metadata_table_manager.freeRange(self.alloc, record);
            if (record.table_id != table_id) continue;
            try ids.append(self.alloc, record.group_id);
        }
        for (ids.items) |range_group_id|
            try self.putTableRangeIndexTxn(txn, group_id, table_id, range_group_id);
        return try ids.toOwnedSlice(self.alloc);
    }

    fn compactDropRangeIdsTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
        expected: topology_protocol.RangeMembership,
    ) !?[]u64 {
        var ids = self.indexedTableRangeIdsTxn(self.alloc, txn, group_id, table_id) catch |err| switch (err) {
            error.InvalidDerivedCatalogIndex => try self.rebuildTableRangeIndexTxn(txn, group_id, table_id),
            else => return err,
        };
        if (try self.indexedRangeMembershipMatchesTxn(txn, group_id, table_id, ids, expected)) return ids;
        self.alloc.free(ids);
        ids = try self.rebuildTableRangeIndexTxn(txn, group_id, table_id);
        if (try self.indexedRangeMembershipMatchesTxn(txn, group_id, table_id, ids, expected)) return ids;
        self.alloc.free(ids);
        return null;
    }

    fn stagingGet(txn: *docstore.DocStore.Txn, key: []const u8) !?[]const u8 {
        return txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
    }

    /// Only internal placement/provisioning uses this paired snapshot. Public
    /// catalog and routing projections remain strictly publication-only.
    pub fn captureProvisioningCatalog(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) !restore_staging.ProvisioningProjection {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var tables = std.ArrayList(metadata.TableRecord).fromOwnedSlice(try self.listTablesTxn(alloc, &txn, group_id));
        errdefer {
            for (tables.items) |table| metadata_table_manager.freeTable(alloc, table);
            tables.deinit(alloc);
        }
        var ranges = std.ArrayList(metadata.RangeRecord).fromOwnedSlice(try self.listRangesTxn(alloc, &txn, group_id));
        var jobs: std.ArrayList([]const u8) = .empty;
        var initial_fk_owners: std.ArrayList(restore_staging.ProvisioningProjection.InitialFkOwner) = .empty;
        errdefer initial_fk_owners.deinit(alloc);
        errdefer {
            for (jobs.items) |job| alloc.free(job);
            jobs.deinit(alloc);
        }
        errdefer {
            for (ranges.items) |range| metadata_table_manager.freeRange(alloc, range);
            ranges.deinit(alloc);
        }
        var prefix_buf: [256]u8 = undefined;
        const prefix = try restore_staging.activePrefix(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        var count: usize = 0;
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix)) break;
            count += 1;
            if (count > restore_staging.max_active_attempts or row.value.len != 16) return error.InvalidRestoreStaging;
            const id: restore_staging.Id = row.value[0..16].*;
            var key_buf: [256]u8 = undefined;
            const job_bytes = (try stagingGet(&txn, try restore_staging.jobKey(&key_buf, group_id, id))) orelse return error.InvalidRestoreStaging;
            if (job_bytes.len > restore_staging.max_encoded_bytes) return error.InvalidRestoreStaging;
            var job = try std.json.parseFromSlice(restore_staging.Job, alloc, job_bytes, .{});
            defer job.deinit();
            try overlayRestoreStagingProgressTxn(&txn, alloc, group_id, id, &job.value);
            // Drafts reserve identities and live source definitions, but may
            // not create target owners until immutable source cuts are bound.
            if (job.value.plan.preparing_sources) continue;
            switch (job.value.state) {
                .importing, .validating, .cutover, .activating, .canceling => {},
                .published, .canceled, .preparing_sources => return error.InvalidRestoreStaging,
            }
            // The plan remains immutable. Only this snapshot's small progress
            // view changes, so a restarted owner can distinguish ordinary
            // staging admission from metadata-authorized cancel recovery.
            try jobs.ensureUnusedCapacity(alloc, 1);
            jobs.appendAssumeCapacity(try std.json.Stringify.valueAlloc(alloc, job.value, .{}));
            for (job.value.plan.targets) |target| {
                try tables.ensureUnusedCapacity(alloc, 1);
                var table = target.table;
                table.restore_backup_id = "";
                table.restore_location = "";
                // Preserve source configuration in the immutable plan, but
                // never start producers against unpublished generations.
                table.replication_sources_json = "[]";
                tables.appendAssumeCapacity(try metadata_table_manager.cloneTable(alloc, table));
                try ranges.ensureUnusedCapacity(alloc, target.ranges.len);
                for (target.ranges) |range| {
                    var owned_range = try metadata_table_manager.cloneRange(alloc, range);
                    errdefer metadata_table_manager.freeRange(alloc, owned_range);
                    // Placement creates EMPTY generations. Artifact import is
                    // driven only through the authenticated scoped importer,
                    // never the ordinary backup_restore bootstrap shortcut.
                    try metadata_table_manager.clearOwnedRangeRestoreIntent(alloc, &owned_range);
                    owned_range.completed_restore_fingerprint = metadata_table_manager.empty_restore_completion_fingerprint;
                    ranges.appendAssumeCapacity(owned_range);
                }
            }
        }
        var initial_prefix_buf: [160]u8 = undefined;
        const initial_prefix = try fk_generation_publication.initialPrefixForGroup(&initial_prefix_buf, group_id);
        entry = try cursor.seekAtOrAfter(initial_prefix);
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, initial_prefix)) break;
            var parsed = try std.json.parseFromSlice(fk_generation_publication.InitialPublication, alloc, row.value, .{});
            defer parsed.deinit();
            const publication = parsed.value;
            if (publication.phase == .published or publication.phase == .canceled or
                publication.phase == .preparing_support) continue;
            try publication.validateState(alloc);
            // A hidden owner is sealed and empty. Do not start external
            // replication producers against it before the final catalog CAS.
            var hidden_child = publication.plan.child;
            hidden_child.replication_sources_json = "[]";
            try tables.append(alloc, try metadata_table_manager.cloneTable(alloc, hidden_child));
            for (publication.plan.child_ranges) |range| {
                try ranges.append(alloc, try metadata_table_manager.cloneRange(alloc, range));
                try initial_fk_owners.append(alloc, .{
                    .catalog_coverage = publication.plan.catalog_coverage,
                    .plan_id = publication.plan.id,
                    .plan_digest = publication.plan_digest,
                    .child_table_id = publication.plan.child.table_id,
                    .child_group_id = range.group_id,
                    .namespace = .{
                        .table_id = publication.plan.child.table_id,
                        .shard_id = metadata_table_manager.rangeDocIdentityShardId(range),
                        .range_id = metadata_table_manager.rangeDocIdentityRangeId(range),
                    },
                    .schema_version = publication.candidate.schema_version,
                    .schema_digest = publication.candidate.schema_digest,
                    .public_schema_json_digest = publication.candidate.public_schema_json_digest,
                    .catalog_digest = publication.candidate.catalog_digest,
                });
            }
        }
        var projection_arena = std.heap.ArenaAllocator.init(alloc);
        defer projection_arena.deinit();
        const pa = projection_arena.allocator();
        var projections: ResolverProjectionCache = .empty;
        for (tables.items) |*table| {
            const indexes = try self.resolverExecutionIndexesTxn(pa, &txn, group_id, table.indexes_json, &projections);
            const owned = try alloc.dupe(u8, indexes);
            alloc.free(table.indexes_json);
            table.indexes_json = owned;
        }
        const owned_tables = try tables.toOwnedSlice(alloc);
        errdefer self.freeTables(alloc, owned_tables);
        const owned_ranges = try ranges.toOwnedSlice(alloc);
        errdefer self.freeRanges(alloc, owned_ranges);
        return .{ .tables = owned_tables, .ranges = owned_ranges, .jobs_json = try jobs.toOwnedSlice(alloc), .initial_fk_owners = try initial_fk_owners.toOwnedSlice(alloc) };
    }

    fn overlayRestoreStagingProgressTxn(txn: *docstore.DocStore.Txn, alloc: std.mem.Allocator, group_id: u64, id: restore_staging.Id, job: *restore_staging.Job) !void {
        var key_buf: [256]u8 = undefined;
        const bytes = (try stagingGet(txn, try restore_staging.progressKey(&key_buf, group_id, id))) orelse return error.InvalidRestoreStaging;
        var progress = try std.json.parseFromSlice(restore_staging.Progress, alloc, bytes, .{});
        defer progress.deinit();
        if (progress.value.revision == 0) return error.InvalidRestoreStaging;
        job.state = progress.value.state;
        job.revision = progress.value.revision;
        job.completed_owners = progress.value.completed_owners;
    }

    /// This is deliberately separate from all public catalog projections.
    /// Only a restore driver holding an exact job identity may obtain targets.
    pub fn loadRestoreStaging(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, id: restore_staging.Id) !?std.json.Parsed(restore_staging.Job) {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [256]u8 = undefined;
        const bytes = (try stagingGet(&txn, try restore_staging.jobKey(&key_buf, group_id, id))) orelse return null;
        var job = try std.json.parseFromSlice(restore_staging.Job, alloc, bytes, .{ .allocate = .alloc_always });
        errdefer job.deinit();
        try overlayRestoreStagingProgressTxn(&txn, alloc, group_id, id, &job.value);
        if (job.value.plan.preparing_sources) {
            const arena = job.arena.allocator();
            const targets = try arena.dupe(restore_staging.Target, job.value.plan.targets);
            for (targets) |*target| {
                var artifacts: std.ArrayList(restore_staging.SourceArtifact) = .empty;
                for (target.ranges) |range| {
                    const raw = (try stagingGet(&txn, try restore_staging.sourceArtifactKey(&key_buf, group_id, id, range.group_id))) orelse continue;
                    const artifact = try std.json.parseFromSliceLeaky(restore_staging.SourceArtifact, arena, raw, .{ .allocate = .alloc_always });
                    try artifacts.append(arena, artifact);
                }
                target.source_artifacts = try artifacts.toOwnedSlice(arena);
            }
            job.value.plan.targets = targets;
        }
        return job;
    }

    /// Owner identity reservations are immutable tombstones, including after
    /// cancellation. Resolve one exact owner without scanning historical jobs.
    pub fn loadRestoreStagingForOwner(self: *RaftApplyStore, alloc: std.mem.Allocator, metadata_group_id: u64, owner_group_id: u64) !?std.json.Parsed(restore_staging.Job) {
        var key_buf: [256]u8 = undefined;
        const bytes = self.store.get(alloc, try restore_staging.identityKey(&key_buf, metadata_group_id, .group, owner_group_id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(bytes);
        if (bytes.len != 16) return error.InvalidRestoreStaging;
        return self.loadRestoreStaging(alloc, metadata_group_id, bytes[0..16].*);
    }

    pub fn loadRestoreStagingProgress(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, id: restore_staging.Id) !?restore_staging.Progress {
        var key_buf: [256]u8 = undefined;
        const bytes = self.store.get(alloc, try restore_staging.progressKey(&key_buf, group_id, id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(bytes);
        var parsed = try std.json.parseFromSlice(restore_staging.Progress, alloc, bytes, .{});
        defer parsed.deinit();
        return parsed.value;
    }

    /// Read-only authorization remains valid after replica placement removal.
    /// The immutable restore group reservation and existing placement-version
    /// tombstone jointly bind plan, group, and node; no whole-plan decode or
    /// retained-history scan is needed for each owner progress poll.
    /// Replacement old owners deliberately receive no grant: the metadata
    /// driver reads their receipts locally and fences them through the normal
    /// topology batch route. An unchanged external FK parent may request its
    /// exact owner group while it still has a live placement. That scope is
    /// intentionally not kept after placement removal, unlike a new target's
    /// historical placement grant needed for terminal status reads.
    pub fn restoreStagingAuthorityAllowed(self: *RaftApplyStore, alloc: std.mem.Allocator, metadata_group_id: u64, id: restore_staging.Id, node_id: u64, owner_group: ?u64) !bool {
        _ = alloc;
        if (node_id == 0) return false;
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var key_buf: [256]u8 = undefined;
        const witness = try stagingGet(&txn, try restore_staging.authorityNodeKey(&key_buf, metadata_group_id, id, node_id));
        if (witness) |bytes| {
            if (bytes.len != 8) return error.InvalidRestoreStaging;
            const witness_group = std.mem.readInt(u64, bytes[0..8], .little);
            const reservation = (try stagingGet(&txn, try restore_staging.identityKey(&key_buf, metadata_group_id, .group, witness_group))) orelse return false;
            if (!std.mem.eql(u8, reservation, &id) or try self.loadPlacementVersionFenceTxn(&txn, metadata_group_id, witness_group, node_id) == 0) return false;
        } else if (owner_group == null) return false;
        if (owner_group) |requested_group| {
            const target_reservation = try stagingGet(&txn, try restore_staging.identityKey(&key_buf, metadata_group_id, .group, requested_group));
            if (target_reservation) |requested| {
                if (witness == null or !std.mem.eql(u8, requested, &id) or try self.loadPlacementVersionFenceTxn(&txn, metadata_group_id, requested_group, node_id) == 0) return false;
            } else {
                const parent_reservation = (try stagingGet(&txn, try restore_staging.identityKey(&key_buf, metadata_group_id, .parent_group, requested_group))) orelse return false;
                if (!std.mem.eql(u8, parent_reservation, &id)) return false;
                // The permanent placement-version fence alone also covers
                // former nodes. Parent activation requires a current hosted
                // replica; final leader authority is checked again at apply.
                if (try stagingGet(&txn, try placementKeyForGroup(&key_buf, metadata_group_id, requested_group, node_id)) == null or
                    try self.loadPlacementVersionFenceTxn(&txn, metadata_group_id, requested_group, node_id) == 0) return false;
            }
        }
        return true;
    }

    fn stageRestorePlacementAuthorityTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, owner_group: u64, node_id: u64) !void {
        _ = self;
        var key_buf: [256]u8 = undefined;
        const reservation = (try stagingGet(txn, try restore_staging.identityKey(&key_buf, metadata_group_id, .group, owner_group))) orelse return;
        if (reservation.len != 16) return error.InvalidRestoreStaging;
        const plan_id: restore_staging.Id = reservation[0..16].*;
        const authority_key = try restore_staging.authorityNodeKey(&key_buf, metadata_group_id, plan_id, node_id);
        if (try stagingGet(txn, authority_key) != null) return;
        var witness: [8]u8 = undefined;
        std.mem.writeInt(u64, &witness, owner_group, .little);
        try txn.put(authority_key, &witness);
    }

    fn initialPlacementAuthorizedTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        intent: raft_reconciler.PlacementIntent,
    ) !bool {
        var key_buf: [192]u8 = undefined;
        const reserved = (try stagingGet(txn, try fk_generation_publication.initialGroupKey(
            &key_buf,
            metadata_group_id,
            intent.record.group_id,
        ))) orelse return true; // Ordinary public or restore-staging placement.
        const identity = try fk_generation_publication.InitialGroupReservation.decode(reserved);
        if (identity.canceled) return false;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const encoded = (try stagingGet(txn, try fk_generation_publication.initialKey(
            &key_buf,
            metadata_group_id,
            identity.child_table_id,
        ))) orelse return false;
        const publication = try std.json.parseFromSliceLeaky(fk_generation_publication.InitialPublication, a, encoded, .{});
        try publication.validateState(a);
        if (!std.mem.eql(u8, &publication.plan.id, &identity.plan_id) or
            !std.mem.eql(u8, &publication.plan_digest, &identity.plan_digest) or
            publication.plan.retirement_scope != identity.retirement_scope or
            publication.phase == .preparing_support or publication.phase == .published or publication.phase == .canceled or
            publication.plan.child.table_id != identity.child_table_id) return false;
        const has_group = for (publication.plan.child_ranges) |range| {
            if (range.group_id == intent.record.group_id and range.table_id == identity.child_table_id and
                range.range_id == identity.range_id) break true;
        } else false;
        if (!has_group) return false;
        const role = publication.plan.child.placement_role;
        const node = (try self.loadNodeRecordTxn(txn, metadata_group_id, intent.record.local_node_id)) orelse return false;
        defer metadata_table_manager.freeNode(self.alloc, node);
        if (!metadata_table_manager.nodeLifecycleActive(node.lifecycle) or !metadata_table_manager.placementRoleCompatible(role, node.role)) return false;
        if (identity.retirement_scope == .hosted_store and intent.store_id == 0) return false;
        if (intent.store_id != 0) {
            const store = (try self.loadStoreHeaderTxn(txn, metadata_group_id, intent.store_id)) orelse return false;
            defer metadata_table_manager.freeStore(self.alloc, store);
            if (store.node_id != intent.record.local_node_id or !store.live or store.drain_requested or
                !metadata_table_manager.placementRoleCompatible(role, store.role)) return false;
            if (identity.retirement_scope == .hosted_store and
                (store.reporter_incarnation == 0 or store.replica_root_incarnation == 0)) return false;
        }
        return true;
    }

    pub fn loadRestoreStagingReceipt(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, id: restore_staging.Id, state: restore_staging.State, owner_group_id: u64) !?[]u8 {
        var key_buf: [256]u8 = undefined;
        return self.store.get(alloc, try restore_staging.receiptKey(&key_buf, group_id, id, state, owner_group_id)) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
    }

    fn restoreReplacementMatchesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, target: restore_staging.Target) !bool {
        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        const name_value = try stagingGet(txn, try tableNameIndexKey(&key_buf, group_id, target.table.name));
        const old = target.replace orelse return name_value == null;
        if (std.mem.eql(u8, old.table.name, target.table.name)) {
            if (name_value == null or name_value.?.len != 8 or std.mem.readInt(u64, name_value.?[0..8], .little) != old.table.table_id) return false;
        } else if (target.catalog_binding == null or name_value != null) return false;
        const encoded = (try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, old.table.table_id))) orelse return false;
        const current = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, current);
        if (!metadata_table_manager.tableDefinitionsEqual(current, old.table)) return false;
        // Restoring an identical declaration can still replace its physical
        // generations and data. Join the same schema locks and shared FK
        // target leases before creating any restore reservation.
        if (try self.fkGenerationTableLockedTxn(txn, group_id, old.table.table_id) or
            try @import("../schema_validation_dependencies.zig").isLeased(txn, group_id, old.table.table_id)) return false;
        const fence = try self.loadTableTransitionFenceTxn(txn, group_id, old.table.table_id);
        if (fence.active() or try backupCohortLocksTableTxn(txn, group_id, old.table.table_id) or
            try self.extensionOwnsTableTxn(txn, group_id, old.table.name)) return false;
        var membership: topology_protocol.RangeMembershipAccumulator = .{};
        for (old.ranges) |range| {
            const actual_bytes = (try stagingGet(txn, try rangeKeyForGroup(&key_buf, group_id, range.group_id))) orelse return false;
            const actual = try decodeRangeRecord(self.alloc, actual_bytes);
            defer metadata_table_manager.freeRange(self.alloc, actual);
            if (!metadata_table_manager.rangeRecordsEqual(actual, range)) return false;
            try membership.add(range.group_id);
        }
        return membership.finish(old.table.table_id).eql(fence.membership(old.table.table_id));
    }

    fn restoreExternalParentMatchesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, parent: restore_staging.ExternalFkParent) !bool {
        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        const name_value = (try stagingGet(txn, try tableNameIndexKey(&key_buf, group_id, parent.table.name))) orelse return false;
        if (name_value.len != 8 or std.mem.readInt(u64, name_value[0..8], .little) != parent.table.table_id) return false;
        const encoded = (try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, parent.table.table_id))) orelse return false;
        const current = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, current);
        if (!metadata_table_manager.tableDefinitionsEqual(current, parent.table)) return false;
        if (try self.fkGenerationTableLockedTxn(txn, group_id, parent.table.table_id)) return false;
        const transition = try self.loadTableTransitionFenceTxn(txn, group_id, parent.table.table_id);
        if (transition.active() or try backupCohortLocksTableTxn(txn, group_id, parent.table.table_id) or
            try self.extensionOwnsTableTxn(txn, group_id, parent.table.name)) return false;
        var membership: topology_protocol.RangeMembershipAccumulator = .{};
        for (parent.ranges) |range| {
            const actual_bytes = (try stagingGet(txn, try rangeKeyForGroup(&key_buf, group_id, range.group_id))) orelse return false;
            const actual = try decodeRangeRecord(self.alloc, actual_bytes);
            defer metadata_table_manager.freeRange(self.alloc, actual);
            if (!metadata_table_manager.rangeRecordsEqual(actual, range)) return false;
            try membership.add(range.group_id);
        }
        return membership.finish(parent.table.table_id).eql(transition.membership(parent.table.table_id));
    }

    fn applyRestoreJobWithStagingTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, record: RestoreJobWithStaging) !void {
        var logical_key_buf: [256]u8 = undefined;
        const logical_key = try restoreJobKeyForGroup(&logical_key_buf, group_id, record.key);
        // Replays, cancellation and prior admission win before any reservation
        // is inspected or created. The caller receives the durable first row.
        if (try stagingGet(txn, logical_key) != null) return;
        const Header = struct { job_id: u64, attempt_id: u64, staging_attempt_id: u64, source_kind: []const u8, phase: []const u8, cancel_requested: bool = false };
        var header = std.json.parseFromSlice(Header, self.alloc, record.value, .{ .ignore_unknown_fields = true }) catch |err| {
            if (err == error.OutOfMemory) return err;
            return;
        };
        defer header.deinit();
        if (header.value.job_id == 0 or header.value.attempt_id != 1 or header.value.staging_attempt_id != 1 or header.value.cancel_requested or
            (!std.mem.eql(u8, header.value.source_kind, "schema_rewrite") and !std.mem.eql(u8, header.value.source_kind, "empty_generation")) or !std.mem.eql(u8, header.value.phase, "queued")) return;
        var expected_key_buf: [128]u8 = undefined;
        const expected_key = try std.fmt.bufPrint(&expected_key_buf, "{s}{x:0>16}", .{ restore_job_logical_prefix, header.value.job_id });
        if (!std.mem.eql(u8, record.key, expected_key)) return;
        var plan = std.json.parseFromSlice(restore_staging.Plan, self.alloc, record.plan_json, .{}) catch |err| {
            if (err == error.OutOfMemory) return err;
            return;
        };
        defer plan.deinit();
        const expected_id = try restore_staging.idForAttempt(header.value.job_id, 1);
        const empty_generation = std.mem.eql(u8, header.value.source_kind, "empty_generation");
        if (!std.mem.eql(u8, &plan.value.id, &expected_id) or plan.value.preparing_sources == empty_generation) return;
        for (plan.value.targets) |target| if (target.empty_generation != empty_generation) return;
        const reserve: restore_staging.Command = .{ .id = expected_id, .action = .reserve, .plan = plan.value };
        reserve.validate(self.alloc) catch |err| {
            if (err == error.OutOfMemory) return err;
            return;
        };
        var plan_key_buf: [256]u8 = undefined;
        const plan_key = try restore_staging.jobKey(&plan_key_buf, group_id, expected_id);
        var progress_key_buf: [256]u8 = undefined;
        const progress_key = try restore_staging.progressKey(&progress_key_buf, group_id, expected_id);
        if (try stagingGet(txn, plan_key) != null or try stagingGet(txn, progress_key) != null) return;
        const bytes = try std.json.Stringify.valueAlloc(self.alloc, reserve, .{});
        defer self.alloc.free(bytes);
        // The shared reservation validates exact source definitions, ranges,
        // incoming dependency closure and every identity collision first.
        try self.applyRestoreStagingTxn(txn, group_id, bytes);
        if (try stagingGet(txn, plan_key) == null) return;
        try txn.put(logical_key, record.value);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = logical_key });
        self.notifyProjectionListeners(.{ .kind = .restore_job, .metadata_group_id = group_id });
    }

    fn restoreIncomingDependenciesClosedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, plan: restore_staging.Plan) !bool {
        var prefix_buf: [128]u8 = undefined;
        const prefix = try tablePrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix)) break;
            const candidate = try decodeTableRecord(self.alloc, row.value);
            defer metadata_table_manager.freeTable(self.alloc, candidate);
            const replaced = for (plan.targets) |target| {
                if (target.replace) |old| if (old.table.table_id == candidate.table_id) break true;
            } else false;
            if (replaced) continue;
            for ([_][]const u8{ candidate.schema_json, candidate.read_schema_json }) |schema| {
                var declarations = try RelationalDeclarations.parse(self.alloc, schema);
                defer declarations.deinit();
                for (plan.targets) |target| if (target.replace) |old| if (declarations.value.references(old.table.name)) return false;
            }
        }
        return true;
    }

    /// Validate every logical destination before any topology is changed.
    /// Schema rewrites inherit an existing binding; restore admission supplies
    /// explicit bindings for previously absent or differently named owners.
    fn restoreCatalogDeltaTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, plan: restore_staging.Plan) !system_catalog.Delta {
        const meta = try system_catalog_storage.readMeta(alloc, txn, group_id);
        const view: system_catalog_storage.View = .{ .alloc = alloc, .txn = txn, .group_id = group_id, .meta = meta };
        var upserts: std.ArrayList(system_catalog.Resource) = .empty;
        var removes: std.ArrayList(system_catalog.Resource) = .empty;
        // Replacements currently install fresh native column identities.
        // Until an admitted view-rebinding cohort exists, reject dependent
        // views at reservation AND publication. Deferring this to deletion
        // would let an ordinary DDL conflict poison ordered Raft apply.
        for (plan.targets) |target| if (target.replace) |replacement| {
            if (try sql_views.firstDependent(txn, group_id, .table, replacement.table.table_id, null) != null)
                return error.InvalidRestoreStaging;
        };
        for (plan.targets) |target| {
            try validateColumnSequenceHandoffsTxn(alloc, txn, group_id, target);
            const old = if (target.replace) |replacement| try view.byId(.table, replacement.table.table_id) else null;
            var binding = target.catalog_binding orelse old orelse continue;
            if (try view.byId(.namespace, binding.parent_id) == null or try view.byId(.table, target.table.table_id) != null) return error.InvalidRestoreStaging;
            if (binding.tablespace_id != 0 and try view.byId(.tablespace, binding.tablespace_id) == null) return error.InvalidRestoreStaging;
            const current = try view.lookup(.table, binding.parent_id, binding.name);
            if (old) |prior| {
                if (current == null or current.?.id != prior.id or prior.parent_id != binding.parent_id or
                    !std.mem.eql(u8, prior.name, binding.name) or !std.mem.eql(u8, prior.storage_name, target.replace.?.table.name)) return error.InvalidRestoreStaging;
                try removes.append(alloc, prior);
            } else if (current != null) return error.InvalidRestoreStaging;
            if (try view.bindingForStorage(target.table.name)) |physical| {
                if (old == null or physical.id != old.?.id) return error.InvalidRestoreStaging;
            }
            binding.id = target.table.table_id;
            binding.storage_name = target.table.name;
            try upserts.append(alloc, binding);
            for (target.sequence_handoffs) |move| try upserts.append(alloc, try move.resource(alloc));
        }
        return .{ .upserts = upserts.items, .removes = removes.items, .next_id = meta.next_id };
    }

    fn applyRestoreStagingTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, bytes: []const u8) !void {
        var catalog_arena = std.heap.ArenaAllocator.init(self.alloc);
        defer catalog_arena.deinit();
        var parsed = restore_staging.parseCommand(self.alloc, bytes) catch |err| {
            if (err == error.OutOfMemory) return err;
            return; // Invalid requests must not poison the Raft apply loop.
        };
        defer parsed.deinit();
        const command = parsed.value;
        if (command.plan) |plan| if (plan.readerPublicationRequired()) {
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_reader_publication_version);
        };
        var job_key_buf: [256]u8 = undefined;
        const job_key = try restore_staging.jobKey(&job_key_buf, group_id, command.id);
        var progress_key_buf: [256]u8 = undefined;
        const progress_key = try restore_staging.progressKey(&progress_key_buf, group_id, command.id);
        const source_tracked = switch (command.action) {
            .reserve, .freeze_rewrite, .publish, .finish_cancel => try relation_reconciliation.readSourceRevision(txn, group_id) != 0,
            else => false, // Receipt/progress traffic cannot change names.
        };
        var previous_source_digest: ?[32]u8 = null;
        var namespace_active_buf: [256]u8 = undefined;
        const namespace_active_key = try restore_staging.activeKey(&namespace_active_buf, group_id, command.id);
        const previous_active = if (source_tracked) try stagingGet(txn, namespace_active_key) != null else false;
        const current = try stagingGet(txn, job_key);
        if (command.action == .cancel_reservation) {
            // A durable attempt exists before reserve is sent. Tombstone even
            // an absent plan so a delayed reserve cannot resurrect cancellation.
            // An already admitted plan requires ordinary owner cleanup instead.
            if (current == null and try stagingGet(txn, progress_key) == null) {
                const tombstone = try std.json.Stringify.valueAlloc(self.alloc, restore_staging.Progress{ .state = .canceled }, .{});
                defer self.alloc.free(tombstone);
                try txn.put(progress_key, tombstone);
            }
            return;
        }
        if (command.action == .reserve) {
            if (current != null) return; // Immutable identity; callers verify plan digest after apply.
            if (try stagingGet(txn, progress_key) != null) return; // Canceled before admission.
            const plan = command.plan.?;
            _ = restoreCatalogDeltaTxn(catalog_arena.allocator(), txn, group_id, plan) catch |err| {
                if (err == error.InvalidRestoreStaging) return;
                return err;
            };
            if (try plan.constraintNameTarget()) |target| {
                // This is before the first name, owner, range or job write.
                // The admitted plan subsequently owns the name reservation.
                self.validateRelationMutationTxn(txn, group_id, plan.constraint_name_guard.?, target.replace.?.table, target.table) catch |err| switch (err) {
                    error.CatalogGenerationChanged, error.CatalogPublicationProofPending, error.CatalogOccupancyNotReady, error.TableTopologyProtocolUpgradeRequired, error.ExtensionOwnedObject => return,
                    else => return err,
                };
            }
            {
                var prefix_buf: [256]u8 = undefined;
                const prefix = try restore_staging.activePrefix(&prefix_buf, group_id);
                var cursor = try txn.openCursor();
                defer cursor.close();
                var entry = try cursor.seekAtOrAfter(prefix);
                var count: usize = 0;
                while (entry) |row| : (entry = try cursor.next()) {
                    if (!std.mem.startsWith(u8, row.key, prefix)) break;
                    count += 1;
                    if (count >= restore_staging.max_active_attempts) return;
                }
            }
            // Check every collision before writing anything. All names and
            // fresh IDs are reserved together, including interdependent FKs.
            for (plan.targets) |target| {
                if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, target.table.table_id)) return;
                if (target.replace) |old| if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, old.table.table_id)) return;
                var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                if (try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, target.table.table_id)) != null or
                    try stagingGet(txn, try restore_staging.nameKey(&key_buf, group_id, target.table.name)) != null or
                    try stagingGet(txn, try fk_generation_publication.initialPhysicalNameKey(&key_buf, group_id, target.table.name)) != null or
                    try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .table, target.table.table_id)) != null) return;
                if (!try self.restoreReplacementMatchesTxn(txn, group_id, target)) return;
                if (target.replace) |old| if (try restoreStagingLocksTableTxn(txn, group_id, old.table.table_id)) return;
                const fence = try self.loadTableTransitionFenceTxn(txn, group_id, target.table.table_id);
                if (fence.generation != 0 or fence.active() or fence.range_membership.count != 0) return;
                for (target.ranges) |range| {
                    if (try stagingGet(txn, try rangeKeyForGroup(&key_buf, group_id, range.group_id)) != null or
                        try stagingGet(txn, try fk_generation_publication.initialGroupKey(&key_buf, group_id, range.group_id)) != null or
                        try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .group, range.group_id)) != null) return;
                }
            }
            for (plan.external_fk_parents) |parent| {
                var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                if (try restoreStagingLocksTableTxn(txn, group_id, parent.table.table_id) or
                    try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .parent_table, parent.table.table_id)) != null or
                    !try self.restoreExternalParentMatchesTxn(txn, group_id, parent)) return;
                for (parent.ranges) |range| if (try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .parent_group, range.group_id)) != null) return;
            }
            if (!try self.restoreIncomingDependenciesClosedTxn(txn, group_id, plan)) return;
            const initial_state: restore_staging.State = if (plan.preparing_sources) .preparing_sources else .importing;
            const job: restore_staging.Job = .{ .plan = plan, .plan_digest = try plan.digest(self.alloc), .state = initial_state };
            const value = try std.json.Stringify.valueAlloc(self.alloc, job, .{});
            defer self.alloc.free(value);
            try txn.put(job_key, value);
            var active_key_buf: [256]u8 = undefined;
            try txn.put(try restore_staging.activeKey(&active_key_buf, group_id, command.id), &command.id);
            for (plan.targets) |target| {
                var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                try txn.put(try restore_staging.nameKey(&key_buf, group_id, target.table.name), &command.id);
                try txn.put(try restore_staging.identityKey(&key_buf, group_id, .table, target.table.table_id), &command.id);
                if (target.replace) |old| try txn.put(try restore_staging.identityKey(&key_buf, group_id, .old_table, old.table.table_id), &command.id);
                for (target.ranges) |range| try txn.put(try restore_staging.identityKey(&key_buf, group_id, .group, range.group_id), &command.id);
            }
            for (plan.external_fk_parents) |parent| {
                var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                try txn.put(try restore_staging.identityKey(&key_buf, group_id, .parent_table, parent.table.table_id), &command.id);
                // Existing parent owners must never acquire the restoration
                // authority implied by a fresh target's `.group` reservation.
                for (parent.ranges) |range| try txn.put(try restore_staging.identityKey(&key_buf, group_id, .parent_group, range.group_id), &command.id);
            }
            const initial = try std.json.Stringify.valueAlloc(self.alloc, restore_staging.Progress{ .state = initial_state }, .{});
            defer self.alloc.free(initial);
            try txn.put(progress_key, initial);
        } else {
            const existing = current orelse return;
            var job = try std.json.parseFromSlice(restore_staging.Job, self.alloc, existing, .{});
            defer job.deinit();
            if (source_tracked) previous_source_digest = try relationRestoreSourceDigest(job.value.plan);
            const progress_bytes = (try stagingGet(txn, progress_key)) orelse return error.InvalidRestoreStaging;
            var progress = try std.json.parseFromSlice(restore_staging.Progress, self.alloc, progress_bytes, .{});
            defer progress.deinit();
            var next = progress.value;
            if (next.revision != command.expected_revision or next.state == .published or next.state == .canceled) return;
            var total: u32 = 0;
            var old_total: u32 = 0;
            var parent_total: u32 = 0;
            var admission_total: u32 = 0;
            for (job.value.plan.targets) |target| {
                total += @intCast(target.ranges.len);
                if (target.replace) |old| old_total += @intCast(old.ranges.len);
                for (target.source_generation_admissions) |range_proof| if (range_proof.entries.len != 0) {
                    admission_total += 1;
                };
                admission_total += @intCast(target.generation_handoffs.len);
            }
            for (job.value.plan.external_fk_parents) |parent| parent_total += @intCast(parent.ranges.len);
            switch (command.action) {
                .reserve, .cancel_reservation => unreachable,
                .rewrite_source_ready => {
                    if (next.state != .preparing_sources or !job.value.plan.preparing_sources) return;
                    const artifact = command.source_artifact.?;
                    const binding = artifact.rewrite.?;
                    const matches = outer: for (job.value.plan.targets) |target| {
                        if (!std.mem.eql(u8, &target.rewrite.?.program_digest, &binding.program_digest)) continue;
                        for (target.rewrite_sources) |scope| if (std.meta.eql(scope, binding.source_scope.?)) break :outer true;
                    } else false;
                    if (!matches) return;
                    var source_key_buf: [256]u8 = undefined;
                    const source_key = try restore_staging.sourceArtifactKey(&source_key_buf, group_id, command.id, artifact.target_group_id);
                    if (try stagingGet(txn, source_key) != null) return;
                    const value = try std.json.Stringify.valueAlloc(self.alloc, artifact, .{});
                    defer self.alloc.free(value);
                    try txn.put(source_key, value);
                    next.completed_owners += 1;
                    next.revision += 1;
                },
                .freeze_rewrite => {
                    if (next.state != .preparing_sources or !job.value.plan.preparing_sources or next.completed_owners != total) return;
                    const frozen = command.plan.?;
                    const previous_digest = try job.value.plan.rewriteIntentDigest(self.alloc);
                    const frozen_digest = try frozen.rewriteIntentDigest(self.alloc);
                    if (!std.mem.eql(u8, &previous_digest, &frozen_digest)) return;
                    for (frozen.targets) |target| for (target.source_artifacts) |artifact| {
                        var source_key_buf: [256]u8 = undefined;
                        const raw = (try stagingGet(txn, try restore_staging.sourceArtifactKey(&source_key_buf, group_id, command.id, artifact.target_group_id))) orelse return;
                        var expected = try std.json.parseFromSlice(restore_staging.SourceArtifact, self.alloc, raw, .{});
                        defer expected.deinit();
                        if (!std.mem.eql(u8, &try expected.value.digest(self.alloc), &try artifact.digest(self.alloc))) return;
                    };
                    // The full cohort geometry remains reserved. No target
                    // scopes exist before this atomic immutable-plan freeze.
                    for (frozen.targets) |target| if (!try self.restoreReplacementMatchesTxn(txn, group_id, target)) return;
                    const value = try std.json.Stringify.valueAlloc(self.alloc, restore_staging.Job{ .plan = frozen, .plan_digest = try frozen.digest(self.alloc) }, .{});
                    defer self.alloc.free(value);
                    try txn.put(job_key, value);
                    next.state = .importing;
                    next.completed_owners = 0;
                    next.revision += 1;
                },
                .imported, .validated, .old_fenced, .canceled, .parent_fenced, .parent_activated, .target_admissions_activated => {
                    const expected_state: restore_staging.State = switch (command.action) {
                        .imported => .importing,
                        .validated => .validating,
                        .old_fenced, .parent_fenced => .cutover,
                        .parent_activated, .target_admissions_activated => .activating,
                        .canceled => .canceling,
                        else => unreachable,
                    };
                    if (next.state != expected_state) return;
                    // Old-child cutover may only start after every external
                    // parent has durably fenced and staged its exact pending
                    // generation set. Parent receipts cannot trail an old
                    // owner receipt in this monotone counter.
                    if (command.action == .old_fenced and next.completed_owners < parent_total) return;
                    if (command.action == .parent_fenced and next.completed_owners >= parent_total) return;
                    if (command.action == .parent_activated and next.completed_owners >= parent_total) return;
                    if (command.action == .target_admissions_activated and (next.completed_owners < parent_total or next.completed_owners >= parent_total + admission_total)) return;
                    const receipt = command.receipt.?;
                    if (!std.mem.eql(u8, &receipt.plan_digest, &job.value.plan_digest)) return;
                    if (command.action == .parent_activated) {
                        const retirement = @import("antfly_local_sources").storage_db_relational_integrity_generation_retirement;
                        const expected_publication = retirement.publicationDigest(command.id, job.value.plan_digest);
                        const planned_fence = outer: for (job.value.plan.external_fk_parents) |parent| {
                            for (parent.fences) |fence| if (fence.owner_group_id == receipt.group_id) break :outer fence;
                        } else return;
                        const expected_receipt = try retirement.activationReceipt(planned_fence, job.value.plan_digest, expected_publication);
                        if (!std.mem.eql(u8, &receipt.completion_digest, &expected_receipt)) return;
                    }
                    if (command.action == .target_admissions_activated) {
                        const handoff = restore_staging.mappedEmptyGenerationHandoffForGroup(self.alloc, job.value.plan, job.value.plan_digest, receipt.group_id) catch |err| switch (err) {
                            error.OutOfMemory => return err,
                            else => return,
                        };
                        if (handoff) |mapped| {
                            if (!std.mem.eql(u8, &receipt.completion_digest, &mapped.expected_receipt_digest)) return;
                        } else {
                            var mapped = (restore_staging.mappedGenerationAdmissionsForGroupAlloc(self.alloc, job.value.plan, job.value.plan_digest, receipt.group_id) catch |err| switch (err) {
                                error.OutOfMemory => return err,
                                else => return,
                            }) orelse return;
                            defer mapped.deinit(self.alloc);
                            if (!std.mem.eql(u8, &receipt.completion_digest, &mapped.expected_receipt_digest)) return;
                        }
                    }
                    const owner_matches = outer: for (job.value.plan.targets) |target| {
                        if (command.action == .target_admissions_activated) {
                            const admitted = blk: {
                                for (target.generation_handoffs) |handoff| if (handoff.target_group_id == receipt.group_id) break :blk true;
                                for (target.source_generation_admissions) |range_proof| if (range_proof.target_group_id == receipt.group_id and range_proof.entries.len != 0) break :blk true;
                                break :blk false;
                            };
                            if (!admitted) continue;
                        }
                        if (command.action != .old_fenced and !job.value.plan.preparing_sources) for (target.ranges) |range| {
                            if (range.group_id == receipt.group_id and range.range_id == receipt.range_id) break :outer true;
                        };
                        if (command.action == .old_fenced or command.action == .canceled) if (target.replace) |old| {
                            for (old.ranges) |range| if (range.group_id == receipt.group_id and (if (range.range_id == 0) range.group_id else range.range_id) == receipt.range_id) break :outer true;
                        };
                    } else blk: {
                        if (command.action == .parent_fenced or command.action == .parent_activated or command.action == .canceled) for (job.value.plan.external_fk_parents) |parent| {
                            for (parent.ranges) |range| if (range.group_id == receipt.group_id and (if (range.range_id == 0) range.group_id else range.range_id) == receipt.range_id) break :blk true;
                        };
                        break :blk false;
                    };
                    if (!owner_matches) return;
                    if (command.action == .old_fenced) {
                        // A graph or FK handoff old-owner receipt is not an
                        // arbitrary coordinator hash. Recompute both exact
                        // logical seals from the immutable Plan, requiring a
                        // combined receipt when both share one old owner.
                        for (job.value.plan.targets) |target| if (target.replace) |old| {
                            for (old.ranges) |range| {
                                if (range.group_id != receipt.group_id or
                                    (if (range.range_id == 0) range.group_id else range.range_id) != receipt.range_id) continue;
                                const graph_scope = restore_staging.graphSealScopeForOldRange(self.alloc, job.value.plan, job.value.plan_digest, target, range) catch |err| switch (err) {
                                    error.OutOfMemory => return err,
                                    else => return,
                                };
                                const graph_digest: ?[32]u8 = if (graph_scope) |scope| scope.sealDigest() catch return else null;
                                const handoff = restore_staging.generationHandoffForOldRange(target, range) catch return;
                                const expected: [32]u8 = if (handoff) |proof| blk: {
                                    const fence = for (old.fences) |candidate| {
                                        if (candidate.owner_group_id == range.group_id) break candidate;
                                    } else return;
                                    const sealed = restore_staging.generationHandoffSealDigest(fence, job.value.plan_digest, proof) catch return;
                                    break :blk restore_staging.generationHandoffOldFenceDigest(fence, sealed, graph_digest) catch return;
                                } else graph_digest orelse break;
                                if (!std.mem.eql(u8, &expected, &receipt.completion_digest)) return;
                            }
                        };
                    }
                    var receipt_buf: [256]u8 = undefined;
                    const receipt_key = try restore_staging.receiptKey(&receipt_buf, group_id, command.id, next.state, receipt.group_id);
                    if (try stagingGet(txn, receipt_key) != null) return;
                    try txn.put(receipt_key, &receipt.completion_digest);
                    next.completed_owners += 1;
                    if (command.action == .imported and next.completed_owners == total) {
                        next.state = .validating;
                        next.completed_owners = 0;
                        next.revision += 1;
                    }
                },
                .source_handoff_checked => {
                    if (next.state != .validating or next.completed_owners != total) return;
                    const receipt = command.receipt.?;
                    if (!std.mem.eql(u8, &receipt.plan_digest, &job.value.plan_digest)) return;
                    const expected = outer: for (job.value.plan.targets) |target| {
                        if (target.generation_handoffs.len == 0) continue;
                        const old = target.replace orelse return;
                        for (old.ranges) |range| {
                            if (range.group_id != receipt.group_id or (if (range.range_id == 0) range.group_id else range.range_id) != receipt.range_id) continue;
                            const handoff = (restore_staging.generationHandoffForOldRange(target, range) catch return) orelse return;
                            const fence = for (old.fences) |candidate| {
                                if (candidate.owner_group_id == range.group_id) break candidate;
                            } else return;
                            break :outer restore_staging.generationHandoffPreflightDigest(fence, job.value.plan_digest, handoff) catch return;
                        }
                    } else return;
                    if (!std.mem.eql(u8, &expected, &receipt.completion_digest)) return;
                    var receipt_buf: [256]u8 = undefined;
                    const receipt_key = try restore_staging.receiptKey(&receipt_buf, group_id, command.id, .validating, receipt.group_id);
                    if (try stagingGet(txn, receipt_key) != null) return;
                    try txn.put(receipt_key, &receipt.completion_digest);
                    next.revision += 1;
                },
                .begin_cutover => {
                    if (next.state != .validating or next.completed_owners != total or old_total == 0) return;
                    for (job.value.plan.targets) |target| {
                        if (target.generation_handoffs.len == 0) continue;
                        const old = target.replace orelse return;
                        for (old.ranges) |range| {
                            var receipt_buf: [256]u8 = undefined;
                            const receipt_key = try restore_staging.receiptKey(&receipt_buf, group_id, command.id, .validating, range.group_id);
                            const actual = (try stagingGet(txn, receipt_key)) orelse return;
                            const handoff = (restore_staging.generationHandoffForOldRange(target, range) catch return) orelse return;
                            const fence = for (old.fences) |candidate| {
                                if (candidate.owner_group_id == range.group_id) break candidate;
                            } else return;
                            const expected = restore_staging.generationHandoffPreflightDigest(fence, job.value.plan_digest, handoff) catch return;
                            if (!std.mem.eql(u8, actual, &expected)) return;
                        }
                    }
                    next.state = .cutover;
                    next.completed_owners = 0;
                    next.revision += 1;
                },
                .begin_activation => {
                    if (parent_total + admission_total == 0 or
                        !((next.state == .cutover and next.completed_owners == old_total + parent_total) or
                            (old_total == 0 and next.state == .validating and next.completed_owners == total))) return;
                    // This transition is the irrevocable metadata decision.
                    // Recheck the full topology and dependency closure in the
                    // same transaction; external owners may only activate
                    // after observing this decision with a leader read-index.
                    for (job.value.plan.targets) |target| if (!try self.restoreReplacementMatchesTxn(txn, group_id, target)) return;
                    for (job.value.plan.external_fk_parents) |parent| if (!try self.restoreExternalParentMatchesTxn(txn, group_id, parent)) return;
                    if (!try self.restoreIncomingDependenciesClosedTxn(txn, group_id, job.value.plan)) return;
                    next.state = .activating;
                    next.completed_owners = 0;
                    next.revision += 1;
                },
                .begin_cancel => {
                    if (next.state == .canceling or next.state == .activating or next.state == .published or next.state == .canceled) return;
                    if (next.state == .cutover) for (job.value.plan.targets) |target| {
                        if (target.graph_retirement_digest != null or target.generation_handoffs.len != 0) return;
                    };
                    next.state = .canceling;
                    next.completed_owners = 0;
                    next.revision += 1;
                },
                .publish, .finish_cancel => {
                    // The irreversible decision and exact owner activation
                    // receipts must precede target publication. A receipt is
                    // admitted only for its planned fence and publication.
                    const required = if (command.action == .finish_cancel)
                        (if (job.value.plan.preparing_sources) old_total else total + old_total + parent_total)
                    else if (parent_total + admission_total != 0)
                        parent_total + admission_total
                    else if (old_total != 0)
                        old_total
                    else
                        total;
                    if (next.completed_owners != required or
                        (command.action == .publish and next.state != (if (parent_total + admission_total != 0) restore_staging.State.activating else if (old_total != 0) restore_staging.State.cutover else .validating)) or
                        (command.action == .finish_cancel and next.state != .canceling)) return;
                    if (command.action == .publish) for (job.value.plan.targets) |target| if (target.replace) |old| {
                        for (old.ranges) |range| {
                            const graph_scope = restore_staging.graphSealScopeForOldRange(self.alloc, job.value.plan, job.value.plan_digest, target, range) catch |err| switch (err) {
                                error.OutOfMemory => return err,
                                else => return,
                            };
                            const graph_digest: ?[32]u8 = if (graph_scope) |scope| scope.sealDigest() catch return else null;
                            const handoff = restore_staging.generationHandoffForOldRange(target, range) catch return;
                            const expected: [32]u8 = if (handoff) |proof| blk: {
                                const fence = for (old.fences) |candidate| {
                                    if (candidate.owner_group_id == range.group_id) break candidate;
                                } else return;
                                const sealed = restore_staging.generationHandoffSealDigest(fence, job.value.plan_digest, proof) catch return;
                                break :blk restore_staging.generationHandoffOldFenceDigest(fence, sealed, graph_digest) catch return;
                            } else graph_digest orelse continue;
                            var graph_receipt_buf: [256]u8 = undefined;
                            const graph_receipt_key = try restore_staging.receiptKey(&graph_receipt_buf, group_id, command.id, .cutover, range.group_id);
                            const actual = (try stagingGet(txn, graph_receipt_key)) orelse return;
                            if (!std.mem.eql(u8, actual, &expected)) return;
                        }
                    };
                    // Verify reservations before publication; stale/corrupt
                    // ownership must never partially expose the target set.
                    for (job.value.plan.targets) |target| {
                        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                        const reservation = (try stagingGet(txn, try restore_staging.nameKey(&key_buf, group_id, target.table.name))) orelse return;
                        if (!std.mem.eql(u8, reservation, &command.id)) return;
                        const table_reservation = (try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .table, target.table.table_id))) orelse return;
                        if (!std.mem.eql(u8, table_reservation, &command.id)) return;
                        if (try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, target.table.table_id)) != null) return;
                        if (command.action == .publish and !try self.restoreReplacementMatchesTxn(txn, group_id, target)) return;
                        if (target.replace) |old| {
                            const reservation_owner = (try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .old_table, old.table.table_id))) orelse return;
                            if (!std.mem.eql(u8, reservation_owner, &command.id)) return;
                        }
                        for (target.ranges) |range| {
                            const group_reservation = (try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .group, range.group_id))) orelse return;
                            if (!std.mem.eql(u8, group_reservation, &command.id)) return;
                            if (try stagingGet(txn, try rangeKeyForGroup(&key_buf, group_id, range.group_id)) != null) return;
                        }
                    }
                    for (job.value.plan.external_fk_parents) |parent| {
                        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                        const reservation = (try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .parent_table, parent.table.table_id))) orelse return;
                        if (!std.mem.eql(u8, reservation, &command.id) or !try self.restoreExternalParentMatchesTxn(txn, group_id, parent)) return;
                        for (parent.ranges) |range| {
                            const group_reservation = (try stagingGet(txn, try restore_staging.identityKey(&key_buf, group_id, .parent_group, range.group_id))) orelse return;
                            if (!std.mem.eql(u8, group_reservation, &command.id)) return;
                        }
                    }
                    if (command.action == .publish and !try self.restoreIncomingDependenciesClosedTxn(txn, group_id, job.value.plan)) return;
                    var prepared_targets: std.ArrayList(PreparedTableRecordWrite) = .empty;
                    defer {
                        for (prepared_targets.items) |*prepared| prepared.deinit(self.alloc);
                        prepared_targets.deinit(self.alloc);
                    }
                    if (command.action == .publish) for (job.value.plan.targets) |target| {
                        var table = target.table;
                        table.restore_backup_id = "";
                        table.restore_location = "";
                        var table_key_buf: [256]u8 = undefined;
                        var prepared = (try self.prepareTableRecordTxnMode(txn, group_id, try tableKeyForGroup(&table_key_buf, group_id, table.table_id), table, false)) orelse return;
                        errdefer prepared.deinit(self.alloc);
                        try prepared_targets.append(self.alloc, prepared);
                    };
                    if (command.action == .publish) {
                        const delta = restoreCatalogDeltaTxn(catalog_arena.allocator(), txn, group_id, job.value.plan) catch |err| {
                            if (err == error.InvalidRestoreStaging) return;
                            return err;
                        };
                        try self.applyColumnSequenceHandoffsTxn(catalog_arena.allocator(), txn, group_id, job.value.plan);
                        if (delta.upserts.len != 0) {
                            const meta = try system_catalog_storage.readMeta(catalog_arena.allocator(), txn, group_id);
                            try self.applySystemCatalogDeltaTxn(catalog_arena.allocator(), txn, group_id, delta, meta, @splat(0));
                        }
                    }
                    // All table targets are admitted before removing any old
                    // generation. Record strings remain owned by the pinned
                    // restore plan throughout this transaction.
                    if (command.action == .publish) for (job.value.plan.targets, prepared_targets.items) |target, prepared| {
                        if (target.replace) |old| {
                            var removed: std.ArrayList(u64) = .empty;
                            defer removed.deinit(self.alloc);
                            for (old.ranges) |range| {
                                var key_buf: [256]u8 = undefined;
                                try txn.put(try restore_staging.identityKey(&key_buf, group_id, .group, range.group_id), &command.id);
                                try txn.delete(try rangeKeyForGroup(&key_buf, group_id, range.group_id));
                                try self.deleteTableRangeIndexTxn(txn, group_id, old.table.table_id, range.group_id);
                                try self.deleteActiveRestoreRangeIndexTxn(txn, group_id, range.group_id);
                                try removed.append(self.alloc, range.group_id);
                            }
                            var key_buf: [256]u8 = undefined;
                            const old_key = try tableKeyForGroup(&key_buf, group_id, old.table.table_id);
                            try txn.delete(old_key);
                            try self.deleteColumnIdentitiesTxn(txn, group_id, old.table.table_id);
                            try self.deleteTableNameIndexTxn(txn, group_id, old.table.name);
                            try self.advanceTableTransitionGenerationWithRangeChangesTxn(txn, group_id, old.table.table_id, &.{}, removed.items);
                            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = old_key });
                            self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group_id, .table_name = old.table.name, .table_id = old.table.table_id });
                            var successor: [24]u8 = undefined;
                            successor[0..16].* = command.id;
                            std.mem.writeInt(u64, successor[16..24], target.table.table_id, .little);
                            try txn.put(try restore_staging.identityKey(&key_buf, group_id, .old_table, old.table.table_id), &successor);
                        }
                        var table_key_buf: [256]u8 = undefined;
                        const table = prepared.identity;
                        try self.writePreparedTableRecordTxn(txn, group_id, try tableKeyForGroup(&table_key_buf, group_id, table.table_id), prepared);
                        if (target.sequence_handoffs.len != 0) try self.initializeColumnIdentitiesTxn(txn, group_id, target.table);
                        var added: std.ArrayList(u64) = .empty;
                        defer added.deinit(self.alloc);
                        for (target.ranges) |range| {
                            var owned_range = try metadata_table_manager.cloneRange(self.alloc, range);
                            defer metadata_table_manager.freeRange(self.alloc, owned_range);
                            if (owned_range.restore_backup_id.len != 0) try metadata_table_manager.clearOwnedRangeRestoreIntent(self.alloc, &owned_range);
                            const encoded = try encodeRangeRecord(self.alloc, owned_range);
                            defer self.alloc.free(encoded);
                            var range_buf: [256]u8 = undefined;
                            try txn.put(try rangeKeyForGroup(&range_buf, group_id, range.group_id), encoded);
                            try self.putTableRangeIndexTxn(txn, group_id, table.table_id, range.group_id);
                            try added.append(self.alloc, range.group_id);
                        }
                        try self.advanceTableTransitionGenerationWithRangeChangesTxn(txn, group_id, table.table_id, added.items, &.{});
                    };
                    for (job.value.plan.targets) |target| {
                        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                        try txn.delete(try restore_staging.nameKey(&key_buf, group_id, target.table.name));
                        // Canceled replacements keep the old generation live;
                        // published replacements retain its tombstone forever.
                        if (command.action == .finish_cancel) if (target.replace) |old| {
                            try txn.delete(try restore_staging.identityKey(&key_buf, group_id, .old_table, old.table.table_id));
                        };
                    }
                    if (command.action == .finish_cancel) for (job.value.plan.external_fk_parents) |parent| {
                        var key_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                        try txn.delete(try restore_staging.identityKey(&key_buf, group_id, .parent_table, parent.table.table_id));
                        for (parent.ranges) |range| try txn.delete(try restore_staging.identityKey(&key_buf, group_id, .parent_group, range.group_id));
                    };
                    // Keep ID tombstones and completion receipts: delayed
                    // import or cancel commands cannot target a new job.
                    next.state = if (command.action == .publish) .published else .canceled;
                    next.revision += 1;
                    var active_key_buf: [256]u8 = undefined;
                    try txn.delete(try restore_staging.activeKey(&active_key_buf, group_id, command.id));
                },
            }
            const value = try std.json.Stringify.valueAlloc(self.alloc, next, .{});
            defer self.alloc.free(value);
            try txn.put(progress_key, value);
        }
        if (source_tracked) {
            const next_digest = if (command.action == .reserve or command.action == .freeze_rewrite) blk: {
                const next_job = (try stagingGet(txn, job_key)) orelse return error.InvalidCatalogRecord;
                break :blk try relationRestoreSourceValueDigest(self.alloc, next_job, command.id);
            } else previous_source_digest.?;
            const next_active = try stagingGet(txn, namespace_active_key) != null;
            if (previous_source_digest == null or previous_active != next_active or
                !std.mem.eql(u8, &previous_source_digest.?, &next_digest)) try relation_reconciliation.advanceSource(txn, group_id);
        }
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = job_key });
        self.notifyProjectionListeners(.{ .kind = .restore_job, .metadata_group_id = group_id });
    }

    fn applyTableTopologyMutationTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        mutation: TableTopologyMutation,
    ) !void {
        return self.applyTableTopologyMutationWithSqlDropTxn(txn, group_id, mutation, false);
    }

    fn applyTableTopologyMutationWithSqlDropTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, mutation: TableTopologyMutation, generation_drop: bool) !void {
        switch (mutation) {
            .create => |create| {
                var arena = std.heap.ArenaAllocator.init(self.alloc);
                defer arena.deinit();
                const admitted = (try self.admittedResolverProjectionTxn(arena.allocator(), txn, group_id, create.table)) orelse return;
                if (try fk_generation_publication.schemaHasForeignKeys(self.alloc, create.table.schema_json)) return;
                if (try self.fkGenerationTableLockedTxn(txn, group_id, create.table.table_id)) return;
                if (!try self.relationalParentsExistForCreateTxn(txn, group_id, create.table, true)) return;
                const fence = try self.loadTableTransitionFenceTxn(
                    txn,
                    group_id,
                    create.table.table_id,
                );
                if (fence.active() or
                    fence.generation != create.expected_transition_generation) return;
                var name_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
                if (try stagingGet(txn, try fk_generation_publication.initialPhysicalNameKey(&name_buf, group_id, create.table.name)) != null) return;
                if (try stagingGet(txn, try tableNameIndexKey(&name_buf, group_id, create.table.name))) |owner| {
                    if (owner.len != 8 or std.mem.readInt(u64, owner[0..8], .little) != create.table.table_id) return;
                }

                var table_key_buf: [160]u8 = undefined;
                const table_key = try tableKeyForGroup(
                    &table_key_buf,
                    group_id,
                    create.table.table_id,
                );
                const encoded_table = txn.get(table_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (encoded_table) |encoded| {
                    const existing = try decodeTableRecord(self.alloc, encoded);
                    defer metadata_table_manager.freeTable(self.alloc, existing);
                    if (!metadata_table_manager.tableDefinitionsEqual(existing, admitted)) return;
                } else if (fence.range_membership.count != 0) {
                    // Atomic creates can only encounter existing ranges when
                    // replaying an already-created table. With no table row,
                    // membership belongs to an interrupted legacy drop and
                    // must never be adopted by a new incarnation.
                    return;
                }

                var unique_groups = std.AutoHashMapUnmanaged(u64, void).empty;
                defer unique_groups.deinit(self.alloc);
                try unique_groups.ensureTotalCapacity(self.alloc, @intCast(create.ranges.len));
                for (create.ranges) |record| {
                    if (unique_groups.contains(record.group_id)) return;
                    unique_groups.putAssumeCapacity(record.group_id, {});
                    if (encoded_table == null and try stagingGet(txn, try restore_staging.identityKey(&name_buf, group_id, .group, record.group_id)) != null) return;
                    if (encoded_table == null and try stagingGet(txn, try fk_generation_publication.initialGroupKey(&name_buf, group_id, record.group_id)) != null) return;
                    var range_key_buf: [160]u8 = undefined;
                    const range_key = try rangeKeyForGroup(&range_key_buf, group_id, record.group_id);
                    const encoded_range = txn.get(range_key) catch |err| switch (err) {
                        error.NotFound => continue,
                        else => return err,
                    };
                    if (encoded_table == null) return;
                    const existing = try decodeRangeRecord(self.alloc, encoded_range);
                    defer metadata_table_manager.freeRange(self.alloc, existing);
                    if (!metadata_table_manager.rangeRecordsEqual(existing, record)) return;
                }

                var changed = false;
                var added_range_group_ids = std.ArrayListUnmanaged(u64).empty;
                defer added_range_group_ids.deinit(self.alloc);
                if (encoded_table == null) {
                    if (!try self.tryPutTableRecordTxnMode(txn, group_id, table_key, admitted, false)) return;
                    changed = true;
                }
                // Atomic topology commands publish one table-scoped catalog
                // invalidation through putTableRecordTxn below. Per-range
                // lifecycle signals would clone the same table name and key
                // once per shard while every production consumer only treats
                // them as an epoch invalidation. Ordinary split/merge commands
                // retain their precise range signals.
                for (create.ranges) |record| {
                    var range_key_buf: [160]u8 = undefined;
                    const range_key = try rangeKeyForGroup(&range_key_buf, group_id, record.group_id);
                    const existing_range = txn.get(range_key) catch |err| switch (err) {
                        error.NotFound => null,
                        else => return err,
                    };
                    if (existing_range != null) continue;
                    changed = true;
                    const encoded_range = try encodeRangeRecord(self.alloc, record);
                    defer self.alloc.free(encoded_range);
                    try txn.put(range_key, encoded_range);
                    try self.putTableRangeIndexTxn(txn, group_id, record.table_id, record.group_id);
                    try self.updateActiveRestoreRangeIndexTxn(txn, group_id, record);
                    try added_range_group_ids.append(self.alloc, record.group_id);
                }
                if (changed) {
                    if (added_range_group_ids.items.len > 0) {
                        try self.advanceTableTransitionGenerationWithRangeChangesTxn(
                            txn,
                            group_id,
                            create.table.table_id,
                            added_range_group_ids.items,
                            &.{},
                        );
                    } else {
                        try self.advanceTableTransitionGenerationTxn(txn, group_id, create.table.table_id);
                    }
                    // A matching legacy table row may exist without the full
                    // atomic range set. New tables already emitted this signal
                    // through putTableRecordTxn; legacy completion needs the
                    // same single table-scoped invalidation here.
                    if (encoded_table != null) self.notifyProjectionListeners(.{
                        .kind = .table,
                        .metadata_group_id = group_id,
                        .table_name = create.table.name,
                        .table_id = create.table.table_id,
                    });
                }
            },
            .drop => |drop| {
                if (!generation_drop and try self.fkGenerationTableLockedTxn(txn, group_id, drop.table_id)) return;
                const fence = try self.loadTableTransitionFenceTxn(txn, group_id, drop.table_id);
                if (fence.active() or fence.generation != drop.expected_transition_generation) return;
                if (drop.range_contract == .membership and
                    !fence.membership(drop.table_id).eql(drop.range_contract.membership)) return;

                var table_key_buf: [160]u8 = undefined;
                const table_key = try tableKeyForGroup(&table_key_buf, group_id, drop.table_id);
                const encoded_table = txn.get(table_key) catch |err| switch (err) {
                    // Replaying an already-applied drop is an idempotent
                    // success. The caller verifies absence after its receipt.
                    error.NotFound => return,
                    else => return err,
                };
                const existing = try decodeTableRecord(self.alloc, encoded_table);
                defer metadata_table_manager.freeTable(self.alloc, existing);
                if (!std.mem.eql(u8, existing.name, drop.expected_name)) return;
                if (try self.extensionOwnsTableTxn(txn, group_id, existing.name)) return;
                // Recheck under the authoritative metadata transaction: an FK
                // can have been published since the DROP admission snapshot.
                if (!generation_drop and try self.relationalDropBlockedTxn(txn, group_id, existing)) return;

                var owned_range_group_ids: ?[]u64 = null;
                defer if (owned_range_group_ids) |ids| self.alloc.free(ids);
                var ranges_validated = false;
                const range_group_ids = switch (drop.range_contract) {
                    .membership => |membership| blk: {
                        owned_range_group_ids = (try self.compactDropRangeIdsTxn(
                            txn,
                            group_id,
                            drop.table_id,
                            membership,
                        )) orelse return;
                        ranges_validated = true;
                        break :blk owned_range_group_ids.?;
                    },
                    .legacy_group_ids => |ids| blk: {
                        // V1 carried the full set directly. Recompute its
                        // compact proof so a malformed legacy entry cannot
                        // omit a range and orphan it when deleting the table.
                        var membership: topology_protocol.RangeMembershipAccumulator = .{};
                        for (ids) |range_group_id| try membership.add(range_group_id);
                        if (!membership.finish(drop.table_id).eql(fence.membership(drop.table_id)))
                            return;
                        break :blk ids;
                    },
                };

                // The generation CAS proves that no legitimate membership
                // mutation occurred after admission. The fixed-size digest
                // validates the local table-keyed index, whose rare repair
                // path falls back to the primary range projection.
                if (!ranges_validated) {
                    for (range_group_ids) |range_group_id| {
                        var range_key_buf: [160]u8 = undefined;
                        const range_key = try rangeKeyForGroup(&range_key_buf, group_id, range_group_id);
                        const encoded_range = txn.get(range_key) catch |err| switch (err) {
                            error.NotFound => return,
                            else => return err,
                        };
                        const record = try decodeRangeRecord(self.alloc, encoded_range);
                        defer metadata_table_manager.freeRange(self.alloc, record);
                        if (record.table_id != drop.table_id) return;
                    }
                }
                // The table deletion below is the single catalog/lifecycle
                // invalidation for this atomic topology change. Avoid queuing
                // O(range_count) duplicate owned notifications while the
                // metadata apply mutex is held.
                for (range_group_ids) |range_group_id| {
                    var range_key_buf: [160]u8 = undefined;
                    const range_key = try rangeKeyForGroup(&range_key_buf, group_id, range_group_id);
                    try txn.delete(range_key);
                    try self.deleteTableRangeIndexTxn(txn, group_id, drop.table_id, range_group_id);
                    try self.deleteActiveRestoreRangeIndexTxn(txn, group_id, range_group_id);
                }
                try self.removeSystemCatalogTableTxn(txn, group_id, drop.table_id);
                try txn.delete(table_key);
                try self.deleteColumnIdentitiesTxn(txn, group_id, drop.table_id);
                try relation_reconciliation.advanceTrackedSource(txn, group_id);
                var fingerprint_key_buf: [192]u8 = undefined;
                txn.delete(try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group_id, drop.table_id)) catch |err| switch (err) {
                    error.NotFound => {}, // Older table records may predate the fingerprint index.
                    else => return err,
                };
                try self.deleteTableNameIndexTxn(txn, group_id, existing.name);
                try self.advanceTableTransitionGenerationWithRangeChangesTxn(
                    txn,
                    group_id,
                    drop.table_id,
                    &.{},
                    range_group_ids,
                );
                self.notifyCommittedKeyListeners(.{
                    .metadata_group_id = group_id,
                    .key = table_key,
                });
                self.notifyProjectionListeners(.{
                    .kind = .table,
                    .metadata_group_id = group_id,
                    .table_name = existing.name,
                    .table_id = drop.table_id,
                });
            },
        }
    }

    fn extensionOwnsTableTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_name: []const u8,
    ) !bool {
        _ = self;
        var prefix_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        const prefix = try extensionTableOwnerIndexPrefixForTable(&prefix_buf, group_id, table_name);
        var cursor = try txn.openCursor();
        defer cursor.close();
        const entry = try cursor.seekAtOrAfter(prefix);
        return if (entry) |row| std.mem.startsWith(u8, row.key, prefix) else false;
    }

    fn applyReplicationSourceStatusUpsertTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.ReplicationSourceStatusRecord,
    ) !void {
        var key_buf: [224]u8 = undefined;
        const key = try replicationSourceStatusKeyForGroup(
            &key_buf,
            group_id,
            record.table_id,
            record.source_ordinal,
        );
        const encoded_existing = txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (encoded_existing) |encoded| {
            const existing = try decodeReplicationSourceStatusRecord(self.alloc, encoded);
            defer metadata_table_manager.freeReplicationSourceStatus(self.alloc, existing);
            if (existing.cutover_authority_id != 0) {
                if (!replicationCutoverAuthorityIdentityEqual(existing, record))
                    return;
                if (!replicationCutoverRetirementEqual(existing, record))
                    return;
            }
            if (existing.cutover_authority_id == 0 and
                record.cutover_authority_id != 0)
                return;
        } else if (record.cutover_authority_id != 0) {
            // Exact cutover authority is admitted only through the catalog- and
            // prior-authority-CAS command below.
            return;
        }
        try self.putReplicationSourceStatusTxn(txn, group_id, key, record);
    }

    fn applyReplicationSourceCutoverClaimTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        expected_replication_sources_json: []const u8,
        expected_authority_id: u64,
        record: metadata.ReplicationSourceStatusRecord,
    ) !void {
        var table_key_buf: [160]u8 = undefined;
        const table_key = try tableKeyForGroup(
            &table_key_buf,
            group_id,
            record.table_id,
        );
        const encoded_table = txn.get(table_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        const table = try decodeTableRecord(self.alloc, encoded_table);
        defer metadata_table_manager.freeTable(self.alloc, table);
        if (!std.mem.eql(
            u8,
            table.replication_sources_json,
            expected_replication_sources_json,
        )) return;

        var status_key_buf: [224]u8 = undefined;
        const status_key = try replicationSourceStatusKeyForGroup(
            &status_key_buf,
            group_id,
            record.table_id,
            record.source_ordinal,
        );
        const encoded_existing = txn.get(status_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (encoded_existing) |encoded| {
            const existing = try decodeReplicationSourceStatusRecord(self.alloc, encoded);
            defer metadata_table_manager.freeReplicationSourceStatus(self.alloc, existing);
            if (replicationCutoverAuthorityIdentityEqual(existing, record)) {
                if (!replicationCutoverRetirementEqual(existing, record)) return;
                // Provider cleanup can legitimately fail after authority is
                // claimed but before any snapshot checkpoint exists. Permit
                // that exact authority to retry preparation, while refusing
                // to roll an advanced snapshot/streaming status backward.
                if (std.mem.eql(u8, existing.phase, "failed") and
                    std.mem.eql(
                        u8,
                        existing.cutover_mode,
                        "exported_snapshot_pending",
                    ) and
                    existing.snapshot_offset == 0 and
                    existing.prepared_checkpoint.len == 0 and
                    existing.stream_checkpoint.len == 0)
                {
                    try self.putReplicationSourceStatusTxn(
                        txn,
                        group_id,
                        status_key,
                        record,
                    );
                }
                return;
            }
            if (existing.cutover_authority_id != expected_authority_id or
                existing.retired_cutover_authority_id != 0 or
                record.cutover_authority_id == expected_authority_id)
                return;
            if (expected_authority_id == 0) {
                if (record.retired_cutover_authority_id != 0 or
                    record.retired_slot_name.len != 0 or
                    record.retired_publication_name.len != 0)
                    return;
            } else if (record.retired_cutover_authority_id != expected_authority_id or
                !std.mem.eql(u8, record.retired_slot_name, existing.slot_name) or
                !std.mem.eql(
                    u8,
                    record.retired_publication_name,
                    existing.publication_name,
                ))
            {
                return;
            }
        } else if (expected_authority_id != 0 or
            record.retired_cutover_authority_id != 0 or
            record.retired_slot_name.len != 0 or
            record.retired_publication_name.len != 0)
        {
            return;
        }
        try self.putReplicationSourceStatusTxn(txn, group_id, status_key, record);
    }

    fn applyReplicationSourceRetirementCompletionTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        expected: metadata.ReplicationSourceStatusRecord,
    ) !void {
        var key_buf: [224]u8 = undefined;
        const key = try replicationSourceStatusKeyForGroup(
            &key_buf,
            group_id,
            expected.table_id,
            expected.source_ordinal,
        );
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        var current = try decodeReplicationSourceStatusRecord(
            self.alloc,
            encoded,
        );
        defer metadata_table_manager.freeReplicationSourceStatus(
            self.alloc,
            current,
        );
        if (!replicationCutoverAuthorityIdentityEqual(current, expected) or
            !replicationCutoverRetirementEqual(current, expected))
            return;

        const retired_authority_id = current.retired_cutover_authority_id;
        const retired_slot_name = current.retired_slot_name;
        const retired_publication_name = current.retired_publication_name;
        defer {
            current.retired_cutover_authority_id = retired_authority_id;
            current.retired_slot_name = retired_slot_name;
            current.retired_publication_name = retired_publication_name;
        }
        current.retired_cutover_authority_id = 0;
        current.retired_slot_name = "";
        current.retired_publication_name = "";
        current.updated_at_ms = @max(current.updated_at_ms, expected.updated_at_ms);
        try self.putReplicationSourceStatusTxn(txn, group_id, key, current);
    }

    fn putReplicationSourceStatusTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        key: []const u8,
        record: metadata.ReplicationSourceStatusRecord,
    ) !void {
        const table_name = try self.lookupTableNameTxn(txn, group_id, record.table_id);
        defer if (table_name) |name| self.alloc.free(name);
        const value = try encodeReplicationSourceStatusRecord(self.alloc, record);
        defer self.alloc.free(value);
        try txn.put(key, value);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .replication_source_status,
            .metadata_group_id = group_id,
            .table_name = table_name,
            .table_id = record.table_id,
        });
    }

    /// Validate name authorization in the same transaction that replaces the
    /// table. A current root is required, but unrelated source revisions do
    /// not invalidate an unchanged owner or logical binding.
    const GuardedRelationOwner = struct {
        namespace_id: u64,
        binding: ?std.json.Parsed(system_catalog.Resource),

        fn deinit(self: *@This()) void {
            if (self.binding) |*value| value.deinit();
        }
        fn physicalName(self: *const @This(), guard: system_catalog.RelationMutationGuard) []const u8 {
            return if (self.binding) |value| value.value.storage_name else guard.logical_table;
        }
    };

    /// The common indexed ownership boundary for reads and writes. It never
    /// decodes table/schema JSON, scans schemas or grants a mutation lease.
    fn guardedRelationOwnerTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        guard: system_catalog.RelationMutationGuard,
    ) !GuardedRelationOwner {
        try guard.validate();
        const required = if (guard.constraint_name_admission != null) topology_protocol.constraint_occupancy_version else topology_protocol.relation_mutation_version;
        const activation = try self.standbyRelationActivationTxn(txn, group_id, required);
        if (activation.version < required) return error.TableTopologyProtocolUpgradeRequired;
        const epoch = try relationSourceEpochTxn(txn, group_id);
        if (!std.mem.eql(u8, &guard.incarnation, &epoch.incarnation)) return error.CatalogGenerationChanged;
        var live = (try relation_reconciliation.LiveStore(docstore.DocStore.Txn).open(txn, group_id)) orelse return error.CatalogPublicationProofPending;
        if (activation.version < relation_control.publicationVersion(live.root.coverage)) return error.TableTopologyProtocolUpgradeRequired;
        if (!live.root.epoch.eql(epoch)) return error.CatalogGenerationChanged;
        const namespace_id = (try resolveSystemCatalogNamespaceTxn(self.alloc, txn, group_id, guard.target.database, guard.target.namespace)) orelse return error.CatalogGenerationChanged;
        const owner = (try live.getClaim(.{ .namespace_id = namespace_id, .name = guard.target.name })) orelse return error.CatalogGenerationChanged;
        if (!owner.eql(guard.owner)) return error.CatalogGenerationChanged;
        var binding = try system_catalog_storage.getById(self.alloc, txn, group_id, .table, owner.table_id);
        errdefer if (binding) |*value| value.deinit();
        if (binding) |value| {
            if (value.value.parent_id != namespace_id or !std.mem.eql(u8, value.value.name, guard.logical_table) or
                value.value.storage_name.len == 0) return error.CatalogGenerationChanged;
        } else if (namespace_id != system_catalog.default_namespace_id) return error.CatalogGenerationChanged;
        return .{ .namespace_id = namespace_id, .binding = binding };
    }

    fn validateRelationMutationTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        guard: system_catalog.RelationMutationGuard,
        expected: metadata.TableRecord,
        replacement: metadata.TableRecord,
    ) !void {
        if (guard.owner.table_id != expected.table_id) return error.InvalidCatalogMutation;
        var scope = try self.guardedRelationOwnerTxn(txn, group_id, guard);
        defer scope.deinit();
        if (!std.mem.eql(u8, scope.physicalName(guard), expected.name)) return error.CatalogGenerationChanged;
        if (guard.constraint_name_admission) |admission|
            try self.validateConstraintNameOccupancyTxn(self.alloc, txn, group_id, admission, scope.namespace_id, replacement.schema_json);
        // Extension ownership is independently mutable. Recheck its exact
        // table-local index in this write transaction, not a preflight snapshot.
        var prefix_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        const prefix = try extensionTableOwnerIndexPrefixForTable(&prefix_buf, group_id, expected.name);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        if (row == null or !std.mem.startsWith(u8, row.?.key, prefix)) return;
        var ownership = try @import("../../extensions/table_ownership.zig").DefinitionMutationGuard.init(self.alloc, expected, replacement);
        defer ownership.deinit();
        while (row) |entry| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            var member = try decodeExtensionMemberRecord(self.alloc, try txn.get(entry.value));
            defer member.deinitOwned(self.alloc);
            if (try ownership.touches(member)) return error.ExtensionOwnedObject;
        }
    }

    fn getTableTxn(_: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, table: u64) !?metadata.TableRecord {
        var buffer: [160]u8 = undefined;
        const bytes = try stagingGet(txn, try tableKeyForGroup(&buffer, group, table));
        return if (bytes) |value| try decodeTableRecord(alloc, value) else null;
    }

    /// Read-only binding also works before first column-identity bootstrap.
    /// Only the subsequent guarded committed writer may persist that state.
    pub fn getSqlColumnIdentities(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, guard: system_catalog.RelationMutationGuard) !std.json.Parsed(column_identities.State) {
        var txn = try self.beginQueryCatalogReadTxn(group);
        defer txn.abort();
        const table = (try self.getTableTxn(self.alloc, &txn, group, guard.owner.table_id)) orelse return error.CatalogGenerationChanged;
        defer metadata_table_manager.freeTable(self.alloc, table);
        try self.validateRelationMutationTxn(&txn, group, guard, table, table);
        return self.columnDescriptionStateTxn(alloc, &txn, group, table);
    }

    fn columnDescriptionStateTxn(self: *RaftApplyStore, alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, table: metadata.TableRecord) !std.json.Parsed(column_identities.State) {
        _ = self;
        const key = try column_identities.key(.{ .group = group, .table = table.table_id });
        const existing = try stagingGet(txn, &key);
        if (existing) |bytes| {
            var buffer: [160]u8 = undefined;
            const raw = try txn.get(try tableKeyForGroup(&buffer, group, table.table_id));
            try validateColumnIdentityRecord(alloc, .{ .group = group, .table = table.table_id }, bytes, raw);
        }
        const bootstrap = if (existing == null) try columnIdentityValue(alloc, table, null, &.{}) else null;
        defer if (bootstrap) |bytes| alloc.free(bytes);
        return column_identities.State.decode(alloc, existing orelse bootstrap.?);
    }

    fn prepareColumnDescriptionTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: ColumnDescriptionCommand) ![]u8 {
        try command.validate();
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_column_comments_version);
        const table = (try self.getTableTxn(self.alloc, txn, group, command.guard.owner.table_id)) orelse return error.CatalogGenerationChanged;
        defer metadata_table_manager.freeTable(self.alloc, table);
        try self.validateRelationMutationTxn(txn, group, command.guard, table, table);
        var state = try self.columnDescriptionStateTxn(self.alloc, txn, group, table);
        defer state.deinit();
        if (!std.meta.eql(state.value.epoch, command.epoch)) return error.CatalogGenerationChanged;
        const column = state.value.columnById(command.column_id) orelse return error.CatalogGenerationChanged;
        if (!std.mem.eql(u8, column.name, command.column.name)) return error.CatalogGenerationChanged;
        return state.value.encodeDescription(self.alloc, command.column_id, command.column.value);
    }

    fn applyColumnDescriptionTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: ColumnDescriptionCommand) !void {
        const bytes = try self.prepareColumnDescriptionTxn(txn, group, command);
        defer self.alloc.free(bytes);
        const key = try column_identities.key(.{ .group = group, .table = command.guard.owner.table_id });
        if (try stagingGet(txn, &key)) |old| if (std.mem.eql(u8, old, bytes)) return;
        try txn.put(&key, bytes);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group, .key = &key });
    }

    fn applyTableCompareAndReplaceTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        expected: metadata.TableRecord,
        replacement: metadata.TableRecord,
    ) !void {
        // A standalone replicated CAS intentionally treats a rejected proposal
        // as a deterministic no-op. Compound publications must inspect the
        // outcome instead of publishing their dependent catalog effects.
        _ = try self.tryApplyTableCompareAndReplaceTxn(txn, group_id, expected, replacement);
    }

    fn tryApplyTableCompareAndReplaceTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        expected: metadata.TableRecord,
        replacement: metadata.TableRecord,
    ) !bool {
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, expected.table_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        const current = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, current);
        if (!metadata_table_manager.tableDefinitionsEqual(current, expected)) return false;
        {
            var arena = std.heap.ArenaAllocator.init(self.alloc);
            defer arena.deinit();
            const a = arena.allocator();
            if (!try resolverNamespaceAdoptionAllowedTxn(txn, group_id, a, current, replacement) or !try self.resolverProjectionValidTxn(a, txn, group_id, replacement)) {
                try txn.put(try resolverRejectionKey(a, group_id, expected.table_id), try std.json.Stringify.valueAlloc(a, ResolverRejection{
                    .digest = try resolverReplacementDigest(a, expected, replacement),
                    .term = self.active_resolver_apply_position.term,
                    .index = self.active_resolver_apply_position.index,
                }, .{}));
                return false;
            }
            try txn.delete(try resolverRejectionKey(a, group_id, expected.table_id));
        }

        if (metadata_table_manager.tableDefinitionsEqual(current, replacement)) {
            try self.advanceResolverNamespaceTxn(txn, group_id, current);
            return true;
        }
        metadata_table_manager.validateObjectTableMutation(self.alloc, current, replacement) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return false,
        };
        const lake_transition_allowed = @import("antfly_local_sources").metadata_lake_index_catalog.transitionAllowed(self.alloc, current, replacement) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => false,
        };
        if (!lake_transition_allowed) return false;
        if (replacement.lake_index_catalog_json.len != 0 or current.lake_index_catalog_json.len != 0) {
            var arena = std.heap.ArenaAllocator.init(self.alloc);
            defer arena.deinit();
            const a = arena.allocator();
            const lifecycle = @import("../lake_index_lifecycle.zig");
            const state = try self.loadLakeIndexLifecycleTxn(a, txn, group_id, current.table_id);
            var catalog_state = try @import("antfly_local_sources").metadata_lake_index_catalog.parse(a, replacement.lake_index_catalog_json);
            defer catalog_state.deinit();
            const next = state.synchronize(a, catalog_state.value) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return false,
            };
            _ = lifecycle.encode(a, next) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return false,
            };
        }
        if (!try self.policyDefinitionMutationAllowedTxn(txn, group_id, current, replacement)) return false;
        var admission = replacement;
        // A completed subtract-only retirement changes active policy, not
        // historical row/index decoding. Old read-schema FK declarations
        // must not resurrect a retired generation at final publication.
        if (try @import("../relational_retirement.zig").permitsSchema(self.alloc, current, replacement)) admission.read_schema_json = "";
        if (!try self.relationalParentsExistTxn(txn, group_id, admission)) return false;
        if (!try @import("../relational_retirement.zig").transitionAllowed(self.alloc, current, replacement)) return false;
        if (replacement.relational_retirement_json.len != 0) {
            var retirement = try @import("../relational_retirement.zig").parse(self.alloc, replacement.relational_retirement_json);
            defer retirement.deinit();
            if (current.relational_retirement_json.len == 0) {
                var target = current;
                target.schema_json = retirement.value.target_schema_json;
                target.read_schema_json = "";
                if (!try self.relationalParentsExistTxn(txn, group_id, target)) return false;
                var retirement_prefix_buf: [128]u8 = undefined;
                const retirement_prefix = try tablePrefixForGroup(&retirement_prefix_buf, group_id);
                var retirement_cursor = try txn.openCursor();
                defer retirement_cursor.close();
                var candidate_row = try retirement_cursor.seekAtOrAfter(retirement_prefix);
                while (candidate_row) |row| : (candidate_row = try retirement_cursor.next()) {
                    if (!std.mem.startsWith(u8, row.key, retirement_prefix)) break;
                    const candidate = try decodeTableRecord(self.alloc, row.value);
                    defer metadata_table_manager.freeTable(self.alloc, candidate);
                    const external = candidate.table_id != current.table_id;
                    for ([_][]const u8{ if (external) candidate.schema_json else target.schema_json, if (external) candidate.read_schema_json else "" }) |schema| {
                        if (!try @import("../relational_retirement.zig").incomingAllowed(self.alloc, current.name, current.schema_json, retirement.value, schema, external)) return false;
                    }
                }
            }
            const owners = try self.indexedTableRangeIdsTxn(self.alloc, txn, group_id, current.table_id);
            defer self.alloc.free(owners);
            if (owners.len != retirement.value.owners.len) return false;
            for (retirement.value.owners) |owner| {
                var range_key_buf: [160]u8 = undefined;
                const range_key = try rangeKeyForGroup(&range_key_buf, group_id, owner.group_id);
                const raw_range = txn.get(range_key) catch |err| switch (err) {
                    error.NotFound => return false,
                    else => return err,
                };
                const range = try decodeRangeRecord(self.alloc, raw_range);
                defer metadata_table_manager.freeRange(self.alloc, range);
                if (range.table_id != current.table_id or range.range_id != owner.range_id or !std.mem.eql(u8, range.start_key, owner.start) or
                    !std.mem.eql(u8, range.end_key orelse "", owner.end)) return false;
            }
        }
        if (!std.mem.eql(u8, current.name, replacement.name) and
            try self.relationalDropBlockedTxn(txn, group_id, current)) return false;
        if (!try self.relationalDefinitionsRetainedForMutationTxn(txn, group_id, current, replacement)) return false;
        if ((try self.loadTableTransitionFenceTxn(txn, group_id, expected.table_id)).active()) return false;
        if (metadata_table_manager.tableDefinitionsEqual(current, replacement)) return true;
        return self.tryPutTableRecordTxnMode(txn, group_id, key, replacement, false);
    }

    fn synchronizeResolverTableRecordTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, key: []const u8, record: metadata.TableRecord) !void {
        const encoded_existing = try stagingGet(txn, key);
        {
            var dependency_arena = std.heap.ArenaAllocator.init(self.alloc);
            defer dependency_arena.deinit();
            const a = dependency_arena.allocator();
            const previous = if (encoded_existing) |bytes| try decodeTableRecord(a, bytes) else null;
            try self.synchronizeResolverDependenciesTxn(a, txn, group_id, previous, record);
        }
        if (record.indexes_json.len > 0) {
            var arena = std.heap.ArenaAllocator.init(self.alloc);
            defer arena.deinit();
            const a = arena.allocator();
            const root = try std.json.parseFromSliceLeaky(std.json.Value, a, record.indexes_json, .{});
            if (root == .object and root.object.contains(resolver_curation.namespaces_key)) {
                const next = try resolver_curation.namespacesFromValue(a, root);
                const prior = if (encoded_existing) |old| blk: {
                    const table = try decodeTableRecord(a, old);
                    break :blk if (table.indexes_json.len == 0) resolver_curation.Namespaces{} else try resolver_curation.namespacesFromValue(a, try std.json.parseFromSliceLeaky(std.json.Value, a, table.indexes_json, .{}));
                } else resolver_curation.Namespaces{};
                if (!std.mem.eql(u8, try std.json.Stringify.valueAlloc(a, prior, .{}), try std.json.Stringify.valueAlloc(a, next, .{}))) {
                    try enqueueResolverNamespaceTxn(a, txn, group_id, record.table_id);
                }
            }
        }
    }

    fn relationalDefinitionsRetained(self: *RaftApplyStore, previous: metadata.TableRecord, next: metadata.TableRecord) !bool {
        if (try @import("../relational_retirement.zig").permitsSchema(self.alloc, previous, next)) return true;
        if (try @import("../relational_retirement.zig").permitsMigrationCleanup(self.alloc, previous, next)) return true;
        for ([_][]const u8{ previous.schema_json, previous.read_schema_json }) |schema| {
            var old = try RelationalDeclarations.parse(self.alloc, schema);
            defer old.deinit();
            if (!old.value.coordinated()) continue;
            const retained = @import("antfly_local_sources").schema_relational_foreign_key_target.retains(self.alloc, schema, next.schema_json) catch |err| {
                if (err == error.OutOfMemory) return err;
                return false;
            };
            if (!retained) return false;
        }
        return true;
    }

    fn relationalDefinitionsRetainedForMutationTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        previous: metadata.TableRecord,
        next: metadata.TableRecord,
    ) !bool {
        if (try self.relationalDefinitionsRetained(previous, next)) return true;
        // A coordinated FK generation may already have published the new
        // schema while its old read layout remains live. Once every owner has
        // durably acknowledged that exact schema, the canonical migration
        // finalizer may retire only the old read layout. This is not authority
        // to remove a declaration from the current schema.
        if (previous.read_schema_json.len == 0 or
            previous.table_id != next.table_id or
            !std.mem.eql(u8, previous.schema_json, next.schema_json)) return false;
        var finalized = try metadata_table_manager.cloneTable(self.alloc, previous);
        defer metadata_table_manager.freeTable(self.alloc, finalized);
        try @import("../schema_migration_finalization.zig").apply(self.alloc, &finalized);
        if (!metadata_table_manager.tableDefinitionsEqual(finalized, next)) return false;
        return self.schemaMigrationReadyTxn(txn, group_id, next.table_id, try @import("../../api/tables.zig").schemaVersion(previous.schema_json));
    }

    const RelationalDeclarations = struct {
        unique_constraints: ?[]const struct {} = null,
        foreign_keys: ?[]const struct { parent_table: []const u8 = "" } = null,

        fn parse(alloc: std.mem.Allocator, schema: []const u8) !std.json.Parsed(RelationalDeclarations) {
            return std.json.parseFromSlice(RelationalDeclarations, alloc, if (schema.len == 0) "{}" else schema, .{
                .ignore_unknown_fields = true,
            });
        }

        fn coordinated(self: RelationalDeclarations) bool {
            return (if (self.unique_constraints) |items| items.len else 0) != 0 or
                (if (self.foreign_keys) |items| items.len else 0) != 0;
        }

        fn references(self: RelationalDeclarations, table_name: []const u8) bool {
            for (self.foreign_keys orelse &.{}) |fk| {
                if (std.mem.eql(u8, fk.parent_table, table_name)) return true;
            }
            return false;
        }
    };

    /// No coordinated table may be removed until durable claim/reference
    /// retirement exists. Incoming references are checked from primary catalog
    /// rows, not an asynchronously maintained dependency projection. The cursor
    /// retains one table at a time and exits at the first dependency.
    fn relationalDropBlockedTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table: metadata.TableRecord,
    ) !bool {
        try @import("../schema_validation_dependencies.zig").requireUnleased(txn, group_id, table.table_id);
        if (try sql_views.firstDependent(txn, group_id, .table, table.table_id, null)) |dependent| {
            const attributes: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = txn, .group_id = group_id };
            var state = (try attributes.load(self.alloc, table.table_id)) orelse return error.InvalidSqlViewRecord;
            defer state.deinit();
            try self.verifySqlViewDependencyTxn(txn, group_id, table.table_id, 0, dependent, state.value);
            return true;
        }
        if (try backupCohortLocksTableTxn(txn, group_id, table.table_id) or try restoreStagingLocksTableTxn(txn, group_id, table.table_id)) return true;
        const retirement_ready = try @import("../relational_retirement.zig").permitsDrop(self.alloc, table);
        for ([_][]const u8{ table.schema_json, table.read_schema_json }) |schema| {
            var declarations = try RelationalDeclarations.parse(self.alloc, schema);
            defer declarations.deinit();
            if (declarations.value.coordinated() and !retirement_ready) return true;
        }
        var prefix_buf: [128]u8 = undefined;
        const prefix = try tablePrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix)) break;
            const candidate = try decodeTableRecord(self.alloc, row.value);
            defer metadata_table_manager.freeTable(self.alloc, candidate);
            if (retirement_ready and candidate.table_id == table.table_id) continue;
            for ([_][]const u8{ candidate.schema_json, candidate.read_schema_json }) |schema| {
                var declarations = try RelationalDeclarations.parse(self.alloc, schema);
                defer declarations.deinit();
                if (declarations.value.references(table.name)) return true;
            }
        }
        return false;
    }

    fn relationalParentsExistTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table: metadata.TableRecord,
    ) !bool {
        return self.relationalParentsExistForCreateTxn(txn, group_id, table, false);
    }

    fn relationalParentsExistForCreateTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table: metadata.TableRecord, explicit_create: bool) !bool {
        @import("antfly_local_sources").schema_relational_index_namespace.validate(self.alloc, table.schema_json, table.indexes_json) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return false,
        };
        if (try backupCohortLocksTableTxn(txn, group_id, table.table_id) or try restoreStagingLocksTableTxn(txn, group_id, table.table_id)) return false;
        var staging_buf: [catalog_name_key_buffer_bytes]u8 = undefined;
        if (try stagingGet(txn, try restore_staging.nameKey(&staging_buf, group_id, table.name)) != null) return false;
        if (try stagingGet(txn, try restore_staging.identityKey(&staging_buf, group_id, .table, table.table_id))) |reservation| {
            if (try stagingGet(txn, try tableKeyForGroup(&staging_buf, group_id, table.table_id)) == null) {
                if (!explicit_create or reservation.len != 16) return false;
                const id: restore_staging.Id = reservation[0..16].*;
                const raw_progress = (try stagingGet(txn, try restore_staging.progressKey(&staging_buf, group_id, id))) orelse return false;
                var progress = try std.json.parseFromSlice(restore_staging.Progress, self.alloc, raw_progress, .{});
                defer progress.deinit();
                if (progress.value.state != .published) return false;
            }
        }
        for ([_][]const u8{ table.schema_json, table.read_schema_json }) |schema| {
            var declarations = try RelationalDeclarations.parse(self.alloc, schema);
            defer declarations.deinit();
            for (declarations.value.foreign_keys orelse &.{}) |fk| {
                if (std.mem.eql(u8, fk.parent_table, table.name)) {
                    if (!try self.relationalTargetValid(schema, table.name, table.schema_json)) return false;
                    continue;
                }
                var prefix_buf: [128]u8 = undefined;
                const prefix = try tablePrefixForGroup(&prefix_buf, group_id);
                var cursor = try txn.openCursor();
                defer cursor.close();
                var entry = try cursor.seekAtOrAfter(prefix);
                var found = false;
                while (entry) |row| : (entry = try cursor.next()) {
                    if (!std.mem.startsWith(u8, row.key, prefix)) break;
                    const candidate = try decodeTableRecord(self.alloc, row.value);
                    defer metadata_table_manager.freeTable(self.alloc, candidate);
                    if (std.mem.eql(u8, fk.parent_table, candidate.name)) {
                        if (try backupCohortLocksTableTxn(txn, group_id, candidate.table_id)) return false;
                        if (try restoreStagingLocksTableTxn(txn, group_id, candidate.table_id)) return false;
                        if (try stagingGet(txn, try restore_staging.nameKey(&staging_buf, group_id, candidate.name)) != null) return false;
                        if (candidate.relational_retirement_json.len != 0) return false;
                        if (!try self.relationalTargetValid(schema, candidate.name, candidate.schema_json)) return false;
                        found = true;
                        break;
                    }
                }
                if (!found) return false;
            }
        }
        // Changing a parent column's type must not publish an incompatible
        // definition between child admission and activation. Revalidate every
        // incoming edge against the proposed parent in the same transaction.
        var prefix_buf: [128]u8 = undefined;
        const prefix = try tablePrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix)) break;
            const candidate = try decodeTableRecord(self.alloc, row.value);
            defer metadata_table_manager.freeTable(self.alloc, candidate);
            if (candidate.table_id == table.table_id) continue;
            for ([_][]const u8{ candidate.schema_json, candidate.read_schema_json }) |schema| {
                var declarations = try RelationalDeclarations.parse(self.alloc, schema);
                defer declarations.deinit();
                if (declarations.value.references(table.name) and
                    !try self.relationalTargetValid(schema, table.name, table.schema_json)) return false;
            }
        }
        return true;
    }

    fn relationalTargetValid(self: *RaftApplyStore, child: []const u8, parent_name: []const u8, parent: []const u8) !bool {
        @import("antfly_local_sources").schema_relational_foreign_key_target.validate(self.alloc, child, parent_name, parent) catch |err| {
            if (err == error.OutOfMemory) return err;
            // Invalid declarations deterministically reject the proposal;
            // they must not turn into a permanently failing Raft apply loop.
            return false;
        };
        return true;
    }

    fn putTableRecordTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        key: []const u8,
        record: metadata.TableRecord,
    ) !void {
        return self.putTableRecordTxnMode(txn, group_id, key, record, false);
    }

    fn resolverAdmissionRejected(err: anyerror) bool {
        return switch (err) {
            error.InvalidResolverAliasCycle, error.ResolverDistinctPair, error.SuppressedResolverRedirectTarget => true,
            else => false,
        };
    }
    /// Namespace projection must not silently discard a newly requested source
    /// correction. Config-only writes and unchanged legacy metadata may still
    /// inherit authority; edited unowned policy must use the entity API instead.
    fn resolverSourceCurationAllowedTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord, root: std.json.Value) !bool {
        const next = try resolver_curation.metadataFromValue(a, root);
        var previous: ?resolver_curation.Metadata = null;
        var prior_names: std.StringHashMapUnmanaged(resolver_curation.MetadataIdentity) = .empty;
        var destinations: std.StringHashMapUnmanaged(std.ArrayListUnmanaged([]const u8)) = .empty;
        for (next.identities) |identity| {
            if (identity.dropped or identity.namespace_owned) continue;
            if (previous == null) {
                var key_buf: [160]u8 = undefined;
                previous = .{};
                if (try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, record.table_id))) |bytes| {
                    const old = try decodeTableRecord(a, bytes);
                    if (old.indexes_json.len > 0) previous = try resolver_curation.metadataFromValue(a, try std.json.parseFromSliceLeaky(std.json.Value, a, old.indexes_json, .{}));
                }
                for (previous.?.identities) |prior| try prior_names.put(a, prior.name, prior);
            }
            const unchanged = if (prior_names.get(identity.name)) |prior|
                std.mem.eql(u8, try std.json.Stringify.valueAlloc(a, prior, .{}), try std.json.Stringify.valueAlloc(a, identity, .{}))
            else
                false;
            if (unchanged) continue;
            const entry = try destinations.getOrPut(a, identity.table);
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            try entry.value_ptr.append(a, identity.key_template);
        }
        // Resolve and parse each destination once. Its catalog/evidence is
        // released before the next destination; only query identities persist.
        var targets = destinations.iterator();
        while (targets.next()) |target| {
            var scratch_arena = std.heap.ArenaAllocator.init(self.alloc);
            defer scratch_arena.deinit();
            const scratch = scratch_arena.allocator();
            const destination = (try self.resolverDestinationForRecordTxn(scratch, txn, group_id, target.key_ptr.*, record)) orelse continue;
            if (destination.indexes_json.len == 0) continue;
            const ownership = try resolver_curation.Ownership.init(scratch, try std.json.parseFromSliceLeaky(std.json.Value, scratch, destination.indexes_json, .{}));
            for (target.value_ptr.items) |template| {
                if (ownership.owns(template)) return false;
                if (@import("../resolver_authority.zig").isNative(try std.json.parseFromSliceLeaky(std.json.Value, scratch, destination.indexes_json, .{}))) {
                    var bridge: NativeResolverTxn = .{ .txn = txn };
                    const store = try nativeResolverStore(scratch, &bridge, group_id, destination.table_id);
                    if (try store.ownsKeyTemplate(template)) return false;
                }
            }
        }
        return true;
    }

    fn admittedResolverProjectionTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !?metadata.TableRecord {
        var key_buf: [160]u8 = undefined;
        if (try stagingGet(txn, try tableKeyForGroup(&key_buf, group_id, record.table_id))) |raw| {
            const previous = try decodeTableRecord(a, raw);
            if (previous.indexes_json.len > 0) {
                const old = try std.json.parseFromSliceLeaky(std.json.Value, a, previous.indexes_json, .{});
                if (@import("../resolver_authority.zig").isNative(old) and !try resolverNamespaceAdoptionAllowedTxn(txn, group_id, a, previous, record)) return null;
            }
        }
        if (record.indexes_json.len == 0) return record;
        const root = try std.json.parseFromSliceLeaky(std.json.Value, a, record.indexes_json, .{});
        if (!try self.resolverSourceCurationAllowedTxn(a, txn, group_id, record, root)) return null;
        const projected = self.projectResolverNamespacesValueTxn(a, txn, group_id, record, root) catch |err| {
            if (resolverAdmissionRejected(err)) return null;
            return err;
        };
        const all = resolverConfigs(a, try std.json.parseFromSliceLeaky(std.json.Value, a, projected.indexes_json, .{})) catch |err| {
            if (resolverAdmissionRejected(err)) return null;
            return err;
        };
        for (all) |cfg| {
            var checked = cfg;
            if (cfg.namespace_curation_table_id != 0) {
                var bridge: NativeResolverTxn = .{ .txn = txn };
                const store = try nativeResolverStore(a, &bridge, group_id, cfg.namespace_curation_table_id);
                const aliases = try cfg.effectiveAliasesAlloc(a);
                var seeds: std.ArrayList([]const u8) = .empty;
                for (aliases) |alias| {
                    try seeds.append(a, alias.key);
                    try seeds.append(a, alias.target);
                }
                const snapshot = (try store.componentWithAliases(cfg.key_template, seeds.items, aliases)) orelse return null;
                checked.merges = snapshot.namespace.merges;
                checked.curation_json = try std.json.Stringify.valueAlloc(a, snapshot.namespace.state, .{});
            }
            checked.validate() catch |err| {
                if (resolverAdmissionRejected(err)) return null;
                return err;
            };
        }
        return projected;
    }
    fn resolverProjectionValidTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !bool {
        return try self.admittedResolverProjectionTxn(a, txn, group_id, record) != null;
    }
    pub fn resolverProjectionValid(self: *RaftApplyStore, a: std.mem.Allocator, group_id: u64, record: metadata.TableRecord) !bool {
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        var arena = std.heap.ArenaAllocator.init(a);
        defer arena.deinit();
        return self.resolverProjectionValidTxn(arena.allocator(), &txn, group_id, record);
    }

    /// A bounded catalog slice; warm reads seek the reverse index, while the
    /// one-time legacy migration advances a table cursor. All pages share one
    /// catalog cut, including changes to source-local aliases.
    const NativeResolverTxn = @import("antfly_local_sources").storage_db_resolver_authority.Transaction(docstore.DocStore.Txn);
    fn nativeResolverStore(a: std.mem.Allocator, bridge: *NativeResolverTxn, group: u64, table: u64) !@import("antfly_local_sources").storage_db_resolver_authority.Store {
        return bridge.store(a, try std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:records:{x:0>16}:", .{ group, table }));
    }
    fn resolverAuthorityViewTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, table: metadata.TableRecord, read: @import("../resolver_authority.zig").Read) !@import("../resolver_authority.zig").View {
        _ = self;
        const domain = @import("../resolver_authority.zig");
        var result: domain.View = .{ .native = false, .table_id = table.table_id };
        const root = try std.json.parseFromSliceLeaky(std.json.Value, a, if (table.indexes_json.len == 0) "{}" else table.indexes_json, .{});
        if (!domain.isNative(root)) return result;
        result.native = true;
        var bridge: NativeResolverTxn = .{ .txn = txn };
        const store = try nativeResolverStore(a, &bridge, group, table.table_id);
        const queue = try store.queueHead();
        result.queue_revision = queue.revision;
        result.proposals.receipt_scope = queue.receipt_scope;
        switch (read.mode) {
            .receipt => result.receipt = try stagingGet(txn, try std.fmt.allocPrint(a, "{s}receipt/{s}", .{ store.prefix, read.id })) != null,
            .proposal => if (try store.proposal(read.id)) |value| {
                result.proposals.proposals = try a.dupe(@import("antfly_resolver").curation.Proposal, &.{value});
            },
            .proposals => {
                const page = try store.proposalPage(read.state, read.action, read.cursor, read.limit);
                result.proposals.proposals = page.proposals;
                result.next_cursor = page.next_cursor;
            },
            .entity => {
                var namespaces: std.ArrayList(domain.records.Snapshot) = .empty;
                var keys: std.StringHashMapUnmanaged(void) = .empty;
                try keys.put(a, read.key, {});
                if (read.into) |id| try keys.put(a, id, {});
                if (read.seeds.len > 4096) return error.ResolverCurationLimitExceeded;
                var seeds: std.ArrayList([]const u8) = .empty;
                try seeds.append(a, read.key);
                if (read.into) |id| try seeds.append(a, id);
                try seeds.appendSlice(a, read.seeds);
                for (read.seeds) |id| try keys.put(a, id, {});
                for (try store.matchingHeads(read.key)) |h| {
                    if (!resolver_curation.keyInNamespace(h.key_template, read.key)) continue;
                    var aliases: std.ArrayList(@import("antfly_resolver").KeyAlias) = .empty;
                    if (read.profiles.len > 4096) return error.ResolverCurationLimitExceeded;
                    for (read.profiles) |profile| if (std.mem.eql(u8, profile.key_template, h.key_template)) {
                        if (profile.aliases.len > 16384 -| aliases.items.len) return error.ResolverCurationLimitExceeded;
                        try aliases.appendSlice(a, profile.aliases);
                    };
                    const value = (try store.componentWithAliases(h.key_template, seeds.items, aliases.items)) orelse return error.InvalidCatalogRecord;
                    try namespaces.append(a, value);
                    for (value.namespace.merges) |alias| {
                        try keys.put(a, alias.key, {});
                        try keys.put(a, alias.target, {});
                    }
                    for (value.namespace.state.suppress.entries) |entry| try keys.put(a, entry.key, {});
                }
                result.namespaces = namespaces.items;
                var selected: std.ArrayList([]const u8) = .empty;
                var it = keys.keyIterator();
                while (it.next()) |key| try selected.append(a, key.*);
                if (read.include_proposals) result.proposals = try store.proposalsForKeys(selected.items);
                if (read.include_proposals and read.id.len > 0) if (try store.proposal(read.id)) |value| {
                    var proposals: std.ArrayList(@import("antfly_resolver").curation.Proposal) = .empty;
                    try proposals.appendSlice(a, result.proposals.proposals);
                    if (for (proposals.items) |p| {
                        if (std.mem.eql(u8, p.id, value.id)) break false;
                    } else true) try proposals.append(a, value);
                    result.proposals.proposals = proposals.items;
                };
            },
        }
        return result;
    }
    fn applyResolverAuthorityTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, body: []const u8) !void {
        const domain = @import("../resolver_authority.zig");
        const native = domain.records;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const write = try std.json.parseFromSliceLeaky(domain.Write, a, body, .{});
        try write.validate();
        var bridge: NativeResolverTxn = .{ .txn = txn };
        const store = try nativeResolverStore(a, &bridge, group, write.table_id);
        try store.ensureHeadRoutes();
        const receipt = try std.fmt.allocPrint(a, "{s}receipt/{s}", .{ store.prefix, try write.receipt(a) });
        if (try stagingGet(txn, receipt) != null) return;
        var table_buf: [160]u8 = undefined;
        const table_key = try tableKeyForGroup(&table_buf, group, write.table_id);
        const raw = (try stagingGet(txn, table_key)) orelse return;
        const current = try decodeTableRecord(a, raw);
        if (try system_catalog_storage.getById(a, txn, group, .table, write.table_id)) |binding| if (binding.value.native_service != null) return;
        if (!std.mem.eql(u8, &write.schema, &try domain.schemaFingerprint(a, current))) return;
        if (write.catalog_revision) |revision| {
            var buf: [160]u8 = undefined;
            const revision_key = if (write.standalone) standalone_revision_key else try catalogRevisionKeyForGroup(&buf, group);
            const bytes = (try stagingGet(txn, revision_key)) orelse &@as([8]u8, @splat(0));
            if (bytes.len != 8 or std.mem.readInt(u64, bytes[0..8], .little) != revision) return;
        }
        var root = try std.json.parseFromSliceLeaky(std.json.Value, a, if (current.indexes_json.len == 0) "{}" else current.indexes_json, .{});
        var patches: std.ArrayList(native.Patch) = .empty;
        const queue = write.queue;
        if (write.bootstrap) |bootstrap| {
            if (domain.isNative(root) or !std.mem.eql(u8, &bootstrap.expected_indexes, &try @import("antfly_resolver").fingerprint(a, current.indexes_json))) return;
            // Metadata owns the legacy bytes. Copy them once locally instead
            // of sending predecessor/afterimage blobs through the Raft log.
            for ((try resolver_curation.namespacesFromValue(a, root)).namespaces) |namespace| {
                try store.apply(try native.difference(a, .{ .key_template = namespace.key_template }, namespace));
            }
            if (root.object.get(resolver_curation.proposals_key)) |value| {
                const state = try @import("antfly_resolver").curation.parseState(a, try std.json.Stringify.valueAlloc(a, value, .{}));
                if (state.proposals.len > 0) try store.applyQueue(.{ .expected_revision = 0, .revision = 1, .receipt_scope = state.receipt_scope, .proposals = state.proposals });
            }
        } else if (!domain.isNative(root)) return;
        try patches.appendSlice(a, write.patches);
        var templates: std.StringHashMapUnmanaged(void) = .empty;
        for (patches.items) |patch| {
            if ((try templates.getOrPut(a, patch.next.key_template)).found_existing) return;
            store.preflight(patch) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return,
            };
        }
        if (queue) |patch| store.preflightQueue(patch) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return,
        };
        // Everything that can reject a command has been checked before the
        // first native edit. Storage/OOM errors abort the enclosing transaction.
        for (patches.items) |patch| try store.apply(patch);
        if (queue) |patch| try store.applyQueue(patch);
        var owners: std.StringHashMapUnmanaged(void) = .empty;
        if (root.object.get(domain.owners_key)) |value| {
            if (value != .array or value.array.items.len > 4096) return;
            for (value.array.items) |item| {
                if (item != .string or item.string.len == 0) return;
                try owners.put(a, item.string, {});
            }
        }
        var owners_changed = false;
        for (write.owned_templates) |template| if (!(try owners.getOrPut(a, template)).found_existing) {
            owners_changed = true;
        };
        var headers: std.ArrayList(resolver_curation.Namespace) = .empty;
        for (try store.heads()) |h| {
            try owners.put(a, h.key_template, {});
            try headers.append(a, .{ .record_store = true, .key_template = h.key_template, .revision = h.revision, .adoption_revision = h.adoption_revision, .adoption_standalone = h.adoption_standalone });
        }
        // Heads in the table are immutable discovery references. Current
        // revisions live in native rows; ordinary curation never rewrites DDL.
        if (write.bootstrap != null or headers.items.len != (try resolver_curation.namespacesFromValue(a, root)).namespaces.len or owners_changed) {
            var owned = std.json.Array.init(a);
            var it = owners.keyIterator();
            while (it.next()) |key| try owned.append(.{ .string = key.* });
            try root.object.put(a, domain.owners_key, .{ .array = owned });
            try root.object.put(a, domain.marker, .{ .integer = 1 });
            try root.object.put(a, resolver_curation.namespaces_key, try std.json.parseFromSliceLeaky(std.json.Value, a, try std.json.Stringify.valueAlloc(a, resolver_curation.Namespaces{ .namespaces = headers.items }, .{}), .{}));
            _ = root.object.swapRemove(resolver_curation.proposals_key);
            var replacement = current;
            replacement.indexes_json = try std.json.Stringify.valueAlloc(a, root, .{});
            try bridge.flush(a);
            // Only private resolver discovery references changed. Schema,
            // physical identity and all other metadata match the live proof.
            try self.putTableRecordTxnModeRaw(txn, group, table_key, replacement, true);
        }
        try bridge.flush(a);
        if (patches.items.len != 0) try enqueueResolverNamespaceTxn(a, txn, group, current.table_id);
        try txn.put(receipt, "true");
    }

    pub fn resolverCatalogRead(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, input: @import("../resolver_catalog_read.zig").Request) ![]u8 {
        const wire = @import("../resolver_catalog_read.zig");
        if (input.table_name.len == 0 or input.table_name.len > 4096 or input.key.len > 16384) return error.InvalidResolverCurationRequest;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var txn = try self.beginQueryCatalogReadTxn(group_id);
        defer txn.abort();
        var revision_buf: [160]u8 = undefined;
        const revision_key = if (input.standalone) standalone_revision_key else try catalogRevisionKeyForGroup(&revision_buf, group_id);
        const raw_revision = (try stagingGet(&txn, revision_key)) orelse &@as([8]u8, @splat(0));
        if (raw_revision.len != 8) return error.InvalidCatalogRecord;
        const revision = std.mem.readInt(u64, raw_revision[0..8], .little);
        if (input.expected_revision) |expected| if (expected != revision) return error.CatalogGenerationChanged;
        const table = if (input.table_id != 0) blk: {
            var key_buf: [160]u8 = undefined;
            break :blk try decodeTableRecord(a, (try stagingGet(&txn, try tableKeyForGroup(&key_buf, group_id, input.table_id))) orelse return error.TableNotFound);
        } else (try self.getTableByNameTxn(a, &txn, group_id, input.table_name)) orelse return error.TableNotFound;
        if (input.mode == .authority) return std.json.Stringify.valueAlloc(alloc, try self.resolverAuthorityViewTxn(a, &txn, group_id, table, input.authority orelse return error.InvalidResolverCurationRequest), .{});
        var result: wire.Page = .{ .version = 1, .revision = revision, .table = table };
        if (input.mode == .table) {
            if (input.cursor != null) return error.InvalidResolverCurationRequest;
            const ids = try self.indexedTableRangeIdsTxn(a, &txn, group_id, table.table_id);
            const ranges = try a.alloc(metadata.RangeRecord, ids.len);
            for (ids, ranges) |id, *range| {
                var buf: [160]u8 = undefined;
                range.* = try decodeRangeRecord(a, try txn.get(try rangeKeyForGroup(&buf, group_id, id)));
            }
            result.ranges = ranges;
            var projections: ResolverProjectionCache = .empty;
            var selected_names = input.projection_names;
            if (input.routing_siblings and selected_names != null and selected_names.?.len != 0) {
                var desired: std.ArrayListUnmanaged(@import("antfly_local_sources").storage_db_catalog_resolver_catalog.ResolverConfig) = .empty;
                try @import("antfly_local_sources").metadata_local_index_reconcile.collectDesiredResolvers(a, try std.json.parseFromSliceLeaky(std.json.Value, a, table.indexes_json, .{}), &desired);
                var names: std.StringHashMapUnmanaged(void) = .empty;
                for (selected_names.?) |name| {
                    try names.put(a, name, {});
                    for (desired.items) |cfg| if (std.mem.eql(u8, cfg.name, name)) {
                        for (desired.items) |sibling| if (cfg.sharesRoutingDomain(sibling) and std.mem.eql(u8, cfg.source_artifact, sibling.source_artifact) and sibling.source_artifact_kind.matches(.asset)) try names.put(a, sibling.name, {});
                    };
                }
                const values = try a.alloc([]const u8, names.count());
                var it = names.keyIterator();
                for (values) |*name| name.* = it.next().?.*;
                selected_names = values;
            }
            if (selected_names == null or selected_names.?.len > 0) result.execution_indexes = try self.resolverSelectedExecutionIndexesTxn(a, &txn, group_id, table.indexes_json, &projections, selected_names);
            return std.json.Stringify.valueAlloc(alloc, result, .{});
        }
        const indexed = try stagingGet(&txn, try resolverNamespaceBootstrapKey(a, group_id)) != null;
        const continuation: ?wire.Cursor = if (input.cursor) |value| try resolver_curation.decodeToken(wire.Cursor, a, value) else null;
        if (continuation) |value| if (value.revision != revision or value.table_id != table.table_id or !std.mem.eql(u8, &value.key_digest, &wire.keyDigest(input.key))) return error.InvalidResolverCurationRequest;
        result.indexed = if (continuation) |value| value.indexed else indexed;
        var prefix_buf: [160]u8 = undefined;
        const prefix = if (result.indexed) try self.resolverConsumerPrefixTxn(a, &txn, group_id, table.table_id) else try a.dupe(u8, try tablePrefixForGroup(&prefix_buf, group_id));
        const after = if (continuation) |value| value.after else prefix;
        if (!std.mem.startsWith(u8, after, prefix)) return error.InvalidResolverCurationRequest;
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(after);
        if (continuation != null and row != null and std.mem.eql(u8, row.?.key, after)) row = try cursor.next();
        var consumers: std.ArrayListUnmanaged(wire.Consumer) = .empty;
        var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
        var bytes: usize = 0;
        var last: ?[]const u8 = null;
        while (row) |entry| {
            if (!std.mem.startsWith(u8, entry.key, prefix) or result.visited == 16 or bytes >= 1024 * 1024) break;
            result.visited += 1;
            last = try a.dupe(u8, entry.key);
            if (input.compact_consumers and result.indexed and entry.value.len > 0 and entry.value[0] == '{') {
                const reference = try wire.decodeConsumerReference(a, entry.value);
                if (!(try seen.getOrPut(a, reference.source_id)).found_existing) {
                    var selected: std.ArrayList(@import("antfly_local_sources").storage_db_catalog_resolver_catalog.ResolverConfig) = .empty;
                    var names: std.ArrayList([]const u8) = .empty;
                    for (reference.configs) |cfg| {
                        if (input.key.len > 0 and !resolver_curation.keyInNamespace(cfg.key_template, input.key)) continue;
                        try selected.append(a, cfg);
                        try names.append(a, cfg.name);
                    }
                    bytes += entry.value.len;
                    if (selected.items.len > 0) try consumers.append(a, .{ .table = .{ .table_id = reference.source_id, .name = reference.source_name }, .names = names.items, .configs = selected.items });
                }
                row = try cursor.next();
                continue;
            }
            const source_bytes = if (!result.indexed) entry.value else block: {
                const id = try resolverConsumerSourceId(a, entry.value);
                if ((try seen.getOrPut(a, id)).found_existing) {
                    row = try cursor.next();
                    continue;
                }
                var key_buf: [160]u8 = undefined;
                break :block (try stagingGet(&txn, try tableKeyForGroup(&key_buf, group_id, id))) orelse {
                    row = try cursor.next();
                    continue;
                };
            };
            if (source_bytes.len > 8 * 1024 * 1024) return error.CatalogCommandTooLarge;
            bytes += source_bytes.len;
            const source = try decodeTableRecord(a, source_bytes);
            if (source.indexes_json.len > 0) {
                const root = try std.json.parseFromSliceLeaky(std.json.Value, a, source.indexes_json, .{});
                var names: std.ArrayListUnmanaged([]const u8) = .empty;
                for (try resolverConfigs(a, root)) |cfg| {
                    if (input.key.len > 0 and !resolver_curation.keyInNamespace(cfg.key_template, input.key)) continue;
                    const destination = (try self.resolverDestinationForRecordTxn(a, &txn, group_id, cfg.table, source)) orelse continue;
                    if (destination.table_id == table.table_id) try names.append(a, cfg.name);
                }
                if (names.items.len > 0) try consumers.append(a, .{ .table = source, .names = names.items });
            }
            row = try cursor.next();
        }
        result.consumers = consumers.items;
        if (row != null and std.mem.startsWith(u8, row.?.key, prefix)) {
            result.next_cursor = try resolver_curation.encodeToken(a, wire.Cursor{ .revision = revision, .table_id = table.table_id, .key_digest = wire.keyDigest(input.key), .indexed = result.indexed, .after = last orelse return error.InvalidCatalogRecord });
        }
        return std.json.Stringify.valueAlloc(alloc, result, .{});
    }

    fn resolverNamespaceAdoptionAllowedTxn(txn: *docstore.DocStore.Txn, group_id: u64, a: std.mem.Allocator, previous: metadata.TableRecord, next: metadata.TableRecord) !bool {
        if (next.indexes_json.len == 0 or std.mem.eql(u8, previous.indexes_json, next.indexes_json)) return true;
        const root = try std.json.parseFromSliceLeaky(std.json.Value, a, next.indexes_json, .{});
        const prior_root = try std.json.parseFromSliceLeaky(std.json.Value, a, if (previous.indexes_json.len == 0) "{}" else previous.indexes_json, .{});
        if (@import("../resolver_authority.zig").isNative(prior_root)) {
            inline for (.{ "_resolver_record_store", "_resolver_record_owners", "_resolver_namespaces", "_curation_proposals" }) |key| {
                const old = prior_root.object.get(key);
                const changed = root.object.get(key);
                if ((old == null) != (changed == null)) return false;
                if (old) |value| if (!std.mem.eql(u8, try std.json.Stringify.valueAlloc(a, value, .{}), try std.json.Stringify.valueAlloc(a, changed.?, .{}))) return false;
            }
            return true;
        }
        const namespaces = try resolver_curation.namespacesFromValue(a, root);
        if (namespaces.namespaces.len == 0) return true;
        const old = if (previous.indexes_json.len == 0) resolver_curation.Namespaces{} else try resolver_curation.namespacesFromValue(a, try std.json.parseFromSliceLeaky(std.json.Value, a, previous.indexes_json, .{}));
        for (namespaces.namespaces) |namespace| {
            const exists = for (old.namespaces) |prior| {
                if (std.mem.eql(u8, prior.key_template, namespace.key_template)) break std.mem.eql(u8, try std.json.Stringify.valueAlloc(a, prior, .{}), try std.json.Stringify.valueAlloc(a, namespace, .{}));
            } else false;
            if (exists) continue;
            if (namespace.adoption_revision) |revision| {
                var buf: [160]u8 = undefined;
                const key = if (namespace.adoption_standalone) standalone_revision_key else try catalogRevisionKeyForGroup(&buf, group_id);
                const bytes = txn.get(key) catch |err| switch (err) {
                    error.NotFound => return revision == 0,
                    else => return err,
                };
                if (bytes.len != 8 or std.mem.readInt(u64, bytes[0..8], .little) != revision) return false;
            }
        }
        return true;
    }

    const ResolverNamespaceJob = struct { table_id: u64, bootstrap: bool = true, after: ?[]const u8 = null, retire: bool = false, dirty: bool = false };
    // Coalesce invalidations without rewinding a live pass. A dirty pass runs
    // again after its tail, so consumers preceding the cursor also catch up.
    fn enqueueResolverNamespaceTxn(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, table: u64) !void {
        const key = try std.fmt.allocPrint(a, "{s}{d}", .{ try resolverJobPrefix(a, group), table });
        var job = if (try stagingGet(txn, key)) |raw| try std.json.parseFromSliceLeaky(ResolverNamespaceJob, a, raw, .{}) else ResolverNamespaceJob{ .table_id = table, .bootstrap = try stagingGet(txn, try resolverNamespaceBootstrapKey(a, group)) == null };
        if (job.retire) return;
        job.dirty = true;
        try txn.put(key, try std.json.Stringify.valueAlloc(a, job, .{}));
    }
    fn resolverNamespacePrefix(buf: []u8, group_id: u64) ![]const u8 {
        return std.fmt.bufPrint(buf, "\x00\x00__metadata__:resolver_namespaces:{d}:", .{group_id});
    }
    fn resolverDependencyPrefix(a: std.mem.Allocator, group_id: u64, destination: u64) ![]const u8 {
        return std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:dependency:{d}:", .{ group_id, destination });
    }
    fn resolverTargetPrefix(a: std.mem.Allocator, group_id: u64, target: system_catalog.Target) ![]const u8 {
        const digest = try @import("antfly_resolver").fingerprint(a, .{ target.database, target.namespace, target.table });
        return std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:target:{x}:", .{ group_id, &digest });
    }
    // Bind the current logical name with point reads. Declared-target edges
    // survive destination replacement and never depend on a cached owner ID.
    fn resolverConsumerPrefixTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) ![]const u8 {
        if (try system_catalog_storage.getById(a, txn, group_id, .table, table_id)) |binding| {
            const namespace = if (try system_catalog_storage.getById(a, txn, group_id, .namespace, binding.value.parent_id)) |value| value.value else if (binding.value.parent_id == system_catalog.default_namespace_id) system_catalog.default_namespace else return error.InvalidCatalogRecord;
            const database = if (try system_catalog_storage.getById(a, txn, group_id, .database, namespace.parent_id)) |value| value.value else if (namespace.parent_id == system_catalog.default_database_id) system_catalog.default_database else return error.InvalidCatalogRecord;
            return resolverTargetPrefix(a, group_id, .{ .database = database.name, .namespace = namespace.name, .table = binding.value.name });
        }
        var buf: [160]u8 = undefined;
        const table = try decodeTableRecord(a, try txn.get(try tableKeyForGroup(&buf, group_id, table_id)));
        _ = self;
        return resolverTargetPrefix(a, group_id, .{ .table = table.name });
    }
    fn resolverJobPrefix(a: std.mem.Allocator, group_id: u64) ![]const u8 {
        return std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:job:", .{group_id});
    }
    fn resolverNamespaceBootstrapKey(a: std.mem.Allocator, group_id: u64) ![]const u8 {
        return std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:bootstrapped-v2", .{group_id});
    }
    fn resolverConfigs(a: std.mem.Allocator, root: std.json.Value) ![]const @import("antfly_local_sources").storage_db_catalog_resolver_catalog.ResolverConfig {
        const Config = @import("antfly_local_sources").storage_db_catalog_resolver_catalog.ResolverConfig;
        var desired: std.ArrayListUnmanaged(Config) = .empty;
        try @import("antfly_local_sources").metadata_local_index_reconcile.collectDesiredResolvers(a, root, &desired);
        const identities = try resolver_curation.metadataFromValue(a, root);
        var profiles: std.StringHashMapUnmanaged(void) = .empty;
        for (desired.items) |*cfg| for (identities.identities) |identity| {
            if (!identity.dropped and std.mem.eql(u8, identity.name, cfg.name)) cfg.* = try resolver_curation.overlayMetadataCached(a, cfg.*, identity, &profiles);
        };
        for (identities.identities) |identity| {
            if (identity.dropped) continue;
            const found = for (desired.items) |cfg| {
                if (std.mem.eql(u8, cfg.name, identity.name)) break true;
            } else false;
            if (!found) try desired.append(a, try resolver_curation.overlayMetadataCached(a, .{ .name = identity.name, .table = identity.table, .key_template = identity.key_template, .source_artifact = "retired_source", .resolution_artifact = "retired_resolution", .retired = true, .promote = false }, identity, &profiles));
        }
        return desired.items;
    }
    fn resolverDestinationTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, name: []const u8) !?metadata.TableRecord {
        return self.resolveSystemCatalogResultTxn(metadata.TableRecord, a, txn, group_id, try system_catalog.Target.parse(name));
    }
    fn resolverDestinationForRecordTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, name: []const u8, record: metadata.TableRecord) !?metadata.TableRecord {
        const target = try system_catalog.Target.parse(name);
        const namespace = (try resolveSystemCatalogNamespaceTxn(a, txn, group_id, target.database, target.namespace)) orelse return null;
        if (try system_catalog_storage.find(a, txn, group_id, .table, namespace, target.table)) |value| {
            var binding = value;
            defer binding.deinit();
            if (binding.value.id == record.table_id) return record;
        } else if (namespace == system_catalog.default_namespace_id and std.mem.eql(u8, target.table, record.name)) return record;
        return self.resolverDestinationTxn(a, txn, group_id, name);
    }
    fn resolverDependencyKeysTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !std.StringHashMapUnmanaged(void) {
        var keys: std.StringHashMapUnmanaged(void) = .empty;
        if (record.indexes_json.len == 0) return keys;
        const root = try std.json.parseFromSliceLeaky(std.json.Value, a, record.indexes_json, .{});
        for (try resolverConfigs(a, root)) |cfg| {
            const digest = try @import("antfly_resolver").fingerprint(a, .{ cfg.key_template, cfg.name });
            const target_key = try std.fmt.allocPrint(a, "{s}{x:0>16}", .{ try resolverTargetPrefix(a, group_id, try system_catalog.Target.parse(cfg.table)), record.table_id });
            try keys.put(a, target_key, {});
            const destination = (try self.resolverDestinationForRecordTxn(a, txn, group_id, cfg.table, record)) orelse continue;
            const key = try std.fmt.allocPrint(a, "{s}{x:0>16}:{x}", .{ try resolverDependencyPrefix(a, group_id, destination.table_id), record.table_id, &digest });
            try keys.put(a, key, {});
        }
        return keys;
    }
    fn removeResolverDependenciesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !void {
        const keys = try self.resolverDependencyKeysTxn(a, txn, group_id, record);
        var it = keys.keyIterator();
        while (it.next()) |key| try txn.delete(key.*);
    }
    /// Maintain only changed edges, after table admission. Projection and CAS
    /// verification must never mutate this index for a rejected definition.
    fn resolverConsumerSourceId(a: std.mem.Allocator, raw: []const u8) !u64 {
        if (raw.len > 0 and raw[0] == '{') return (try std.json.parseFromSliceLeaky(struct { source_id: u64 }, a, raw, .{ .ignore_unknown_fields = true })).source_id;
        return std.json.parseFromSliceLeaky(u64, a, raw, .{});
    }
    fn putCompactResolverConsumersTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, source: metadata.TableRecord) !void {
        if (source.indexes_json.len == 0) return;
        const root = try std.json.parseFromSliceLeaky(std.json.Value, a, source.indexes_json, .{});
        const wire = @import("../resolver_catalog_read.zig");
        const Config = @import("antfly_local_sources").storage_db_catalog_resolver_catalog.ResolverConfig;
        const identities = try resolver_curation.metadataFromValue(a, root);
        var targets: std.StringHashMapUnmanaged(std.ArrayList(Config)) = .empty;
        for (try resolverConfigs(a, root)) |original| {
            const destination = (try self.resolverDestinationForRecordTxn(a, txn, group, original.table, source)) orelse continue;
            const target_root = try std.json.parseFromSliceLeaky(std.json.Value, a, if (destination.indexes_json.len == 0) "{}" else destination.indexes_json, .{});
            if (!@import("../resolver_authority.zig").isNative(target_root)) continue;
            var cfg = original;
            for (identities.identities) |identity| if (identity.namespace_owned and std.mem.eql(u8, identity.name, cfg.name)) {
                cfg.merges = &.{};
                cfg.curation_json = "{}";
                break;
            };
            const entry = try targets.getOrPut(a, cfg.table);
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            try entry.value_ptr.append(a, cfg);
        }
        var it = targets.iterator();
        while (it.next()) |target| {
            const key = try std.fmt.allocPrint(a, "{s}{x:0>16}", .{ try resolverTargetPrefix(a, group, try system_catalog.Target.parse(target.key_ptr.*)), source.table_id });
            try txn.put(key, try std.json.Stringify.valueAlloc(a, wire.ConsumerReference{ .source_id = source.table_id, .source_name = source.name, .configs = target.value_ptr.items }, .{}));
        }
    }

    fn synchronizeResolverDependenciesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, previous: ?metadata.TableRecord, next: metadata.TableRecord) !void {
        if (previous) |old| if (std.mem.eql(u8, old.name, next.name) and std.mem.eql(u8, old.indexes_json, next.indexes_json)) return;
        const old = if (previous) |value| try self.resolverDependencyKeysTxn(a, txn, group_id, value) else std.StringHashMapUnmanaged(void).empty;
        const desired = try self.resolverDependencyKeysTxn(a, txn, group_id, next);
        var retired = old.keyIterator();
        while (retired.next()) |key| if (!desired.contains(key.*)) try txn.delete(key.*);
        const value = try std.json.Stringify.valueAlloc(a, next.table_id, .{});
        var added = desired.keyIterator();
        while (added.next()) |key| if (!old.contains(key.*)) try txn.put(key.*, value);
        try self.putCompactResolverConsumersTxn(a, txn, group_id, next);
    }
    /// The authoritative namespace is read in the table mutation transaction.
    /// New consumers therefore inherit it before their first owner is opened.
    fn materializedResolverNamespaceTxn(_: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, destination: u64, namespace: resolver_curation.Namespace) !resolver_curation.Namespace {
        if (!namespace.record_store) return namespace;
        var bridge: NativeResolverTxn = .{ .txn = txn };
        const store = try nativeResolverStore(a, &bridge, group, destination);
        return (try store.exportNamespace(namespace.key_template) orelse return error.InvalidCatalogRecord).namespace;
    }
    fn resolverNamespaceBindingTxn(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, destination: u64, header: resolver_curation.Namespace) !resolver_curation.Namespace {
        if (!header.record_store) return header;
        var bridge: NativeResolverTxn = .{ .txn = txn };
        const store = try nativeResolverStore(a, &bridge, group, destination);
        const head = try store.head(header.key_template) orelse return error.InvalidCatalogRecord;
        return .{ .record_store = true, .key_template = header.key_template, .revision = head.revision };
    }
    /// Shared immutable payload cache. Every lookup first reads the head from
    /// the caller's transaction; a revision/fingerprint change misses at once.
    /// Copies give each read cut independent lifetime through eviction/restore.
    fn resolverProjectionPayloadTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, identity: resolver_curation.MetadataIdentity) !resolver_curation.Namespace {
        var bridge: NativeResolverTxn = .{ .txn = txn };
        const native = try nativeResolverStore(a, &bridge, group, identity.authority_table_id);
        var key_buf: [160]u8 = undefined;
        if (try stagingGet(txn, try tableKeyForGroup(&key_buf, group, identity.authority_table_id)) == null) return .{ .key_template = identity.key_template, .revision = identity.revision };
        const head = try native.head(identity.key_template) orelse return error.InvalidCatalogRecord;
        const cacheable = !std.mem.eql(u8, &head.fingerprint, &@as([32]u8, @splat(0)));
        const key = try std.json.Stringify.valueAlloc(a, .{ group, identity.authority_table_id, identity.key_template, head.revision, head.fingerprint }, .{});
        if (cacheable) {
            const copy: ?[]const u8 = blk: {
                self.resolver_projection_mutex.lockUncancelable(self.io_impl.io());
                defer self.resolver_projection_mutex.unlock(self.io_impl.io());
                break :blk if (self.resolver_projection_payloads.get(key)) |raw| try a.dupe(u8, raw) else null;
            };
            if (copy) |raw| return std.json.parseFromSliceLeaky(resolver_curation.Namespace, a, raw, .{});
        }
        const snapshot = (try native.exportNamespace(identity.key_template)) orelse return error.InvalidCatalogRecord;
        const encoded = try std.json.Stringify.valueAlloc(a, snapshot.namespace, .{});
        self.resolver_projection_mutex.lockUncancelable(self.io_impl.io());
        defer self.resolver_projection_mutex.unlock(self.io_impl.io());
        if (builtin.is_test) self.resolver_projection_exports += 1;
        const budget = 64 * 1024 * 1024;
        if (cacheable and encoded.len <= budget and !self.resolver_projection_payloads.contains(key)) {
            while (self.resolver_projection_bytes + encoded.len > budget or self.resolver_projection_payloads.count() >= 64) {
                var entries = self.resolver_projection_payloads.iterator();
                const entry = entries.next() orelse break;
                const expired_key = entry.key_ptr.*;
                const expired_value = entry.value_ptr.*;
                _ = self.resolver_projection_payloads.remove(expired_key);
                self.resolver_projection_bytes -= expired_value.len;
                self.alloc.free(expired_key);
                self.alloc.free(expired_value);
            }
            const owned_key = try self.alloc.dupe(u8, key);
            errdefer self.alloc.free(owned_key);
            const owned_value = try self.alloc.dupe(u8, encoded);
            errdefer self.alloc.free(owned_value);
            try self.resolver_projection_payloads.put(self.alloc, owned_key, owned_value);
            self.resolver_projection_bytes += encoded.len;
        }
        return snapshot.namespace;
    }
    const ResolverProjectionCache = std.StringHashMapUnmanaged(resolver_curation.Namespace);
    /// Expand compact bindings only on execution/provisioning reads. One
    /// immutable snapshot is shared across all consumers in this read cut;
    /// source metadata and Raft updates never serialize the policy payload.
    fn resolverExecutionIndexesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, indexes: []const u8, cache: *ResolverProjectionCache) ![]const u8 {
        return self.resolverSelectedExecutionIndexesTxn(a, txn, group, indexes, cache, null);
    }
    fn resolverSelectedExecutionIndexesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, indexes: []const u8, cache: *ResolverProjectionCache, names: ?[]const []const u8) ![]const u8 {
        if (names) |selected| if (selected.len == 0) return indexes;
        if (indexes.len == 0) return indexes;
        var root = try std.json.parseFromSliceLeaky(std.json.Value, a, indexes, .{});
        const identities = try resolver_curation.metadataFromValue(a, root);
        var changed = false;
        var attachments: std.StringHashMapUnmanaged(resolver_curation.MetadataProjection) = .empty;
        const hydrated_identities = try a.dupe(resolver_curation.MetadataIdentity, identities.identities);
        for (hydrated_identities) |*identity| {
            if (!identity.projection_only or identity.dropped) continue;
            if (names) |selected| {
                const found = for (selected) |name| {
                    if (std.mem.eql(u8, name, identity.name)) break true;
                } else false;
                if (!found) continue;
            }
            const cache_key = try std.json.Stringify.valueAlloc(a, .{ identity.authority_table_id, identity.key_template }, .{});
            const entry = try cache.getOrPut(a, cache_key);
            if (!entry.found_existing) {
                entry.value_ptr.* = try self.resolverProjectionPayloadTxn(a, txn, group, identity.*);
            }
            const namespace = entry.value_ptr.*;
            const attachment = try attachments.getOrPut(a, cache_key);
            if (!attachment.found_existing) {
                var digest: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(try std.json.Stringify.valueAlloc(a, namespace, .{}), &digest, .{});
                attachment.value_ptr.* = .{ .id = try a.dupe(u8, &std.fmt.bytesToHex(digest, .lower)), .namespace = namespace };
            }
            identity.projection_ref = attachment.value_ptr.id;
            identity.projection_only = false;
            identity.revision = namespace.revision;
            identity.merges = namespace.merges;
            identity.state = namespace.state;
            identity.authority_missing = !namespace.record_store;
            changed = true;
        }
        if (!changed) return indexes;
        var unique: std.StringArrayHashMapUnmanaged(resolver_curation.MetadataProjection) = .empty;
        var values = attachments.valueIterator();
        while (values.next()) |item| try unique.put(a, item.id, item.*);
        const projections = unique.values();
        try root.object.put(a, resolver_curation.metadata_key, try std.json.parseFromSliceLeaky(std.json.Value, a, try std.json.Stringify.valueAlloc(a, resolver_curation.Metadata{ .identities = hydrated_identities, .projections = projections }, .{}), .{}));
        return std.json.Stringify.valueAlloc(a, root, .{});
    }
    fn projectResolverNamespacesTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !metadata.TableRecord {
        if (record.indexes_json.len == 0) return record;
        return self.projectResolverNamespacesValueTxn(a, txn, group_id, record, try std.json.parseFromSliceLeaky(std.json.Value, a, record.indexes_json, .{}));
    }
    fn projectResolverNamespacesValueTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord, value: std.json.Value) !metadata.TableRecord {
        var root = value;
        const configs = try resolverConfigs(a, root);
        var changed = false;
        for (configs) |cfg| {
            const destination = (try self.resolverDestinationForRecordTxn(a, txn, group_id, cfg.table, record)) orelse continue;
            if (destination.indexes_json.len == 0) continue;
            const namespaces = try resolver_curation.namespacesFromValue(a, try std.json.parseFromSliceLeaky(std.json.Value, a, destination.indexes_json, .{}));
            for (namespaces.namespaces) |header| {
                if (!std.mem.eql(u8, header.key_template, cfg.key_template)) continue;
                const namespace = try resolverNamespaceBindingTxn(a, txn, group_id, destination.table_id, header);
                try resolver_curation.replaceMetadata(a, &root, .{ .name = cfg.name, .table = cfg.table, .key_template = cfg.key_template, .merges = namespace.merges, .state = namespace.state, .revision = namespace.revision, .namespace_generation = cfg.namespace_generation, .namespace_owned = true, .authority_table_id = if (header.record_store) destination.table_id else 0, .projection_only = header.record_store });
                changed = true;
            }
        }
        var projected = record;
        if (changed) projected.indexes_json = try std.json.Stringify.valueAlloc(a, root, .{});
        return projected;
    }
    const ResolverRejection = struct { digest: [32]u8, term: u64, index: u64 };
    fn resolverRejectionKey(a: std.mem.Allocator, group_id: u64, table_id: u64) ![]const u8 {
        return std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:rejected:{x:0>16}", .{ group_id, table_id });
    }
    fn resolverReplacementDigest(a: std.mem.Allocator, expected: metadata.TableRecord, replacement: metadata.TableRecord) ![32]u8 {
        var digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(try std.json.Stringify.valueAlloc(a, .{ expected, replacement }, .{}), &digest, .{});
        return digest;
    }
    pub fn resolverNamespaceReplacementRejected(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, term: u64, index: u64, expected: metadata.TableRecord, replacement: metadata.TableRecord) !bool {
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const value = (try stagingGet(&txn, try resolverRejectionKey(a, group_id, expected.table_id))) orelse return false;
        const receipt = try std.json.parseFromSliceLeaky(ResolverRejection, a, value, .{});
        return receipt.term == term and receipt.index == index and std.mem.eql(u8, &receipt.digest, &(try resolverReplacementDigest(a, expected, replacement)));
    }
    pub fn resolverNamespaceReplacementMatches(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64, current: metadata.TableRecord, replacement: metadata.TableRecord) !bool {
        if (metadata_table_manager.tableDefinitionsEqual(current, replacement)) return true;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        // Projection maintenance must not mutate a read transaction. This
        // comparison rebuilds just the expected identity afterimages locally.
        const a = arena.allocator();
        var expected = replacement;
        if (expected.indexes_json.len == 0) return false;
        var root = try std.json.parseFromSliceLeaky(std.json.Value, a, expected.indexes_json, .{});
        for (try resolverConfigs(a, root)) |cfg| {
            const destination = (try self.resolverDestinationTxn(a, &txn, group_id, cfg.table)) orelse continue;
            if (destination.indexes_json.len == 0) continue;
            const namespaces = try resolver_curation.namespacesFromValue(a, try std.json.parseFromSliceLeaky(std.json.Value, a, destination.indexes_json, .{}));
            for (namespaces.namespaces) |header| if (std.mem.eql(u8, header.key_template, cfg.key_template)) {
                const namespace = try resolverNamespaceBindingTxn(a, &txn, group_id, destination.table_id, header);
                try resolver_curation.replaceMetadata(a, &root, .{ .name = cfg.name, .table = cfg.table, .key_template = cfg.key_template, .merges = namespace.merges, .state = namespace.state, .revision = namespace.revision, .namespace_generation = cfg.namespace_generation, .namespace_owned = true, .authority_table_id = if (header.record_store) destination.table_id else 0, .projection_only = header.record_store });
            };
        }
        expected.indexes_json = try std.json.Stringify.valueAlloc(a, root, .{});
        return metadata_table_manager.tableDefinitionsEqual(current, expected);
    }

    fn retireResolverNamespaceDependenciesTxn(_: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !void {
        const prefix = try resolverDependencyPrefix(a, group_id, table_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        var keys: std.ArrayListUnmanaged([]const u8) = .empty;
        while (row) |entry| {
            if (!std.mem.startsWith(u8, entry.key, prefix) or keys.items.len == 16) break;
            try keys.append(a, try a.dupe(u8, entry.key));
            row = try cursor.next();
        }
        const pending = row != null and std.mem.startsWith(u8, row.?.key, prefix);
        for (keys.items) |key| try txn.delete(key);
        const job = try std.fmt.allocPrint(a, "{s}{d}", .{ try resolverJobPrefix(a, group_id), table_id });
        // Native policy, proposal indexes and receipts share the same bounded
        // retirement job, so dropping a destination never leaks its authority.
        const native_prefix = try std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:records:{x:0>16}:", .{ group_id, table_id });
        var native_cursor = try txn.openCursor();
        defer native_cursor.close();
        var native_row = try native_cursor.seekAtOrAfter(native_prefix);
        var native_keys: std.ArrayList([]const u8) = .empty;
        while (native_row) |entry| {
            if (!std.mem.startsWith(u8, entry.key, native_prefix) or native_keys.items.len == 128) break;
            try native_keys.append(a, try a.dupe(u8, entry.key));
            native_row = try native_cursor.next();
        }
        const native_pending = native_row != null and std.mem.startsWith(u8, native_row.?.key, native_prefix);
        for (native_keys.items) |key| try txn.delete(key);
        try txn.put(try resolverScheduleKey(a, group_id), job);
        if (pending or native_pending) try txn.put(job, try std.json.Stringify.valueAlloc(a, ResolverNamespaceJob{ .table_id = table_id, .bootstrap = false, .retire = true }, .{})) else try txn.delete(job);
    }
    fn resolverScheduleKey(a: std.mem.Allocator, group: u64) ![]const u8 {
        return std.fmt.allocPrint(a, "\x00\x00__metadata__:resolver_namespaces:{d}:scheduled", .{group});
    }
    fn nextResolverNamespaceJobTxn(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64) !?docstore.OwnedKVPair {
        const prefix = try resolverJobPrefix(a, group);
        defer a.free(prefix);
        const schedule_key = try resolverScheduleKey(a, group);
        defer a.free(schedule_key);
        const after = try stagingGet(txn, schedule_key);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(after orelse prefix);
        if (after) |key| if (row) |entry| if (std.mem.eql(u8, key, entry.key)) {
            row = try cursor.next();
        };
        if (row == null or !std.mem.startsWith(u8, row.?.key, prefix)) row = try cursor.seekAtOrAfter(prefix);
        const entry = row orelse return null;
        if (!std.mem.startsWith(u8, entry.key, prefix)) return null;
        const key = try a.dupe(u8, entry.key);
        errdefer a.free(key);
        return .{ .key = key, .value = try a.dupe(u8, entry.value) };
    }
    pub fn pendingResolverNamespaceDrop(self: *RaftApplyStore, a: std.mem.Allocator, group_id: u64) !?u64 {
        var arena = std.heap.ArenaAllocator.init(a);
        defer arena.deinit();
        const scratch = arena.allocator();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const row = (try nextResolverNamespaceJobTxn(scratch, &txn, group_id)) orelse return null;
        const job = try std.json.parseFromSliceLeaky(ResolverNamespaceJob, scratch, row.value, .{});
        if (!job.retire) return null;
        var buf: [160]u8 = undefined;
        if (try stagingGet(&txn, try tableKeyForGroup(&buf, group_id, job.table_id)) != null) return null;
        return job.table_id;
    }

    /// One durable seek and one table point read; no catalog fan-out on ticks.
    pub fn pendingResolverNamespaceTable(self: *RaftApplyStore, a: std.mem.Allocator, group_id: u64) !?metadata.TableRecord {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const row = (try nextResolverNamespaceJobTxn(a, &txn, group_id)) orelse return null;
        defer a.free(row.key);
        defer a.free(row.value);
        var parsed = try std.json.parseFromSlice(ResolverNamespaceJob, a, row.value, .{});
        defer parsed.deinit();
        const job = parsed.value;
        if (job.retire) return null;
        var key_buf: [160]u8 = undefined;
        const raw = txn.get(try tableKeyForGroup(&key_buf, group_id, job.table_id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return try decodeTableRecord(a, raw);
    }
    /// Bounded preview used by standalone to refresh its in-memory projection
    /// after the same durable page commits. No source tables are scanned.
    pub fn pendingResolverNamespaceSources(self: *RaftApplyStore, alloc: std.mem.Allocator, group_id: u64) ![]metadata.TableRecord {
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        var cursor = try txn.openCursor();
        defer cursor.close();
        const first = (try nextResolverNamespaceJobTxn(a, &txn, group_id)) orelse return alloc.alloc(metadata.TableRecord, 0);
        var job = try std.json.parseFromSliceLeaky(ResolverNamespaceJob, a, first.value, .{});
        if (!job.bootstrap and try stagingGet(&txn, try resolverNamespaceBootstrapKey(a, group_id)) == null) {
            job.bootstrap = true;
            job.after = null;
        }
        var prefix_buf: [128]u8 = undefined;
        const prefix = if (job.bootstrap) try tablePrefixForGroup(&prefix_buf, group_id) else try self.resolverConsumerPrefixTxn(a, &txn, group_id, job.table_id);
        if (job.after) |after| if (!std.mem.startsWith(u8, after, prefix)) {
            job.after = null;
        };
        var entry = try cursor.seekAtOrAfter(job.after orelse prefix);
        if (job.after) |after| if (entry) |row| if (std.mem.eql(u8, row.key, after)) {
            entry = try cursor.next();
        };
        var records: std.ArrayListUnmanaged(metadata.TableRecord) = .empty;
        errdefer {
            for (records.items) |record| metadata_table_manager.freeTable(alloc, record);
            records.deinit(alloc);
        }
        var count: usize = 0;
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix) or count == 16) break;
            count += 1;
            var table_buf: [160]u8 = undefined;
            const bytes = if (job.bootstrap) row.value else blk: {
                const id = try resolverConsumerSourceId(a, row.value);
                break :blk txn.get(try tableKeyForGroup(&table_buf, group_id, id)) catch |err| switch (err) {
                    error.NotFound => continue,
                    else => return err,
                };
            };
            const record = try decodeTableRecord(alloc, bytes);
            errdefer metadata_table_manager.freeTable(alloc, record);
            try records.append(alloc, record);
        }
        return records.toOwnedSlice(alloc);
    }

    /// The same-table CAS is a bounded metadata-Raft page. Source projections,
    /// their catalog notifications, and the job cursor commit together.
    fn advanceResolverNamespaceTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !void {
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const job_key = try std.fmt.allocPrint(a, "{s}{d}", .{ try resolverJobPrefix(a, group_id), record.table_id });
        const raw = txn.get(job_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        var job = try std.json.parseFromSliceLeaky(ResolverNamespaceJob, a, raw, .{});
        try txn.put(try resolverScheduleKey(a, group_id), job_key);
        if (!job.bootstrap and try stagingGet(txn, try resolverNamespaceBootstrapKey(a, group_id)) == null) {
            job.bootstrap = true;
            job.after = null;
        }
        const prefix = if (job.bootstrap) blk: {
            var buf: [128]u8 = undefined;
            break :blk try a.dupe(u8, try tablePrefixForGroup(&buf, group_id));
        } else try self.resolverConsumerPrefixTxn(a, txn, group_id, record.table_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        if (job.after) |after| if (!std.mem.startsWith(u8, after, prefix)) {
            job.after = null;
        };
        var entry = try cursor.seekAtOrAfter(job.after orelse prefix);
        if (job.after) |after| if (entry) |row| if (std.mem.eql(u8, row.key, after)) {
            entry = try cursor.next();
        };
        var rows: std.ArrayListUnmanaged(docstore.OwnedKVPair) = .empty;
        while (entry) |row| {
            if (!std.mem.startsWith(u8, row.key, prefix) or rows.items.len == 16) break;
            try rows.append(a, .{ .key = try a.dupe(u8, row.key), .value = try a.dupe(u8, row.value) });
            entry = try cursor.next();
        }
        const done = entry == null or !std.mem.startsWith(u8, entry.?.key, prefix);
        // Copy the bounded page before writing: cursor values are txn-owned.
        for (rows.items) |row| {
            var key_buf: [160]u8 = undefined;
            const bytes = if (job.bootstrap) row.value else blk: {
                const id = try resolverConsumerSourceId(a, row.value);
                break :blk txn.get(try tableKeyForGroup(&key_buf, group_id, id)) catch |err| switch (err) {
                    error.NotFound => {
                        try txn.delete(row.key);
                        continue;
                    },
                    else => return err,
                };
            };
            const source = try decodeTableRecord(a, bytes);
            if ((try self.loadTableTransitionFenceTxn(txn, group_id, source.table_id)).active() or try self.fkGenerationTableLockedTxn(txn, group_id, source.table_id)) return;
            // Legacy sources may have no reverse edges yet. Bootstrap enrolls
            // them even when their effective policy did not change.
            if (job.bootstrap) try self.synchronizeResolverDependenciesTxn(a, txn, group_id, null, source);
            const projected = try self.projectResolverNamespacesTxn(a, txn, group_id, source);
            if (!metadata_table_manager.tableDefinitionsEqual(source, projected)) {
                const key = try tableKeyForGroup(&key_buf, group_id, source.table_id);
                try self.putTableRecordTxnModeRaw(txn, group_id, key, projected, false);
            }
            job.after = row.key;
        }
        if (done and job.bootstrap) {
            try txn.put(try resolverNamespaceBootstrapKey(a, group_id), "1");
            job.bootstrap = false;
            job.after = null;
            job.dirty = false;
        } else if (done and job.dirty) {
            job.after = null;
            job.dirty = false;
        } else if (done) {
            try txn.delete(job_key);
            return;
        }
        try txn.put(job_key, try std.json.Stringify.valueAlloc(a, job, .{}));
    }

    fn putTableRecordTxnMode(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, key: []const u8, record: metadata.TableRecord, published_fk_generation: bool) !void {
        try self.putTableRecordTxnModeRaw(txn, group_id, key, record, published_fk_generation);
    }

    fn putTableRecordTxnModeRaw(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        key: []const u8,
        record: metadata.TableRecord,
        published_fk_generation: bool,
    ) !void {
        const accepted = try self.tryPutTableRecordTxnMode(txn, group_id, key, record, published_fk_generation);
        if (published_fk_generation and !accepted) return error.GenerationPublicationChanged;
    }

    fn tryPutTableRecordTxnMode(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        key: []const u8,
        record: metadata.TableRecord,
        published_fk_generation: bool,
    ) !bool {
        var prepared = (try self.prepareTableRecordTxnMode(txn, group_id, key, record, published_fk_generation)) orelse return false;
        defer prepared.deinit(self.alloc);
        try self.writePreparedTableRecordTxn(txn, group_id, key, prepared);
        return true;
    }

    /// Bytes and rename ownership survive preparation of every target in one
    /// pinned transaction. Only the name borrows its enclosing command/plan;
    /// decoded predecessor fields never escape into this prepared value.
    /// This is local write admission, not an installed-root owner receipt.
    const PreparedTableRecordWrite = struct {
        identity: struct { table_id: u64, name: []const u8 },
        value: []u8,
        previous_name: ?[]u8,
        lake_value: ?[]u8,
        column_identity_value: ?[]u8,
        source_changed: bool,
        fingerprint: [32]u8,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.value);
            if (self.previous_name) |name| alloc.free(name);
            if (self.lake_value) |bytes| alloc.free(bytes);
            if (self.column_identity_value) |bytes| alloc.free(bytes);
            self.* = undefined;
        }
    };

    fn prepareTableRecordTxnMode(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        key: []const u8,
        input_record: metadata.TableRecord,
        published_fk_generation: bool,
    ) !?PreparedTableRecordWrite {
        var resolver_arena = std.heap.ArenaAllocator.init(self.alloc);
        defer resolver_arena.deinit();
        const record = (try self.admittedResolverProjectionTxn(resolver_arena.allocator(), txn, group_id, input_record)) orelse return null;
        const encoded_existing = txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const source_tracked = try relation_reconciliation.readSourceRevision(txn, group_id) != 0;
        var previous_digest: ?[32]u8 = null;
        var previous_name: ?[]u8 = null;
        errdefer if (previous_name) |name| self.alloc.free(name);
        if (encoded_existing) |encoded| {
            const existing = try decodeTableRecord(self.alloc, encoded);
            defer metadata_table_manager.freeTable(self.alloc, existing);
            if (source_tracked) previous_digest = relationTableSourceDigest(existing.table_id, existing.name, existing.schema_json);
            if (!std.mem.eql(u8, existing.schema_json, record.schema_json))
                try @import("../schema_validation_dependencies.zig").requireDefinitionsRetained(self.alloc, txn, group_id, record.table_id, record.schema_json);
            const lock_kind = if (!published_fk_generation and !metadata_table_manager.tableDefinitionsEqual(existing, record))
                try self.fkTableLockKindTxn(txn, group_id, record.table_id)
            else
                null;
            if (lock_kind) |kind| {
                // The initial-FK support reservation must permit its exact
                // schema-migration finalization. An ADD/DROP generation lock,
                // however, binds an immutable table cut: allowing that same
                // finalization would invalidate the plan after admission and
                // strand the publication despite healthy owners.
                if (kind != .initial_support) return null;
                if (existing.read_schema_json.len == 0 or record.read_schema_json.len != 0) return null;
                var finalized = try metadata_table_manager.cloneTable(self.alloc, existing);
                defer metadata_table_manager.freeTable(self.alloc, finalized);
                try @import("../schema_migration_finalization.zig").apply(self.alloc, &finalized);
                if (!metadata_table_manager.tableDefinitionsEqual(finalized, record) or
                    !try self.schemaMigrationReadyTxn(txn, group_id, record.table_id, try @import("../../api/tables.zig").schemaVersion(existing.schema_json))) return null;
            }
            // Policy bytecode and owner descriptors bind the exact typed-row
            // layout. Relational index DDL changes schema_json even when its
            // indexed columns do not change; publishing that schema alone
            // would leave every owner serving an old policy layout. Until a
            // coupled schema/policy candidate is acknowledged by every owner,
            // reject the mutation at the common table writer rather than
            // accepting DDL that later makes protected reads unavailable.
            if (!try self.policyDefinitionMutationAllowedTxn(txn, group_id, existing, record))
                return error.RowPolicyUnsupported;
            if (!std.mem.eql(u8, existing.name, record.name)) previous_name = try self.alloc.dupe(u8, existing.name);
        } else if (!published_fk_generation and try self.fkGenerationTableLockedTxn(txn, group_id, record.table_id)) return null;
        if (record.schema_reader_requirements) |requirement| {
            // Invalid pairs retain the table encoder's established error.
            if (requirement.valid()) _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_reader_publication_version);
        }
        if (record.full_text_read_index != null)
            _ = try self.standbyRelationActivationTxn(txn, group_id, topology_protocol.schema_validation_publication_version);
        const lake_value = try self.prepareLakeIndexLifecycleTxn(txn, group_id, record);
        errdefer if (lake_value) |bytes| self.alloc.free(bytes);
        const column_value = self.prepareTrackedColumnIdentitiesTxn(txn, group_id, record) catch |err| switch (err) {
            error.ColumnIdentityDefinitionRejected => return null,
            else => return err,
        };
        errdefer if (column_value) |bytes| self.alloc.free(bytes);
        const value = try encodeTableRecord(self.alloc, record);
        const source_changed = if (source_tracked) changed: {
            const digest = relationTableSourceDigest(record.table_id, record.name, record.schema_json);
            break :changed previous_digest == null or !std.mem.eql(u8, &previous_digest.?, &digest);
        } else false;
        return .{
            .identity = .{ .table_id = record.table_id, .name = record.name },
            .value = value,
            .previous_name = previous_name,
            .lake_value = lake_value,
            .column_identity_value = column_value,
            .source_changed = source_changed,
            .fingerprint = policyTableSchemaRecordDigest(record),
        };
    }

    /// No semantic rejection is permitted once publication starts. Failures
    /// here abort the containing transaction, including its catalog/outbox.
    fn writePreparedTableRecordTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, key: []const u8, prepared: PreparedTableRecordWrite) !void {
        var resolver_arena = std.heap.ArenaAllocator.init(self.alloc);
        defer resolver_arena.deinit();
        const definition = try decodeTableRecord(resolver_arena.allocator(), prepared.value);
        // Attribute retirement owns its sequences just as whole-table DROP
        // does. Publish dependency cleanup and the new layout in one native
        // transaction, after admission and before replacing stable identities.
        if (prepared.column_identity_value) |bytes| {
            var successor = try column_identities.State.decode(resolver_arena.allocator(), bytes);
            defer successor.deinit();
            try self.retireOwnedSequencesTxn(txn, group_id, prepared.identity.table_id, successor.value);
        }
        try self.synchronizeResolverTableRecordTxn(txn, group_id, key, definition);
        const record = prepared.identity;
        if (prepared.column_identity_value) |bytes| {
            const column_key = try column_identities.key(.{ .group = group_id, .table = record.table_id });
            try txn.put(&column_key, bytes);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = &column_key });
        }
        if (prepared.previous_name) |name| try self.deleteTableNameIndexTxn(txn, group_id, name);
        if (prepared.lake_value) |bytes| {
            var buffer: [160]u8 = undefined;
            try txn.put(try lakeIndexLifecycleKeyForGroup(&buffer, group_id, record.table_id), bytes);
        }
        if (prepared.source_changed) try relation_reconciliation.advanceSource(txn, group_id);
        try txn.put(key, prepared.value);
        var fingerprint_key_buf: [192]u8 = undefined;
        try txn.put(try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group_id, record.table_id), &prepared.fingerprint);
        try self.putTableNameIndexTxn(txn, group_id, record.name, record.table_id);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .table,
            .metadata_group_id = group_id,
            .table_name = record.name,
            .table_id = record.table_id,
        });
    }

    fn columnIdentityValue(alloc: std.mem.Allocator, record: metadata.TableRecord, previous: ?column_identities.State, renames: []const column_identities.Rename) ![]u8 {
        if (record.schema_json.len > column_identities.max_encoded_bytes * 4) return error.ColumnIdentityLimitExceeded;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const sources = @import("antfly_local_sources");
        const parsed = try sources.schema_mod.parseValidatedTableSchema(a, if (record.schema_json.len == 0) "{}" else record.schema_json);
        const columns = if (parsed.storage_mode == .document)
            try sources.sql_document_row.deriveColumns(a, parsed)
        else relational: {
            const native = try sources.schema_mod.deriveRuntimeTableSchema(a, parsed);
            break :relational try sources.sql_document_row.deriveRelationalColumnsLeaky(a, a, parsed, native);
        };
        const table: sources.sql_catalog.Table = .{ .id = record.table_id, .physical_name = record.name, .schema_version = parsed.version, .storage_mode = if (parsed.storage_mode == .document) .document else .relational, .columns = columns };
        const virtual = table.virtualColumns();
        if (columns.len + virtual.len > column_identities.max_columns) return error.ColumnIdentityLimitExceeded;
        const declarations = try a.alloc(column_identities.Declaration, columns.len + virtual.len);
        for (columns, declarations[0..columns.len]) |column, *out| out.* = .{ .name = column.name, .signature = try column.identitySignature(a) };
        for (virtual, declarations[columns.len..]) |column, *out| out.* = .{ .name = column.name, .signature = try column.identitySignature(a) };
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(record.schema_json, &digest, .{});
        var prepared = try column_identities.prepare(alloc, record.table_id, previous, .{ .version = parsed.version, .digest = digest }, declarations, renames);
        defer prepared.deinit();
        return prepared.value.encode(alloc);
    }

    const SqlViewIdentity = sql_views.Identity;
    const SequenceOwnerBootstrap = struct { key: []const u8, value: []const u8 };

    /// Verify a stable owner attribute against the actual table cut. Preparing
    /// the first attribute identity record is read-only until the caller's
    /// complete sequence/catalog mutation is ready to commit.
    fn verifySequenceOwnerTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, namespace_id: u64, owner: sql_sequences.sequence.OwnedBy, guard: ?system_catalog.RelationMutationGuard) !?SequenceOwnerBootstrap {
        try owner.validate();
        var reservation_buffer: [256]u8 = undefined;
        if (try stagingGet(txn, try restore_staging.identityKey(&reservation_buffer, group, .old_table, owner.table_id)) != null) return error.CatalogGenerationChanged;
        return (try self.bindSequenceOwnerTxn(a, txn, group, namespace_id, owner.table_id, guard, .{ .id = owner.column_id }) orelse return error.CatalogGenerationChanged).bootstrap;
    }

    const BoundSequenceOwner = struct { namespace_id: u64, column: sql_sequences.sequence.OwnedBy, bootstrap: ?SequenceOwnerBootstrap };
    fn bindSequenceOwnerTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, wanted_namespace: ?u64, table_id: u64, guard: ?system_catalog.RelationMutationGuard, column: union(enum) { id: u64, name: []const u8 }) !?BoundSequenceOwner {
        var table_buffer: [160]u8 = undefined;
        const raw = try stagingGet(txn, try tableKeyForGroup(&table_buffer, group, table_id)) orelse return error.CatalogGenerationChanged;
        const table = try decodeTableRecord(a, raw);
        if (table.table_id != table_id) return error.InvalidCatalogRecord;
        var namespace_id: u64 = undefined;
        if (guard) |proof| {
            if (proof.owner.kind != .table or proof.owner.table_id != table_id) return error.CatalogGenerationChanged;
            var scope = try self.guardedRelationOwnerTxn(txn, group, proof);
            defer scope.deinit();
            namespace_id = scope.namespace_id;
            if (!std.mem.eql(u8, scope.physicalName(proof), table.name)) return error.CatalogGenerationChanged;
            var digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(table.schema_json, &digest, .{});
            if (!std.mem.eql(u8, &digest, &proof.owner.schema_digest)) return error.CatalogGenerationChanged;
        } else {
            var binding = try system_catalog_storage.getById(a, txn, group, .table, table_id);
            defer if (binding) |*value| value.deinit();
            if (binding) |value| {
                if (!std.mem.eql(u8, value.value.storage_name, table.name)) return error.CatalogGenerationChanged;
                namespace_id = value.value.parent_id;
            } else namespace_id = system_catalog.default_namespace_id;
        }
        if (wanted_namespace) |wanted| if (wanted != namespace_id) return error.CatalogGenerationChanged;
        const key = try column_identities.key(.{ .group = group, .table = table_id });
        const prior = try stagingGet(txn, &key);
        if (prior == null) {
            // Once an owned sequence exists, lost attribute identities cannot
            // be regenerated from ordinals and rebound to different columns.
            var prefix_buffer: [192]u8 = undefined;
            const prefix = try sql_sequences.ownerPrefix(&prefix_buffer, group, table_id);
            var cursor = try txn.openCursor();
            defer cursor.close();
            if (try cursor.seekAtOrAfter(prefix)) |entry|
                if (std.mem.startsWith(u8, entry.key, prefix)) return error.InvalidSequenceState;
        }
        const bytes = prior orelse try columnIdentityValue(a, table, null, &.{});
        try validateColumnIdentityRecord(a, .{ .group = group, .table = table_id }, bytes, raw);
        var attributes = try column_identities.State.decode(a, bytes);
        defer attributes.deinit();
        const id = switch (column) {
            .id => |value| (attributes.value.columnById(value) orelse return error.CatalogGenerationChanged).id,
            .name => |name| for (attributes.value.columns) |value| {
                if (std.mem.eql(u8, name, value.name)) break value.id;
            } else return null,
        };
        return .{ .namespace_id = namespace_id, .column = .{ .table_id = table_id, .column_id = id }, .bootstrap = if (prior == null) .{ .key = try a.dupe(u8, &key), .value = bytes } else null };
    }

    /// One bounded metadata read cut. No schema/attribute bootstrap is written
    /// by lookup; its provisional identity is guarded again during mutation.
    pub fn sqlSequenceSnapshot(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: sql_sequences.SnapshotRequest, context: @import("antfly_local_sources").api_operation.RequestContext) ![]u8 {
        try context.ensureActive();
        try request.validate();
        var txn = try self.beginQueryCatalogReadTxn(group);
        defer txn.abort();
        // Binding existing namespaces must work before the first sequence
        // activates its decoder. Reading an actual sequence still requires
        // the durable sequence barrier below; discovery never upgrades it.
        _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.constraint_occupancy_version);
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, &txn, group);
        const epoch = try relationSourceEpochTxn(&txn, group);
        if (request.incarnation) |expected| if (!std.mem.eql(u8, &expected, &epoch.incarnation)) return error.CatalogGenerationChanged;
        var registry = try RelationRegistry(docstore.DocStore.Txn).init(a, &txn, group);
        const live = registry.live orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names or !live.root.epoch.eql(epoch) or !try relationWriterEnabledTxn(&txn, group)) return error.CatalogOccupancyNotReady;
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = &txn, .group_id = group, .meta = meta };
        const entries = try a.alloc(sql_sequences.Snapshot.Entry, request.targets.len);
        var sequence_decoder_checked = false;
        for (request.targets, entries, 0..) |requested, *entry, ordinal| {
            var target = requested;
            var bound_resource: ?system_catalog.Resource = null;
            if (request.sequence_ids) |ids| {
                bound_resource = try view.byId(.sequence, ids[ordinal]);
                if (bound_resource) |resource| {
                    const parent_namespace = (try view.byId(.namespace, resource.parent_id)) orelse return error.InvalidCatalogRecord;
                    const parent_database = (try view.byId(.database, parent_namespace.parent_id)) orelse return error.InvalidCatalogRecord;
                    target = .{ .database = parent_database.name, .namespace = parent_namespace.name, .table = resource.name };
                } else {
                    entry.* = .{ .target = requested, .namespace_id = null, .value = .absent };
                    continue;
                }
            }
            try context.ensureActive();
            entry.* = .{ .target = target, .namespace_id = null, .value = .absent };
            const namespace = view.namespaceFor(target.database, target.namespace) catch |err| switch (err) {
                error.DatabaseNotFound => {
                    entry.value = .missing_database;
                    continue;
                },
                error.NamespaceNotFound => {
                    entry.value = .missing_namespace;
                    continue;
                },
                else => return err,
            };
            entry.namespace_id = namespace.id;
            const resource = if (request.sequence_ids != null) bound_resource else try view.lookup(.sequence, namespace.id, target.table);
            const occupied = try registry.getEntry(.{ .namespace_id = namespace.id, .name = target.table }) != null or
                try view.lookup(.table, namespace.id, target.table) != null or try view.lookup(.view, namespace.id, target.table) != null;
            if (resource) |value| {
                if (!sequence_decoder_checked) {
                    _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.sql_sequence_catalog_version);
                    sequence_decoder_checked = true;
                }
                if (occupied or value.id >= meta.next_id or value.storage_name.len != 0 or value.tablespace_id != 0) return error.InvalidSequenceState;
                const descriptor = try sql_sequences.sequence.Descriptor.decode(a, value.source_json);
                if (descriptor.id != value.id) return error.InvalidSequenceState;
                const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .key = .{ .group = group, .sequence_id = value.id } };
                const state = (try counter.load(a, try descriptor.definition())) orelse return error.InvalidSequenceState;
                entry.value = .{ .sequence = descriptor };
                if (request.include_counters) entry.counter = state;
            } else if (occupied) entry.value = .other;
        }
        var owner: ?sql_sequences.Snapshot.Owner = null;
        if (request.owner) |wanted| {
            try context.ensureActive();
            if (try self.bindSequenceOwnerTxn(a, &txn, group, null, wanted.guard.owner.table_id, wanted.guard, .{ .name = wanted.column })) |bound|
                owner = .{ .namespace_id = bound.namespace_id, .column = bound.column };
        }
        if (request.column_default) |wanted| {
            try context.ensureActive();
            _ = try self.standbyRelationActivationTxn(&txn, group, topology_protocol.sql_column_sequences_version);
            var table_buffer: [160]u8 = undefined;
            const encoded = try stagingGet(&txn, try tableKeyForGroup(&table_buffer, group, wanted.scope.table_id)) orelse return error.CatalogGenerationChanged;
            const table = try decodeTableRecord(a, encoded);
            if (!std.mem.eql(u8, table.name, wanted.scope.storage_name) or try @import("../../api/tables.zig").schemaVersion(table.schema_json) != wanted.scope.schema_version) return error.CatalogGenerationChanged;
            if ((try self.loadTableTransitionFenceTxn(&txn, group, table.table_id)).active()) return error.TableTransitionActive;
            if (try self.bindSequenceOwnerTxn(a, &txn, group, null, table.table_id, null, .{ .name = wanted.column })) |bound| {
                if (bound.bootstrap != null) return error.InvalidSequenceState;
                const resource = try view.byId(.table, table.table_id);
                owner = .{ .namespace_id = bound.namespace_id, .column = bound.column, .table_name = if (resource) |value| value.name else table.name };
            }
        }
        const result: sql_sequences.Snapshot = .{ .metadata_group_id = group, .revision = meta.revision, .head = meta.sequence_outcome_head orelse 0, .incarnation = epoch.incarnation, .entries = entries, .owner = owner };
        try result.validate(request);
        try context.ensureActive();
        return std.json.Stringify.valueAlloc(alloc, result, .{});
    }

    fn validateSqlSequenceCommandTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: SystemCatalogCommand) !void {
        const request = command.sql_sequence orelse return error.InvalidCatalogMutation;
        try request.validate();
        const expected_action: system_catalog.Action = switch (request.operation) {
            .create => .create,
            .alter => .alter,
            .rename => .rename,
            .drop => .drop,
        };
        if (command.version != 3 or command.expected_revision != 0 or command.sql_view != null or command.column_sequences.len != 0 or
            command.topology != null or command.placement_update != null or command.constraint_name_admission != null or
            command.mutation.kind != .sequence or command.mutation.action != expected_action or
            command.mutation.table_id != 0 or command.mutation.storage_name.len != 0 or command.mutation.new_name != null or
            command.mutation.tablespace != null or command.mutation.placement_policy.placement_role != null or
            command.mutation.placement_policy.desired_replica_count != null or command.mutation.placement_policy.min_ranges != null or
            !std.mem.eql(u8, command.mutation.location_json, "null") or !std.mem.eql(u8, command.mutation.source_json, "null") or
            !std.mem.eql(u8, command.mutation.database, request.target.database) or
            !std.mem.eql(u8, command.mutation.namespace, request.target.namespace) or
            !std.mem.eql(u8, command.mutation.name, request.target.table)) return error.InvalidCatalogMutation;
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_sequence_catalog_version);
        const epoch = try relationSourceEpochTxn(txn, group);
        if (!std.mem.eql(u8, &epoch.incarnation, &request.incarnation)) return error.CatalogGenerationChanged;
    }

    fn prepareSqlSequenceCatalogTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: SystemCatalogCommand) !sql_sequences.Result {
        try self.validateSqlSequenceCommandTxn(txn, group, command);
        const request = command.sql_sequence.?;
        const outcomes: sql_sequences.outcomes.Store(docstore.DocStore.Txn) = .{ .txn = txn, .group = group, .incarnation = request.incarnation };
        switch (try outcomes.prepare(self.alloc, request.admission, try sql_sequences.commandDigest(self.alloc, request))) {
            .replay => |outcome| return outcome.result(),
            .append => return self.applySqlSequenceCatalogTxn(txn, group, command, false),
        }
    }

    fn applySqlSequenceOutcomeTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: SystemCatalogCommand) !void {
        try self.validateSqlSequenceCommandTxn(txn, group, command);
        const request = command.sql_sequence.?;
        const outcomes: sql_sequences.outcomes.Store(docstore.DocStore.Txn) = .{ .txn = txn, .group = group, .incarnation = request.incarnation };
        const digest = try sql_sequences.commandDigest(self.alloc, request);
        switch (try outcomes.prepare(self.alloc, request.admission, digest)) {
            .replay => return,
            .append => |ordinal| {
                const result = self.applySqlSequenceCatalogTxn(txn, group, command, true);
                const outcome: sql_sequences.Outcome = if (result) |value| .{ .success = value } else |err| sql_sequences.Outcome.fromError(err) orelse return err;
                // The applied identity/outcome, not its read-only preview,
                // shares the native definition/counter transaction.
                try outcomes.append(self.alloc, ordinal, request.admission, digest, outcome);
            },
        }
    }

    pub fn sqlSequenceAdmissionHead(self: *RaftApplyStore, group: u64) !u64 {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        const outcomes: sql_sequences.outcomes.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .group = group, .incarnation = (try relationSourceEpochTxn(&txn, group)).incarnation };
        return outcomes.head(self.alloc);
    }

    const SequenceCounterBinding = struct { definition: sql_sequences.sequence.Definition, matches_name: bool };

    fn sequenceCounterBindingTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, request: sql_sequences.CounterRequest) !?SequenceCounterBinding {
        try request.validate();
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_sequence_catalog_version);
        const epoch = try relationSourceEpochTxn(txn, group);
        if (!std.mem.eql(u8, &epoch.incarnation, &request.incarnation)) return null;
        var resource = (try system_catalog_storage.getById(a, txn, group, .sequence, request.sequence_id)) orelse return null;
        defer resource.deinit();
        if (resource.value.parent_id != request.namespace_id) return null;
        const descriptor = try sql_sequences.sequence.Descriptor.decode(a, resource.value.source_json);
        if (descriptor.id != request.sequence_id) return error.InvalidCatalogRecord;
        const definition = try descriptor.definition();
        if (definition.generation != request.request.expected.generation) return null;
        const meta = try system_catalog_storage.readMeta(a, txn, group);
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group, .meta = meta };
        const namespace = view.namespaceFor(request.target.database, request.target.namespace) catch |err| switch (err) {
            error.DatabaseNotFound, error.NamespaceNotFound => return .{ .definition = definition, .matches_name = false },
            else => return err,
        };
        return .{ .definition = definition, .matches_name = namespace.id == request.namespace_id and std.mem.eql(u8, resource.value.name, request.target.table) };
    }

    fn sequenceCounterAdmissionTxn(self: *RaftApplyStore, a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, request: sql_sequences.CounterRequest) !sql_sequences.CounterAdmission {
        // An old generation/scope may have applied before retirement.
        const binding = (try self.sequenceCounterBindingTxn(a, txn, group, request)) orelse return .unknown;
        return sequenceCounterAdmissionBoundTxn(a, txn, group, request, binding);
    }

    fn sequenceCounterAdmissionBoundTxn(a: std.mem.Allocator, txn: *docstore.DocStore.Txn, group: u64, request: sql_sequences.CounterRequest, binding: SequenceCounterBinding) !sql_sequences.CounterAdmission {
        const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = request.sequence_id } };
        const admission = counter.admission(a, binding.definition, request.request) catch |err| {
            const rejected = sql_sequences.CounterOutcome.fromError(err) orelse return err;
            return .{ .rejected = rejected.rejected };
        };
        return switch (admission) {
            .ready => if (binding.matches_name) .ready else .{ .rejected = .CatalogGenerationChanged },
            .applied => |value| .{ .applied = value },
            .unknown => .unknown,
        };
    }

    pub fn sqlSequenceCounterPreflight(self: *RaftApplyStore, a: std.mem.Allocator, group: u64, request: sql_sequences.CounterRequest) !sql_sequences.CounterAdmission {
        // Immutable-ID and namespace point reads need no derived name-registry
        // reconstruction. Allocation never starts a full catalog scan.
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        // Catalog views intentionally borrow arena-owned decoded resources.
        // The result is fixed-width and owns no pointers into this scratch.
        var scratch = std.heap.ArenaAllocator.init(a);
        defer scratch.deinit();
        return self.sequenceCounterAdmissionTxn(scratch.allocator(), &txn, group, request);
    }

    pub fn sqlSequenceCounterOutcome(self: *RaftApplyStore, a: std.mem.Allocator, group: u64, request: sql_sequences.CounterRequest) !?sql_sequences.CounterOutcome {
        return switch (try self.sqlSequenceCounterPreflight(a, group, request)) {
            .applied => |value| .{ .success = value },
            .rejected => |value| .{ .rejected = value },
            .ready, .unknown => null,
        };
    }

    fn applySqlSequenceCounterTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, bytes: []const u8) !void {
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const request = try std.json.parseFromSliceLeaky(sql_sequences.CounterRequest, a, bytes, .{});
        try request.validate();
        const binding = (try self.sequenceCounterBindingTxn(a, txn, group, request)) orelse return;
        switch (try sequenceCounterAdmissionBoundTxn(a, txn, group, request, binding)) {
            .ready => {},
            .applied, .rejected, .unknown => return,
        }
        const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = request.sequence_id } };
        _ = try counter.execute(a, binding.definition, request.request);
    }

    /// Typed semantic rejection survives the checked owner boundary without
    /// expanding the generic runtime error ABI or losing SQL diagnostics.
    pub fn sqlSequencePreflight(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: sql_sequences.Mutation) !sql_sequences.Outcome {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        self.validateSqlSequenceCommandTxn(&txn, group, sql_sequences.command(request)) catch |err| return switch (err) {
            error.CatalogGenerationChanged => error.MetadataMutationOutcomeUnknown,
            else => err,
        };
        const result = self.prepareSqlSequenceCatalogTxn(&txn, group, sql_sequences.command(request));
        _ = alloc;
        return if (result) |value| .{ .success = value } else |err| sql_sequences.Outcome.fromError(err) orelse return switch (err) {
            error.SequenceAdmissionExpired, error.SequenceAdmissionConflict => error.MetadataMutationOutcomeUnknown,
            else => err,
        };
    }

    /// Observe only: unknown/evicted admission is never permission to submit a
    /// fresh mutation. The caller keeps its existing proposal receipt/deadline.
    pub fn sqlSequenceOutcome(self: *RaftApplyStore, alloc: std.mem.Allocator, group: u64, request: sql_sequences.Mutation) !sql_sequences.Outcome {
        var txn = try self.store.beginReadTxn();
        defer txn.abort();
        try self.validateSqlSequenceCommandTxn(&txn, group, sql_sequences.command(request));
        const outcomes: sql_sequences.outcomes.Store(docstore.DocStore.Txn) = .{ .txn = &txn, .group = group, .incarnation = request.incarnation };
        return (try outcomes.lookup(alloc, request.admission, try sql_sequences.commandDigest(alloc, request))) orelse error.MetadataMutationOutcomeUnknown;
    }

    /// One transaction owns the namespace binding, immutable descriptor,
    /// mutable counter and reverse ownership edge. This is the same path for
    /// read-only admission, standalone commits and deterministic Raft apply.
    fn applySqlSequenceCatalogTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: SystemCatalogCommand, apply: bool) !sql_sequences.Result {
        try self.validateSqlSequenceCommandTxn(txn, group, command);
        const request = command.sql_sequence.?;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const epoch = try relationSourceEpochTxn(txn, group);
        const meta = try system_catalog_storage.readMeta(a, txn, group);
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group, .meta = meta };
        const namespace = try view.namespaceFor(request.target.database, request.target.namespace);
        if (namespace.id != request.namespace_id) return error.CatalogGenerationChanged;
        var registry = try RelationRegistry(docstore.DocStore.Txn).init(a, txn, group);
        const live = registry.live orelse return error.CatalogPublicationProofPending;
        if (live.root.coverage != .constraint_names or !live.root.epoch.eql(epoch)) return error.CatalogOccupancyNotReady;
        if (!try relationWriterEnabledTxn(txn, group)) return error.CatalogOccupancyNotReady;
        const resource = try view.lookup(.sequence, namespace.id, request.target.table);
        const occupied = try registry.getEntry(.{ .namespace_id = namespace.id, .name = request.target.table }) != null or
            try view.lookup(.table, namespace.id, request.target.table) != null or
            try view.lookup(.view, namespace.id, request.target.table) != null;
        if (resource != null and occupied) return error.InvalidCatalogRecord;
        const sequence = sql_sequences.sequence;
        const Counter = sql_sequences.journal.Store(docstore.DocStore.Txn);
        const descriptor: ?sequence.Descriptor = if (resource) |value| blk: {
            const decoded = sequence.Descriptor.decode(a, value.source_json) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return error.InvalidSequenceState,
            };
            if (decoded.id != value.id or value.storage_name.len != 0 or value.tablespace_id != 0) return error.InvalidCatalogRecord;
            break :blk decoded;
        } else null;
        if (request.operation == .create) {
            if (resource != null or occupied) {
                if (!request.operation.create.if_not_exists) return error.CatalogAlreadyExists;
                return .{ .revision = meta.revision, .identity = if (descriptor) |value| .{ .id = value.id, .generation = value.generation } else null, .removed = 0 };
            }
        } else if (descriptor == null) {
            if (occupied) return error.SqlWrongObjectType;
            if (request.operation == .drop and request.operation.drop.if_exists and request.operation.drop.expected == null)
                return .{ .revision = meta.revision, .identity = null, .removed = 0 };
            return error.SequenceNotFound;
        }
        var prior: ?sequence.Record = null;
        if (descriptor) |value| {
            const expected: sql_sequences.Identity = switch (request.operation) {
                .alter => |input| input.expected,
                .rename => |input| input.expected,
                .drop => |input| input.expected orelse return error.CatalogGenerationChanged,
                .create => unreachable,
            };
            if (expected.id != value.id or expected.generation != value.generation) return error.CatalogGenerationChanged;
            const layout = try value.definition();
            const counter: Counter = .{ .txn = txn, .key = .{ .group = group, .sequence_id = value.id } };
            const state = counter.load(a, layout) catch |err| switch (err) {
                error.SequenceCatalogChanged, error.InvalidSequenceDefinition => return error.InvalidSequenceState,
                else => return err,
            };
            prior = .{ .definition = layout, .state = state orelse return error.InvalidSequenceState };
        }
        var next = prior;
        var next_name = request.target.table;
        var next_id = meta.next_id;
        const id = if (descriptor) |value| value.id else meta.next_id;
        switch (request.operation) {
            .create => |input| {
                next = try sequence.Record.create(input.options);
                next_id = std.math.add(u64, next_id, 1) catch return error.CatalogIdExhausted;
                const counter: Counter = .{ .txn = txn, .key = .{ .group = group, .sequence_id = id } };
                const existing = counter.load(a, next.?.definition) catch |err| switch (err) {
                    error.SequenceCatalogChanged, error.InvalidSequenceDefinition => return error.InvalidSequenceState,
                    else => return err,
                };
                if (existing != null) return error.InvalidSequenceState;
            },
            .alter => |input| next = try prior.?.alter(input.options),
            .rename => |input| {
                if (try registry.getEntry(.{ .namespace_id = namespace.id, .name = input.name }) != null or
                    try view.lookup(.table, namespace.id, input.name) != null or try view.lookup(.view, namespace.id, input.name) != null or
                    try view.lookup(.sequence, namespace.id, input.name) != null) return error.CatalogAlreadyExists;
                next_name = input.name;
            },
            .drop => next = null,
        }
        const before_owner = if (prior) |value| value.definition.owned_by else null;
        if (before_owner) |owner| {
            var reservation_buffer: [256]u8 = undefined;
            if (try stagingGet(txn, try restore_staging.identityKey(&reservation_buffer, group, .old_table, owner.table_id)) != null) return error.CatalogGenerationChanged;
        }
        const after_owner = if (next) |value| value.definition.owned_by else null;
        var owner_bootstrap: ?SequenceOwnerBootstrap = null;
        if (after_owner) |owner| owner_bootstrap = try self.verifySequenceOwnerTxn(a, txn, group, namespace.id, owner, request.owner_guard);
        var key_buffer: [192]u8 = undefined;
        if (before_owner) |owner| {
            const edge = (try stagingGet(txn, try sql_sequences.ownerKey(&key_buffer, group, owner, id))) orelse return error.InvalidSequenceState;
            if (!std.mem.eql(u8, edge, &.{1})) return error.InvalidSequenceState;
        }
        const changed_owner = !std.meta.eql(before_owner, after_owner);
        if (changed_owner) if (after_owner) |owner| if (try stagingGet(txn, try sql_sequences.ownerKey(&key_buffer, group, owner, id)) != null) return error.InvalidSequenceState;
        if (request.operation == .alter and std.meta.eql(prior.?, next.?)) return .{ .revision = meta.revision, .identity = .{ .id = id, .generation = next.?.definition.generation }, .removed = 0 };
        var upserts: [1]system_catalog.Resource = undefined;
        if (next) |value| upserts[0] = .{ .kind = .sequence, .id = id, .parent_id = namespace.id, .name = next_name, .source_json = try (try sequence.Descriptor.init(id, value.definition)).encode(a) };
        const revision = std.math.add(u64, meta.revision, 1) catch return error.CatalogRevisionExhausted;
        const result: sql_sequences.Result = .{ .revision = revision, .identity = if (next) |value| .{ .id = id, .generation = value.definition.generation } else null, .removed = if (next == null) 1 else 0 };
        if (!apply) return result;
        // All semantic checks above are read-only. Any failure below aborts
        // the native write transaction; no standalone registry commits exist.
        const counter: Counter = .{ .txn = txn, .key = .{ .group = group, .sequence_id = id } };
        switch (request.operation) {
            .create => try counter.initialize(a, next.?),
            .alter => |input| _ = try counter.alter(a, prior.?, input.options),
            .drop => try counter.remove(a, prior.?.definition),
            .rename => {},
        }
        if (owner_bootstrap) |value| try txn.put(value.key, value.value);
        if (changed_owner or next == null) if (before_owner) |owner| try txn.delete(try sql_sequences.ownerKey(&key_buffer, group, owner, id));
        if (changed_owner) if (after_owner) |owner| try txn.put(try sql_sequences.ownerKey(&key_buffer, group, owner, id), &.{1});
        const encoded = try std.json.Stringify.valueAlloc(a, command, .{});
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(encoded, &hash, .{});
        var removes: [1]system_catalog.Resource = undefined;
        if (next == null) removes[0] = resource.?;
        try self.applySystemCatalogDeltaTxn(a, txn, group, .{ .upserts = upserts[0..if (next != null) @as(usize, 1) else 0], .removes = removes[0..if (next == null) @as(usize, 1) else 0], .next_id = next_id }, meta, hash);
        self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group });
        return result;
    }

    const SqlViewPublication = struct {
        expected_revision: u64,
        target: system_catalog.Target,
        definition: @import("antfly_local_sources").sql_view_definition.Definition,
        replace: bool = false,
        expected: ?SqlViewIdentity = null,
        dry_run: bool = false,
        command_hash: ?[32]u8 = null,
    };

    /// The caller owns the containing catalog transaction and admission
    /// receipt. All semantic rejection precedes the first persistent write.
    fn publishSqlViewTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, request: SqlViewPublication) !SqlViewIdentity {
        try request.target.validate();
        if (request.definition.sources.len > 64 or request.definition.columns.len == 0 or request.definition.columns.len > 1024)
            return error.InvalidSqlViewRecord;
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_view_domains_version);
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const meta = try system_catalog_storage.readMeta(a, txn, group);
        if (meta.revision != request.expected_revision) return error.CatalogGenerationChanged;
        if (meta.revision == std.math.maxInt(u64)) return error.CatalogRevisionExhausted;
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group, .meta = meta };
        const namespace = try view.namespaceFor(request.target.database, request.target.namespace);
        var registry = try RelationRegistry(docstore.DocStore.Txn).init(a, txn, group);
        const live = registry.live orelse return error.CatalogPublicationProofPending;
        if (!try relationWriterEnabledTxn(txn, group)) return error.InvalidCatalogRecord;
        if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
        if (!live.root.epoch.eql(try relationSourceEpochTxn(txn, group))) return error.CatalogGenerationChanged;
        if (try registry.getEntry(.{ .namespace_id = namespace.id, .name = request.target.table }) != null or
            try view.lookup(.table, namespace.id, request.target.table) != null or
            try view.lookup(.sequence, namespace.id, request.target.table) != null) return error.CatalogAlreadyExists;
        var previous_resource = try system_catalog_storage.find(a, txn, group, .view, namespace.id, request.target.table);
        defer if (previous_resource) |*value| value.deinit();
        var previous_record: ?std.json.Parsed(sql_views.Record) = null;
        defer if (previous_record) |*value| value.deinit();
        if (previous_resource) |resource| {
            if (!request.replace) return error.CatalogAlreadyExists;
            previous_record = try sql_views.Record.decode(a, resource.value.source_json);
            if (previous_record.?.value.id != resource.value.id) return error.InvalidSqlViewRecord;
            const expected = request.expected orelse return error.CatalogGenerationChanged;
            if (expected.id != resource.value.id or expected.generation != previous_record.?.value.generation) return error.CatalogGenerationChanged;
        } else if (request.expected != null) return error.CatalogGenerationChanged;
        const id = if (previous_resource) |resource| resource.value.id else meta.next_id;
        const next_id = if (previous_resource != null) meta.next_id else std.math.add(u64, meta.next_id, 1) catch return error.CatalogIdExhausted;
        const definition = request.definition;
        const columns = try a.alloc([]const u64, definition.sources.len);
        var bootstrap: std.ArrayList(struct { key: []const u8, value: []const u8 }) = .empty;
        for (definition.sources, columns) |source, *bound| switch (source.kind) {
            .table => {
                var table_buf: [160]u8 = undefined;
                const raw_table = try txn.get(try tableKeyForGroup(&table_buf, group, source.table_id));
                const table = try decodeTableRecord(a, raw_table);
                if (try self.fkTableLockKindTxn(txn, group, table.table_id) == .sql_drop) return error.TableTransitionActive;
                if (table.table_id != source.table_id or !std.mem.eql(u8, table.name, source.physical_name)) return error.CatalogGenerationChanged;
                if (try restoreStagingLocksTableTxn(txn, group, table.table_id)) return error.CatalogGenerationChanged;
                // Logical source scope is admitted in this same catalog cut.
                if (try view.byId(.table, source.table_id)) |binding| {
                    const source_namespace = try view.namespaceFor(source.database, source.namespace);
                    if (binding.parent_id != source_namespace.id or !std.mem.eql(u8, binding.name, source.name) or
                        !std.mem.eql(u8, binding.storage_name, table.name)) return error.CatalogGenerationChanged;
                } else if (!std.mem.eql(u8, source.database, system_catalog.default_database_name) or
                    !std.mem.eql(u8, source.namespace, system_catalog.default_namespace_name) or
                    !std.mem.eql(u8, source.name, table.name)) return error.CatalogGenerationChanged;
                const key = try column_identities.key(.{ .group = group, .table = table.table_id });
                const prior = try stagingGet(txn, &key);
                const bytes = if (prior) |value| blk: {
                    try validateColumnIdentityRecord(a, .{ .group = group, .table = table.table_id }, value, raw_table);
                    break :blk value;
                } else try columnIdentityValue(a, table, null, &.{});
                var state = try column_identities.State.decode(a, bytes);
                defer state.deinit();
                bound.* = try sql_views.bindSource(a, source, state.value);
                if (prior == null) try bootstrap.append(a, .{ .key = try a.dupe(u8, &key), .value = bytes });
            },
            .view => {
                var resource = (try system_catalog_storage.getById(a, txn, group, .view, source.table_id)) orelse return error.CatalogGenerationChanged;
                defer resource.deinit();
                const source_namespace = try view.namespaceFor(source.database, source.namespace);
                if (resource.value.parent_id != source_namespace.id or !std.mem.eql(u8, resource.value.name, source.name)) return error.CatalogGenerationChanged;
                var record = try sql_views.Record.decode(a, resource.value.source_json);
                defer record.deinit();
                if (record.value.id != resource.value.id) return error.InvalidSqlViewRecord;
                bound.* = try sql_views.bindSource(a, source, record.value.attributes);
            },
        };
        var prepared = try sql_views.prepare(a, id, definition, if (previous_record) |record| record.value else null, columns);
        defer prepared.deinit();
        const bytes = try prepared.value.encode(a);
        const dependencies = try prepared.value.dependencies(a);
        const previous_dependencies = if (previous_record) |record| try record.value.dependencies(a) else &.{};
        var key_buf: [160]u8 = undefined;
        // An existing forward record cannot silently heal missing/forged edges.
        for (previous_dependencies) |dependency| {
            const key = try sql_views.dependencyKey(&key_buf, group, dependency, id);
            if (!std.mem.eql(u8, (try stagingGet(txn, key)) orelse return error.InvalidSqlViewRecord, &.{1})) return error.InvalidSqlViewRecord;
        }
        if (request.dry_run) return .{ .id = id, .generation = prepared.value.generation };
        const resource: system_catalog.Resource = .{ .kind = .view, .id = id, .parent_id = namespace.id, .name = request.target.table, .source_json = bytes };
        var upserts = [_]system_catalog.Resource{resource};
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
        if (request.command_hash) |value| hash = value;
        for (previous_dependencies) |dependency| try txn.delete(try sql_views.dependencyKey(&key_buf, group, dependency, id));
        for (bootstrap.items) |item| {
            try txn.put(item.key, item.value);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group, .key = item.key });
        }
        for (dependencies) |dependency| try txn.put(try sql_views.dependencyKey(&key_buf, group, dependency, id), &.{1});
        try self.applySystemCatalogDeltaTxn(a, txn, group, .{ .upserts = &upserts, .removes = &.{}, .next_id = next_id }, meta, hash);
        self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group });
        // The durable bytes own the result; never return the local arena.
        // Callers discover the admitted record through the existing receipt.
        return .{ .id = id, .generation = prepared.value.generation };
    }

    /// Planning and replay use the same semantic checks. Preflight is strictly
    /// read-only, including listeners; replay writes only after the complete
    /// bounded dependency closure and all reverse edges have been verified.
    fn applySqlViewLifecycleTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, command: SystemCatalogCommand, apply: bool) !sql_views.MutationResult {
        const request = command.sql_view orelse return error.InvalidCatalogMutation;
        try request.validate();
        if (command.version != 2 or command.topology != null or command.placement_update != null or
            command.constraint_name_admission != null or command.mutation.kind != .view or
            command.mutation.table_id != 0 or command.mutation.storage_name.len != 0 or
            !std.mem.eql(u8, command.mutation.database, request.target.database) or
            !std.mem.eql(u8, command.mutation.namespace, request.target.namespace) or
            !std.mem.eql(u8, command.mutation.name, request.target.table))
            return error.InvalidCatalogMutation;
        const action: system_catalog.Action = switch (request.operation) {
            .publish => .create,
            .rename => .rename,
            .drop => .drop,
        };
        if (command.mutation.action != action) return error.InvalidCatalogMutation;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        const bytes = try std.json.Stringify.valueAlloc(a, command, .{});
        if (bytes.len > system_catalog.max_command_bytes) return error.CatalogCommandTooLarge;
        var hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bytes, &hash, .{});
        if (request.operation == .publish) {
            const input = request.operation.publish;
            const identity = try self.publishSqlViewTxn(txn, group, .{
                .expected_revision = command.expected_revision,
                .target = request.target,
                .definition = input.definition,
                .replace = input.replace,
                .expected = input.expected,
                .dry_run = !apply,
                .command_hash = hash,
            });
            return .{ .revision = command.expected_revision + 1, .identity = identity };
        }
        _ = try self.standbyRelationActivationTxn(txn, group, topology_protocol.sql_view_domains_version);
        const meta = try system_catalog_storage.readMeta(a, txn, group);
        if (meta.revision != command.expected_revision) return error.CatalogGenerationChanged;
        if (meta.revision == std.math.maxInt(u64)) return error.CatalogRevisionExhausted;
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = txn, .group_id = group, .meta = meta };
        const namespace = try view.namespaceFor(request.target.database, request.target.namespace);
        const resource = (try system_catalog_storage.find(a, txn, group, .view, namespace.id, request.target.table)) orelse {
            if (request.operation == .drop and request.operation.drop.if_exists and request.operation.drop.expected == null)
                return .{ .revision = meta.revision, .identity = null };
            return error.CatalogNotFound;
        };
        var record = try sql_views.Record.decode(a, resource.value.source_json);
        defer record.deinit();
        if (record.value.id != resource.value.id) return error.InvalidSqlViewRecord;
        const identity: sql_views.Identity = .{ .id = record.value.id, .generation = record.value.generation };
        const expected: ?sql_views.Identity = switch (request.operation) {
            .rename => |input| input.expected,
            .drop => |input| input.expected,
            .publish => unreachable,
        };
        if (expected) |value| {
            if (value.id != identity.id or value.generation != identity.generation) return error.CatalogGenerationChanged;
        } else return error.CatalogGenerationChanged;
        if (request.operation == .rename) {
            const name = request.operation.rename.name;
            var registry = try RelationRegistry(docstore.DocStore.Txn).init(a, txn, group);
            const live = registry.live orelse return error.CatalogPublicationProofPending;
            if (!try relationWriterEnabledTxn(txn, group)) return error.InvalidCatalogRecord;
            if (live.root.coverage != .constraint_names) return error.CatalogOccupancyNotReady;
            if (!live.root.epoch.eql(try relationSourceEpochTxn(txn, group))) return error.CatalogGenerationChanged;
            if (try registry.getEntry(.{ .namespace_id = namespace.id, .name = name }) != null or
                try view.lookup(.table, namespace.id, name) != null or
                try view.lookup(.view, namespace.id, name) != null or
                try view.lookup(.sequence, namespace.id, name) != null) return error.CatalogAlreadyExists;
            var renamed = resource.value;
            renamed.name = name;
            if (apply) {
                // applyDelta removes an old name before installing its new
                // spelling; dependencies retain durable IDs unchanged.
                var removes = [_]system_catalog.Resource{resource.value};
                var upserts = [_]system_catalog.Resource{renamed};
                try self.applySystemCatalogDeltaTxn(a, txn, group, .{ .upserts = &upserts, .removes = &removes, .next_id = meta.next_id }, meta, hash);
                self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group });
            }
            return .{ .revision = meta.revision + 1, .identity = identity };
        }
        var removes: std.ArrayList(system_catalog.Resource) = .empty;
        try removes.append(a, resource.value);
        var seen: std.AutoHashMapUnmanaged(u64, void) = .empty;
        try seen.put(a, identity.id, {});
        var edges: std.ArrayList([]const u8) = .empty;
        var edge_set: std.StringHashMapUnmanaged(void) = .empty;
        var incoming: std.ArrayList([]const u8) = .empty;
        var size: usize = resource.value.source_json.len;
        if (size > sql_views.max_bytes) return error.SqlProgramLimitExceeded;
        var position: usize = 0;
        while (position < removes.items.len) : (position += 1) {
            const current = removes.items[position];
            var current_record = try sql_views.Record.decode(a, current.source_json);
            defer current_record.deinit();
            if (current_record.value.id != current.id) return error.InvalidSqlViewRecord;
            var key_buf: [160]u8 = undefined;
            for (try current_record.value.dependencies(a)) |dependency| {
                const key = try sql_views.dependencyKey(&key_buf, group, dependency, current.id);
                if (!std.mem.eql(u8, (try stagingGet(txn, key)) orelse return error.InvalidSqlViewRecord, &.{1})) return error.InvalidSqlViewRecord;
                if (edges.items.len >= 16384) return error.SqlProgramLimitExceeded;
                try edges.append(a, try a.dupe(u8, key));
                try edge_set.put(a, edges.items[edges.items.len - 1], {});
            }
            const prefix = try sql_views.dependencyPrefix(&key_buf, group, .view, current.id, null);
            var cursor = try txn.openCursor();
            defer cursor.close();
            var row = try cursor.seekAtOrAfter(prefix);
            while (row) |item| : (row = try cursor.next()) {
                if (!std.mem.startsWith(u8, item.key, prefix)) break;
                const edge = (try sql_views.dependencyFromKey(item.key, group)) orelse return error.InvalidSqlViewRecord;
                if (!std.mem.eql(u8, item.value, &.{1})) return error.InvalidSqlViewRecord;
                if (!request.operation.drop.cascade) return error.SqlDependentObjectsExist;
                if (incoming.items.len >= 16384) return error.SqlProgramLimitExceeded;
                try incoming.append(a, try a.dupe(u8, item.key));
                if (seen.contains(edge.view)) continue;
                if (seen.count() >= 256) return error.SqlProgramLimitExceeded;
                const child = (try system_catalog_storage.getById(a, txn, group, .view, edge.view)) orelse return error.InvalidSqlViewRecord;
                // Charge queued records immediately, not when visited: a
                // wide dependency frontier must not retain hundreds of large
                // definitions before noticing that its byte budget is full.
                size = std.math.add(usize, size, child.value.source_json.len) catch return error.SqlProgramLimitExceeded;
                if (size > sql_views.max_bytes) return error.SqlProgramLimitExceeded;
                try seen.put(a, edge.view, {});
                try removes.append(a, child.value);
            }
        }
        // A forged incoming edge must not expand the drop set or survive as
        // an orphan after publication. Every reverse edge must be justified
        // by a verified forward definition in this same closure.
        for (incoming.items) |key| if (!edge_set.contains(key)) return error.InvalidSqlViewRecord;
        if (apply) {
            for (edges.items) |key| try txn.delete(key);
            try self.applySystemCatalogDeltaTxn(a, txn, group, .{ .upserts = &.{}, .removes = removes.items, .next_id = meta.next_id }, meta, hash);
            self.notifyProjectionListeners(.{ .kind = .table, .metadata_group_id = group });
        }
        return .{ .revision = meta.revision + 1, .identity = identity, .removed = removes.items.len };
    }

    /// Only a containing catalog publication may bootstrap IDs. Ordinary
    /// schema writes maintain already registered sources, never allocate an
    /// identity registry merely because a query or status read touched them.
    fn initializeColumnIdentitiesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !void {
        var buf: [160]u8 = undefined;
        const bytes = try txn.get(try tableKeyForGroup(&buf, group_id, record.table_id));
        const actual = try decodeTableRecord(self.alloc, bytes);
        defer metadata_table_manager.freeTable(self.alloc, actual);
        if (actual.table_id != record.table_id or !std.mem.eql(u8, actual.name, record.name) or !std.mem.eql(u8, actual.schema_json, record.schema_json)) return error.ColumnIdentityEpochChanged;
        const registry: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = txn, .group_id = group_id };
        var previous = try registry.load(self.alloc, record.table_id);
        defer if (previous) |*loaded| loaded.deinit();
        const value = try columnIdentityValue(self.alloc, record, if (previous) |loaded| loaded.value else null, &.{});
        defer self.alloc.free(value);
        const column_key = try column_identities.key(.{ .group = group_id, .table = record.table_id });
        if (try stagingGet(txn, &column_key)) |old| if (std.mem.eql(u8, old, value)) return;
        try txn.put(&column_key, value);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = &column_key });
    }

    /// Scan only this owner's reverse edges, retaining at most one small page
    /// at a time. Cursors are closed before writes. Every failure aborts the
    /// surrounding metadata transaction; no cleanup transaction is published.
    fn retireOwnedSequencesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, table: u64, successor: ?column_identities.State) !void {
        var prefix_buffer: [192]u8 = undefined;
        const prefix = try sql_sequences.ownerPrefix(&prefix_buffer, group, table);
        var position_key: [192]u8 = undefined;
        var resume_len: usize = 0;
        var removed = false;
        const registry: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = txn, .group_id = group };
        // Most schema publications have no owned sequences. Do not decode
        // their complete attribute registry merely to prove an empty prefix.
        var prior: ?std.json.Parsed(column_identities.State) = null;
        defer if (prior) |*loaded| loaded.deinit();
        const Retirement = struct { resource: system_catalog.Resource, definition: sql_sequences.sequence.Definition, edge: []const u8 };
        while (true) {
            var arena = std.heap.ArenaAllocator.init(self.alloc);
            defer arena.deinit();
            const a = arena.allocator();
            var page: std.ArrayList(Retirement) = .empty;
            var scanned: usize = 0;
            var complete = true;
            {
                var cursor = try txn.openCursor();
                defer cursor.close();
                var row = try cursor.seekAtOrAfter(if (resume_len == 0) prefix else position_key[0..resume_len]);
                if (row) |item| if (resume_len != 0 and std.mem.eql(u8, item.key, position_key[0..resume_len])) {
                    row = try cursor.next();
                };
                while (row) |item| : (row = try cursor.next()) {
                    if (!std.mem.startsWith(u8, item.key, prefix)) break;
                    const edge = try sql_sequences.ownershipFromKey(item.key, group, table);
                    if (prior == null) prior = (try registry.load(self.alloc, table)) orelse return error.InvalidSequenceState;
                    if (!std.mem.eql(u8, item.value, &.{1}) or prior == null or prior.?.value.columnById(edge.owner.column_id) == null)
                        return error.InvalidSequenceState;
                    var resource = (try system_catalog_storage.getById(a, txn, group, .sequence, edge.sequence_id)) orelse return error.InvalidSequenceState;
                    defer resource.deinit();
                    const descriptor = sql_sequences.sequence.Descriptor.decode(a, resource.value.source_json) catch |err| switch (err) {
                        error.OutOfMemory => return err,
                        else => return error.InvalidSequenceState,
                    };
                    const definition = try descriptor.definition();
                    if (descriptor.id != edge.sequence_id or !std.meta.eql(definition.owned_by, @as(?sql_sequences.sequence.OwnedBy, edge.owner))) return error.InvalidSequenceState;
                    const retain = if (successor) |state| state.columnById(edge.owner.column_id) != null else false;
                    if (!retain) try page.append(a, .{ .resource = try system_catalog.cloneResource(a, resource.value), .definition = definition, .edge = try a.dupe(u8, item.key) });
                    @memcpy(position_key[0..item.key.len], item.key);
                    resume_len = item.key.len;
                    scanned += 1;
                    if (scanned == 128) {
                        complete = false;
                        break;
                    }
                }
            }
            for (page.items) |retirement| {
                const counter: sql_sequences.journal.Store(docstore.DocStore.Txn) = .{ .txn = txn, .key = .{ .group = group, .sequence_id = retirement.resource.id } };
                try counter.remove(a, retirement.definition);
                try system_catalog_storage.removeResource(a, txn, group, retirement.resource);
                try txn.delete(retirement.edge);
                removed = true;
            }
            if (complete) break;
        }
        if (removed) {
            const meta = try system_catalog_storage.readMeta(self.alloc, txn, group);
            // Ownership retirement changes logical catalog state, not the
            // physical relation source. Its caller publishes table changes.
            try system_catalog_storage.applyDelta(self.alloc, txn, group, .{ .upserts = &.{}, .removes = &.{}, .next_id = meta.next_id }, meta, @splat(0));
        }
    }

    fn deleteColumnIdentitiesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !void {
        if (try sql_views.firstDependent(txn, group_id, .table, table_id, null) != null)
            return error.SqlDependentObjectsExist;
        try self.retireOwnedSequencesTxn(txn, group_id, table_id, null);
        const column_key = try column_identities.key(.{ .group = group_id, .table = table_id });
        if (try stagingGet(txn, &column_key) == null) return;
        try txn.delete(&column_key);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = &column_key });
    }

    fn prepareTrackedColumnIdentitiesTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.TableRecord) !?[]u8 {
        const registry: column_identities.Store(docstore.DocStore.Txn) = .{ .txn = txn, .group_id = group_id };
        var previous = (try registry.load(self.alloc, record.table_id)) orelse return null;
        defer previous.deinit();
        const column_key = try column_identities.key(.{ .group = group_id, .table = record.table_id });
        var table_buf: [160]u8 = undefined;
        const old_table = try txn.get(try tableKeyForGroup(&table_buf, group_id, record.table_id));
        validateColumnIdentityRecord(self.alloc, .{ .group = group_id, .table = record.table_id }, try txn.get(&column_key), old_table) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidColumnIdentityState,
        };
        // Stored-state corruption above is fatal. A proposed incompatible or
        // malformed successor is instead normal catalog nonadmission; a
        // committed stale command must not wedge ordered Raft apply.
        const value = columnIdentityValue(self.alloc, record, previous.value, &.{}) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.ColumnIdentityDefinitionRejected,
        };
        errdefer self.alloc.free(value);
        if (std.mem.eql(u8, try txn.get(&column_key), value)) {
            self.alloc.free(value);
            return null;
        }
        var successor = try column_identities.State.decode(self.alloc, value);
        defer successor.deinit();
        for (previous.value.columns) |column| {
            if (successor.value.columnById(column.id)) |next| if (std.mem.eql(u8, &column.signature, &next.signature)) continue;
            if (try sql_views.firstDependent(txn, group_id, .table, record.table_id, column.id)) |dependent| {
                try self.verifySqlViewDependencyTxn(txn, group_id, record.table_id, column.id, dependent, previous.value);
                return error.ColumnIdentityDefinitionRejected;
            }
        }
        return value;
    }

    fn verifySqlViewDependencyTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group: u64, table: u64, column: u64, dependent: u64, state: column_identities.State) !void {
        var resource = (try system_catalog_storage.getById(self.alloc, txn, group, .view, dependent)) orelse return error.InvalidSqlViewRecord;
        defer resource.deinit();
        var record = try sql_views.Record.decode(self.alloc, resource.value.source_json);
        defer record.deinit();
        if (record.value.id != dependent) return error.InvalidSqlViewRecord;
        for (record.value.definition.sources, record.value.source_columns, 0..) |source, columns, index| {
            if (source.kind != .table or source.table_id != table or (column != 0 and std.mem.indexOfScalar(u64, columns, column) == null)) continue;
            try record.value.requireSource(index, state, false);
            return;
        }
        return error.InvalidSqlViewRecord;
    }

    fn loadTableTransitionFenceTxn(
        _: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
    ) !TableTransitionFence {
        var key_buf: [192]u8 = undefined;
        const key = try tableTransitionFenceKeyForGroup(&key_buf, group_id, table_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return .{},
            else => return err,
        };
        return try decodeTableTransitionFence(encoded);
    }

    fn updateTableTransitionFenceTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
        was_active: bool,
        is_active: bool,
    ) !void {
        if (table_id == 0 or was_active == is_active) return;
        var fence = try self.loadTableTransitionFenceTxn(txn, group_id, table_id);
        if (fence.generation == std.math.maxInt(u64))
            return error.TableTransitionGenerationExhausted;
        if (is_active) {
            if (fence.active_count == std.math.maxInt(u32))
                return error.TableTransitionCountExhausted;
            fence.active_count += 1;
        } else {
            if (fence.active_count == 0)
                return error.InvalidTableTransitionFence;
            fence.active_count -= 1;
        }
        fence.generation += 1;

        var key_buf: [192]u8 = undefined;
        const key = try tableTransitionFenceKeyForGroup(&key_buf, group_id, table_id);
        var encoded: [table_transition_fence_encoded_len]u8 = undefined;
        encodeTableTransitionFence(&encoded, fence);
        try txn.put(key, &encoded);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
    }

    fn advanceTableTransitionGenerationTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
    ) !void {
        if (table_id == 0) return;
        var fence = try self.loadTableTransitionFenceTxn(txn, group_id, table_id);
        if (fence.generation == std.math.maxInt(u64))
            return error.TableTransitionGenerationExhausted;
        fence.generation += 1;

        var key_buf: [192]u8 = undefined;
        const key = try tableTransitionFenceKeyForGroup(&key_buf, group_id, table_id);
        var encoded: [table_transition_fence_encoded_len]u8 = undefined;
        encodeTableTransitionFence(&encoded, fence);
        try txn.put(key, &encoded);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
    }

    fn advanceTableTransitionGenerationWithRangeChangesTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        table_id: u64,
        added_range_group_ids: []const u64,
        removed_range_group_ids: []const u64,
    ) !void {
        if (table_id == 0) return;
        var fence = try self.loadTableTransitionFenceTxn(txn, group_id, table_id);
        if (fence.generation == std.math.maxInt(u64))
            return error.TableTransitionGenerationExhausted;
        for (added_range_group_ids) |range_group_id|
            try fence.range_membership.add(range_group_id);
        for (removed_range_group_ids) |range_group_id|
            try fence.range_membership.remove(range_group_id);
        fence.generation += 1;

        var key_buf: [192]u8 = undefined;
        const key = try tableTransitionFenceKeyForGroup(&key_buf, group_id, table_id);
        var encoded: [table_transition_fence_encoded_len]u8 = undefined;
        encodeTableTransitionFence(&encoded, fence);
        try txn.put(key, &encoded);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
    }

    fn applySplitTransitionUpsertTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.SplitTransitionRecord,
    ) !void {
        if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, record.table_contract.table_id)) return;
        var key_buf: [160]u8 = undefined;
        const key = try splitTransitionKeyForGroup(&key_buf, group_id, record.transition_id);
        const encoded_existing = txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const encoded = encoded_existing orelse {
            // New splits must use admit_split_transition, which atomically
            // validates the source epoch, range identity, and table contract.
            return;
        };
        var existing_active = false;
        const existing = try decodeSplitTransitionRecord(self.alloc, encoded);
        defer metadata_table_manager.freeSplitTransitionRecord(self.alloc, existing);
        if (!splitTransitionUpdateAllowed(existing, record)) return;
        existing_active = splitTransitionActive(existing);

        const value = try encodeSplitTransitionRecord(self.alloc, record);
        defer self.alloc.free(value);
        try txn.put(key, value);
        try self.updateTableTransitionFenceTxn(
            txn,
            group_id,
            record.table_contract.table_id,
            existing_active,
            splitTransitionActive(record),
        );
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .split_transition,
            .metadata_group_id = group_id,
            .group_id = record.source_group_id,
        });
        self.notifyCommittedTransition(.{ .upsert_split = record });
    }

    fn applySplitTransitionRemovalTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        transition_id: u64,
    ) !void {
        var key_buf: [160]u8 = undefined;
        const key = try splitTransitionKeyForGroup(&key_buf, group_id, transition_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        const existing = try decodeSplitTransitionRecord(self.alloc, encoded);
        defer metadata_table_manager.freeSplitTransitionRecord(self.alloc, existing);
        if (!transitionPhaseTerminal(existing.phase)) return;

        try txn.delete(key);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .split_transition,
            .metadata_group_id = group_id,
        });
        self.notifyCommittedTransition(.{ .remove_split = transition_id });
    }

    fn applyMergeTransitionUpsertTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.MergeTransitionRecord,
    ) !void {
        return self.applyMergeTransitionUpsertAuthorizedTxn(txn, group_id, record, false);
    }

    fn applyOnlineMergeAdmissionTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, admission: OnlineMergeAdmission) !void {
        var key_buf: [160]u8 = undefined;
        const key = try mergeTransitionKeyForGroup(&key_buf, group_id, admission.next.scope.fence.transition_id);
        const bytes = (try stagingGet(txn, key)) orelse return;
        if (!std.mem.eql(u8, &OnlineMergeAdmission.digestEncoded(bytes), &admission.expected_record_digest)) return;
        const current = try decodeMergeTransitionRecord(self.alloc, bytes);
        defer metadata_table_manager.freeMergeTransitionRecord(self.alloc, current);
        if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, current.table_contract.table_id)) return;
        if (current.online != null or current.phase != .prepare or current.rollback_reason != null) return;
        // The catalog flag authorizes rebuilding source identities in the
        // receiver namespace. Online row preparation performs that rebuild;
        // it does not run the legacy receiver identity-reassignment command.
        current.table_contract.validateForMerge(current.allow_doc_identity_reassignment) catch return;
        var replacement = current;
        replacement.online = admission.next;
        admission.next.validateRecord(replacement) catch return;
        var lease_buf: [160]u8 = undefined;
        const lease_bytes = (try stagingGet(txn, try reconcileLeaseKeyForGroup(&lease_buf, group_id))) orelse return;
        var lease_pos: usize = 0;
        const lease = try readReconcileLeaseRecord(lease_bytes, &lease_pos);
        if (lease_pos != lease_bytes.len) return error.InvalidMetadataTransitionEncoding;
        if (!std.meta.eql(lease, admission.lease)) return;
        if (!try self.mergeTransitionAdmissionMatchesTxn(txn, group_id, replacement) or
            try backupCohortLocksTableTxn(txn, group_id, current.table_contract.table_id) or
            try restoreStagingLocksTableTxn(txn, group_id, current.table_contract.table_id)) return;
        // No transition-count change: the ordinary queued record already owns
        // this table's active-transition fence. Publish identity and notify the
        // scheduler in the same transaction, without reopening ordinary upsert.
        const encoded = try encodeMergeTransitionRecord(self.alloc, replacement);
        defer self.alloc.free(encoded);
        try txn.put(key, encoded);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{ .kind = .merge_transition, .metadata_group_id = group_id, .group_id = replacement.receiver_group_id });
        self.notifyCommittedTransition(.{ .upsert_merge = replacement });
    }

    fn applyOnlineMergeUpdateTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, update: OnlineMergeUpdate) anyerror!void {
        var key_buf: [160]u8 = undefined;
        const key = try mergeTransitionKeyForGroup(&key_buf, group_id, update.expected.scope.fence.transition_id);
        const bytes = (try stagingGet(txn, key)) orelse return;
        const current = try decodeMergeTransitionRecord(self.alloc, bytes);
        defer metadata_table_manager.freeMergeTransitionRecord(self.alloc, current);
        if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, current.table_contract.table_id)) return;
        const online = current.online orelse return;
        if (!online.eql(update.expected) or (current.rollback_reason != null) != update.expected_cancel) return;
        var lease_buf: [160]u8 = undefined;
        const lease_bytes = (try stagingGet(txn, try reconcileLeaseKeyForGroup(&lease_buf, group_id))) orelse return;
        var lease_pos: usize = 0;
        const lease = try readReconcileLeaseRecord(lease_bytes, &lease_pos);
        if (lease_pos != lease_bytes.len) return error.InvalidMetadataTransitionEncoding;
        if (!std.meta.eql(lease, update.lease)) return;
        if (!try self.tableMatchesTransitionContractTxn(txn, group_id, current.table_contract)) return;
        var replacement = current;
        replacement.online = update.next;
        if (update.next.phase == .complete) replacement.phase = .finalized;
        if (update.next.phase == .cancelled) replacement.phase = .rolled_back;
        if (!mergeTransitionUpdateAllowed(current, replacement)) return;
        if (update.publish_cutover) {
            if (try backupCohortLocksTableTxn(txn, group_id, current.table_contract.table_id) or try restoreStagingLocksTableTxn(txn, group_id, current.table_contract.table_id)) return;
            var donor_buf: [160]u8 = undefined;
            var receiver_buf: [160]u8 = undefined;
            const donor_bytes = (try stagingGet(txn, try rangeKeyForGroup(&donor_buf, group_id, current.donor_group_id))) orelse return;
            const receiver_bytes = (try stagingGet(txn, try rangeKeyForGroup(&receiver_buf, group_id, current.receiver_group_id))) orelse return;
            const donor = try decodeRangeRecord(self.alloc, donor_bytes);
            defer metadata_table_manager.freeRange(self.alloc, donor);
            const receiver = try decodeRangeRecord(self.alloc, receiver_bytes);
            defer metadata_table_manager.freeRange(self.alloc, receiver);
            if (donor.table_id != current.table_contract.table_id or receiver.table_id != current.table_contract.table_id or !rangesAreAdjacent(donor, receiver) or
                !rangeMatchesTransitionIdentity(donor, current.table_contract.source_identity) or !rangeMatchesTransitionIdentity(receiver, current.table_contract.target_identity)) return;
            var merged = receiver;
            if (std.mem.order(u8, donor.start_key, receiver.start_key) == .lt) merged.start_key = donor.start_key else merged.end_key = donor.end_key;
            const bounds = update.cutover_bounds.?;
            const actual = OnlineMergeCutoverBounds.fromRanges(.{ .start = receiver.start_key, .end = receiver.end_key orelse "" }, .{ .start = merged.start_key, .end = merged.end_key orelse "" });
            if (!std.meta.eql(bounds, actual)) return;
            // Both existing range handlers maintain table/range indexes and
            // generation fences in this SAME transaction as the online CAS.
            try self.applyTransitionCommandTxn(txn, group_id, .{ .upsert_range = merged });
            try self.applyTransitionCommandTxn(txn, group_id, .{ .remove_range = .{ .group_id = donor.group_id } });
        }
        try self.applyMergeTransitionUpsertAuthorizedTxn(txn, group_id, replacement, true);
    }

    fn applyMergeTransitionUpsertAuthorizedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, record: metadata.MergeTransitionRecord, allow_online_change: bool) !void {
        if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, record.table_contract.table_id)) return;
        if (record.online) |online| try online.validateRecord(record);
        var key_buf: [160]u8 = undefined;
        const key = try mergeTransitionKeyForGroup(&key_buf, group_id, record.transition_id);
        const encoded_existing = txn.get(key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var existing_active = false;
        if (!allow_online_change and encoded_existing == null and record.online != null) return;
        if (encoded_existing) |encoded| {
            const existing = try decodeMergeTransitionRecord(self.alloc, encoded);
            defer metadata_table_manager.freeMergeTransitionRecord(self.alloc, existing);
            if (!allow_online_change) if (existing.online) |previous| if (record.online == null or !previous.eql(record.online.?)) return;
            if (!mergeTransitionUpdateAllowed(existing, record)) return;
            existing_active = !transitionPhaseTerminal(existing.phase);
        } else if (!try self.mergeTransitionAdmissionMatchesTxn(
            txn,
            group_id,
            record,
        )) {
            return;
        }

        if (encoded_existing == null and !try self.activateRelationalTopologyProtocolTxn(txn, group_id, record.table_contract)) return;
        const value = try encodeMergeTransitionRecord(self.alloc, record);
        defer self.alloc.free(value);
        try txn.put(key, value);
        try self.updateTableTransitionFenceTxn(
            txn,
            group_id,
            record.table_contract.table_id,
            existing_active,
            !transitionPhaseTerminal(record.phase),
        );
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .merge_transition,
            .metadata_group_id = group_id,
            .group_id = record.receiver_group_id,
        });
        self.notifyCommittedTransition(.{ .upsert_merge = record });
    }

    fn applyMergeTransitionRemovalTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        transition_id: u64,
    ) !void {
        var key_buf: [160]u8 = undefined;
        const key = try mergeTransitionKeyForGroup(&key_buf, group_id, transition_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        const existing = try decodeMergeTransitionRecord(self.alloc, encoded);
        defer metadata_table_manager.freeMergeTransitionRecord(self.alloc, existing);
        if (!transitionPhaseTerminal(existing.phase)) return;

        try txn.delete(key);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .merge_transition,
            .metadata_group_id = group_id,
        });
        self.notifyCommittedTransition(.{ .remove_merge = transition_id });
    }

    /// Atomically reserves the next source-local split epoch and publishes its
    /// transition. Failed compare-and-set preconditions are deterministic
    /// no-ops because a committed Raft command must always remain applicable.
    fn applySplitAdmissionTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        expected_source_epoch: u64,
        record: metadata.SplitTransitionRecord,
    ) !void {
        if (!try self.policyTopologyMutationAllowedTxn(txn, group_id, record.table_contract.table_id)) return;
        const split_key = record.split_key orelse return error.InvalidSplitAdmission;

        var transition_key_buf: [160]u8 = undefined;
        const transition_key = try splitTransitionKeyForGroup(&transition_key_buf, group_id, record.transition_id);
        const existing_transition = txn.get(transition_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (existing_transition) |encoded| {
            const existing = try decodeSplitTransitionRecord(self.alloc, encoded);
            defer metadata_table_manager.freeSplitTransitionRecord(self.alloc, existing);
            if (splitTransitionActive(existing)) return;
        }

        var source_key_buf: [160]u8 = undefined;
        const source_key = try rangeKeyForGroup(&source_key_buf, group_id, record.source_group_id);
        const encoded_source = txn.get(source_key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        var source = try decodeRangeRecord(self.alloc, encoded_source);
        defer metadata_table_manager.freeRange(self.alloc, source);
        if (source.split_attempt_epoch != expected_source_epoch or
            expected_source_epoch == std.math.maxInt(u64) or
            record.attempt_epoch != expected_source_epoch + 1 or
            source.table_id != record.table_contract.table_id or
            !rangeMatchesTransitionIdentity(
                source,
                record.table_contract.source_identity,
            ) or
            !optionalBytesEqual(source.end_key, record.source_range_end) or
            !keyStrictlyInsideRange(split_key, source.start_key, source.end_key))
        {
            return;
        }
        if (!try self.tableMatchesTransitionContractTxn(
            txn,
            group_id,
            record.table_contract,
        )) return;

        var destination_key_buf: [160]u8 = undefined;
        const destination_key = try rangeKeyForGroup(&destination_key_buf, group_id, record.destination_group_id);
        if (txn.get(destination_key)) |_| {
            return;
        } else |err| switch (err) {
            error.NotFound => {},
            else => return err,
        }

        var prefix_buf: [128]u8 = undefined;
        const prefix = try splitTransitionPrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |kv| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            const existing = try decodeSplitTransitionRecord(self.alloc, kv.value);
            defer metadata_table_manager.freeSplitTransitionRecord(self.alloc, existing);
            if (splitTransitionActive(existing) and existing.source_group_id == record.source_group_id) return;
        }

        if (!try self.activateRelationalTopologyProtocolTxn(txn, group_id, record.table_contract)) return;
        source.split_attempt_epoch = record.attempt_epoch;
        const source_value = try encodeRangeRecord(self.alloc, source);
        defer self.alloc.free(source_value);
        const transition_value = try encodeSplitTransitionRecord(self.alloc, record);
        defer self.alloc.free(transition_value);
        try txn.put(source_key, source_value);
        try txn.put(transition_key, transition_value);
        try self.updateTableTransitionFenceTxn(
            txn,
            group_id,
            record.table_contract.table_id,
            false,
            splitTransitionActive(record),
        );

        const table_name = try self.lookupTableNameTxn(txn, group_id, source.table_id);
        defer if (table_name) |name| self.alloc.free(name);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = source_key });
        self.notifyProjectionListeners(.{
            .kind = .range,
            .metadata_group_id = group_id,
            .table_name = table_name,
            .table_id = source.table_id,
            .group_id = source.group_id,
        });
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = transition_key });
        self.notifyProjectionListeners(.{
            .kind = .split_transition,
            .metadata_group_id = group_id,
            .group_id = record.source_group_id,
        });
        self.notifyCommittedTransition(.{ .upsert_split = record });
    }

    fn tableMatchesTransitionContractTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        contract: metadata.TransitionTableContract,
    ) !bool {
        if (try backupCohortLocksTableTxn(txn, group_id, contract.table_id) or try restoreStagingLocksTableTxn(txn, group_id, contract.table_id)) return false;
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, contract.table_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        const table = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, table);
        if (table.relational_retirement_json.len != 0) return false;
        var coordinated_schema = false;
        for ([_][]const u8{ table.schema_json, table.read_schema_json }) |schema| {
            var declarations = try RelationalDeclarations.parse(self.alloc, schema);
            defer declarations.deinit();
            if (declarations.value.coordinated()) {
                coordinated_schema = true;
                if (contract.integrity_protocol != .distributed_quiescent_v1 or table.read_schema_json.len != 0) return false;
                if (!try self.relationalTopologyStoresCapableTxn(txn, group_id)) return false;
            }
        }
        if (!coordinated_schema and contract.integrity_protocol != .none) return false;
        return table.table_id == contract.table_id and
            std.mem.eql(u8, table.name, contract.table_name) and
            std.mem.eql(u8, table.schema_json, contract.schema_json) and
            std.mem.eql(u8, table.read_schema_json, contract.read_schema_json) and
            std.mem.eql(u8, table.indexes_json, contract.indexes_json);
    }

    fn relationalTopologyStoresCapableTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64) !bool {
        var prefix_buf: [128]u8 = undefined;
        const prefix = try storePrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var found = false;
        var count: usize = 0;
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |kv| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            count += 1;
            if (count > 4096) return false;
            // Capability admission needs only the compact durable header,
            // never the separately paged group/runtime report payloads.
            const record = try decodeStoredHeader(self.alloc, kv.value);
            defer metadata_table_manager.freeStore(self.alloc, record);
            if (!metadata_table_manager.storeServesTableData(record.role)) continue;
            found = true;
            if (record.reporter_incarnation == 0 or record.relational_topology_protocol_version != metadata_table_manager.relational_topology_protocol_version) return false;
        }
        return found;
    }

    fn activateRelationalTopologyProtocolTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, contract: metadata.TransitionTableContract) !bool {
        if (contract.integrity_protocol == .none) return true;
        if (!try self.relationalTopologyStoresCapableTxn(txn, group_id)) return false;
        var key_buf: [160]u8 = undefined;
        const key = try metadataIncarnationKeyForGroup(&key_buf, group_id);
        const raw = txn.get(key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        var incarnation = try decodeMetadataIncarnationRecord(raw);
        if (incarnation.relational_topology_protocol_activated_version == metadata_table_manager.relational_topology_protocol_version) return true;
        incarnation.relational_topology_protocol_activated_version = metadata_table_manager.relational_topology_protocol_version;
        try writeMetadataIncarnationRecordTxn(txn, group_id, incarnation);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{ .kind = .metadata_incarnation, .metadata_group_id = group_id });
        return true;
    }

    /// Publication must first validate its mutation/decoder admission, then
    /// raise this floor in that SAME transaction before installing the schema.
    /// This is not a standalone activation producer or a data-owner ACK.
    fn raiseSchemaReaderFloorTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, requirement: @import("antfly_local_sources").storage_schema.ReaderRequirements) !bool {
        var key_buf: [160]u8 = undefined;
        const key = try metadataIncarnationKeyForGroup(&key_buf, group_id);
        const raw = txn.get(key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        var incarnation = try decodeMetadataIncarnationRecord(raw);
        const next = try incarnation.schema_reader_floor.include(requirement);
        // Registration and every durable status replacement enforce an active
        // floor. Re-admitting an already covered layout therefore needs no
        // store inventory scan or allocation.
        if (incarnation.schema_reader_floor.covers(requirement)) return true;
        var activation_buf: [160]u8 = undefined;
        const activation_bytes = (try stagingGet(txn, try topologyActivationKeyForGroup(&activation_buf, group_id))) orelse return false;
        if (!try schemaReaderDecoderActivationValid(self.alloc, activation_bytes, incarnation.incarnation)) return false;
        var prefix_buf: [128]u8 = undefined;
        const prefix = try storePrefixForGroup(&prefix_buf, group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(prefix);
        var count: usize = 0;
        var found = false;
        while (entry) |kv| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            count += 1;
            if (count > 4096) return false;
            const record = try decodeStoredHeader(self.alloc, kv.value);
            defer metadata_table_manager.freeStore(self.alloc, record);
            if (!metadata_table_manager.storeServesTableData(record.role)) continue;
            found = true;
            if (!next.admits(record.schema_reader, record.reporter_incarnation)) return false;
        }
        if (!found) return false;
        incarnation.schema_reader_floor = next;
        try writeMetadataIncarnationRecordTxn(txn, group_id, incarnation);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        self.notifyProjectionListeners(.{ .kind = .metadata_incarnation, .metadata_group_id = group_id });
        return true;
    }

    fn mergeTransitionAdmissionMatchesTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.MergeTransitionRecord,
    ) !bool {
        if (record.online) |online| {
            online.validateRecord(record) catch return false;
            if (online.phase != .admit or online.revision != 1 or online.certificate != null) return false;
        }
        if (record.phase != .prepare or
            record.donor_group_id == record.receiver_group_id)
            return false;
        if (!try self.tableMatchesTransitionContractTxn(
            txn,
            group_id,
            record.table_contract,
        )) return false;

        var donor_key_buf: [160]u8 = undefined;
        const donor_key = try rangeKeyForGroup(
            &donor_key_buf,
            group_id,
            record.donor_group_id,
        );
        const encoded_donor = txn.get(donor_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        const donor = try decodeRangeRecord(self.alloc, encoded_donor);
        defer metadata_table_manager.freeRange(self.alloc, donor);

        var receiver_key_buf: [160]u8 = undefined;
        const receiver_key = try rangeKeyForGroup(
            &receiver_key_buf,
            group_id,
            record.receiver_group_id,
        );
        const encoded_receiver = txn.get(receiver_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        const receiver = try decodeRangeRecord(self.alloc, encoded_receiver);
        defer metadata_table_manager.freeRange(self.alloc, receiver);

        return donor.table_id == record.table_contract.table_id and
            receiver.table_id == record.table_contract.table_id and
            rangesAreAdjacent(donor, receiver) and
            rangeMatchesTransitionIdentity(
                donor,
                record.table_contract.source_identity,
            ) and
            rangeMatchesTransitionIdentity(
                receiver,
                record.table_contract.target_identity,
            );
    }

    fn applyExtensionLifecycleDeltaTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, delta: ExtensionLifecycleDelta) !void {
        for (delta.upsert_extension_members) |member| if (!try self.extensionOwnershipAdditionAllowedTxn(txn, group_id, member)) return;
        if (delta.expected_tables.len != 0) {
            if (delta.expected_tables.len != delta.upsert_tables.len) return;
            for (delta.upsert_tables) |replacement| {
                const expected = for (delta.expected_tables) |candidate| {
                    if (candidate.table_id == replacement.table_id) break candidate;
                } else return;
                var key_buf: [160]u8 = undefined;
                const key = try tableKeyForGroup(&key_buf, group_id, replacement.table_id);
                const encoded = txn.get(key) catch |err| switch (err) {
                    error.NotFound => return,
                    else => return err,
                };
                const current = try decodeTableRecord(self.alloc, encoded);
                defer metadata_table_manager.freeTable(self.alloc, current);
                const current_fingerprint = metadata_table_manager.tableDefinitionFingerprint(current);
                if (!std.mem.eql(u8, &current_fingerprint, &expected.definition_fingerprint)) return;
            }
        }
        // Extension lifecycle commands are atomic. Preflight every structural
        // table write before touching any extension row so an active range
        // transition rejects the whole delta rather than publishing half of it.
        for (delta.upsert_tables) |record| {
            if (record.relational_retirement_json.len != 0) return;
            if (!try self.relationalParentsExistTxn(txn, group_id, record)) return;
            var key_buf: [160]u8 = undefined;
            const key = try tableKeyForGroup(&key_buf, group_id, record.table_id);
            const encoded_existing = txn.get(key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (encoded_existing) |encoded| {
                const existing = try decodeTableRecord(self.alloc, encoded);
                defer metadata_table_manager.freeTable(self.alloc, existing);
                if (metadata_table_manager.tableDefinitionsEqual(existing, record)) continue;
                if (existing.relational_retirement_json.len != 0) return;
                if (!std.mem.eql(u8, existing.name, record.name) and
                    try self.relationalDropBlockedTxn(txn, group_id, existing)) return;
                if (!try self.relationalDefinitionsRetainedForMutationTxn(txn, group_id, existing, record)) return;
            }
            if ((try self.loadTableTransitionFenceTxn(txn, group_id, record.table_id)).active()) return;
        }
        var prepared_tables: std.ArrayList(PreparedTableRecordWrite) = .empty;
        defer {
            for (prepared_tables.items) |*prepared| prepared.deinit(self.alloc);
            prepared_tables.deinit(self.alloc);
        }
        var unique_tables: std.AutoHashMapUnmanaged(u64, void) = .empty;
        defer unique_tables.deinit(self.alloc);
        for (delta.upsert_tables) |record| {
            if ((try unique_tables.getOrPut(self.alloc, record.table_id)).found_existing) return;
            switch (try self.prepareTableUpsertTxn(txn, group_id, record)) {
                .rejected => return,
                .unchanged => {},
                .write => |value| {
                    var prepared = value;
                    errdefer prepared.deinit(self.alloc);
                    try prepared_tables.append(self.alloc, prepared);
                },
            }
        }
        for (prepared_tables.items) |prepared| {
            var key_buf: [160]u8 = undefined;
            try self.writePreparedTableRecordTxn(txn, group_id, try tableKeyForGroup(&key_buf, group_id, prepared.identity.table_id), prepared);
        }
        for (delta.remove_extension_dependencies) |record| {
            var key_buf: [320]u8 = undefined;
            const key = try extensionDependencyKeyForGroup(&key_buf, group_id, record.extension_name, record.required_extension_name, record.package_name);
            txn.delete(key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
        for (delta.remove_extension_members) |record| {
            var key_buf: [256]u8 = undefined;
            const key = try extensionMemberKeyForGroup(&key_buf, group_id, record.extension_name, record.object_kind, record.object_name);
            const encoded_existing = txn.get(key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (encoded_existing) |encoded| {
                var existing = try decodeExtensionMemberRecord(self.alloc, encoded);
                defer existing.deinitOwned(self.alloc);
                try self.deleteExtensionTableOwnerIndexTxn(txn, group_id, existing);
            }
            txn.delete(key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
        for (delta.remove_installed_extensions) |name| {
            var key_buf: [192]u8 = undefined;
            const key = try installedExtensionKeyForGroup(&key_buf, group_id, name);
            txn.delete(key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
        for (delta.upsert_installed_extensions) |record| {
            var key_buf: [192]u8 = undefined;
            const key = try installedExtensionKeyForGroup(&key_buf, group_id, record.name);
            const value = try encodeInstalledExtensionRecord(self.alloc, record);
            defer self.alloc.free(value);
            try txn.put(key, value);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
        for (delta.upsert_extension_dependencies) |record| {
            var key_buf: [320]u8 = undefined;
            const key = try extensionDependencyKeyForGroup(&key_buf, group_id, record.extension_name, record.required_extension_name, record.package_name);
            const value = try encodeExtensionDependencyRecord(self.alloc, record);
            defer self.alloc.free(value);
            try txn.put(key, value);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
        for (delta.upsert_extension_members) |record| {
            var key_buf: [256]u8 = undefined;
            const key = try extensionMemberKeyForGroup(&key_buf, group_id, record.extension_name, record.object_kind, record.object_name);
            const encoded_existing = txn.get(key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (encoded_existing) |encoded| {
                var existing = try decodeExtensionMemberRecord(self.alloc, encoded);
                defer existing.deinitOwned(self.alloc);
                try self.deleteExtensionTableOwnerIndexTxn(txn, group_id, existing);
            }
            const value = try encodeExtensionMemberRecord(self.alloc, record);
            defer self.alloc.free(value);
            try txn.put(key, value);
            try self.putExtensionTableOwnerIndexTxn(txn, group_id, record);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
        }
    }

    fn encodeRegistrationNodeRecordTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.NodeRecord,
    ) ![]u8 {
        var applied = record;
        const existing = try self.loadNodeRecordTxn(txn, group_id, record.node_id);
        defer if (existing) |existing_record| metadata_table_manager.freeNode(self.alloc, existing_record);
        if (existing) |existing_record| {
            applied.lifecycle = existing_record.lifecycle;
        }
        return try encodeNodeRecord(self.alloc, applied);
    }

    fn applyNodeShutdownRequestTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, node_id: u64) !void {
        const existing = try self.loadNodeRecordTxn(txn, group_id, node_id);
        defer if (existing) |record| metadata_table_manager.freeNode(self.alloc, record);
        // A retried request is idempotent across every accepted shutdown
        // phase. Only cancellation may move finalizing back to active; keeping
        // this state monotonic preserves the one-shot finalize intent while
        // placement or store observations drain.
        if (existing == null or !metadata_table_manager.nodeLifecycleFinalizing(existing.?.lifecycle)) {
            try self.setNodeLifecycleTxn(txn, group_id, node_id, metadata_table_manager.node_lifecycle_draining, true);
        }
        try self.setNodeStoresDrainRequestedTxn(txn, group_id, node_id, true);
    }

    fn applyNodeShutdownCancelTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, node_id: u64) !void {
        try self.setNodeLifecycleTxn(txn, group_id, node_id, metadata_table_manager.node_lifecycle_active, false);
        try self.setNodeStoresDrainRequestedTxn(txn, group_id, node_id, false);
    }

    fn applyNodeShutdownFinalizeTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, node_id: u64) !void {
        var node_key_buf: [160]u8 = undefined;
        const node_key = try nodeKeyForGroup(&node_key_buf, group_id, node_id);

        const existing_node = try self.loadNodeRecordTxn(txn, group_id, node_id);
        defer if (existing_node) |record| metadata_table_manager.freeNode(self.alloc, record);
        var draining_node = false;
        if (existing_node) |record| {
            // Explicit cancellation wins if it commits before finalization.
            // Other debt races retain a durable finalizing lifecycle below so
            // the accepted one-shot request is not silently lost.
            if (metadata_table_manager.nodeLifecycleActive(record.lifecycle)) return;
            draining_node = true;
        }

        // Placement ownership is the durable deletion fence. Observational
        // store debt below may lag, but finalization must never remove the
        // node/store records while a placement still targets this node.
        var has_termination_debt = try self.nodeHasPlacementIntentTxn(txn, group_id, node_id);

        const StoreRef = struct {
            store_id: u64,
            node_id: u64,
        };
        var stores_to_delete = std.ArrayListUnmanaged(StoreRef).empty;
        defer stores_to_delete.deinit(self.alloc);

        var prefix_buf: [128]u8 = undefined;
        const prefix = try storePrefixForGroup(&prefix_buf, group_id);
        {
            var cur = try txn.openCursor();
            defer cur.close();
            var entry = try cur.seekAtOrAfter(prefix);
            while (entry) |kv| : (entry = try cur.next()) {
                if (!std.mem.startsWith(u8, kv.key, prefix)) break;
                const store = try self.readStoredStoreTxn(self.alloc, txn, group_id, kv.value);
                defer metadata_table_manager.freeStore(self.alloc, store);
                if (store.node_id == node_id) {
                    if (!draining_node and !store.drain_requested) return;
                    has_termination_debt = has_termination_debt or metadata_table_manager.storeHasTerminationDebt(store);
                    has_termination_debt = has_termination_debt or try initialFkStoreHasLivePlacementTxn(txn, group_id, store.store_id);
                    try stores_to_delete.append(self.alloc, .{ .store_id = store.store_id, .node_id = store.node_id });
                }
            }
        }

        if (has_termination_debt) {
            // Persist the accepted finalization request in the same record
            // whose draining lifecycle already fences new placement. Store
            // status and placement-removal commands retry only this node when
            // they clear debt, avoiding a metadata-wide polling scan.
            try self.setNodeLifecycleTxn(
                txn,
                group_id,
                node_id,
                metadata_table_manager.node_lifecycle_finalizing,
                true,
            );
            return;
        }

        txn.delete(node_key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = node_key });

        for (stores_to_delete.items) |store| {
            var key_buf: [160]u8 = undefined;
            const key = try storeKeyForGroup(&key_buf, group_id, store.store_id);
            _ = try self.updateListingStoreTxn(txn, group_id, store.store_id, null);
            txn.delete(key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            self.notifyProjectionListeners(.{
                .kind = .store,
                .metadata_group_id = group_id,
                .store_id = store.store_id,
                .node_id = store.node_id,
            });
        }
    }

    fn retryPendingNodeShutdownFinalizeTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        node_id: u64,
    ) !void {
        const node = (try self.loadNodeRecordTxn(txn, group_id, node_id)) orelse return;
        defer metadata_table_manager.freeNode(self.alloc, node);
        if (!metadata_table_manager.nodeLifecycleFinalizing(node.lifecycle)) return;
        try self.applyNodeShutdownFinalizeTxn(txn, group_id, node_id);
    }

    fn nodeHasPlacementIntentTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        node_id: u64,
    ) !bool {
        var prefix_buf: [128]u8 = undefined;
        const prefix = try placementPrefixForGroup(&prefix_buf, metadata_group_id);
        var cur = try txn.openCursor();
        defer cur.close();
        var entry = try cur.seekAtOrAfter(prefix);
        while (entry) |kv| : (entry = try cur.next()) {
            if (!std.mem.startsWith(u8, kv.key, prefix)) break;
            const intent = try decodePlacementIntent(self.alloc, kv.value);
            defer raft_reconciler.freeIntentOwned(self.alloc, intent);
            if (intent.record.local_node_id == node_id) return true;
        }
        return false;
    }

    fn setNodeLifecycleTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        node_id: u64,
        lifecycle: []const u8,
        create_if_missing: bool,
    ) !void {
        var key_buf: [160]u8 = undefined;
        const key = try nodeKeyForGroup(&key_buf, group_id, node_id);

        const existing = try self.loadNodeRecordTxn(txn, group_id, node_id);
        defer if (existing) |existing_record| metadata_table_manager.freeNode(self.alloc, existing_record);

        if (existing) |existing_record| {
            if (std.mem.eql(u8, existing_record.lifecycle, lifecycle)) return;
            var applied = existing_record;
            applied.lifecycle = lifecycle;
            const value = try encodeNodeRecord(self.alloc, applied);
            defer self.alloc.free(value);
            try txn.put(key, value);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            return;
        }

        if (!create_if_missing) return;
        const record: metadata.NodeRecord = .{
            .node_id = node_id,
            .role = "data",
            .lifecycle = lifecycle,
        };
        const value = try encodeNodeRecord(self.alloc, record);
        defer self.alloc.free(value);
        try txn.put(key, value);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
    }

    fn setNodeStoresDrainRequestedTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        node_id: u64,
        drain_requested: bool,
    ) !void {
        var updates = std.ArrayListUnmanaged(metadata.StoreRecord).empty;
        defer {
            for (updates.items) |record| metadata_table_manager.freeStore(self.alloc, record);
            updates.deinit(self.alloc);
        }

        var prefix_buf: [128]u8 = undefined;
        const prefix = try storePrefixForGroup(&prefix_buf, group_id);
        {
            var cur = try txn.openCursor();
            defer cur.close();
            var entry = try cur.seekAtOrAfter(prefix);
            while (entry) |kv| : (entry = try cur.next()) {
                if (!std.mem.startsWith(u8, kv.key, prefix)) break;
                var store = try self.readStoredStoreTxn(self.alloc, txn, group_id, kv.value);
                var store_owned = true;
                errdefer if (store_owned) metadata_table_manager.freeStore(self.alloc, store);
                if (store.node_id == node_id and store.drain_requested != drain_requested) {
                    store.drain_requested = drain_requested;
                    try updates.append(self.alloc, store);
                    store_owned = false;
                } else {
                    store_owned = false;
                    metadata_table_manager.freeStore(self.alloc, store);
                }
            }
        }

        for (updates.items) |record| {
            var key_buf: [160]u8 = undefined;
            const key = try storeKeyForGroup(&key_buf, group_id, record.store_id);
            _ = try self.updateListingStoreTxn(txn, group_id, record.store_id, record);
            self.notifyCommittedKeyListeners(.{ .metadata_group_id = group_id, .key = key });
            self.notifyProjectionListeners(.{
                .kind = .store,
                .metadata_group_id = group_id,
                .store_id = record.store_id,
                .node_id = record.node_id,
            });
        }
    }

    fn normalizeStoreDrainIntentTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.StoreRecord,
    ) !metadata.StoreRecord {
        var applied = record;
        if (try self.nodeDrainRequestedTxn(txn, group_id, record.node_id)) {
            applied.drain_requested = true;
            return applied;
        }
        const existing = try self.loadStoreHeaderTxn(txn, group_id, record.store_id);
        defer if (existing) |existing_record| metadata_table_manager.freeStore(self.alloc, existing_record);
        if (existing) |existing_record| {
            applied.drain_requested = existing_record.drain_requested;
        } else {
            applied.drain_requested = false;
        }
        return applied;
    }

    fn normalizeStoreUpsertDrainIntentTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        group_id: u64,
        record: metadata.StoreRecord,
    ) !metadata.StoreRecord {
        // The decoded command owns its reports through apply. Drain intent
        // changes only a scalar; borrowing avoids cloning every runtime payload.
        var applied = record;
        if (try self.nodeDrainRequestedTxn(txn, group_id, record.node_id)) {
            applied.drain_requested = true;
        }
        return applied;
    }

    fn loadNodeRecordTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, node_id: u64) !?metadata.NodeRecord {
        var key_buf: [160]u8 = undefined;
        const key = try nodeKeyForGroup(&key_buf, group_id, node_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return try decodeNodeRecord(self.alloc, encoded);
    }

    fn nodeDrainRequestedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, node_id: u64) !bool {
        const node = (try self.loadNodeRecordTxn(txn, group_id, node_id)) orelse return false;
        defer metadata_table_manager.freeNode(self.alloc, node);
        return !metadata_table_manager.nodeLifecycleActive(node.lifecycle);
    }

    fn loadPlacementIntentTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        placement_key: []const u8,
    ) !?raft_reconciler.PlacementIntent {
        const encoded = txn.get(placement_key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return try decodePlacementIntent(self.alloc, encoded);
    }

    fn loadPlacementVersionFenceTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        range_group_id: u64,
        local_node_id: u64,
    ) !u64 {
        _ = self;
        var key_buf: [192]u8 = undefined;
        const key = try placementVersionKeyForGroup(&key_buf, metadata_group_id, range_group_id, local_node_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return 0,
            else => return err,
        };
        if (encoded.len != @sizeOf(u64)) return error.InvalidPlacementVersionFence;
        return std.mem.readInt(u64, encoded[0..@sizeOf(u64)], .little);
    }

    fn writePlacementVersionFenceTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        range_group_id: u64,
        local_node_id: u64,
        version: u64,
    ) !void {
        _ = self;
        var key_buf: [192]u8 = undefined;
        const key = try placementVersionKeyForGroup(&key_buf, metadata_group_id, range_group_id, local_node_id);
        var encoded: [@sizeOf(u64)]u8 = undefined;
        std.mem.writeInt(u64, &encoded, version, .little);
        try txn.put(key, &encoded);
    }

    fn advancePlacementVersionFenceTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        range_group_id: u64,
        local_node_id: u64,
        observed_version: u64,
    ) !u64 {
        const current = try self.loadPlacementVersionFenceTxn(txn, metadata_group_id, range_group_id, local_node_id);
        const basis = @max(current, observed_version);
        if (basis == std.math.maxInt(u64)) return error.PlacementVersionExhausted;
        const next = basis + 1;
        try self.writePlacementVersionFenceTxn(txn, metadata_group_id, range_group_id, local_node_id, next);
        return next;
    }

    fn placementTargetDrainRequestedTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        intent: raft_reconciler.PlacementIntent,
    ) !?bool {
        const node = (try self.loadNodeRecordTxn(txn, metadata_group_id, intent.record.local_node_id)) orelse return null;
        defer metadata_table_manager.freeNode(self.alloc, node);
        var drain_requested = !metadata_table_manager.nodeLifecycleActive(node.lifecycle);
        if (intent.store_id != 0) {
            const store = (try self.loadStoreHeaderTxn(txn, metadata_group_id, intent.store_id)) orelse return null;
            defer metadata_table_manager.freeStore(self.alloc, store);
            if (store.node_id != intent.record.local_node_id) return null;
            drain_requested = drain_requested or store.drain_requested;
        }
        return drain_requested;
    }

    /// The wire command, not mutable apply-time state alone, determines the
    /// decoder floor. A hosted reservation therefore accepts only the v17
    /// command bearing its exact identity; stale commands are Raft no-ops.
    fn initialPlacementProofMatchesTxn(
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        range_group_id: u64,
        proof: ?fk_generation_publication.InitialPlacementProof,
        allow_canceled: bool,
    ) !bool {
        var key_buf: [160]u8 = undefined;
        const raw = try stagingGet(txn, try fk_generation_publication.initialGroupKey(&key_buf, metadata_group_id, range_group_id));
        if (raw == null) return proof == null;
        const reservation = try fk_generation_publication.InitialGroupReservation.decode(raw.?);
        if (reservation.retirement_scope == .local_owner) return proof == null;
        return if (proof) |identity|
            (if (allow_canceled) identity.identityMatches(reservation) else identity.activeMatches(reservation))
        else
            false;
    }

    /// Point-read the immutable hidden group reservation for proposal-time
    /// command selection. The caller must re-read under catalog mutation
    /// serialization before append; apply still checks the proof exactly.
    pub fn initialGroupReservation(self: *RaftApplyStore, metadata_group_id: u64, range_group_id: u64) !?fk_generation_publication.InitialGroupReservation {
        var key_buf: [160]u8 = undefined;
        const raw = self.store.get(self.alloc, try fk_generation_publication.initialGroupKey(&key_buf, metadata_group_id, range_group_id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer self.alloc.free(raw);
        return try fk_generation_publication.InitialGroupReservation.decode(raw);
    }

    fn applyPlacementCompareAndUpsertTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        expected_metadata_version: ?u64,
        expected_version_fence: u64,
        expected_target_drain_requested: bool,
        replacement: raft_reconciler.PlacementIntent,
        proof: ?fk_generation_publication.InitialPlacementProof,
    ) !void {
        if (!try initialPlacementProofMatchesTxn(txn, metadata_group_id, replacement.record.group_id, proof, false)) return;
        const target_drain_requested = (try self.placementTargetDrainRequestedTxn(
            txn,
            metadata_group_id,
            replacement,
        )) orelse return;
        if (target_drain_requested != expected_target_drain_requested) return;
        if (target_drain_requested and
            replacement.serving_state != .draining and
            replacement.serving_state != .retiring)
        {
            return;
        }

        var key_buf: [192]u8 = undefined;
        const key = try placementKeyForGroup(
            &key_buf,
            metadata_group_id,
            replacement.record.group_id,
            replacement.record.local_node_id,
        );
        const existing = try self.loadPlacementIntentTxn(txn, key);
        defer if (existing) |intent| raft_reconciler.freeIntentOwned(self.alloc, intent);
        const current_version_fence = try self.loadPlacementVersionFenceTxn(
            txn,
            metadata_group_id,
            replacement.record.group_id,
            replacement.record.local_node_id,
        );
        if (current_version_fence != expected_version_fence) return;
        if (expected_metadata_version) |expected| {
            if (existing == null or
                existing.?.record.metadata_version != expected or
                replacement.record.metadata_version != expected or
                expected != expected_version_fence)
            {
                return;
            }
        } else if (existing != null or replacement.record.metadata_version != 0) {
            return;
        }
        if (!try self.initialPlacementAuthorizedTxn(txn, metadata_group_id, replacement)) return;
        if (!try self.initialFkPhysicalSlotReusableTxn(txn, metadata_group_id, replacement, existing)) return;

        const next_version = try self.advancePlacementVersionFenceTxn(
            txn,
            metadata_group_id,
            replacement.record.group_id,
            replacement.record.local_node_id,
            if (existing) |intent| intent.record.metadata_version else 0,
        );
        var applied = replacement;
        applied.record.metadata_version = next_version;
        // The placement CAS is the physical owner-admission identity source.
        // Reconciliation may refresh metadata_version many times for the same
        // local replica; only a new hidden placement or a changed store/
        // replica receives a new root generation. The local replica catalog
        // persists this before publishing the live Raft owner.
        var initial_group_key_buf: [160]u8 = undefined;
        const hidden_initial = try stagingGet(txn, try fk_generation_publication.initialGroupKey(
            &initial_group_key_buf,
            metadata_group_id,
            applied.record.group_id,
        )) != null;
        applied.record.initial_fk_root_generation = initialFkRootGeneration(
            existing,
            applied,
            hidden_initial,
            next_version,
        );
        if (hidden_initial) try self.recordInitialFkReplicaTxn(txn, metadata_group_id, applied, existing);
        try self.stageRestorePlacementAuthorityTxn(txn, metadata_group_id, applied.record.group_id, applied.record.local_node_id);
        const value = try encodePlacementIntent(self.alloc, applied);
        defer self.alloc.free(value);
        try txn.put(key, value);
        try self.upsertProjectedPlacementIntent(metadata_group_id, applied);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = metadata_group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .placement_intent,
            .metadata_group_id = metadata_group_id,
            .group_id = applied.record.group_id,
            .node_id = applied.record.local_node_id,
        });
    }

    /// Retain every admitted hidden replica, including one later removed from
    /// placement while its store is offline. The count is Raft-transactional
    /// and caps terminal cancellation work. A live-placement point index
    /// makes same-physical-root refreshes O(1), even across process restarts.
    fn adjustInitialFkStoreLiveCountTxn(txn: *docstore.DocStore.Txn, metadata_group_id: u64, store_id: u64, increment: bool) !void {
        if (store_id == 0) return;
        var key_buf: [160]u8 = undefined;
        const key = try fk_initial_retirement.storeLiveCountKey(&key_buf, metadata_group_id, store_id);
        const raw = try stagingGet(txn, key);
        const prior: u64 = if (raw) |bytes| blk: {
            if (bytes.len != 8) return error.InvalidInitialFkRetirement;
            break :blk std.mem.readInt(u64, bytes[0..8], .little);
        } else 0;
        if (!increment and prior == 0) return error.InvalidInitialFkRetirement;
        const next = if (increment) std.math.add(u64, prior, 1) catch return error.InitialFkRetirementHistoryFull else prior - 1;
        if (next == 0) {
            try txn.delete(key);
        } else {
            var encoded: [8]u8 = undefined;
            std.mem.writeInt(u64, &encoded, next, .little);
            try txn.put(key, &encoded);
        }
    }

    fn recordInitialFkReplicaTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, intent: raft_reconciler.PlacementIntent, existing: ?raft_reconciler.PlacementIntent) !void {
        var key_buf: [256]u8 = undefined;
        const raw_reservation = (try stagingGet(txn, try fk_generation_publication.initialGroupKey(&key_buf, metadata_group_id, intent.record.group_id))) orelse return error.InvalidInitialFkRetirement;
        const reservation = try fk_generation_publication.InitialGroupReservation.decode(raw_reservation);
        if (reservation.canceled or intent.record.initial_fk_root_generation == 0) return error.InvalidInitialFkRetirement;
        if (reservation.retirement_scope == .hosted_store and intent.store_id == 0) return error.InitialFkStoreRootIdentityUnavailable;
        const store_identity: struct { reporter: u64, root: u128 } = if (intent.store_id == 0) .{ .reporter = 0, .root = 0 } else blk: {
            const store = (try self.loadStoreHeaderTxn(txn, metadata_group_id, intent.store_id)) orelse return error.InvalidInitialFkRetirement;
            defer metadata_table_manager.freeStore(self.alloc, store);
            if (store.node_id != intent.record.local_node_id or store.reporter_incarnation == 0 or
                store.replica_root_incarnation == 0) return error.InitialFkStoreRootIdentityUnavailable;
            break :blk .{ .reporter = store.reporter_incarnation, .root = store.replica_root_incarnation };
        };
        var live_key_buf: [192]u8 = undefined;
        const live_key = try fk_initial_retirement.liveKey(&live_key_buf, metadata_group_id, intent.record.group_id, intent.record.local_node_id);
        const live_raw = try stagingGet(txn, live_key);
        if (existing) |prior| if (prior.store_id == intent.store_id and
            prior.record.replica_id == intent.record.replica_id and
            prior.record.initial_fk_root_generation == intent.record.initial_fk_root_generation)
        {
            // A same-placement refresh may survive process restart, but a
            // replacement physical root must first remove/re-admit the exact
            // placement to rotate its generation. The historical admission
            // is authoritative even if current registration now names a new
            // disk under the same node/store ID.
            const prior_replica = try fk_initial_retirement.Replica.decode(live_raw orelse return error.InitialFkRetirementHistoryMissing);
            if (prior_replica.group_id != intent.record.group_id or prior_replica.node_id != intent.record.local_node_id or
                prior_replica.store_id != intent.store_id or prior_replica.replica_id != intent.record.replica_id or
                prior_replica.root_generation != intent.record.initial_fk_root_generation or
                prior_replica.child_table_id != reservation.child_table_id or prior_replica.range_id != reservation.range_id or
                !std.mem.eql(u8, &prior_replica.plan_id, &reservation.plan_id) or
                !std.mem.eql(u8, &prior_replica.plan_digest, &reservation.plan_digest) or
                prior_replica.canceled or prior_replica.acked)
                return error.InvalidInitialFkRetirement;
            if (prior_replica.store_root_incarnation != store_identity.root) return error.InitialFkStoreRootChanged;
            var history_key_buf: [256]u8 = undefined;
            const history = try stagingGet(txn, try fk_initial_retirement.groupKey(&history_key_buf, metadata_group_id, prior_replica));
            if (history == null or !std.mem.eql(u8, history.?, live_raw.?)) return error.InitialFkRetirementHistoryMissing;
            // Process incarnation is not physical identity. Reuse the exact
            // historical work item rather than consuming the plan-wide cap.
            return;
        };
        if (existing == null and live_raw != null) return error.InvalidInitialFkRetirement;
        const prior_live = if (live_raw) |raw| try fk_initial_retirement.Replica.decode(raw) else null;
        if (prior_live) |prior| {
            const prior_intent = existing orelse return error.InvalidInitialFkRetirement;
            if (prior.group_id != prior_intent.record.group_id or prior.node_id != prior_intent.record.local_node_id or
                prior.store_id != prior_intent.store_id or prior.replica_id != prior_intent.record.replica_id or
                prior.root_generation != prior_intent.record.initial_fk_root_generation)
                return error.InvalidInitialFkRetirement;
        }
        const replica: fk_initial_retirement.Replica = .{
            .plan_id = reservation.plan_id,
            .plan_digest = reservation.plan_digest,
            .child_table_id = reservation.child_table_id,
            .group_id = intent.record.group_id,
            .range_id = reservation.range_id,
            .node_id = intent.record.local_node_id,
            .store_id = intent.store_id,
            .store_incarnation = store_identity.reporter,
            .store_root_incarnation = store_identity.root,
            .replica_id = intent.record.replica_id,
            .root_generation = intent.record.initial_fk_root_generation,
        };
        const history_key = try fk_initial_retirement.groupKey(&key_buf, metadata_group_id, replica);
        if (try stagingGet(txn, history_key)) |prior| {
            const decoded = try fk_initial_retirement.Replica.decode(prior);
            if (!std.meta.eql(decoded, replica)) return error.InvalidInitialFkRetirement;
            return;
        }
        var count_buf: [160]u8 = undefined;
        const count_key = try fk_initial_retirement.groupCountKey(&count_buf, metadata_group_id, replica.group_id);
        const previous = if (try stagingGet(txn, count_key)) |value| blk: {
            if (value.len != 8) return error.InvalidInitialFkRetirement;
            break :blk std.mem.readInt(u64, value[0..8], .little);
        } else @as(u64, 0);
        var plan_count_buf: [160]u8 = undefined;
        const plan_count_key = try fk_initial_retirement.planCountKey(&plan_count_buf, metadata_group_id, replica.child_table_id);
        const plan_previous = if (try stagingGet(txn, plan_count_key)) |value| blk: {
            if (value.len != 8) return error.InvalidInitialFkRetirement;
            break :blk std.mem.readInt(u64, value[0..8], .little);
        } else @as(u64, 0);
        if (previous >= fk_initial_retirement.max_replicas_per_group or
            plan_previous >= fk_initial_retirement.max_replicas_per_group) return error.InitialFkRetirementHistoryFull;
        var next: [8]u8 = undefined;
        std.mem.writeInt(u64, &next, previous + 1, .little);
        var plan_next: [8]u8 = undefined;
        std.mem.writeInt(u64, &plan_next, plan_previous + 1, .little);
        const value = try replica.encode();
        var store_key_buf: [256]u8 = undefined;
        if (prior_live) |prior| {
            if (prior.store_id != replica.store_id) {
                try adjustInitialFkStoreLiveCountTxn(txn, metadata_group_id, prior.store_id, false);
                try adjustInitialFkStoreLiveCountTxn(txn, metadata_group_id, replica.store_id, true);
            }
        } else try adjustInitialFkStoreLiveCountTxn(txn, metadata_group_id, replica.store_id, true);
        try txn.put(history_key, &value);
        try txn.put(try fk_initial_retirement.storeKey(&store_key_buf, metadata_group_id, replica), &value);
        try txn.put(live_key, &value);
        try txn.put(count_key, &next);
        try txn.put(plan_count_key, &plan_next);
    }

    /// A physical group directory cannot represent two outstanding historical
    /// roots. Metadata must not relabel it as a fresh generation before the
    /// old root's unlink ACK. Exact live-placement refreshes remain allowed.
    fn initialFkPhysicalSlotReusableTxn(_: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, replacement: raft_reconciler.PlacementIntent, existing: ?raft_reconciler.PlacementIntent) !bool {
        var prefix_buf: [160]u8 = undefined;
        const prefix = try fk_initial_retirement.groupPrefix(&prefix_buf, metadata_group_id, replacement.record.group_id);
        var cursor = try txn.openCursor();
        defer cursor.close();
        var row = try cursor.seekAtOrAfter(prefix);
        var count: usize = 0;
        while (row) |item| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, prefix)) break;
            count += 1;
            if (count > fk_initial_retirement.max_replicas_per_group) return error.InitialFkRetirementHistoryFull;
            const historical = try fk_initial_retirement.Replica.decode(item.value);
            if (historical.acked or historical.node_id != replacement.record.local_node_id or historical.store_id != replacement.store_id) continue;
            if (existing) |prior| {
                if (historical.retirement_authority == .canceled_plan and !historical.canceled and
                    prior.store_id == replacement.store_id and prior.record.replica_id == replacement.record.replica_id and
                    prior.record.replica_id == historical.replica_id and prior.record.initial_fk_root_generation == historical.root_generation) continue;
            }
            return false;
        }
        return true;
    }

    fn initialFkReplicaIsCurrentPlacementTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, replica: fk_initial_retirement.Replica) !bool {
        var key_buf: [192]u8 = undefined;
        const placement = (try self.loadPlacementIntentTxn(txn, try placementKeyForGroup(&key_buf, metadata_group_id, replica.group_id, replica.node_id))) orelse return false;
        defer raft_reconciler.freeIntentOwned(self.alloc, placement);
        // Protect the physical slot, not merely a label that a stale catalog
        // refresh could have changed while retaining the same group directory.
        return placement.store_id == replica.store_id and placement.record.group_id == replica.group_id and placement.record.local_node_id == replica.node_id;
    }

    /// Both discovery and ACK call this against their single transaction.
    /// Published-obsolete work derives authority from the immutable plan and
    /// the exact generation's absence, never from a fabricated canceled plan.
    fn initialFkRetirementAuthorityTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, publication: fk_generation_publication.InitialPublication, replica: fk_initial_retirement.Replica) !fk_initial_retirement_ack.CanceledReservation {
        if (publication.plan.retirement_scope != .hosted_store or publication.plan.child.table_id != replica.child_table_id or
            !std.mem.eql(u8, &publication.plan.id, &replica.plan_id) or !std.mem.eql(u8, &publication.plan_digest, &replica.plan_digest))
            return error.InitialFkRetirementPublicationChanged;
        switch (replica.retirement_authority) {
            .canceled_plan => {
                if (publication.phase != .canceled) return error.InitialFkRetirementPublicationChanged;
                var key_buf: [192]u8 = undefined;
                const raw = (try stagingGet(txn, try fk_generation_publication.initialGroupKey(&key_buf, metadata_group_id, replica.group_id))) orelse return error.InitialFkRetirementReservationChanged;
                const reservation = try fk_generation_publication.InitialGroupReservation.decode(raw);
                if (!reservation.canceled or reservation.retirement_scope != .hosted_store or reservation.child_table_id != replica.child_table_id or reservation.range_id != replica.range_id or
                    !std.mem.eql(u8, &reservation.plan_id, &replica.plan_id) or !std.mem.eql(u8, &reservation.plan_digest, &replica.plan_digest)) return error.InitialFkRetirementReservationChanged;
                return .{ .child_table_id = reservation.child_table_id, .range_id = reservation.range_id, .plan_id = reservation.plan_id, .plan_digest = reservation.plan_digest, .hosted = true, .canceled = true };
            },
            .published_obsolete => {
                if (publication.phase != .published) return error.InitialFkRetirementPublicationChanged;
                const matches_range = for (publication.plan.child_ranges) |range| {
                    if (range.group_id == replica.group_id and range.range_id == replica.range_id) break true;
                } else false;
                if (!matches_range or try self.initialFkReplicaIsCurrentPlacementTxn(txn, metadata_group_id, replica)) return error.InitialFkRetirementReservationChanged;
                return .{ .child_table_id = replica.child_table_id, .range_id = replica.range_id, .plan_id = replica.plan_id, .plan_digest = replica.plan_digest, .hosted = true, .canceled = false, .obsolete_placement = true };
            },
        }
    }

    fn terminalizeInitialFkReplicasTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, publication: fk_generation_publication.InitialPublication) !void {
        const canceled = publication.phase == .canceled;
        if (!canceled and publication.phase != .published) return error.InvalidInitialFkRetirement;
        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const a = arena.allocator();
        var plan_count_key_buf: [160]u8 = undefined;
        const plan_count_key = try fk_initial_retirement.planCountKey(&plan_count_key_buf, metadata_group_id, publication.plan.child.table_id);
        const plan_count_raw = try stagingGet(txn, plan_count_key);
        const plan_count: u64 = if (plan_count_raw) |raw| blk: {
            if (raw.len != 8) return error.InvalidInitialFkRetirement;
            break :blk std.mem.readInt(u64, raw[0..8], .little);
        } else 0;
        if (plan_count > fk_initial_retirement.max_replicas_per_group) return error.InitialFkRetirementHistoryFull;
        var seen: u64 = 0;
        var retained_total: u64 = 0;
        for (publication.plan.child_ranges) |range| {
            var prefix_buf: [160]u8 = undefined;
            const prefix = try fk_initial_retirement.groupPrefix(&prefix_buf, metadata_group_id, range.group_id);
            var collected: std.ArrayList(fk_initial_retirement.Replica) = .empty;
            {
                var cursor = try txn.openCursor();
                defer cursor.close();
                var row = try cursor.seekAtOrAfter(prefix);
                while (row) |item| : (row = try cursor.next()) {
                    if (!std.mem.startsWith(u8, item.key, prefix)) break;
                    if (collected.items.len >= fk_initial_retirement.max_replicas_per_group) return error.InitialFkRetirementHistoryFull;
                    const replica = try fk_initial_retirement.Replica.decode(item.value);
                    if (replica.group_id != range.group_id or replica.range_id != range.range_id or
                        replica.child_table_id != publication.plan.child.table_id or
                        !std.mem.eql(u8, &replica.plan_id, &publication.plan.id) or
                        !std.mem.eql(u8, &replica.plan_digest, &publication.plan_digest) or replica.canceled or replica.acked)
                        return error.InvalidInitialFkRetirement;
                    try collected.append(a, replica);
                }
            }
            var key_buf: [256]u8 = undefined;
            var count_key_buf: [160]u8 = undefined;
            const count_key = try fk_initial_retirement.groupCountKey(&count_key_buf, metadata_group_id, range.group_id);
            const count_raw = try stagingGet(txn, count_key);
            const count: u64 = if (count_raw) |raw| blk: {
                if (raw.len != 8) return error.InvalidInitialFkRetirement;
                break :blk std.mem.readInt(u64, raw[0..8], .little);
            } else 0;
            if (count != @as(u64, @intCast(collected.items.len))) return error.InvalidInitialFkRetirement;
            seen += count;
            if (seen > plan_count) return error.InvalidInitialFkRetirement;
            var retained_count: u64 = 0;
            for (collected.items) |replica| {
                var history_key_buf: [256]u8 = undefined;
                const work_key = try fk_initial_retirement.storeKey(&key_buf, metadata_group_id, replica);
                const work = (try stagingGet(txn, work_key)) orelse return error.InvalidInitialFkRetirement;
                if (!std.meta.eql(try fk_initial_retirement.Replica.decode(work), replica)) return error.InvalidInitialFkRetirement;
                const history_key = try fk_initial_retirement.groupKey(&history_key_buf, metadata_group_id, replica);
                var live_key_buf: [192]u8 = undefined;
                const live_key = try fk_initial_retirement.liveKey(&live_key_buf, metadata_group_id, replica.group_id, replica.node_id);
                if (try stagingGet(txn, live_key)) |raw_live| {
                    const live = try fk_initial_retirement.Replica.decode(raw_live);
                    if (live.store_id == replica.store_id and live.replica_id == replica.replica_id and
                        live.root_generation == replica.root_generation and live.store_root_incarnation == replica.store_root_incarnation)
                    {
                        try adjustInitialFkStoreLiveCountTxn(txn, metadata_group_id, live.store_id, false);
                        try txn.delete(live_key);
                    }
                }
                const obsolete = !canceled and !try self.initialFkReplicaIsCurrentPlacementTxn(txn, metadata_group_id, replica);
                if (canceled or obsolete) {
                    var terminal = replica;
                    terminal.canceled = true;
                    terminal.retirement_authority = if (canceled) .canceled_plan else .published_obsolete;
                    const encoded = try terminal.encode();
                    try txn.put(history_key, &encoded);
                    try txn.put(work_key, &encoded);
                    retained_count += 1;
                } else {
                    try txn.delete(history_key);
                    try txn.delete(work_key);
                }
            }
            retained_total += retained_count;
            if (!canceled and count_raw != null) {
                if (retained_count == 0) try txn.delete(count_key) else {
                    var value: [8]u8 = undefined;
                    std.mem.writeInt(u64, &value, retained_count, .little);
                    try txn.put(count_key, &value);
                }
            }
        }
        if (seen != plan_count) return error.InvalidInitialFkRetirement;
        if (!canceled and plan_count_raw != null) {
            if (retained_total == 0) try txn.delete(plan_count_key) else {
                var value: [8]u8 = undefined;
                std.mem.writeInt(u64, &value, retained_total, .little);
                try txn.put(plan_count_key, &value);
            }
        }
    }

    fn applyPlacementRemoveIfVersionTxn(
        self: *RaftApplyStore,
        txn: *docstore.DocStore.Txn,
        metadata_group_id: u64,
        range_group_id: u64,
        local_node_id: u64,
        expected_metadata_version: u64,
        proof: ?fk_generation_publication.InitialPlacementProof,
    ) !void {
        if (!try initialPlacementProofMatchesTxn(txn, metadata_group_id, range_group_id, proof, true)) return;
        var key_buf: [192]u8 = undefined;
        const key = try placementKeyForGroup(&key_buf, metadata_group_id, range_group_id, local_node_id);
        const existing = (try self.loadPlacementIntentTxn(txn, key)) orelse return;
        defer raft_reconciler.freeIntentOwned(self.alloc, existing);
        if (existing.record.metadata_version != expected_metadata_version) return;
        _ = try self.advancePlacementVersionFenceTxn(
            txn,
            metadata_group_id,
            range_group_id,
            local_node_id,
            existing.record.metadata_version,
        );
        if (existing.record.initial_fk_root_generation != 0) {
            var live_key_buf: [192]u8 = undefined;
            const live_key = try fk_initial_retirement.liveKey(&live_key_buf, metadata_group_id, range_group_id, local_node_id);
            if (try stagingGet(txn, live_key)) |raw| {
                const live = try fk_initial_retirement.Replica.decode(raw);
                if (live.group_id != range_group_id or live.node_id != local_node_id or
                    live.store_id != existing.store_id or live.replica_id != existing.record.replica_id or
                    live.root_generation != existing.record.initial_fk_root_generation)
                    return error.InvalidInitialFkRetirement;
                try adjustInitialFkStoreLiveCountTxn(txn, metadata_group_id, live.store_id, false);
                try txn.delete(live_key);
            }
        }
        try txn.delete(key);
        self.removeProjectedPlacementIntent(metadata_group_id, range_group_id, local_node_id);
        self.notifyCommittedKeyListeners(.{ .metadata_group_id = metadata_group_id, .key = key });
        self.notifyProjectionListeners(.{
            .kind = .placement_intent,
            .metadata_group_id = metadata_group_id,
            .group_id = range_group_id,
            .node_id = local_node_id,
        });
    }

    fn loadStoreHeaderTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, store_id: u64) !?metadata.StoreRecord {
        var key_buf: [160]u8 = undefined;
        const encoded = txn.get(try storeKeyForGroup(&key_buf, group_id, store_id)) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return try decodeStoredHeader(self.alloc, encoded);
    }

    /// A replacement physical disk may not silently inherit a live hidden
    /// child's placement merely by re-registering the same store ID. The
    /// transactional live-placement count is a point read even for a cluster
    /// with many unrelated placements.
    fn storeRootUpdateAllowedTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, metadata_group_id: u64, incoming: metadata.StoreRecord) !bool {
        const prior = (try self.loadStoreHeaderTxn(txn, metadata_group_id, incoming.store_id)) orelse
            // A missing header does not prove the physical root is new: a
            // truncated/corrupt header must not bypass an indexed live child.
            return !try initialFkStoreHasLivePlacementTxn(txn, metadata_group_id, incoming.store_id);
        defer metadata_table_manager.freeStore(self.alloc, prior);
        if (prior.replica_root_incarnation == incoming.replica_root_incarnation) {
            // Registration credentials cannot substitute an admitted root's
            // verifier. Rotation requires a new physical-root UUID.
            if (!std.mem.allEqual(u8, &prior.replica_root_public_key, 0) and
                !std.mem.eql(u8, &prior.replica_root_public_key, &incoming.replica_root_public_key)) return false;
            return true;
        }
        return !try initialFkStoreHasLivePlacementTxn(txn, metadata_group_id, incoming.store_id);
    }

    fn initialFkStoreHasLivePlacementTxn(txn: *docstore.DocStore.Txn, metadata_group_id: u64, store_id: u64) !bool {
        var count_key_buf: [160]u8 = undefined;
        const count = try stagingGet(txn, try fk_initial_retirement.storeLiveCountKey(&count_key_buf, metadata_group_id, store_id));
        if (count == null) return false;
        if (count.?.len != 8) return error.InvalidInitialFkRetirement;
        return std.mem.readInt(u64, count.?[0..8], .little) != 0;
    }

    fn notifyProjectionListeners(self: *RaftApplyStore, signal: ProjectionSignal) void {
        if (self.active_outcome) |outcome| {
            outcome.appendProjection(signal) catch |err| outcome.recordFailure(err);
            return;
        }
        for (self.projection_listeners.items) |registered| registered.listener.onProjectionSignal(signal);
    }

    fn notifyCommittedKeyListeners(self: *RaftApplyStore, signal: CommittedKeySignal) void {
        if (self.active_outcome) |outcome| {
            outcome.appendCommittedKey(signal) catch |err| outcome.recordFailure(err);
            return;
        }
        for (self.committed_key_listeners.items) |registered| registered.listener.onCommittedKey(signal);
    }

    fn notifyCommittedTransition(self: *RaftApplyStore, delta: CommittedTransitionDelta) void {
        const outcome = self.active_outcome orelse {
            std.debug.assert(false);
            return;
        };
        if (!outcome.collect_transition_deltas) return;
        outcome.appendTransition(delta) catch |err| outcome.recordFailure(err);
    }

    fn dispatchCommittedOutcome(self: *RaftApplyStore, outcome: *const CommittedApplyOutcome) void {
        std.debug.assert(outcome.failure == null);
        for (outcome.projection_signals.items) |owned| {
            for (self.projection_listeners.items) |registered| registered.listener.onProjectionSignal(owned.signal);
        }
        for (outcome.committed_keys.items) |owned| {
            const signal = CommittedKeySignal{
                .metadata_group_id = owned.metadata_group_id,
                .key = owned.key,
            };
            for (self.committed_key_listeners.items) |registered| registered.listener.onCommittedKey(signal);
        }
    }

    fn outcomeContainsProjectionKind(
        outcome: *const CommittedApplyOutcome,
        kind: ProjectionSignalKind,
    ) bool {
        return outcome.projection_kinds.contains(kind);
    }

    fn beginProjectionCommitBarriers(
        self: *RaftApplyStore,
        outcome: *const CommittedApplyOutcome,
    ) void {
        for (self.projection_listeners.items) |registered| {
            const listener = registered.listener;
            const kind = listener.commit_barrier_kind orelse continue;
            if (!outcomeContainsProjectionKind(outcome, kind)) continue;
            listener.beginCommitBarrier();
        }
    }

    fn endProjectionCommitBarriers(
        self: *RaftApplyStore,
        outcome: *const CommittedApplyOutcome,
    ) void {
        // Release in reverse registration order so independently composed
        // listeners retain ordinary nested-lock semantics.
        var index = self.projection_listeners.items.len;
        while (index > 0) {
            index -= 1;
            const listener = self.projection_listeners.items[index].listener;
            const kind = listener.commit_barrier_kind orelse continue;
            if (!outcomeContainsProjectionKind(outcome, kind)) continue;
            listener.endCommitBarrier();
        }
    }

    fn lookupTableName(self: *RaftApplyStore, group_id: u64, table_id: u64) !?[]u8 {
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, table_id);
        const encoded = self.store.get(self.alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer self.alloc.free(encoded);
        const table = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, table);
        return try self.alloc.dupe(u8, table.name);
    }

    fn lookupTableNameTxn(self: *RaftApplyStore, txn: *docstore.DocStore.Txn, group_id: u64, table_id: u64) !?[]u8 {
        var key_buf: [160]u8 = undefined;
        const key = try tableKeyForGroup(&key_buf, group_id, table_id);
        const encoded = txn.get(key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        const table = try decodeTableRecord(self.alloc, encoded);
        defer metadata_table_manager.freeTable(self.alloc, table);
        return try self.alloc.dupe(u8, table.name);
    }
};

fn replicationCutoverAuthorityIdentityEqual(
    a: metadata.ReplicationSourceStatusRecord,
    b: metadata.ReplicationSourceStatusRecord,
) bool {
    return a.table_id == b.table_id and
        a.source_ordinal == b.source_ordinal and
        a.cutover_intent_id == b.cutover_intent_id and
        a.cutover_authority_id == b.cutover_authority_id and
        std.mem.eql(u8, &a.cutover_config_fingerprint, &b.cutover_config_fingerprint) and
        std.mem.eql(u8, &a.cutover_provider_identity, &b.cutover_provider_identity) and
        std.mem.eql(u8, a.source_kind, b.source_kind) and
        std.mem.eql(u8, a.external_table, b.external_table) and
        std.mem.eql(u8, a.slot_name, b.slot_name) and
        std.mem.eql(u8, a.publication_name, b.publication_name);
}

fn replicationCutoverRetirementEqual(
    a: metadata.ReplicationSourceStatusRecord,
    b: metadata.ReplicationSourceStatusRecord,
) bool {
    return a.retired_cutover_authority_id == b.retired_cutover_authority_id and
        std.mem.eql(u8, a.retired_slot_name, b.retired_slot_name) and
        std.mem.eql(
            u8,
            a.retired_publication_name,
            b.retired_publication_name,
        );
}

fn replicationCutoverRetirementCleared(
    record: metadata.ReplicationSourceStatusRecord,
) bool {
    return record.retired_cutover_authority_id == 0 and
        record.retired_slot_name.len == 0 and
        record.retired_publication_name.len == 0;
}

const transition_magic = "afmd1";
const group_status_record_version: u16 = 4;
const metadata_incarnation_extension_magic = "afmi1";
const metadata_incarnation_extension_runtime_status_version: u16 = 1;
const metadata_incarnation_extension_version: u16 = 2;
const metadata_incarnation_extension_relational_topology_version: u16 = 3;
const metadata_incarnation_extension_schema_reader_version: u16 = 4;
// Store records predate framing and are read by mixed-version metadata
// replicas. Keep the existing prefix byte-for-byte compatible. Extensions are
// self-identifying for current readers, but legacy readers do not ignore them;
// embedded record-version upgrades therefore require capability negotiation.
const store_record_extension_magic = "afsx1";
const store_record_extension_legacy_version: u16 = 1;
const store_record_extension_reporter_version: u16 = 2;
const store_record_extension_native_restore_version: u16 = 3;
const store_record_extension_artifact_sources_version: u16 = 4;
const store_record_extension_version: u16 = 5;
const store_record_extension_relational_topology_version: u16 = 6;
const store_record_extension_root_incarnation_version: u16 = 7;
const store_record_extension_root_signing_version: u16 = 8;
// V9 makes root identity independent of reader capabilities. Zero UUID/key
// mean unsigned/absent here; V7/V8 retain their mandatory-root interpretation.
const store_record_extension_schema_reader_version: u16 = 9;

test "metadata raft apply store schema reader capabilities use explicit versions without requiring signed roots" {
    const alloc = std.testing.allocator;
    var record: metadata.StoreRecord = .{ .store_id = 1, .node_id = 2, .reporter_incarnation = 7 };
    var old_extension: std.ArrayListUnmanaged(u8) = .empty;
    defer old_extension.deinit(alloc);
    try appendStoreRecordExtensions(alloc, &old_extension, record);
    try std.testing.expectEqualStrings("afsx1", old_extension.items[0..5]);
    try std.testing.expectEqual(@as(u16, 2), std.mem.readInt(u16, old_extension.items[5..7], .little));
    try std.testing.expectEqual(@as(usize, 27), old_extension.items.len);
    record.schema_reader = metadata_table_manager.SchemaReaderCapabilities.current;
    const encoded = try encodeStoreRecord(alloc, record);
    defer alloc.free(encoded);
    const decoded = try decodeStoreRecord(alloc, encoded);
    defer metadata_table_manager.freeStore(alloc, decoded);
    try std.testing.expectEqualDeep(record.schema_reader, decoded.schema_reader);
    try std.testing.expectEqual(@as(u128, 0), decoded.replica_root_incarnation);
    var extension: std.ArrayListUnmanaged(u8) = .empty;
    defer extension.deinit(alloc);
    try appendStoreRecordExtensions(alloc, &extension, record);
    try std.testing.expectEqual(@as(u16, 9), std.mem.readInt(u16, extension.items[5..7], .little));
    for (1..extension.items.len) |cut| {
        var pos: usize = 0;
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, readStoreRecordExtensions(extension.items[0..cut], &pos, &.{}));
    }
    // A forged old version must not reinterpret capability bytes as old facts.
    extension.items[5] = 8;
    var pos: usize = 0;
    try std.testing.expectError(error.InvalidMetadataTransitionEncoding, readStoreRecordExtensions(extension.items, &pos, &.{}));
    record.schema_reader.encoding_ceiling = 0;
    try std.testing.expectError(error.InvalidStoreReporterFence, encodeStoreRecord(alloc, record));
}

test "metadata raft apply store schema reader registration and sparse replacement survive restart" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/schema-reader", .{tmp.sub_path});
    defer alloc.free(root);
    const record: metadata.StoreRecord = .{ .store_id = 1, .node_id = 2, .reporter_incarnation = 7, .status_generation = 1, .schema_reader = metadata_table_manager.SchemaReaderCapabilities.current };
    var report = store_report_update.asReport(record);
    report.status_generation = 2;
    report.schema_reader.semantic_ceiling = 30;
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try store.applyTransitionCommandTxn(&txn, 21, .{ .initialize_metadata_incarnation = "0123456789abcdef0123456789abcdef".* });
            try store.applyTransitionCommandTxn(&txn, 21, .{ .register_store = record });
            try txn.commit();
        }
        const bytes = try encodeTestReportUpdate(&store, alloc, .{ .sequence = 1, .report = report });
        defer alloc.free(bytes);
        try applyTestReportUpdate(&store, bytes);
    }
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const observed = (try store.readStore(alloc, 21, 1, false)).?;
    defer metadata_table_manager.freeStore(alloc, observed);
    try std.testing.expectEqualDeep(report.schema_reader, observed.schema_reader);
    try std.testing.expectEqual(@as(u64, 7), observed.reporter_incarnation);
    try std.testing.expectEqual(@as(u64, 2), observed.status_generation);
    try std.testing.expect(runtime_status_protocol.profileSatisfies(
        try store.getRuntimeStatusProtocolActivationVersion(21),
        runtime_status_protocol.framed_index_record_version,
    ));
    try std.testing.expectEqual(@as(u64, 1), (try store.reportCursor(21, 1)).?.sequence);
    // An old process cannot replace the installed report after restart.
    report.reporter_incarnation = 6;
    const stale = try encodeTestReportUpdate(&store, alloc, .{ .sequence = 2, .report = report });
    defer alloc.free(stale);
    try applyTestReportUpdate(&store, stale);
    const unchanged = (try store.readStore(alloc, 21, 1, false)).?;
    defer metadata_table_manager.freeStore(alloc, unchanged);
    try std.testing.expectEqualDeep(observed.schema_reader, unchanged.schema_reader);
    try std.testing.expectEqual(@as(u64, 7), unchanged.reporter_incarnation);
}

test "metadata raft apply store schema reader sparse and baseline envelopes reject downgraded framing" {
    const alloc = std.testing.allocator;
    const report: metadata.StoreStatusReport = .{ .store_id = 1, .reporter_incarnation = 7, .schema_reader = metadata_table_manager.SchemaReaderCapabilities.current };
    const bytes = try encodeStoreReportUpdate(alloc, .{ .update = .{ .sequence = 1, .report = report }, .request_digest = @splat(1), .expected_header = @splat(2) });
    defer alloc.free(bytes);
    try std.testing.expectEqual(@as(u16, 2), std.mem.readInt(u16, bytes[0..2], .little));
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const command = try decodeStoreReportUpdate(arena.allocator(), bytes);
    try std.testing.expectEqualDeep(report.schema_reader, command.update.report.schema_reader);
    bytes[0] = 1;
    try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeStoreReportUpdate(arena.allocator(), bytes));
    const baseline = try encodeStoreReportBaseline(alloc, .{
        .request = .{ .action = .prepare, .cursor = .{ .reporter_incarnation = 7, .sequence = 1, .digest = @splat(3) }, .chunk_count = 1, .total_bytes = 1, .report = report },
        .expected_header = @splat(2),
        .admission_cursor = null,
    });
    defer alloc.free(baseline);
    try std.testing.expectEqual(@as(u16, 3), std.mem.readInt(u16, baseline[0..2], .little));
    const decoded = try decodeStoreReportBaseline(arena.allocator(), baseline);
    try std.testing.expectEqualDeep(report.schema_reader, decoded.request.report.schema_reader);
    const batch = try encodeStoreReportBaselineBatch(alloc, &.{ baseline, baseline });
    defer alloc.free(batch);
    try std.testing.expectEqual(@as(u16, 4), std.mem.readInt(u16, batch[0..2], .little));
    baseline[0] = 1;
    try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeStoreReportBaseline(arena.allocator(), baseline));
}
const reallocation_request_extension_magic = "afrr1";
const reallocation_request_extension_version: u16 = 1;

const MetadataIncarnationRecord = struct {
    incarnation: metadata_incarnation.MetadataClusterIncarnation,
    runtime_status_record_version: u16 = 0,
    dense_native_storage_protocol_activated_version: u16 = 0,
    relational_topology_protocol_activated_version: u16 = 0,
    schema_reader_floor: metadata_table_manager.SchemaReaderFloor = .{},
};

test "metadata raft apply store schema reader floor codec preserves predecessor floors and rejects corrupt frames" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reader-floor-codec", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    var record: MetadataIncarnationRecord = .{ .incarnation = "0123456789abcdef0123456789abcdef".* };
    var buf: [160]u8 = undefined;
    const key = try metadataIncarnationKeyForGroup(&buf, 21);
    try writeMetadataIncarnationRecordTxn(&txn, 21, record);
    const legacy = try a.dupe(u8, try txn.get(key));
    defer a.free(legacy);
    const version_offset = @sizeOf(metadata_incarnation.MetadataClusterIncarnation) + metadata_incarnation_extension_magic.len;
    try std.testing.expectEqual(@as(u16, 2), std.mem.readInt(u16, legacy[version_offset..][0..2], .little));
    try std.testing.expect(!(try decodeMetadataIncarnationRecord(legacy)).schema_reader_floor.active());
    record.runtime_status_record_version = runtime_status_protocol.framed_index_record_version;
    record.dense_native_storage_protocol_activated_version = 1;
    record.relational_topology_protocol_activated_version = 2;
    record.schema_reader_floor = .{ .semantic_version = 30, .encoding_version = 31 };
    try writeMetadataIncarnationRecordTxn(&txn, 21, record);
    const encoded = try a.dupe(u8, try txn.get(key));
    defer a.free(encoded);
    try std.testing.expectEqual(@as(u16, 4), std.mem.readInt(u16, encoded[version_offset..][0..2], .little));
    try std.testing.expectEqualDeep(record, try decodeMetadataIncarnationRecord(encoded));
    for (0..encoded.len) |cut| {
        if (cut == @sizeOf(metadata_incarnation.MetadataClusterIncarnation)) continue; // Exact legacy incarnation remains valid.
        try std.testing.expectError(error.InvalidMetadataIncarnation, decodeMetadataIncarnationRecord(encoded[0..cut]));
    }
    encoded[version_offset] = 3;
    try std.testing.expectError(error.InvalidMetadataIncarnation, decodeMetadataIncarnationRecord(encoded));
    encoded[version_offset] = 5;
    try std.testing.expectError(error.InvalidMetadataIncarnation, decodeMetadataIncarnationRecord(encoded));
    encoded[version_offset] = 4;
    const floor_offset = version_offset + 4 * @sizeOf(u16);
    for ([_]metadata_table_manager.SchemaReaderFloor{
        .{},                                                                                                                                 .{ .semantic_version = 30 },                                                                                                         .{ .encoding_version = 31 },
        .{ .semantic_version = @import("antfly_local_sources").common_schema_readers.current_semantic_version + 1, .encoding_version = 31 }, .{ .semantic_version = 30, .encoding_version = @import("antfly_local_sources").common_schema_readers.current_encoding_version + 1 },
    }) |bad| {
        std.mem.writeInt(u32, encoded[floor_offset..][0..4], bad.semantic_version, .little);
        std.mem.writeInt(u32, encoded[floor_offset + 4 ..][0..4], bad.encoding_version, .little);
        try std.testing.expectError(error.InvalidMetadataIncarnation, decodeMetadataIncarnationRecord(encoded));
    }
    record.schema_reader_floor = .{ .semantic_version = 30 };
    try std.testing.expectError(error.InvalidMetadataIncarnation, writeMetadataIncarnationRecordTxn(&txn, 21, record));
}

test "metadata raft apply store schema reader floor is transactional monotonic and rejects later downgrade" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reader-floor", .{tmp.sub_path});
    defer a.free(root);
    const restored_root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reader-floor-restored", .{tmp.sub_path});
    defer a.free(restored_root);
    const requirement: @import("antfly_local_sources").storage_schema.ReaderRequirements = .{ .semantic_version = 30, .encoding_version = 31 };
    const activation = try readerFloorActivationForTest(a);
    defer a.free(activation);
    const capable: metadata.StoreRecord = .{ .store_id = 1, .node_id = 1, .reporter_incarnation = 11, .schema_reader = metadata_table_manager.SchemaReaderCapabilities.current };
    var other = capable;
    other.store_id = 2;
    other.node_id = 2;
    other.reporter_incarnation = 22;
    other.schema_reader.semantic_ceiling = 29;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "reader_floor_rows", .schema_json = "{}" };
    const snapshot = snapshot: {
        var store = try RaftApplyStore.init(a, .{ .root_dir = root });
        defer store.deinit();
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try store.applyTransitionCommandTxn(&txn, 21, .{ .initialize_metadata_incarnation = "0123456789abcdef0123456789abcdef".* });
            _ = try store.ensureDerivedCatalogIndexesTxn(&txn, 21);
            try store.applyTransitionCommandTxn(&txn, 21, .{ .register_store = capable });
            try store.applyTransitionCommandTxn(&txn, 21, .{ .register_store = other });
            try store.applyTransitionCommandTxn(&txn, 21, .{ .activate_topology_protocol = activation });
            try std.testing.expect(!try store.raiseSchemaReaderFloorTxn(&txn, 21, requirement));
            try txn.commit();
        }
        try std.testing.expect(!(try store.getSchemaReaderFloor(21)).active());
        other.schema_reader = metadata_table_manager.SchemaReaderCapabilities.current;
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try store.applyTransitionCommandTxn(&txn, 21, .{ .register_store = other });
            try txn.commit();
        }
        // An aborted publication exposes neither the floor nor catalog row.
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            try std.testing.expect(try store.raiseSchemaReaderFloorTxn(&txn, 21, requirement));
            try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_table = table });
        }
        try std.testing.expect(!(try store.getSchemaReaderFloor(21)).active());
        {
            var txn = try store.store.beginReadTxn();
            defer txn.abort();
            try std.testing.expect((try store.getTableByNameTxn(a, &txn, 21, table.name)) == null);
        }
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try std.testing.expect(try store.raiseSchemaReaderFloorTxn(&txn, 21, requirement));
            try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_table = table });
            try txn.commit();
        }
        const admitted = try store.getSchemaReaderFloor(21);
        try std.testing.expectEqual(@as(u32, 30), admitted.semantic_version);
        try std.testing.expectEqual(@as(u32, 31), admitted.encoding_version);
        // This deliberately fails every header allocation: already covered
        // identities must not rescan/decode the registered store inventory.
        {
            var failing = std.testing.FailingAllocator.init(a, .{ .fail_index = 0, .resize_fail_index = 0 });
            const saved = store.alloc;
            store.alloc = failing.allocator();
            defer store.alloc = saved;
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            for (0..10_000) |_| try std.testing.expect(try store.raiseSchemaReaderFloorTxn(&txn, 21, .{ .semantic_version = 13, .encoding_version = 17 }));
            try std.testing.expectEqual(@as(usize, 0), failing.alloc_index);
        }
        var downgrade = capable;
        downgrade.schema_reader = .{};
        var newcomer = downgrade;
        newcomer.store_id = 3;
        newcomer.node_id = 3;
        newcomer.reporter_incarnation = 33;
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_store = downgrade });
            try store.applyTransitionCommandTxn(&txn, 21, .{ .register_store = newcomer });
            // References retain the registered capability, not an omitted or
            // forged implementation claim in a liveness-only refresh.
            downgrade.capacity_bytes = 123;
            try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_store_heartbeat = downgrade });
            try txn.commit();
        }
        try std.testing.expect((try store.readStore(a, 21, 3, false)) == null);
        const unchanged = (try store.readStore(a, 21, 1, false)).?;
        defer metadata_table_manager.freeStore(a, unchanged);
        try std.testing.expectEqualDeep(capable.schema_reader, unchanged.schema_reader);
        try std.testing.expectEqual(@as(u64, 123), unchanged.capacity_bytes);
        try std.testing.expectError(error.SchemaReaderUpgradeRequired, metadata_table_manager.requireSchemaReaderAtFloor(admitted, newcomer));
        newcomer.role = "metadata";
        try metadata_table_manager.requireSchemaReaderAtFloor(admitted, newcomer);
        const sparse = try encodeTestReportUpdate(&store, a, .{ .sequence = 1, .report = store_report_update.asReport(downgrade) });
        defer a.free(sparse);
        try applyTestReportUpdate(&store, sparse);
        try std.testing.expect((try store.reportCursor(21, 1)) == null);
        try std.testing.expectEqualDeep(admitted, try store.getSchemaReaderFloor(21));
        break :snapshot try store.snapshotBuilder().buildSnapshot(a, 21);
    };
    defer a.free(snapshot);
    {
        var restored = try RaftApplyStore.init(a, .{ .root_dir = restored_root });
        defer restored.deinit();
        try RaftApplyStore.installSnapshotFromRaft(&restored, a, 21, 10, snapshot);
    }
    var reopened = try RaftApplyStore.init(a, .{ .root_dir = restored_root });
    defer reopened.deinit();
    const retained = try reopened.getSchemaReaderFloor(21);
    try std.testing.expectEqual(@as(u32, 30), retained.semantic_version);
    try std.testing.expectEqual(@as(u32, 31), retained.encoding_version);
    // Snapshot installation deliberately retires derived lookup indexes.
    // Bootstrap them through the normal catalog path before a name lookup.
    {
        var bootstrap = try reopened.store.beginWriteTxn();
        errdefer bootstrap.abort();
        _ = try reopened.ensureDerivedCatalogIndexesTxn(&bootstrap, 21);
        try bootstrap.commit();
    }
    var txn = try reopened.store.beginReadTxn();
    defer txn.abort();
    const visible = (try reopened.getTableByNameTxn(a, &txn, 21, table.name)).?;
    defer metadata_table_manager.freeTable(a, visible);
    try std.testing.expectEqual(table.table_id, visible.table_id);
}

test "system catalog schema reader floor advancement fences an uploaded baseline before activation" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reader-floor-baseline", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    const capable: metadata.StoreRecord = .{ .store_id = 1, .node_id = 1, .reporter_incarnation = 11, .schema_reader = metadata_table_manager.SchemaReaderCapabilities.current };
    const activation = try readerFloorActivationForTest(a);
    defer a.free(activation);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try store.applyTransitionCommandTxn(&txn, 21, .{ .initialize_metadata_incarnation = "0123456789abcdef0123456789abcdef".* });
        try store.applyTransitionCommandTxn(&txn, 21, .{ .register_store = capable });
        try std.testing.expect(!try store.raiseSchemaReaderFloorTxn(&txn, 21, .{ .semantic_version = 30, .encoding_version = 31 }));
        try store.applyTransitionCommandTxn(&txn, 21, .{ .activate_topology_protocol = activation });
        try txn.commit();
    }
    var publisher: store_report_update.Publisher = .{};
    defer publisher.deinit(a);
    var groups = [_]metadata.GroupStatusReport{.{ .group_id = 100 }};
    var report = store_report_update.asReport(capable);
    report.group_statuses = &groups;
    report.schema_reader.semantic_ceiling = 29;
    var prepared = try publisher.prepare(a, report, true, false);
    defer prepared.deinit(a);
    var plan = try store_report_baseline.Plan.init(a, &prepared);
    defer plan.deinit();
    try applyTestBaseline(&store, a, plan.request);
    var chunk = plan.request;
    chunk.action = .chunk;
    chunk.report = plan.chunks[0];
    try applyTestBaseline(&store, a, chunk);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try std.testing.expect(try store.raiseSchemaReaderFloorTxn(&txn, 21, .{ .semantic_version = 30, .encoding_version = 31 }));
        try txn.commit();
    }
    var activate = plan.request;
    activate.action = .activate;
    try applyTestBaseline(&store, a, activate);
    try std.testing.expect(!(try store.reportBaselineProgress(21, plan.request)).activated);
    try std.testing.expect((try store.reportCursor(21, 1)) == null);
    const retained = (try store.readStore(a, 21, 1, false)).?;
    defer metadata_table_manager.freeStore(a, retained);
    try std.testing.expectEqualDeep(capable.schema_reader, retained.schema_reader);
    report.schema_reader = capable.schema_reader;
    var repaired = try publisher.prepare(a, report, true, false);
    defer repaired.deinit(a);
    var repaired_plan = try store_report_baseline.Plan.init(a, &repaired);
    defer repaired_plan.deinit();
    try std.testing.expect(repaired_plan.request.cursor.sequence > plan.request.cursor.sequence);
    try applyTestBaseline(&store, a, repaired_plan.request);
    chunk = repaired_plan.request;
    chunk.action = .chunk;
    chunk.report = repaired_plan.chunks[0];
    try applyTestBaseline(&store, a, chunk);
    activate = repaired_plan.request;
    activate.action = .activate;
    try applyTestBaseline(&store, a, activate);
    try std.testing.expect((try store.reportBaselineProgress(21, repaired_plan.request)).activated);
    try std.testing.expectEqual(repaired_plan.request.cursor, (try store.reportCursor(21, 1)).?);
}

fn schemaReaderDecoderActivationValid(a: std.mem.Allocator, bytes: []const u8, incarnation: metadata_incarnation.MetadataClusterIncarnation) !bool {
    return schemaReaderDecoderActivationValidAt(a, bytes, incarnation, topology_protocol.schema_reader_floor_version);
}

fn schemaReaderDecoderActivationValidAt(a: std.mem.Allocator, bytes: []const u8, incarnation: metadata_incarnation.MetadataClusterIncarnation, required: u16) !bool {
    if (bytes.len > topology_protocol.max_activation_bytes) return error.InvalidCatalogRecord;
    var parsed = try std.json.parseFromSlice(topology_protocol.Activation, a, bytes, .{});
    defer parsed.deinit();
    const activation = parsed.value;
    return activation.version >= required and activation.version <= topology_protocol.current_version and
        activation.member_count != 0 and !std.mem.allEqual(u8, &activation.membership_fingerprint, 0) and
        std.meta.eql(activation.incarnation, incarnation);
}

fn readerFloorActivationForTest(a: std.mem.Allocator) ![]u8 {
    return std.json.Stringify.valueAlloc(a, topology_protocol.Activation{
        .version = topology_protocol.schema_reader_floor_version,
        .incarnation = "0123456789abcdef0123456789abcdef".*,
        .member_count = 2,
        .membership_fingerprint = @splat(7),
    }, .{});
}

fn decodeMetadataIncarnationRecord(encoded: []const u8) !MetadataIncarnationRecord {
    const incarnation_len = @sizeOf(metadata_incarnation.MetadataClusterIncarnation);
    if (encoded.len < incarnation_len) return error.InvalidMetadataIncarnation;

    var incarnation: metadata_incarnation.MetadataClusterIncarnation = undefined;
    @memcpy(&incarnation, encoded[0..incarnation_len]);
    if (!metadata_incarnation.isValid(incarnation)) return error.InvalidMetadataIncarnation;
    if (encoded.len == incarnation_len) return .{ .incarnation = incarnation };

    const minimum_extension_len = metadata_incarnation_extension_magic.len + @sizeOf(u16) + @sizeOf(u16);
    if (encoded.len < incarnation_len + minimum_extension_len or
        !std.mem.eql(
            u8,
            encoded[incarnation_len..][0..metadata_incarnation_extension_magic.len],
            metadata_incarnation_extension_magic,
        ))
    {
        return error.InvalidMetadataIncarnation;
    }
    var pos: usize = incarnation_len + metadata_incarnation_extension_magic.len;
    const extension_version = std.mem.readInt(u16, encoded[pos..][0..@sizeOf(u16)], .little);
    pos += @sizeOf(u16);
    if (extension_version != metadata_incarnation_extension_runtime_status_version and
        extension_version != metadata_incarnation_extension_version and
        extension_version != metadata_incarnation_extension_relational_topology_version and
        extension_version != metadata_incarnation_extension_schema_reader_version) return error.InvalidMetadataIncarnation;
    const trailing_len: usize = if (extension_version >= metadata_incarnation_extension_schema_reader_version)
        2 * @sizeOf(u16) + 2 * @sizeOf(u32)
    else if (extension_version >= metadata_incarnation_extension_relational_topology_version)
        2 * @sizeOf(u16)
    else if (extension_version >= metadata_incarnation_extension_version)
        @sizeOf(u16)
    else
        0;
    const expected_len = incarnation_len + minimum_extension_len + trailing_len;
    if (encoded.len != expected_len) return error.InvalidMetadataIncarnation;
    const runtime_status_record_version = std.mem.readInt(u16, encoded[pos..][0..@sizeOf(u16)], .little);
    pos += @sizeOf(u16);
    if (runtime_status_record_version != 0 and
        !runtime_status_protocol.isSupported(runtime_status_record_version))
    {
        return error.InvalidMetadataIncarnation;
    }
    const dense_native_storage_protocol_activated_version = if (extension_version >= metadata_incarnation_extension_version)
        std.mem.readInt(u16, encoded[pos..][0..@sizeOf(u16)], .little)
    else
        0;
    if (dense_native_storage_protocol_activated_version >
        metadata_table_manager.dense_native_storage_protocol_version) return error.InvalidMetadataIncarnation;
    const relational_topology_protocol_activated_version = if (extension_version >= metadata_incarnation_extension_relational_topology_version)
        std.mem.readInt(u16, encoded[pos + @sizeOf(u16) ..][0..@sizeOf(u16)], .little)
    else
        0;
    if (relational_topology_protocol_activated_version > metadata_table_manager.relational_topology_protocol_version) return error.InvalidMetadataIncarnation;
    const schema_reader_floor: metadata_table_manager.SchemaReaderFloor = if (extension_version >= metadata_incarnation_extension_schema_reader_version)
        .{
            .semantic_version = std.mem.readInt(u32, encoded[pos + 2 * @sizeOf(u16) ..][0..4], .little),
            .encoding_version = std.mem.readInt(u32, encoded[pos + 2 * @sizeOf(u16) + 4 ..][0..4], .little),
        }
    else
        .{};
    if (!schema_reader_floor.valid() or (extension_version == metadata_incarnation_extension_schema_reader_version and !schema_reader_floor.active())) return error.InvalidMetadataIncarnation;
    return .{
        .incarnation = incarnation,
        .runtime_status_record_version = runtime_status_record_version,
        .dense_native_storage_protocol_activated_version = dense_native_storage_protocol_activated_version,
        .relational_topology_protocol_activated_version = relational_topology_protocol_activated_version,
        .schema_reader_floor = schema_reader_floor,
    };
}

fn writeMetadataIncarnationRecordTxn(
    txn: *docstore.DocStore.Txn,
    group_id: u64,
    record: MetadataIncarnationRecord,
) !void {
    if (!record.schema_reader_floor.valid()) return error.InvalidMetadataIncarnation;
    var key_buf: [160]u8 = undefined;
    const key = try metadataIncarnationKeyForGroup(&key_buf, group_id);
    const incarnation_len = @sizeOf(metadata_incarnation.MetadataClusterIncarnation);
    const encoded_len = incarnation_len + metadata_incarnation_extension_magic.len +
        @sizeOf(u16) + @sizeOf(u16) + @sizeOf(u16) + @sizeOf(u16) + 2 * @sizeOf(u32);
    var encoded: [encoded_len]u8 = undefined;
    @memcpy(encoded[0..incarnation_len], &record.incarnation);
    var pos: usize = incarnation_len;
    @memcpy(encoded[pos..][0..metadata_incarnation_extension_magic.len], metadata_incarnation_extension_magic);
    pos += metadata_incarnation_extension_magic.len;
    const has_topology_floor = record.relational_topology_protocol_activated_version != 0;
    const has_reader_floor = record.schema_reader_floor.active();
    std.mem.writeInt(u16, encoded[pos..][0..@sizeOf(u16)], if (has_reader_floor) metadata_incarnation_extension_schema_reader_version else if (has_topology_floor) metadata_incarnation_extension_relational_topology_version else metadata_incarnation_extension_version, .little);
    pos += @sizeOf(u16);
    std.mem.writeInt(u16, encoded[pos..][0..@sizeOf(u16)], record.runtime_status_record_version, .little);
    pos += @sizeOf(u16);
    std.mem.writeInt(
        u16,
        encoded[pos..][0..@sizeOf(u16)],
        record.dense_native_storage_protocol_activated_version,
        .little,
    );
    pos += @sizeOf(u16);
    if (has_topology_floor or has_reader_floor) {
        std.mem.writeInt(u16, encoded[pos..][0..@sizeOf(u16)], record.relational_topology_protocol_activated_version, .little);
        pos += @sizeOf(u16);
    }
    if (has_reader_floor) {
        std.mem.writeInt(u32, encoded[pos..][0..4], record.schema_reader_floor.semantic_version, .little);
        pos += 4;
        std.mem.writeInt(u32, encoded[pos..][0..4], record.schema_reader_floor.encoding_version, .little);
        pos += 4;
    }
    try txn.put(key, encoded[0..pos]);
}

test "metadata incarnation rejects unsupported runtime status activation profiles" {
    const incarnation: metadata_incarnation.MetadataClusterIncarnation = "0123456789abcdef0123456789abcdef".*;
    const incarnation_len = @sizeOf(metadata_incarnation.MetadataClusterIncarnation);
    const encoded_len = incarnation_len + metadata_incarnation_extension_magic.len + @sizeOf(u16) + @sizeOf(u16);

    inline for ([_]u16{ 13, 14, 18 }) |unsupported_version| {
        var encoded: [encoded_len]u8 = undefined;
        @memcpy(encoded[0..incarnation_len], &incarnation);
        var pos: usize = incarnation_len;
        @memcpy(encoded[pos..][0..metadata_incarnation_extension_magic.len], metadata_incarnation_extension_magic);
        pos += metadata_incarnation_extension_magic.len;
        std.mem.writeInt(u16, encoded[pos..][0..@sizeOf(u16)], metadata_incarnation_extension_version, .little);
        pos += @sizeOf(u16);
        std.mem.writeInt(u16, encoded[pos..][0..@sizeOf(u16)], unsupported_version, .little);

        try std.testing.expectError(
            error.InvalidMetadataIncarnation,
            decodeMetadataIncarnationRecord(&encoded),
        );
    }
}

fn activateRuntimeStatusProtocolTxn(
    txn: *docstore.DocStore.Txn,
    group_id: u64,
    target_version: u16,
) !void {
    var key_buf: [160]u8 = undefined;
    const key = try metadataIncarnationKeyForGroup(&key_buf, group_id);
    const existing = txn.get(key) catch |err| switch (err) {
        // Production admission requires an incarnation before the current profile can be
        // proposed. Preserve the historical state-machine behavior for direct
        // test/embedding callers that apply a store before initialization.
        error.NotFound => return,
        else => return err,
    };
    var decoded = try decodeMetadataIncarnationRecord(existing);
    if (!runtime_status_protocol.isSupported(target_version))
        return error.InvalidMetadataTransitionEncoding;
    if (decoded.runtime_status_record_version == target_version or
        runtime_status_protocol.profileSatisfies(decoded.runtime_status_record_version, target_version)) return;

    decoded.runtime_status_record_version = target_version;
    try writeMetadataIncarnationRecordTxn(txn, group_id, decoded);
}

/// Atomically admits a store against the durable dense-native capability
/// floor and activates that floor when `incoming` completes a fully capable
/// table-serving set. Returning false makes a stale, already-committed legacy
/// registration a deterministic no-op instead of reopening an unsafe rollout
/// window between service-side validation and Raft application.
fn admitDenseNativeStoreTxn(
    self: *RaftApplyStore,
    txn: *docstore.DocStore.Txn,
    group_id: u64,
    incoming: metadata.StoreRecord,
) !bool {
    var incarnation_key_buf: [160]u8 = undefined;
    const incarnation_key = try metadataIncarnationKeyForGroup(&incarnation_key_buf, group_id);
    const encoded_incarnation = txn.get(incarnation_key) catch |err| switch (err) {
        // Preserve direct state-machine test/embedding behavior before cluster
        // initialization. Production registration initializes this first.
        error.NotFound => return true,
        else => return err,
    };
    var incarnation_record = try decodeMetadataIncarnationRecord(encoded_incarnation);
    const incoming_serves_tables = metadata_table_manager.storeServesTableData(incoming.role);
    const incoming_capable = metadata_table_manager.denseNativeStorageProtocolSupported(
        incoming.reporter_incarnation,
        incoming.dense_native_storage_protocol_version,
    );
    if (incarnation_record.dense_native_storage_protocol_activated_version >=
        metadata_table_manager.dense_native_storage_protocol_version)
    {
        return !incoming_serves_tables or incoming_capable;
    }
    if (!incoming_serves_tables or !incoming_capable) return true;

    var prefix_buf: [128]u8 = undefined;
    const prefix = try storePrefixForGroup(&prefix_buf, group_id);
    var cur = try txn.openCursor();
    defer cur.close();
    var entry = try cur.seekAtOrAfter(prefix);
    while (entry) |kv| : (entry = try cur.next()) {
        if (!std.mem.startsWith(u8, kv.key, prefix)) break;
        const store = try RaftApplyStore.decodeStoredHeader(self.alloc, kv.value);
        defer metadata_table_manager.freeStore(self.alloc, store);
        if (store.store_id == incoming.store_id or
            !metadata_table_manager.storeServesTableData(store.role)) continue;
        if (!metadata_table_manager.denseNativeStorageProtocolSupported(
            store.reporter_incarnation,
            store.dense_native_storage_protocol_version,
        )) return true;
    }

    incarnation_record.dense_native_storage_protocol_activated_version =
        metadata_table_manager.dense_native_storage_protocol_version;
    try writeMetadataIncarnationRecordTxn(txn, group_id, incarnation_record);
    // Activation changes placement admissibility and must advance the durable
    // catalog revision. The paired store update is otherwise status-only and
    // deliberately does not invalidate catalog projections.
    self.notifyProjectionListeners(.{
        .kind = .metadata_incarnation,
        .metadata_group_id = group_id,
    });
    return true;
}

/// Independent schema-reader and topology floors share one fixed-size
/// incarnation read; neither capability implies the other.
fn admitSchemaAndTopologyStoreTxn(txn: *docstore.DocStore.Txn, group_id: u64, incoming: metadata.StoreRecord) !bool {
    if (!incoming.schema_reader.validForReporter(incoming.reporter_incarnation)) return false;
    if (incoming.relational_topology_protocol_version > metadata_table_manager.relational_topology_protocol_version or
        (incoming.relational_topology_protocol_version != 0 and incoming.reporter_incarnation == 0)) return false;
    if (!metadata_table_manager.storeServesTableData(incoming.role)) return true;
    var key_buf: [160]u8 = undefined;
    const raw = txn.get(try metadataIncarnationKeyForGroup(&key_buf, group_id)) catch |err| switch (err) {
        error.NotFound => return true,
        else => return err,
    };
    const incarnation = try decodeMetadataIncarnationRecord(raw);
    if (!incarnation.schema_reader_floor.admits(incoming.schema_reader, incoming.reporter_incarnation)) return false;
    const floor = incarnation.relational_topology_protocol_activated_version;
    return floor == 0 or (incoming.reporter_incarnation != 0 and incoming.relational_topology_protocol_version >= floor);
}

fn storeHasRuntimeRepairStatus(record: metadata.StoreRecord) bool {
    for (record.runtime_statuses) |runtime_status| {
        for (runtime_status.indexes) |index_status| {
            if (index_status.repair_status != null) return true;
        }
    }
    return false;
}

fn storeHasVectorProjectionStatus(record: metadata.StoreRecord) bool {
    for (record.runtime_statuses) |runtime_status| {
        for (runtime_status.indexes) |index_status| {
            if (index_status.dense_vector_projection_pending) return true;
        }
    }
    return false;
}

fn storeHasDenseNativeStorageStatus(record: metadata.StoreRecord) bool {
    for (record.runtime_statuses) |runtime_status| {
        for (runtime_status.indexes) |index_status| {
            if (index_status.dense_native_storage_phase != .legacy) return true;
        }
    }
    return false;
}

fn storeRuntimeStatusRecordVersion(record: metadata.StoreRecord) ?u16 {
    for (record.runtime_statuses) |status| {
        if (status.source_authority != null) return runtime_status_protocol.source_authority_record_version;
    }
    for (record.runtime_statuses) |status| {
        if (status.enrichment.output_counts_available or !std.meta.eql(status.enrichment.output_counts, @as(@TypeOf(status.enrichment.output_counts), .{}))) return runtime_status_protocol.media_output_record_version;
    }
    for (record.runtime_statuses) |status| {
        if (status.schema_epoch != 0) return runtime_status_protocol.schema_epoch_record_version;
    }
    if (record.relational_topology_protocol_version != 0 or record.schema_reader.known()) return runtime_status_protocol.framed_index_record_version;
    if (record.dense_native_storage_protocol_version != 0 or
        storeHasDenseNativeStorageStatus(record) or
        storeHasVectorProjectionStatus(record))
    {
        return runtime_status_protocol.framed_index_record_version;
    }
    for (record.runtime_statuses) |status| {
        if (metadata_table_manager.runtimeEnrichmentHasInferenceDiagnostics(status.enrichment))
            return runtime_status_protocol.inference_diagnostics_record_version;
    }
    if (metadata_table_manager.storeRequiresCurrentRuntimeStatusProfile(record))
        return runtime_status_protocol.previous_record_version;
    return null;
}

