/// Every released table-record encoding shares the identity prefix. Validate
/// the length-framed tail without allocating or interpreting its definition.
fn decodeTableIdentity(alloc: std.mem.Allocator, encoded: []const u8) !system_catalog.ResolvedTable {
    return decodeTableQueryProjection(alloc, encoded, false);
}

fn decodeTableQueryProjection(alloc: std.mem.Allocator, encoded: []const u8, include_definition: bool) !system_catalog.ResolvedTable {
    return decodeTableProjection(alloc, encoded, if (include_definition) .query else .identity);
}

const TableProjectionMode = enum { identity, schema, query };
const BorrowedTableProjection = struct {
    restore_pending: bool = false,
    table_id: u64,
    name: []const u8,
    query_definition: ?system_catalog.QueryDefinition,
    schema_reader_requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements = null,
    full_text_read_index: ?[]const u8 = null,
    fn clone(self: @This(), alloc: std.mem.Allocator) !system_catalog.ResolvedTable {
        return (system_catalog.ResolvedTable{ .table_id = self.table_id, .name = self.name, .query_definition = self.query_definition }).clone(alloc);
    }
};
fn decodeTableProjection(alloc: std.mem.Allocator, encoded: []const u8, mode: TableProjectionMode) !system_catalog.ResolvedTable {
    return (try borrowTableProjection(encoded, mode)).clone(alloc);
}

/// The complete framing is validated, but every slice retains the encoded
/// record's lifetime. Hashing pinned source rows needs no copies or allocator.
fn borrowTableProjection(encoded: []const u8, mode: TableProjectionMode) !BorrowedTableProjection {
    var pos: usize = 0;
    const table_id = try readInt(encoded, &pos, u64);
    _ = try readInt(encoded, &pos, u16); // replicas
    _ = try readInt(encoded, &pos, u32); // minimum ranges
    const name_len = try readInt(encoded, &pos, u32);
    if (name_len > encoded.len - pos) return error.InvalidMetadataTransitionEncoding;
    const name = encoded[pos..][0..name_len];
    pos += name_len;
    var fields: [8][]const u8 = undefined;
    var count: usize = 0;
    var storage: @import("antfly_local_sources").common_table_storage.Settings = .{};
    var reader_requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements = null;
    var full_text_read_index: ?[]const u8 = null;
    var lake_index_catalog_json: []const u8 = "";
    while (pos < encoded.len and count < fields.len) : (count += 1) {
        const length = try readInt(encoded, &pos, u32);
        if (length > encoded.len - pos) return error.InvalidMetadataTransitionEncoding;
        fields[count] = encoded[pos..][0..length];
        pos += length;
    }
    if (count == fields.len) {
        if (encoded.len - pos >= 4 and std.mem.readInt(u32, encoded[pos..][0..4], .little) == 0x31524941) {
            pos += 4;
            const length = try readInt(encoded, &pos, u32);
            if (length > encoded.len - pos) return error.InvalidMetadataTransitionEncoding;
            pos += length;
        }
        lake_index_catalog_json = try readLakeIndexCatalogExtension(encoded, &pos);
        const extension = try readTableStorageExtension(encoded, &pos);
        storage = extension.storage;
        reader_requirements = extension.schema_reader_requirements;
        full_text_read_index = extension.full_text_read_index;
    }
    // Legacy, read-schema, and restore-intent records respectively. Borrow all
    // framed fields to validate the encoding, but copy only query-owned data.
    if (count != 5 and count != 6 and count != 8) return error.InvalidMetadataTransitionEncoding;
    return .{ .restore_pending = count == 8 and fields[6].len != 0, .table_id = table_id, .name = name, .schema_reader_requirements = reader_requirements, .full_text_read_index = full_text_read_index, .query_definition = if (mode != .identity) system_catalog.QueryDefinition{
        .full_text_read_index = if (mode == .query) full_text_read_index else null,
        .table_id = table_id,
        .storage_engine = storage.engine,
        .schema_json = fields[1],
        .read_schema_json = if (mode == .schema or count == 5) "" else fields[2],
        .indexes_json = if (mode == .schema) "" else fields[if (count == 5) 2 else 3],
        .lake_index_catalog_json = if (mode == .query) lake_index_catalog_json else "",
    } else null };
}

