fn appendRuntimeIndexStatusRecord(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    record: metadata.RuntimeIndexStatusReport,
    version: u16,
) !void {
    if (!runtime_status_protocol.isNegotiable(version))
        return error.InvalidMetadataTransitionEncoding;
    if (version >= runtime_status_protocol.framed_index_status_record_version) {
        var payload = std.ArrayListUnmanaged(u8).empty;
        defer payload.deinit(alloc);
        try appendRuntimeIndexStatusRecordBody(alloc, &payload, record, version);
        try appendInt(alloc, out, u32, std.math.cast(u32, payload.items.len) orelse
            return error.MetadataTransitionEncodingTooLarge);
        try out.appendSlice(alloc, payload.items);
        return;
    }
    try appendRuntimeIndexStatusRecordBody(alloc, out, record, version);
}

fn appendRuntimeIndexStatusRecordBody(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    record: metadata.RuntimeIndexStatusReport,
    version: u16,
) !void {
    try appendRequiredString(alloc, out, record.name);
    try appendRequiredString(alloc, out, record.kind);
    try appendInt(alloc, out, u64, record.doc_count);
    try appendInt(alloc, out, u64, record.term_count);
    try appendInt(alloc, out, u64, record.edge_count);
    try appendInt(alloc, out, u64, record.node_count);
    try appendInt(alloc, out, u64, record.root_node);
    if (version >= 5) {
        try appendInt(alloc, out, u64, record.coverage_produced_count);
        try appendInt(alloc, out, u64, record.coverage_skipped_count);
        try appendInt(alloc, out, u64, record.coverage_terminal_failed_count);
    }
    if (version >= 7) try appendInt(alloc, out, u64, record.coverage_generation);
    if (version >= 6) try appendInt(alloc, out, u64, record.coverage_config_hash);
    if (version >= 7) try out.append(alloc, if (record.coverage_identity_ready) 1 else 0);
    if (version >= 6) try out.append(alloc, if (record.coverage_summary_ready) 1 else 0);
    try out.append(alloc, if (record.backfill_active) 1 else 0);
    try appendInt(alloc, out, u16, record.backfill_progress_millis);
    try appendInt(alloc, out, u64, record.replay_applied_sequence);
    try appendInt(alloc, out, u64, record.replay_target_sequence);
    try out.append(alloc, if (record.replay_catch_up_required) 1 else 0);
    if (version >= 11) try appendOptionalString(alloc, out, record.load_error);
    if (runtime_status_protocol.profileSatisfies(
        version,
        runtime_status_protocol.positional_record_version,
    )) {
        // V15 is one atomic profile: safety-critical repair state and
        // publication target, and per-source replay state must never be
        // projected independently.
        try appendInt(alloc, out, u64, record.publication_target_count);
        try out.append(alloc, if (record.publication_target_ready) 1 else 0);
        try out.append(alloc, if (record.serving_snapshot_ready) 1 else 0);
        if ((record.repair_status != null) != (record.lifecycle_work_class == .repair))
            return error.InvalidMetadataTransitionEncoding;
        try out.append(alloc, @backingInt(record.lifecycle_work_class));
        try out.append(alloc, if (record.repair_status) |status| @backingInt(status) else 0);
        try out.append(
            alloc,
            if (record.repair_status != null and record.repair_active_generation_serviceable) 1 else 0,
        );
        try appendInt(alloc, out, u16, @intCast(record.source_replay.len));
        for (record.source_replay) |source| {
            try appendRequiredString(alloc, out, source.artifact_name);
            try appendInt(alloc, out, u64, source.published_sequence);
            try appendInt(alloc, out, u64, source.target_sequence);
            try out.append(alloc, if (source.failed) 1 else 0);
        }
    }
    if (version >= runtime_status_protocol.vector_projection_record_version) {
        try out.append(alloc, if (record.dense_vector_projection_pending) 1 else 0);
    }
    if (version >= runtime_status_protocol.dense_native_storage_record_version) {
        try out.append(alloc, @backingInt(record.dense_native_storage_phase));
    }
    if (version >= runtime_status_protocol.framed_index_status_record_version) {
        // Optional field 1: graph counts are physical upper bounds while
        // ownership retirement is pending. Old readers skip the extension.
        const producer_extension_len: u32 = if (record.source_replay.len == 0) 0 else @intCast(8 + record.source_replay.len);
        try appendInt(alloc, out, u32, (if (record.graph_counts_pending) @as(u32, 7) else 0) + producer_extension_len);
        if (record.graph_counts_pending) {
            try appendInt(alloc, out, u16, 1);
            try appendInt(alloc, out, u32, 1);
            try out.append(alloc, 1);
        }
        if (record.source_replay.len != 0) {
            // Field 2: producer closure for each configured source, in the
            // same order as the positional source records. Missing evidence
            // from older writers remains pending in current readers.
            try appendInt(alloc, out, u16, 2);
            try appendInt(alloc, out, u32, @intCast(2 + record.source_replay.len));
            try appendInt(alloc, out, u16, @intCast(record.source_replay.len));
            for (record.source_replay) |source| try out.append(alloc, @intFromBool(source.producer_complete));
        }
    }
}

fn readRuntimeIndexStatusRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
    version: u16,
) !metadata.RuntimeIndexStatusReport {
    if (!runtime_status_protocol.isSupported(version))
        return error.InvalidMetadataTransitionEncoding;
    if (version >= runtime_status_protocol.framed_index_status_record_version) {
        const record_len = try readInt(encoded, pos, u32);
        const end = std.math.add(usize, pos.*, record_len) catch
            return error.InvalidMetadataTransitionEncoding;
        if (end > encoded.len) return error.InvalidMetadataTransitionEncoding;
        var body_pos = pos.*;
        const record = try readRuntimeIndexStatusRecordBody(alloc, encoded[0..end], &body_pos, version);
        if (body_pos != end) {
            metadata_table_manager.freeRuntimeIndexStatusReport(alloc, record);
            return error.InvalidMetadataTransitionEncoding;
        }
        pos.* = end;
        return record;
    }
    return try readRuntimeIndexStatusRecordBody(alloc, encoded, pos, version);
}

fn readRuntimeIndexStatusRecordBody(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
    version: u16,
) !metadata.RuntimeIndexStatusReport {
    const name = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(name);
    const kind = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(kind);
    const doc_count = try readInt(encoded, pos, u64);
    const term_count = try readInt(encoded, pos, u64);
    const edge_count = try readInt(encoded, pos, u64);
    const node_count = try readInt(encoded, pos, u64);
    const root_node = try readInt(encoded, pos, u64);
    const coverage_produced_count = try readInt(encoded, pos, u64);
    const coverage_skipped_count = try readInt(encoded, pos, u64);
    const coverage_terminal_failed_count = try readInt(encoded, pos, u64);
    const coverage_generation = try readInt(encoded, pos, u64);
    const coverage_config_hash = try readInt(encoded, pos, u64);
    if (pos.* + 2 > encoded.len) return error.InvalidMetadataTransitionEncoding;
    const coverage_identity_ready = encoded[pos.*] != 0;
    pos.* += 1;
    const coverage_summary_ready = encoded[pos.*] != 0;
    pos.* += 1;
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const backfill_active = encoded[pos.*] != 0;
    pos.* += 1;
    const backfill_progress_millis = try readInt(encoded, pos, u16);
    const replay_applied_sequence = try readInt(encoded, pos, u64);
    const replay_target_sequence = try readInt(encoded, pos, u64);
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const replay_catch_up_required = encoded[pos.*] != 0;
    pos.* += 1;
    const load_error = try readOptionalString(alloc, encoded, pos);
    errdefer if (load_error) |value| alloc.free(value);
    const has_positional_profile = runtime_status_protocol.profileSatisfies(
        version,
        runtime_status_protocol.positional_record_version,
    );
    const publication_target_count = if (has_positional_profile)
        try readInt(encoded, pos, u64)
    else
        0;
    const publication_target_ready = if (has_positional_profile) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const value = encoded[pos.*];
        pos.* += 1;
        if (value > 1) return error.InvalidMetadataTransitionEncoding;
        break :blk value == 1;
    } else false;
    const serving_snapshot_ready = if (has_positional_profile) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const value = encoded[pos.*];
        pos.* += 1;
        if (value > 1) return error.InvalidMetadataTransitionEncoding;
        break :blk value == 1;
    } else false;
    const lifecycle_work_class: metadata.IndexLifecycleWorkClass = if (has_positional_profile) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const tag = encoded[pos.*];
        pos.* += 1;
        break :blk switch (tag) {
            @backingInt(metadata.IndexLifecycleWorkClass.none) => .none,
            @backingInt(metadata.IndexLifecycleWorkClass.initial_build) => .initial_build,
            @backingInt(metadata.IndexLifecycleWorkClass.repair) => .repair,
            else => return error.InvalidMetadataTransitionEncoding,
        };
    } else .none;
    const repair_status: ?metadata.IndexRepairStatus = if (has_positional_profile) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const tag = encoded[pos.*];
        pos.* += 1;
        break :blk switch (tag) {
            0 => null,
            @backingInt(metadata.IndexRepairStatus.rebuilding) => .rebuilding,
            @backingInt(metadata.IndexRepairStatus.waiting) => .waiting,
            @backingInt(metadata.IndexRepairStatus.paused) => .paused,
            @backingInt(metadata.IndexRepairStatus.failed) => .failed,
            else => return error.InvalidMetadataTransitionEncoding,
        };
    } else null;
    if ((repair_status != null) != (lifecycle_work_class == .repair))
        return error.InvalidMetadataTransitionEncoding;
    const repair_active_generation_serviceable = if (has_positional_profile) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const value = encoded[pos.*];
        pos.* += 1;
        if (value > 1 or (value == 1 and repair_status == null)) return error.InvalidMetadataTransitionEncoding;
        break :blk value == 1;
    } else false;
    const source_replay_count = if (has_positional_profile)
        try readInt(encoded, pos, u16)
    else
        0;
    const source_replay = try alloc.alloc(metadata.RuntimeIndexSourceReplayStatusReport, source_replay_count);
    var source_count: usize = 0;
    errdefer {
        for (source_replay[0..source_count]) |source| alloc.free(source.artifact_name);
        if (source_replay.len > 0) alloc.free(source_replay);
    }
    while (source_count < source_replay_count) : (source_count += 1) {
        const artifact_name = try readRequiredString(alloc, encoded, pos);
        errdefer alloc.free(artifact_name);
        const published_sequence = try readInt(encoded, pos, u64);
        const target_sequence = try readInt(encoded, pos, u64);
        const failed = if (has_positional_profile) blk: {
            if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
            const value = encoded[pos.*];
            pos.* += 1;
            if (value > 1) return error.InvalidMetadataTransitionEncoding;
            break :blk value == 1;
        } else false;
        source_replay[source_count] = .{
            .artifact_name = artifact_name,
            .published_sequence = published_sequence,
            .target_sequence = target_sequence,
            .failed = failed,
        };
    }
    const dense_vector_projection_pending = if (version >= runtime_status_protocol.vector_projection_record_version) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const value = encoded[pos.*];
        pos.* += 1;
        if (value > 1) return error.InvalidMetadataTransitionEncoding;
        break :blk value == 1;
    } else false;
    const dense_native_storage_phase: metadata.DenseNativeStoragePhase = if (version >= runtime_status_protocol.dense_native_storage_record_version) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const value = encoded[pos.*];
        pos.* += 1;
        break :blk std.enums.fromInt(metadata.DenseNativeStoragePhase, value) orelse
            return error.InvalidMetadataTransitionEncoding;
    } else .legacy;
    var graph_counts_pending = false;
    if (version >= runtime_status_protocol.framed_index_status_record_version) {
        const extensions_len = try readInt(encoded, pos, u32);
        const extensions_end = std.math.add(usize, pos.*, extensions_len) catch
            return error.InvalidMetadataTransitionEncoding;
        if (extensions_end > encoded.len) return error.InvalidMetadataTransitionEncoding;
        var seen = std.AutoHashMapUnmanaged(u16, void).empty;
        defer seen.deinit(alloc);
        while (pos.* < extensions_end) {
            const field_id = try readInt(encoded[0..extensions_end], pos, u16);
            const field_len = try readInt(encoded[0..extensions_end], pos, u32);
            const field_end = std.math.add(usize, pos.*, field_len) catch
                return error.InvalidMetadataTransitionEncoding;
            if (field_id == 0 or field_end > extensions_end or seen.contains(field_id))
                return error.InvalidMetadataTransitionEncoding;
            try seen.put(alloc, field_id, {});
            if (field_id == 1) {
                if (field_len != 1 or encoded[pos.*] > 1) return error.InvalidMetadataTransitionEncoding;
                graph_counts_pending = encoded[pos.*] == 1;
            }
            if (field_id == 2) {
                const producer_count = try readInt(encoded[0..field_end], pos, u16);
                if (producer_count != source_replay.len or field_len != 2 + producer_count) return error.InvalidMetadataTransitionEncoding;
                for (source_replay) |*source| {
                    if (encoded[pos.*] > 1) return error.InvalidMetadataTransitionEncoding;
                    source.producer_complete = encoded[pos.*] == 1;
                    pos.* += 1;
                }
            }
            pos.* = field_end;
        }
    }
    return .{
        .name = name,
        .kind = kind,
        .load_error = load_error,
        .doc_count = doc_count,
        .term_count = term_count,
        .edge_count = edge_count,
        .graph_counts_pending = graph_counts_pending,
        .node_count = node_count,
        .root_node = root_node,
        .publication_target_count = publication_target_count,
        .publication_target_ready = publication_target_ready,
        .serving_snapshot_ready = serving_snapshot_ready,
        .coverage_produced_count = coverage_produced_count,
        .coverage_skipped_count = coverage_skipped_count,
        .coverage_terminal_failed_count = coverage_terminal_failed_count,
        .coverage_generation = coverage_generation,
        .coverage_config_hash = coverage_config_hash,
        .coverage_identity_ready = coverage_identity_ready,
        .coverage_summary_ready = coverage_summary_ready,
        .backfill_active = backfill_active,
        .backfill_progress_millis = backfill_progress_millis,
        .replay_applied_sequence = replay_applied_sequence,
        .replay_target_sequence = replay_target_sequence,
        .replay_catch_up_required = replay_catch_up_required,
        .dense_vector_projection_pending = dense_vector_projection_pending,
        .dense_native_storage_phase = dense_native_storage_phase,
        .embedding_activity = .{},
        .source_replay = source_replay,
        .lifecycle_work_class = lifecycle_work_class,
        .repair_status = repair_status,
        .repair_active_generation_serviceable = repair_active_generation_serviceable,
    };
}

fn appendGroupStatusRecord(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    record: metadata.GroupStatusReport,
) !void {
    try appendInt(alloc, out, u16, group_status_record_version);
    try appendInt(alloc, out, u64, record.group_id);
    try appendInt(alloc, out, u64, record.relocation_generation);
    try appendInt(alloc, out, u64, record.raft_applied_index);
    try appendInt(alloc, out, u64, record.raft_term);
    try appendInt(alloc, out, u64, record.raft_membership_index);
    try appendInt(alloc, out, u64, record.doc_count);
    try appendInt(alloc, out, u64, record.disk_bytes);
    try out.append(alloc, if (record.disk_bytes_known) 1 else 0);
    try out.append(alloc, if (record.empty) 1 else 0);
    try appendInt(alloc, out, u32, 0);
    try appendInt(alloc, out, u64, record.updated_at_millis);
    try out.append(alloc, if (record.local_leader) 1 else 0);
    try appendInt(alloc, out, u64, record.created_at_millis);
    try out.append(alloc, if (record.transition_pending) 1 else 0);
    try out.append(alloc, if (record.replay_required) 1 else 0);
    try out.append(alloc, if (record.replay_caught_up) 1 else 0);
    try out.append(alloc, if (record.cutover_ready) 1 else 0);
    try out.append(alloc, if (record.reads_ready_after_cutover) 1 else 0);
    try out.append(alloc, if (record.local_voter) 1 else 0);
    try appendInt(alloc, out, u16, record.voter_count);
    try out.append(alloc, if (record.joint_consensus) 1 else 0);
    try out.append(alloc, if (record.voter_set_known) 1 else 0);
    try out.appendSlice(alloc, &record.voter_set_fingerprint);
}

fn readGroupStatusRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.GroupStatusReport {
    _ = alloc;
    const version = try readInt(encoded, pos, u16);
    if (version == 0 or version > group_status_record_version) return error.InvalidMetadataTransitionEncoding;
    const group_id = try readInt(encoded, pos, u64);
    const relocation_generation = if (version >= 2) try readInt(encoded, pos, u64) else 0;
    const raft_applied_index = if (version >= 2) try readInt(encoded, pos, u64) else 0;
    const raft_term = if (version >= 4) try readInt(encoded, pos, u64) else 0;
    const raft_membership_index = if (version >= 4) try readInt(encoded, pos, u64) else 0;
    const doc_count = try readInt(encoded, pos, u64);
    const disk_bytes = try readInt(encoded, pos, u64);
    const disk_bytes_known = if (version >= 3) blk: {
        if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const empty = encoded[pos.*] != 0;
    pos.* += 1;
    const median_key_len = try readInt(encoded, pos, u32);
    if (pos.* + median_key_len > encoded.len) return error.InvalidMetadataTransitionEncoding;
    pos.* += median_key_len;
    const updated_at_millis = if (pos.* < encoded.len) try readInt(encoded, pos, u64) else 0;
    const local_leader = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const created_at_millis = if (pos.* < encoded.len) try readInt(encoded, pos, u64) else 0;
    const transition_pending = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const replay_required = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const replay_caught_up = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const cutover_ready = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const reads_ready_after_cutover = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const local_voter = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    const voter_count = if (pos.* + @sizeOf(u16) <= encoded.len)
        try readInt(encoded, pos, u16)
    else
        0;
    const joint_consensus = if (pos.* < encoded.len) blk: {
        const value = encoded[pos.*] != 0;
        pos.* += 1;
        break :blk value;
    } else false;
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const voter_set_known = encoded[pos.*] != 0;
    pos.* += 1;
    if (pos.* + metadata_table_manager.voter_set_fingerprint_len > encoded.len) {
        return error.InvalidMetadataTransitionEncoding;
    }
    var voter_set_fingerprint: metadata_table_manager.VoterSetFingerprint = undefined;
    @memcpy(&voter_set_fingerprint, encoded[pos.* .. pos.* + metadata_table_manager.voter_set_fingerprint_len]);
    pos.* += metadata_table_manager.voter_set_fingerprint_len;
    return .{
        .group_id = group_id,
        .relocation_generation = relocation_generation,
        .raft_applied_index = raft_applied_index,
        .raft_term = raft_term,
        .raft_membership_index = raft_membership_index,
        .doc_count = doc_count,
        .disk_bytes = disk_bytes,
        .disk_bytes_known = disk_bytes_known,
        .empty = empty,
        .created_at_millis = created_at_millis,
        .updated_at_millis = updated_at_millis,
        .local_leader = local_leader,
        .local_voter = local_voter,
        .voter_count = voter_count,
        .voter_set_known = voter_set_known,
        .voter_set_fingerprint = voter_set_fingerprint,
        .joint_consensus = joint_consensus,
        .transition_pending = transition_pending,
        .replay_required = replay_required,
        .replay_caught_up = replay_caught_up,
        .cutover_ready = cutover_ready,
        .reads_ready_after_cutover = reads_ready_after_cutover,
    };
}

fn appendPlacementIntent(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    intent: raft_reconciler.PlacementIntent,
) !void {
    try appendInt(alloc, out, u64, intent.record.group_id);
    try appendInt(alloc, out, u64, intent.record.replica_id);
    try appendInt(alloc, out, u64, intent.record.local_node_id);
    try appendInt(alloc, out, u64, intent.record.metadata_version);
    try out.append(alloc, @backingInt(intent.record.bootstrap_mode));
    try appendInt(alloc, out, u32, @intCast(intent.peer_node_ids.len));
    for (intent.peer_node_ids) |node_id| try appendInt(alloc, out, u64, node_id);
    try appendInt(alloc, out, u64, intent.store_id);
    // Keep emitting the established snapshot source shape during rolling
    // upgrades. The isolated v2 URI namespace is the durable protocol
    // discriminator and the transport already resolves `.unknown` from it;
    // duplicating that fact in a new un-negotiated tag would make an older
    // metadata voter unable to apply otherwise compatible entries.
    if (intent.record.initial_fk_root_generation != 0 and
        (intent.record.snapshot_bootstrap != null or intent.record.backup_restore_bootstrap != null))
        return error.InvalidMetadataTransitionEncoding;
    const source_tag: u8 = if (intent.record.initial_fk_root_generation != 0)
        4
    else if (intent.record.snapshot_bootstrap != null)
        1
    else if (intent.record.backup_restore_bootstrap != null)
        2
    else
        0;
    try out.append(alloc, source_tag);
    switch (source_tag) {
        4 => try appendInt(alloc, out, u64, intent.record.initial_fk_root_generation),
        1, 3 => {
            const snapshot = intent.record.snapshot_bootstrap.?;
            try appendInt(alloc, out, u64, snapshot.from_node_id);
            try appendInt(alloc, out, u64, snapshot.term);
            try appendInt(alloc, out, u32, @intCast(snapshot.snapshot_id.len));
            try out.appendSlice(alloc, snapshot.snapshot_id);
            try appendInt(alloc, out, u32, @intCast(snapshot.uri.len));
            try out.appendSlice(alloc, snapshot.uri);
            // Tag 3 remains decoder-only so entries created by development
            // versions are recoverable, but production proposals stay on the
            // rolling-compatible tag 1 representation.
        },
        2 => {
            const backup = intent.record.backup_restore_bootstrap.?;
            try backup.validate();
            try appendInt(alloc, out, u32, @intCast(backup.backup_id.len));
            try out.appendSlice(alloc, backup.backup_id);
            try appendInt(alloc, out, u32, @intCast(backup.artifact_backup_id.len));
            try out.appendSlice(alloc, backup.artifact_backup_id);
            try appendInt(alloc, out, u32, @intCast(backup.location.len));
            try out.appendSlice(alloc, backup.location);
            try appendInt(alloc, out, u32, @intCast(backup.snapshot_path.len));
            try out.appendSlice(alloc, backup.snapshot_path);
            try appendInt(alloc, out, u32, @intCast(backup.connection.len));
            try out.appendSlice(alloc, backup.connection);
            try appendInt(alloc, out, u64, backup.artifact_size_bytes);
            try appendInt(alloc, out, u32, @intCast(backup.artifact_sha256.len));
            try out.appendSlice(alloc, backup.artifact_sha256);
        },
        else => {},
    }
    try out.append(alloc, @backingInt(intent.serving_state));
    try appendInt(alloc, out, u64, intent.relocation_generation);
    try appendInt(alloc, out, u64, intent.relocation_source_node_id);
    try appendInt(alloc, out, u64, intent.relocation_source_store_id);
    try appendInt(alloc, out, u64, intent.relocation_doc_count_watermark);
    try appendInt(alloc, out, u64, intent.relocation_disk_bytes_watermark);
    try appendInt(alloc, out, u64, intent.relocation_target_sequence);
    try appendInt(alloc, out, u64, intent.relocation_applied_sequence);
    if (intent.record.backup_restore_bootstrap) |backup| {
        if (backup.native_manifest_size_bytes != 0 or backup.native_manifest_sha256.len != 0 or backup.destination_table_name.len != 0) {
            // Appended after the legacy placement payload so older decoders
            // ignore it rather than misreading it as serving/relocation state.
            try appendInt(alloc, out, u64, backup.native_manifest_size_bytes);
            try appendRequiredString(alloc, out, backup.native_manifest_sha256);
            if (backup.destination_table_name.len != 0) {
                try appendRequiredString(alloc, out, backup.destination_table_name);
                try appendInt(alloc, out, u64, backup.destination_table_id);
                try appendInt(alloc, out, u64, backup.destination_shard_id);
                try appendInt(alloc, out, u64, backup.destination_range_id);
            }
        }
    }
}

const table_storage_metadata_magic: u32 = 0x31535441; // ATS1
const table_storage_metadata_version: u16 = 1;
const lake_index_catalog_magic: u32 = 0x31434c41; // ALC1
const max_lake_index_catalog_bytes: usize = 256 * 1024;

fn appendTableRecord(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    record: metadata.TableRecord,
) !void {
    try appendInt(alloc, out, u64, record.table_id);
    try appendInt(alloc, out, u16, record.desired_replica_count);
    try appendInt(alloc, out, u32, record.min_ranges);
    try appendInt(alloc, out, u32, @intCast(record.name.len));
    try out.appendSlice(alloc, record.name);
    try appendInt(alloc, out, u32, @intCast(record.description.len));
    try out.appendSlice(alloc, record.description);
    try appendInt(alloc, out, u32, @intCast(record.schema_json.len));
    try out.appendSlice(alloc, record.schema_json);
    try appendInt(alloc, out, u32, @intCast(record.read_schema_json.len));
    try out.appendSlice(alloc, record.read_schema_json);
    try appendInt(alloc, out, u32, @intCast(record.indexes_json.len));
    try out.appendSlice(alloc, record.indexes_json);
    try appendInt(alloc, out, u32, @intCast(record.replication_sources_json.len));
    try out.appendSlice(alloc, record.replication_sources_json);
    try appendInt(alloc, out, u32, @intCast(record.placement_role.len));
    try out.appendSlice(alloc, record.placement_role);
    try appendInt(alloc, out, u32, @intCast(record.restore_backup_id.len));
    try out.appendSlice(alloc, record.restore_backup_id);
    try appendInt(alloc, out, u32, @intCast(record.restore_location.len));
    try out.appendSlice(alloc, record.restore_location);
    if (record.relational_retirement_json.len != 0) {
        try appendInt(alloc, out, u32, 0x31524941);
        try appendRequiredString(alloc, out, record.relational_retirement_json);
    }
    if (record.lake_index_catalog_json.len != 0) {
        if (record.lake_index_catalog_json.len > max_lake_index_catalog_bytes) return error.InvalidMetadataTransitionEncoding;
        var validated = try @import("antfly_local_sources").metadata_lake_index_catalog.parse(alloc, record.lake_index_catalog_json);
        defer validated.deinit();
        try appendInt(alloc, out, u32, lake_index_catalog_magic);
        try appendRequiredString(alloc, out, record.lake_index_catalog_json);
    }
    if (record.requiresStorageMetadataExtension()) {
        try appendInt(alloc, out, u32, table_storage_metadata_magic);
        const version: u16 = if (record.full_text_read_index != null) 4 else if (record.schema_reader_requirements != null) 3 else if (record.storage.engine == .object) 2 else table_storage_metadata_version;
        try appendInt(alloc, out, u16, version);
        if (version >= 2)
            try out.append(alloc, if (record.storage.engine == .object) 1 else 0);
        if (record.storage.engine == .object) {
            try appendInt(alloc, out, u64, record.object_storage_generation);
            try out.appendSlice(alloc, &record.object_storage_identity);
        }
        try out.append(alloc, switch (record.storage.dense_embeddings) {
            .primary_lsm => 0,
            .vector_store => 1,
        });
        try out.append(alloc, if (record.storage_migration != null) 1 else 0);
        if (record.storage_migration) |migration| {
            try migration.request.validate();
            try appendInt(alloc, out, u16, @intCast(migration.request.job_id.len));
            try out.appendSlice(alloc, migration.request.job_id);
            try out.append(alloc, switch (migration.request.mode) {
                .offline => 0,
                .online => 1,
            });
            try appendInt(alloc, out, u64, migration.request.budget.batch_bytes);
            try appendInt(alloc, out, u32, migration.request.budget.batch_rows);
            try appendInt(alloc, out, u64, migration.request.budget.temporary_bytes);
            try appendInt(alloc, out, u64, migration.request.budget.disk_reserve_bytes);
        }
        if (version == 4) try out.append(alloc, @intFromBool(record.schema_reader_requirements != null));
        if (record.schema_reader_requirements) |requirements| {
            if (!requirements.valid()) return error.InvalidMetadataTransitionEncoding;
            try appendInt(alloc, out, u32, requirements.semantic_version);
            try appendInt(alloc, out, u32, requirements.encoding_version);
        }
        if (record.full_text_read_index) |index_name| {
            if (index_name.len == 0 or index_name.len > 1024 or std.mem.indexOfScalar(u8, index_name, 0) != null) return error.InvalidMetadataTransitionEncoding;
            try appendRequiredString(alloc, out, index_name);
        }
    }
}

fn appendFramedTableRecord(
