        .read_schema_json = read_schema_json,
        .indexes_json = indexes_json,
        .replication_sources_json = replication_sources_json,
        .placement_role = placement_role,
        .restore_backup_id = try alloc.dupe(u8, ""),
        .restore_location = try alloc.dupe(u8, ""),
        .desired_replica_count = desired_replica_count,
        .min_ranges = min_ranges,
    };
}

const BorrowedTableStorage = struct {
    full_text_read_index: ?[]const u8 = null,
    schema_reader_requirements: ?@import("antfly_local_sources").common_schema_readers.ReaderRequirements = null,
    object_storage_generation: u64 = 0,
    object_storage_identity: [32]u8 = @splat(0),
    storage: @import("antfly_local_sources").common_table_storage.Settings = .{},
    migration: ?@import("antfly_local_sources").common_vector_migration.Admission = null,
};

/// Shared strict extension decoder. Point projections validate the entire
/// framing without allocating unrelated schemas, retirement jobs or indexes.
fn readLakeIndexCatalogExtension(encoded: []const u8, pos: *usize) ![]const u8 {
    if (encoded.len - pos.* < 4 or std.mem.readInt(u32, encoded[pos.*..][0..4], .little) != lake_index_catalog_magic) return "";
    pos.* += 4;
    const length = try readInt(encoded, pos, u32);
    if (length == 0 or length > max_lake_index_catalog_bytes or length > encoded.len - pos.*) return error.InvalidMetadataTransitionEncoding;
    const result = encoded[pos.*..][0..length];
    pos.* += length;
    return result;
}

fn readTableStorageExtension(encoded: []const u8, pos: *usize) !BorrowedTableStorage {
    var result: BorrowedTableStorage = .{};
    if (pos.* == encoded.len) return result;
    if (try readInt(encoded, pos, u32) != table_storage_metadata_magic) return error.InvalidMetadataTransitionEncoding;
    const version = try readInt(encoded, pos, u16);
    if (version != table_storage_metadata_version and version != 2 and version != 3 and version != 4) return error.InvalidMetadataTransitionEncoding;
    if (version >= 2) {
        const engine = try readInt(encoded, pos, u8);
        if (engine > 1 or (version == 2 and engine != 1)) return error.InvalidMetadataTransitionEncoding;
        result.storage.engine = if (engine == 1) .object else .local;
    }
    if (result.storage.engine == .object) {
        result.object_storage_generation = try readInt(encoded, pos, u64);
        for (&result.object_storage_identity) |*byte| byte.* = try readInt(encoded, pos, u8);
    }
    result.storage.dense_embeddings = switch (try readInt(encoded, pos, u8)) {
        0 => .primary_lsm,
        1 => .vector_store,
        else => return error.InvalidMetadataTransitionEncoding,
    };
    switch (try readInt(encoded, pos, u8)) {
        0 => {},
        1 => {
            const job_len = try readInt(encoded, pos, u16);
            if (job_len == 0 or job_len > 128 or job_len > encoded.len - pos.*) return error.InvalidMetadataTransitionEncoding;
            const job_id = encoded[pos.*..][0..job_len];
            pos.* += job_len;
            const mode: @import("antfly_local_sources").common_vector_migration.Mode = switch (try readInt(encoded, pos, u8)) {
                0 => .offline,
                1 => .online,
                else => return error.InvalidMetadataTransitionEncoding,
            };
            result.migration = .{ .request = .{ .job_id = job_id, .mode = mode, .budget = .{
                .batch_bytes = try readInt(encoded, pos, u64),
                .batch_rows = try readInt(encoded, pos, u32),
                .temporary_bytes = try readInt(encoded, pos, u64),
                .disk_reserve_bytes = try readInt(encoded, pos, u64),
            } } };
            result.migration.?.request.validate() catch return error.InvalidMetadataTransitionEncoding;
        },
        else => return error.InvalidMetadataTransitionEncoding,
    }
    const has_requirements = if (version == 4) switch (try readInt(encoded, pos, u8)) {
        0 => false,
        1 => true,
        else => return error.InvalidMetadataTransitionEncoding,
    } else version == 3;
    if (has_requirements) {
        const requirements: @import("antfly_local_sources").common_schema_readers.ReaderRequirements = .{
            .semantic_version = try readInt(encoded, pos, u32),
            .encoding_version = try readInt(encoded, pos, u32),
        };
        if (!requirements.valid()) return error.InvalidMetadataTransitionEncoding;
        result.schema_reader_requirements = requirements;
    }
    if (version == 4) {
        const length = try readInt(encoded, pos, u32);
        if (length == 0 or length > 1024 or length > encoded.len - pos.*) return error.InvalidMetadataTransitionEncoding;
        const name = encoded[pos.*..][0..length];
        if (std.mem.indexOfScalar(u8, name, 0) != null) return error.InvalidMetadataTransitionEncoding;
        result.full_text_read_index = name;
        pos.* += length;
    }
    if (pos.* != encoded.len or (result.storage.engine == .local and result.storage.dense_embeddings == .primary_lsm and result.migration == null and result.schema_reader_requirements == null and result.full_text_read_index == null)) return error.InvalidMetadataTransitionEncoding;
    if (result.storage.engine == .object and (result.storage.dense_embeddings != .primary_lsm or result.migration != null)) return error.InvalidMetadataTransitionEncoding;
    return result;
}

fn readTableRecordWithRestoreIntent(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.TableRecord {
    const table_id = try readInt(encoded, pos, u64);
    const desired_replica_count = try readInt(encoded, pos, u16);
    const min_ranges = try readInt(encoded, pos, u32);
    const name = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(name);
    const description = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(description);
    const schema_json = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(schema_json);
    const read_schema_json = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(read_schema_json);
    const indexes_json = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(indexes_json);
    const replication_sources_json = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(replication_sources_json);
    const placement_role = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(placement_role);
    const restore_backup_id = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(restore_backup_id);
    const restore_location = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(restore_location);
    const relational_retirement_json = if (encoded.len - pos.* >= @sizeOf(u32) and std.mem.readInt(u32, encoded[pos.*..][0..4], .little) == 0x31524941) blk: {
        _ = try readInt(encoded, pos, u32);
        break :blk try readRequiredString(alloc, encoded, pos);
    } else try alloc.dupe(u8, "");
    errdefer alloc.free(relational_retirement_json);
    const lake_index_catalog_json = try alloc.dupe(u8, try readLakeIndexCatalogExtension(encoded, pos));
    errdefer alloc.free(lake_index_catalog_json);
    var extension = try readTableStorageExtension(encoded, pos);
    const full_text_read_index = if (extension.full_text_read_index) |index_name| try alloc.dupe(u8, index_name) else null;
    errdefer if (full_text_read_index) |index_name| alloc.free(index_name);
    if (extension.migration) |*migration| migration.request.job_id = try alloc.dupe(u8, migration.request.job_id);
    return .{
        .schema_reader_requirements = extension.schema_reader_requirements,
        .full_text_read_index = full_text_read_index,
        .storage = extension.storage,
        .object_storage_generation = extension.object_storage_generation,
        .object_storage_identity = extension.object_storage_identity,
        .storage_migration = extension.migration,
        .relational_retirement_json = relational_retirement_json,
        .lake_index_catalog_json = lake_index_catalog_json,
        .table_id = table_id,
        .name = name,
        .description = description,
        .schema_json = schema_json,
        .read_schema_json = read_schema_json,
        .indexes_json = indexes_json,
        .replication_sources_json = replication_sources_json,
        .placement_role = placement_role,
        .restore_backup_id = restore_backup_id,
        .restore_location = restore_location,
        .desired_replica_count = desired_replica_count,
        .min_ranges = min_ranges,
    };
}

fn readRequiredString(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) ![]u8 {
    const value_len = try readInt(encoded, pos, u32);
    if (pos.* + value_len > encoded.len) return error.InvalidMetadataTransitionEncoding;
    const value = try alloc.dupe(u8, encoded[pos.* .. pos.* + value_len]);
    pos.* += value_len;
    return value;
}

fn readRequiredStrings(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
    max_count: usize,
) ![]const []const u8 {
    const count = try readInt(encoded, pos, u32);
    if (count == 0 or count > max_count) return error.InvalidMetadataTransitionEncoding;
    const values = try alloc.alloc([]const u8, count);
    var initialized: usize = 0;
    errdefer {
        for (values[0..initialized]) |value| alloc.free(value);
        alloc.free(values);
    }
    for (values) |*value| {
        value.* = try readRequiredString(alloc, encoded, pos);
        initialized += 1;
    }
    return values;
}

fn readBackupCohortSeal(alloc: std.mem.Allocator, encoded: []const u8, pos: *usize) !?@import("antfly_local_sources").metadata_backup_cohort.SealReceipt {
    const tag = try readInt(encoded, pos, u8);
    if (tag == 0) return null;
    if (tag != 1) return error.InvalidMetadataTransitionEncoding;
    const bytes = try readRequiredString(alloc, encoded, pos);
    defer alloc.free(bytes);
    var parsed = try std.json.parseFromSlice(@import("antfly_local_sources").metadata_backup_cohort.SealReceipt, alloc, bytes, .{});
    defer parsed.deinit();
    return parsed.value;
}

fn readRelationMutationGuard(alloc: std.mem.Allocator, encoded: []const u8, pos: *usize) !system_catalog.RelationMutationGuard {
    const len = try readInt(encoded, pos, u32);
    // Four route names, one optional selected name, owner fields and JSON
    // escaping fit within 8 KiB. Guard validation bounds additive proofs.
    // Check before allocating or parsing, including hostile persisted frames.
    if (len == 0 or len > 8192 or len > encoded.len - pos.*) return error.InvalidMetadataTransitionEncoding;
    const json = encoded[pos.*..][0..len];
    pos.* += len;
    var parsed = try std.json.parseFromSlice(system_catalog.RelationMutationGuard, alloc, json, .{});
    defer parsed.deinit();
    return parsed.value.clone(alloc);
}

fn readJsonRecord(comptime T: type, alloc: std.mem.Allocator, encoded: []const u8, pos: *usize) !T {
    const json = try readRequiredString(alloc, encoded, pos);
    defer alloc.free(json);
    var value = try std.json.parseFromSliceLeaky(T, alloc, json, .{ .allocate = .alloc_always, .ignore_unknown_fields = true });
    errdefer deinitExtensionJsonRecord(T, alloc, &value);
    if (@hasDecl(T, "validate")) try value.validate();
    return value;
}

fn appendRequiredString(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    value: []const u8,
) !void {
    try appendInt(alloc, out, u32, @intCast(value.len));
    try out.appendSlice(alloc, value);
}

fn appendOptionalString(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    value: ?[]const u8,
) !void {
    const present = value orelse {
        try out.append(alloc, 0);
        return;
    };
    try out.append(alloc, 1);
    try appendRequiredString(alloc, out, present);
}

fn appendRestoreIntentIdentity(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(u8),
    identity: metadata.RestoreIntentIdentity,
) !void {
    try appendInt(alloc, out, u64, identity.group_id);
    try appendInt(alloc, out, u64, identity.table_id);
    try appendRequiredString(alloc, out, identity.backup_id);
    try appendRequiredString(alloc, out, identity.artifact_backup_id);
    try appendRequiredString(alloc, out, identity.location);
    try appendRequiredString(alloc, out, identity.snapshot_path);
    try appendRequiredString(alloc, out, identity.connection);
    try appendInt(alloc, out, u64, identity.artifact_size_bytes);
    try appendRequiredString(alloc, out, identity.artifact_sha256);
    if (identity.native_manifest_size_bytes != 0 or identity.native_manifest_sha256.len != 0) {
        try appendInt(alloc, out, u64, identity.native_manifest_size_bytes);
        try appendRequiredString(alloc, out, identity.native_manifest_sha256);
    }
}

fn readRestoreIntentIdentity(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.RestoreIntentIdentity {
    const group_id = try readInt(encoded, pos, u64);
    const table_id = try readInt(encoded, pos, u64);
    const backup_id = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(backup_id);
    const artifact_backup_id = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(artifact_backup_id);
    const location = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(location);
    const snapshot_path = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(snapshot_path);
    const connection = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(connection);
    const artifact_size_bytes = try readInt(encoded, pos, u64);
    const artifact_sha256 = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(artifact_sha256);
    const native_manifest_size_bytes = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const native_manifest_sha256 = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(native_manifest_sha256);
    return .{
        .group_id = group_id,
        .table_id = table_id,
        .backup_id = backup_id,
        .artifact_backup_id = artifact_backup_id,
        .location = location,
        .snapshot_path = snapshot_path,
        .connection = connection,
        .artifact_size_bytes = artifact_size_bytes,
        .artifact_sha256 = artifact_sha256,
        .native_manifest_size_bytes = native_manifest_size_bytes,
        .native_manifest_sha256 = native_manifest_sha256,
    };
}

fn appendJsonRecord(alloc: std.mem.Allocator, out: *std.ArrayListUnmanaged(u8), record: anytype) !void {
    const json = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(record, .{})});
    defer alloc.free(json);
    try appendRequiredString(alloc, out, json);
}

fn extensionLifecycleDeltaV1(delta: ExtensionLifecycleDelta) ExtensionLifecycleDeltaV1 {
    return .{
        .upsert_tables = delta.upsert_tables,
        .upsert_installed_extensions = delta.upsert_installed_extensions,
        .remove_installed_extensions = delta.remove_installed_extensions,
        .upsert_extension_members = delta.upsert_extension_members,
        .remove_extension_members = delta.remove_extension_members,
        .upsert_extension_dependencies = delta.upsert_extension_dependencies,
        .remove_extension_dependencies = delta.remove_extension_dependencies,
    };
}

fn extensionLifecycleDeltaFromV1(delta: ExtensionLifecycleDeltaV1) ExtensionLifecycleDelta {
    return .{
        .expected_tables = &.{},
        .upsert_tables = delta.upsert_tables,
        .upsert_installed_extensions = delta.upsert_installed_extensions,
        .remove_installed_extensions = delta.remove_installed_extensions,
        .upsert_extension_members = delta.upsert_extension_members,
        .remove_extension_members = delta.remove_extension_members,
        .upsert_extension_dependencies = delta.upsert_extension_dependencies,
        .remove_extension_dependencies = delta.remove_extension_dependencies,
    };
}

fn deinitExtensionJsonRecord(comptime T: type, alloc: std.mem.Allocator, value: *T) void {
    if (@hasDecl(T, "deinitOwned")) {
        value.deinitOwned(alloc);
    }
}

fn freeExtensionLifecycleDelta(alloc: std.mem.Allocator, delta: ExtensionLifecycleDelta) void {
    if (delta.expected_tables.len > 0) alloc.free(@constCast(delta.expected_tables));
    for (delta.upsert_tables) |record| metadata_table_manager.freeTable(alloc, record);
    if (delta.upsert_tables.len > 0) alloc.free(@constCast(delta.upsert_tables));
    for (delta.upsert_installed_extensions) |record| {
        var owned = record;
        owned.deinitOwned(alloc);
    }
    if (delta.upsert_installed_extensions.len > 0) alloc.free(@constCast(delta.upsert_installed_extensions));
    for (delta.remove_installed_extensions) |name| alloc.free(@constCast(name));
    if (delta.remove_installed_extensions.len > 0) alloc.free(@constCast(delta.remove_installed_extensions));
    for (delta.upsert_extension_members) |record| {
        var owned = record;
        owned.deinitOwned(alloc);
    }
    if (delta.upsert_extension_members.len > 0) alloc.free(@constCast(delta.upsert_extension_members));
    for (delta.remove_extension_members) |record| {
        alloc.free(@constCast(record.extension_name));
        alloc.free(@constCast(record.object_name));
    }
    if (delta.remove_extension_members.len > 0) alloc.free(@constCast(delta.remove_extension_members));
    for (delta.upsert_extension_dependencies) |record| {
        var owned = record;
        owned.deinitOwned(alloc);
    }
    if (delta.upsert_extension_dependencies.len > 0) alloc.free(@constCast(delta.upsert_extension_dependencies));
    for (delta.remove_extension_dependencies) |record| {
        alloc.free(@constCast(record.extension_name));
        alloc.free(@constCast(record.required_extension_name));
        alloc.free(@constCast(record.package_name));
    }
    if (delta.remove_extension_dependencies.len > 0) alloc.free(@constCast(delta.remove_extension_dependencies));
}

fn readRangeRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.RangeRecord {
    const group_id = try readInt(encoded, pos, u64);
    const table_id = try readInt(encoded, pos, u64);
    const start_len = try readInt(encoded, pos, u32);
    if (pos.* + start_len > encoded.len) return error.InvalidMetadataTransitionEncoding;
    const start_key = try alloc.dupe(u8, encoded[pos.* .. pos.* + start_len]);
    errdefer alloc.free(start_key);
    pos.* += start_len;
    const end_key = try readOptionalString(alloc, encoded, pos);
    errdefer if (end_key) |value| alloc.free(value);
    const restore_backup_id = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_backup_id);
    const restore_location = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_location);
    const restore_snapshot_path = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_snapshot_path);
    const range_id = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        group_id;
    const doc_identity_shard_id = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const doc_identity_range_id = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    // Range values are independently length-delimited by the metadata store.
    // Older v1 values end after the identity fields, so appended fields must
    // remain optional for rolling upgrades and snapshot/log replay.
    const split_attempt_epoch = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const restore_connection = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_connection);
    const restore_artifact_size_bytes = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const restore_artifact_sha256 = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_artifact_sha256);
    const restore_artifact_backup_id = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_artifact_backup_id);
    var completed_restore_fingerprint =
        metadata_table_manager.empty_restore_completion_fingerprint;
    if (pos.* < encoded.len) {
        if (encoded.len - pos.* <
            @sizeOf(metadata_table_manager.RestoreCompletionFingerprint))
        {
            return error.InvalidMetadataTransitionEncoding;
        }
        @memcpy(
            &completed_restore_fingerprint,
            encoded[pos.*..][0..@sizeOf(metadata_table_manager.RestoreCompletionFingerprint)],
        );
        pos.* += @sizeOf(metadata_table_manager.RestoreCompletionFingerprint);
    }
    const restore_native_manifest_size_bytes = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const restore_native_manifest_sha256 = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(restore_native_manifest_sha256);
    return .{
        .group_id = group_id,
        .range_id = if (range_id == 0) group_id else range_id,
        .table_id = table_id,
        .start_key = start_key,
        .end_key = end_key,
        .doc_identity_shard_id = doc_identity_shard_id,
        .doc_identity_range_id = doc_identity_range_id,
        .split_attempt_epoch = split_attempt_epoch,
        .restore_backup_id = restore_backup_id,
        .restore_artifact_backup_id = restore_artifact_backup_id,
        .restore_location = restore_location,
        .restore_snapshot_path = restore_snapshot_path,
        .restore_connection = restore_connection,
        .restore_artifact_size_bytes = restore_artifact_size_bytes,
        .restore_artifact_sha256 = restore_artifact_sha256,
        .restore_native_manifest_size_bytes = restore_native_manifest_size_bytes,
        .restore_native_manifest_sha256 = restore_native_manifest_sha256,
        .completed_restore_fingerprint = completed_restore_fingerprint,
    };
}

fn readSchemaProgressRecord(
    encoded: []const u8,
    pos: *usize,
) !metadata.SchemaProgressRecord {
    return .{
        .table_id = try readInt(encoded, pos, u64),
        .node_id = try readInt(encoded, pos, u64),
        .schema_version = try readInt(encoded, pos, u32),
    };
}

fn readRestoreProgressRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.RestoreProgressRecord {
    const table_id = try readInt(encoded, pos, u64);
    const node_id = try readInt(encoded, pos, u64);
    const group_id = try readInt(encoded, pos, u64);
    const backup_id = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(backup_id);
    const location = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(location);
    const snapshot_path = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(snapshot_path);
    if (pos.* >= encoded.len) return error.InvalidRestoreProgressRecord;
    const primary_restored = switch (encoded[pos.*]) {
        0 => false,
        1 => true,
        else => return error.InvalidRestoreProgressRecord,
    };
    pos.* += 1;
    if (pos.* >= encoded.len) return error.InvalidRestoreProgressRecord;
    const runtime_repair_complete = switch (encoded[pos.*]) {
        0 => false,
        1 => true,
        else => return error.InvalidRestoreProgressRecord,
    };
    pos.* += 1;
    const phase = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(phase);
    const last_error = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(last_error);
    const updated_at_ms = try readInt(encoded, pos, u64);
    const artifact_sha256 = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(artifact_sha256);
    const artifact_backup_id = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(artifact_backup_id);
    const native_manifest_size_bytes = if (pos.* < encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const native_manifest_sha256 = if (pos.* < encoded.len)
        try readRequiredString(alloc, encoded, pos)
    else
        try alloc.dupe(u8, "");
    errdefer alloc.free(native_manifest_sha256);
    return .{
        .table_id = table_id,
        .node_id = node_id,
        .group_id = group_id,
        .backup_id = backup_id,
        .artifact_backup_id = artifact_backup_id,
        .location = location,
        .snapshot_path = snapshot_path,
        .artifact_sha256 = artifact_sha256,
        .native_manifest_size_bytes = native_manifest_size_bytes,
        .native_manifest_sha256 = native_manifest_sha256,
        .primary_restored = primary_restored,
        .runtime_repair_complete = runtime_repair_complete,
        .phase = phase,
        .last_error = last_error,
        .updated_at_ms = updated_at_ms,
    };
}

fn readReplicationSourceStatusRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.ReplicationSourceStatusRecord {
    const table_id = try readInt(encoded, pos, u64);
    const source_ordinal = try readInt(encoded, pos, u32);
    const source_kind = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(source_kind);
    const external_table = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(external_table);
    const slot_name = if (pos.* < encoded.len) try readRequiredString(alloc, encoded, pos) else try alloc.dupe(u8, "");
    errdefer alloc.free(slot_name);
    const publication_name = if (pos.* < encoded.len) try readRequiredString(alloc, encoded, pos) else try alloc.dupe(u8, "");
    errdefer alloc.free(publication_name);
    const phase = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(phase);
    const checkpoint = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(checkpoint);
    const snapshot_offset = if (pos.* + @sizeOf(u64) <= encoded.len)
        try readInt(encoded, pos, u64)
    else
        0;
    const stream_checkpoint = if (pos.* < encoded.len) try readRequiredString(alloc, encoded, pos) else try alloc.dupe(u8, "");
    errdefer alloc.free(stream_checkpoint);
    const last_error = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(last_error);
    const lag_records = try readInt(encoded, pos, u64);
    const updated_at_ms = try readInt(encoded, pos, u64);
    const prepared_checkpoint = if (pos.* < encoded.len) try readRequiredString(alloc, encoded, pos) else try alloc.dupe(u8, "");
    errdefer alloc.free(prepared_checkpoint);
    const cutover_mode = if (pos.* < encoded.len) try readRequiredString(alloc, encoded, pos) else try alloc.dupe(u8, "");
    errdefer alloc.free(cutover_mode);
    const consecutive_failures = if (pos.* + @sizeOf(u64) <= encoded.len) try readInt(encoded, pos, u64) else 0;
    const last_success_at_ms = if (pos.* + @sizeOf(u64) <= encoded.len) try readInt(encoded, pos, u64) else 0;
    const last_change_applied_at_ms = if (pos.* + @sizeOf(u64) <= encoded.len) try readInt(encoded, pos, u64) else 0;
    const failure_class = if (pos.* < encoded.len) try readRequiredString(alloc, encoded, pos) else try alloc.dupe(u8, "");
    errdefer alloc.free(failure_class);
    const lag_millis = if (pos.* + @sizeOf(u64) <= encoded.len) try readInt(encoded, pos, u64) else 0;
    const last_source_commit_at_ms = if (pos.* + @sizeOf(u64) <= encoded.len) try readInt(encoded, pos, u64) else 0;
    const cutover_intent_id = if (pos.* + @sizeOf(u64) <= encoded.len) try readInt(encoded, pos, u64) else 0;
    var cutover_config_fingerprint =
        @as([std.crypto.hash.sha2.Sha256.digest_length]u8, @splat(0));
    if (pos.* + cutover_config_fingerprint.len <= encoded.len) {
        @memcpy(&cutover_config_fingerprint, encoded[pos.*..][0..cutover_config_fingerprint.len]);
        pos.* += cutover_config_fingerprint.len;
    }
    const cutover_authority_id = try readInt(encoded, pos, u64);
    var cutover_provider_identity =
        @as([std.crypto.hash.sha2.Sha256.digest_length]u8, @splat(0));
    if (pos.* + cutover_provider_identity.len > encoded.len)
        return error.InvalidMetadataTransitionEncoding;
    @memcpy(
        &cutover_provider_identity,
        encoded[pos.*..][0..cutover_provider_identity.len],
    );
    pos.* += cutover_provider_identity.len;
    const retired_cutover_authority_id = try readInt(encoded, pos, u64);
    const retired_slot_name = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(retired_slot_name);
    const retired_publication_name = try readRequiredString(
        alloc,
        encoded,
        pos,
    );
    errdefer alloc.free(retired_publication_name);
    return .{
        .table_id = table_id,
        .source_ordinal = source_ordinal,
        .source_kind = source_kind,
        .external_table = external_table,
        .cutover_mode = cutover_mode,
        .slot_name = slot_name,
        .publication_name = publication_name,
        .phase = phase,
        .checkpoint = checkpoint,
        .snapshot_offset = snapshot_offset,
        .prepared_checkpoint = prepared_checkpoint,
        .stream_checkpoint = stream_checkpoint,
        .last_error = last_error,
        .failure_class = failure_class,
        .lag_records = lag_records,
        .lag_millis = lag_millis,
        .consecutive_failures = consecutive_failures,
        .last_source_commit_at_ms = last_source_commit_at_ms,
        .last_success_at_ms = last_success_at_ms,
        .last_change_applied_at_ms = last_change_applied_at_ms,
        .cutover_intent_id = cutover_intent_id,
        .cutover_authority_id = cutover_authority_id,
        .cutover_config_fingerprint = cutover_config_fingerprint,
        .cutover_provider_identity = cutover_provider_identity,
        .retired_cutover_authority_id = retired_cutover_authority_id,
        .retired_slot_name = retired_slot_name,
        .retired_publication_name = retired_publication_name,
        .updated_at_ms = updated_at_ms,
    };
}

fn readPlacementIntent(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !raft_reconciler.PlacementIntent {
    const group_id = try readInt(encoded, pos, u64);
    const replica_id = try readInt(encoded, pos, u64);
    const local_node_id = try readInt(encoded, pos, u64);
    const metadata_version = try readInt(encoded, pos, u64);
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const bootstrap_mode = std.enums.fromInt(raft_catalog.ReplicaBootstrapMode, encoded[pos.*]) orelse
        return error.InvalidMetadataTransitionEncoding;
    pos.* += 1;
    const peer_count = try readInt(encoded, pos, u32);
    const peer_node_ids = try alloc.alloc(u64, peer_count);
    errdefer alloc.free(peer_node_ids);
    for (peer_node_ids) |*node_id| node_id.* = try readInt(encoded, pos, u64);
    const store_id = if (pos.* < encoded.len) try readInt(encoded, pos, u64) else 0;
    var snapshot_bootstrap: ?raft_catalog.SnapshotBootstrapRecord = null;
    var backup_restore_bootstrap: ?raft_catalog.BackupRestoreBootstrapRecord = null;
    var initial_fk_root_generation: u64 = 0;
    if (pos.* < encoded.len) {
        const source_tag = encoded[pos.*];
        pos.* += 1;
        switch (source_tag) {
            0 => {},
            4 => {
                initial_fk_root_generation = try readInt(encoded, pos, u64);
                if (initial_fk_root_generation == 0) return error.InvalidMetadataTransitionEncoding;
            },
            1, 3 => {
                const from_node_id = try readInt(encoded, pos, u64);
                const term = try readInt(encoded, pos, u64);
                const snapshot_id = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(snapshot_id);
                const uri = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(uri);
                const format: raft_engine.runtime.snapshot_transport_iface.SnapshotArtifactFormat = if (source_tag == 3) blk: {
                    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
                    const decoded = std.enums.fromInt(
                        raft_engine.runtime.snapshot_transport_iface.SnapshotArtifactFormat,
                        encoded[pos.*],
                    ) orelse return error.InvalidMetadataTransitionEncoding;
                    pos.* += 1;
                    if (decoded == .unknown) return error.InvalidMetadataTransitionEncoding;
                    break :blk decoded;
                } else raft_catalog.SnapshotBootstrapRecord.inferFormat(snapshot_id, uri);
                snapshot_bootstrap = .{
                    .from_node_id = from_node_id,
                    .term = term,
                    .snapshot_id = snapshot_id,
                    .uri = uri,
                    .format = format,
                };
            },
            2 => {
                const backup_id = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(backup_id);
                const artifact_backup_id = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(artifact_backup_id);
                const location = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(location);
                const snapshot_path = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(snapshot_path);
                const connection = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(connection);
                const artifact_size_bytes = try readInt(encoded, pos, u64);
                const artifact_sha256 = try readRequiredString(alloc, encoded, pos);
                errdefer alloc.free(artifact_sha256);
                backup_restore_bootstrap = .{
                    .backup_id = backup_id,
                    .artifact_backup_id = artifact_backup_id,
                    .location = location,
                    .snapshot_path = snapshot_path,
                    .connection = connection,
                    .artifact_size_bytes = artifact_size_bytes,
                    .artifact_sha256 = artifact_sha256,
                };
                backup_restore_bootstrap.?.validate() catch
                    return error.InvalidMetadataTransitionEncoding;
            },
            else => return error.InvalidMetadataTransitionEncoding,
        }
    }
    var serving_state: raft_reconciler.PlacementServingState = .serving;
    var relocation_generation: u64 = 0;
    var relocation_source_node_id: u64 = 0;
    var relocation_source_store_id: u64 = 0;
    var relocation_doc_count_watermark: u64 = 0;
    var relocation_disk_bytes_watermark: u64 = 0;
    var relocation_target_sequence: u64 = 0;
    var relocation_applied_sequence: u64 = 0;
    if (pos.* < encoded.len) {
        serving_state = std.enums.fromInt(raft_reconciler.PlacementServingState, encoded[pos.*]) orelse
            return error.InvalidMetadataTransitionEncoding;
        pos.* += 1;
        relocation_generation = try readInt(encoded, pos, u64);
        relocation_source_node_id = try readInt(encoded, pos, u64);
        relocation_source_store_id = try readInt(encoded, pos, u64);
        relocation_doc_count_watermark = try readInt(encoded, pos, u64);
        relocation_disk_bytes_watermark = try readInt(encoded, pos, u64);
        relocation_target_sequence = try readInt(encoded, pos, u64);
        relocation_applied_sequence = try readInt(encoded, pos, u64);
    }
    if (backup_restore_bootstrap != null and pos.* < encoded.len) {
        const native_manifest_size_bytes = try readInt(encoded, pos, u64);
        const native_manifest_sha256 = try readRequiredString(alloc, encoded, pos);
        errdefer alloc.free(native_manifest_sha256);
        backup_restore_bootstrap.?.native_manifest_size_bytes = native_manifest_size_bytes;
        backup_restore_bootstrap.?.native_manifest_sha256 = native_manifest_sha256;
        if (pos.* < encoded.len) {
            const destination_name = try readRequiredString(alloc, encoded, pos);
            errdefer alloc.free(destination_name);
            backup_restore_bootstrap.?.destination_table_id = try readInt(encoded, pos, u64);
            backup_restore_bootstrap.?.destination_shard_id = try readInt(encoded, pos, u64);
            backup_restore_bootstrap.?.destination_range_id = try readInt(encoded, pos, u64);
            backup_restore_bootstrap.?.destination_table_name = destination_name;
        }
        backup_restore_bootstrap.?.validate() catch
            return error.InvalidMetadataTransitionEncoding;
    }
    return .{
        .record = .{
            .group_id = group_id,
            .replica_id = replica_id,
            .local_node_id = local_node_id,
            .metadata_version = metadata_version,
            .initial_fk_root_generation = initial_fk_root_generation,
            .bootstrap_mode = bootstrap_mode,
            .snapshot_bootstrap = snapshot_bootstrap,
            .backup_restore_bootstrap = backup_restore_bootstrap,
        },
        .store_id = store_id,
        .peer_node_ids = peer_node_ids,
        .serving_state = serving_state,
        .relocation_generation = relocation_generation,
        .relocation_source_node_id = relocation_source_node_id,
        .relocation_source_store_id = relocation_source_store_id,
        .relocation_doc_count_watermark = relocation_doc_count_watermark,
        .relocation_disk_bytes_watermark = relocation_disk_bytes_watermark,
        .relocation_target_sequence = relocation_target_sequence,
        .relocation_applied_sequence = relocation_applied_sequence,
    };
}

fn readSplitTransitionRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.SplitTransitionRecord {
    const transition_id = try readInt(encoded, pos, u64);
    const attempt_epoch = try readInt(encoded, pos, u64);
    const source_group_id = try readInt(encoded, pos, u64);
    const destination_group_id = try readInt(encoded, pos, u64);
    if (transition_id == 0 or attempt_epoch == 0 or source_group_id == 0 or destination_group_id == 0)
        return error.InvalidMetadataTransitionEncoding;
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const phase = std.enums.fromInt(metadata.TransitionPhase, encoded[pos.*]) orelse
        return error.InvalidMetadataTransitionEncoding;
    pos.* += 1;
    const split_key = try readOptionalString(alloc, encoded, pos);
    errdefer if (split_key) |value| alloc.free(value);
    const source_range_end = try readOptionalString(alloc, encoded, pos);
    errdefer if (source_range_end) |value| alloc.free(value);
    const rollback_reason = try readOptionalString(alloc, encoded, pos);
    errdefer if (rollback_reason) |value| alloc.free(value);
    var table_contract = try readTransitionTableContract(alloc, encoded, pos);
    errdefer table_contract.deinitOwned(alloc);
    try table_contract.validateForSplit();
    return .{
        .transition_id = transition_id,
        .attempt_epoch = attempt_epoch,
        .source_group_id = source_group_id,
        .destination_group_id = destination_group_id,
        .phase = phase,
        .split_key = split_key,
        .source_range_end = source_range_end,
        .rollback_reason = rollback_reason,
        .table_contract = table_contract,
    };
}

fn readMergeTransitionRecord(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.MergeTransitionRecord {
    const transition_id = try readInt(encoded, pos, u64);
    const donor_group_id = try readInt(encoded, pos, u64);
    const receiver_group_id = try readInt(encoded, pos, u64);
    if (transition_id == 0 or donor_group_id == 0 or receiver_group_id == 0)
        return error.InvalidMetadataTransitionEncoding;
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const phase = std.enums.fromInt(metadata.TransitionPhase, encoded[pos.*]) orelse
        return error.InvalidMetadataTransitionEncoding;
    pos.* += 1;
    const rollback_reason = try readOptionalString(alloc, encoded, pos);
    errdefer if (rollback_reason) |value| alloc.free(value);
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const reassignment_tag = encoded[pos.*];
    if (reassignment_tag > 1) return error.InvalidMetadataTransitionEncoding;
    const allow_doc_identity_reassignment = reassignment_tag == 1;
    pos.* += 1;
    var table_contract = try readTransitionTableContract(alloc, encoded, pos);
    errdefer table_contract.deinitOwned(alloc);
    try table_contract.validateForMerge(allow_doc_identity_reassignment);
    var record: metadata.MergeTransitionRecord = .{
        .transition_id = transition_id,
        .donor_group_id = donor_group_id,
        .receiver_group_id = receiver_group_id,
        .phase = phase,
        .rollback_reason = rollback_reason,
        .allow_doc_identity_reassignment = allow_doc_identity_reassignment,
        .table_contract = table_contract,
    };
    if (std.mem.startsWith(u8, encoded[pos.*..], "afom1")) {
        pos.* += 5;
        const length = try readInt(encoded, pos, u32);
        if (length == 0 or length > 16 * 1024 or length > encoded.len - pos.*) return error.InvalidMetadataTransitionEncoding;
        if (length != 0) {
            const parsed = try std.json.parseFromSlice(@import("../online_merge.zig").State, alloc, encoded[pos.*..][0..length], .{});
            defer parsed.deinit();
            record.online = parsed.value;
            try record.online.?.validateRecord(record);
        }
        pos.* += length;
    }
    return record;
}

fn readTransitionTableContract(
    alloc: std.mem.Allocator,
    encoded: []const u8,
    pos: *usize,
) !metadata.TransitionTableContract {
    const table_id = try readInt(encoded, pos, u64);
    const table_name = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(table_name);
    const schema_json = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(schema_json);
    const indexes_json = try readRequiredString(alloc, encoded, pos);
    errdefer alloc.free(indexes_json);
    var contract: metadata.TransitionTableContract = .{
        .table_id = table_id,
        .table_name = table_name,
        .schema_json = schema_json,
        .indexes_json = indexes_json,
        .source_identity = .{
            .shard_id = try readInt(encoded, pos, u64),
            .range_id = try readInt(encoded, pos, u64),
        },
        .target_identity = .{
            .shard_id = try readInt(encoded, pos, u64),
            .range_id = try readInt(encoded, pos, u64),
        },
    };
    contract.read_schema_json = try alloc.dupe(u8, "");
    errdefer alloc.free(contract.read_schema_json);
    if (std.mem.startsWith(u8, encoded[pos.*..], "aftc1")) {
        pos.* += 5;
        const read_schema_json = try readRequiredString(alloc, encoded, pos);
        alloc.free(contract.read_schema_json);
        contract.read_schema_json = read_schema_json;
        contract.integrity_protocol = std.enums.fromInt(@TypeOf(contract.integrity_protocol), try readInt(encoded, pos, u8)) orelse return error.InvalidMetadataTransitionEncoding;
    }
    try contract.validate();
    return contract;
}

fn readReconcileLeaseRecord(
    encoded: []const u8,
    pos: *usize,
) !metadata.ReconcileLeaseRecord {
    return .{
        .owner_node_id = try readInt(encoded, pos, u64),
        .expires_at_ms = try readInt(encoded, pos, u64),
    };
}

fn readShuffleJoinLeaseRecord(
    encoded: []const u8,
    pos: *usize,
) !metadata.ShuffleJoinLeaseRecord {
    return .{
        .job_id = try readInt(encoded, pos, u64),
        .owner_group_id = try readInt(encoded, pos, u64),
        .expires_at_ms = try readInt(encoded, pos, u64),
    };
}

fn readReallocationRequestRecord(
    encoded: []const u8,
    pos: *usize,
) !metadata.ReallocationRequestRecord {
    var record: metadata.ReallocationRequestRecord = .{
        .request_id = try readInt(encoded, pos, u128),
        .requested_at_ms = try readInt(encoded, pos, u64),
    };
    if (pos.* < encoded.len) {
        if (pos.* + reallocation_request_extension_magic.len > encoded.len or
            !std.mem.eql(
                u8,
                encoded[pos.* .. pos.* + reallocation_request_extension_magic.len],
                reallocation_request_extension_magic,
            ))
        {
            return error.InvalidMetadataRecord;
        }
        pos.* += reallocation_request_extension_magic.len;
        const version = try readInt(encoded, pos, u16);
        if (version != reallocation_request_extension_version) return error.InvalidMetadataRecord;
        record.barrier_protocol_version = try readInt(encoded, pos, u16);
        if (pos.* + @sizeOf(metadata.MetadataClusterIncarnation) > encoded.len) return error.InvalidMetadataRecord;
        var incarnation: metadata.MetadataClusterIncarnation = undefined;
        @memcpy(&incarnation, encoded[pos.*..][0..incarnation.len]);
        pos.* += incarnation.len;
        record.metadata_incarnation = incarnation;
        record.protected_metadata_member_count = try readInt(encoded, pos, u32);
        if (pos.* + record.protected_metadata_membership_fingerprint.len > encoded.len) return error.InvalidMetadataRecord;
        @memcpy(
            &record.protected_metadata_membership_fingerprint,
            encoded[pos.*..][0..record.protected_metadata_membership_fingerprint.len],
        );
        pos.* += record.protected_metadata_membership_fingerprint.len;
    }
    if (!metadata.isValidReallocationRequest(record)) return error.InvalidMetadataRecord;
    return record;
}

fn appendMetadataPrefixRowsTxn(
    alloc: std.mem.Allocator,
    txn: *docstore.DocStore.Txn,
    out: *std.ArrayListUnmanaged(docstore.OwnedKVPair),
    prefix: []const u8,
) !void {
    const rows = try docstore.DocStore.scanPrefixTxn(alloc, txn, prefix);
    var transferred = false;
    defer {
        if (!transferred) freeMetadataSnapshotRows(alloc, rows) else alloc.free(rows);
    }
    try out.appendSlice(alloc, rows);
    transferred = true;
}

fn appendMetadataPointRowTxn(
    alloc: std.mem.Allocator,
    txn: *docstore.DocStore.Txn,
    out: *std.ArrayListUnmanaged(docstore.OwnedKVPair),
    key: []const u8,
) !void {
    const borrowed = txn.get(key) catch |err| switch (err) {
        error.NotFound => return,
        else => return err,
    };
    const owned_key = try alloc.dupe(u8, key);
    errdefer alloc.free(owned_key);
    const owned_value = try alloc.dupe(u8, borrowed);
    errdefer alloc.free(owned_value);
    try out.append(alloc, .{ .key = owned_key, .value = owned_value });
}

fn metadataSnapshotRowLessThan(_: void, lhs: docstore.OwnedKVPair, rhs: docstore.OwnedKVPair) bool {
    return std.mem.order(u8, lhs.key, rhs.key) == .lt;
}

fn encodeMetadataSnapshot(alloc: std.mem.Allocator, rows: []const docstore.OwnedKVPair) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.appendSlice(alloc, RaftApplyStore.metadata_snapshot_magic);
    try out.append(alloc, RaftApplyStore.metadata_snapshot_version);
    try appendInt(alloc, &out, u32, std.math.cast(u32, rows.len) orelse return error.MetadataSnapshotTooLarge);
    for (rows) |row| {
        try appendInt(alloc, &out, u32, std.math.cast(u32, row.key.len) orelse return error.MetadataSnapshotTooLarge);
        try out.appendSlice(alloc, row.key);
        try appendInt(alloc, &out, u32, std.math.cast(u32, row.value.len) orelse return error.MetadataSnapshotTooLarge);
        try out.appendSlice(alloc, row.value);
    }
    return try out.toOwnedSlice(alloc);
}

fn decodeMetadataSnapshotAlloc(alloc: std.mem.Allocator, encoded: []const u8) ![]docstore.OwnedKVPair {
    if (encoded.len < RaftApplyStore.metadata_snapshot_magic.len + 1 + @sizeOf(u32) or
        !std.mem.eql(u8, encoded[0..RaftApplyStore.metadata_snapshot_magic.len], RaftApplyStore.metadata_snapshot_magic) or
        encoded[RaftApplyStore.metadata_snapshot_magic.len] != RaftApplyStore.metadata_snapshot_version)
    {
        return error.InvalidMetadataSnapshot;
    }
    var pos: usize = RaftApplyStore.metadata_snapshot_magic.len + 1;
    const count = readInt(encoded, &pos, u32) catch return error.InvalidMetadataSnapshot;
    if (count > (encoded.len - pos) / 8) return error.InvalidMetadataSnapshot;
    const rows = try alloc.alloc(docstore.OwnedKVPair, count);
    var initialized: usize = 0;
    errdefer {
        for (rows[0..initialized]) |row| {
            alloc.free(row.key);
            alloc.free(row.value);
        }
        alloc.free(rows);
    }
    while (initialized < rows.len) : (initialized += 1) {
        const key_len = readInt(encoded, &pos, u32) catch return error.InvalidMetadataSnapshot;
        if (key_len > encoded.len - pos) return error.InvalidMetadataSnapshot;
        const key = try alloc.dupe(u8, encoded[pos .. pos + key_len]);
        pos += key_len;
        errdefer alloc.free(key);
        const value_len = readInt(encoded, &pos, u32) catch return error.InvalidMetadataSnapshot;
        if (value_len > encoded.len - pos) return error.InvalidMetadataSnapshot;
        const value = try alloc.dupe(u8, encoded[pos .. pos + value_len]);
        pos += value_len;
        rows[initialized] = .{ .key = key, .value = value };
    }
    if (pos != encoded.len) return error.InvalidMetadataSnapshot;
    return rows;
}

fn freeMetadataSnapshotRows(alloc: std.mem.Allocator, rows: []const docstore.OwnedKVPair) void {
    for (rows) |row| {
        alloc.free(row.key);
        alloc.free(row.value);
    }
    alloc.free(rows);
}

fn validateMetadataSnapshotRows(
    alloc: std.mem.Allocator,
    group_id: u64,
    rows: []const docstore.OwnedKVPair,
) !void {
    return validateMetadataSnapshotRowsCancelable(alloc, group_id, rows, null);
}

fn validateMetadataSnapshotRowsCancelable(alloc: std.mem.Allocator, group_id: u64, rows: []const docstore.OwnedKVPair, cancelled: ?*const std.atomic.Value(bool)) !void {
    if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
    var seen = std.StringHashMapUnmanaged([]const u8).empty;
    defer seen.deinit(alloc);
    try seen.ensureTotalCapacity(alloc, @intCast(rows.len));
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (!metadataSnapshotKeyBelongsToGroup(group_id, row.key)) return error.InvalidMetadataSnapshot;
        const result = try seen.getOrPut(alloc, row.key);
        if (result.found_existing) return error.InvalidMetadataSnapshot;
        result.value_ptr.* = row.value;
    }
    validateSchemaReaderSnapshotCut(alloc, group_id, rows, &seen, cancelled) catch |err| switch (err) {
        error.OutOfMemory, error.SnapshotBuildCancelled => return err,
        else => return error.InvalidMetadataSnapshot,
    };
    for (rows) |row| {
        if (column_identities.decodeKey(row.key) catch return error.InvalidMetadataSnapshot) |identity| {
            if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
            var buf: [160]u8 = undefined;
            const table = seen.get(try tableKeyForGroup(&buf, group_id, identity.table)) orelse return error.InvalidMetadataSnapshot;
            validateColumnIdentityRecord(alloc, identity, row.value, table) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return error.InvalidMetadataSnapshot,
            };
        }
    }
    validateRelationSnapshotCut(alloc, group_id, rows, &seen, cancelled) catch |err| switch (err) {
        error.OutOfMemory, error.SnapshotBuildCancelled => return err,
        else => return error.InvalidMetadataSnapshot,
    };
    validateSqlViewSnapshotCut(alloc, group_id, rows, &seen, cancelled) catch |err| switch (err) {
        error.OutOfMemory, error.SnapshotBuildCancelled => return err,
        else => return error.InvalidMetadataSnapshot,
    };
    validateSqlSequenceSnapshotCut(alloc, group_id, rows, &seen, cancelled) catch |err| switch (err) {
        error.OutOfMemory, error.SnapshotBuildCancelled => return err,
        else => return error.InvalidMetadataSnapshot,
    };
}

/// Manifest-cut validation is linear in rows. Immutable definitions/counter
/// states and shared owner layouts are pinned once for the complete import;
/// counters, leases and ownership edges cannot be restored independently.
fn validateSqlSequenceSnapshotCut(backing: std.mem.Allocator, group: u64, rows: []const docstore.OwnedKVPair, values: *const std.StringHashMapUnmanaged([]const u8), cancelled: ?*const std.atomic.Value(bool)) !void {
    const Reader = struct {
        values: *const std.StringHashMapUnmanaged([]const u8),
        pub fn get(self: *@This(), key: []const u8) anyerror![]const u8 {
            return self.values.get(key) orelse error.NotFound;
        }
    };
    const Rows = struct {
        values: []const docstore.OwnedKVPair,
        index: usize = 0,
        fn reset(self: *@This()) !void {
            self.index = 0;
        }
        fn next(self: *@This()) !?docstore.KVPair {
            if (self.index == self.values.len) return null;
            const row = self.values[self.index];
            self.index += 1;
            return .{ .key = row.key, .value = row.value };
        }
    };
    var reader: Reader = .{ .values = values };
    var scan: Rows = .{ .values = rows };
    try verifySqlSequenceCut(backing, group, &reader, &scan, cancelled);
}

/// Same closure rules for Raft images and native checkpoints. The latter
/// streams only this group's two sequence/catalog namespaces, retaining no
/// copies of unrelated table schemas, topology or primary data.
fn verifySqlSequenceCut(backing: std.mem.Allocator, group: u64, reader: anytype, rows: anytype, cancelled: ?*const std.atomic.Value(bool)) !void {
    const Reader = @TypeOf(reader.*);
    var arena = std.heap.ArenaAllocator.init(backing);
    defer arena.deinit();
    const a = arena.allocator();
    var buffer: [256]u8 = undefined;
    const catalog_prefix = try a.dupe(u8, try system_catalog_storage.prefixForGroup(&buffer, group));
    const record_prefix = try std.mem.concat(a, u8, &.{ catalog_prefix, "record:" });
    const sequence_prefix = try std.mem.concat(a, u8, &.{ record_prefix, "sequence:" });
    const owner_prefix = try std.mem.concat(a, u8, &.{ catalog_prefix, "sequence-owner:" });
    const counter_prefix = try a.dupe(u8, try sql_sequences.journal.prefixForGroup(&buffer, group));
    const outcome_prefix = try a.dupe(u8, try sql_sequences.outcomes.prefixForGroup(&buffer, group));
    const meta_key = try std.mem.concat(a, u8, &.{ catalog_prefix, "meta" });
    const meta = if (try RaftApplyStore.relationOptional(reader, meta_key)) |bytes| try std.json.parseFromSliceLeaky(system_catalog.Meta, a, bytes, .{}) else system_catalog.Meta{};
    try rows.reset();
    const present = meta.sequence_outcome_head != null or present: {
        while (try rows.next()) |row| {
            if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
            if (std.mem.startsWith(u8, row.key, sequence_prefix) or std.mem.startsWith(u8, row.key, owner_prefix) or std.mem.startsWith(u8, row.key, counter_prefix) or std.mem.startsWith(u8, row.key, outcome_prefix)) break :present true;
        }
        break :present false;
    };
    if (!present) return;
    const activation = try std.json.parseFromSliceLeaky(topology_protocol.Activation, a, try reader.get(try RaftApplyStore.topologyActivationKeyForGroup(&buffer, group)), .{});
    if (activation.version < topology_protocol.sql_sequence_catalog_version or activation.version > topology_protocol.current_version or
        activation.member_count == 0 or std.mem.allEqual(u8, &activation.membership_fingerprint, 0)) return error.InvalidSequenceState;
    const incarnation = try decodeMetadataIncarnationRecord(try reader.get(try metadataIncarnationKeyForGroup(&buffer, group)));
    if (!std.meta.eql(activation.incarnation, incarnation.incarnation)) return error.InvalidSequenceState;
    if (meta.sequence_outcome_head == null) return error.InvalidSequenceOutcome;
    const outcomes: sql_sequences.outcomes.Store(Reader) = .{ .txn = reader, .group = group, .incarnation = (try RaftApplyStore.relationSourceEpochTxn(reader, group)).incarnation };
    try outcomes.validateCut(a);
    var definitions_present = false;
    try rows.reset();
    while (try rows.next()) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (std.mem.startsWith(u8, row.key, outcome_prefix)) try outcomes.validateRow(a, row.key, row.value);
        if (std.mem.startsWith(u8, row.key, sequence_prefix)) definitions_present = true;
    }
    // Conditional DDL can have an outcome before the first logical catalog
    // resource exists. Outcomes alone must not invent a catalog generation.
    if (!definitions_present) {
        try rows.reset();
        while (try rows.next()) |row| if (std.mem.startsWith(u8, row.key, owner_prefix) or std.mem.startsWith(u8, row.key, counter_prefix)) return error.InvalidSequenceState;
        return;
    }
    if (meta.version != 1 or meta.revision == 0) return error.InvalidSequenceState;
    const sequence = sql_sequences.sequence;
    const Cut = struct { definition: sequence.Definition, state: sequence.State };
    var cuts: std.AutoHashMapUnmanaged(u64, Cut) = .empty;
    var names: std.StringHashMapUnmanaged(void) = .empty;
    const OwnerLayout = struct { namespace_id: u64, columns: column_identities.State };
    var attributes: std.AutoHashMapUnmanaged(u64, OwnerLayout) = .empty;
    var registry = try RaftApplyStore.RelationRegistry(Reader).init(a, reader, group);
    const live = registry.live orelse return error.InvalidSequenceState;
    if (live.root.coverage != .constraint_names or !live.root.epoch.eql(try RaftApplyStore.relationSourceEpochTxn(reader, group))) return error.InvalidSequenceState;
    try rows.reset();
    while (try rows.next()) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (!std.mem.startsWith(u8, row.key, record_prefix)) continue;
        // Do not decode potentially large view payloads just to check names.
        const header = try std.json.parseFromSliceLeaky(struct { kind: system_catalog.Kind, id: u64, parent_id: u64, name: []const u8 }, a, row.value, .{ .ignore_unknown_fields = true });
        if (!system_catalog.namespaceRelation(header.kind)) continue;
        const name_key = try a.alloc(u8, 8 + header.name.len);
        std.mem.writeInt(u64, name_key[0..8], header.parent_id, .big);
        @memcpy(name_key[8..], header.name);
        if ((try names.getOrPut(a, name_key)).found_existing) return error.InvalidSequenceState;
        if (header.kind != .sequence) continue;
        const resource = try std.json.parseFromSliceLeaky(system_catalog.Resource, a, row.value, .{});
        if (resource.id == 0 or resource.id >= meta.next_id or resource.storage_name.len != 0 or resource.tablespace_id != 0 or !std.mem.eql(u8, resource.location_json, "null") or
            !std.mem.eql(u8, row.key, try system_catalog_storage.recordKeyAlloc(a, group, .sequence, resource.id))) return error.InvalidSequenceState;
        try system_catalog.validateTableName(resource.name);
        const namespace_key = try system_catalog_storage.recordKeyAlloc(a, group, .namespace, resource.parent_id);
        const namespace = try std.json.parseFromSliceLeaky(system_catalog.Resource, a, try reader.get(namespace_key), .{});
        if (namespace.kind != .namespace or namespace.id != resource.parent_id) return error.InvalidSequenceState;
        if (try registry.getEntry(.{ .namespace_id = namespace.id, .name = resource.name }) != null) return error.InvalidSequenceState;
        const descriptor = try sequence.Descriptor.decode(a, resource.source_json);
        if (descriptor.id != resource.id) return error.InvalidSequenceState;
        const layout = try descriptor.definition();
        const Counter = sql_sequences.journal.Store(Reader);
        const counter: Counter = .{ .txn = reader, .key = .{ .group = group, .sequence_id = resource.id } };
        const state = (try counter.load(a, layout)) orelse return error.InvalidSequenceState;
        if ((try cuts.getOrPut(a, resource.id)).found_existing) return error.InvalidSequenceState;
        cuts.getPtr(resource.id).?.* = .{ .definition = layout, .state = state };
        if (layout.owned_by) |owner| {
            const edge = try reader.get(try sql_sequences.ownerKey(&buffer, group, owner, resource.id));
            if (!std.mem.eql(u8, edge, &.{1})) return error.InvalidSequenceState;
            const entry = try attributes.getOrPut(a, owner.table_id);
            if (!entry.found_existing) {
                const table_bytes = try reader.get(try tableKeyForGroup(&buffer, group, owner.table_id));
                const namespace_id = if (try system_catalog_storage.getById(a, reader, group, .table, owner.table_id)) |binding_| namespace: {
                    var binding = binding_;
                    defer binding.deinit();
                    break :namespace binding.value.parent_id;
                } else system_catalog.default_namespace_id;
                const bytes = try reader.get(&try column_identities.key(.{ .group = group, .table = owner.table_id }));
                try validateColumnIdentityRecord(a, .{ .group = group, .table = owner.table_id }, bytes, table_bytes);
                entry.value_ptr.* = .{ .namespace_id = namespace_id, .columns = try std.json.parseFromSliceLeaky(column_identities.State, a, bytes, .{ .allocate = .alloc_always }) };
            }
            if (entry.value_ptr.namespace_id != resource.parent_id or entry.value_ptr.columns.columnById(owner.column_id) == null) return error.InvalidSequenceState;
        }
    }
    try rows.reset();
    while (try rows.next()) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (try sql_sequences.journal.storedKey(row.key)) |stored| {
            if (stored.key.group != group) return error.InvalidSequenceState;
            const cut = cuts.get(stored.key.sequence_id) orelse return error.InvalidSequenceState;
            if (stored.revision != 0) {
                const receipt = try sql_sequences.journal.receiptBytes(a, row.value, cut.definition);
                const first = if (cut.state.revision > sql_sequences.journal.retained_receipts) cut.state.revision - sql_sequences.journal.retained_receipts + 1 else 1;
                if (stored.revision != receipt.state.revision or stored.revision < first or stored.revision > cut.state.revision or
                    (stored.revision == cut.state.revision and !std.meta.eql(receipt.state, cut.state))) return error.InvalidSequenceState;
            }
        } else if (std.mem.startsWith(u8, row.key, owner_prefix)) {
            if (row.key.len != owner_prefix.len + 24 or !std.mem.eql(u8, row.value, &.{1})) return error.InvalidSequenceState;
            const bytes = row.key[owner_prefix.len..];
            const owner: sequence.OwnedBy = .{ .table_id = std.mem.readInt(u64, bytes[0..8], .big), .column_id = std.mem.readInt(u64, bytes[8..16], .big) };
            const id = std.mem.readInt(u64, bytes[16..24], .big);
            const cut = cuts.get(id) orelse return error.InvalidSequenceState;
            if (!std.meta.eql(owner, cut.definition.owned_by orelse return error.InvalidSequenceState)) return error.InvalidSequenceState;
        }
    }
}

const SequenceCheckpointRows = struct {
    cursor: docstore.DocStore.Txn.CursorAdapter,
    group: u64,
    lane: u2 = 0,
    started: bool = false,

    fn reset(self: *@This()) !void {
        self.lane = 0;
        self.started = false;
    }
    fn next(self: *@This()) !?docstore.KVPair {
        while (self.lane < 2) {
            var buffer: [256]u8 = undefined;
            const prefix = if (self.lane == 0) try system_catalog_storage.prefixForGroup(&buffer, self.group) else try sql_sequences.journal.prefixForGroup(&buffer, self.group);
            const row = if (self.started) try self.cursor.next() else try self.cursor.seekAtOrAfter(prefix);
            self.started = true;
            if (row) |value| if (std.mem.startsWith(u8, value.key, prefix)) return .{ .key = value.key, .value = value.value };
            self.lane += 1;
            self.started = false;
        }
        return null;
    }
};

fn verifySqlSequenceCheckpointTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn) !void {
    var cursor = try txn.openCursor();
    defer cursor.close();
    var groups: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer groups.deinit(alloc);
    // Catalog groups are contiguous even though their decimal IDs sort
    // lexically. A second namespace pass catches orphan counter-only groups.
    const catalog = sql_views.allGroupsPrefix();
    var row = try cursor.seekAtOrAfter(catalog);
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, catalog)) break;
        const tail = item.key[catalog.len..];
        const colon = std.mem.indexOfScalar(u8, tail, ':') orelse return error.InvalidSequenceState;
        if (colon == 0 or tail[0] == '0') return error.InvalidSequenceState;
        for (tail[0..colon]) |byte| if (byte < '0' or byte > '9') return error.InvalidSequenceState;
        const group = std.fmt.parseInt(u64, tail[0..colon], 10) catch return error.InvalidSequenceState;
        try groups.put(alloc, group, {});
    }
    const counters = sql_sequences.journal.allGroupsPrefix();
    row = try cursor.seekAtOrAfter(counters);
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, counters)) break;
        const key = (try sql_sequences.journal.storedKey(item.key)) orelse return error.InvalidSequenceState;
        try groups.put(alloc, key.key.group, {});
    }
    var iterator = groups.keyIterator();
    while (iterator.next()) |group| {
        var scan: SequenceCheckpointRows = .{ .cursor = try txn.openCursor(), .group = group.* };
        defer scan.cursor.close();
        try verifySqlSequenceCut(alloc, group.*, txn, &scan, null);
    }
}

fn freeSqlViewNames(a: std.mem.Allocator, names: *std.StringHashMapUnmanaged(void)) void {
    var keys = names.keyIterator();
    while (keys.next()) |key| a.free(key.*);
    names.deinit(a);
}

fn verifySqlViewRecord(backing: std.mem.Allocator, reader: anytype, group: u64, expected_id: u64, bytes: []const u8, names: *std.StringHashMapUnmanaged(void), cancelled: ?*const std.atomic.Value(bool)) !usize {
    if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
    var arena = std.heap.ArenaAllocator.init(backing);
    defer arena.deinit();
    const a = arena.allocator();
    const resource = try std.json.parseFromSliceLeaky(system_catalog.Resource, a, bytes, .{ .allocate = .alloc_always });
    if (resource.kind != .view or resource.id != expected_id or resource.id == 0 or resource.parent_id == 0 or
        resource.storage_name.len != 0 or resource.tablespace_id != 0) return error.InvalidSqlViewRecord;
    var record = try sql_views.Record.decode(a, resource.source_json);
    defer record.deinit();
    if (record.value.id != resource.id) return error.InvalidSqlViewRecord;
    try system_catalog.validateTableName(resource.name);
    const name_key = try backing.alloc(u8, 8 + resource.name.len);
    std.mem.writeInt(u64, name_key[0..8], resource.parent_id, .big);
    @memcpy(name_key[8..], resource.name);
    if (names.contains(name_key)) {
        backing.free(name_key);
        return error.InvalidSqlViewRecord;
    }
    names.put(backing, name_key, {}) catch |err| {
        backing.free(name_key);
        return err;
    };
    const namespace_key = try system_catalog_storage.recordKeyAlloc(a, group, .namespace, resource.parent_id);
    const namespace_bytes = reader.get(namespace_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
    if (namespace_bytes) |raw| {
        const namespace = try std.json.parseFromSliceLeaky(system_catalog.Resource, a, raw, .{});
        if (namespace.kind != .namespace or namespace.id != resource.parent_id) return error.InvalidSqlViewRecord;
        if (namespace.id == system_catalog.default_namespace_id and
            (!std.mem.eql(u8, namespace.name, system_catalog.default_namespace_name) or namespace.parent_id != system_catalog.default_database_id))
            return error.InvalidSqlViewRecord;
    } else if (resource.parent_id != system_catalog.default_namespace_id) return error.InvalidSqlViewRecord;
    var key_buf: [160]u8 = undefined;
    const activation_bytes = try reader.get(try RaftApplyStore.topologyActivationKeyForGroup(&key_buf, group));
    const activation = try std.json.parseFromSliceLeaky(topology_protocol.Activation, a, activation_bytes, .{});
    const required_view_protocol = if (record.value.definition.requiredFormat() >= 2) topology_protocol.sql_view_domains_version else topology_protocol.sql_view_catalog_version;
    if (activation.version < required_view_protocol or activation.version > topology_protocol.current_version or
        activation.member_count == 0 or std.mem.allEqual(u8, &activation.membership_fingerprint, 0))
        return error.InvalidSqlViewRecord;
    const incarnation_bytes = try reader.get(try metadataIncarnationKeyForGroup(&key_buf, group));
    if (!std.meta.eql(activation.incarnation, (try decodeMetadataIncarnationRecord(incarnation_bytes)).incarnation))
        return error.InvalidSqlViewRecord;
    var registry = try RaftApplyStore.RelationRegistry(@TypeOf(reader.*)).init(a, reader, group);
    const live = registry.live orelse return error.InvalidSqlViewRecord;
    if (live.root.coverage != .constraint_names or !live.root.epoch.eql(try RaftApplyStore.relationSourceEpochTxn(reader, group)))
        return error.InvalidSqlViewRecord;
    if (try registry.getEntry(.{ .namespace_id = resource.parent_id, .name = resource.name }) != null)
        return error.InvalidSqlViewRecord;
    for (record.value.definition.sources, 0..) |source, index| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        var source_arena = std.heap.ArenaAllocator.init(backing);
        defer source_arena.deinit();
        const sa = source_arena.allocator();
        switch (source.kind) {
            .table => {
                const key = try column_identities.key(.{ .group = group, .table = source.table_id });
                var state = try column_identities.State.decode(sa, try reader.get(&key));
                defer state.deinit();
                try record.value.requireSource(index, state.value, false);
            },
            .view => {
                const key = try system_catalog_storage.recordKeyAlloc(sa, group, .view, source.table_id);
                const parent = try std.json.parseFromSliceLeaky(system_catalog.Resource, sa, try reader.get(key), .{});
                if (parent.kind != .view or parent.id != source.table_id) return error.InvalidSqlViewRecord;
                var state = try sql_views.Record.decode(sa, parent.source_json);
                defer state.deinit();
                if (state.value.id != source.table_id) return error.InvalidSqlViewRecord;
                try record.value.requireSource(index, state.value.attributes, false);
            },
        }
    }
    const dependencies = try record.value.dependencies(a);
    for (dependencies) |dependency| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        const key = try sql_views.dependencyKey(&key_buf, group, dependency, resource.id);
        if (!std.mem.eql(u8, try reader.get(key), &.{1})) return error.InvalidSqlViewRecord;
    }
    return dependencies.len;
}

fn validateSqlViewSnapshotCut(alloc: std.mem.Allocator, group: u64, rows: []const docstore.OwnedKVPair, values: *const std.StringHashMapUnmanaged([]const u8), cancelled: ?*const std.atomic.Value(bool)) !void {
    const Reader = struct {
        values: *const std.StringHashMapUnmanaged([]const u8),
        pub fn get(self: *@This(), key: []const u8) anyerror![]const u8 {
            return self.values.get(key) orelse error.NotFound;
        }
    };
    var reader: Reader = .{ .values = values };
    var expected: usize = 0;
    var actual: usize = 0;
    var names: std.StringHashMapUnmanaged(void) = .empty;
    defer freeSqlViewNames(alloc, &names);
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (try sql_views.recordId(row.key, group)) |id| {
            const key = try system_catalog_storage.recordKeyAlloc(alloc, group, .view, id);
            defer alloc.free(key);
            if (!std.mem.eql(u8, key, row.key)) return error.InvalidSqlViewRecord;
            expected = try std.math.add(usize, expected, try verifySqlViewRecord(alloc, &reader, group, id, row.value, &names, cancelled));
        } else if (try sql_views.dependencyFromKey(row.key, group) != null) {
            if (!std.mem.eql(u8, row.value, &.{1})) return error.InvalidSqlViewRecord;
            actual = try std.math.add(usize, actual, 1);
        }
    }
    if (expected != actual) return error.InvalidSqlViewRecord;
}

fn verifySqlViewCheckpointTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn) !void {
    var cursor = try txn.openCursor();
    defer cursor.close();
    var groups: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer groups.deinit(alloc);
    const prefix = sql_views.allGroupsPrefix();
    var row = try cursor.seekAtOrAfter(prefix);
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, prefix)) break;
        if (try sql_views.groupFromKey(item.key)) |group| try groups.put(alloc, group, {});
    }
    var iterator = groups.keyIterator();
    while (iterator.next()) |group| {
        var names: std.StringHashMapUnmanaged(void) = .empty;
        defer freeSqlViewNames(alloc, &names);
        var key_buf: [160]u8 = undefined;
        const records = try sql_views.recordPrefix(&key_buf, group.*);
        var expected: usize = 0;
        var current = try cursor.seekAtOrAfter(records);
        while (current) |item| : (current = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, records)) break;
            const id = (try sql_views.recordId(item.key, group.*)) orelse return error.InvalidSqlViewRecord;
            const key = try system_catalog_storage.recordKeyAlloc(alloc, group.*, .view, id);
            defer alloc.free(key);
            if (!std.mem.eql(u8, key, item.key)) return error.InvalidSqlViewRecord;
            expected = try std.math.add(usize, expected, try verifySqlViewRecord(alloc, txn, group.*, id, item.value, &names, null));
        }
        const edges = try sql_views.dependencyNamespacePrefix(&key_buf, group.*);
        var actual: usize = 0;
        current = try cursor.seekAtOrAfter(edges);
        while (current) |item| : (current = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, edges)) break;
            _ = (try sql_views.dependencyFromKey(item.key, group.*)) orelse return error.InvalidSqlViewRecord;
            if (!std.mem.eql(u8, item.value, &.{1})) return error.InvalidSqlViewRecord;
            actual = try std.math.add(usize, actual, 1);
        }
        if (expected != actual) return error.InvalidSqlViewRecord;
    }
}

fn validateColumnIdentityRecord(alloc: std.mem.Allocator, identity: column_identities.Key, bytes: []const u8, table_bytes: []const u8) !void {
    var state = try column_identities.State.decode(alloc, bytes);
    defer state.deinit();
    if (state.value.table_id != identity.table) return error.InvalidColumnIdentityState;
    const table = try decodeTableRecord(alloc, table_bytes);
    defer metadata_table_manager.freeTable(alloc, table);
    if (table.table_id != identity.table) return error.InvalidColumnIdentityState;
    const expected = try RaftApplyStore.columnIdentityValue(alloc, table, state.value, &.{});
    defer alloc.free(expected);
    if (!std.mem.eql(u8, bytes, expected)) return error.InvalidColumnIdentityState;
}

fn verifyColumnIdentityCheckpointTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn) !void {
    var cursor = try txn.openCursor();
    defer cursor.close();
    const prefix = column_identities.allGroupsPrefix();
    var current = try cursor.seekAtOrAfter(prefix);
    while (current) |row| : (current = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, prefix)) break;
        const identity = (try column_identities.decodeKey(row.key)) orelse return error.InvalidColumnIdentityState;
        var buf: [160]u8 = undefined;
        const table = try txn.get(try tableKeyForGroup(&buf, identity.group, identity.table));
        try validateColumnIdentityRecord(alloc, identity, row.value, table);
    }
}

/// Reuse the snapshot's existing borrowed-row index. Only active store headers
/// participate: an incomplete baseline may retain a weaker unpublished root,
/// but must revalidate the current floor before that root becomes visible.
/// Pending native retirement is part of the snapshot, never a reason to
/// silently drop report bytes. Validate its exact frozen scope before allowing
/// an inactive predecessor to lack serving-reader capabilities.
fn validateNativeRestartSnapshot(alloc: std.mem.Allocator, group_id: u64, values: *const std.StringHashMapUnmanaged([]const u8), bytes: []const u8) !standalone_native_owner.Registration {
    const record = try RaftApplyStore.decodeNativeRestart(alloc, bytes);
    const request = record.request;
    var buf: [256]u8 = undefined;
    const owner = try standalone_native_owner.decode(values.get(try standalone_native_owner.key(&buf, group_id)) orelse return error.InvalidMetadataSnapshot);
    if (!owner.eql(request.binding())) return error.InvalidMetadataSnapshot;
    const incarnation = try decodeMetadataIncarnationRecord(values.get(try metadataIncarnationKeyForGroup(&buf, group_id)) orelse return error.InvalidMetadataSnapshot);
    if (!std.mem.eql(u8, &incarnation.incarnation, &request.identity.metadata_incarnation)) return error.InvalidMetadataSnapshot;
    try metadata_table_manager.requireSchemaReaderAtFloor(incarnation.schema_reader_floor, .{ .store_id = request.identity.store_id, .node_id = request.identity.node_id, .reporter_incarnation = request.reporter_incarnation, .schema_reader = request.schema_reader });
    const raw = values.get(try storeKeyForGroup(&buf, group_id, request.identity.store_id));
    if ((raw != null) != (record.frozen_header != null)) return error.InvalidMetadataSnapshot;
    if (raw) |encoded| {
        const header = try RaftApplyStore.decodeStoredHeader(alloc, encoded);
        defer metadata_table_manager.freeStore(alloc, header);
        if (header.live or header.node_id != request.identity.node_id or header.store_id != request.identity.store_id or
            request.expected_reporter_incarnation == null or header.reporter_incarnation != request.expected_reporter_incarnation.? or
            header.replica_root_incarnation != request.identity.root_incarnation or
            (!std.mem.allEqual(u8, &header.replica_root_public_key, 0) and !std.mem.eql(u8, &header.replica_root_public_key, &request.identity.public_key)) or
            !std.mem.eql(u8, &record.frozen_header.?, &try RaftApplyStore.reportHeaderDigest(alloc, header))) return error.InvalidMetadataSnapshot;
    }
    const baseline_key = try RaftApplyStore.baselineKey(alloc, group_id, request.identity.store_id);
    defer alloc.free(baseline_key);
    var baseline: RaftApplyStore.BaselineState = .{};
    if (values.get(baseline_key)) |encoded| {
        var parsed = try std.json.parseFromSlice(RaftApplyStore.BaselineState, alloc, encoded, .{});
        defer parsed.deinit();
        baseline = parsed.value;
    }
    if (!std.meta.eql(baseline, record.baseline)) return error.InvalidMetadataSnapshot;
    return request;
}

fn validateSchemaReaderSnapshotCut(alloc: std.mem.Allocator, group_id: u64, rows: []const docstore.OwnedKVPair, values: *const std.StringHashMapUnmanaged([]const u8), cancelled: ?*const std.atomic.Value(bool)) !void {
    var buf: [160]u8 = undefined;
    var setting_buf: [160]u8 = undefined;
    const settings_prefix = try std.fmt.bufPrint(&setting_buf, "\x00\x00__metadata__:system_catalog:{d}:setting:", .{group_id});
    var table_buf: [128]u8 = undefined;
    const tables_prefix = try tablePrefixForGroup(&table_buf, group_id);
    var plan_buffers: [4][160]u8 = undefined;
    const plan_prefixes = [_][]const u8{
        try index_publication.planPrefix(&plan_buffers[0], group_id),
        try fk_generation_publication.prefixForGroup(&plan_buffers[1], group_id),
        try fk_generation_publication.initialPrefixForGroup(&plan_buffers[2], group_id),
        try restore_staging.jobPrefix(&plan_buffers[3], group_id),
    };
    var head_prefix_buf: [160]u8 = undefined;
    const heads_prefix = try index_publication.headPrefix(&head_prefix_buf, group_id);
    var native_key_buf: [192]u8 = undefined;
    const native_key = try standalone_native_owner.key(&native_key_buf, group_id);
    const restart_prefix = try std.fmt.allocPrint(alloc, "\x00\x00__metadata__:store_report_cursor_v1:{d}:native_restart:", .{group_id});
    defer alloc.free(restart_prefix);
    var required_version: u16 = 0;
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (std.mem.startsWith(u8, row.key, @import("../schema_validation_dependencies.zig").all_prefix)) {
            const record = (try @import("../schema_validation_dependencies.zig").Key.parse(row.key)) orelse return error.InvalidMetadataSnapshot;
            if (record.group != group_id) return error.InvalidMetadataSnapshot;
            required_version = @max(required_version, topology_protocol.schema_validation_publication_version);
        } else if (std.mem.startsWith(u8, row.key, schema_validation.all_prefix)) {
            const record = (try schema_validation.Key.parse(row.key)) orelse return error.InvalidMetadataSnapshot;
            if (record.group != group_id) return error.InvalidMetadataSnapshot;
            required_version = @max(required_version, topology_protocol.schema_validation_publication_version);
        } else if (std.mem.startsWith(u8, row.key, @import("../table_lifecycle_lock.zig").allGroupsPrefix()) and
            (try @import("../table_lifecycle_lock.zig").Lock.decode(row.value)).kind == .schema_validation)
        {
            required_version = @max(required_version, topology_protocol.schema_validation_publication_version);
        } else if (std.mem.startsWith(u8, row.key, settings_prefix)) {
            if (@import("../schema_reader_wire.zig").requiresRoleDefaults(row.value)) {
                required_version = @max(required_version, topology_protocol.sql_role_defaults_version);
                const Reader = struct {
                    a: std.mem.Allocator,
                    group: u64,
                    values: *const std.StringHashMapUnmanaged([]const u8),
                    pub fn requireDatabase(self: @This(), id: u64) !void {
                        if (id == system_catalog.default_database_id) return;
                        const key = try system_catalog_storage.recordKeyAlloc(self.a, self.group, .database, id);
                        defer self.a.free(key);
                        const bytes = self.values.get(key) orelse return error.InvalidMetadataSnapshot;
                        var database = std.json.parseFromSlice(system_catalog.Resource, self.a, bytes, .{}) catch |err| return if (err == error.OutOfMemory) err else error.InvalidMetadataSnapshot;
                        defer database.deinit();
                        if (database.value.kind != .database or database.value.id != id or database.value.parent_id != 0) return error.InvalidMetadataSnapshot;
                    }
                };
                var record = std.json.parseFromSlice(sql_settings.Record, alloc, row.value, .{}) catch |err| return if (err == error.OutOfMemory) err else error.InvalidMetadataSnapshot;
                defer record.deinit();
                record.value.validate() catch return error.InvalidMetadataSnapshot;
                try sql_settings.requireDatabaseBindings(alloc, record.value, null, Reader{ .a = alloc, .group = group_id, .values = values });
            }
        } else if (std.mem.startsWith(u8, row.key, restart_prefix)) {
            const request = try validateNativeRestartSnapshot(alloc, group_id, values, row.value);
            var restart_key_buf: [256]u8 = undefined;
            if (!std.mem.eql(u8, row.key, try standalone_native_owner.restartKey(&restart_key_buf, group_id, request.identity.store_id))) return error.InvalidMetadataSnapshot;
            required_version = @max(required_version, topology_protocol.native_reporter_restart_version);
        } else if (std.mem.eql(u8, row.key, native_key)) {
            _ = try standalone_native_owner.decode(row.value);
            required_version = @max(required_version, topology_protocol.index_delivery_version);
        } else if (std.mem.startsWith(u8, row.key, heads_prefix)) {
            const head = try index_progress.Head.decode(row.value);
            const decided = head.phase == .installing or head.phase == .releasing or head.phase == .published;
            required_version = @max(required_version, if (decided) topology_protocol.index_publication_decision_version else topology_protocol.index_publication_head_version);
            if (head.counts[@backingInt(index_progress.Action.released)] != 0)
                required_version = @max(required_version, topology_protocol.index_publication_release_version);
        } else if (std.mem.startsWith(u8, row.key, tables_prefix)) {
            const table_projection = try borrowTableProjection(row.value, .identity);
            if (table_projection.full_text_read_index != null)
                required_version = @max(required_version, topology_protocol.schema_validation_publication_version);
            if (table_projection.schema_reader_requirements != null) {
                required_version = @max(required_version, topology_protocol.schema_reader_publication_version);
            }
        } else {
            for (plan_prefixes) |prefix| {
                if (std.mem.startsWith(u8, row.key, prefix)) {
                    if (@import("../schema_reader_wire.zig").requiresTextGenerationBinding(row.value))
                        required_version = @max(required_version, topology_protocol.schema_validation_publication_version);
                    if (@import("../schema_reader_wire.zig").requiresPublication(row.value))
                        required_version = @max(required_version, topology_protocol.schema_reader_publication_version);
                    break;
                }
            }
        }
    }
    const encoded = values.get(try metadataIncarnationKeyForGroup(&buf, group_id)) orelse {
        if (required_version != 0) return error.InvalidMetadataSnapshot;
        return;
    };
    const incarnation = try decodeMetadataIncarnationRecord(encoded);
    const floor = incarnation.schema_reader_floor;
    if (!floor.active() and required_version == 0) return;
    const activation = values.get(try RaftApplyStore.topologyActivationKeyForGroup(&buf, group_id)) orelse return error.InvalidMetadataSnapshot;
    const required = @max(required_version, if (floor.active()) topology_protocol.schema_reader_floor_version else @as(u16, 0));
    if (!try schemaReaderDecoderActivationValidAt(alloc, activation, incarnation.incarnation, required)) return error.InvalidMetadataSnapshot;
    if (!floor.active()) return;
    var prefix_buf: [128]u8 = undefined;
    const prefix = try storePrefixForGroup(&prefix_buf, group_id);
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (!std.mem.startsWith(u8, row.key, prefix)) continue;
        const header = try RaftApplyStore.decodeStoredHeader(alloc, row.value);
        defer metadata_table_manager.freeStore(alloc, header);
        if (!header.live) {
            var restart_buf: [256]u8 = undefined;
            if (values.get(try standalone_native_owner.restartKey(&restart_buf, group_id, header.store_id))) |pending| {
                _ = try validateNativeRestartSnapshot(alloc, group_id, values, pending);
                continue;
            }
        }
        try metadata_table_manager.requireSchemaReaderAtFloor(floor, header);
    }
}

test "system catalog schema reader table snapshot protects marked definitions before native floor activation" {
    const a = std.testing.allocator;
    const group: u64 = 21;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/marked-snapshot", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    const incarnation = "11111111111111111111111111111111".*;
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    try writeMetadataIncarnationRecordTxn(&txn, group, .{ .incarnation = incarnation });
    var inc_buf: [160]u8 = undefined;
    const inc_key = try metadataIncarnationKeyForGroup(&inc_buf, group);
    const inc_bytes = try a.dupe(u8, try txn.get(inc_key));
    defer a.free(inc_bytes);
    var activation_buf: [160]u8 = undefined;
    const activation_key = try RaftApplyStore.topologyActivationKeyForGroup(&activation_buf, group);
    var activation: topology_protocol.Activation = .{ .version = topology_protocol.schema_reader_floor_version, .incarnation = incarnation, .member_count = 3, .membership_fingerprint = @splat(7) };
    const old = try std.json.Stringify.valueAlloc(a, activation, .{});
    defer a.free(old);
    activation.version = topology_protocol.schema_reader_publication_version;
    const current = try std.json.Stringify.valueAlloc(a, activation, .{});
    defer a.free(current);
    const large = try a.alloc(u8, 64 * 1024);
    defer a.free(large);
    @memset(large, 'x');
    const schema_json = try std.mem.concat(a, u8, &.{ "{\"version\":0,\"default_type\":\"doc\",\"document_schemas\":{\"doc\":{\"schema\":{\"type\":\"object\",\"description\":\"", large, "\"}}}}" });
    defer a.free(schema_json);
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .schema_json = schema_json, .schema_reader_requirements = .{ .semantic_version = 11, .encoding_version = 31 } };
    const encoded = try encodeTableRecord(a, table);
    defer a.free(encoded);
    var table_buf: [160]u8 = undefined;
    const table_key = try tableKeyForGroup(&table_buf, group, table.table_id);
    var rows = [_]docstore.OwnedKVPair{
        .{ .key = @constCast(inc_key), .value = inc_bytes },
        .{ .key = @constCast(activation_key), .value = old },
        .{ .key = @constCast(table_key), .value = encoded },
    };
    try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, group, &rows));
    rows[1].value = current;
    try validateMetadataSnapshotRows(a, group, &rows);
    try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, group, rows[1..]));
    const Check = struct {
        fn project(alloc: std.mem.Allocator, source: []const docstore.OwnedKVPair) !void {
            var values: std.StringHashMapUnmanaged([]const u8) = .empty;
            defer values.deinit(alloc);
            for (source) |row| try values.put(alloc, row.key, row.value);
            try validateSchemaReaderSnapshotCut(alloc, 21, source, &values, null);
        }
    };
    // The 64 KiB schema is borrowed, not copied into the projection scratch.
    var scratch: [4096]u8 = undefined;
    var fixed = std.heap.FixedBufferAllocator.init(&scratch);
    try Check.project(fixed.allocator(), &rows);
    const marked_plan = @constCast("{\"plan\":{\"after\":{\"schema_reader_requirements\":{\"semantic_version\":14,\"encoding_version\":31}}}}");
    var plan_buf: [160]u8 = undefined;
    const prefixes = .{ index_publication.planPrefix, fk_generation_publication.prefixForGroup, fk_generation_publication.initialPrefixForGroup, restore_staging.jobPrefix };
    inline for (prefixes) |prefix_fn| {
        rows[2] = .{ .key = @constCast(try prefix_fn(&plan_buf, group)), .value = marked_plan };
        rows[1].value = old;
        try std.testing.expectError(error.InvalidMetadataSnapshot, Check.project(a, &rows));
        rows[1].value = current;
        try Check.project(a, &rows);
    }
    // A later compact head needs v40 even when a preceding marked table has
    // already established v39. The reader pair may also be absent in a head.
    const progress = @import("antfly_local_sources").storage_db_relational_index_publication_progress;
    const head_bytes = try (progress.Head{ .plan_id = @splat(1), .plan_digest = @splat(2), .candidate_digest = @splat(3), .reservation_digest = @splat(4), .table_id = 7, .owner_count = 1 }).encode();
    var head_key_buf: [160]u8 = undefined;
    const head_key = try index_publication.headKey(&head_key_buf, group, 7);
    rows[2] = .{ .key = @constCast(table_key), .value = encoded };
    var with_head = [_]docstore.OwnedKVPair{ rows[0], rows[1], rows[2], .{ .key = @constCast(head_key), .value = @constCast(&head_bytes) } };
    try std.testing.expectError(error.InvalidMetadataSnapshot, Check.project(a, &with_head));
    activation.version = topology_protocol.index_publication_head_version;
    const newest = try std.json.Stringify.valueAlloc(a, activation, .{});
    defer a.free(newest);
    with_head[1].value = newest;
    try Check.project(a, &with_head);
    rows[2] = with_head[3];
    try std.testing.expectError(error.InvalidMetadataSnapshot, Check.project(a, &rows));
    rows[1].value = newest;
    try Check.project(a, &rows);
    // Opaque restore pointers are not JSON plans and require no new decoder.
    rows[2] = .{ .key = @constCast(try restore_staging.activeKey(&plan_buf, group, @splat(7))), .value = @constCast(&@as([16]u8, @splat(7))) };
    rows[1].value = old;
    try Check.project(a, &rows);
}

test "metadata raft apply store schema reader snapshot rejects incompatible active store headers" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/reader-floor-snapshot", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    var txn = try store.store.beginWriteTxn();
    defer txn.abort();
    const state: MetadataIncarnationRecord = .{ .incarnation = "0123456789abcdef0123456789abcdef".*, .schema_reader_floor = .{ .semantic_version = 30, .encoding_version = 31 } };
    try writeMetadataIncarnationRecordTxn(&txn, 21, state);
    var inc_buf: [160]u8 = undefined;
    const incarnation_key = try metadataIncarnationKeyForGroup(&inc_buf, 21);
    const incarnation_bytes = try a.dupe(u8, try txn.get(incarnation_key));
    defer a.free(incarnation_bytes);
    var activation_buf: [160]u8 = undefined;
    const activation_key = try RaftApplyStore.topologyActivationKeyForGroup(&activation_buf, 21);
    const activation = try readerFloorActivationForTest(a);
    defer a.free(activation);
    var store_buf: [160]u8 = undefined;
    const store_key = try storeKeyForGroup(&store_buf, 21, 1);
    var record: metadata.StoreRecord = .{ .store_id = 1, .node_id = 1, .reporter_incarnation = 11, .schema_reader = metadata_table_manager.SchemaReaderCapabilities.current };
    const capable = try encodeStoreRecord(a, record);
    defer a.free(capable);
    var rows = [_]docstore.OwnedKVPair{
        .{ .key = @constCast(incarnation_key), .value = incarnation_bytes },
        .{ .key = @constCast(store_key), .value = capable },
        .{ .key = @constCast(activation_key), .value = activation },
    };
    try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, 21, rows[0..2]));
    try validateMetadataSnapshotRows(a, 21, &rows);
    const version_digit = (std.mem.indexOf(u8, activation, "\"version\":38") orelse return error.TestUnexpectedResult) + "\"version\":3".len;
    activation[version_digit] = '7';
    try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, 21, &rows));
    activation[version_digit] = '8';
    for ([_]metadata_table_manager.SchemaReaderCapabilities{
        .{}, .{ .semantic_ceiling = 29, .encoding_ceiling = 31 }, .{ .semantic_ceiling = 31, .encoding_ceiling = 30 },
    }) |insufficient| {
        record.schema_reader = insufficient;
        const invalid = try encodeStoreRecord(a, record);
        defer a.free(invalid);
        rows[1].value = invalid;
        try std.testing.expectError(error.InvalidMetadataSnapshot, validateMetadataSnapshotRows(a, 21, &rows));
    }
    record.schema_reader = .{};
    record.role = "metadata";
    const metadata_only = try encodeStoreRecord(a, record);
    defer a.free(metadata_only);
    rows[1].value = metadata_only;
    try validateMetadataSnapshotRows(a, 21, &rows);
}

/// Validate outside the apply lock, using borrowed snapshot rows and one
/// transient names-only table cut at a time. Every expected claim must match
/// exactly; equal total cardinality then excludes unrelated injected claims.
/// This is verification, never a repair or a hot-path catalog scan.
fn validateRelationSnapshotCut(alloc: std.mem.Allocator, group_id: u64, rows: []const docstore.OwnedKVPair, values: *const std.StringHashMapUnmanaged([]const u8), cancelled: ?*const std.atomic.Value(bool)) !void {
    const Reader = struct {
        values: *const std.StringHashMapUnmanaged([]const u8),
        pub fn get(self: *@This(), key: []const u8) anyerror![]const u8 {
            return self.values.get(key) orelse error.NotFound;
        }
    };
    var reader: Reader = .{ .values = values };
    var reconciliation = try relation_reconciliation.Verifier(Reader).init(&reader, group_id);
    var buf: [160]u8 = undefined;
    const writer = values.get(try RaftApplyStore.relationWriterKeyForGroup(&buf, group_id));
    var live_prefix_buf: [relation_reconciliation.max_cursor_bytes]u8 = undefined;
    const live_prefix = if (reconciliation.live) |live| blk: {
        if (writer == null or !live.epoch.eql(try RaftApplyStore.relationSourceEpochTxn(&reader, group_id))) return error.InvalidMetadataSnapshot;
        break :blk try relation_reconciliation.candidateGenerationPrefix(&live_prefix_buf, live.generation);
    } else null;
    var received: usize = 0;
    var index_jobs: IndexPublicationVerification = .{};
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        try reconciliation.feed(row.key, row.value);
        try index_jobs.feed(alloc, &reader, group_id, row.key, row.value);
        if (try relation_names.Key.fromStorageKey(row.key, group_id) != null) {
            _ = try relation_names.Entry.decode(row.value);
            if (live_prefix == null) received += 1;
        }
        if (live_prefix) |prefix| if (std.mem.startsWith(u8, row.key, prefix)) {
            received += 1;
        };
    }
    try reconciliation.finish();
    if (index_jobs.expected[3] != 0) {
        const ranges = try rangePrefixForGroup(&buf, group_id);
        for (rows) |row| {
            if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
            if (std.mem.startsWith(u8, row.key, ranges)) try IndexPublicationVerification.verifyRange(&reader, group_id, row.key, row.value);
        }
    }
    try index_jobs.finish();
    if (writer == null) {
        if (index_jobs.has_records) return error.InvalidMetadataSnapshot;
        if (received != 0) return error.InvalidMetadataSnapshot;
        return;
    }
    if (!std.mem.eql(u8, writer.?, "AFRW01")) return error.InvalidMetadataSnapshot;
    var registry = try RaftApplyStore.RelationRegistry(Reader).init(alloc, &reader, group_id);
    var restores: RaftApplyStore.RelationRestoreOwnerCache(Reader) = .{ .a = alloc, .txn = &reader, .group_id = group_id };
    defer restores.deinit();
    var restored: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer restored.deinit(alloc);
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        const source = (try RaftApplyStore.relationRestoreSourceKey(row.key, group_id)) orelse continue;
        switch (source) {
            .active => |id| if (!try restores.loadJob(id)) return error.InvalidMetadataSnapshot,
            else => {},
        }
    }
    var expected: usize = 0;
    for (rows) |row| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        if (try system_catalog_storage.tableIdFromRecordKey(row.key, group_id)) |id| {
            // A binding with no physical table must not disappear from a
            // table-only scan and accidentally certify an incomplete cut.
            _ = try reader.get(try tableKeyForGroup(&buf, group_id, id));
            var binding = (try system_catalog_storage.getById(alloc, &reader, group_id, .table, id)) orelse return error.InvalidMetadataSnapshot;
            defer binding.deinit();
        }
        const prefix = try tablePrefixForGroup(&buf, group_id);
        const count = if (std.mem.startsWith(u8, row.key, prefix)) blk: {
            const id = (try RaftApplyStore.capturedRelationTableId(row.key, group_id)) orelse return error.InvalidMetadataSnapshot;
            break :blk try verifyRelationWriterTableCut(alloc, &reader, group_id, id, &restores, &restored, &registry);
        } else if (try RaftApplyStore.relationInitialWorkTableId(row.key, group_id)) |id|
            try verifyRelationInitialCut(alloc, &reader, group_id, id, &registry)
        else
            continue;
        expected = std.math.add(usize, expected, count) catch return error.InvalidMetadataSnapshot;
    }
    expected = std.math.add(usize, expected, try verifyRelationRestoreRemainder(alloc, &reader, group_id, &restores, &restored, cancelled, &registry)) catch return error.InvalidMetadataSnapshot;
    if (expected != received) return error.InvalidMetadataSnapshot;
}

fn verifyRelationTableCut(alloc: std.mem.Allocator, reader: anytype, group_id: u64, table_id: u64, registry: anytype) !usize {
    var table = try RaftApplyStore.relationWriterSnapshotWithCoverage(alloc, reader, group_id, table_id, true, registry.coverage());
    defer table.deinit();
    return verifyRelationClaims(registry, table.claims());
}
fn verifyRelationWriterTableCut(alloc: std.mem.Allocator, reader: anytype, group: u64, table_id: u64, restores: anytype, seen: *std.AutoHashMapUnmanaged(u64, void), registry: anytype) !usize {
    if (try restores.lookup(table_id, null)) |proof| return verifyRelationRestoreTarget(alloc, reader, group, proof.plan_id, proof.target, seen, registry);
    return verifyRelationTableCut(alloc, reader, group, table_id, registry);
}
fn verifyRelationRestoreTarget(alloc: std.mem.Allocator, reader: anytype, group: u64, plan_id: [16]u8, target: RaftApplyStore.RelationRestoreProjection.Target, seen: *std.AutoHashMapUnmanaged(u64, void), registry: anytype) !usize {
    if (seen.contains(target.table.table_id)) return 0;
    var cut = try RaftApplyStore.relationRestoreTargetSnapshotWithCoverage(alloc, reader, group, plan_id, target, false, registry.coverage());
    defer cut.deinit();
    const count = try verifyRelationClaims(registry, cut.claims());
    try seen.put(alloc, target.table.table_id, {});
    return count;
}
fn verifyRelationRestoreRemainder(alloc: std.mem.Allocator, reader: anytype, group: u64, restores: anytype, seen: *std.AutoHashMapUnmanaged(u64, void), cancelled: ?*const std.atomic.Value(bool), registry: anytype) !usize {
    var count: usize = 0;
    var jobs = restores.jobs.valueIterator();
    while (jobs.next()) |job| for (job.value.plan.targets) |target| {
        if (cancelled) |flag| if (flag.load(.acquire)) return error.SnapshotBuildCancelled;
        count = std.math.add(usize, count, try verifyRelationRestoreTarget(alloc, reader, group, job.value.plan.id, target, seen, registry)) catch return error.InvalidCatalogRecord;
    };
    return count;
}
fn verifyRelationInitialCut(alloc: std.mem.Allocator, reader: anytype, group_id: u64, table_id: u64, registry: anytype) !usize {
    var hidden = try RaftApplyStore.relationInitialSnapshotWithCoverage(alloc, reader, group_id, table_id, registry.coverage());
    defer hidden.deinit();
    if (hidden.claims().len == 0) return error.InvalidCatalogRecord;
    return verifyRelationClaims(registry, hidden.claims());
}
fn verifyRelationClaims(registry: anytype, claims: []const relation_names.Claim) !usize {
    for (claims) |claim| {
        const entry = (try registry.getEntry(claim.key)) orelse return error.InvalidCatalogRecord;
        if (!entry.eql(try claim.entry())) return error.InvalidCatalogRecord;
    }
    return claims.len;
}

/// Offline checkpoint verification. Cursors lend bytes; only one table's
/// decoded projection/names occupy scratch at once. No whole-catalog map,
/// independent transaction, repair, or user-data scan is needed.
/// Shared only by verification of the new private index-job record classes.
/// Snapshots without these records/index-build locks keep their existing path.
const IndexPublicationVerification = struct {
    expected: [10]usize = @splat(0),
    received: [10]usize = @splat(0),
    has_records: bool = false,

    /// Reverse cohort proof: each current range of a live job must resolve to
    /// its admitted owner. Forward proof checks the full descriptor separately.
    /// Consume borrowed results before the next read; no plan decode/allocation.
    fn verifyRange(reader: anytype, group: u64, key: []const u8, value: []const u8) !void {
        var pos: usize = 0;
        const range_group = readInt(value, &pos, u64) catch return error.InvalidCatalogRecord;
        const table = readInt(value, &pos, u64) catch return error.InvalidCatalogRecord;
        var buf: [160]u8 = undefined;
        const canonical = std.mem.eql(u8, key, try rangeKeyForGroup(&buf, group, range_group));
        const head_bytes = reader.get(try index_publication.headKey(&buf, group, table)) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        const head = index_progress.Head.decode(head_bytes) catch return error.InvalidCatalogRecord;
        if (head.phase == .published or head.phase == .canceled) return;
        if (head.table_id != table or !canonical) return error.InvalidCatalogRecord;
        const ordinal = try index_publication.ownerOrdinal(reader, group, table, range_group);
        if (ordinal >= head.owner_count) return error.InvalidCatalogRecord;
        const owner = index_progress.OwnerState.decode(try reader.get(try index_publication.ownerKey(&buf, group, table, ordinal))) catch return error.InvalidCatalogRecord;
        if (owner.owner.ordinal != ordinal or owner.owner.group_id != range_group or
            !std.mem.eql(u8, &owner.owner.plan_id, &head.plan_id) or
            !std.mem.eql(u8, &owner.owner.plan_digest, &head.plan_digest)) return error.InvalidCatalogRecord;
    }

    /// Verify logical authority by stable catalog IDs, not name-index scans or
    /// the admission root's old revision (the job itself advances that root).
    fn verifyAuthority(a: std.mem.Allocator, reader: anytype, group: u64, plan: anytype, table: anytype) !void {
        const epoch = try RaftApplyStore.relationSourceEpochTxn(reader, group);
        if (!std.mem.eql(u8, &epoch.incarnation, &plan.table_guard.incarnation)) return error.InvalidCatalogRecord;
        const target = plan.table_guard.target;
        var namespace = try system_catalog_storage.getById(a, reader, group, .namespace, plan.namespace_id);
        defer if (namespace) |*resource| resource.deinit();
        const database_id = if (namespace) |resource| blk: {
            if (!std.mem.eql(u8, resource.value.name, target.namespace)) return error.InvalidCatalogRecord;
            break :blk resource.value.parent_id;
        } else blk: {
            if (plan.namespace_id != system_catalog.default_namespace_id or
                !std.mem.eql(u8, target.namespace, system_catalog.default_namespace_name)) return error.InvalidCatalogRecord;
            break :blk system_catalog.default_database_id;
        };
        var database = try system_catalog_storage.getById(a, reader, group, .database, database_id);
        defer if (database) |*resource| resource.deinit();
        if (database) |resource| {
            if (resource.value.parent_id != 0 or !std.mem.eql(u8, resource.value.name, target.database)) return error.InvalidCatalogRecord;
        } else if (database_id != system_catalog.default_database_id or
            !std.mem.eql(u8, target.database, system_catalog.default_database_name)) return error.InvalidCatalogRecord;
        var binding = try system_catalog_storage.getById(a, reader, group, .table, table.table_id);
        defer if (binding) |*resource| resource.deinit();
        if (binding) |resource| {
            if (resource.value.parent_id != plan.namespace_id or
                !std.mem.eql(u8, resource.value.name, plan.table_guard.logical_table) or
                !std.mem.eql(u8, resource.value.storage_name, table.name)) return error.InvalidCatalogRecord;
        } else if (plan.namespace_id != system_catalog.default_namespace_id or
            !std.mem.eql(u8, table.name, plan.table_guard.logical_table)) return error.InvalidCatalogRecord;
    }

    fn verifyTableCut(a: std.mem.Allocator, reader: anytype, group: u64, id: u64) !index_progress.Head {
        return verifyTableCutWithReceiptCount(a, reader, group, id, null, null);
    }

    fn verifyTableCutWithReceiptCount(a: std.mem.Allocator, reader: anytype, group: u64, id: u64, receipt_count: ?*usize, delivery_counts: ?*[2]usize) !index_progress.Head {
        var proof = try index_publication.verifyOwned(a, reader, group, id);
        defer proof.deinit();
        if (receipt_count) |count| count.* = proof.receipt_count;
        if (delivery_counts) |count| count.* = proof.delivery_counts;
        var buf: [160]u8 = undefined;
        const current = decodeTableRecord(a, try reader.get(try tableKeyForGroup(&buf, group, id))) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidCatalogRecord,
        };
        defer metadata_table_manager.freeTable(a, current);
        if (current.table_id != id) return error.InvalidCatalogRecord;
        // Terminal history may outlive later DDL/topology. Only a live job
        // owns the immutable table/range cut protected by its lifecycle lock.
        if (proof.head.phase == .published or proof.head.phase == .canceled) return proof.head;
        const plan = proof.plan.value;
        const expected = if (proof.head.phase == .installing or proof.head.phase == .releasing) plan.after else plan.before;
        if (!metadata_table_manager.tableDefinitionsEqual(current, expected)) return error.InvalidCatalogRecord;
        try verifyAuthority(a, reader, group, plan, current);
        for (plan.owners) |owner| {
            const range = decodeRangeRecord(a, try reader.get(try rangeKeyForGroup(&buf, group, owner.range.group_id))) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return error.InvalidCatalogRecord,
            };
            defer metadata_table_manager.freeRange(a, range);
            if (!metadata_table_manager.rangeRecordsEqual(range, owner.range)) return error.InvalidCatalogRecord;
        }
        return proof.head;
    }

    fn feed(self: *@This(), a: std.mem.Allocator, reader: anytype, group: u64, key: []const u8, value: []const u8) !void {
        var buf: [160]u8 = undefined;
        if (try index_delivery.Key.parse(key)) |delivery_key| {
            if (delivery_key.group != group) return error.InvalidCatalogRecord;
            self.has_records = true;
            self.received[if (delivery_key.kind == .source) @as(usize, 8) else 9] += 1;
        } else if (std.mem.startsWith(u8, key, index_publication.allGroupsPrefix())) {
            if (try index_publication.groupFromKey(key) != group) return error.InvalidCatalogRecord;
            self.has_records = true;
            if (try index_publication.sourceKey(key, group)) |source| switch (source) {
                .plan => |id| {
                    var receipt_count: usize = 0;
                    var delivery_counts: [2]usize = undefined;
                    const head = try verifyTableCutWithReceiptCount(a, reader, group, id, &receipt_count, &delivery_counts);
                    self.expected[8] = std.math.add(usize, self.expected[8], delivery_counts[0]) catch return error.InvalidCatalogRecord;
                    self.expected[9] = std.math.add(usize, self.expected[9], delivery_counts[1]) catch return error.InvalidCatalogRecord;
                    self.expected[7] = std.math.add(usize, self.expected[7], receipt_count) catch return error.InvalidCatalogRecord;
                    self.expected[0] += 1;
                    self.expected[1] += switch (head.phase) {
                        .installing, .releasing, .published, .canceled => @as(usize, 0),
                        else => 1,
                    };
                    self.expected[2] = std.math.add(usize, self.expected[2], head.owner_count) catch return error.InvalidCatalogRecord;
                    self.expected[4] = std.math.add(usize, self.expected[4], head.owner_count) catch return error.InvalidCatalogRecord;
                    self.expected[5] += 1;
                    self.expected[6] = std.math.add(usize, self.expected[6], head.owner_count) catch return error.InvalidCatalogRecord;
                    self.expected[3] += if (head.phase == .published or head.phase == .canceled) @as(usize, 0) else 1;
                    return;
                },
                .active => {
                    self.received[1] += 1;
                    return;
                },
            };
            if (std.mem.startsWith(u8, key, try index_publication.headPrefix(&buf, group))) self.received[0] += 1 else if (std.mem.startsWith(u8, key, try index_publication.ownersPrefix(&buf, group))) self.received[2] += 1 else if (std.mem.startsWith(u8, key, try index_publication.ownerGroupsPrefix(&buf, group))) self.received[4] += 1 else if (std.mem.startsWith(u8, key, try index_publication.inputsPrefix(&buf, group))) self.received[5] += 1 else if (std.mem.startsWith(u8, key, try index_publication.dispatchPrefix(&buf, group))) self.received[6] += 1 else if (std.mem.startsWith(u8, key, try index_publication.proofsPrefix(&buf, group))) self.received[7] += 1 else return error.InvalidCatalogRecord;
        } else if (std.mem.startsWith(u8, key, @import("../table_lifecycle_lock.zig").allGroupsPrefix())) {
            const lifecycle = @import("../table_lifecycle_lock.zig");
            const lock = lifecycle.Lock.decode(value) catch return error.InvalidCatalogRecord;
            if (lock.kind != .index_build) return;
            if (try lifecycle.groupFromKey(key) != group) return error.InvalidCatalogRecord;
            self.has_records = true;
            self.received[3] += 1;
        }
    }
    fn finish(self: @This()) !void {
        if (!std.meta.eql(self.expected, self.received)) return error.InvalidCatalogRecord;
    }
};

fn verifyIndexPublicationGroupTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64) !void {
    var cursor = try txn.openCursor();
    defer cursor.close();
    var buf: [160]u8 = undefined;
    // Forward verification point-reads every required row. Equal reverse counts
    // then exclude extras/orphans without retaining all jobs in a hash table.
    var verification: IndexPublicationVerification = .{};
    const fns = .{ index_publication.planPrefix, index_publication.headPrefix, index_publication.activePrefix, index_publication.ownersPrefix, index_publication.ownerGroupsPrefix, index_publication.inputsPrefix, index_publication.dispatchPrefix, index_publication.proofsPrefix, index_delivery.sourcesPrefix, index_delivery.targetsPrefix, fk_generation_publication.tableLockPrefix };
    inline for (fns) |prefix_fn| {
        const owned = try prefix_fn(&buf, group_id);
        var row = try cursor.seekAtOrAfter(owned);
        while (row) |item| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, owned)) break;
            try verification.feed(alloc, txn, group_id, item.key, item.value);
        }
    }
    if (verification.expected[3] != 0) {
        const ranges = try rangePrefixForGroup(&buf, group_id);
        var row = try cursor.seekAtOrAfter(ranges);
        while (row) |item| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, ranges)) break;
            try IndexPublicationVerification.verifyRange(txn, group_id, item.key, item.value);
        }
    }
    try verification.finish();
}

fn verifyRelationGroupTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn, group_id: u64) !void {
    if (!try RaftApplyStore.relationWriterEnabledTxn(txn, group_id)) return error.InvalidCatalogRecord;
    try verifyIndexPublicationGroupTxn(alloc, txn, group_id);
    var registry = try RaftApplyStore.RelationRegistry(docstore.DocStore.Txn).init(alloc, txn, group_id);
    const live = registry.live;
    if (live) |value| if (!value.root.epoch.eql(try RaftApplyStore.relationSourceEpochTxn(txn, group_id))) return error.InvalidCatalogRecord;
    var cursor = try txn.openCursor();
    defer cursor.close();
    var buf: [160]u8 = undefined;
    var restores: RaftApplyStore.RelationRestoreProofCache = .{ .a = alloc, .txn = txn, .group_id = group_id };
    defer restores.deinit();
    var restored: std.AutoHashMapUnmanaged(u64, void) = .empty;
    defer restored.deinit(alloc);
    const active = try restore_staging.activePrefix(&buf, group_id);
    var active_row = try cursor.seekAtOrAfter(active);
    while (active_row) |row| : (active_row = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, active)) break;
        const source = (try RaftApplyStore.relationRestoreSourceKey(row.key, group_id)) orelse return error.InvalidCatalogRecord;
        switch (source) {
            .active => |id| if (!try restores.loadJob(id)) return error.InvalidCatalogRecord,
            else => return error.InvalidCatalogRecord,
        }
    }
    var expected: usize = 0;
    const tables = try tablePrefixForGroup(&buf, group_id);
    var entry = try cursor.seekAtOrAfter(tables);
    while (entry) |row| : (entry = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, tables)) break;
        const id = (try RaftApplyStore.capturedRelationTableId(row.key, group_id)) orelse return error.InvalidCatalogRecord;
        var scratch = std.heap.ArenaAllocator.init(alloc);
        defer scratch.deinit();
        // Cache/seen allocations must outlive this one-table scratch arena.
        if (try restores.lookup(id, null)) |proof| {
            expected = std.math.add(usize, expected, try verifyRelationRestoreTarget(alloc, txn, group_id, proof.plan_id, proof.target, &restored, &registry)) catch return error.InvalidCatalogRecord;
        } else expected = std.math.add(usize, expected, try verifyRelationTableCut(scratch.allocator(), txn, group_id, id, &registry)) catch return error.InvalidCatalogRecord;
    }
    const initial = try fk_generation_publication.initialWorkPrefixForGroup(&buf, group_id);
    entry = try cursor.seekAtOrAfter(initial);
    while (entry) |row| : (entry = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, initial)) break;
        const id = (try RaftApplyStore.relationInitialWorkTableId(row.key, group_id)) orelse return error.InvalidCatalogRecord;
        var scratch = std.heap.ArenaAllocator.init(alloc);
        defer scratch.deinit();
        // A hidden work row may never double-count a public table. Its exact
        // reservation pointers and absence of public identity are dependencies.
        expected = std.math.add(usize, expected, try verifyRelationInitialCut(scratch.allocator(), txn, group_id, id, &registry)) catch return error.InvalidCatalogRecord;
    }
    const bindings = try system_catalog_storage.tableRecordPrefixForGroup(&buf, group_id);
    entry = try cursor.seekAtOrAfter(bindings);
    while (entry) |row| : (entry = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, bindings)) break;
        const id = (try system_catalog_storage.tableIdFromRecordKey(row.key, group_id)) orelse return error.InvalidCatalogRecord;
        var physical_buf: [160]u8 = undefined;
        _ = try txn.get(try tableKeyForGroup(&physical_buf, group_id, id));
    }
    const claims = if (live) |value| try relation_reconciliation.candidateGenerationPrefix(&buf, value.root.generation) else try relation_names.Key.prefixForGroup(&buf, group_id);
    var received: usize = 0;
    entry = try cursor.seekAtOrAfter(claims);
    while (entry) |row| : (entry = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, claims)) break;
        if (live) |value| {
            _ = try relation_reconciliation.logicalLiveCandidateKey(row.key, value.root);
        } else _ = (try relation_names.Key.fromStorageKey(row.key, group_id)) orelse return error.InvalidCatalogRecord;
        _ = try relation_names.Entry.decode(row.value);
        received += 1;
    }
    expected = std.math.add(usize, expected, try verifyRelationRestoreRemainder(alloc, txn, group_id, &restores, &restored, null, &registry)) catch return error.InvalidCatalogRecord;
    if (expected != received) return error.InvalidCatalogRecord;
}

fn verifyRelationCheckpointTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn) !void {
    verifyRelationCheckpointGroupsTxn(alloc, txn) catch |err| switch (err) {
        error.InvalidCatalogRecord, error.InvalidCatalogName, error.InvalidMetadataIncarnation, error.CatalogSourceUntracked, error.NotFound, error.CatalogAlreadyExists, error.CatalogCommandTooLarge => return error.InvalidMetadataHACheckpoint,
        else => return err,
    };
}

const SchemaValidationCheckpoint = struct {
    alloc: std.mem.Allocator,
    group: u64,

    pub fn restore(self: @This(), txn: *docstore.DocStore.Txn, recovery: *const schema_validation.Recovery) !void {
        const plan = recovery.plan.value;
        const head = recovery.head;
        var buf: [192]u8 = undefined;
        const incarnation = (try decodeMetadataIncarnationRecord(try txn.get(try metadataIncarnationKeyForGroup(&buf, self.group)))).incarnation;
        if (head.metadata_group_id != self.group or !std.mem.eql(u8, &incarnation, &head.metadata_incarnation)) return error.InvalidCatalogRecord;
        if (head.phase == .succeeded or head.phase == .canceled) return;
        if (!try RaftApplyStore.relationWriterEnabledTxn(txn, self.group)) return error.InvalidCatalogRecord;
        const guard = plan.table_guard orelse return error.InvalidCatalogRecord;
        const expected = if (head.phase == .releasing) plan.after else plan.before;
        const current = try decodeTableRecord(self.alloc, try txn.get(try tableKeyForGroup(&buf, self.group, head.table_id)));
        defer metadata_table_manager.freeTable(self.alloc, current);
        if (!metadata_table_manager.tableDefinitionsEqual(current, expected)) return error.InvalidCatalogRecord;
        const namespace = (try RaftApplyStore.resolveSystemCatalogNamespaceTxn(self.alloc, txn, self.group, guard.target.database, guard.target.namespace)) orelse return error.InvalidCatalogRecord;
        try IndexPublicationVerification.verifyAuthority(self.alloc, txn, self.group, .{ .table_guard = guard, .namespace_id = namespace }, expected);
        for (plan.owners) |owner| {
            const range = try decodeRangeRecord(self.alloc, try txn.get(try rangeKeyForGroup(&buf, self.group, owner.range.group_id)));
            defer metadata_table_manager.freeRange(self.alloc, range);
            if (!metadata_table_manager.rangeRecordsEqual(range, owner.range)) return error.InvalidCatalogRecord;
        }
        // Forward point reads prove every required owner; a reverse count
        // proves that no extra live range escaped the immutable cohort.
        var cursor = try txn.openCursor();
        defer cursor.close();
        const ranges_prefix = try rangePrefixForGroup(&buf, self.group);
        var row = try cursor.seekAtOrAfter(ranges_prefix);
        var count: usize = 0;
        while (row) |item| : (row = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, ranges_prefix)) break;
            const range = try decodeRangeRecord(self.alloc, item.value);
            defer metadata_table_manager.freeRange(self.alloc, range);
            if (range.table_id != head.table_id) continue;
            var key_buf: [192]u8 = undefined;
            if (!std.mem.eql(u8, item.key, try rangeKeyForGroup(&key_buf, self.group, range.group_id))) return error.InvalidCatalogRecord;
            count = try std.math.add(usize, count, 1);
            if (count > head.owner_count) return error.InvalidCatalogRecord;
        }
        if (count != head.owner_count) return error.InvalidCatalogRecord;
    }
};

fn verifySchemaValidationCheckpointTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn) !void {
    var cursor = try txn.openCursor();
    defer cursor.close();
    var row = try cursor.seekAtOrAfter(schema_validation.all_prefix);
    var previous_group: ?u64 = null;
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, schema_validation.all_prefix)) break;
        const key = (try schema_validation.Key.parse(item.key)) orelse return error.InvalidCatalogRecord;
        if (!try RaftApplyStore.relationWriterEnabledTxn(txn, key.group)) return error.InvalidCatalogRecord;
        if (previous_group != key.group) {
            try schema_validation.verifyGroup(alloc, txn, key.group, SchemaValidationCheckpoint{ .alloc = alloc, .group = key.group });
            previous_group = key.group;
        }
    }
    const dependencies = @import("../schema_validation_dependencies.zig");
    row = try cursor.seekAtOrAfter(dependencies.all_prefix);
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, dependencies.all_prefix)) break;
        const key = (try dependencies.Key.parse(item.key)) orelse return error.InvalidCatalogRecord;
        var head_buf: [192]u8 = undefined;
        const head_key: schema_validation.Key = .{ .group = key.group, .table = key.child, .id = key.id, .kind = .head };
        const head = try @import("../schema_validation_publication.zig").Head.decode(try txn.get(try head_key.encode(&head_buf)));
        if (head.metadata_group_id != key.group or head.table_id != key.child or !std.mem.eql(u8, &head.id, &key.id) or
            head.phase == .succeeded or head.phase == .canceled) return error.InvalidCatalogRecord;
        const owner = try schema_validation.readOwner(txn, head, 0);
        if (owner.binding.purpose != .foreign_key_source or key.ordinal >= owner.binding.columns) return error.InvalidCatalogRecord;
        if (key.parent != null) {
            const record = try dependencies.Record.decode(item.value);
            if (!std.meta.eql(record.key, key) or !std.mem.eql(u8, &record.plan_digest, &head.plan_digest) or
                !std.mem.eql(u8, &record.metadata_incarnation, &head.metadata_incarnation)) return error.InvalidCatalogRecord;
            const expected = @import("antfly_local_sources").storage_db_relational_schema_owner_contract.hash(item.value);
            var index_key = key;
            index_key.parent = null;
            var index_buf: [256]u8 = undefined;
            const index = try txn.get(try index_key.encode(&index_buf));
            if (index.len != 40 or std.mem.readInt(u64, index[0..8], .little) != key.parent.? or !std.mem.eql(u8, index[8..40], &expected)) return error.InvalidCatalogRecord;
        } else {
            if (item.value.len != 40) return error.InvalidCatalogRecord;
            var parent_key = key;
            parent_key.parent = std.mem.readInt(u64, item.value[0..8], .little);
            const expected = item.value[8..40].*;
            var parent_buf: [256]u8 = undefined;
            const bytes = try txn.get(try parent_key.encode(&parent_buf));
            if (!std.mem.eql(u8, &@import("antfly_local_sources").storage_db_relational_schema_owner_contract.hash(bytes), &expected)) return error.InvalidCatalogRecord;
            const record = try dependencies.Record.decode(bytes);
            if (!std.meta.eql(record.key, parent_key) or !std.mem.eql(u8, &record.metadata_incarnation, &head.metadata_incarnation) or
                !std.mem.eql(u8, &record.plan_digest, &head.plan_digest)) return error.InvalidCatalogRecord;
        }
    }
    // The forward cohort audit requires every live job's shared lock. Also
    // reject the reverse orphan: a lock with no ledger must not freeze a table
    // forever while evading the schema-validation namespace scan.
    const lifecycle = @import("../table_lifecycle_lock.zig");
    row = try cursor.seekAtOrAfter(lifecycle.allGroupsPrefix());
    while (row) |item| : (row = try cursor.next()) {
        if (!std.mem.startsWith(u8, item.key, lifecycle.allGroupsPrefix())) break;
        const lock = try lifecycle.Lock.decode(item.value);
        if (lock.kind != .schema_validation) continue;
        const group = (try lifecycle.groupFromKey(item.key)) orelse return error.InvalidCatalogRecord;
        const table = (try lifecycle.tableFromKey(item.key)) orelse return error.InvalidCatalogRecord;
        var key_buf: [192]u8 = undefined;
        const key: schema_validation.Key = .{ .group = group, .table = table, .id = lock.id, .kind = .head };
        const head = try @import("../schema_validation_publication.zig").Head.decode(try txn.get(try key.encode(&key_buf)));
        if (head.metadata_group_id != group or head.table_id != table or !std.mem.eql(u8, &head.id, &lock.id) or
            head.phase == .succeeded or head.phase == .canceled) return error.InvalidCatalogRecord;
    }
}

fn verifyRelationCheckpointGroupsTxn(alloc: std.mem.Allocator, txn: *docstore.DocStore.Txn) !void {
    try verifySchemaValidationCheckpointTxn(alloc, txn);
    try verifyColumnIdentityCheckpointTxn(alloc, txn);
    verifySqlSequenceCheckpointTxn(alloc, txn) catch |err| switch (err) {
        error.OutOfMemory, error.Canceled, error.SnapshotBuildCancelled => return err,
        else => return error.InvalidCatalogRecord,
    };
    verifySqlViewCheckpointTxn(alloc, txn) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => return error.InvalidCatalogRecord,
    };
    try verifyReconciliationCheckpointTxn(txn);
    var cursor = try txn.openCursor();
    defer cursor.close();
    const index_prefix = index_publication.allGroupsPrefix();
    var index_row = try cursor.seekAtOrAfter(index_prefix);
    while (index_row) |row| : (index_row = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, index_prefix)) break;
        const group = (try index_publication.groupFromKey(row.key)) orelse return error.InvalidCatalogRecord;
        if (!try RaftApplyStore.relationWriterEnabledTxn(txn, group)) return error.InvalidCatalogRecord;
    }
    // A lock without any index job/source must not evade the marker scan.
    // Legacy FK lock kinds may predate adoption; only the new index kind
    // requires the versioned index job and adopted relation writer.
    const lifecycle = @import("../table_lifecycle_lock.zig");
    const lock_prefix = lifecycle.allGroupsPrefix();
    var lock_row = try cursor.seekAtOrAfter(lock_prefix);
    while (lock_row) |row| : (lock_row = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, lock_prefix)) break;
        const lock = lifecycle.Lock.decode(row.value) catch return error.InvalidCatalogRecord;
        if (lock.kind != .index_build) continue;
        const group = (try lifecycle.groupFromKey(row.key)) orelse return error.InvalidCatalogRecord;
        if (!try RaftApplyStore.relationWriterEnabledTxn(txn, group)) return error.InvalidCatalogRecord;
    }
    // Registry keys are grouped by binary group ID. Check each marker once,
    // including orphan registry groups that no marker scan would discover.
    const claims = relation_names.Key.allGroupsPrefix();
    var entry = try cursor.seekAtOrAfter(claims);
    var previous_group: ?u64 = null;
    while (entry) |row| : (entry = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, claims)) break;
        const group = (try relation_names.Key.groupFromStorageKey(row.key)) orelse return error.InvalidCatalogRecord;
        if (previous_group != group) {
            if (!try RaftApplyStore.relationWriterEnabledTxn(txn, group)) return error.InvalidCatalogRecord;
            previous_group = group;
        }
    }
    const markers = RaftApplyStore.relation_writer_prefix;
    entry = try cursor.seekAtOrAfter(markers);
    while (entry) |row| : (entry = try cursor.next()) {
        if (!std.mem.startsWith(u8, row.key, markers)) break;
        const group = std.fmt.parseInt(u64, row.key[markers.len..], 10) catch return error.InvalidCatalogRecord;
        var buf: [160]u8 = undefined;
        if (group == 0 or !std.mem.eql(u8, row.key, try RaftApplyStore.relationWriterKeyForGroup(&buf, group))) return error.InvalidCatalogRecord;
        try verifyRelationGroupTxn(alloc, txn, group);
    }
}

fn verifyReconciliationGroupTxn(txn: *docstore.DocStore.Txn, group: u64) !void {
    const r = relation_reconciliation;
    var verifier = try r.Verifier(docstore.DocStore.Txn).init(txn, group);
    var cursor = try txn.openCursor();
    defer cursor.close();
    inline for (std.meta.tags(r.RecordKind)) |kind| {
        var buf: [128]u8 = undefined;
        const prefix = try r.groupPrefix(&buf, kind, group);
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix)) break;
            try verifier.feed(row.key, row.value);
        }
    }
    try verifier.finish();
}
fn verifyReconciliationCheckpointTxn(txn: *docstore.DocStore.Txn) !void {
    const r = relation_reconciliation;
    var cursor = try txn.openCursor();
    defer cursor.close();
    // One group at a time. The second pass detects orphan groups that a scan
    // driven only by current jobs would otherwise never discover.
    inline for (std.meta.tags(r.RecordKind)) |kind| {
        const prefix = r.allGroupsPrefix(kind);
        var previous_group: ?u64 = null;
        var entry = try cursor.seekAtOrAfter(prefix);
        while (entry) |row| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, row.key, prefix)) break;
            const record = (try r.classifyStructure(row.key)) orelse return error.InvalidCatalogRecord;
            if (kind == .live) {
                const live = try r.LiveRoot.decode(row.value);
                if (!try RaftApplyStore.relationWriterEnabledTxn(txn, record.group_id) or
                    !live.epoch.eql(try RaftApplyStore.relationSourceEpochTxn(txn, record.group_id))) return error.InvalidCatalogRecord;
            }
            // Source-only groups are valid before any job. Validate their
            // point value without rescanning every candidate a second time;
            // the job pass verifies complete cuts, later passes catch orphans.
            if (kind == .source) {
                _ = try r.sourceRevision(row.value);
                continue;
            }
            if (previous_group != record.group_id) {
                if (kind == .job) try verifyReconciliationGroupTxn(txn, record.group_id) else {
                    var buf: [128]u8 = undefined;
                    const state = try r.State.decode(try txn.get(try r.jobKey(&buf, record.group_id)));
                    if (state.group_id != record.group_id) return error.InvalidCatalogRecord;
                }
                previous_group = record.group_id;
            }
        }
    }
}

fn metadataSnapshotKeyBelongsToGroup(group_id: u64, key: []const u8) bool {
    var buf: [256]u8 = undefined;
    for (RaftApplyStore.metadata_snapshot_projections) |descriptor| {
        const owned_key = switch (descriptor.key) {
            .prefix => |key_fn| key_fn(&buf, group_id) catch return false,
            .point => |key_fn| key_fn(&buf, group_id) catch return false,
        };
        switch (descriptor.key) {
            .prefix => if (std.mem.startsWith(u8, key, owned_key)) return true,
            .point => if (std.mem.eql(u8, key, owned_key)) return true,
        }
    }
    return false;
}

test "relational index publication terminal ACK snapshot key registry includes exact lock retirement" {
    const mask = RaftApplyStore.transitionCommandProjectionMask(.ack_relational_index_publication);
    const expected = RaftApplyStore.metadataSnapshotProjectionBit(.index_publication_head) |
        RaftApplyStore.metadataSnapshotProjectionBit(.index_publication_owner) |
        RaftApplyStore.metadataSnapshotProjectionBit(.index_publication_proof) |
        RaftApplyStore.metadataSnapshotProjectionBit(.fk_generation_table_lock) |
        RaftApplyStore.metadataSnapshotProjectionBit(.index_publication_active) |
        RaftApplyStore.metadataSnapshotProjectionBit(.relation_source) |
        RaftApplyStore.metadataSnapshotProjectionBit(.relation_names) |
        RaftApplyStore.metadataSnapshotProjectionBit(.relation_candidates) |
        RaftApplyStore.metadataSnapshotProjectionBit(.relation_live);
    try std.testing.expectEqual(expected, mask);
}

test "metadata raft apply store snapshot key registry covers every durable projection class" {
    const projection_count = @typeInfo(RaftApplyStore.MetadataSnapshotProjection).@"enum".field_names.len;
    try std.testing.expectEqual(projection_count, RaftApplyStore.metadata_snapshot_projections.len);

    var seen = @as([projection_count]bool, @splat(false));
    var buf: [256]u8 = undefined;
    for (RaftApplyStore.metadata_snapshot_projections) |descriptor| {
        const ordinal = @backingInt(descriptor.projection);
        try std.testing.expect(!seen[ordinal]);
        seen[ordinal] = true;
        const key = switch (descriptor.key) {
            .prefix => |key_fn| try key_fn(&buf, 41),
            .point => |key_fn| try key_fn(&buf, 41),
        };
        try std.testing.expect(metadataSnapshotKeyBelongsToGroup(41, key));
        try std.testing.expect(!metadataSnapshotKeyBelongsToGroup(42, key));
    }
    for (seen) |present| try std.testing.expect(present);

    var descriptor_mask: RaftApplyStore.MetadataSnapshotProjectionMask = 0;
    for (RaftApplyStore.metadata_snapshot_projections) |descriptor| {
        descriptor_mask |= RaftApplyStore.metadataSnapshotProjectionBit(descriptor.projection);
    }
    var command_mask: RaftApplyStore.MetadataSnapshotProjectionMask = 0;
    inline for (std.meta.tags(std.meta.Tag(TransitionCommand))) |tag| {
        const mask = RaftApplyStore.transitionCommandProjectionMask(tag);
        try std.testing.expect(mask != 0);
        command_mask |= mask;
    }
    try std.testing.expectEqual(descriptor_mask, command_mask);
}

fn appendInt(alloc: std.mem.Allocator, out: *std.ArrayListUnmanaged(u8), comptime T: type, value: T) !void {
    var bytes: [@sizeOf(T)]u8 = undefined;
    std.mem.writeInt(T, &bytes, value, .little);
    try out.appendSlice(alloc, &bytes);
}

fn readInt(encoded: []const u8, pos: *usize, comptime T: type) !T {
    if (pos.* + @sizeOf(T) > encoded.len) return error.InvalidMetadataTransitionEncoding;
    const bytes: *const [@sizeOf(T)]u8 = @ptrCast(encoded[pos.* .. pos.* + @sizeOf(T)]);
    const value = std.mem.readInt(T, bytes, .little);
    pos.* += @sizeOf(T);
    return value;
}

fn readOptionalString(alloc: std.mem.Allocator, encoded: []const u8, pos: *usize) !?[]u8 {
    if (pos.* >= encoded.len) return error.InvalidMetadataTransitionEncoding;
    const present = encoded[pos.*];
    pos.* += 1;
    if (present == 0) return null;
    const len = try readInt(encoded, pos, u32);
    if (pos.* + len > encoded.len) return error.InvalidMetadataTransitionEncoding;
    const reason = try alloc.dupe(u8, encoded[pos.* .. pos.* + len]);
    pos.* += len;
    return reason;
}

