test "metadata raft apply store notifies committed key listeners for matched metadata prefixes" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-key-listener-store", .{tmp.sub_path});
    defer std.testing.allocator.free(root);

    const Capture = struct {
        matched: usize = 0,
        saw_table: bool = false,
        saw_range: bool = false,

        fn matches(ptr: *anyopaque, signal: CommittedKeySignal) bool {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            _ = self;
            var table_prefix_buf: [96]u8 = undefined;
            const table_prefix = tablePrefixForGroup(&table_prefix_buf, signal.metadata_group_id) catch return false;
            if (std.mem.startsWith(u8, signal.key, table_prefix)) return true;

            var range_prefix_buf: [96]u8 = undefined;
            const range_prefix = rangePrefixForGroup(&range_prefix_buf, signal.metadata_group_id) catch return false;
            return std.mem.startsWith(u8, signal.key, range_prefix);
        }

        fn onKey(ptr: *anyopaque, signal: CommittedKeySignal) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.matched += 1;

            var table_prefix_buf: [96]u8 = undefined;
            const table_prefix = tablePrefixForGroup(&table_prefix_buf, signal.metadata_group_id) catch return;
            if (std.mem.startsWith(u8, signal.key, table_prefix)) {
                self.saw_table = true;
                return;
            }

            var range_prefix_buf: [96]u8 = undefined;
            const range_prefix = rangePrefixForGroup(&range_prefix_buf, signal.metadata_group_id) catch return;
            if (std.mem.startsWith(u8, signal.key, range_prefix)) self.saw_range = true;
        }
    };

    const table_cmd = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_table = .{
            .table_id = 88,
            .name = "docs",
            .schema_json = "{}",
            .indexes_json = "{}",
        },
    });
    defer std.testing.allocator.free(table_cmd);
    const range_cmd = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_range = .{
            .group_id = 2001,
            .table_id = 88,
            .start_key = "",
            .end_key = null,
        },
    });
    defer std.testing.allocator.free(range_cmd);
    const encoded_entries = try raft_state_machine.encodeCommittedEntries(std.testing.allocator, &.{
        .{ .term = 1, .index = 1, .entry_type = .normal, .data = table_cmd },
        .{ .term = 1, .index = 2, .entry_type = .normal, .data = range_cmd },
    });
    defer std.testing.allocator.free(encoded_entries);

    var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
    defer store.deinit();

    var capture = Capture{};
    try store.addCommittedKeyListener(.{
        .ptr = &capture,
        .vtable = &.{
            .matches_key = Capture.matches,
            .on_committed_key = Capture.onKey,
        },
    });

    try store.snapshotBuilder().applyBatch(.{
        .group_id = 41,
        .commit_index = 2,
        .entries_bytes = encoded_entries,
    });

    try std.testing.expectEqual(@as(usize, 2), capture.matched);
    try std.testing.expect(capture.saw_table);
    try std.testing.expect(capture.saw_range);
}

test "system catalog schema reader table pending publication decoder activation survives reopen without native floor" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/pending-schema-decoder", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    var open = true;
    defer if (open) store.deinit();
    const incarnation: metadata_incarnation.MetadataClusterIncarnation = "0123456789abcdef0123456789abcdef".*;
    try store.applyStandaloneCommand(21, .{ .initialize_metadata_incarnation = incarnation });
    var activation: topology_protocol.Activation = .{ .version = topology_protocol.schema_reader_publication_version, .incarnation = incarnation, .member_count = 3, .membership_fingerprint = @splat(1) };
    const encoded = try std.json.Stringify.valueAlloc(a, activation, .{});
    defer a.free(encoded);
    try store.applyStandaloneCommand(21, .{ .activate_topology_protocol = encoded });
    try std.testing.expect(!(try store.getSchemaReaderFloor(21)).active());
    store.deinit();
    open = false;
    store = try RaftApplyStore.init(a, .{ .root_dir = root });
    open = true;
    try std.testing.expectEqualDeep(activation, (try store.topologyActivation(21)).?);
    try std.testing.expect(!(try store.getSchemaReaderFloor(21)).active());
    activation.version = topology_protocol.schema_reader_floor_version;
    const older = try std.json.Stringify.valueAlloc(a, activation, .{});
    defer a.free(older);
    try store.applyStandaloneCommand(21, .{ .activate_topology_protocol = older });
    try std.testing.expectEqual(topology_protocol.schema_reader_publication_version, (try store.topologyActivation(21)).?.version);
    activation.version = topology_protocol.schema_reader_publication_version;
    activation.incarnation = "1123456789abcdef0123456789abcdef".*;
    const foreign = try std.json.Stringify.valueAlloc(a, activation, .{});
    defer a.free(foreign);
    try store.applyStandaloneCommand(21, .{ .activate_topology_protocol = foreign });
    try std.testing.expectEqualDeep(incarnation, (try store.topologyActivation(21)).?.incarnation);
    try std.testing.expect(!(try store.getSchemaReaderFloor(21)).active());
    const oversized = try a.alloc(u8, topology_protocol.max_activation_bytes + 1);
    defer a.free(oversized);
    @memset(oversized, ' ');
    @memcpy(oversized[0..encoded.len], encoded);
    try std.testing.expectError(error.InvalidMetadataTransitionEncoding, store.applyStandaloneCommand(21, .{ .activate_topology_protocol = oversized }));
    try std.testing.expectEqual(topology_protocol.schema_reader_publication_version, (try store.topologyActivation(21)).?.version);
    // Simulate a corrupt imported/disk value, bypassing command validation.
    var key_buf: [160]u8 = undefined;
    const key = try RaftApplyStore.topologyActivationKeyForGroup(&key_buf, 21);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try txn.put(key, oversized);
        try txn.commit();
    }
    try std.testing.expectError(error.InvalidMetadataTransitionEncoding, store.topologyActivation(21));
}

test "schema validation publication committed stale guards are classified only after relation rollback" {
    // Mutation routing is part of the safety proof: a ready relation writer
    // attaches and rolls back its journal before this classifier is consulted.
    // This is not full activated-cohort Raft/recovery qualification.
    try std.testing.expect(apply_contract.transitionMutatesRelationSource(TransitionCommand{ .apply_schema_validation = "{}" }));
    for ([_]anyerror{
        error.GenerationPublicationChanged, error.CatalogGenerationChanged,            error.StoreRootEnrollmentChanged,
        error.IndexOwnerReceiptChanged,     error.SchemaValidationJobChanged,          error.SchemaValidationRuntimeRecoveryRequired,
        error.SchemaValidationNotReady,     error.SchemaValidationPublicationRequired, error.SchemaValidationCancellationRequired,
        error.MetadataIncarnationMismatch,  error.RowPolicyUnsupported,                error.ExtensionOwnedObject,
    }) |err| try std.testing.expect(RaftApplyStore.schemaValidationLosingGuard(err));
    for ([_]anyerror{
        error.TableTopologyProtocolUpgradeRequired, error.InvalidGenerationPublication,  error.InvalidCatalogRecord,
        error.InvalidIndexOwnerReceipt,             error.InvalidMetadataCommandJournal, error.OutOfMemory,
        error.InjectedStorageFailure,               error.InputOutput,
    }) |err| try std.testing.expect(!RaftApplyStore.schemaValidationLosingGuard(err));
}

test "schema validation publication command codec and snapshot registry require durable activation" {
    const a = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/validation-command", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    const command: TransitionCommand = .{ .apply_schema_validation = "{}" };
    const encoded = try encodeTransitionCommand(a, command);
    defer a.free(encoded);
    var decoded = (try decodeTransitionCommand(a, encoded)) orelse return error.TestUnexpectedResult;
    defer decoded.deinit(a);
    try std.testing.expectEqualStrings(command.apply_schema_validation, decoded.apply_schema_validation);
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(21, command));
    const lookup: schema_validation.Lookup = .{ .group = 21, .table = 7, .id = @splat(1), .plan_digest = @splat(2), .metadata_incarnation = "0123456789abcdef0123456789abcdef".* };
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.schemaValidationOwnerControlJson(a, 21, lookup, 0, .begin));
    try std.testing.expectError(error.InvalidGenerationPublication, store.schemaValidationOwnerControlJson(a, 22, lookup, 0, .begin));
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.schemaValidationOwnerInputBytes(a, 21, lookup, 0));
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.schemaValidationReceiptJson(a, 21, .{ .lookup = lookup, .expected = .admission }));
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.schemaValidationPreflightJson(a, 21, "{}"));
    try std.testing.expectError(error.InvalidGenerationPublication, store.schemaValidationPreflightJson(a, 21, ""));
    try std.testing.expectError(error.InvalidGenerationPublication, store.schemaValidationOwnerInputBytes(a, 22, lookup, 0));
    const mask = RaftApplyStore.transitionCommandProjectionMask(.apply_schema_validation);
    const expected = RaftApplyStore.metadataSnapshotProjectionBit(.schema_validation) |
        RaftApplyStore.metadataSnapshotProjectionBit(.schema_validation_dependency) |
        RaftApplyStore.metadataSnapshotProjectionBit(.table) | RaftApplyStore.metadataSnapshotProjectionBit(.fk_generation_table_lock);
    try std.testing.expectEqual(expected, mask & expected);
    var buf: [192]u8 = undefined;
    const key: schema_validation.Key = .{ .group = 21, .table = 7, .id = @splat(1), .kind = .preparation, .ordinal = 1 };
    const storage_key = try key.encode(&buf);
    try std.testing.expect(metadataSnapshotKeyBelongsToGroup(21, storage_key));
    try std.testing.expect(!metadataSnapshotKeyBelongsToGroup(22, storage_key));
    var parent_key: schema_validation.Key = .{ .group = 21, .table = 7, .id = @splat(1), .kind = .parent, .ordinal = 1, .grant = @splat(3) };
    const parent_storage_key = try parent_key.encode(&buf);
    try std.testing.expectEqualDeep(parent_key, (try schema_validation.Key.parse(parent_storage_key)).?);
    try std.testing.expect(metadataSnapshotKeyBelongsToGroup(21, parent_storage_key));
    try std.testing.expect(!metadataSnapshotKeyBelongsToGroup(22, parent_storage_key));
    parent_key.grant = null;
    try std.testing.expectError(error.InvalidGenerationPublication, parent_key.encode(&buf));
    const dependencies = @import("../schema_validation_dependencies.zig");
    const dependency_key: dependencies.Key = .{ .group = 21, .child = 7, .parent = 8, .id = @splat(1), .ordinal = 0 };
    var dependency_buf: [256]u8 = undefined;
    const dependency_bytes = try dependency_key.encode(&dependency_buf);
    try std.testing.expect(metadataSnapshotKeyBelongsToGroup(21, dependency_bytes));
    try std.testing.expect(!metadataSnapshotKeyBelongsToGroup(22, dependency_bytes));
    var source_index = dependency_key;
    source_index.parent = null;
    try std.testing.expect(metadataSnapshotKeyBelongsToGroup(21, try source_index.encode(&dependency_buf)));
    var txn = try store.store.beginReadTxn();
    defer txn.abort();
    try std.testing.expectError(error.GenerationPublicationNotFound, schema_validation.readHead(&txn, .{
        .group = 21,
        .table = 7,
        .id = @splat(1),
        .plan_digest = @splat(2),
        .metadata_incarnation = "0123456789abcdef0123456789abcdef".*,
    }));
}

test "schema validation publication snapshot rejects text bindings before complete protocol activation" {
    const a = std.testing.allocator;
    const group = 21;
    const incarnation: metadata_incarnation.MetadataClusterIncarnation = "0123456789abcdef0123456789abcdef".*;
    var key_bufs: [3][160]u8 = undefined;
    const incarnation_key = try metadataIncarnationKeyForGroup(&key_bufs[0], group);
    const activation_key = try RaftApplyStore.topologyActivationKeyForGroup(&key_bufs[1], group);
    const table_key = try tableKeyForGroup(&key_bufs[2], group, 7);
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .schema_json = "{}", .full_text_read_index = "named", .indexes_json = "{\"named\":{\"type\":\"full_text\"}}" };
    const encoded = try encodeTableRecord(a, table);
    defer a.free(encoded);
    const activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{ .version = topology_protocol.schema_validation_publication_version - 1, .incarnation = incarnation, .member_count = 3, .membership_fingerprint = @splat(7) }, .{});
    defer a.free(activation);
    var rows = [_]docstore.OwnedKVPair{
        .{ .key = @constCast(incarnation_key), .value = @constCast(&incarnation) },
        .{ .key = @constCast(activation_key), .value = activation },
        .{ .key = @constCast(table_key), .value = encoded },
    };
    const Check = struct {
        fn reject(alloc: std.mem.Allocator, source: []const docstore.OwnedKVPair) !void {
            var values: std.StringHashMapUnmanaged([]const u8) = .empty;
            defer values.deinit(alloc);
            for (source) |row| try values.put(alloc, row.key, row.value);
            try std.testing.expectError(error.InvalidMetadataSnapshot, validateSchemaReaderSnapshotCut(alloc, 21, source, &values, null));
        }
    };
    try Check.reject(a, &rows);
    const plan = @constCast("{\"plan\":{\"after\":{\"full_text_read_index\":\"named\"}}}");
    var plan_key_buf: [160]u8 = undefined;
    inline for (.{ index_publication.planPrefix, fk_generation_publication.prefixForGroup, fk_generation_publication.initialPrefixForGroup, restore_staging.jobPrefix }) |prefix| {
        rows[2] = .{ .key = @constCast(try prefix(&plan_key_buf, group)), .value = plan };
        try Check.reject(a, &rows);
    }
    const key: schema_validation.Key = .{ .group = group, .table = 7, .id = @splat(1), .kind = .head };
    rows[2] = .{ .key = @constCast(try key.encode(&plan_key_buf)), .value = @constCast("") };
    try Check.reject(a, &rows);
    const lifecycle = @import("../table_lifecycle_lock.zig");
    const lock = lifecycle.value(.schema_validation, @splat(1));
    rows[2] = .{ .key = @constCast(try lifecycle.key(&plan_key_buf, group, 7)), .value = @constCast(&lock) };
    try Check.reject(a, &rows);
}

test "schema validation publication physical text generations survive table frames query projections and CAS" {
    const a = std.testing.allocator;
    const baseline: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .schema_json = "{\"version\":3}", .indexes_json = "{\"full_text_index_v1\":{\"type\":\"full_text\"},\"named\":{\"type\":\"full_text\"}}" };
    const old_json = try std.json.Stringify.valueAlloc(a, baseline, .{});
    defer a.free(old_json);
    try std.testing.expect(std.mem.indexOf(u8, old_json, "full_text_read_index") == null);
    for ([_][]const u8{ "full_text_index_v0", "full_text_index_v1", "named" }) |index_name| inline for (.{ false, true }) |reader_requirements| {
        var table = baseline;
        table.full_text_read_index = index_name;
        if (reader_requirements) table.schema_reader_requirements = .{ .semantic_version = 14, .encoding_version = 31 };
        const encoded = try encodeTableRecord(a, table);
        defer a.free(encoded);
        const decoded = try decodeTableRecord(a, encoded);
        defer metadata_table_manager.freeTable(a, decoded);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, decoded));
        const clone = try metadata_table_manager.cloneTable(a, decoded);
        defer metadata_table_manager.freeTable(a, clone);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(clone, decoded));
        var changed = clone;
        changed.full_text_read_index = null;
        try std.testing.expect(!metadata_table_manager.tableDefinitionsEqual(changed, decoded));
        const canonical = try encodeTableRecord(a, clone);
        defer a.free(canonical);
        try std.testing.expectEqualSlices(u8, encoded, canonical);
        const identity = try borrowTableProjection(encoded, .identity);
        try std.testing.expectEqualStrings(index_name, identity.full_text_read_index.?);
        const projected = try decodeTableQueryProjection(a, encoded, true);
        defer projected.deinit(a);
        try std.testing.expectEqualStrings(index_name, projected.query_definition.?.full_text_read_index.?);
        const query_clone = try projected.query_definition.?.clone(a);
        defer query_clone.deinit(a);
        const query_json = try std.json.Stringify.valueAlloc(a, query_clone, .{});
        defer a.free(query_json);
        const query_decoded = try std.json.parseFromSlice(system_catalog.QueryDefinition, a, query_json, .{});
        defer query_decoded.deinit();
        try std.testing.expectEqualStrings(index_name, query_decoded.value.full_text_read_index.?);
        const json = try std.json.Stringify.valueAlloc(a, decoded, .{});
        defer a.free(json);
        const parsed = try std.json.parseFromSlice(metadata.TableRecord, a, json, .{});
        defer parsed.deinit();
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(decoded, parsed.value));
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(a, encoded[0 .. encoded.len - 1]));
        const Faults = struct {
            fn run(backing: std.mem.Allocator, bytes: []const u8) !void {
                const value = try decodeTableRecord(backing, bytes);
                defer metadata_table_manager.freeTable(backing, value);
            }
        };
        try std.testing.checkAllAllocationFailures(a, Faults.run, .{encoded});
    };
}

test "system catalog schema reader table requirements preserve canonical frames projections and CAS identity" {
    const a = std.testing.allocator;
    const legacy: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .schema_json = "{}" };
    const legacy_bytes = try encodeTableRecord(a, legacy);
    defer a.free(legacy_bytes);
    const legacy_json = try std.json.Stringify.valueAlloc(a, legacy, .{});
    defer a.free(legacy_json);
    try std.testing.expect(std.mem.indexOf(u8, legacy_json, "schema_reader_requirements") == null);
    inline for (.{ 0, 1, 2, 3 }) |storage_kind| inline for (.{ false, true }) |retirement| {
        var table = legacy;
        table.schema_reader_requirements = .{ .semantic_version = 30, .encoding_version = 31 };
        if (storage_kind == 3) {
            table.storage.engine = .object;
            table.object_storage_generation = 17;
            table.object_storage_identity = @splat(5);
        } else if (storage_kind != 0) {
            table.storage.dense_embeddings = .vector_store;
            if (storage_kind == 2) table.storage_migration = .{ .request = .{ .job_id = "reader_migration", .mode = .online, .budget = .{ .batch_rows = 17, .batch_bytes = 8192, .temporary_bytes = 65536, .disk_reserve_bytes = 32768 } } };
        }
        if (retirement) table.relational_retirement_json = "retiring";
        const encoded = try encodeTableRecord(a, table);
        defer a.free(encoded);
        const decoded = try decodeTableRecord(a, encoded);
        defer metadata_table_manager.freeTable(a, decoded);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, decoded));
        const clone = try metadata_table_manager.cloneTable(a, decoded);
        defer metadata_table_manager.freeTable(a, clone);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, clone));
        const canonical = try encodeTableRecord(a, clone);
        defer a.free(canonical);
        try std.testing.expectEqualSlices(u8, encoded, canonical);
        const json = try std.json.Stringify.valueAlloc(a, .{ .table = table }, .{});
        defer a.free(json);
        try validateTransitionCommandSchemaReaderRequirements(.{ .apply_system_catalog = json });
        const identity = try decodeTableIdentity(a, encoded);
        defer identity.deinit(a);
        try std.testing.expectEqual(table.table_id, identity.table_id);
        const query = try decodeTableQueryProjection(a, encoded, true);
        defer query.deinit(a);
        try std.testing.expectEqual(table.storage.engine, query.query_definition.?.storage_engine);
        var changed = table;
        changed.schema_reader_requirements.?.semantic_version -= 1;
        try std.testing.expect(!metadata_table_manager.tableDefinitionsEqual(table, changed));
        try std.testing.expect(!std.mem.eql(u8, &metadata_table_manager.tableDefinitionFingerprint(table), &metadata_table_manager.tableDefinitionFingerprint(changed)));
        changed.schema_reader_requirements = null;
        try std.testing.expect(!metadata_table_manager.tableDefinitionsEqual(table, changed));
        try std.testing.expect(!std.mem.eql(u8, &metadata_table_manager.tableDefinitionFingerprint(table), &metadata_table_manager.tableDefinitionFingerprint(changed)));
        const extension = std.mem.indexOf(u8, encoded, "ATS1").?;
        for (extension + 1..encoded.len) |len| {
            try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(a, encoded[0..len]));
            try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableIdentity(a, encoded[0..len]));
        }
        const corrupt = try a.dupe(u8, encoded);
        defer a.free(corrupt);
        std.mem.writeInt(u32, corrupt[corrupt.len - 8 ..][0..4], @import("antfly_local_sources").common_schema_readers.current_semantic_version + 1, .little);
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(a, corrupt));
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableIdentity(a, corrupt));
        @memcpy(corrupt, encoded);
        std.mem.writeInt(u32, corrupt[corrupt.len - 4 ..][0..4], 0, .little);
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(a, corrupt));
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableIdentity(a, corrupt));
        var bad = table;
        bad.schema_reader_requirements = .{ .semantic_version = 30, .encoding_version = 0 };
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, encodeTableRecord(a, bad));
        try std.testing.expectError(error.InvalidSchemaReaderRequirements, bad.validateSchemaReaderRequirements());
        try std.testing.expectError(error.InvalidSchemaReaderRequirements, validateTransitionCommandSchemaReaderRequirements(.{ .upsert_table = bad }));
        const bad_json = try std.json.Stringify.valueAlloc(a, .{ .table = bad }, .{});
        defer a.free(bad_json);
        try std.testing.expectError(error.InvalidSchemaReaderRequirements, validateTransitionCommandSchemaReaderRequirements(.{ .apply_system_catalog = bad_json }));
    };
    const decoded_legacy = try decodeTableRecord(a, legacy_bytes);
    defer metadata_table_manager.freeTable(a, decoded_legacy);
    try std.testing.expect(decoded_legacy.schema_reader_requirements == null);
    const canonical_legacy = try encodeTableRecord(a, decoded_legacy);
    defer a.free(canonical_legacy);
    try std.testing.expectEqualSlices(u8, legacy_bytes, canonical_legacy);
}

test "metadata.table storage extension preserves ownership migration and legacy bytes" {
    const alloc = std.testing.allocator;
    const legacy: metadata.TableRecord = .{ .table_id = 7, .name = "rows" };
    const legacy_bytes = try encodeTableRecord(alloc, legacy);
    defer alloc.free(legacy_bytes);
    const golden_hex = "070000000000000003000100000004000000726f7773000000000000000000000000020000007b7d020000005b5d04000000646174610000000000000000";
    var golden: [golden_hex.len / 2]u8 = undefined;
    _ = try std.fmt.hexToBytes(&golden, golden_hex);
    try std.testing.expectEqualSlices(u8, &golden, legacy_bytes);
    inline for (.{ false, true }) |retirement| inline for (.{ false, true }) |migration| {
        var table = legacy;
        table.storage.dense_embeddings = .vector_store;
        if (retirement) table.relational_retirement_json = "{\"phase\":\"retiring\"}";
        if (migration) table.storage_migration = .{ .request = .{ .job_id = "migration_7", .mode = .online, .budget = .{ .batch_rows = 17, .batch_bytes = 8192, .temporary_bytes = 65536, .disk_reserve_bytes = 32768 } } };
        const encoded = try encodeTableRecord(alloc, table);
        defer alloc.free(encoded);
        const projected = try decodeTableQueryProjection(alloc, encoded, true);
        defer projected.deinit(alloc);
        try std.testing.expectEqual(table.table_id, projected.table_id);
        try std.testing.expectEqualStrings(table.name, projected.name);
        try std.testing.expectEqualStrings(table.schema_json, projected.query_definition.?.schema_json);
        const decoded = try decodeTableRecord(alloc, encoded);
        defer metadata_table_manager.freeTable(alloc, decoded);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, decoded));
        const canonical = try encodeTableRecord(alloc, decoded);
        defer alloc.free(canonical);
        try std.testing.expectEqualSlices(u8, encoded, canonical);
        const clone = try metadata_table_manager.cloneTable(alloc, decoded);
        defer metadata_table_manager.freeTable(alloc, clone);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, clone));
        if (migration) try std.testing.expect(clone.storage_migration.?.request.job_id.ptr != decoded.storage_migration.?.request.job_id.ptr);
        const extension = std.mem.indexOf(u8, encoded, "ATS1").?;
        const corrupt = try alloc.dupe(u8, encoded);
        defer alloc.free(corrupt);
        corrupt[extension + 4] = 2; // Unknown extension version.
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(alloc, corrupt));
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableIdentity(alloc, corrupt));
        @memcpy(corrupt, encoded);
        corrupt[extension + 6] = 2; // Unknown physical ownership.
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(alloc, corrupt));
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableIdentity(alloc, corrupt));
        @memcpy(corrupt, encoded);
        corrupt[extension + 7] = 2; // Invalid optional-admission discriminator.
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(alloc, corrupt));
        try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableIdentity(alloc, corrupt));
        for (extension + 1..encoded.len) |len| try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTableRecord(alloc, encoded[0..len]));
    };
    const Fixture = struct {
        fn run(allocator: std.mem.Allocator) !void {
            const table: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .relational_retirement_json = "retiring", .storage_migration = .{ .request = .{ .job_id = "migration", .mode = .offline } } };
            const encoded = try encodeTableRecord(allocator, table);
            defer allocator.free(encoded);
            const decoded = try decodeTableRecord(allocator, encoded);
            defer metadata_table_manager.freeTable(allocator, decoded);
            try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, decoded));
            const clone = try metadata_table_manager.cloneTable(allocator, decoded);
            defer metadata_table_manager.freeTable(allocator, clone);
        }
    };
    try std.testing.checkAllAllocationFailures(alloc, Fixture.run, .{});
}

test "standalone metadata storage migration survives reopen checkpoint and exact CAS" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/migration", .{tmp.sub_path});
    defer alloc.free(root);
    const target = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/restored", .{tmp.sub_path});
    defer alloc.free(target);
    const checkpoint = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/metadata.bin", .{tmp.sub_path});
    defer alloc.free(checkpoint);
    const group = group_ids.main_metadata_group_id;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .storage_migration = .{ .request = .{ .job_id = "move_vectors", .mode = .online } } };
    const ranges = [_]metadata.RangeRecord{.{ .table_id = 7, .group_id = 17, .range_id = 19, .start_key = "" }};
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        try store.replaceStandaloneCatalog(group, 0, &.{table}, &ranges, "{\"schema_version\":3}");
    }
    var reopened = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer reopened.deinit();
    const records = try reopened.listTables(alloc, group);
    defer reopened.freeTables(alloc, records);
    try std.testing.expectEqual(@as(usize, 1), records.len);
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, records[0]));
    const artifact = try reopened.exportHotStandbyCheckpoint(std.testing.io, checkpoint);
    var restored = try RaftApplyStore.init(alloc, .{ .root_dir = target });
    defer restored.deinit();
    try restored.importHotStandbyCheckpoint(std.testing.io, checkpoint, artifact.size_bytes);
    var replacement = table;
    replacement.storage.dense_embeddings = .vector_store;
    replacement.storage_migration = null;
    var stale = table;
    stale.storage_migration.?.request.job_id = "different";
    try restored.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = stale, .replacement = replacement } });
    {
        const unchanged = try restored.listTables(alloc, group);
        defer restored.freeTables(alloc, unchanged);
        try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, unchanged[0]));
    }
    try restored.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = table, .replacement = replacement } });
    const published = try restored.listTables(alloc, group);
    defer restored.freeTables(alloc, published);
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(replacement, published[0]));
}

test "metadata.table record decoder accepts legacy table metadata encoding" {
    var encoded = std.ArrayListUnmanaged(u8).empty;
    defer encoded.deinit(std.testing.allocator);

    try appendInt(std.testing.allocator, &encoded, u64, 41);
    try appendInt(std.testing.allocator, &encoded, u16, 5);
    try appendInt(std.testing.allocator, &encoded, u32, 2);
