test "system catalog active policy edits atomically enqueue immutable generations and reject forged owner cuts" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/policy-atomic-edit", .{tmp.sub_path});
    defer alloc.free(root);
    const group = group_ids.main_metadata_group_id;
    // SQL TEXT columns derive keyword mappings even without a search index.
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "table:policies", .schema_json = "{\"version\":1,\"storage_mode\":\"relational\",\"default_type\":\"row\",\"document_schemas\":{\"row\":{\"schema\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"integer\"},\"tenant_id\":{\"type\":\"keyword\"}},\"additionalProperties\":false}}}}" };
    const binding: system_catalog.Resource = .{ .kind = .table, .id = 7, .parent_id = system_catalog.default_namespace_id, .name = "policies", .storage_name = table.name };
    const range: metadata.RangeRecord = .{ .table_id = 7, .group_id = 17, .range_id = 17, .start_key = "", .end_key = null };
    var expected_install: ?[]u8 = null;
    defer if (expected_install) |bytes| alloc.free(bytes);
    var candidate: sql_policies.Publication = undefined;
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        try store.updateStandaloneCatalog(group, 0, .{ .tables = &.{table}, .ranges = &.{range}, .auxiliary_json = "{}", .import_catalog = .{ .revision = 1, .next_id = 8, .resources = &.{binding} } });
        const empty_begin = try store.sqlPolicyBeginCommandJson(alloc, group, .{ .table_id = 7, .enable = true, .expected_revision = 1 });
        defer alloc.free(empty_begin);
        var initial = try std.json.parseFromSlice(sql_policies.PublicationCommand, alloc, empty_begin, .{});
        defer initial.deinit();
        try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = empty_begin });
        for ([_]sql_policies.Publication.Phase{ .pending_install, .serving_install }) |phase| {
            const status_bytes = try store.sqlPolicyPublicationWorkJson(alloc, group, 0);
            defer alloc.free(status_bytes);
            var work = try std.json.parseFromSlice(sql_policies.PublicationWork, alloc, status_bytes, .{});
            defer work.deinit();
            const publication = work.value.publication.?;
            try std.testing.expectEqual(phase, publication.phase);
            const owner = publication.required_owners[0];
            const install = try store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = publication.generation, .expected_catalog_epoch = publication.catalog_epoch, .expected_phase = phase, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
            defer alloc.free(install);
            var empty = try std.json.parseFromSlice(sql_policies.InstallSnapshot, alloc, install, .{});
            defer empty.deinit();
            try std.testing.expectEqual(@as(usize, 0), empty.value.records.len);
            var digest: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(install, &digest, .{});
            const ack = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = work.value.revision, .change = .{ .acknowledge = .{ .table_id = 7, .generation = publication.generation, .receipt = .{ .owner = owner, .catalog_epoch = publication.catalog_epoch, .phase = phase, .applied_term = 1, .applied_index = work.value.revision + 1, .bundle_digest = digest } } } }, .{});
            defer alloc.free(ack);
            try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = ack });
            const promote = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = work.value.revision + 1, .change = .{ .promote = .{ .table_id = 7, .generation = publication.generation, .phase = if (phase == .pending_install) .serving_install else .active } } }, .{});
            defer alloc.free(promote);
            try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = promote });
        }
        const meta = try store.systemCatalogMeta(alloc, group);
        const status_bytes = try store.sqlPolicyPublicationStatusJson(alloc, group, 7);
        defer alloc.free(status_bytes);
        var status = try std.json.parseFromSlice(sql_policies.PublicationStamp, alloc, status_bytes, .{});
        defer status.deinit();
        const record: sql_policies.Record = .{ .id = 8, .generation = 1, .table_id = 7, .schema_version = 1, .schema_digest = initial.value.change.begin.schema_digest, .name = "visible", .commands = .{ .select = true }, .roles = &.{"PUBLIC"}, .using = .{ .instructions = &.{.{ .type = .{ .kind = .boolean }, .operation = .{ .literal = .{ .bool = true } } }}, .root = 0 } };
        const bytes = try store.sqlPolicyDefinitionCommandJson(alloc, group, .{ .expected_revision = meta.revision, .change = .{ .put = record } });
        defer alloc.free(bytes);
        var admitted = try std.json.parseFromSlice(sql_policies.Command, alloc, bytes, .{});
        defer admitted.deinit();
        candidate = admitted.value.publication.?;
        candidate.required_owners = &.{}; // Do not retain the parsed arena.
        var forged = admitted.value;
        var changed_owner = admitted.value.publication.?.required_owners[0];
        changed_owner.descriptor_digest = @splat(8);
        forged.publication.?.required_owners = &.{changed_owner};
        const forged_bytes = try std.json.Stringify.valueAlloc(alloc, forged, .{});
        defer alloc.free(forged_bytes);
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.applyStandaloneCommand(group, .{ .apply_sql_policies = forged_bytes }));
        var rejected = try store.systemCatalogSnapshot(alloc, group);
        defer rejected.deinit();
        try std.testing.expectEqual(meta.revision, rejected.value.revision);
        try std.testing.expectEqual(@as(usize, 0), rejected.value.policies.len);
        try std.testing.expectEqual(sql_policies.Publication.Phase.active, rejected.value.policy_publications[0].phase);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policies = bytes });
        try store.applyStandaloneCommand(group, .{ .apply_sql_policies = bytes });
        const committed = try store.systemCatalogMeta(alloc, group);
        try std.testing.expectEqual(meta.revision + 1, committed.revision);
        try std.testing.expectEqual(@as(u64, 9), committed.next_id);
        const owner = admitted.value.publication.?.required_owners[0];
        expected_install = try store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = candidate.generation, .expected_catalog_epoch = candidate.catalog_epoch, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
    }
    {
        var reopened = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer reopened.deinit();
        var state = try reopened.systemCatalogSnapshot(alloc, group);
        defer state.deinit();
        try std.testing.expectEqual(@as(usize, 1), state.value.policies.len);
        try std.testing.expectEqual(@as(u64, 9), state.value.next_id);
        const publication = state.value.policy_publications[0];
        try std.testing.expectEqual(candidate.generation, publication.generation);
        try std.testing.expectEqual(sql_policies.Publication.Phase.pending_install, publication.phase);
        const owner = publication.required_owners[0];
        const recovered = try reopened.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = publication.generation, .expected_catalog_epoch = publication.catalog_epoch, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
        defer alloc.free(recovered);
        try std.testing.expectEqualStrings(expected_install.?, recovered);
        var installed = try std.json.parseFromSlice(sql_policies.InstallSnapshot, alloc, recovered, .{});
        defer installed.deinit();
        try std.testing.expectEqual(@as(u64, 8), installed.value.records[0].id);
    }
}

test "inert SQL policy definitions survive standalone replay, snapshot, and restart" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/policy-catalog", .{tmp.sub_path});
    defer alloc.free(root);
    const group = group_ids.main_metadata_group_id;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "table:policies", .schema_json = "{\"storage_mode\":\"relational\"}" };
    const binding: system_catalog.Resource = .{ .kind = .table, .id = 7, .parent_id = system_catalog.default_namespace_id, .name = "policies", .storage_name = table.name };
    var object_literal = try std.json.parseFromSlice(std.json.Value, alloc, "{\"tenant\":\"alpha\"}", .{});
    defer object_literal.deinit();
    var array_literal = try std.json.parseFromSlice(std.json.Value, alloc, "[1,2]", .{});
    defer array_literal.deinit();
    const predicate: sql_policies.Predicate = .{ .instructions = &.{
        .{ .type = .{ .kind = .string }, .operation = .{ .literal = .{ .string = "alpha" } } },
        .{ .type = .{ .kind = .json }, .operation = .{ .literal = object_literal.value } },
        .{ .type = .{ .kind = .json }, .operation = .{ .literal = array_literal.value } },
        .{ .type = .{ .kind = .boolean, .nullable = false }, .operation = .{ .literal = .{ .bool = true } } },
    }, .root = 3 };
    const record: sql_policies.Record = .{ .id = 8, .generation = 1, .table_id = 7, .schema_version = 1, .schema_digest = @splat(5), .name = "owner_filter", .commands = .{ .select = true }, .roles = &.{"alice"}, .using = predicate };
    const command: sql_policies.Command = .{ .expected_revision = 1, .change = .{ .put = record } };
    const bytes = try std.json.Stringify.valueAlloc(alloc, command, .{});
    defer alloc.free(bytes);
    // Standalone's opaque metadata transport uses the integrity JSON writer.
    // Its policy payload must round-trip as typed logical JSON, never as the
    // pointer-bearing representation of std.json.Value.
    var wire: std.Io.Writer.Allocating = .init(alloc);
    defer wire.deinit();
    var stream: std.json.Stringify = .{ .writer = &wire.writer, .options = .{} };
    try @import("antfly_local_sources").storage_db_relational_integrity_json.write(@import("raft_apply_contract.zig").StandaloneCatalogUpdate{ .policy_command = command }, &stream);
    var decoded = try std.json.parseFromSlice(@import("raft_apply_contract.zig").StandaloneCatalogUpdate, alloc, wire.written(), .{});
    defer decoded.deinit();
    try std.testing.expectEqual(@as(u64, 8), decoded.value.policy_command.?.change.put.id);
    const restored = decoded.value.policy_command.?.change.put.using.?.instructions;
    try std.testing.expectEqualStrings("alpha", restored[0].operation.literal.string);
    try std.testing.expectEqualStrings("alpha", restored[1].operation.literal.object.get("tenant").?.string);
    try std.testing.expectEqual(@as(usize, 2), restored[2].operation.literal.array.items.len);
    try std.testing.expectEqual(@as(i64, 1), restored[2].operation.literal.array.items[0].integer);
    try std.testing.expect(restored[3].operation.literal.bool);
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        try store.updateStandaloneCatalog(group, 0, .{ .tables = &.{table}, .auxiliary_json = "{}", .import_catalog = .{ .revision = 1, .next_id = 8, .resources = &.{binding} } });
        try store.applyStandaloneCommand(group, .{ .apply_sql_policies = bytes });
        try store.applyStandaloneCommand(group, .{ .apply_sql_policies = bytes });
        const stale: sql_policies.Command = .{ .expected_revision = 1, .change = .{ .drop = .{ .id = 8, .generation = 1, .table_id = 7 } } };
        const stale_bytes = try std.json.Stringify.valueAlloc(alloc, stale, .{});
        defer alloc.free(stale_bytes);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policies = stale_bytes });
        var state = try store.systemCatalogSnapshot(alloc, group);
        defer state.deinit();
        try std.testing.expectEqual(@as(u64, 2), state.value.revision);
        try std.testing.expectEqual(@as(usize, 1), state.value.policies.len);
        const portable_bytes = try store.exportSystemCatalog(alloc, group);
        defer alloc.free(portable_bytes);
        var portable = try std.json.parseFromSlice(@import("../../system_catalog/projection.zig").Export, alloc, portable_bytes, .{});
        defer portable.deinit();
        try std.testing.expectEqual(@as(usize, 1), portable.value.system_catalog.policies.len);
    }
    {
        var reopened = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer reopened.deinit();
        var state = try reopened.systemCatalogSnapshot(alloc, group);
        defer state.deinit();
        try std.testing.expectEqual(@as(usize, 1), state.value.policies.len);
        try std.testing.expectEqualStrings("owner_filter", state.value.policies[0].name);
        try std.testing.expectEqual(@as(u64, 1), state.value.policies[0].generation);
    }
}

test "row-policy ENABLE admits relational indexes but rejects search artifact modalities" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    try std.testing.expect(!try policyHasUnsupportedArtifactIndexes(alloc, "{}"));
    try std.testing.expect(!try policyHasUnsupportedArtifactIndexes(alloc, "{\"by_account\":{\"type\":\"relational\"}}"));
    inline for (.{ "full_text", "dense_vector", "graph", "embeddings", "enrichment" }) |kind| {
        const json = try std.fmt.allocPrint(alloc, "{{\"idx\":{{\"type\":\"{s}\"}}}}", .{kind});
        try std.testing.expect(try policyHasUnsupportedArtifactIndexes(alloc, json));
    }
    try std.testing.expectError(error.InvalidCatalogRecord, policyHasUnsupportedArtifactIndexes(alloc, "{\"idx\":{}}"));
}

test "row-policy publication persists exact owner ACKs and leader install cut" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/policy-publication", .{tmp.sub_path});
    defer alloc.free(root);
    var schema_arena = std.heap.ArenaAllocator.init(alloc);
    defer schema_arena.deinit();
    const schema_alloc = schema_arena.allocator();
    const group = group_ids.main_metadata_group_id;
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "table:policies", .schema_json = "{\"version\":1,\"storage_mode\":\"relational\",\"default_type\":\"row\",\"document_schemas\":{\"row\":{\"schema\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"integer\"}},\"additionalProperties\":false}}}}" };
    var parsed_schema = try @import("antfly_local_sources").schema_mod.parseValidatedTableSchema(schema_alloc, table.schema_json);
    defer parsed_schema.deinit(schema_alloc);
    const native_schema = try @import("antfly_local_sources").schema_mod.deriveRuntimeTableSchema(schema_alloc, parsed_schema);
    const layout = try @import("antfly_local_sources").storage_schema.serializeSchema(schema_alloc, native_schema);
    var schema_digest: [32]u8 = undefined;
    std.crypto.hash.Blake3.hash(layout, &schema_digest, .{});
    const binding: system_catalog.Resource = .{ .kind = .table, .id = 7, .parent_id = system_catalog.default_namespace_id, .name = "policies", .storage_name = table.name };
    const predicate: sql_policies.Predicate = .{ .instructions = &.{.{ .type = .{ .kind = .boolean, .nullable = false }, .operation = .{ .literal = .{ .bool = true } } }}, .root = 0 };
    const record: sql_policies.Record = .{ .id = 8, .generation = 1, .table_id = 7, .schema_version = 1, .schema_digest = schema_digest, .name = "owner_filter", .commands = .{ .select = true }, .roles = &.{"PUBLIC"}, .using = predicate };
    const range: metadata.RangeRecord = .{ .table_id = 7, .group_id = 17, .range_id = 17, .start_key = "", .end_key = null };
    const owner: sql_policies.Publication.OwnerIdentity = .{ .group_id = 17, .descriptor_digest = try (sql_policies.OwnerDescriptor{
        .table_id = 7,
        .group_id = 17,
        .shard_id = 17,
        .range_id = 17,
        .schema_version = 1,
        .schema_digest = schema_digest,
        .range_start = "",
        .range_end = "",
    }).digest() };
    const publication: sql_policies.Publication = .{ .table_id = 7, .schema_version = 1, .schema_digest = schema_digest, .generation = 1, .catalog_epoch = 3, .phase = .pending_install, .required_owners = &.{owner}, .acknowledged_owners = &.{} };
    var receipt: sql_policies.Publication.OwnerAck = .{ .owner = owner, .catalog_epoch = 3, .phase = .pending_install, .applied_term = 4, .applied_index = 91, .bundle_digest = @splat(0) };
    {
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        try store.updateStandaloneCatalog(group, 0, .{ .tables = &.{table}, .ranges = &.{range}, .auxiliary_json = "{}", .import_catalog = .{ .revision = 1, .next_id = 8, .resources = &.{binding} } });
        const definition = try std.json.Stringify.valueAlloc(alloc, sql_policies.Command{ .expected_revision = 1, .change = .{ .put = record } }, .{});
        defer alloc.free(definition);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policies = definition });
        const absent_status = try store.sqlPolicyPublicationStatusJson(alloc, group, table.table_id);
        defer alloc.free(absent_status);
        try std.testing.expectEqualStrings("null", absent_status);

        try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyBeginCommandJson(alloc, group, .{ .table_id = 7, .enable = false, .expected_revision = 2 }));
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyBeginCommandJson(alloc, group, .{ .table_id = 7, .enable = true, .expected_revision = 1 }));
        var forged_publication = publication;
        forged_publication.schema_digest = @splat(9);
        const forged_begin = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 2, .change = .{ .begin = forged_publication } }, .{});
        defer alloc.free(forged_begin);
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = forged_begin }));
        const begin = try store.sqlPolicyBeginCommandJson(alloc, group, .{ .table_id = 7, .enable = true, .expected_revision = 2 });
        defer alloc.free(begin);
        var generated_begin = try std.json.parseFromSlice(sql_policies.PublicationCommand, alloc, begin, .{});
        defer generated_begin.deinit();
        try std.testing.expectEqual(publication.generation, generated_begin.value.change.begin.generation);
        try std.testing.expectEqual(owner.group_id, generated_begin.value.change.begin.required_owners[0].group_id);
        try std.testing.expectEqualSlices(u8, &owner.descriptor_digest, &generated_begin.value.change.begin.required_owners[0].descriptor_digest);
        // A generation lock committed after the begin payload was prepared
        // must reject both fresh admission and the stale Raft apply. Policy
        // publication cannot install against a changing FK owner cut.
        var lock_key_buf: [160]u8 = undefined;
        const lock_key = try fk_generation_publication.tableLockKey(&lock_key_buf, group, table.table_id);
        {
            var lock_txn = try store.store.beginWriteTxn();
            errdefer lock_txn.abort();
            const lock_value = RaftApplyStore.fkTableLockValue(.generation, @splat(1));
            try lock_txn.put(lock_key, &lock_value);
            try lock_txn.commit();
        }
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyBeginCommandJson(alloc, group, .{ .table_id = 7, .enable = true, .expected_revision = 2 }));
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = begin }));
        {
            var unlock_txn = try store.store.beginWriteTxn();
            errdefer unlock_txn.abort();
            try unlock_txn.delete(lock_key);
            try unlock_txn.commit();
        }
        try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = begin });

        // Losing the stamp of an existing publication must fail closed rather
        // than turning a protected table into an unprotected one.
        {
            const stamp_key = try std.fmt.allocPrint(alloc, "\x00\x00__metadata__:system_catalog:{d}:policy-publication-stamp:{d}", .{ group, table.table_id });
            defer alloc.free(stamp_key);
            const stamp_bytes = blk: {
                var txn = try store.store.beginWriteTxn();
                errdefer txn.abort();
                const bytes = try alloc.dupe(u8, try txn.get(stamp_key));
                errdefer alloc.free(bytes);
                try txn.delete(stamp_key);
                try txn.commit();
                break :blk bytes;
            };
            defer alloc.free(stamp_bytes);
            try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyPublicationStatusJson(alloc, group, table.table_id));
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            try txn.put(stamp_key, stamp_bytes);
            try txn.commit();
        }
        const full_cut_validations_after_begin = store.policy_full_owner_cut_validations;
        const pending_work_bytes = try store.sqlPolicyPublicationWorkJson(alloc, group, 0);
        defer alloc.free(pending_work_bytes);
        var pending_work = try std.json.parseFromSlice(sql_policies.PublicationWork, alloc, pending_work_bytes, .{});
        defer pending_work.deinit();
        try std.testing.expectEqual(@as(u64, 7), pending_work.value.publication.?.table_id);
        try std.testing.expectEqual(sql_policies.Publication.Phase.pending_install, pending_work.value.publication.?.phase);
        try std.testing.expectError(error.RowPolicyUnsupported, store.sqlPolicySnapshotJson(alloc, group, 7, "alice", "main", &.{}));
        const install = try store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 1, .expected_catalog_epoch = 3, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
        defer alloc.free(install);
        std.crypto.hash.sha2.Sha256.hash(install, &receipt.bundle_digest, .{});
        var parsed = try std.json.parseFromSlice(sql_policies.InstallSnapshot, alloc, install, .{});
        defer parsed.deinit();
        try std.testing.expectEqual(sql_policies.Publication.Phase.pending_install, parsed.value.phase);
        try std.testing.expectEqual(@as(usize, 1), parsed.value.records.len);
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 2, .expected_catalog_epoch = 3, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest }));
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 1, .expected_catalog_epoch = 3, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = @splat(4) }));
        const ack = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 3, .change = .{ .acknowledge = .{ .table_id = 7, .generation = 1, .receipt = receipt } } }, .{});
        defer alloc.free(ack);
        var ack_fingerprint_key_buf: [192]u8 = undefined;
        const ack_fingerprint_key = try tableSchemaFingerprintKeyForGroup(&ack_fingerprint_key_buf, group, table.table_id);
        const valid_ack_fingerprint = try store.store.get(alloc, ack_fingerprint_key);
        defer alloc.free(valid_ack_fingerprint);
        try store.store.put(ack_fingerprint_key, &(@as([32]u8, @splat(9))));
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = ack }));
        try store.store.put(ack_fingerprint_key, valid_ack_fingerprint);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = ack });
        const premature_active = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 4, .change = .{ .promote = .{ .table_id = 7, .generation = 1, .phase = .active } } }, .{});
        defer alloc.free(premature_active);
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = premature_active }));
        const enter_serving = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 4, .change = .{ .promote = .{ .table_id = 7, .generation = 1, .phase = .serving_install } } }, .{});
        defer alloc.free(enter_serving);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = enter_serving });
        try std.testing.expectError(error.RowPolicyUnsupported, store.sqlPolicySnapshotJson(alloc, group, 7, "alice", "main", &.{}));
        const serving_install = try store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 1, .expected_catalog_epoch = 3, .expected_phase = .serving_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
        defer alloc.free(serving_install);
        var serving_receipt = receipt;
        serving_receipt.phase = .serving_install;
        serving_receipt.applied_index = 92;
        std.crypto.hash.sha2.Sha256.hash(serving_install, &serving_receipt.bundle_digest, .{});
        const serving_ack = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 5, .change = .{ .acknowledge = .{ .table_id = 7, .generation = 1, .receipt = serving_receipt } } }, .{});
        defer alloc.free(serving_ack);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = serving_ack });
        const promote = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 6, .change = .{ .promote = .{ .table_id = 7, .generation = 1, .phase = .active } } }, .{});
        defer alloc.free(promote);
        try store.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = promote });
        const idle_work_bytes = try store.sqlPolicyPublicationWorkJson(alloc, group, 0);
        defer alloc.free(idle_work_bytes);
        var idle_work = try std.json.parseFromSlice(sql_policies.PublicationWork, alloc, idle_work_bytes, .{});
        defer idle_work.deinit();
        try std.testing.expect(idle_work.value.publication == null);
        const replay_pending = try store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 1, .expected_catalog_epoch = 3, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
        defer alloc.free(replay_pending);
        try std.testing.expectEqualStrings(install, replay_pending);
        const active_install = try store.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 1, .expected_catalog_epoch = 3, .expected_phase = .active, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
        defer alloc.free(active_install);
        var active_parsed = try std.json.parseFromSlice(sql_policies.InstallSnapshot, alloc, active_install, .{});
        defer active_parsed.deinit();
        try std.testing.expectEqual(sql_policies.Publication.Phase.active, active_parsed.value.phase);
        const serving_bytes = try store.sqlPolicySnapshotJson(alloc, group, 7, "alice", "main", &.{});
        defer alloc.free(serving_bytes);
        var serving = try std.json.parseFromSlice(sql_policies.Snapshot, alloc, serving_bytes, .{});
        defer serving.deinit();
        try std.testing.expectEqual(@as(u64, 1), serving.value.policy_generation);
        try std.testing.expectEqual(@as(u64, 3), serving.value.catalog_epoch);
        try std.testing.expectEqual(@as(usize, 1), serving.value.records.len);
        const status_bytes = try store.sqlPolicyPublicationStatusJson(alloc, group, 7);
        defer alloc.free(status_bytes);
        try std.testing.expect(std.mem.indexOf(u8, status_bytes, "required_owners") == null);
        var status = try std.json.parseFromSlice(sql_policies.PublicationStamp, alloc, status_bytes, .{});
        defer status.deinit();
        try std.testing.expectEqual(full_cut_validations_after_begin, store.policy_full_owner_cut_validations);
        try std.testing.expectEqual(sql_policies.Publication.Phase.active, status.value.phase);
        const export_bytes = try store.exportSystemCatalog(alloc, group);
        defer alloc.free(export_bytes);
        var exported = try std.json.parseFromSlice(@import("../../system_catalog/projection.zig").Export, alloc, export_bytes, .{});
        defer exported.deinit();
        try std.testing.expectEqual(@as(usize, 1), exported.value.policy_install_snapshots.len);
        try std.testing.expectEqual(@as(u64, 1), exported.value.policy_install_snapshots[0].policy_generation);
        try std.testing.expectEqual(@as(usize, 1), exported.value.policy_install_snapshots[0].records.len);
        const projection = @import("../../system_catalog/projection.zig");
        try projection.validatePolicyPrograms(alloc, exported.value.system_catalog.policy_publications, exported.value.policy_install_snapshots);
        try std.testing.expectError(error.RowPolicyCatalogChanged, projection.validatePolicyPrograms(alloc, exported.value.system_catalog.policy_publications, &.{}));
        var wrong_program = exported.value.policy_install_snapshots[0];
        wrong_program.catalog_epoch += 1;
        try std.testing.expectError(error.RowPolicyCatalogChanged, projection.validatePolicyPrograms(alloc, exported.value.system_catalog.policy_publications, &.{wrong_program}));
        try std.testing.expect(status.value.topology_generation != 0);
        try std.testing.expect(!std.mem.allEqual(u8, &status.value.schema_record_digest, 0));
        var fingerprint_key_buf: [192]u8 = undefined;
        const fingerprint_key = try tableSchemaFingerprintKeyForGroup(&fingerprint_key_buf, group, table.table_id);
        const original_fingerprint = try store.store.get(alloc, fingerprint_key);
        defer alloc.free(original_fingerprint);
        try store.store.put(fingerprint_key, &(@as([32]u8, @splat(9))));
        try std.testing.expectError(error.RowPolicyCatalogChanged, store.sqlPolicyPublicationStatusJson(alloc, group, table.table_id));
        try store.store.put(fingerprint_key, original_fingerprint);
        try std.testing.expectError(error.RowPolicyUnsupported, store.requirePolicyTopologyMutationAllowed(group, table.table_id));
        var changed_range = range;
        changed_range.doc_identity_range_id = 18;
        try store.applyStandaloneCommand(group, .{ .upsert_range = changed_range });
        const retained_range = (try store.getRange(alloc, group, range.group_id)).?;
        defer metadata_table_manager.freeRange(alloc, retained_range);
        try std.testing.expectEqual(range.doc_identity_range_id, retained_range.doc_identity_range_id);
        var state = try store.systemCatalogSnapshot(alloc, group);
        defer state.deinit();
        try std.testing.expectEqual(@as(usize, 1), state.value.policy_publications.len);
        try std.testing.expectEqual(sql_policies.Publication.Phase.active, state.value.policy_publications[0].phase);
        try std.testing.expectEqual(@as(u64, 91), state.value.policy_publications[0].acknowledged_owners[0].applied_index);
        try std.testing.expectEqual(@as(u64, 92), state.value.policy_publications[0].serving_acknowledged_owners[0].applied_index);
        {
            var lock_txn = try store.store.beginWriteTxn();
            errdefer lock_txn.abort();
            const lock_value = RaftApplyStore.fkTableLockValue(.generation, @splat(2));
            try lock_txn.put(lock_key, &lock_value);
            try lock_txn.commit();
        }
        {
            var admission = try store.store.beginReadTxn();
            defer admission.abort();
            try std.testing.expectError(error.RowPolicyCatalogChanged, store.validatePolicyPublicationStampTxn(&admission, group, state.value.policy_publications[0]));
        }
        {
            var unlock_txn = try store.store.beginWriteTxn();
            errdefer unlock_txn.abort();
            try unlock_txn.delete(lock_key);
            try unlock_txn.commit();
        }
        // Unified relational index DDL is a schema-epoch mutation. An
        // uncoupled Raft proposal must deterministically no-op, not publish a
        // layout that leaves the active owner policy bound to the old schema.
        var indexed = table;
        indexed.schema_json =
            \\{"version":2,"storage_mode":"relational","default_type":"row","relational_indexes":[{"name":"by_id","keys":[{"column":"id"}]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
        ;
        try std.testing.expectError(error.RowPolicyUnsupported, store.requirePolicyIndexMutationAllowed(group, table.table_id));
        {
            var admission = try store.store.beginReadTxn();
            defer admission.abort();
            try std.testing.expect(!try store.policyDefinitionMutationAllowedTxn(&admission, group, table, indexed));
        }
        try store.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = table, .replacement = indexed } });
        const retained = (try store.getTable(alloc, group, table.table_id)).?;
        defer metadata_table_manager.freeTable(alloc, retained);
        try std.testing.expectEqualStrings(table.schema_json, retained.schema_json);
    }
    {
        var reopened = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer reopened.deinit();
        var state = try reopened.systemCatalogSnapshot(alloc, group);
        defer state.deinit();
        try std.testing.expectEqual(sql_policies.Publication.Phase.active, state.value.policy_publications[0].phase);
        var revised_record = record;
        revised_record.generation = 2;
        const draft = try std.json.Stringify.valueAlloc(alloc, sql_policies.Command{ .expected_revision = 7, .change = .{ .put = revised_record } }, .{});
        defer alloc.free(draft);
        try reopened.applyStandaloneCommand(group, .{ .apply_sql_policies = draft });
        const before_install = try reopened.sqlPolicySnapshotJson(alloc, group, 7, "alice", "main", &.{});
        defer alloc.free(before_install);
        var prior_serving = try std.json.parseFromSlice(sql_policies.Snapshot, alloc, before_install, .{});
        defer prior_serving.deinit();
        try std.testing.expectEqual(@as(u64, 1), prior_serving.value.records[0].generation);
        const begin_successor = try reopened.sqlPolicyBeginCommandJson(alloc, group, .{ .table_id = 7, .enable = true, .expected_revision = 8 });
        defer alloc.free(begin_successor);
        try reopened.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = begin_successor });
        try std.testing.expectError(error.RowPolicyPublicationInProgress, reopened.exportSystemCatalog(alloc, group));
        const successor_full_cut_validations = reopened.policy_full_owner_cut_validations;
        const resumed_work_bytes = try reopened.sqlPolicyPublicationWorkJson(alloc, group, 7);
        defer alloc.free(resumed_work_bytes);
        var resumed_work = try std.json.parseFromSlice(sql_policies.PublicationWork, alloc, resumed_work_bytes, .{});
        defer resumed_work.deinit();
        try std.testing.expectEqual(@as(u64, 7), resumed_work.value.publication.?.table_id);
        try std.testing.expectEqual(@as(u64, 2), resumed_work.value.publication.?.generation);
        const during_install = try reopened.sqlPolicySnapshotJson(alloc, group, 7, "alice", "main", &.{});
        defer alloc.free(during_install);
        try std.testing.expectEqualStrings(before_install, during_install);
        const candidate_status_bytes = try reopened.sqlPolicyPublicationStatusJson(alloc, group, 7);
        defer alloc.free(candidate_status_bytes);
        var candidate_status = try std.json.parseFromSlice(sql_policies.PublicationStamp, alloc, candidate_status_bytes, .{});
        defer candidate_status.deinit();
        try std.testing.expectEqual(successor_full_cut_validations, reopened.policy_full_owner_cut_validations);
        const prior_authority = (try candidate_status.value.servingAuthority()).?;
        try std.testing.expectEqual(@as(u64, 1), prior_authority.generation);
        try std.testing.expectEqual(@as(u64, 3), prior_authority.catalog_epoch);
        const candidate = try reopened.sqlPolicyInstallSnapshotJson(alloc, group, .{ .table_id = 7, .expected_generation = 2, .expected_catalog_epoch = 9, .expected_phase = .pending_install, .owner_group_id = owner.group_id, .expected_descriptor_digest = owner.descriptor_digest });
        defer alloc.free(candidate);
        var candidate_parsed = try std.json.parseFromSlice(sql_policies.InstallSnapshot, alloc, candidate, .{});
        defer candidate_parsed.deinit();
        try std.testing.expectEqual(@as(u64, 2), candidate_parsed.value.records[0].generation);
        var moved = range;
        moved.doc_identity_range_id = 18;
        try std.testing.expectError(error.TableLifecycleConflict, reopened.updateStandaloneCatalog(group, try reopened.standaloneRevision(), .{ .tables = &.{table}, .ranges = &.{moved}, .auxiliary_json = "{}" }));
        const stale_ack = try std.json.Stringify.valueAlloc(alloc, sql_policies.PublicationCommand{ .expected_revision = 9, .change = .{ .acknowledge = .{ .table_id = 7, .generation = 2, .receipt = receipt } } }, .{});
        defer alloc.free(stale_ack);
        try std.testing.expectError(error.RowPolicyCatalogChanged, reopened.applyStandaloneCommand(group, .{ .apply_sql_policy_publication = stale_ack }));
        const fence = try reopened.getTableTransitionFence(group, table.table_id);
        try reopened.applyStandaloneCommand(group, .{ .apply_table_topology = .{ .drop = .{
            .table_id = table.table_id,
            .expected_name = table.name,
            .expected_transition_generation = fence.generation,
            .range_contract = .{ .legacy_group_ids = &.{range.group_id} },
        } } });
        const after_drop_bytes = try reopened.sqlPolicyPublicationWorkJson(alloc, group, 0);
        defer alloc.free(after_drop_bytes);
        var after_drop = try std.json.parseFromSlice(sql_policies.PublicationWork, alloc, after_drop_bytes, .{});
        defer after_drop.deinit();
        try std.testing.expect(after_drop.value.publication == null);
    }
}

test "system catalog SQL settings load owns allocations from the final prefix scan" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/setting-scan-ownership", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    // Even an empty setting prefix allocates after resource decoding. A
    // copied ArenaAllocator must therefore be returned only after this scan.
    for (0..4) |_| {
        var state = try store.systemCatalogSnapshot(alloc, group_ids.main_metadata_group_id);
        try std.testing.expectEqual(@as(usize, 0), state.value.settings.len);
        state.deinit();
    }
}

test "metadata apply store replay is idempotent when applied watermark lags WAL state" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const root = try std.fmt.allocPrint(std.testing.allocator, ".zig-cache/tmp/{s}/metadata-apply-replay-idempotent", .{tmp.sub_path});
    defer std.testing.allocator.free(root);

    var layout = try raft_storage_mod.ReplicaPathLayout.initForReplica(std.testing.allocator, root, 202, 1);
    defer layout.deinit(std.testing.allocator);

    const cmd = try encodeTransitionCommand(std.testing.allocator, .{
        .upsert_table = testTransitionTableRecord(),
    });
    defer std.testing.allocator.free(cmd);

    {
        var wal_state = try wal_replica_state_mod.WalReplicaState.init(std.testing.allocator, layout, .{});
        defer wal_state.deinit();

        const entries = try std.testing.allocator.dupe(raft_engine.core.Entry, &[_]raft_engine.core.Entry{
            .{ .term = 5, .index = 1, .entry_type = .normal, .data = cmd },
        });
        defer std.testing.allocator.free(entries);

        try wal_state.groupStorage().persistReady(202, .{
            .hard_state = .{ .current_term = 5, .voted_for = 1, .commit_index = 1 },
            .entries = entries,
        });
    }

    {
        var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
        defer store.deinit();

        var sm = raft_state_machine.MetadataStateMachine{
            .alloc = std.testing.allocator,
            .applied_sink = raft_state_machine.noopAppliedIndexSink(),
            .snapshot_builder = store.snapshotBuilder(),
        };
        try sm.stateMachine().applyReady(202, null, &.{
            .{ .term = 5, .index = 1, .entry_type = .normal, .data = cmd },
        }, &.{});
    }

    {
        var wal_state = try wal_replica_state_mod.WalReplicaState.init(std.testing.allocator, layout, .{});
        defer wal_state.deinit();
        try std.testing.expectEqual(@as(u64, 0), wal_state.appliedIndex());

        var raw = try raft_engine.core.RawNode.init(std.testing.allocator, .{
            .id = 1,
            .group_id = 202,
            .peers = &.{1},
            .election_tick = 5,
            .heartbeat_tick = 1,
            .pre_vote = false,
            .check_quorum = true,
            .applied = wal_state.appliedIndex(),
        }, wal_state.storage());
        defer raw.deinit();

        try std.testing.expect(raw.hasReady());
        const rd = raw.ready();
        try std.testing.expectEqual(@as(usize, 1), rd.committed_entries.len);

        var store = try RaftApplyStore.init(std.testing.allocator, .{ .root_dir = root });
        defer store.deinit();

        var sm = raft_state_machine.MetadataStateMachine{
            .alloc = std.testing.allocator,
            .applied_sink = raft_state_machine.noopAppliedIndexSink(),
            .snapshot_builder = store.snapshotBuilder(),
        };
        try sm.stateMachine().applyReady(202, rd.snapshot, rd.committed_entries, &.{});

        const batch = (try store.latestCheckpoint(202)) orelse return error.MissingMetadataBatch;
        try std.testing.expectEqual(@as(u64, 1), batch.commit_index);

        const tables = try store.listTables(std.testing.allocator, 202);
        defer store.freeTables(std.testing.allocator, tables);
        try std.testing.expectEqual(@as(usize, 1), tables.len);
        try std.testing.expectEqual(
            test_transition_table_contract.table_id,
            tables[0].table_id,
        );
        try std.testing.expectEqualStrings(
            test_transition_table_contract.table_name,
            tables[0].name,
        );
    }
}
const restore_job_logical_prefix = "\x00\x00__api_restore_jobs__:";
const max_restore_job_logical_key_bytes: usize = 128;
const max_restore_job_value_bytes: usize = 64 * 1024;

fn applySystemCatalogTestCommand(store: *RaftApplyStore, index: u64, command: SystemCatalogCommand) !void {
    const alloc = std.testing.allocator;
    const json = try std.json.Stringify.valueAlloc(alloc, command, .{});
    defer alloc.free(json);
    const encoded = try encodeTransitionCommand(alloc, .{ .apply_system_catalog = json });
    defer alloc.free(encoded);
    var decoded = (try decodeTransitionCommand(alloc, encoded)).?;
    defer decoded.deinit(alloc);
    try std.testing.expectEqualStrings(json, decoded.apply_system_catalog);
    const entries = try raft_state_machine.encodeCommittedEntries(alloc, &.{.{ .term = 1, .index = index, .entry_type = .normal, .data = encoded }});
    defer alloc.free(entries);
    try store.snapshotBuilder().applyBatch(.{ .group_id = 21, .commit_index = index, .entries_bytes = entries });
}

test "system catalog qualified DROP removes topology atomically and rejects stale identity" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/catalog-drop", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const table: metadata.TableRecord = .{ .table_id = 42, .name = "table:42", .min_ranges = 1 };
    const ranges = [_]metadata.RangeRecord{.{ .table_id = 42, .group_id = 301, .range_id = 301, .start_key = "" }};
    try applySystemCatalogTestCommand(&store, 1, .{ .expected_revision = 0, .mutation = .{ .action = .create, .kind = .table, .name = "events", .table_id = 42, .storage_name = "table:42" }, .topology = .{ .create = .{ .expected_transition_generation = 0, .table = table, .ranges = &ranges } } });
    var membership: topology_protocol.RangeMembershipAccumulator = .{};
    try membership.add(301);
    var drop: SystemCatalogCommand = .{ .expected_revision = 1, .mutation = .{ .action = .drop, .kind = .table, .name = "events", .table_id = 42, .storage_name = "table:42" }, .topology = .{ .drop = .{ .table_id = 42, .expected_name = "table:42", .expected_transition_generation = 1, .range_contract = .{ .membership = membership.finish(42) } } } };
    const admitted = try store.prepareSystemCatalogResult(alloc, 21, drop);
    defer alloc.free(admitted);
    drop.topology.?.drop.table_id = 43;
    try std.testing.expectError(error.InvalidCatalogMutation, store.prepareSystemCatalogResult(alloc, 21, drop));
    drop.topology.?.drop.table_id = 42;
    drop.topology.?.drop.expected_transition_generation = 0;
    try applySystemCatalogTestCommand(&store, 2, drop);
    try std.testing.expectEqual(@as(u64, 1), (try store.systemCatalogMeta(alloc, 21)).revision);
    drop.topology.?.drop.expected_transition_generation = 1;
    try applySystemCatalogTestCommand(&store, 3, drop);
    try std.testing.expectEqual(@as(?metadata.TableRecord, null), try store.resolveSystemCatalogTable(alloc, 21, .{ .table = "events" }));
    const remaining = try store.listTables(alloc, 21);
    defer {
        for (remaining) |entry| metadata_table_manager.freeTable(alloc, entry);
        alloc.free(remaining);
    }
    try std.testing.expectEqual(@as(usize, 0), remaining.len);
    try std.testing.expectEqual(@as(u64, 2), (try store.systemCatalogMeta(alloc, 21)).revision);
}

test "system catalog publishes names and table topology atomically and fences stale mutations" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/antfly-system-catalog", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    try applySystemCatalogTestCommand(&store, 1, .{ .expected_revision = 0, .mutation = .{ .action = .create, .kind = .database, .name = "analytics" } });
    const large_description = @as([(256 * 1024)]u8, @splat('x'));
    const table: metadata.TableRecord = .{ .table_id = 42, .name = "table:42", .description = &large_description, .min_ranges = 1 };
    const ranges = [_]metadata.RangeRecord{.{ .table_id = 42, .group_id = 301, .range_id = 301, .start_key = "" }};
    try applySystemCatalogTestCommand(&store, 2, .{ .expected_revision = 1, .mutation = .{ .action = .create, .kind = .table, .name = "events", .database = "analytics", .table_id = 42, .storage_name = "table:42" }, .topology = .{ .create = .{ .expected_transition_generation = 0, .table = table, .ranges = &ranges } } });
    {
        const resolved = (try store.resolveSystemCatalogTable(alloc, 21, .{ .database = "analytics", .table = "events" })).?;
        defer metadata_table_manager.freeTable(alloc, resolved);
        try std.testing.expectEqual(@as(u64, 42), resolved.table_id);
        try std.testing.expectEqualStrings("table:42", resolved.name);
    }
    {
        const targets = [_]system_catalog.Target{ .{ .database = "analytics", .table = "events" }, .{ .database = "analytics", .table = "missing" } };
        const resolved = try store.resolveSystemCatalogIdentities(alloc, 21, .{ .targets = &targets, .expected_revision = 2 });
        defer resolved.deinit(alloc);
        try std.testing.expectEqual(@as(u64, 2), resolved.revision);
        try std.testing.expectEqual(@as(u64, 42), resolved.tables[0].?.table_id);
        try std.testing.expect(resolved.tables[1] == null);
        try std.testing.expectError(error.CatalogGenerationChanged, store.resolveSystemCatalogIdentities(alloc, 21, .{ .targets = &targets, .expected_revision = 1 }));
    }
    // The hot-path response must neither serialize nor allocate the table's
    // potentially large definition. Its allocator budget is independent of it.
    {
        var buffer: [16 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const identity = (try store.resolveSystemCatalogIdentity(bounded.allocator(), 21, .{ .database = "analytics", .table = "events" })).?;
        const encoded = try std.json.Stringify.valueAlloc(alloc, identity, .{});
        defer alloc.free(encoded);
        try std.testing.expectEqualStrings("{\"table_id\":42,\"name\":\"table:42\"}", encoded);
    }
    {
        var buffer: [16 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const definition = (try store.queryTableDefinition(bounded.allocator(), 21, "table:42")).?;
        defer definition.deinit(bounded.allocator());
        try std.testing.expectEqualStrings(table.schema_json, definition.schema_json);
        try std.testing.expectEqualStrings(table.indexes_json, definition.indexes_json);
    }
    {
        // Administrative inventory has the same schema-independent allocation
        // bound as point resolution, including the cursor's borrowed values.
        var buffer: [16 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        var txn = try store.store.beginReadTxn();
        defer txn.abort();
        const physical = try RaftApplyStore.listPhysicalTableIdentities(bounded.allocator(), &txn, 21);
        defer RaftApplyStore.freePhysicalTableIdentities(bounded.allocator(), physical);
        try std.testing.expectEqual(@as(usize, 1), physical.len);
        try std.testing.expectEqual(@as(u64, 42), physical[0].id);
        try std.testing.expectEqualStrings("table:42", physical[0].name);
    }
    try applySystemCatalogTestCommand(&store, 3, .{ .expected_revision = 2, .mutation = .{ .action = .rename, .kind = .database, .name = "analytics", .new_name = "reports" } });
    try std.testing.expectEqual(@as(?metadata.TableRecord, null), try store.resolveSystemCatalogTable(alloc, 21, .{ .database = "analytics", .table = "events" }));
    const renamed = (try store.resolveSystemCatalogTable(alloc, 21, .{ .database = "reports", .table = "events" })).?;
    defer metadata_table_manager.freeTable(alloc, renamed);
    try std.testing.expectEqual(@as(u64, 42), renamed.table_id);
    {
        const projection = @import("../../system_catalog/projection.zig");
        const bytes = try store.listSystemCatalogTables(alloc, 21, .{ .database = "reports" });
        defer alloc.free(bytes);
        var listing = try std.json.parseFromSlice(projection.TableListing, alloc, bytes, .{});
        defer listing.deinit();
        try std.testing.expectEqual(@as(u64, 3), listing.value.revision);
        try std.testing.expectEqual(@as(usize, 1), listing.value.entries.len);
        try std.testing.expectEqualStrings("events", listing.value.entries[0].name);
        try std.testing.expectEqual(@as(u64, 42), listing.value.entries[0].table.table_id);
        try std.testing.expectEqual(@as(usize, 1), listing.value.ranges.len);
        const exported = try store.exportSystemCatalog(alloc, 21);
        defer alloc.free(exported);
        var portable = try std.json.parseFromSlice(projection.Export, alloc, exported, .{});
        defer portable.deinit();
        try std.testing.expectEqual(@as(u64, 3), portable.value.system_catalog.revision);
        try std.testing.expect(portable.value.system_catalog.find(.database, 0, "reports") != null);
        try std.testing.expectEqual(@as(u64, 42), portable.value.tables[0].table_id);
        // Selecting no tables must not allocate the unrelated 256 KiB definition.
        var buffer: [32 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const empty = try store.listSystemCatalogTables(bounded.allocator(), 21, .{ .database = "reports", .prefix = "absent" });
        try std.testing.expect(std.mem.indexOf(u8, empty, "events") == null);
        bounded.reset();
        const default_empty = try store.listSystemCatalogTables(bounded.allocator(), 21, .{});
        try std.testing.expect(std.mem.indexOf(u8, default_empty, "table:42") == null);
    }
    // The predecessor catalog revision cannot admit a destructive mutation.
    try applySystemCatalogTestCommand(&store, 4, .{ .expected_revision = 2, .mutation = .{ .action = .create, .kind = .database, .name = "stale" } });
    var snapshot = try store.systemCatalogSnapshot(alloc, 21);
    defer snapshot.deinit();
    try std.testing.expectEqual(@as(u64, 3), snapshot.meta.revision);
    try std.testing.expect(snapshot.value.find(.database, 0, "stale") == null);
    try std.testing.expectError(error.DatabaseNotEmpty, store.validateSystemCatalog(21, .{ .expected_revision = 3, .mutation = .{ .action = .drop, .kind = .database, .name = "reports" } }));
    const snapshot_bytes = try store.snapshotBuilder().buildSnapshot(alloc, 21);
    defer alloc.free(snapshot_bytes);
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    const target_root = try std.fmt.allocPrint(alloc, "{s}-restored", .{root});
    defer alloc.free(target_root);
    var restored = try RaftApplyStore.init(alloc, .{ .root_dir = target_root });
    defer restored.deinit();
    try std.testing.expect(try restored.snapshotBuilder().installSnapshot(alloc, 21, 4, snapshot_bytes));
    for ([_]*RaftApplyStore{ &store, &restored }) |reader| {
        const found = (try reader.resolveSystemCatalogTable(alloc, 21, .{ .database = "reports", .table = "events" })).?;
        defer metadata_table_manager.freeTable(alloc, found);
        try std.testing.expectEqual(@as(u64, 42), found.table_id);
        try std.testing.expectEqualStrings("table:42", found.name);
    }
    // A damaged derived name row cannot masquerade as an absent database.
    {
        var txn = try restored.store.beginWriteTxn();
        errdefer txn.abort();
        const key = try system_catalog_storage.nameKeyAlloc(alloc, 21, .database, 0, "reports");
        defer alloc.free(key);
        try txn.delete(key);
        try txn.commit();
    }
    // Reopen is a projection trust boundary: reconstruct missing derived rows
    // from authoritative records before allowing constant-time negative reads.
    restored.deinit();
    restored = try RaftApplyStore.init(alloc, .{ .root_dir = target_root });
    const repaired = (try restored.resolveSystemCatalogTable(alloc, 21, .{ .database = "reports", .table = "events" })).?;
    defer metadata_table_manager.freeTable(alloc, repaired);
    try std.testing.expectEqualStrings("table:42", repaired.name);
}

test "system catalog legacy and missing point reads have catalog-independent allocation" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/catalog-point-reads", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        for (0..1000) |i| {
            const name = try std.fmt.allocPrint(alloc, "database_{d}", .{i});
            defer alloc.free(name);
            try system_catalog_storage.writeResource(alloc, &txn, 21, .{ .kind = .database, .id = 100 + i, .name = name });
        }
        const encoded = try encodeTableRecord(alloc, .{ .table_id = 7, .name = "legacy" });
        defer alloc.free(encoded);
        var buf: [160]u8 = undefined;
        try txn.put(try tableKeyForGroup(&buf, 21, 7), encoded);
        try txn.commit();
    }
    try store.ensureQueryCatalogIndexes(21);
    for ([_]system_catalog.Target{ .{ .table = "legacy" }, .{ .table = "missing" }, .{ .database = "missing", .table = "legacy" } }, 0..) |target, i| {
        var buffer: [4096]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const result = try store.resolveSystemCatalogIdentity(bounded.allocator(), 21, target);
        defer if (result) |value| value.deinit(bounded.allocator());
        if (i == 0) try std.testing.expectEqualStrings("legacy", result.?.name) else try std.testing.expect(result == null);
    }
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root, .read_only = true });
    const result = (try store.resolveSystemCatalogIdentity(alloc, 21, .{ .table = "legacy" })).?;
    defer result.deinit(alloc);
    try std.testing.expectEqual(@as(u64, 7), result.table_id);
}

test "system catalog indexed management reads and mutation planning ignore unrelated inventory" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/catalog-management", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        for (0..1000) |i| {
            const name = try std.fmt.allocPrint(alloc, "database_{d}", .{i});
            defer alloc.free(name);
            try system_catalog_storage.writeResource(alloc, &txn, 21, .{ .kind = .database, .id = 100 + i, .name = name });
        }
        try txn.commit();
    }
    try store.ensureQueryCatalogIndexes(21);
    {
        var buffer: [16 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const a = bounded.allocator();
        var txn = try store.beginQueryCatalogReadTxn(21);
        defer txn.abort();
        const view: system_catalog_storage.View = .{ .alloc = a, .txn = &txn, .group_id = 21, .meta = try system_catalog_storage.readMeta(a, &txn, 21) };
        const selected = try view.read(.{ .kind = .database, .name = "database_999" });
        try std.testing.expectEqual(@as(usize, 1), selected.resources.len);
        const reader: RaftApplyStore.CatalogReader = .{ .store = &store, .view = view };
        const delta = try system_catalog.planWithReader(a, reader, view.meta.next_id, .{ .action = .rename, .kind = .database, .name = "database_999", .new_name = "renamed" });
        try std.testing.expectEqual(@as(usize, 1), delta.upserts.len);
        try std.testing.expectEqualStrings("renamed", delta.upserts[0].name);
    }
    // Reverse references move with the authoritative record and rebuild after
    // reopen. A cleared binding must not keep its former tablespace in use.
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        var db: system_catalog.Resource = .{ .kind = .database, .id = 100, .name = "database_0", .tablespace_id = 70 };
        try system_catalog_storage.writeResource(alloc, &txn, 21, db);
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const view: system_catalog_storage.View = .{ .alloc = arena.allocator(), .txn = &txn, .group_id = 21, .meta = .{} };
        try std.testing.expect(try view.tablespaceInUse(70));
        db.tablespace_id = 0;
        try system_catalog_storage.writeResource(alloc, &txn, 21, db);
        try std.testing.expect(!try view.tablespaceInUse(70));
        try txn.commit();
    }
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    const response = try store.systemCatalogRead(alloc, 21, .{ .kind = .database, .name = "database_999" });
    defer alloc.free(response);
    try std.testing.expect(std.mem.indexOf(u8, response, "database_999") != null);
    try std.testing.expect(std.mem.indexOf(u8, response, "database_998") == null);
}

test "system catalog listing indexes bound legacy pages and runtime reports across rebuild" {
    const alloc = std.testing.allocator;
    const projection = @import("../../system_catalog/projection.zig");
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/catalog-pages", .{tmp.sub_path});
    defer alloc.free(root);
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    const huge = @as([(256 * 1024)]u8, @splat('x'));
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        _ = try store.ensureDerivedCatalogIndexesTxn(&txn, 21);
        for ([_][]const u8{ "a", "b", "z" }, 1..) |name, id| try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_table = .{ .table_id = id, .name = name, .description = if (id == 3) &huge else "" } });
        for ([_]u64{ 301, 40, 41 }) |id| try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_range = .{ .table_id = 1, .group_id = id, .range_id = id, .start_key = "" } });
        var reports = [_]metadata.RuntimeGroupStatusReport{
            .{ .table_id = 1, .table_name = "a", .group_id = 301, .store_id = 20 },
            .{ .table_id = 3, .table_name = &huge, .group_id = 303, .store_id = 20 },
        };
        var group_statuses: [2000]metadata.GroupStatusReport = undefined;
        for (&group_statuses, 301..) |*status, id| status.* = .{ .group_id = id };
        // Lexical key order differs from numeric range order; group 41 is absent.
        group_statuses[group_statuses.len - 1] = .{ .group_id = 40 };
        try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_store = .{ .store_id = 20, .node_id = 30, .runtime_statuses = &reports, .group_statuses = &group_statuses } });
        try txn.commit();
    }
    var fingerprint: [32]u8 = undefined;
    for (0..2) |round| {
        if (round == 1) {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            var buf: [160]u8 = undefined;
            try txn.delete(try derivedCatalogIndexVersionKey(&buf, 21));
            _ = try store.ensureDerivedCatalogIndexesTxn(&txn, 21);
            try txn.commit();
        }
        var buffer: [128 * 1024]u8 = undefined;
        var bounded = std.heap.FixedBufferAllocator.init(&buffer);
        const bytes = try store.listSystemCatalogTables(bounded.allocator(), 21, .{ .limit = 1 });
        var parsed = try std.json.parseFromSlice(projection.TableListing, alloc, bytes, .{});
        defer parsed.deinit();
        const first = parsed.value;
        try std.testing.expectEqualStrings("a", first.entries[0].name);
        try std.testing.expectEqual(@as(?u64, 1), first.next_table_id);
        try std.testing.expectEqual(@as(usize, 1), first.stores[0].runtime_statuses.len);
        try std.testing.expectEqual(@as(usize, 2), first.stores[0].group_statuses.len);
        try std.testing.expect(first.stores[0].group_statuses[0].group_id + first.stores[0].group_statuses[1].group_id == 341);
        try std.testing.expectEqual(@as(u64, 301), first.stores[0].runtime_statuses[0].group_id);
        if (round == 0) fingerprint = first.legacy_membership else try std.testing.expectEqualSlices(u8, &fingerprint, &first.legacy_membership);
        bounded.reset();
        const second = try store.listSystemCatalogTables(bounded.allocator(), 21, .{ .limit = 1, .after_table_id = first.next_table_id, .revision = first.revision, .legacy_membership = fingerprint });
        var page = try std.json.parseFromSlice(projection.TableListing, alloc, second, .{});
        defer page.deinit();
        try std.testing.expectEqualStrings("b", page.value.entries[0].name);
        try std.testing.expectEqual(@as(usize, 0), page.value.stores.len);
    }
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        // Heartbeat replacement removes old report rows without changing cursors.
        try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_store = .{ .store_id = 20, .node_id = 30 } });
        const removed_key = try RaftApplyStore.listingReportKey(alloc, 21, 20, 301);
        defer alloc.free(removed_key);
        try std.testing.expectError(error.NotFound, txn.get(removed_key));
        try txn.commit();
    }
    const unchanged = try store.listSystemCatalogTables(alloc, 21, .{ .limit = 1, .legacy_membership = fingerprint });
    alloc.free(unchanged);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_table = .{ .table_id = 4, .name = "new" } });
        try txn.commit();
    }
    try std.testing.expectError(error.CatalogGenerationChanged, store.listSystemCatalogTables(alloc, 21, .{ .limit = 1, .legacy_membership = fingerprint }));
}

test "system catalog normalized store reports preserve clocks duplicates migration and wire snapshots" {
    const alloc = std.testing.allocator;
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/normalized-reports", .{tmp.sub_path});
    var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    defer store.deinit();
    var groups = [_]metadata.GroupStatusReport{
        .{ .group_id = 301, .raft_term = 7, .updated_at_millis = 100 },
        .{ .group_id = 301, .raft_term = 8, .updated_at_millis = 101 },
    };
    var runtimes = [_]metadata.RuntimeGroupStatusReport{
        .{ .group_id = 301, .store_id = 20, .table_id = 1, .table_name = "docs", .updated_at_ns = 123 },
        .{ .group_id = 301, .store_id = 20, .table_id = 1, .table_name = "docs", .updated_at_ns = 124 },
    };
    var record: metadata.StoreRecord = .{ .store_id = 20, .node_id = 30, .reporter_incarnation = 50, .group_statuses = &groups, .runtime_statuses = &runtimes };
    var key_buf: [160]u8 = undefined;
    const key = try storeKeyForGroup(&key_buf, 21, 20);
    const payload_key = try RaftApplyStore.listingReportKey(a, 21, 20, 301);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        // Import the exact pre-normalization primary encoding.
        try txn.put(key, try encodeStoreRecord(a, record));
        _ = try store.ensureDerivedCatalogIndexesTxn(&txn, 21);
        try txn.commit();
    }
    const payload_page_key = try RaftApplyStore.reportPageKey(a, 21, 20, 0, false);
    const payload = try store.store.get(a, payload_page_key);
    const before = store.snapshotWriteStats().wal_append_bytes;
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        _ = try store.updateListingStoreTxn(&txn, 21, 20, record);
        try txn.commit();
    }
    try std.testing.expect(store.snapshotWriteStats().wal_append_bytes - before < 128);
    groups[0].updated_at_millis = 200;
    runtimes[1].updated_at_ns = 250;
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        _ = try store.updateListingStoreTxn(&txn, 21, 20, record);
        try std.testing.expectEqualSlices(u8, payload, try txn.get(payload_page_key));
        try txn.commit();
    }
    store.deinit();
    store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
    const recovered = try store.listStores(a, 21);
    try std.testing.expectEqual(@as(usize, 2), recovered[0].group_statuses.len);
    try std.testing.expectEqual(@as(u64, 7), recovered[0].group_statuses[0].raft_term);
    try std.testing.expectEqual(@as(u64, 8), recovered[0].group_statuses[1].raft_term);
    try std.testing.expectEqual(@as(u64, 200), recovered[0].group_statuses[0].updated_at_millis);
    try std.testing.expectEqual(@as(u64, 250), recovered[0].runtime_statuses[1].updated_at_ns);
    const snapshot = try store.snapshotBuilder().buildSnapshot(a, 21);
    const rows = try decodeMetadataSnapshotAlloc(a, snapshot);
    var saw_store = false;
    for (rows) |row| if (std.mem.eql(u8, key, row.key)) {
        // The old decoder must read exported snapshots without local magic.
        const decoded = try decodeStoreRecord(a, row.value);
        try std.testing.expectEqual(@as(usize, 2), decoded.runtime_statuses.len);
        try std.testing.expectEqual(@as(u64, 250), decoded.runtime_statuses[1].updated_at_ns);
        saw_store = true;
    };
    try std.testing.expect(saw_store);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        record.node_id = 40;
        record.reporter_incarnation = 60;
        _ = try store.updateListingStoreTxn(&txn, 21, 20, record);
        _ = try store.updateListingStoreTxn(&txn, 22, 20, record);
        // Installing a complete snapshot can repair a missing local payload;
        // enumerating replaced keys must not require hydrating damaged rows.
        try txn.delete(try RaftApplyStore.reportPageKey(a, 21, 20, 0, true));
        try txn.commit();
    }
    try std.testing.expect(try store.snapshotBuilder().installSnapshot(a, 21, 1, snapshot));
    try std.testing.expectError(error.NotFound, store.store.get(a, payload_key));
    try store.ensureDerivedCatalogIndexes(21);
    const restored = try store.listStores(a, 21);
    try std.testing.expectEqual(@as(u64, 30), restored[0].node_id);
    try std.testing.expectEqual(@as(u64, 50), restored[0].reporter_incarnation);
    try std.testing.expectEqual(@as(usize, 2), restored[0].runtime_statuses.len);
    const other = try store.listStores(a, 22);
    try std.testing.expectEqual(@as(u64, 40), other[0].node_id);
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try store.applyTransitionCommandTxn(&txn, 21, .{ .remove_store = .{ .store_id = 20 } });
        try std.testing.expectError(error.NotFound, txn.get(payload_key));
        try std.testing.expectError(error.NotFound, txn.get(try RaftApplyStore.reportPageKey(a, 21, 20, 0, true)));
        try std.testing.expectError(error.NotFound, txn.get(try RaftApplyStore.reportMembershipKey(a, 21, 20)));
        try txn.commit();
    }
    try std.testing.expectEqual(@as(usize, 0), (try store.listStores(a, 21)).len);
}

test "system catalog store report workload benchmark" {
    if (std.c.getenv("ANTFLY_CATALOG_REPORT_BENCH") == null) return;
    // Match the libc-linked ReleaseFast executable allocator. Correctness
    // regressions above still use the leak-checking test allocator.
    const alloc = std.heap.c_allocator;
    for ([_]usize{ 100, 1000, 10000 }) |count| {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        const root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/report-bench", .{tmp.sub_path});
        defer alloc.free(root);
        var store = try RaftApplyStore.init(alloc, .{ .root_dir = root });
        defer store.deinit();
        const groups = try alloc.alloc(metadata.GroupStatusReport, count);
        defer alloc.free(groups);
        for (groups, 100..) |*group, id| group.* = .{ .group_id = id, .raft_term = 1, .updated_at_millis = 1 };
        const runtimes = try alloc.alloc(metadata.RuntimeGroupStatusReport, count);
        defer alloc.free(runtimes);
        for (runtimes, 100..) |*report, id| report.* = .{ .group_id = id, .table_id = id, .table_name = "tenant_events", .store_id = 20, .node_id = 30, .updated_at_ns = 1 };
        var record: metadata.StoreRecord = .{ .store_id = 20, .node_id = 30, .reporter_incarnation = 77, .status_generation = 1, .group_statuses = groups, .runtime_statuses = runtimes };
        const full = try encodeStoreRecord(alloc, record);
        defer alloc.free(full);
        {
            var txn = try store.store.beginWriteTxn();
            errdefer txn.abort();
            _ = try store.ensureDerivedCatalogIndexesTxn(&txn, 21);
            try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_node = .{ .node_id = 30, .role = "data" } });
            try store.applyTransitionCommandTxn(&txn, 21, .{ .upsert_store = record });
            try txn.commit();
        }
        for ([_][]const u8{ "cached_heartbeat", "fresh_clocks", "one_group_change", "all_groups_change", "referenced_runtime" }) |scenario| {
            var elapsed: [7]u64 = undefined;
            var command_bytes: usize = 0;
            const before = store.snapshotWriteStats().wal_append_bytes;
            for (&elapsed) |*sample| {
                record.available_bytes += 1;
                if (std.mem.eql(u8, scenario, "fresh_clocks")) {
                    for (groups) |*group| group.updated_at_millis += 1;
                    for (runtimes) |*report| report.updated_at_ns += 1;
                }
                if (std.mem.eql(u8, scenario, "one_group_change")) groups[0].raft_term += 1;
                if (std.mem.eql(u8, scenario, "all_groups_change")) for (groups) |*group| {
                    group.raft_term += 1;
                };
                var transmitted = record;
                const reference = std.mem.eql(u8, scenario, "referenced_runtime");
                if (reference) transmitted.runtime_statuses = &.{};
                const command = try encodeTransitionCommand(alloc, if (reference) .{ .upsert_store_heartbeat = transmitted } else .{ .upsert_store = transmitted });
                command_bytes = command.len;
                defer alloc.free(command);
                const entries = try raft_state_machine.encodeCommittedEntries(alloc, &.{.{ .term = 1, .index = record.available_bytes, .entry_type = .normal, .data = command }});
                defer alloc.free(entries);
                const start = platform_time.monotonicNs();
                try store.snapshotBuilder().applyBatch(.{ .group_id = 21, .commit_index = record.available_bytes, .entries_bytes = entries });
                sample.* = platform_time.monotonicNs() - start;
            }
            std.mem.sort(u64, &elapsed, {}, std.sort.asc(u64));
            std.debug.print("REPORT_BENCH groups={d} scenario={s} apply_p50_ms={d:.3} wal_bytes_per_apply={d} full_record_bytes={d} command_bytes={d}\n", .{ count, scenario, @as(f64, @floatFromInt(elapsed[3])) / 1e6, (store.snapshotWriteStats().wal_append_bytes - before) / elapsed.len, full.len, command_bytes });
        }
        // Sparse and full measurements use the same logical report inventory.
        // Establishing a recovery baseline is outside the timed patch applies.
        const initial_update = try encodeTestReportUpdate(&store, alloc, .{ .sequence = 1, .report = store_report_update.asReport(record) });
        defer alloc.free(initial_update);
        try applyTestReportUpdate(&store, initial_update);
        for ([_]bool{ false, true }) |change_runtime| {
            var patch_elapsed: [7]u64 = undefined;
            const before_patch = store.snapshotWriteStats().wal_append_bytes;
            var patch_command_bytes: usize = 0;
            for (&patch_elapsed) |*sample| {
                record.available_bytes += 1;
                groups[0].raft_term += 1;
                if (change_runtime) runtimes[0].doc_count += 1;
                var report = store_report_update.asReport(record);
                report.group_statuses = groups[0..1];
                report.runtime_statuses = runtimes[0..1];
                const cursor = (try store.reportCursor(21, record.store_id)).?;
                const payload = try encodeTestReportUpdate(&store, alloc, .{ .sequence = cursor.sequence + 1, .base = cursor, .report = report });
                defer alloc.free(payload);
                const command = try encodeTransitionCommand(alloc, .{ .apply_store_report_update = payload });
                defer alloc.free(command);
                patch_command_bytes = command.len;
                const entries = try raft_state_machine.encodeCommittedEntries(alloc, &.{.{ .term = 1, .index = record.available_bytes, .entry_type = .normal, .data = command }});
                defer alloc.free(entries);
                const start = platform_time.monotonicNs();
                try store.snapshotBuilder().applyBatch(.{ .group_id = 21, .commit_index = record.available_bytes, .entries_bytes = entries });
                sample.* = platform_time.monotonicNs() - start;
                try std.testing.expectEqual(cursor.sequence + 1, (try store.reportCursor(21, record.store_id)).?.sequence);
            }
            std.mem.sort(u64, &patch_elapsed, {}, std.sort.asc(u64));
            std.debug.print("SPARSE_REPORT_BENCH groups={d} runtime_changed={} apply_p50_ms={d:.3} wal_bytes_per_apply={d} command_bytes={d}\n", .{ count, change_runtime, @as(f64, @floatFromInt(patch_elapsed[3])) / 1e6, (store.snapshotWriteStats().wal_append_bytes - before_patch) / patch_elapsed.len, patch_command_bytes });
        }
        var elapsed: [7]u64 = undefined;
        for (&elapsed) |*sample| {
            const start = platform_time.monotonicNs();
            const records = try store.listStores(alloc, 21);
            try std.testing.expectEqual(count, records[0].group_statuses.len);
            store.freeStores(alloc, records);
            sample.* = platform_time.monotonicNs() - start;
        }
        std.mem.sort(u64, &elapsed, {}, std.sort.asc(u64));
        std.debug.print("REPORT_BENCH groups={d} full_store_read_p50_ms={d:.3}\n", .{ count, @as(f64, @floatFromInt(elapsed[3])) / 1e6 });
        // Count caller-owned hydration and scratch allocations separately from
        // timing so instrumentation does not perturb the historical comparison.
        var read_counter = std.testing.FailingAllocator.init(alloc, .{});
        const counted_records = try store.listStores(read_counter.allocator(), 21);
        store.freeStores(read_counter.allocator(), counted_records);
        try std.testing.expectEqual(read_counter.allocated_bytes, read_counter.freed_bytes);
        std.debug.print("REPORT_BENCH groups={d} full_store_read_allocations={d} full_store_read_allocated_bytes={d}\n", .{ count, read_counter.allocations, read_counter.allocated_bytes });
        for (&elapsed) |*sample| {
            const start = platform_time.monotonicNs();
            for (0..100) |_| {
                var txn = try store.store.beginReadTxn();
                defer txn.abort();
                const draining = try store.placementTargetDrainRequestedTxn(&txn, 21, .{ .store_id = 20, .record = .{ .group_id = 100, .replica_id = 1, .local_node_id = 30, .bootstrap_mode = .persisted } });
                try std.testing.expectEqual(@as(?bool, false), draining);
            }
            sample.* = platform_time.monotonicNs() - start;
        }
        std.mem.sort(u64, &elapsed, {}, std.sort.asc(u64));
        std.debug.print("REPORT_BENCH groups={d} placement_drain_read_p50_ms={d:.6}\n", .{ count, @as(f64, @floatFromInt(elapsed[3])) / 1e8 });
    }
}

