    adopted.indexes_json = try std.json.Stringify.valueAlloc(a, .{ ._curation_proposals = queue.state }, .{});
    try store.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = destination, .replacement = adopted } });
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(source, (try store.getTable(a, group, 2)).?));
    try std.testing.expect(!try store.resolverProjectionValid(a, group, replacement));
    const command = try encodeTransitionCommand(a, .{ .compare_and_replace_table = .{ .expected = source, .replacement = replacement } });
    var outcome = try MetadataReplayTest.apply(&store, group, &.{.{ .term = 9, .index = 1, .entry_type = .normal, .data = command }});
    outcome.deinit();
    try std.testing.expect(try store.resolverNamespaceReplacementRejected(a, group, 9, 1, source, replacement));
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(source, (try store.getTable(a, group, 2)).?));
    // The same source-only CAS remains rejected when replicated again, while
    // unrelated schema changes still commit without adopting resolver policy.
    try store.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = source, .replacement = replacement } });
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(source, (try store.getTable(a, group, 2)).?));
    var ordinary = source;
    ordinary.schema_json = "{\"type\":\"object\"}";
    try std.testing.expect(try store.resolverProjectionValid(a, group, ordinary));
    try store.applyStandaloneCommand(group, .{ .compare_and_replace_table = .{ .expected = source, .replacement = ordinary } });
    try std.testing.expectEqualStrings(ordinary.schema_json, (try store.getTable(a, group, 2)).?.schema_json);
}

test "SQL COMMENT column codec retains guarded identity and rejects truncated admission" {
    const a = std.testing.allocator;
    try std.testing.expectEqual(RaftApplyStore.metadataSnapshotProjectionBit(.sql_column_identities), RaftApplyStore.transitionCommandProjectionMask(.comment_column));
    const command: TransitionCommand = .{ .comment_column = .{
        .guard = .{ .target = .{ .name = "rows" }, .logical_table = "rows", .owner = .{ .table_id = 7, .schema_version = 1, .schema_digest = @splat(1), .kind = .table }, .incarnation = @splat(2) },
        .column = .{ .name = "status", .value = "a 'quoted' Ω" },
        .column_id = 2,
        .epoch = .{ .version = 1, .digest = @splat(1) },
    } };
    const bytes = try encodeTransitionCommand(a, command);
    defer a.free(bytes);
    var decoded = (try decodeTransitionCommand(a, bytes)).?;
    defer decoded.deinit(a);
    try std.testing.expectEqualStrings("a 'quoted' Ω", decoded.comment_column.column.value.?);
    try std.testing.expectEqualDeep(command.comment_column.guard, decoded.comment_column.guard);
    try std.testing.expectEqual(command.comment_column.column_id, decoded.comment_column.column_id);
    for (transition_magic.len + 1..bytes.len) |length| try std.testing.expectError(error.InvalidMetadataTransitionEncoding, decodeTransitionCommand(a, bytes[0..length]));
}

test "SQL COMMENT column writer fences decoder epoch and stable identity without changing table definition" {
    const a = std.testing.allocator;
    const group: u64 = 21;
    const incarnation = "01010101010101010101010101010101".*;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/column-comment", .{tmp.sub_path});
    defer a.free(root);
    var store = try RaftApplyStore.init(a, .{ .root_dir = root });
    defer store.deinit();
    try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = incarnation });
    const table: metadata.TableRecord = .{ .table_id = 7, .name = "rows", .schema_json = "{\"version\":1,\"storage_mode\":\"relational\",\"default_type\":\"row\",\"document_schemas\":{\"row\":{\"schema\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"integer\"},\"status\":{\"type\":\"keyword\"}},\"additionalProperties\":false}}}}" };
    try store.applyStandaloneCommand(group, .{ .upsert_table = table });
    _ = try adoptLiveRelationWriterForTest(&store, a, group);
    const old_activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{ .version = topology_protocol.sql_column_comments_version - 1, .incarnation = incarnation, .member_count = 1, .membership_fingerprint = @splat(7) }, .{});
    defer a.free(old_activation);
    try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = old_activation });
    const resolved = try store.resolveSystemCatalogIdentities(a, group, .{ .relations = &.{.{ .name = "rows" }} });
    defer resolved.deinit(a);
    const guard: system_catalog.RelationMutationGuard = .{ .target = .{ .name = "rows" }, .logical_table = resolved.relations[0].?.logical_table, .owner = resolved.relations[0].?.owner, .incarnation = resolved.relation_epoch.?.incarnation };
    var attributes = try store.getSqlColumnIdentities(a, group, guard);
    defer attributes.deinit();
    const column = for (attributes.value.columns) |column| {
        if (std.mem.eql(u8, column.name, "status")) break column;
    } else return error.TestMissingColumnIdentity;
    var command: TransitionCommand = .{ .comment_column = .{ .guard = guard, .column = .{ .name = "status", .value = "application state" }, .column_id = column.id, .epoch = attributes.value.epoch } };
    try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.applyStandaloneCommand(group, command));
    const activation = try std.json.Stringify.valueAlloc(a, topology_protocol.Activation{ .version = topology_protocol.sql_column_comments_version, .incarnation = incarnation, .member_count = 1, .membership_fingerprint = @splat(7) }, .{});
    defer a.free(activation);
    try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = activation });
    try store.applyStandaloneCommand(group, command);
    try store.applyStandaloneCommand(group, command); // Exact desired-state retry.
    {
        var current = try store.getSqlColumnIdentities(a, group, guard);
        defer current.deinit();
        try std.testing.expectEqualStrings("application state", current.value.columnById(column.id).?.description.?);
    }
    const unchanged = (try store.getTable(a, group, 7)).?;
    defer metadata_table_manager.freeTable(a, unchanged);
    try std.testing.expect(metadata_table_manager.tableDefinitionsEqual(table, unchanged));
    // Admission checks the complete encoded successor, including escaping.
    // At replicated apply a concurrent aggregate-size conflict is a no-op,
    // never an error that wedges the committed log behind a user comment.
    const oversized = try a.alloc(u8, column_identities.max_encoded_bytes / 2);
    defer a.free(oversized);
    @memset(oversized, '"');
    const prior_value = command.comment_column.column.value;
    command.comment_column.column.value = oversized;
    try std.testing.expectError(error.ColumnIdentityLimitExceeded, store.applyStandaloneCommand(group, command));
    {
        var txn = try store.store.beginWriteTxn();
        errdefer txn.abort();
        try store.applyTransitionCommandTxn(&txn, group, command);
        try txn.commit();
    }
    command.comment_column.column.value = prior_value;
    try store.applyStandaloneCommand(group, command);
    command.comment_column.epoch.digest[0] ^= 1;
    try std.testing.expectError(error.CatalogGenerationChanged, store.applyStandaloneCommand(group, command));
    command.comment_column.epoch = attributes.value.epoch;
    command.comment_column.column_id += 1;
    try std.testing.expectError(error.CatalogGenerationChanged, store.applyStandaloneCommand(group, command));
    var current = try store.getSqlColumnIdentities(a, group, guard);
    defer current.deinit();
    try std.testing.expectEqualStrings("application state", current.value.columnById(column.id).?.description.?);
}

test "system catalog resource comments use three atomic writes retain receipts and recover cold snapshots" {
    const a = std.testing.allocator;
    const group: u64 = 21;
    const incarnation = "01010101010101010101010101010101".*;
    const T = struct {
        fn activate(store: *RaftApplyStore, version: u16) !void {
            const bytes = try std.json.Stringify.valueAlloc(store.alloc, topology_protocol.Activation{ .version = version, .incarnation = incarnation, .member_count = 1, .membership_fingerprint = @splat(7) }, .{});
            defer store.alloc.free(bytes);
            try store.applyStandaloneCommand(group, .{ .activate_topology_protocol = bytes });
        }
        fn verify(store: *RaftApplyStore) !void {
            // Production catalog reads reconstruct derived covering indexes
            // after snapshot installation before pinning the observation.
            var txn = try store.beginQueryCatalogReadTxn(group);
            defer txn.abort();
            const meta = try system_catalog_storage.readMeta(store.alloc, &txn, group);
            try std.testing.expectEqual(@as(u64, 1), meta.revision);
            try std.testing.expectEqual(@as(u64, 3), meta.next_id);
            var resource = (try system_catalog_storage.getById(store.alloc, &txn, group, .namespace, 2)).?;
            defer resource.deinit();
            try std.testing.expectEqualStrings("public", resource.value.name);
            try std.testing.expectEqualStrings("retained Ω", resource.value.description.?);
            var arena = std.heap.ArenaAllocator.init(store.alloc);
            defer arena.deinit();
            const view: system_catalog_storage.View = .{ .alloc = arena.allocator(), .txn = &txn, .group_id = group, .meta = meta };
            const children = try view.children(.namespace, 1, 0);
            try std.testing.expectEqual(@as(usize, 1), children.len);
            try std.testing.expectEqualStrings("retained Ω", children[0].description.?);
        }
    };
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const root = try std.fmt.allocPrint(a, ".zig-cache/tmp/{s}/resource-comments", .{tmp.sub_path});
    defer a.free(root);
    const target = try std.fmt.allocPrint(a, "{s}-snapshot", .{root});
    defer a.free(target);
    {
        var store = try RaftApplyStore.init(a, .{ .root_dir = root });
        defer store.deinit();
        try store.applyStandaloneCommand(group, .{ .initialize_metadata_incarnation = incarnation });
        try T.activate(&store, topology_protocol.sql_resource_comments_version - 1);
        const command: SystemCatalogCommand = .{ .expected_revision = 0, .mutation = .{ .action = .comment, .kind = .namespace, .name = "public", .description = "retained Ω" } };
        try std.testing.expectError(error.TableTopologyProtocolUpgradeRequired, store.validateSystemCatalog(group, command));
        try applySystemCatalogTestCommand(&store, 1, command);
        {
            var read = try store.store.beginReadTxn();
            defer read.abort();
            try std.testing.expectEqual(@as(u64, 0), (try system_catalog_storage.readMeta(a, &read, group)).revision);
        }
        try T.activate(&store, topology_protocol.sql_resource_comments_version);
        try store.validateSystemCatalog(group, command);
        try applySystemCatalogTestCommand(&store, 2, command);
        try applySystemCatalogTestCommand(&store, 3, command); // CAS retry cannot alter receipt or allocate an ID.
        try T.verify(&store);
        const baseline = try store.snapshotBuilder().buildSnapshot(a, group);
        defer a.free(baseline);
        const Writer = struct {
            txn: *docstore.DocStore.Txn,
            fail_at: usize,
            after: bool,
            writes: usize = 0,
            pub fn put(self: *@This(), key: []const u8, value: []const u8) !void {
                self.writes += 1;
                if (self.writes == self.fail_at and !self.after) return error.TestCommentWriteFailed;
                try self.txn.put(key, value);
                if (self.writes == self.fail_at and self.after) return error.TestCommentWriteFailed;
            }
        };
        for ([_]bool{ false, true }) |after| for (1..4) |fail_at| {
            var txn = try store.store.beginWriteTxn();
            const previous = try system_catalog_storage.readMeta(a, &txn, group);
            var row = system_catalog.default_namespace;
            row.description = "uncommitted";
            var writer: Writer = .{ .txn = &txn, .fail_at = fail_at, .after = after };
            const result = system_catalog_storage.applyPresentationRecord(a, &writer, group, row, previous, @splat(9));
            txn.abort();
            try std.testing.expectError(error.TestCommentWriteFailed, result);
            try std.testing.expectEqual(fail_at, writer.writes);
            const actual = try store.snapshotBuilder().buildSnapshot(a, group);
            defer a.free(actual);
            try std.testing.expectEqualSlices(u8, baseline, actual);
        };
        // Structural edits cannot use the constant-write presentation path.
        {
            var txn = try store.store.beginWriteTxn();
            defer txn.abort();
            const previous = try system_catalog_storage.readMeta(a, &txn, group);
            var forged = system_catalog.default_namespace;
            forged.name = "forged";
            var upserts = [_]system_catalog.Resource{forged};
            try std.testing.expectError(error.InvalidCatalogMutation, system_catalog_storage.applyDelta(a, &txn, group, .{ .upserts = &upserts, .removes = &.{}, .next_id = previous.next_id, .presentation_only = true }, previous, @splat(9)));
        }
        var copy = try RaftApplyStore.init(a, .{ .root_dir = target });
        defer copy.deinit();
        try std.testing.expect(try copy.snapshotBuilder().installSnapshot(a, group, 100, baseline));
        try T.verify(&copy);
    }
    {
        var reopened = try RaftApplyStore.init(a, .{ .root_dir = root });
        defer reopened.deinit();
        try T.verify(&reopened);
        var restored = try RaftApplyStore.init(a, .{ .root_dir = target });
        defer restored.deinit();
        try T.verify(&restored);
    }
}

test "runtime status media output counts preserve the v18 wire profile and round trip v19" {
    const alloc = std.testing.allocator;
    const report = metadata.RuntimeEnrichmentStatusReport{ .output_counts_available = true, .output_counts = .{ .embedding = .{ .complete = 4 }, .transcribe = .{ .failed = 2, .terminal = 1 } } };
    var encoded = std.ArrayListUnmanaged(u8).empty;
    defer encoded.deinit(alloc);
    for ([_]u16{ runtime_status_protocol.schema_epoch_record_version, runtime_status_protocol.media_output_record_version }) |version| {
        encoded.clearRetainingCapacity();
        try appendRuntimeEnrichmentStatusRecord(alloc, &encoded, report, version);
        var position: usize = 0;
        const decoded = try readRuntimeEnrichmentStatusRecord(alloc, encoded.items, &position, version);
        defer metadata_table_manager.freeRuntimeEnrichmentStatusReport(alloc, decoded);
        try std.testing.expectEqual(encoded.items.len, position);
        if (version == runtime_status_protocol.media_output_record_version) {
            try std.testing.expect(decoded.output_counts_available);
            try std.testing.expectEqualDeep(report.output_counts, decoded.output_counts);
        } else {
            try std.testing.expect(!decoded.output_counts_available);
            try std.testing.expectEqual(@as(u64, 0), decoded.output_counts.embedding.complete);
        }
    }
}

test "runtime status automatic store profile retains v19 media counters" {
